// One document on screen: its state, its plugins and its keys.

import { baseKeymap, toggleMark } from 'prosemirror-commands';
import { dropCursor } from 'prosemirror-dropcursor';
import { gapCursor } from 'prosemirror-gapcursor';
import { history, redo, undo } from 'prosemirror-history';
import { InputRule, inputRules } from 'prosemirror-inputrules';
import { keymap } from 'prosemirror-keymap';
import type { Node as PMNode } from 'prosemirror-model';
import { type Command, EditorState, Plugin, type Transaction } from 'prosemirror-state';
import { TableView, columnResizing, fixTables, tableEditing } from 'prosemirror-tables';
import { EditorView, type NodeView } from 'prosemirror-view';
import { chartSvg } from '../chart/draw';
import { mathPlugin } from '../math/plugin';
import { parseSpec } from '../chart/model';
import type { DocContext } from '../docx/import';
import type { ListKind } from '../docx/numbering';
import { clipboardPlugin } from './clipboard';
import {
  applyStyle, backspaceAtStart, clearFormatting, insertLineBreak, insertPageBreak, neighbouringList, setAlign, splitParagraph, tab, toggleList,
} from './commands';
import { findPlugin } from './find';
import { listKey, listOf, listPlugin } from './lists';
import { pagesPlugin } from './pages';
import { columnsPlugin } from '../columns/view';
import { schema } from './schema';
import { suggestPlugin } from './suggest';
import { tabsPlugin } from './tabs';
import { fieldsPlugin } from '../fields/plugin';
import { reviewPlugins } from '../review/plugin';
import { notesPlugins } from '../notes/view';
import { ShapeView } from '../shapes/view';

const N = schema.nodes;
const M = schema.marks;

export interface EditorOptions {
  ctx: DocContext;
  doc: PMNode;
  mount: HTMLElement;
  /** Called after every change of state: the text, the selection, or a plugin's own state. */
  onChange: (view: EditorView, tr: Transaction) => void;
  /** Ctrl+click on a link. */
  onOpenLink: (href: string) => void;
  /** A double click on the chart at this position. */
  onEditChart: (pos: number) => void;
  /** A click on a word the writing assistant suggests changing. */
  onSuggestion: (view: EditorView, id: number, target: HTMLElement) => void;
  /** An editor inside the document's own (a header, a footer, a note): no notes of its own. */
  nested?: boolean;
}

/** The table on screen: the library's own view for column widths, plus the table's look. */
class DocxTableView extends TableView {
  constructor(node: PMNode, cellMinWidth: number) {
    super(node, cellMinWidth);
    this.look(node);
  }

  update(node: PMNode): boolean {
    const updated = super.update(node);
    if (updated) this.look(node);
    return updated;
  }

  private look(node: PMNode): void {
    this.table.className = node.attrs.borders ? 'grid' : 'nogrid';
    this.table.dataset.tstyle = node.attrs.tstyle ?? '';
  }
}

/** A picture, with a handle at its corner to resize it by. */
class ImageView implements NodeView {
  readonly dom: HTMLElement;
  private readonly body: HTMLElement;
  private readonly handle: HTMLElement;

  constructor(
    private node: PMNode,
    private readonly view: EditorView,
    private readonly getPos: () => number | undefined,
  ) {
    this.dom = document.createElement('span');
    this.dom.className = 'image';

    if (node.attrs.src) {
      const img = document.createElement('img');
      img.src = node.attrs.src;
      img.alt = node.attrs.alt;
      img.draggable = false;
      this.body = img;
    } else {
      // A format Chromium cannot draw (EMF, WMF, TIFF): a box of the right size that says so.
      this.body = document.createElement('span');
      this.body.className = 'image-missing';
      this.body.textContent = node.attrs.alt || 'Picture';
    }

    this.handle = document.createElement('span');
    this.handle.className = 'image-handle';
    this.handle.addEventListener('pointerdown', this.startResize);

    this.dom.append(this.body, this.handle);
    this.size(node.attrs.w, node.attrs.h);
  }

  private size(w: number, h: number): void {
    this.body.style.width = `${w}px`;
    this.body.style.height = `${h}px`;
  }

  update(node: PMNode): boolean {
    if (node.type !== this.node.type || node.attrs.src !== this.node.attrs.src) return false;

    this.node = node;
    this.size(node.attrs.w, node.attrs.h);
    return true;
  }

  stopEvent(event: Event): boolean {
    return event.target === this.handle;
  }

  ignoreMutation(): boolean {
    return true;
  }

  private readonly startResize = (event: PointerEvent): void => {
    event.preventDefault();

    const page = this.dom.closest<HTMLElement>('.page');
    const zoom = Number(page ? getComputedStyle(page).zoom : 1) || 1;
    const { w, h } = this.node.attrs as { w: number; h: number };
    const startX = event.clientX;
    let width = w;

    const move = (e: PointerEvent) => {
      width = Math.max(16, Math.round(w + (e.clientX - startX) / zoom));
      this.size(width, Math.round((width * h) / w));
    };

    const up = () => {
      window.removeEventListener('pointermove', move);

      const pos = this.getPos();

      if (pos !== undefined && width !== w) {
        this.view.dispatch(this.view.state.tr.setNodeMarkup(pos, null, { ...this.node.attrs, w: width, h: Math.round((width * h) / w) }));
      }
    };

    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up, { once: true });
  };
}

/** A chart, drawn from its sheet, with a handle at its corner that sets its width and height. */
class ChartView implements NodeView {
  readonly dom: HTMLElement;
  private readonly body: HTMLElement;
  private readonly handle: HTMLElement;

  constructor(
    private node: PMNode,
    private readonly view: EditorView,
    private readonly getPos: () => number | undefined,
  ) {
    this.dom = document.createElement('span');
    this.dom.className = 'image chart';
    this.dom.title = 'Double-click to change the chart';

    this.body = document.createElement('span');
    this.body.className = 'chart-body';

    this.handle = document.createElement('span');
    this.handle.className = 'image-handle';
    this.handle.addEventListener('pointerdown', this.startResize);

    this.dom.append(this.body, this.handle);
    this.draw(node.attrs.w, node.attrs.h);
  }

  private draw(w: number, h: number): void {
    const spec = parseSpec(this.node.attrs.spec);

    this.body.style.width = `${w}px`;
    this.body.style.height = `${h}px`;
    this.body.innerHTML = spec ? chartSvg(spec, w, h) : '';
  }

  update(node: PMNode): boolean {
    if (node.type !== this.node.type) return false;

    const same = node.attrs.spec === this.node.attrs.spec && node.attrs.w === this.node.attrs.w && node.attrs.h === this.node.attrs.h;

    this.node = node;
    if (!same) this.draw(node.attrs.w, node.attrs.h);

    return true;
  }

  stopEvent(event: Event): boolean {
    return event.target === this.handle;
  }

  ignoreMutation(): boolean {
    return true;
  }

  private readonly startResize = (event: PointerEvent): void => {
    event.preventDefault();

    const page = this.dom.closest<HTMLElement>('.page');
    const zoom = Number(page ? getComputedStyle(page).zoom : 1) || 1;
    const room = this.view.dom.clientWidth || 2000;
    const { w, h } = this.node.attrs as { w: number; h: number };
    const startX = event.clientX;
    const startY = event.clientY;
    let width = w;
    let height = h;

    const move = (e: PointerEvent) => {
      width = Math.max(120, Math.min(room, Math.round(w + (e.clientX - startX) / zoom)));
      height = Math.max(90, Math.min(1400, Math.round(h + (e.clientY - startY) / zoom)));
      this.draw(width, height);
    };

    const up = () => {
      window.removeEventListener('pointermove', move);

      const pos = this.getPos();

      if (pos !== undefined && (width !== w || height !== h)) {
        this.view.dispatch(this.view.state.tr.setNodeMarkup(pos, null, { ...this.node.attrs, w: width, h: height }));
      }
    };

    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up, { once: true });
  };
}

/** Typing "- " or "1. " at the start of a paragraph starts a list; "# " to "### " makes a heading. */
function typingRules(ctx: DocContext) {
  const startList = (kind: ListKind) => (state: EditorState, _match: RegExpMatchArray, start: number, end: number) => {
    const $start = state.doc.resolve(start);
    const node = $start.parent;

    if (node.type !== N.paragraph || listOf(node, ctx)) return null;

    const numId = neighbouringList(state, ctx, [{ node, pos: $start.before() }], kind) ?? ctx.numbering.createList(kind);
    const listStyle = ctx.styles.byName('List Paragraph');
    const plain = !node.attrs.styleId || node.attrs.styleId === ctx.styles.defaultParagraph;

    return state.tr
      .delete(start, end)
      .setNodeMarkup($start.before(), null, { ...node.attrs, numId, ilvl: 0, styleId: listStyle && plain ? listStyle.id : node.attrs.styleId })
      .setMeta(listKey, true);
  };

  const heading = new InputRule(/^(#{1,3})\s$/, (state, match, start, end) => {
    const $start = state.doc.resolve(start);
    const styleId = ctx.styles.ensureBuiltin(`heading ${match[1].length}`);

    if ($start.parent.type !== N.paragraph || !styleId) return null;

    return state.tr.delete(start, end).setNodeMarkup($start.before(), null, { ...$start.parent.attrs, styleId });
  });

  return inputRules({ rules: [new InputRule(/^[-*]\s$/, startList('bullet')), new InputRule(/^1[.)]\s$/, startList('number')), heading] });
}

/** Whether the document ends in a paragraph, not counting placeholders that show nothing. */
function endsInParagraph(doc: PMNode): boolean {
  for (let i = doc.childCount - 1; i >= 0; i--) {
    const block = doc.child(i);

    if (block.type === N.opaque_block && block.attrs.hidden) continue;
    return block.type === N.paragraph;
  }

  return false;
}

/**
 * A document always ends in a paragraph, as it does in Word. Without one, a table at the very end
 * leaves nowhere to click to write after it.
 */
const trailingParagraph = new Plugin({
  appendTransaction: (transactions, _old, state) =>
    transactions.some((tr) => tr.docChanged) && !endsInParagraph(state.doc) ? state.tr.insert(state.doc.content.size, N.paragraph.create()) : null,
});

function keys(ctx: DocContext): Record<string, Command> {
  const normal: Command = (state, dispatch) => applyStyle(ctx, ctx.styles.defaultParagraph ?? '')(state, dispatch);

  return {
    'Mod-z': undo,
    'Mod-y': redo,
    'Mod-Shift-z': redo,
    'Mod-b': toggleMark(M.bold, { on: true }),
    'Mod-i': toggleMark(M.italic, { on: true }),
    'Mod-u': toggleMark(M.underline, { kind: 'single' }),
    'Mod-Shift-x': toggleMark(M.strike, { on: true }),
    'Mod-Space': clearFormatting,
    Enter: splitParagraph(ctx),
    'Shift-Enter': insertLineBreak,
    'Mod-Enter': insertPageBreak,
    Backspace: backspaceAtStart(ctx),
    Tab: tab(ctx, 1),
    'Shift-Tab': tab(ctx, -1),
    'Mod-l': setAlign('left'),
    'Mod-e': setAlign('center'),
    'Mod-r': setAlign('right'),
    'Mod-j': setAlign('both'),
    // Alt and not Ctrl+Alt, which on a German keyboard is AltGr and types ² and ³.
    'Alt-1': applyStyle(ctx, 'builtin:heading 1'),
    'Alt-2': applyStyle(ctx, 'builtin:heading 2'),
    'Alt-3': applyStyle(ctx, 'builtin:heading 3'),
    'Mod-Shift-n': normal,
    'Mod-Shift-l': toggleList(ctx, 'bullet'),
  };
}

export function createEditor(options: EditorOptions): EditorView {
  const { ctx } = options;

  let state = EditorState.create({
    doc: options.doc,
    plugins: [
      typingRules(ctx),
      keymap(keys(ctx)),
      keymap(baseKeymap),
      history(),
      dropCursor({ class: 'drop-cursor', color: false }),
      gapCursor(),
      columnResizing({ View: DocxTableView, cellMinWidth: 24 }),
      tableEditing(),
      listPlugin(ctx),
      findPlugin(),
      pagesPlugin(),
      // A header, footer or note has no sections of its own.
      ...(options.nested ? [] : [columnsPlugin(ctx)]),
      suggestPlugin(options.onSuggestion),
      clipboardPlugin(ctx),
      trailingParagraph,
      fieldsPlugin(ctx),
      tabsPlugin(ctx),
      mathPlugin(),
      ...reviewPlugins(ctx),
      ...(options.nested ? [] : notesPlugins(ctx, (o) => createEditor({ ...o, onChange: () => {}, onOpenLink: () => {}, onEditChart: () => {}, onSuggestion: () => {}, nested: true }))),
    ],
  });

  // Tables whose rows do not add up are squared off before anything is shown or edited, and a
  // document that ends in a table gets its closing paragraph. Neither counts as a change to undo.
  const fix = fixTables(state);
  if (fix) state = state.apply(fix.setMeta('addToHistory', false));

  if (!endsInParagraph(state.doc)) {
    state = state.apply(state.tr.insert(state.doc.content.size, N.paragraph.create()).setMeta('addToHistory', false));
  }

  const view: EditorView = new EditorView(options.mount, {
    state,
    attributes: { spellcheck: 'true' },
    nodeViews: {
      image: (node, editorView, getPos) => new ImageView(node, editorView, getPos),
      chart: (node, editorView, getPos) => new ChartView(node, editorView, getPos),
      shape: (node, editorView, getPos) =>
        new ShapeView(node, editorView, getPos, ctx, (o) =>
          createEditor({ ...o, nested: true, onChange: (v, tr) => tr.docChanged && o.onDocChange(v.state.doc), onOpenLink: options.onOpenLink, onEditChart: () => {}, onSuggestion: () => {} }),
        ),
    },
    dispatchTransaction(tr) {
      view.updateState(view.state.apply(tr));
      options.onChange(view, tr);
    },
    handleDoubleClickOn(_view, _pos, node, nodePos) {
      if (node.type !== N.chart) return false;

      options.onEditChart(nodePos);
      return true;
    },
    handleClick(editorView, pos, event) {
      if (!(event.ctrlKey || event.metaKey)) return false;

      const link = M.link.isInSet(editorView.state.doc.resolve(pos).marks()) ?? M.link.isInSet(editorView.state.doc.nodeAt(pos)?.marks ?? []);
      if (!link?.attrs.href) return false;

      options.onOpenLink(link.attrs.href);
      return true;
    },
  });

  return view;
}
