// Summaries of a selection, an abstract of the whole document, and the model's part of the
// document review. A document longer than the model can read at once is read in parts: each
// part is boiled down to notes, and the abstract is written from the notes.

import type { AssistRequest } from '../desktop';

/** Paragraphs grouped into parts of at most `max` characters; a longer paragraph is a part of its own, cut. */
export function chunkParagraphs(paragraphs: string[], max: number): string[] {
  const parts: string[] = [];
  let current = '';

  for (const text of paragraphs.map((p) => p.trim()).filter(Boolean)) {
    const piece = text.length > max ? text.slice(0, max) : text;

    if (current && current.length + piece.length + 2 > max) {
      parts.push(current);
      current = '';
    }

    current = current ? `${current}\n\n${piece}` : piece;
  }

  if (current) parts.push(current);
  return parts;
}

const tokensFor = (words: number) => Math.ceil(words * 2) + 64;
const withContext = (context: string) => (context ? ` ${context}` : '');

export function summaryRequest(model: string, text: string, context = ''): AssistRequest {
  return {
    model,
    system:
      'You summarise text for its author. Summarise the user’s text in a few sentences, at most a third of its length, ' +
      'keeping its key claims, numbers and terms. Write in the language of the text. Reply with the summary only.' +
      withContext(context),
    text,
    temperature: 0.2,
    maxTokens: Math.min(1024, Math.ceil(text.length / 6) + 64),
  };
}

/** Notes on one part of a long document, from which the abstract is written. */
export function notesRequest(model: string, part: string, context = ''): AssistRequest {
  return {
    model,
    system:
      'The user sends one part of a longer document. Write compact notes on it, at most 120 words: its aim, methods, ' +
      'findings and conclusions as far as this part states them. Keep numbers and terms. Write in the language of the text. ' +
      'Reply with the notes only.' +
      withContext(context),
    text: part,
    temperature: 0.1,
    maxTokens: 400,
  };
}

/**
 * The abstract, from the document itself or, for a long one, from notes on its parts. `words` is
 * the length aimed for.
 */
export function abstractRequest(model: string, text: string, words: number, fromNotes: boolean, context = ''): AssistRequest {
  return {
    model,
    system:
      `You write abstracts for academic and professional documents. Write an abstract of about ${words} words for the ` +
      `document ${fromNotes ? 'described by the user’s notes, which cover it part by part' : 'the user sends'}: its purpose, ` +
      'approach, main findings and conclusion, in one paragraph, in the language and register of the document. Do not add ' +
      'anything the document does not say. Reply with the abstract only, without a heading.' +
      withContext(context),
    text,
    temperature: 0.3,
    maxTokens: tokensFor(words),
  };
}

/** The model's part of the review: terms used for the same concept, which word lists cannot know. */
export function termReviewRequest(model: string, part: string, context = ''): AssistRequest {
  return {
    model,
    system:
      'You are an editor checking a document for consistent terminology. Find pairs of different words or phrases that the ' +
      'text uses for the same concept, such as "participants" and "subjects", or "neural net" and "neural network". Do not ' +
      'report differences in spelling, hyphenation or capitals only. For each pair, answer with one line in the form ' +
      '"term used less | term to use | why in at most eight words", using the terms exactly as they appear in the text. ' +
      'At most eight lines. If there are none, answer "none".' +
      withContext(context),
    text: part,
    temperature: 0,
    maxTokens: 400,
  };
}

export interface TermPair {
  from: string;
  to: string;
  why: string;
}

/** The pairs in the model's answer, without ones that are not in the text. */
export function parseTermPairs(answer: string, text: string): TermPair[] {
  const lower = text.toLowerCase();
  const pairs: TermPair[] = [];

  for (const line of answer.replace(/<think>[\s\S]*?<\/think>/g, '').split('\n')) {
    const parts = line.replace(/^\s*(?:[-*]|\d+[.)])\s*/, '').split('|').map((p) => p.trim().replace(/^["'“]|["'”]$/g, ''));
    if (parts.length < 2 || !parts[0] || !parts[1]) continue;

    const [from, to, why = ''] = parts;

    if (from.toLowerCase() === to.toLowerCase() || !lower.includes(from.toLowerCase()) || pairs.some((p) => p.from === from)) continue;
    pairs.push({ from, to, why });
  }

  return pairs.slice(0, 8);
}
