/** Roles that are people, not plain text fields. */
export const ROLES = new Set(['Author', 'Editor', 'Translator', 'BookAuthor', 'Compiler', 'Counsel', 'Director', 'Interviewee', 'Interviewer', 'Inventor', 'Performer', 'Producer', 'Writer', 'Artist', 'Composer', 'Conductor', 'ProducerName']);

export const field = (source: Source, name: string): string => (source.fields[name] ?? '').trim();
export const people = (source: Source, role: string): Name[] => source.people[role] ?? [];

// ---- Names as text ---------------------------------------------------------------------------------

/** "Smith, John Paul; {World Health Organization}" → names. */
export function parseNames(text: string): Name[] {
  return text
    .split(/\s*;\s*/)
    .map((part) => part.trim())
    .filter(Boolean)
    .map((part): Name => {
      const corporate = /^\{(.*)\}$/.exec(part);
      if (corporate) return { corporate: corporate[1].trim() };

      const comma = part.indexOf(',');
      if (comma >= 0) {
        const [first, ...middle] = part.slice(comma + 1).trim().split(/\s+/).filter(Boolean);
        return tidy({ last: part.slice(0, comma).trim(), first, middle: middle.join(' ') });
      }

      const words = part.split(/\s+/);
      if (words.length === 1) return { last: words[0] };
      const last = words.pop()!;
      const [first, ...middle] = words;
      return tidy({ last, first, middle: middle.join(' ') });
    });
}

function tidy(name: Name): Name {
  const out: Name = {};
  for (const key of ['last', 'first', 'middle', 'corporate'] as const) if (name[key]) out[key] = name[key];
  return out;
}

/** Names back to the text `parseNames` reads. */
export function namesText(names: Name[]): string {
  return names
    .map((name) => (name.corporate ? `{${name.corporate}}` : [name.last, [name.first, name.middle].filter(Boolean).join(' ')].filter(Boolean).join(', ')))
    .join('; ');
}

// ---- Tags, identity ------------------------------------------------------------------------------

/** A tag the way Word makes one: three letters of the first author and two of the year, made unique. */
export function newTag(source: Source, taken: Iterable<string>): string {
  const used = new Set([...taken].map((t) => t.toLowerCase()));
  const first = people(source, 'Author')[0];
  const word = (first?.corporate ?? first?.last ?? field(source, 'Title') ?? '').normalize('NFD').replace(/[^A-Za-z]/g, '');
  const base = (word.slice(0, 3) || 'Src').replace(/^./, (c) => c.toUpperCase()) + (/\d{2}(?=\D*$)/.exec(field(source, 'Year'))?.[0] ?? '');
  if (!used.has(base.toLowerCase())) return base;

  for (let i = 1; ; i++) if (!used.has(`${base}${i}`.toLowerCase())) return `${base}${i}`;
}

/** A DOI without its resolver: "https://doi.org/10.1/x" → "10.1/x". */
export const bareDoi = (doi: string): string => doi.trim().replace(/^(?:https?:\/\/(?:dx\.)?doi\.org\/|doi:\s*)/i, '');

/** What makes two sources the same: their DOI, or their title and year. */
export function identity(source: Source): string {
  const doi = bareDoi(field(source, 'DOI')).toLowerCase();
  if (doi) return `doi:${doi}`;

  const title = field(source, 'Title').toLowerCase().normalize('NFD').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  return `title:${title}|${field(source, 'Year')}`;
}

/** A new, empty source of a kind. */
export function emptySource(kind: Kind): Source {
  const entry = KINDS.find((k) => k.kind === kind)!;
  return { tag: '', type: entry.type, fields: kind === 'thesis' ? { ThesisType: 'Doctoral dissertation' } : {}, people: {}, extra: [] };
}

/** One line for lists: "Smith, J. (2020). Title". */
export function describe(source: Source): string {
  const first = people(source, 'Author')[0];
  const who = first ? (first.corporate ?? first.last ?? '') + (people(source, 'Author').length > 1 ? ' et al.' : '') : '';
  return [who, field(source, 'Year') && `(${field(source, 'Year')})`, field(source, 'Title')].filter(Boolean).join(' ');
}
