// Small helpers for building the interface: elements, pop-ups, dialogs, notices.

/** A setting kept in this browser's storage, or null when there is none or storage is switched off. */
export function stored(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

export function store(key: string, value: string): void {
  try {
    localStorage.setItem(key, value);
  } catch {
    // Storage switched off: the setting lasts for this run.
  }
}

type Child = Node | string | null | undefined | false;
type Props = Record<string, unknown> | null;

/** Makes an element. `class`, `html` and `on…` handlers are set as such, the rest as attributes. */
export function h<K extends keyof HTMLElementTagNameMap>(tag: K, props?: Props, ...children: Child[]): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);

  for (const [name, value] of Object.entries(props ?? {})) {
    if (value === null || value === undefined || value === false) continue;

    if (name === 'class') el.className = String(value);
    else if (name === 'html') el.innerHTML = String(value);
    else if (name.startsWith('on') && typeof value === 'function') el.addEventListener(name.slice(2), value as EventListener);
    else el.setAttribute(name, value === true ? '' : String(value));
  }

  for (const child of children) {
    if (child) el.append(child);
  }

  return el;
}

/**
 * Keeps a click on a control from taking the cursor out of the document. Text fields and
 * drop-down lists are left alone: those need the focus to work at all.
 */
export function keepFocus(el: HTMLElement): void {
  el.addEventListener('mousedown', (event) => {
    if (!(event.target as HTMLElement).closest('input, select, textarea')) event.preventDefault();
  });
}

let closeOpenPopover: (() => void) | null = null;
let openAnchor: HTMLElement | null = null;

/** Closes whatever pop-up is open. */
export function closePopover(): void {
  closeOpenPopover?.();
}

/**
 * Shows `content` in a pop-up under `anchor`. A second call with the same anchor closes it,
 * so a button toggles its own menu. Returns the function that closes it.
 */
export function popover(anchor: HTMLElement, content: HTMLElement, onClose?: () => void): () => void {
  const sameAnchor = openAnchor === anchor;

  closePopover();
  if (sameAnchor) return () => {};

  const box = h('div', { class: 'popover' }, content);

  keepFocus(box);
  document.body.append(box);

  const at = anchor.getBoundingClientRect();
  const size = box.getBoundingClientRect();
  const below = at.bottom + 4;
  const top = below + size.height > innerHeight - 8 && at.top - size.height - 4 > 8 ? at.top - size.height - 4 : below;

  box.style.left = `${Math.max(8, Math.min(at.left, innerWidth - size.width - 8))}px`;
  box.style.top = `${Math.max(8, top)}px`;
  anchor.classList.add('open');

  const onPointer = (event: PointerEvent) => {
    const target = event.target as Node;
    if (!box.contains(target) && !anchor.contains(target)) close();
  };

  const onKey = (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.stopPropagation();
      close();
    }
  };

  function close(): void {
    if (closeOpenPopover !== close) return;

    closeOpenPopover = null;
    openAnchor = null;
    box.remove();
    anchor.classList.remove('open');
    document.removeEventListener('pointerdown', onPointer, true);
    document.removeEventListener('keydown', onKey, true);
    window.removeEventListener('blur', close);
    window.removeEventListener('resize', close);
    onClose?.();
  }

  document.addEventListener('pointerdown', onPointer, true);
  document.addEventListener('keydown', onKey, true);
  window.addEventListener('blur', close);
  window.addEventListener('resize', close);

  closeOpenPopover = close;
  openAnchor = anchor;

  return close;
}

export interface Choice<T> {
  label: string;
  value: T;
  primary?: boolean;
}

/** Asks a question in a dialog and answers with the chosen button's value; Escape gives `cancel`. */
export function ask<T>(title: string, message: string, choices: Choice<T>[], cancel: T): Promise<T> {
  return new Promise((resolve) => {
    const buttons = h('div', { class: 'buttons' });
    const backdrop = h('div', { class: 'dialog-backdrop' }, h('div', { class: 'dialog', role: 'dialog' }, h('h2', null, title), h('p', null, message), buttons));

    const done = (value: T) => {
      document.removeEventListener('keydown', onKey, true);
      backdrop.remove();
      resolve(value);
    };

    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        done(cancel);
      }
    };

    let first: HTMLButtonElement | null = null;

    for (const choice of choices) {
      const button = h('button', { class: choice.primary ? 'button primary' : 'button', onclick: () => done(choice.value) }, choice.label);

      if (choice.primary || !first) first = choice.primary ? button : (first ?? button);
      buttons.append(button);
    }

    closePopover();
    document.addEventListener('keydown', onKey, true);
    document.body.append(backdrop);
    first?.focus();
  });
}

/** Tells the user something in a dialog with one button. */
export function tell(title: string, message: string): Promise<void> {
  return ask<void>(title, message, [{ label: 'OK', value: undefined, primary: true }], undefined);
}

let toastTimer = 0;

/** A short notice at the bottom of the window that goes away by itself. */
export function toast(message: string, bad = false): void {
  document.querySelector('.toast')?.remove();
  clearTimeout(toastTimer);

  const el = h('div', { class: bad ? 'toast bad' : 'toast' }, message);

  document.body.append(el);
  toastTimer = window.setTimeout(() => el.remove(), bad ? 6000 : 1800);
}
