// What the Markdown, HTML and ODT writers share: how a paragraph's heading level, list place and
// note numbers are found, what a picture, chart or shape is as a file, and how a run of list
// paragraphs (Word's flat model) becomes nested lists.

import type { Mark, Node as PMNode } from 'prosemirror-model';
import { chartSvg } from '../chart/draw';
import { parseSpec } from '../chart/model';
import { type Label, ListCounter } from '../docx/numbering';
import type { DocContext } from '../docx/import';
import { parseDataUrl } from '../docx/package';
import { listOf } from '../editor/lists';
import { headingLevel, styleLevels } from '../editor/outline';
import { schema } from '../editor/schema';
import { type NoteKind, notesOf, numberRefs, refOf, refsIn } from '../notes/model';
import { shapeSvg } from '../shapes/geometry';

export const N = schema.nodes;

/** A document to convert, and the name its files go under (no folder, no extension). */
export interface Source {
  ctx: DocContext;
  doc: PMNode;
  name: string;
}

/** A file that goes beside the converted one, as a Markdown file's pictures do. */
export interface SideFile {
  name: string;
  bytes: Uint8Array;
  mime: string;
}

// ---- Paragraphs ------------------------------------------------------------------------------

/** A paragraph's heading level, 1 to 9, or 0 for body text. The Title style counts as level 1. */
export function headings(ctx: DocContext): (node: PMNode) => number {
  const levels = styleLevels(ctx.styles);

  return (node) => {
    const level = headingLevel(node, levels);
    if (level) return level;

    const def = ctx.styles.byId.get(node.attrs.styleId ?? '');
    return def && /^title$/i.test(def.name) ? 1 : 0;
  };
}

export interface ListItem extends Label {
  numId: number;
  level: number;
  kind: 'bullet' | 'number';
}

/** Hands out list markers in document order; a fresh one for each separate text (notes, text boxes). */
export class Lists {
  private readonly counter: ListCounter;

  constructor(private readonly ctx: DocContext) {
    this.counter = new ListCounter(ctx.numbering);
  }

  item(node: PMNode): ListItem | null {
    if (node.type !== N.paragraph) return null;

    const place = listOf(node, this.ctx);
    const label = place ? this.counter.next(place.numId, place.ilvl) : null;
    if (!place || !label) return null;

    return { ...label, numId: place.numId, level: place.ilvl, kind: label.bullet ? 'bullet' : 'number' };
  }
}

/** A text deleted as a tracked change: the exports show the document with its changes made. */
export const isDeleted = (marks: readonly Mark[]): boolean =>
  marks.some((mark) => mark.type === schema.marks.track && (mark.attrs.kind === 'del' || mark.attrs.kind === 'moveFrom'));

/** The marks that are on: a bold mark that switches bold off is no bold. */
export const markOn = (marks: readonly Mark[], name: string): Mark | null =>
  marks.find((mark) => mark.type.name === name && mark.attrs.on !== false) ?? null;

/** A paragraph's inline content cut at its page breaks: the parts after a break start a new page. */
export function splitAtBreaks(paragraph: PMNode): { nodes: PMNode[]; pageBefore: boolean }[] {
  const parts: { nodes: PMNode[]; pageBefore: boolean }[] = [{ nodes: [], pageBefore: false }];

  paragraph.forEach((node) => {
    if (node.type === N.page_break && !node.attrs.column && !isDeleted(node.marks)) parts.push({ nodes: [], pageBefore: true });
    else parts[parts.length - 1].nodes.push(node);
  });

  return parts;
}

// ---- Notes ----------------------------------------------------------------------------------

export interface NoteOut {
  kind: NoteKind;
  id: string;
  /** The number or mark it shows, as the editor numbers it. */
  label: string;
  /** Unique in the export: f1, f2, ... e1, ... */
  key: string;
  doc: PMNode;
}

/** The notes the text refers to, in order of first reference, with their numbers. */
export class Notes {
  readonly list: NoteOut[] = [];
  private readonly byRef = new Map<string, NoteOut>();

  constructor(ctx: DocContext, doc: PMNode) {
    const refs = refsIn(doc);
    if (!refs.length) return;

    const store = notesOf(ctx);
    const sectPrs: (string | null)[] = [];
    doc.forEach((node) => {
      if (node.type === N.paragraph && node.attrs.sectPr) sectPrs.push(node.attrs.sectPr);
    });
    sectPrs.push(doc.attrs.sectPr ?? ctx.sectPr);

    const labels = numberRefs(refs, (kind, section) => store.sectionProps(kind, sectPrs[section] ?? null));
    const counts: Record<NoteKind, number> = { footnote: 0, endnote: 0 };

    refs.forEach((ref, i) => {
      const key = `${ref.kind}:${ref.id}`;
      const note = store.get(ref.kind, ref.id);
      if (this.byRef.has(key) || !note) return;

      const out: NoteOut = {
        kind: ref.kind,
        id: ref.id,
        label: labels[i] || '*',
        key: `${ref.kind === 'footnote' ? 'f' : 'e'}${++counts[ref.kind]}`,
        doc: store.docOf(note),
      };
      this.byRef.set(key, out);
      this.list.push(out);
    });
  }

  /** The note a node refers to, if it is a note reference. */
  of(node: PMNode): NoteOut | null {
    const ref = refOf(node);
    return ref ? (this.byRef.get(`${ref.kind}:${ref.id}`) ?? null) : null;
  }

  /** The notes in the order they go at the end: footnotes, then endnotes. */
  get ordered(): NoteOut[] {
    return [...this.list.filter((n) => n.kind === 'footnote'), ...this.list.filter((n) => n.kind === 'endnote')];
  }
}

/**
 * The note's own reference mark at the start of its text (`w:footnoteRef`) is hidden XML in the
 * editor; the exports write their own number, so the note's text is all there is to write.
 */
export const noteBlocks = (note: NoteOut): PMNode[] => {
  const out: PMNode[] = [];
  note.doc.forEach((block) => out.push(block));
  return out;
};

// ---- Pictures, charts and shapes ------------------------------------------------------------

const EXT: Record<string, string> = {
  'image/png': 'png', 'image/jpeg': 'jpg', 'image/gif': 'gif', 'image/bmp': 'bmp', 'image/webp': 'webp', 'image/svg+xml': 'svg', 'image/tiff': 'tif',
};

/** A picture's bytes, type and file extension; null for one the editor could not read. */
export function pictureOf(node: PMNode): { bytes: Uint8Array; mime: string; ext: string } | null {
  const data = node.attrs.src ? parseDataUrl(node.attrs.src) : null;
  if (!data) return null;
  return { ...data, ext: EXT[data.mime] ?? 'bin' };
}

const XML_DECL = '<?xml version="1.0" encoding="UTF-8"?>\n';

/** A chart drawn as SVG, as the editor draws it; null if its description does not read. */
export function chartSvgOf(node: PMNode): string | null {
  const spec = parseSpec(node.attrs.spec);
  return spec ? withSvgNamespace(chartSvg(spec, node.attrs.w, node.attrs.h)) : null;
}

/** A shape drawn as SVG; null if its description does not read. */
export function shapeSvgOf(node: PMNode): string | null {
  try {
    return withSvgNamespace(shapeSvg(JSON.parse(node.attrs.spec)));
  } catch {
    return null;
  }
}

/** The text in a text box, as a document of its own; null when the shape has none. */
export function shapeText(node: PMNode): PMNode | null {
  if (!node.attrs.text) return null;

  try {
    const doc = schema.nodeFromJSON(JSON.parse(node.attrs.text));
    return doc.textContent.trim() ? doc : null;
  } catch {
    return null;
  }
}

/** An SVG that also works as a file of its own: inline SVG in HTML may leave the namespace out. */
function withSvgNamespace(svg: string): string {
  return /^<svg\b[^>]*\bxmlns=/.test(svg) ? svg : svg.replace(/^<svg\b/, '<svg xmlns="http://www.w3.org/2000/svg"');
}

/** An SVG as a file. */
export const svgFile = (svg: string): Uint8Array => new TextEncoder().encode(XML_DECL + svg);

/** Names files beside an export: image1.png, chart1.svg, ... */
export class FileNames {
  private readonly counts = new Map<string, number>();

  next(stem: string, ext: string): string {
    const n = (this.counts.get(stem) ?? 0) + 1;
    this.counts.set(stem, n);
    return `${stem}${n}.${ext}`;
  }
}

// ---- Lists ----------------------------------------------------------------------------------

/** What a writer does as a run of list paragraphs is laid out as nested lists. */
export interface ListSink {
  openList(first: ListItem): void;
  closeList(first: ListItem): void;
  openItem(item: ListItem): void;
  closeItem(item: ListItem): void;
}

/**
 * Lays out consecutive list paragraphs as nested lists: a deeper level opens a list inside the
 * item before it, a shallower one closes lists, and a change of list or kind at one level starts
 * a new list there. `body` writes the paragraph itself, between openItem and closeItem.
 */
export function nestList(run: { node: PMNode; item: ListItem }[], sink: ListSink, body: (node: PMNode, item: ListItem) => void): void {
  const open: ListItem[] = [];

  for (const { node, item } of run) {
    while (open.length && open[open.length - 1].level > item.level) {
      const top = open.pop()!;
      sink.closeItem(top);
      sink.closeList(top);
    }

    const top = open[open.length - 1];

    if (top && top.level === item.level) {
      sink.closeItem(top);
      if (top.kind !== item.kind || top.numId !== item.numId) {
        sink.closeList(open.pop()!);
        sink.openList(item);
        open.push(item);
      }
    } else {
      sink.openList(item);
      open.push(item);
    }

    sink.openItem(item);
    body(node, item);
  }

  while (open.length) {
    const top = open.pop()!;
    sink.closeItem(top);
    sink.closeList(top);
  }
}

export type Grouped = { node: PMNode; run?: undefined } | { run: { node: PMNode; item: ListItem }[]; node?: undefined };

/**
 * A container's blocks, with each run of list paragraphs gathered up. `lists` must see the
 * paragraphs in document order, so each group is handed out before the block after it is looked
 * at: a list that goes on after a table counts the table's lists in between.
 */
export function* groupBlocks(blocks: readonly PMNode[], lists: Lists): Generator<Grouped> {
  let run: { node: PMNode; item: ListItem }[] = [];

  for (const node of blocks) {
    const item = lists.item(node);

    if (item) {
      run.push({ node, item });
      continue;
    }

    if (run.length) yield { run };
    run = [];
    yield { node };
  }

  if (run.length) yield { run };
}

/** A node's children as an array. */
export function childrenOf(node: PMNode): PMNode[] {
  const out: PMNode[] = [];
  node.forEach((child) => out.push(child));
  return out;
}
