// The chart editor: a small sheet to type the numbers into, the chart's settings, and the chart
// itself, redrawn at every keystroke.
//
// The sheet is the chart's whole data (chart/model.ts says how it is laid out). It always shows
// an empty row and column past the last filled cell, so there is room to go on typing, and takes
// a block of cells pasted from a spreadsheet as it is.

import { chartSvg } from '../chart/draw';
import { CellError, type Value, colName, evaluateSheet, shiftFormula } from '../chart/formula';
import {
  type ChartKind, type ChartSpec, KINDS, MAX_COLS, MAX_ROWS, canStack, colorOf, dataOf, editText, hasData, shownText, storedText, trimCells,
} from '../chart/model';
import { closePopover, h } from './dom';

export interface ChartDialogOptions {
  spec: ChartSpec;
  isNew: boolean;
  /** Something the user should know about this chart, shown beside the buttons. */
  note: string | null;
  /** The mode of the page the chart is on (light, tint, dark): the preview is drawn as the page will show it. */
  pageMode: string;
}

const MIN_ROWS = 9;
const MIN_COLS = 5;
const PREVIEW = { w: 420, h: 250 };
const MOST_COLORS = 12;

class ChartDialog {
  private readonly spec: ChartSpec;
  private cells: string[][];
  private inputs: HTMLInputElement[][] = [];
  private values: Value[][] = [];
  /** The cell the row and column buttons act on: the one last typed in. */
  private current = { r: 1, c: 1 };
  /** What the cell in hand held when it was entered, for Escape to put back. */
  private before = '';

  private readonly table = h('table', { class: 'sheet' });
  private readonly preview: HTMLElement;
  private readonly colors = h('div', { class: 'chart-colors' });
  private readonly kinds = new Map<ChartKind, HTMLButtonElement>();
  private readonly stacked = h('input', { type: 'checkbox' });
  private readonly legend = h('input', { type: 'checkbox' });
  private readonly okButton: HTMLButtonElement;
  private readonly backdrop: HTMLElement;
  private colorsShown = '';

  constructor(
    options: ChartDialogOptions,
    private readonly done: (spec: ChartSpec | null) => void,
  ) {
    this.spec = { ...options.spec, colors: [...options.spec.colors] };
    this.cells = options.spec.cells.map((row) => [...row]);
    this.preview = h('div', { class: 'chart-preview', 'data-mode': options.pageMode });
    this.okButton = h('button', { class: 'button primary', onclick: () => this.close(true) }, options.isNew ? 'Insert chart' : 'Update chart');

    const title = h('input', { class: 'field', placeholder: 'Chart title', value: this.spec.title, spellcheck: 'false' });
    const sheetButton = (label: string, hint: string, action: () => void) =>
      h('button', { class: 'button small', title: hint, onmousedown: (event: Event) => event.preventDefault(), onclick: action }, label);

    title.addEventListener('input', () => {
      this.spec.title = title.value;
      this.redraw();
    });

    this.stacked.checked = this.spec.stacked;
    this.legend.checked = this.spec.legend;

    this.stacked.addEventListener('change', () => {
      this.spec.stacked = this.stacked.checked;
      this.redraw();
    });

    this.legend.addEventListener('change', () => {
      this.spec.legend = this.legend.checked;
      this.redraw();
    });

    for (const kind of KINDS) {
      const button = h('button', { class: 'kind', onclick: () => this.setKind(kind.id) }, kind.label);
      this.kinds.set(kind.id, button);
    }

    this.backdrop = h(
      'div',
      { class: 'dialog-backdrop' },
      h(
        'div',
        { class: 'dialog chart-dialog', role: 'dialog' },
        h('h2', null, options.isNew ? 'Insert chart' : 'Change chart'),
        h(
          'div',
          { class: 'chart-columns' },
          h(
            'div',
            { class: 'chart-side' },
            h(
              'div',
              { class: 'sheet-tools' },
              sheetButton('+ Row', 'Insert a row above the cell in hand', () => this.insert('row')),
              sheetButton('+ Column', 'Insert a column left of the cell in hand', () => this.insert('col')),
              sheetButton('− Row', 'Delete the row of the cell in hand', () => this.remove('row')),
              sheetButton('− Column', 'Delete the column of the cell in hand', () => this.remove('col')),
            ),
            h('div', { class: 'sheet-scroll' }, this.table),
            h('p', { class: 'sheet-hint' }, 'Row 1 names the series, column A the categories. A cell that starts with = is a formula: =SUM(B2:B5), =B2*1.19'),
          ),
          h(
            'div',
            { class: 'chart-side' },
            h('div', { class: 'kinds' }, ...this.kinds.values()),
            title,
            h('div', { class: 'chart-checks' }, h('label', { class: 'check' }, this.stacked, 'Stacked'), h('label', { class: 'check' }, this.legend, 'Legend')),
            this.colors,
            this.preview,
          ),
        ),
        h('div', { class: 'buttons' }, h('span', { class: 'chart-note' }, options.note ?? ''), h('button', { class: 'button', onclick: () => this.close(false) }, 'Cancel'), this.okButton),
      ),
    );

    closePopover();
    document.addEventListener('keydown', this.onKey, true);
    document.body.append(this.backdrop);

    this.build();
    this.setKind(this.spec.kind);
    this.focus(1, 1);
  }

  private close(accept: boolean): void {
    document.removeEventListener('keydown', this.onKey, true);
    this.backdrop.remove();
    this.done(accept ? { ...this.spec, title: this.spec.title.trim(), cells: trimCells(this.cells) } : null);
  }

  private readonly onKey = (event: KeyboardEvent): void => {
    const cell = (event.target as HTMLElement | null)?.closest?.('.cell') as HTMLInputElement | null;

    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();

      // In a cell, Escape takes back what was typed there; anywhere else it closes the dialog.
      if (!cell) {
        this.close(false);
      } else {
        const { r, c } = this.current;

        this.cells[r][c] = this.before;
        cell.value = editText(this.before);
        cell.select();
        this.changed();
      }
    } else if (event.key === 'Enter' && (event.ctrlKey || event.metaKey) && !this.okButton.disabled) {
      event.preventDefault();
      event.stopPropagation();
      this.close(true);
    }
  };

  // ---- The sheet -----------------------------------------------------------------------------

  /** The sheet's size: what is filled, an empty row and column to grow into, and never less than a screenful. */
  private pad(): void {
    const used = trimCells(this.cells);
    const rows = Math.min(MAX_ROWS, Math.max(MIN_ROWS, used.length + 1, this.cells.length));
    const cols = Math.min(MAX_COLS, Math.max(MIN_COLS, (used[0]?.length ?? 0) + 1, this.cells[0]?.length ?? 0));

    this.cells = Array.from({ length: rows }, (_row, r) => Array.from({ length: cols }, (_cell, c) => this.cells[r]?.[c] ?? ''));
  }

  /** Lays the table out anew. Typing only ever adds to it (`grow`); this is for everything else. */
  private build(): void {
    this.cells = trimCells(this.cells);
    this.pad();
    this.inputs = [];

    const head = h('tr', null, h('th', { class: 'corner' }));
    const body = h('tbody');

    for (let c = 0; c < this.cells[0].length; c++) head.append(h('th', null, colName(c)));

    this.cells.forEach((_row, r) => body.append(this.rowEl(r)));
    this.table.replaceChildren(h('thead', null, head), body);
    this.changed();
  }

  private rowEl(r: number): HTMLElement {
    const row = h('tr', null, h('th', null, String(r + 1)));

    this.inputs[r] = [];

    for (let c = 0; c < this.cells[r].length; c++) row.append(this.cellEl(r, c));

    return row;
  }

  private cellEl(r: number, c: number): HTMLElement {
    const input = h('input', { class: 'cell', spellcheck: 'false', autocomplete: 'off', 'aria-label': `${colName(c)}${r + 1}` });

    input.addEventListener('focus', () => {
      this.current = { r, c };
      this.before = this.cells[r][c];
      input.value = editText(this.cells[r][c]);
      input.classList.remove('num', 'err');
    });

    input.addEventListener('input', () => {
      this.current = { r, c };
      this.cells[r][c] = storedText(input.value);
      this.grow();
      this.changed();
    });

    input.addEventListener('blur', () => this.show(r, c));
    input.addEventListener('keydown', (event) => this.cellKey(event, input, r, c));
    input.addEventListener('paste', (event) => this.paste(event, r, c));

    this.inputs[r][c] = input;
    return h('td', null, input);
  }

  /** Adds the rows and columns that typing into the last ones calls for, without touching the rest. */
  private grow(): void {
    const rows = this.cells.length;
    const cols = this.cells[0].length;

    this.pad();

    if (this.cells[0].length > cols) {
      const head = this.table.tHead!.rows[0];

      for (let c = cols; c < this.cells[0].length; c++) head.append(h('th', null, colName(c)));

      for (let r = 0; r < rows; r++) {
        for (let c = cols; c < this.cells[0].length; c++) this.table.tBodies[0].rows[r].append(this.cellEl(r, c));
      }
    }

    for (let r = rows; r < this.cells.length; r++) this.table.tBodies[0].append(this.rowEl(r));
  }

  /** Puts a cell's value into its box, unless the box is being typed in. */
  private show(r: number, c: number): void {
    const input = this.inputs[r]?.[c];
    if (!input || input === document.activeElement) return;

    const value = this.values[r]?.[c] ?? null;

    input.value = shownText(value);
    input.classList.toggle('num', typeof value === 'number');
    input.classList.toggle('err', value instanceof CellError);
    input.classList.toggle('head', r === 0 || c === 0);
  }

  /** A cell changed: every cell is worked out again, and the chart drawn again. */
  private changed(): void {
    this.values = evaluateSheet(this.cells);

    for (let r = 0; r < this.inputs.length; r++) {
      for (let c = 0; c < this.inputs[r].length; c++) this.show(r, c);
    }

    this.redraw();
  }

  private focus(r: number, c: number): void {
    const input = this.inputs[Math.max(0, Math.min(this.inputs.length - 1, r))]?.[Math.max(0, Math.min(this.inputs[0].length - 1, c))];

    input?.focus();
    input?.select();
  }

  private cellKey(event: KeyboardEvent, input: HTMLInputElement, r: number, c: number): void {
    const caret = input.selectionStart === input.selectionEnd ? input.selectionStart : null;
    let to: [number, number] | null = null;

    if (event.ctrlKey || event.metaKey || event.altKey) return;

    if (event.key === 'Enter') to = [r + (event.shiftKey ? -1 : 1), c];
    else if (event.key === 'ArrowDown') to = [r + 1, c];
    else if (event.key === 'ArrowUp') to = [r - 1, c];
    else if (event.key === 'ArrowLeft' && caret === 0) to = [r, c - 1];
    else if (event.key === 'ArrowRight' && caret === input.value.length) to = [r, c + 1];

    if (to && to[0] >= 0 && to[1] >= 0) {
      event.preventDefault();
      this.focus(to[0], to[1]);
    }
  }

  /** A block of cells copied from a spreadsheet arrives as lines of text with tabs between the cells. */
  private paste(event: ClipboardEvent, r: number, c: number): void {
    const text = (event.clipboardData?.getData('text/plain') ?? '').replace(/\r?\n$/, '');
    if (!/[\t\n]/.test(text)) return;

    event.preventDefault();

    text.split(/\r?\n/).forEach((line, i) => {
      line.split('\t').forEach((cell, k) => {
        if (r + i >= MAX_ROWS || c + k >= MAX_COLS) return;

        while (this.cells.length <= r + i) this.cells.push([]);
        while (this.cells[r + i].length <= c + k) this.cells[r + i].push('');

        this.cells[r + i][c + k] = storedText(cell);
      });
    });

    this.before = this.cells[r][c];
    this.build();
    this.focus(r, c);
  }

  private insert(axis: 'row' | 'col'): void {
    const { r, c } = this.current;

    if (axis === 'row') this.cells.splice(r, 0, this.cells[0].map(() => ''));
    else this.cells.forEach((row) => row.splice(c, 0, ''));

    this.shiftColors(axis, axis === 'row' ? r : c, 1);
    this.shift(axis, axis === 'row' ? r : c, 1);
  }

  /** The colours go by series (by slice for a pie): they move with their row or column. */
  private shiftColors(axis: 'row' | 'col', at: number, delta: 1 | -1): void {
    const { colors } = this.spec;

    if (axis !== (this.spec.kind === 'pie' ? 'row' : 'col') || at < 1 || at - 1 >= colors.length) return;

    if (delta > 0) colors.splice(at - 1, 0, '');
    else colors.splice(at - 1, 1);
  }

  private remove(axis: 'row' | 'col'): void {
    const { r, c } = this.current;

    if (axis === 'row') this.cells.splice(r, 1);
    else this.cells.forEach((row) => row.splice(c, 1));

    this.shiftColors(axis, axis === 'row' ? r : c, -1);
    this.shift(axis, axis === 'row' ? r : c, -1);
  }

  /** After a row or column came or went: formulas follow the cells they point at. */
  private shift(axis: 'row' | 'col', at: number, delta: 1 | -1): void {
    const { r, c } = this.current;

    this.cells = this.cells.map((row) => row.map((cell) => shiftFormula(cell, axis, at, delta)));
    this.build();
    this.focus(r, c);
  }

  // ---- The chart -----------------------------------------------------------------------------

  private setKind(kind: ChartKind): void {
    this.spec.kind = kind;

    for (const [id, button] of this.kinds) button.setAttribute('aria-pressed', String(id === kind));

    this.stacked.disabled = !canStack(kind);
    this.stacked.parentElement!.classList.toggle('off', !canStack(kind));
    this.redraw();
  }

  private redraw(): void {
    const spec = { ...this.spec, cells: trimCells(this.cells) };
    const data = dataOf(spec);
    const pie = spec.kind === 'pie';
    const names = (pie ? data.categories : data.series.map((one) => one.name)).slice(0, MOST_COLORS);
    const shown = `${spec.kind}|${names.join('|')}`;

    this.preview.innerHTML = chartSvg(spec, PREVIEW.w, PREVIEW.h);
    this.okButton.disabled = !hasData(data);

    // The colour boxes are only made anew when what they stand for changed: making them anew
    // while one is open would close the colour picker under the mouse.
    if (shown !== this.colorsShown) {
      this.colorsShown = shown;
      this.colors.replaceChildren(
        h('span', { class: 'chart-colors-label' }, 'Colours'),
        ...names.map((name, i) => {
          const box = h('input', { type: 'color', value: colorOf(spec, i), title: name || `${pie ? 'Slice' : 'Series'} ${i + 1}` });

          box.addEventListener('input', () => {
            while (this.spec.colors.length < i) this.spec.colors.push('');

            this.spec.colors[i] = box.value.toUpperCase();
            this.redraw();
          });

          return box;
        }),
      );
    }
  }
}

/** Shows the chart editor and answers with the chart as it was left, or null if it was cancelled. */
export function chartDialog(options: ChartDialogOptions): Promise<ChartSpec | null> {
  return new Promise((resolve) => {
    new ChartDialog(options, resolve);
  });
}
