// Inserting captions, cross-references and tables of contents, the way Word writes them.

import type { Node as PMNode } from 'prosemirror-model';
import { type Command, type EditorState, TextSelection, type Transaction } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { schema } from '../editor/schema';
import { bookmarkText, findBookmark } from './builtin';
import { bookmarkNodes, ensureFieldStyle, fieldCodes, fieldNodes, newBookmarkName } from './build';
import { type Field, isHidden, parseInstr, scanFields, visibleText } from './model';
import { outlineLevel } from './seq';
import { updateFields } from './update';

const N = schema.nodes;

/** The labels Word offers for captions. */
export const CAPTION_LABELS = ['Figure', 'Table', 'Equation'];

/** A SEQ identifier from a label: Word's identifiers have no spaces. */
export const seqId = (label: string): string => label.trim().replace(/\s+/g, '_');

/**
 * Inserts a caption: a Caption paragraph "Figure 3: text" with a SEQ field for the number, below
 * (or above) the block the cursor is in. The number is set right by the update the insert sets off.
 */
export function insertCaption(ctx: DocContext, label: string, text: string, above = false): Command {
  return (state, dispatch) => {
    const name = label.trim();
    if (!name) return false;
    if (!dispatch) return true;

    const { $from } = state.selection;
    const at = $from.depth ? (above ? $from.before(1) : $from.after(1)) : state.selection.from;
    const styleId = ensureFieldStyle(ctx, 'caption');
    const content: PMNode[] = [schema.text(`${name} `), ...fieldNodes(`SEQ ${seqId(name)} \\* ARABIC`, '1')];
    if (text.trim()) content.push(schema.text(`: ${text.trim()}`));

    const paragraph = N.paragraph.create({ styleId }, content);
    const tr = state.tr.insert(at, paragraph);

    updateFields(tr, ctx, { only: 'live' });
    const end = tr.mapping.map(at, -1) + paragraph.nodeSize - 1;
    tr.setSelection(TextSelection.near(tr.doc.resolve(Math.min(end, tr.doc.content.size))));
    dispatch(tr.scrollIntoView());
    return true;
  };
}

// ---- What can be referred to -----------------------------------------------------------------------

export interface CaptionTarget {
  kind: 'caption';
  /** The SEQ identifier, as written (Figure, Table, ...). */
  label: string;
  /** The paragraph's position, and the SEQ field in it. */
  pos: number;
  seq: Field;
  /** "Figure 3: The results", for a list to pick from. */
  text: string;
}

export interface HeadingTarget {
  kind: 'heading';
  pos: number;
  level: number;
  text: string;
}

export type RefTarget = CaptionTarget | HeadingTarget;

/** Every caption in the document, by label, in order. */
export function captionTargets(doc: PMNode): CaptionTarget[] {
  const out: CaptionTarget[] = [];
  const seen = new Set<number>();

  for (const field of scanFields(doc).fields) {
    if (field.type !== 'SEQ' || field.parent) continue;

    const $pos = doc.resolve(field.from);
    const pos = $pos.before();
    if (seen.has(pos)) continue;
    seen.add(pos);

    const label = parseInstr(field.instr).args[0] ?? '';
    const text = visibleText(doc, pos + 1, pos + $pos.parent.nodeSize - 1).replace(/\s+/g, ' ').trim();
    out.push({ kind: 'caption', label: label.replace(/_/g, ' '), pos, seq: field, text });
  }

  return out;
}

/** Every heading, with its outline level (0 for Heading 1). */
export function headingTargets(doc: PMNode, ctx: DocContext): HeadingTarget[] {
  const out: HeadingTarget[] = [];

  doc.descendants((node, pos) => {
    if (node.type !== N.paragraph) return !node.isInline;

    const level = outlineLevel(ctx, node);
    const text = level === null ? '' : visibleText(doc, pos + 1, pos + node.nodeSize - 1).replace(/\s+/g, ' ').trim();
    if (level !== null && text) out.push({ kind: 'heading', pos, level, text });
    return false;
  });

  return out;
}

/** What a cross-reference shows: Word's "Insert reference to". */
export type RefWhat = 'labelNumber' | 'number' | 'text' | 'page';

/** Moves a start position forward, and an end backward, past hidden nodes (field codes, bookmarks). */
function tighten(doc: PMNode, from: number, to: number): [number, number] {
  while (from < to && isHidden(doc.nodeAt(from))) from++;
  while (to > from && isHidden(doc.resolve(to).nodeBefore)) to--;
  return [from, to];
}

/** The range a reference's bookmark goes around. */
function targetRange(doc: PMNode, target: RefTarget, what: RefWhat): [number, number] {
  const para = doc.nodeAt(target.pos)!;
  const start = target.pos + 1;
  const end = target.pos + para.nodeSize - 1;

  if (target.kind === 'heading' || what === 'text') return [start, end];

  const seq = scanFields(doc).fields.find((f) => f.type === 'SEQ' && f.from >= start && f.to <= end) ?? target.seq;
  return what === 'number' ? [seq.from, seq.to] : [start, seq.to];
}

/**
 * Inserts a cross-reference at the cursor: a `_Ref` bookmark around the target (one already there
 * for the same words is used again) and a REF or PAGEREF field with `\h`. `pageOf` gives page
 * numbers for positions in the current document, when there is a layout.
 */
export function insertCrossReference(ctx: DocContext, target: RefTarget, what: RefWhat, pageOf: ((pos: number) => number | null) | null = null): Command {
  return (state, dispatch) => {
    if (!dispatch) return true;

    const tr = state.tr;
    const doc = state.doc;
    const scan = scanFields(doc);
    const [from, to] = targetRange(doc, target, what);
    const wanted = tighten(doc, from, to);
    let name: string | null = null;

    for (const bookmark of scan.bookmarks.values()) {
      if (!bookmark.name.startsWith('_Ref')) continue;
      const [a, b] = tighten(doc, bookmark.from, bookmark.to);
      if (a === wanted[0] && b === wanted[1]) {
        name = bookmark.name;
        break;
      }
    }

    if (!name) {
      name = newBookmarkName('_Ref', scan);
      const [start, end] = bookmarkNodes(name, scan.maxId + 1);
      tr.insert(to, end);
      tr.insert(from, start);
    }

    const marks = state.storedMarks ?? state.selection.$from.marks();
    const instr = what === 'page' ? `PAGEREF ${name} \\h` : `REF ${name} \\h`;
    const bookmark = findBookmark(scanFields(tr.doc), name);
    let result = '';

    if (bookmark && what !== 'page') result = bookmarkText(tr.doc, bookmark);
    else if (bookmark && pageOf) result = String(pageOf(tr.mapping.invert().map(bookmark.from)) ?? '');

    const nodes = fieldNodes(instr, result || '?', marks);
    const at = tr.mapping.map(state.selection.from);
    tr.replaceWith(at, tr.mapping.map(state.selection.to), nodes);
    dispatch(tr.scrollIntoView());
    return true;
  };
}

// ---- Table of contents -----------------------------------------------------------------------------

/** The table of contents in a document, if it has one. */
export function findToc(doc: PMNode): Field | null {
  return scanFields(doc).fields.find((field) => field.type === 'TOC' && !/\\c/i.test(field.instr)) ?? null;
}

/**
 * Inserts a table of contents before the paragraph the cursor is in (in place of it, if it is
 * empty), with a "Contents" heading, and fills it in. With one already in the document, updates
 * that one instead.
 */
export function insertToc(ctx: DocContext, pageOf: ((pos: number) => number | null) | null): Command {
  return (state, dispatch) => {
    if (!dispatch) return true;

    const tr = state.tr;
    const existing = findToc(state.doc);

    if (existing) {
      updateFields(tr, ctx, { range: [existing.from, existing.to], pages: pageOf });
      dispatch(tr.scrollIntoView());
      return true;
    }

    const { $from } = state.selection;
    const block = $from.depth ? $from.node(1) : null;
    const at = $from.depth ? $from.before(1) : state.selection.from;
    const replace = block && block.type === N.paragraph && block.content.size === 0 && !block.attrs.sectPr;
    const heading = N.paragraph.create({ styleId: ensureFieldStyle(ctx, 'TOC Heading') }, schema.text('Contents'));
    const [begin, end] = fieldCodes('TOC \\o "1-3" \\h \\z \\u');
    const field = N.paragraph.create({ styleId: ensureFieldStyle(ctx, 'toc 1') }, [begin, end]);

    tr.replaceWith(at, replace ? at + block!.nodeSize : at, [heading, field]);
    const fieldPos = at + heading.nodeSize;
    const inserted = scanFields(tr.doc).fields.find((f) => f.type === 'TOC' && f.from > fieldPos);

    if (inserted) updateFields(tr, ctx, { range: [inserted.from, inserted.to], pages: pageOf, pagesFrom: 0 });
    dispatch(tr.scrollIntoView());
    return true;
  };
}

/** Updates the fields in the selection, or the one the cursor is in, or (with `all`) every field. */
export function updateFieldsCommand(ctx: DocContext, all: boolean, pageOf: ((pos: number) => number | null) | null): Command {
  return (state: EditorState, dispatch?: (tr: Transaction) => void) => {
    const { from, to } = state.selection;
    const tr = state.tr;
    const changed = updateFields(tr, ctx, { range: all ? undefined : [from, to], pages: pageOf });

    if (changed && dispatch) dispatch(tr);
    return changed;
  };
}
