/** Modes whose answer may be much shorter than the paragraph. */
const SHORTENING = new Set<WriteMode | 'translate'>(['short', 'acad-concise']);

/** Languages to translate into, by the name the model is given. */
export const LANGUAGES = [
  'English', 'German', 'French', 'Spanish', 'Italian', 'Portuguese', 'Dutch', 'Polish', 'Czech', 'Swedish', 'Danish', 'Norwegian',
  'Finnish', 'Turkish', 'Russian', 'Ukrainian', 'Greek', 'Japanese', 'Chinese (Simplified)', 'Korean', 'Arabic',
];

/** About how many tokens a text is, for the limit on the answer's length. */
const tokensFor = (text: string) => Math.ceil(text.length / 3);

/** What the model is asked for one paragraph. `custom` is the user's own instruction, for the custom mode. */
export function writeRequest(model: string, mode: WriteMode, text: string, custom = '', context = ''): AssistRequest {
  const spec: ModeSpec =
    mode === 'custom'
      ? { persona: COPY_EDITOR, task: `Revise it following this instruction: ${custom.trim() || 'improve it'}. Correct any mistakes.` }
      : MODES[mode];

  return {
    model,
    system:
      `${spec.persona} The user sends one paragraph from a document. ` +
      `${spec.task} ${spec.academic ? `${ACADEMIC_RULES} ` : ''}${context ? `${context} ` : ''}Always answer in the language of the paragraph. ` +
      'Reply with the revised paragraph only: no quotation marks around it, no explanation, no preamble. ' +
      'If nothing needs to change, reply with the paragraph exactly as it is.',
    text,
    temperature: spec.temperature ?? 0.3,
    maxTokens: tokensFor(text) * 2 + 64,
  };
}

export function translateRequest(model: string, language: string, text: string, tagged: boolean): AssistRequest {
  return {
    model,
    system:
      `You are a professional translator. Translate the user's text into ${language}. ` +
      'Reply with the translation only: no quotation marks around it, no notes, no preamble. Keep its line breaks. ' +
      (tagged
        ? 'The text contains markup: tags such as <s1>…</s1> around words, and empty tags such as <x1/>. ' +
          'Keep every tag exactly as written, and place each one around, or at, the words of the translation that correspond. '
        : '') +
      'If the text is already in that language, reply with it unchanged.',
    text,
    temperature: 0.1,
    maxTokens: tokensFor(text) * 3 + 64,
  };
}

/**
 * The model's answer as text to use, or null when it is not a version of the paragraph at all
 * (empty, or far longer or shorter than it). Thinking a model did anyway is removed, and so are
 * quotation marks or a code fence put around the whole answer.
 */
export function cleanAnswer(answer: string, original: string, mode: WriteMode | 'translate'): string | null {
  let text = answer.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const core = original.trim();

  const fence = /^```[^\n]*\n([\s\S]*?)\n?```$/.exec(text);
  if (fence) text = fence[1].trim();

  for (const [open, close] of [['"', '"'], ['“', '”'], ['„', '“'], ['«', '»'], ["'", "'"]]) {
    if (text.length > 1 && text.startsWith(open) && text.endsWith(close) && !(core.startsWith(open) && core.endsWith(close))) {
      text = text.slice(open.length, -close.length).trim();
    }
  }

  if (!text) return null;

  const ratio = text.length / Math.max(1, core.length);
  const [low, high] = mode === 'translate' ? [0.25, 4] : SHORTENING.has(mode) ? [0.15, 1.6] : [0.4, 2.5];

  if (core.length > 20 && (ratio < low || ratio > high)) return null;

  // The paragraph's own space before and after, which the answer leaves out.
  const lead = /^\s*/.exec(original)![0];
  const trail = /\s*$/.exec(original)![0];

  return lead + text + trail;
}
