// The writing assistant's suggestions, as marks on the page that are not in the document.
//
// Each suggestion is a decoration: an underline under the words it would change, or a small mark
// where it would add some. Decorations move with the text as it is edited, so a suggestion stays
// on its words while the rest of the paragraph changes; one whose own words were edited goes.
//
// A paragraph still being checked is a decoration too. When its answer comes back, the
// decoration says where the paragraph is now, and whether its text is still what was sent.

import type { Node as PMNode } from 'prosemirror-model';
import { type EditorState, Plugin, PluginKey, TextSelection, type Transaction } from 'prosemirror-state';
import { Decoration, DecorationSet, type EditorView } from 'prosemirror-view';
import { diffWords } from '../assist/diff';
import { type Piece, pieceOf, rangeOf, replaceKeepingLeaves } from '../assist/text';

export interface Suggestion {
  id: number;
  from: number;
  to: number;
  /** The text it replaces; '' when it only adds. */
  original: string;
  insert: string;
}

interface Spec {
  kind: 'suggestion' | 'pending' | 'review';
  id: number;
  original: string;
  insert: string;
}

interface SuggestMeta {
  add?: Suggestion[];
  remove?: number[];
  clear?: boolean;
  pending?: { id: number; from: number; to: number; text: string }[];
  done?: number[];
  /** Places a document review found; they move with edits, and go when their text is edited. */
  review?: { id: number; from: number; to: number; text: string }[];
  clearReview?: boolean;
}

export const suggestKey = new PluginKey<DecorationSet>('suggest');

let lastId = 0;
const nextId = () => ++lastId;

/** The text of a range as the assistant reads it: text and line breaks, nothing else. */
const textAt = (doc: PMNode, from: number, to: number) => pieceOf(doc, from, to).text;

function decoration(kind: Spec['kind'], id: number, from: number, to: number, original: string, insert: string): Decoration {
  const spec: Spec = { kind, id, original, insert };

  if (kind === 'pending') return Decoration.inline(from, to, { class: 'assist-pending' }, spec);
  if (kind === 'review') return Decoration.inline(from, to, { class: 'review-spot' }, spec);

  const title = original ? (insert ? `${original} → ${insert}` : `Remove “${original}”`) : `Add “${insert}”`;

  if (from === to) {
    return Decoration.widget(
      from,
      () => {
        const mark = document.createElement('span');

        mark.className = 'suggest suggest-add';
        mark.dataset.sid = String(id);
        mark.title = title;
        return mark;
      },
      { ...spec, side: 1, key: `s${id}` },
    );
  }

  return Decoration.inline(from, to, { class: insert ? 'suggest' : 'suggest suggest-cut', 'data-sid': String(id), title }, spec);
}

const specOf = (deco: Decoration) => deco.spec as Spec;

/** Drops suggestions and pending paragraphs whose text is no longer what it was. */
function stillTrue(doc: PMNode, set: DecorationSet): DecorationSet {
  const stale = set.find(undefined, undefined, (spec: Spec) => !!spec.kind).filter((deco) => {
    const spec = specOf(deco);
    return deco.from > deco.to || textAt(doc, deco.from, deco.to) !== spec.original;
  });

  return stale.length ? set.remove(stale) : set;
}

export function suggestPlugin(onClick: (view: EditorView, id: number, target: HTMLElement) => void): Plugin<DecorationSet> {
  return new Plugin<DecorationSet>({
    key: suggestKey,
    state: {
      init: () => DecorationSet.empty,
      apply(tr, old) {
        const meta = tr.getMeta(suggestKey) as SuggestMeta | undefined;
        let set = old.map(tr.mapping, tr.doc);

        if (tr.docChanged) set = stillTrue(tr.doc, set);
        if (!meta) return set;

        if (meta.clear) {
          set = set.remove(set.find(undefined, undefined, (spec: Spec) => spec.kind === 'suggestion'));
        }

        if (meta.clearReview) {
          set = set.remove(set.find(undefined, undefined, (spec: Spec) => spec.kind === 'review'));
        }

        const gone = new Set([...(meta.remove ?? []), ...(meta.done ?? [])]);

        if (gone.size) set = set.remove(set.find(undefined, undefined, (spec: Spec) => gone.has(spec.id)));

        const added = [
          ...(meta.add ?? []).map((s) => decoration('suggestion', s.id, s.from, s.to, s.original, s.insert)),
          ...(meta.pending ?? []).map((p) => decoration('pending', p.id, p.from, p.to, p.text, '')),
          ...(meta.review ?? []).map((p) => decoration('review', p.id, p.from, p.to, p.text, '')),
        ];

        return added.length ? set.add(tr.doc, added) : set;
      },
    },
    props: {
      decorations: (state) => suggestKey.getState(state),
      handleClick(view, _pos, event) {
        const target = (event.target as HTMLElement | null)?.closest<HTMLElement>('.suggest[data-sid]');
        if (!target) return false;

        onClick(view, Number(target.dataset.sid), target);
        return false;
      },
    },
  });
}

// ---- Reading the state -----------------------------------------------------------------------

/** The suggestions in the document, in reading order. */
export function suggestions(state: EditorState): Suggestion[] {
  const set = suggestKey.getState(state);
  if (!set) return [];

  return set
    .find(undefined, undefined, (spec: Spec) => spec.kind === 'suggestion')
    .map((deco) => ({ id: specOf(deco).id, from: deco.from, to: deco.to, original: specOf(deco).original, insert: specOf(deco).insert }))
    .sort((a, b) => a.from - b.from || a.id - b.id);
}

export function suggestionById(state: EditorState, id: number): Suggestion | null {
  return suggestions(state).find((s) => s.id === id) ?? null;
}

/** How many paragraphs are still waiting for their answer. */
export function pendingCount(state: EditorState): number {
  return suggestKey.getState(state)?.find(undefined, undefined, (spec: Spec) => spec.kind === 'pending').length ?? 0;
}

// ---- Changing it -----------------------------------------------------------------------------

/**
 * Marks stretches of paragraphs as being checked, and answers their ids. The decorations keep
 * track of where the stretches go while their answers are on the way. Suggestions already on
 * them are dropped: the new answer replaces them.
 */
export function markPending(view: EditorView, pieces: Piece[]): number[] {
  const pending = pieces.map((piece) => ({ id: nextId(), from: piece.map[0], to: piece.end, text: piece.text }));
  const old = suggestions(view.state).filter((s) => pending.some((p) => s.from < p.to && s.to > p.from));

  view.dispatch(view.state.tr.setMeta(suggestKey, { pending, remove: old.map((s) => s.id) }).setMeta('addToHistory', false));
  return pending.map((p) => p.id);
}

/** Where a pending stretch is now, if its text is still the text that was sent. */
export function pendingPiece(state: EditorState, id: number): Piece | null {
  const deco = suggestKey.getState(state)?.find(undefined, undefined, (spec: Spec) => spec.kind === 'pending' && spec.id === id)[0];
  if (!deco) return null;

  const piece = pieceOf(state.doc, deco.from, deco.to);
  return piece.text === specOf(deco).original ? piece : null;
}

/**
 * The answer for a pending stretch came: its changes become suggestions, which it answers; none
 * when the stretch was edited in the meantime, or nothing needed changing.
 */
export function resolvePending(view: EditorView, id: number, revised: string | null): Suggestion[] {
  const piece = pendingPiece(view.state, id);
  const tr = view.state.tr.setMeta('addToHistory', false);
  const add: Suggestion[] = [];

  if (piece && revised !== null) {
    for (const change of diffWords(piece.text, revised)) {
      const { from, to } = rangeOf(piece, change.from, change.to);
      add.push({ id: nextId(), from, to, original: piece.text.slice(change.from, change.to), insert: change.insert });
    }
  }

  view.dispatch(tr.setMeta(suggestKey, { done: [id], add }));
  return add;
}

/** Stops waiting for these stretches. */
export function dropPending(view: EditorView, ids: number[]): void {
  if (ids.length) view.dispatch(view.state.tr.setMeta(suggestKey, { done: ids }).setMeta('addToHistory', false));
}

function apply(tr: Transaction, s: Suggestion): void {
  replaceKeepingLeaves(tr, s.from, s.to, s.insert);
}

/** Takes a suggestion: its words are changed in the document, as one step to undo. */
export function acceptSuggestion(view: EditorView, id: number): boolean {
  const s = suggestionById(view.state, id);
  if (!s) return false;

  const tr = view.state.tr;

  apply(tr, s);
  tr.setMeta(suggestKey, { remove: [id] });
  view.dispatch(tr);
  return true;
}

/** Takes every suggestion, as one step to undo. */
export function acceptAll(view: EditorView): number {
  const all = suggestions(view.state);
  if (!all.length) return 0;

  const tr = view.state.tr;

  // From the end, so that positions further up stay true.
  for (let i = all.length - 1; i >= 0; i--) apply(tr, all[i]);
  tr.setMeta(suggestKey, { clear: true });
  view.dispatch(tr);
  return all.length;
}

export function rejectSuggestion(view: EditorView, id: number): void {
  view.dispatch(view.state.tr.setMeta(suggestKey, { remove: [id] }).setMeta('addToHistory', false));
}

export function clearSuggestions(view: EditorView): void {
  view.dispatch(view.state.tr.setMeta(suggestKey, { clear: true }).setMeta('addToHistory', false));
}

/** Puts the cursor on a suggestion's words and brings them into view. */
export function showSuggestion(view: EditorView, id: number): void {
  const s = suggestionById(view.state, id);
  if (!s) return;

  view.dispatch(view.state.tr.setSelection(TextSelection.create(view.state.doc, s.from, s.to)).scrollIntoView());
}

// ---- Places a document review found ----------------------------------------------------------

/** Marks stretches a review found, replacing the last review's; answers their ids, in order. */
export function markReview(view: EditorView, spots: { from: number; to: number }[]): number[] {
  const review = spots
    .filter((s) => s.from < s.to)
    .map((s) => ({ id: nextId(), from: s.from, to: s.to, text: textAt(view.state.doc, s.from, s.to) }));

  view.dispatch(view.state.tr.setMeta(suggestKey, { review, clearReview: true }).setMeta('addToHistory', false));
  return review.map((r) => r.id);
}

/** Where a marked stretch is now; null once its text was edited. */
export function reviewSpot(state: EditorState, id: number): { from: number; to: number } | null {
  const deco = suggestKey.getState(state)?.find(undefined, undefined, (spec: Spec) => spec.kind === 'review' && spec.id === id)[0];
  return deco ? { from: deco.from, to: deco.to } : null;
}

export function clearReview(view: EditorView): void {
  view.dispatch(view.state.tr.setMeta(suggestKey, { clearReview: true }).setMeta('addToHistory', false));
}

/** Replaces marked stretches, as one step to undo. False, and nothing done, when one was edited. */
export function replaceReviewed(view: EditorView, edits: { id: number; insert: string }[]): boolean {
  const ranges = edits.map((e) => ({ ...e, at: reviewSpot(view.state, e.id) }));
  if (ranges.some((r) => !r.at)) return false;

  const tr = view.state.tr;

  for (const r of ranges.sort((a, b) => b.at!.from - a.at!.from)) replaceKeepingLeaves(tr, r.at!.from, r.at!.to, r.insert);
  view.dispatch(tr.scrollIntoView());
  return true;
}
