// A small XML reader that keeps source offsets.
//
// A .docx is XML this editor only partly understands. What it does not understand has to go back
// into the file exactly as it came, so every element remembers where it sits in the source and
// `raw()` hands that stretch back untouched. Names keep their prefix as written ("w:p"): the
// reader does not resolve namespaces, and import.ts refuses a file whose main prefix is not "w".

export interface XmlEl {
  name: string;
  attrs: Record<string, string>;
  /** Element children only; text between them is in `text`. */
  children: XmlEl[];
  /** The element's own text, entities decoded, child elements skipped. */
  text: string;
  /** The source the offsets below point into. */
  src: string;
  start: number;
  end: number;
  /** Just after the open tag, and just before the close tag. Equal to `end` when self-closing. */
  innerStart: number;
  innerEnd: number;
}

const ENTITIES: Record<string, string> = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'" };

export function decodeEntities(text: string): string {
  if (text.indexOf('&') < 0) {
    return text;
  }

  return text.replace(/&(#x[0-9a-fA-F]+|#\d+|[a-zA-Z]+);/g, (whole, body: string) => {
    if (body[0] === '#') {
      const code = body[1] === 'x' || body[1] === 'X' ? parseInt(body.slice(2), 16) : parseInt(body.slice(1), 10);
      return Number.isFinite(code) && code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : '';
    }

    return ENTITIES[body] ?? whole;
  });
}

const isSpace = (code: number) => code === 32 || code === 9 || code === 10 || code === 13;

/** Reads a document and returns its root element. Throws on XML that does not close properly. */
export function parseXml(src: string): XmlEl {
  const length = src.length;
  const stack: XmlEl[] = [];
  let root: XmlEl | null = null;
  let i = 0;

  while (i < length) {
    const lt = src.indexOf('<', i);
    const top = stack[stack.length - 1];

    if (lt < 0) {
      break;
    }

    if (top && lt > i) {
      top.text += decodeEntities(src.slice(i, lt));
    }

    const next = src.charCodeAt(lt + 1);

    // <?xml ... ?> and other processing instructions.
    if (next === 63) {
      const close = src.indexOf('?>', lt);
      if (close < 0) throw new Error('XML: unfinished processing instruction');
      i = close + 2;
      continue;
    }

    if (next === 33) {
      if (src.startsWith('<!--', lt)) {
        const close = src.indexOf('-->', lt + 4);
        if (close < 0) throw new Error('XML: unfinished comment');
        i = close + 3;
        continue;
      }

      if (src.startsWith('<![CDATA[', lt)) {
        const close = src.indexOf(']]>', lt + 9);
        if (close < 0) throw new Error('XML: unfinished CDATA section');
        if (top) top.text += src.slice(lt + 9, close);
        i = close + 3;
        continue;
      }

      // A DOCTYPE; Word never writes one, and nothing in it matters here.
      const close = src.indexOf('>', lt);
      if (close < 0) throw new Error('XML: unfinished declaration');
      i = close + 1;
      continue;
    }

    if (next === 47) {
      const gt = src.indexOf('>', lt);
      const el = stack.pop();
      if (gt < 0 || !el) throw new Error('XML: closing tag without an element');
      el.innerEnd = lt;
      el.end = gt + 1;
      i = gt + 1;
      continue;
    }

    // An opening tag: name, attributes, then > or />.
    let p = lt + 1;
    while (p < length) {
      const code = src.charCodeAt(p);
      if (isSpace(code) || code === 62 || code === 47) break;
      p++;
    }

    const el: XmlEl = {
      name: src.slice(lt + 1, p),
      attrs: {},
      children: [],
      text: '',
      src,
      start: lt,
      end: -1,
      innerStart: -1,
      innerEnd: -1,
    };

    let selfClosing = false;

    for (;;) {
      while (p < length && isSpace(src.charCodeAt(p))) p++;
      if (p >= length) throw new Error(`XML: <${el.name}> is never finished`);

      const code = src.charCodeAt(p);

      if (code === 62) {
        p++;
        break;
      }

      if (code === 47) {
        selfClosing = true;
        p = src.indexOf('>', p) + 1;
        if (p === 0) throw new Error(`XML: <${el.name}> is never finished`);
        break;
      }

      const nameStart = p;
      while (p < length) {
        const c = src.charCodeAt(p);
        if (c === 61 || isSpace(c) || c === 62 || c === 47) break;
        p++;
      }

      const attrName = src.slice(nameStart, p);
      while (p < length && isSpace(src.charCodeAt(p))) p++;

      if (src.charCodeAt(p) !== 61) {
        // An attribute with no value is not XML, but there is no reason to stop over it.
        el.attrs[attrName] = '';
        continue;
      }

      p++;
      while (p < length && isSpace(src.charCodeAt(p))) p++;

      const quote = src[p];
      if (quote !== '"' && quote !== "'") throw new Error(`XML: attribute ${attrName} has no quotes`);

      const valueEnd = src.indexOf(quote, p + 1);
      if (valueEnd < 0) throw new Error(`XML: attribute ${attrName} is never finished`);

      el.attrs[attrName] = decodeEntities(src.slice(p + 1, valueEnd));
      p = valueEnd + 1;
    }

    if (top) {
      top.children.push(el);
    } else if (!root) {
      root = el;
    }

    if (selfClosing) {
      el.innerStart = p;
      el.innerEnd = p;
      el.end = p;
    } else {
      el.innerStart = p;
      stack.push(el);
    }

    i = p;
  }

  if (!root || stack.length) {
    throw new Error(stack.length ? `XML: <${stack[stack.length - 1].name}> is never closed` : 'XML: no root element');
  }

  return root;
}

/** The element exactly as it stands in the source. */
export const raw = (el: XmlEl): string => el.src.slice(el.start, el.end);

/** What is between the element's tags, as it stands in the source. */
export const inner = (el: XmlEl): string => el.src.slice(el.innerStart, el.innerEnd);

/** The opening tag alone, as it stands in the source. For a self-closing element, the whole of it. */
export const openTag = (el: XmlEl): string => el.src.slice(el.start, el.innerStart);

export function child(el: XmlEl | null | undefined, name: string): XmlEl | null {
  if (!el) return null;

  for (const c of el.children) {
    if (c.name === name) return c;
  }

  return null;
}

export function childrenNamed(el: XmlEl | null | undefined, name: string): XmlEl[] {
  return el ? el.children.filter((c) => c.name === name) : [];
}

/** `w:val` of a child, the shape nearly every property in WordprocessingML has. */
export function val(el: XmlEl | null | undefined, name: string): string | null {
  return child(el, name)?.attrs['w:val'] ?? null;
}

/** Every descendant with this name, in document order. */
export function descendants(el: XmlEl, name: string, into: XmlEl[] = []): XmlEl[] {
  for (const c of el.children) {
    if (c.name === name) into.push(c);
    descendants(c, name, into);
  }

  return into;
}

/** Whether any descendant has one of these names. */
export function hasDescendant(el: XmlEl, names: ReadonlySet<string>): boolean {
  for (const c of el.children) {
    if (names.has(c.name) || hasDescendant(c, names)) return true;
  }

  return false;
}

// Characters XML 1.0 cannot carry at all, escaped or not.
const INVALID = /[\u0000-\u0008\u000B\u000C\u000E-\u001F￾￿]/g;

export function escText(text: string): string {
  return text.replace(INVALID, '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

export function escAttr(text: string): string {
  return escText(text).replace(/"/g, '&quot;').replace(/\t/g, '&#9;').replace(/\n/g, '&#10;').replace(/\r/g, '&#13;');
}

const splitCache = new Map<string, [string, string][]>();

/**
 * A run of sibling elements, as source, split into [name, source] pairs. Used for the insides of
 * `w:pPr`, `w:rPr` and the like, which are kept as source and patched on the way out.
 */
export function splitElements(source: string | null | undefined): [string, string][] {
  if (!source) return [];

  let parts = splitCache.get(source);

  if (!parts) {
    const holder = parseXml(`<x>${source}</x>`);
    parts = holder.children.map((c) => [c.name, raw(c)] as [string, string]);
    if (splitCache.size > 4000) splitCache.clear();
    splitCache.set(source, parts);
  }

  return parts;
}

const fragmentCache = new Map<string, XmlEl>();

/** Parses a run of sibling elements kept as source; the result's children are those elements. */
export function parseFragment(source: string | null | undefined): XmlEl | null {
  if (!source) return null;

  let holder = fragmentCache.get(source);

  if (!holder) {
    holder = parseXml(`<x>${source}</x>`);
    if (fragmentCache.size > 4000) fragmentCache.clear();
    fragmentCache.set(source, holder);
  }

  return holder;
}

/**
 * Puts properties into the order the schema asks for. Word refuses some files whose properties
 * come in another order, so everything written out goes through this. Names the list does not
 * know keep their relative order and go just before the entries in `last`.
 */
export function orderProps(entries: [string, string][], order: readonly string[], last: readonly string[]): string {
  const rank = (name: string) => {
    const tail = last.indexOf(name);
    if (tail >= 0) return order.length + 1 + tail;
    const at = order.indexOf(name);
    return at >= 0 ? at : order.length;
  };

  const seen = new Set<string>();
  const kept = entries.filter(([name]) => (seen.has(name) ? false : (seen.add(name), true)));

  return kept
    .map((entry, index) => ({ entry, index, rank: rank(entry[0]) }))
    .sort((a, b) => a.rank - b.rank || a.index - b.index)
    .map((item) => item.entry[1])
    .join('');
}
