// Tab characters drawn at the document's tab stops, with their leaders.
//
// A tab is a '\t' in the text. Each one gets an inline decoration that makes it an inline block of
// the width that carries the text after it to the right stop (docx/tabstops.ts does the sums).
// Widths depend on where the text falls, so they are measured after the view has drawn: the
// paragraphs a change touched are measured in the next frame and their widths set by a
// transaction of the plugin's own. A width that moves the text again is checked once or twice
// more, and then left alone.

import type { Node as PMNode } from 'prosemirror-model';
import { Plugin, PluginKey, type EditorState, type Transaction } from 'prosemirror-state';
import { Decoration, DecorationSet, type EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { type TabStop, defaultTabInterval, paragraphTabs, placeTab } from '../docx/tabstops';
import { schema } from './schema';

interface Placed {
  pos: number;
  width: number;
  leader: string;
}

interface TabsState {
  decorations: DecorationSet;
  /** Ranges of the current document whose tabs need measuring again. */
  dirty: [number, number][];
  /** How many times in a row the dirty ranges were measured without the text being edited. */
  passes: number;
}

interface TabsMeta {
  placed?: Placed[];
  measured?: [number, number];
  all?: boolean;
  settled?: boolean;
}

export const tabsKey = new PluginKey<TabsState>('tabs');

const MAX_PASSES = 3;

function hasTab(doc: PMNode, from: number, to: number): boolean {
  let found = false;

  doc.nodesBetween(from, to, (node) => {
    if (found) return false;
    if (node.isText && node.text!.includes('\t')) found = true;
    return !node.isInline;
  });

  return found;
}

/** A changed range widened to the top-level blocks it is in; null when those have no tab in them. */
function widen(doc: PMNode, from: number, to: number): [number, number] | null {
  const size = doc.content.size;
  const $a = doc.resolve(Math.max(0, Math.min(size, from)));
  const $b = doc.resolve(Math.max(0, Math.min(size, to)));
  const a = $a.depth ? $a.before(1) : $a.pos;
  const b = $b.depth ? $b.after(1) : $b.pos;

  return hasTab(doc, a, b) ? [a, b] : null;
}

function decoration(p: Placed): Decoration {
  return Decoration.inline(p.pos, p.pos + 1, { nodeName: 'span', class: `tab-char tab-${p.leader}`, style: `width:${p.width.toFixed(2)}px` }, { tab: p });
}

function applyMeta(old: TabsState, tr: Transaction, meta: TabsMeta): TabsState {
  let decorations = old.decorations;
  let dirty = old.dirty;
  let passes = old.passes;

  if (meta.all) return { decorations, dirty: [[0, tr.doc.content.size]], passes: 0 };

  if (meta.placed && meta.measured) {
    const [from, to] = meta.measured;
    decorations = decorations.remove(decorations.find(from, to)).add(tr.doc, meta.placed.map(decoration));
    dirty = dirty.filter(([a, b]) => b < from || a > to);

    if (!meta.settled && passes < MAX_PASSES) {
      dirty = [...dirty, [from, to]];
      passes++;
    }
  }

  return { decorations, dirty, passes };
}

function tabStopsCache(ctx: DocContext) {
  const cache = new Map<string, TabStop[]>();

  return (node: PMNode): TabStop[] => {
    const key = `${ctx.styles.version}|${node.attrs.styleId ?? ''}|${node.attrs.ppr ?? ''}`;
    let stops = cache.get(key);

    if (!stops) {
      stops = paragraphTabs(ctx.styles, node.attrs.styleId, node.attrs.ppr);
      if (cache.size > 500) cache.clear();
      cache.set(key, stops);
    }

    return stops;
  };
}

const sameLine = (a: DOMRect | { top: number; bottom: number }, b: { top: number; bottom: number }) =>
  Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top) > 0.5 * Math.min(a.bottom - a.top, b.bottom - b.top);

/** The first decimal separator in a run of text after a tab: a point or comma between digits, or the first point. */
function decimalIndex(text: string): number {
  const between = /\d[.,]\d/.exec(text);
  if (between) return between.index + 1;

  const point = text.search(/[.,]/);
  return point;
}

/** Measures the tabs of one paragraph; null when it is not laid out. */
function measureParagraph(view: EditorView, node: PMNode, pos: number, stops: TabStop[], intervalPx: number, zoom: number): Placed[] | null {
  const dom = view.nodeDOM(pos) as HTMLElement | null;
  if (!dom || !(dom instanceof HTMLElement) || !dom.isConnected) return null;

  const parent = dom.parentElement ?? dom;
  const parentStyle = getComputedStyle(parent);
  const originX = parent.getBoundingClientRect().left / zoom + (parseFloat(parentStyle.borderLeftWidth) || 0) + (parseFloat(parentStyle.paddingLeft) || 0);
  const style = getComputedStyle(dom);
  const marginLeft = parseFloat(style.marginLeft) || 0;
  const textIndent = parseFloat(style.textIndent) || 0;
  const hanging = textIndent < 0 ? marginLeft : null;

  // The tabs' positions, and the text between them.
  const tabs: number[] = [];
  // The visible characters between the tabs, as text and as positions. Field codes and other
  // hidden nodes are left out: they have no place on the line to measure from.
  const texts: string[] = [''];
  const chars: number[][] = [[]];

  node.descendants((child, offset) => {
    const at = pos + 1 + offset;

    if (child.isText) {
      const text = child.text!;

      for (let i = 0; i < text.length; i++) {
        if (text[i] === '	') {
          tabs.push(at + i);
          texts.push('');
          chars.push([]);
        } else {
          texts[texts.length - 1] += text[i];
          chars[chars.length - 1].push(at + i);
        }
      }
    } else if (child.isInline && !(child.type === schema.nodes.opaque && child.attrs.look === 'hidden')) {
      texts[texts.length - 1] += ' ';
      chars[chars.length - 1].push(at);
    }

    return true;
  });

  const placed: Placed[] = [];
  let lineTop: { top: number; bottom: number } | null = null;
  let shift = 0;

  const coords = (at: number, side: number) => {
    const c = view.coordsAtPos(at, side);
    return { left: c.left / zoom, top: c.top, bottom: c.bottom };
  };

  for (let i = 0; i < tabs.length; i++) {
    const at = tabs[i];
    const start = coords(at, 1);
    const after = coords(at + 1, -1);
    const current = sameLine(start, after) ? Math.max(0, after.left - start.left) : 0;

    if (!lineTop || !sameLine(lineTop, start)) {
      lineTop = start;
      shift = 0;
    }

    const segment = chars[i + 1];
    let follow = 0;
    let beforeDecimal = 0;
    let wrapped = false;

    if (segment.length) {
      const first = segment[0];
      const last = segment[segment.length - 1];
      const followStart = coords(first, 1);
      const followEnd = coords(last + 1, -1);

      wrapped = !sameLine(followStart, followEnd) || !sameLine(start, followStart);
      follow = wrapped ? 0 : Math.max(0, followEnd.left - followStart.left);
      beforeDecimal = follow;

      const dot = decimalIndex(texts[i + 1]);
      if (!wrapped && dot >= 0 && segment[dot] !== undefined) beforeDecimal = Math.max(0, coords(segment[dot], 1).left - followStart.left);
    }

    const x = start.left - originX + shift;
    const placement = placeTab(stops, intervalPx, { x, follow, beforeDecimal }, hanging);
    // Text pushed onto the next line by a tab that was too wide comes back first, then is placed.
    const width = wrapped && current > 1 && placement.align !== 'left' ? 0 : placement.width;

    placed.push({ pos: at, width, leader: placement.leader });
    shift += width - current;
  }

  return placed;
}

export function tabsPlugin(ctx: DocContext): Plugin<TabsState> {
  const stopsOf = tabStopsCache(ctx);
  const intervalPx = defaultTabInterval(ctx.pkg, ctx.docPath, ctx.rels) / 15;

  return new Plugin<TabsState>({
    key: tabsKey,
    state: {
      init: (_config, state) => ({
        decorations: DecorationSet.empty,
        dirty: hasTab(state.doc, 0, state.doc.content.size) ? [[0, state.doc.content.size]] : [],
        passes: 0,
      }),
      apply(tr, old) {
        const meta = tr.getMeta(tabsKey) as TabsMeta | undefined;
        let next = old;

        if (tr.docChanged) {
          const dirty: [number, number][] = old.dirty.map(([a, b]) => [tr.mapping.map(a, -1), tr.mapping.map(b, 1)]);

          tr.mapping.maps.forEach((map, index) => {
            map.forEach((_oldStart, _oldEnd, newStart, newEnd) => {
              const rest = tr.mapping.slice(index + 1);
              const range = widen(tr.doc, rest.map(newStart, -1), rest.map(newEnd, 1));
              if (range) dirty.push(range);
            });
          });

          next = { decorations: old.decorations.map(tr.mapping, tr.doc), dirty, passes: 0 };
        }

        return meta ? applyMeta(next, tr, meta) : next;
      },
    },
    props: {
      decorations: (state) => tabsKey.getState(state)?.decorations,
    },
    view(editorView) {
      let frame = 0;
      let stylesVersion = ctx.styles.version;

      const measure = () => {
        frame = 0;
        const view = editorView;
        if (view.isDestroyed || view.composing) return;
        if (!view.dom.isConnected || view.dom.getClientRects().length === 0) return;

        const state = tabsKey.getState(view.state);
        if (!state || !state.dirty.length) return;

        const doc = view.state.doc;
        const size = doc.content.size;
        const from = Math.max(0, Math.min(...state.dirty.map(([a]) => a)));
        const to = Math.min(size, Math.max(...state.dirty.map(([, b]) => b)));
        const pageEl = view.dom.closest<HTMLElement>('.page') ?? view.dom;
        const zoom = parseFloat(getComputedStyle(pageEl).zoom) || 1;
        const placed: Placed[] = [];
        let rangeFrom = from;
        let rangeTo = to;

        doc.nodesBetween(from, to, (node, pos) => {
          if (node.type !== schema.nodes.paragraph) return true;

          rangeFrom = Math.min(rangeFrom, pos);
          rangeTo = Math.max(rangeTo, pos + node.nodeSize);
          if (!node.textContent.includes('\t')) return false;

          const found = measureParagraph(view, node, pos, stopsOf(node), intervalPx, zoom);
          if (found) placed.push(...found);
          return false;
        });

        const old = state.decorations.find(rangeFrom, rangeTo);
        const oldWidth = new Map(old.map((d) => [d.from, (d.spec.tab as Placed).width]));
        const settled = placed.every((p) => Math.abs((oldWidth.get(p.pos) ?? -99) - p.width) < 0.5) && old.length === placed.length;
        const meta: TabsMeta = { placed, measured: [rangeFrom, rangeTo], settled };

        view.dispatch(view.state.tr.setMeta(tabsKey, meta).setMeta('addToHistory', false));
      };

      const schedule = () => {
        if (!frame) frame = requestAnimationFrame(measure);
      };

      const all = () => {
        if (!editorView.isDestroyed) editorView.dispatch(editorView.state.tr.setMeta(tabsKey, { all: true }).setMeta('addToHistory', false));
      };

      const resize = new ResizeObserver(() => schedule());
      resize.observe(editorView.dom);
      document.fonts?.addEventListener?.('loadingdone', all);
      schedule();

      return {
        update(view: EditorView, prev: EditorState) {
          if (ctx.styles.version !== stylesVersion) {
            stylesVersion = ctx.styles.version;
            if (hasTab(view.state.doc, 0, view.state.doc.content.size)) {
              requestAnimationFrame(all);
              return;
            }
          }

          const state = tabsKey.getState(view.state);
          if (state?.dirty.length && (view.state.doc !== prev.doc || state !== tabsKey.getState(prev))) schedule();
        },
        destroy() {
          if (frame) cancelAnimationFrame(frame);
          resize.disconnect();
          document.fonts?.removeEventListener?.('loadingdone', all);
        },
      };
    },
  });
}
