// Tracked changes: recording new edits as Word's `w:ins` and `w:del`, and accepting or rejecting
// them, the document's own ones included.
//
// Recording works on transactions, so typing, paste, find & replace and the writing assistant's
// accepted suggestions are all caught the same way. After a transaction while tracking is on, an
// appended one marks what it inserted as an insertion and puts back what it deleted, marked as a
// deletion. Text the same author inserted while tracking goes for good when deleted, as in Word.
// Paragraph breaks are not tracked: they split and join as usual.

import { Fragment, type Mark, type Node as PMNode, Slice } from 'prosemirror-model';
import { type EditorState, Plugin, PluginKey, TextSelection, type Transaction } from 'prosemirror-state';
import { ReplaceStep, type StepMap } from 'prosemirror-transform';
import type { DocContext } from '../docx/import';
import { escAttr } from '../docx/xml';
import { nextKey, schema } from '../editor/schema';
import { authorName, revisionDate } from './author';
import { editHidden } from './opaque';

const M = schema.marks;
const N = schema.nodes;

export type ChangeKind = 'ins' | 'del' | 'moveFrom' | 'moveTo';

export interface Change {
  kind: ChangeKind;
  from: number;
  to: number;
  mark: Mark;
  author: string;
  date: string;
  text: string;
}

interface TrackState {
  on: boolean;
}

export const trackKey = new PluginKey<TrackState>('track');

/** Set on a transaction tracking must leave alone: accepting and rejecting, loading. */
export const UNTRACKED = 'review-untracked';

const removes = (kind: string) => kind === 'del' || kind === 'moveFrom';

/** The author and date a track mark's opening tag names. */
export function signature(mark: Mark): { author: string; date: string; id: string } {
  const tag: string = mark.attrs.tag ?? '';
  const attr = (name: string) => {
    const v = new RegExp(`\\b${name}="([^"]*)"`).exec(tag)?.[1] ?? '';
    return v.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
  };
  return { author: attr('w:author'), date: attr('w:date'), id: attr('w:id') };
}

// New marks sit inside a link or content control (depth from the file counts from 0, outside in);
// a deletion sits inside an insertion of someone else's.
const INS_DEPTH = 50;
const DEL_DEPTH = 51;

let revisionId = 0;

/** A revision id no element in the document has. */
function newRevisionId(doc: PMNode): number {
  if (!revisionId) {
    let max = 0;
    doc.descendants((node) => {
      for (const mark of node.marks) if (mark.type === M.track) max = Math.max(max, Number(signature(mark).id) || 0);
      if (node.type === N.opaque) for (const m of (node.attrs.raw as string).matchAll(/\bw:id="(\d+)"/g)) max = Math.max(max, Number(m[1]));
    });
    revisionId = Math.max(max, 900000);
  }
  return ++revisionId;
}

function trackMark(kind: 'ins' | 'del', doc: PMNode, author: string, date: string): Mark {
  const tag = `<w:${kind} w:id="${newRevisionId(doc)}" w:author="${escAttr(author)}" w:date="${date}">`;
  return M.track.create({ kind, tag, depth: kind === 'ins' ? INS_DEPTH : DEL_DEPTH, k: nextKey() });
}

const ownMark = (marks: readonly Mark[], kind: string, author: string) =>
  marks.find((m) => m.type === M.track && m.attrs.kind === kind && signature(m).author === author) ?? null;

/** A mark of this kind by this author on either side of a stretch, to extend; otherwise a new one. */
function markFor(doc: PMNode, from: number, to: number, kind: 'ins' | 'del', author: string, date: string): Mark {
  const before = doc.resolve(from).nodeBefore;
  const after = doc.resolve(to).nodeAfter;
  return (before && ownMark(before.marks, kind, author)) ?? (after && ownMark(after.marks, kind, author)) ?? trackMark(kind, doc, author, date);
}

/** Deleted content, to put back: marked as deleted, minus what this author had inserted. */
function asDeleted(fragment: Fragment, mark: Mark, author: string): Fragment {
  const kids: PMNode[] = [];

  fragment.forEach((node) => {
    if (!node.isInline) {
      kids.push(node.copy(asDeleted(node.content, mark, author)));
    } else if (ownMark(node.marks, 'ins', author)) {
      // Inserted while tracking, by the same hand: gone for good.
    } else if (node.isText || node.type === N.hard_break || node.type === N.image) {
      kids.push(node.marks.some((m) => m.type === M.track && removes(m.attrs.kind)) ? node : node.mark(mark.addToSet(node.marks)));
    } else {
      kids.push(node);
    }
  });

  return Fragment.from(kids);
}

function hasInline(fragment: Fragment): boolean {
  let found = false;
  fragment.descendants((node) => {
    if (node.isInline) found = true;
    return !found;
  });
  return found;
}

/** Turns what the transactions did into tracked changes. */
export function trackTransactions(trs: readonly Transaction[], oldState: EditorState, newState: EditorState, author = authorName(), date = revisionDate()): Transaction | null {
  const maps: StepMap[] = [];
  const work: { step: ReplaceStep; before: PMNode; index: number; single: boolean }[] = [];
  const tracked = trs.filter((tr) => tr.docChanged && !skip(tr));
  const single = tracked.length === 1 && tracked[0].steps.length === 1;

  for (const tr of trs) {
    const take = tr.docChanged && !skip(tr);
    tr.steps.forEach((step, i) => {
      if (take && step instanceof ReplaceStep) work.push({ step, before: tr.docs[i], index: maps.length, single });
      maps.push(tr.mapping.maps[i]);
    });
  }

  if (!work.length) return null;

  const out = newState.tr;
  const through = (pos: number, assoc: number, from: number) => {
    for (let i = from; i < maps.length; i++) pos = maps[i].map(pos, assoc);
    return out.mapping.map(pos, assoc);
  };
  let cursor: number | null = null;

  for (const { step, before, index } of work) {
    const { from, to, slice } = step as unknown as { from: number; to: number; slice: Slice };
    const a = through(from, -1, index);
    let b = through(to, 1, index);
    if (b < a) b = a;

    // What went in: an insertion.
    if (slice.size && hasInline(slice.content) && b > a) {
      out.removeMark(a, b, M.track);
      out.addMark(a, b, markFor(out.doc, a, b, 'ins', author, date));
    }

    // What went out: back in, as a deletion.
    if (to > from) {
      const removed = before.slice(from, to);
      if (!hasInline(removed.content)) continue;

      const content = asDeleted(removed.content, markFor(out.doc, a, a, 'del', author, date), author);
      if (!hasInline(content)) continue;

      const put = new Slice(content, removed.openStart, removed.openEnd);
      const size = out.doc.content.size;
      out.replace(a, a, put);
      const added = out.doc.content.size - size;

      if (single && !slice.size) {
        // Backspace leaves the cursor before what it deleted; Delete, after.
        const sel = oldState.selection;
        cursor = sel.empty && sel.head === to ? a : a + added;
      }
    }
  }

  if (!out.docChanged) return null;

  if (cursor !== null) out.setSelection(TextSelection.create(out.doc, Math.min(cursor, out.doc.content.size)));
  return out.setMeta(UNTRACKED, true);
}

function skip(tr: Transaction): boolean {
  return Boolean(tr.getMeta(UNTRACKED) || tr.getMeta('history$') || tr.getMeta('addToHistory') === false || tr.getMeta('appendedTransaction'));
}

/** Records edits while switched on. Starts on when the document's settings ask for it. */
export function trackPlugin(ctx: DocContext): Plugin<TrackState> {
  const settingsRel = ctx.rels.find((r) => r.type.endsWith('/settings'));
  const settings = settingsRel ? (ctx.pkg.text(`${ctx.docPath.slice(0, ctx.docPath.lastIndexOf('/') + 1)}${settingsRel.target}`) ?? '') : '';
  const startOn = /<w:trackRevisions(?![^>]*w:val="(?:false|0|off)")[^>]*\/?>/.test(settings);

  return new Plugin<TrackState>({
    key: trackKey,
    state: {
      init: () => ({ on: startOn }),
      apply(tr, value) {
        const on = tr.getMeta(trackKey);
        return typeof on === 'boolean' ? { on } : value;
      },
    },
    appendTransaction(trs, oldState, newState) {
      if (!trackKey.getState(newState)?.on) return null;
      return trackTransactions(trs, oldState, newState);
    },
  });
}

export const isTracking = (state: EditorState): boolean => trackKey.getState(state)?.on ?? false;

export function setTracking(state: EditorState, on: boolean): Transaction {
  return state.tr.setMeta(trackKey, on).setMeta('addToHistory', false);
}

// ---- Finding, accepting, rejecting ---------------------------------------------------------------

/** The tracked changes, in the order of the text; neighbours with the same mark are one change. */
export function changesIn(doc: PMNode, from = 0, to = doc.content.size): Change[] {
  const changes: Change[] = [];
  const open = new Map<Mark, Change>();

  doc.nodesBetween(from, to, (node, pos) => {
    if (!node.isInline) return true;

    for (const mark of node.marks) {
      if (mark.type !== M.track) continue;

      let current: Change | undefined;
      for (const [m, c] of open) if (m.eq(mark) && c.to === pos) current = c;

      const text = node.isText ? (node.text ?? '') : node.type === N.hard_break ? '\n' : node.type === N.opaque ? '' : '￼';

      if (current) {
        current.to = pos + node.nodeSize;
        current.text += text;
      } else {
        const { author, date } = signature(mark);
        const change: Change = { kind: mark.attrs.kind, from: pos, to: pos + node.nodeSize, mark, author, date, text };
        changes.push(change);
        for (const [m] of open) if (m.eq(mark)) open.delete(m);
        open.set(mark, change);
      }
    }

    return false;
  });

  return changes;
}

/** Accepts (or rejects) these changes. */
export function resolveChanges(state: EditorState, changes: Change[], accept: boolean): Transaction {
  const tr = state.tr;

  for (const change of changes) {
    const from = tr.mapping.map(change.from, 1);
    const to = tr.mapping.map(change.to, -1);
    if (to <= from) continue;

    const goes = removes(change.kind) === accept;

    if (goes) {
      tr.delete(from, to);
    } else {
      tr.removeMark(from, to, change.mark);

      if (removes(change.kind)) {
        // Deleted field codes and the like, now kept: their deleted-text elements become ordinary ones.
        tr.doc.nodesBetween(from, to, (node, pos) => {
          if (node.type === N.opaque && /<w:del(?:Text|InstrText)\b/.test(node.attrs.raw)) {
            const raw = (node.attrs.raw as string).replace(/<(\/?)w:delText\b/g, '<$1w:t').replace(/<(\/?)w:delInstrText\b/g, '<$1w:instrText');
            tr.setNodeMarkup(pos, null, { ...node.attrs, raw }, node.marks);
          }
        });
      }
    }
  }

  // A move fully settled leaves its range markers with nothing to mark.
  if (!changesIn(tr.doc).some((c) => c.kind === 'moveFrom' || c.kind === 'moveTo')) {
    editHidden(tr, (raw) => (raw.includes('<w:move') ? raw.replace(/<w:move(?:From|To)Range(?:Start|End)\b[^>]*\/>/g, '') : raw));
  }

  return tr.setMeta(UNTRACKED, true);
}

/** The changes the selection touches, or the one at the cursor. */
export function changesAtSelection(state: EditorState): Change[] {
  const { from, to } = state.selection;
  const all = changesIn(state.doc);
  return from === to ? all.filter((c) => c.from <= from && c.to >= from).slice(0, 1) : all.filter((c) => c.to > from && c.from < to);
}

/** Selects the next (or previous) change after the selection; null when there is none. */
export function selectChange(state: EditorState, forward: boolean): Transaction | null {
  const all = changesIn(state.doc);
  const { from, to } = state.selection;
  const target = forward ? (all.find((c) => c.from >= to && !(c.from === from && c.to === to)) ?? all[0]) : ([...all].reverse().find((c) => c.to <= from && !(c.from === from && c.to === to)) ?? all[all.length - 1]);
  if (!target) return null;

  return state.tr.setSelection(TextSelection.create(state.doc, target.from, target.to)).scrollIntoView();
}
