// The document's outline: its headings, with their levels, as Word's navigation pane shows them.
// A paragraph is a heading when it has an outline level, set on it or by its style, or when its
// style is one of the built-in headings.

import type { Node as PMNode } from 'prosemirror-model';
import type { Styles } from '../docx/styles';
import { child } from '../docx/xml';

export interface Heading {
  /** 1 to 9. */
  level: number;
  text: string;
  /** Where the heading paragraph starts. */
  pos: number;
}

/** The outline level a paragraph style gives, 1 to 9, or null. */
export type StyleLevel = (styleId: string | null) => number | null;

const levelOfValue = (value: string | null | undefined): number | null => {
  const n = Number(value);
  // Level 9 (written as 9) is "body text": not a heading.
  return value !== null && value !== undefined && Number.isInteger(n) && n >= 0 && n <= 8 ? n + 1 : null;
};

/** What a style gives: an outline level set in it or in one it is based on, or its being a built-in heading. */
export function styleLevels(styles: Styles): StyleLevel {
  const cache = new Map<string, number | null>();

  return (id) => {
    const key = id ?? styles.defaultParagraph ?? '';
    if (cache.has(key)) return cache.get(key)!;

    let level: number | null = null;
    let set = false;

    for (const def of styles.chain(key)) {
      const lvl = child(def.pPr, 'w:outlineLvl');
      if (lvl) {
        level = levelOfValue(lvl.attrs['w:val']);
        set = true;
      }
    }

    if (!set) {
      const own = styles.byId.get(key);
      const name = /^heading ([1-9])$/i.exec(own?.name ?? '');
      if (name) level = Number(name[1]);
    }

    cache.set(key, level);
    return level;
  };
}

/** The outline level of a paragraph: its own, or its style's. */
export function headingLevel(paragraph: PMNode, styleLevel: StyleLevel | null): number | null {
  const own = /<w:outlineLvl\b[^>]*w:val="(\d+)"/.exec((paragraph.attrs.ppr as string | null) ?? '');
  if (own) return levelOfValue(own[1]);

  return styleLevel ? styleLevel((paragraph.attrs.styleId as string | null) ?? null) : null;
}

/** Every heading in the document, in order. Empty headings are left out. */
export function outline(doc: PMNode, styleLevel: StyleLevel | null): Heading[] {
  const headings: Heading[] = [];

  doc.descendants((node, pos) => {
    if (!node.isTextblock) return true;
    if (node.type.name !== 'paragraph') return false;

    const level = headingLevel(node, styleLevel);
    const text = level ? node.textContent.replace(/\s+/g, ' ').trim() : '';

    if (level && text) headings.push({ level, text, pos });
    return false;
  });

  return headings;
}

/** The index of the heading whose section a position is in, or -1 before the first heading. */
export function sectionAt(headings: readonly Heading[], pos: number): number {
  let found = -1;

  for (let i = 0; i < headings.length && headings[i].pos <= pos; i++) found = i;
  return found;
}
