// The equation editor: a line of linear text (LaTeX or Word's UnicodeMath) and the equation it
// makes, drawn as it is typed.

import { closePopover, h } from '../ui/dom';
import { mathHtml } from './node';
import { linearToOmml } from './parse';

export interface EquationInput {
  text: string;
  display: boolean;
  isNew: boolean;
  /** Parts of the equation have no linear form: say that changing it writes them as text. */
  lossy?: boolean;
}

export interface EquationResult {
  text: string;
  display: boolean;
}

/** Buttons that put a piece of linear text in at the cursor; `|` is where the cursor goes after. */
const PALETTE: [string, string, string][] = [
  ['a/b', '\\frac{|}{}', 'Fraction'],
  ['x²', '^{|}', 'Superscript'],
  ['xᵢ', '_{|}', 'Subscript'],
  ['√', '\\sqrt{|}', 'Square root'],
  ['ⁿ√', '\\sqrt[|]{}', 'Root'],
  ['∑', '\\sum_{|}^{}', 'Sum'],
  ['∫', '\\int_{|}^{}', 'Integral'],
  ['( )', '\\left(|\\right)', 'Brackets that grow'],
  ['lim', '\\lim_{|}', 'Limit'],
  ['x̂', '\\hat{|}', 'Accent'],
  ['[ ]', '\\begin{pmatrix}| & \\\\  & \\end{pmatrix}', 'Matrix'],
  ['α', '\\alpha', 'Greek letters: \\alpha, \\beta, … \\Omega'],
  ['≤', '\\le', 'Relations: \\le, \\ge, \\ne, \\approx, \\equiv'],
  ['→', '\\to', 'Arrows: \\to, \\Rightarrow, \\leftrightarrow'],
  ['∞', '\\infty', 'Infinity'],
];

/** Opens the editor; resolves with the new text, or null if it was cancelled. */
export function equationDialog(input: EquationInput): Promise<EquationResult | null> {
  return new Promise((resolve) => {
    const field = h('textarea', { class: 'math-input', spellcheck: 'false', rows: '3', 'aria-label': 'Equation as linear text' });
    field.value = input.text;
    const preview = h('div', { class: 'math-preview', 'aria-live': 'polite' });
    const problems = h('div', { class: 'math-error' });
    const display = h('input', { type: 'checkbox' });
    display.checked = input.display;

    const update = () => {
      const parsed = linearToOmml(field.value, { display: display.checked });
      const shown = h('span', { class: display.checked ? 'math-eq math-display' : 'math-eq' });
      shown.innerHTML = field.value.trim() ? mathHtml(parsed.xml) : '';
      preview.replaceChildren(shown);
      problems.textContent = parsed.problems.join('. ');
    };

    const insert = (snippet: string) => {
      const at = snippet.indexOf('|');
      const text = snippet.replace('|', '');
      const { selectionStart: s, selectionEnd: e, value } = field;
      field.value = value.slice(0, s) + text + value.slice(e);
      const caret = s + (at >= 0 ? at : text.length);
      field.focus();
      field.setSelectionRange(caret, caret);
      update();
    };

    const palette = h('div', { class: 'math-palette' }, ...PALETTE.map(([label, snippet, title]) => h('button', { class: 'button', title, type: 'button', onclick: () => insert(snippet) }, label)));

    const done = (result: EquationResult | null) => {
      document.removeEventListener('keydown', onKey, true);
      backdrop.remove();
      resolve(result);
    };

    const ok = () => done({ text: field.value.trim(), display: display.checked });

    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        done(null);
      } else if (event.key === 'Enter' && !event.shiftKey && event.target === field) {
        event.preventDefault();
        ok();
      }
    };

    field.addEventListener('input', update);
    display.addEventListener('change', update);

    const backdrop = h(
      'div',
      { class: 'dialog-backdrop' },
      h(
        'div',
        { class: 'dialog math-dialog', role: 'dialog', 'aria-label': 'Equation' },
        h('h2', null, input.isNew ? 'Insert equation' : 'Edit equation'),
        palette,
        field,
        h('div', { class: 'math-row' }, 'LaTeX or Word’s linear format: \\frac{a}{b}, x^2, x_i, \\sqrt{x}, \\sum_{i=1}^n, \\alpha, (a+b)/c. Shift+Enter for a new line.'),
        preview,
        problems,
        input.lossy ? h('p', { class: 'math-row' }, 'Parts of this equation have no linear form and are shown as text. Changing it writes them as plain text.') : null,
        h('label', { class: 'math-row' }, display, ' On a line of its own (display equation)'),
        h(
          'div',
          { class: 'buttons' },
          h('button', { class: 'button', onclick: () => done(null) }, 'Cancel'),
          h('button', { class: 'button primary', onclick: ok }, input.isNew ? 'Insert' : 'OK'),
        ),
      ),
    );

    closePopover();
    document.addEventListener('keydown', onKey, true);
    document.body.append(backdrop);
    update();
    field.focus();
    field.setSelectionRange(field.value.length, field.value.length);
  });
}
