// The sheet behind a chart: cells as they were typed, and what they work out to.
//
// A cell holds a number, some text, or a formula that starts with "=". Numbers are kept the way a
// program writes them (1234.5) whatever the keyboard's country; the chart editor turns what was
// typed into that form and back. Formulas are kept as typed and understood both ways round:
// =SUM(A1,B1) and =SUMME(A1;B1) are the same thing, and `excelFormula` gives the first of the two
// for the workbook that goes into the file.

export class CellError {
  constructor(readonly code: string) {}
}

export type Value = number | string | boolean | null | CellError;

const DIV0 = new CellError('#DIV/0!');
const VALUE = new CellError('#VALUE!');
const NAME = new CellError('#NAME?');
const REF = new CellError('#REF!');
const NUM = new CellError('#NUM!');
const CYCLE = new CellError('#CYCLE!');

/** German Excel's names for the functions below, and for true and false. */
const ALIASES: Record<string, string> = {
  SUMME: 'SUM', MITTELWERT: 'AVERAGE', ANZAHL: 'COUNT', ANZAHL2: 'COUNTA', PRODUKT: 'PRODUCT', RUNDEN: 'ROUND', AUFRUNDEN: 'ROUNDUP',
  ABRUNDEN: 'ROUNDDOWN', WURZEL: 'SQRT', GANZZAHL: 'INT', POTENZ: 'POWER', REST: 'MOD', WENN: 'IF', UND: 'AND', ODER: 'OR', NICHT: 'NOT',
  WAHR: 'TRUE', FALSCH: 'FALSE',
};

// ---- Cell names ----------------------------------------------------------------------------

/** 0 is A, 25 is Z, 26 is AA. */
export function colName(col: number): string {
  let name = '';

  for (let n = col + 1; n > 0; n = Math.floor((n - 1) / 26)) {
    name = String.fromCharCode(65 + ((n - 1) % 26)) + name;
  }

  return name;
}

function colIndex(name: string): number {
  let n = 0;

  for (const letter of name.toUpperCase()) n = n * 26 + (letter.charCodeAt(0) - 64);

  return n - 1;
}

export const cellName = (row: number, col: number): string => `${colName(col)}${row + 1}`;

/** "B3" as a row and a column, both counted from 0. Null for anything that is not a cell's name. */
export function parseCellName(name: string): { row: number; col: number } | null {
  const match = /^\$?([A-Za-z]{1,3})\$?(\d{1,7})$/.exec(name);
  if (!match || match[2] === '0') return null;

  return { row: Number(match[2]) - 1, col: colIndex(match[1]) };
}

// ---- Reading a formula ---------------------------------------------------------------------

interface Ref {
  row: number;
  col: number;
  /** As written, dollar signs and all. */
  text: string;
}

type Ast =
  | { k: 'num'; v: number }
  | { k: 'str'; v: string }
  | { k: 'bool'; v: boolean }
  | { k: 'ref'; ref: Ref }
  | { k: 'range'; from: Ref; to: Ref }
  | { k: 'un'; op: string; a: Ast }
  | { k: 'pct'; a: Ast }
  | { k: 'bin'; op: string; a: Ast; b: Ast }
  | { k: 'paren'; a: Ast }
  | { k: 'call'; name: string; args: Ast[] };

type Token =
  | { t: 'num'; v: number }
  | { t: 'str'; v: string }
  | { t: 'bool'; v: boolean }
  | { t: 'ref'; ref: Ref }
  | { t: 'fn'; v: string }
  | { t: 'op'; v: string }
  | { t: 'end' };

class FormulaError extends Error {
  constructor(readonly error: CellError) {
    super(error.code);
  }
}

/**
 * Splits a formula into tokens. A comma is a decimal comma wherever it cannot be anything else:
 * in a formula that separates its arguments with semicolons, and outside any function's brackets.
 */
function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  const semicolons = source.includes(';');
  /** For each open bracket, whether it is a function's. */
  const brackets: boolean[] = [];
  let i = 0;

  while (i < source.length) {
    const ch = source[i];

    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
      i++;
      continue;
    }

    if (ch === '"') {
      let text = '';
      i++;

      for (;;) {
        if (i >= source.length) throw new FormulaError(VALUE);

        if (source[i] === '"') {
          if (source[i + 1] !== '"') break;
          i++;
        }

        text += source[i++];
      }

      i++;
      tokens.push({ t: 'str', v: text });
      continue;
    }

    if ((ch >= '0' && ch <= '9') || (ch === '.' && source[i + 1] >= '0' && source[i + 1] <= '9')) {
      const commaIsDecimal = semicolons || !brackets.length || !brackets[brackets.length - 1];
      const match = (commaIsDecimal ? /^(\d+(?:[.,]\d+)?|\.\d+)(?:[eE][+-]?\d+)?/ : /^(\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?/).exec(source.slice(i))!;

      tokens.push({ t: 'num', v: Number(match[0].replace(',', '.')) });
      i += match[0].length;
      continue;
    }

    if (/[A-Za-z_$]/.test(ch)) {
      const word = /^[A-Za-z_$][A-Za-z0-9_.$]*/.exec(source.slice(i))![0];
      const calls = /^\s*\(/.test(source.slice(i + word.length));
      const cell = calls ? null : parseCellName(word);
      const upper = word.toUpperCase();
      const name = ALIASES[upper] ?? upper;

      i += word.length;

      if (cell) tokens.push({ t: 'ref', ref: { ...cell, text: upper } });
      else if (!calls && (name === 'TRUE' || name === 'FALSE')) tokens.push({ t: 'bool', v: name === 'TRUE' });
      else if (calls) tokens.push({ t: 'fn', v: name });
      else throw new FormulaError(NAME);

      continue;
    }

    const two = source.slice(i, i + 2);

    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ t: 'op', v: two });
      i += 2;
      continue;
    }

    if ('+-*/^&=<>(),;:%'.includes(ch)) {
      if (ch === '(') {
        brackets.push(tokens[tokens.length - 1]?.t === 'fn');
      } else if (ch === ')') {
        brackets.pop();
      }

      tokens.push({ t: 'op', v: ch === ';' ? ',' : ch });
      i++;
      continue;
    }

    // "#REF!" is what a deleted row or column leaves in a formula that pointed into it.
    throw new FormulaError(ch === '#' ? REF : NAME);
  }

  tokens.push({ t: 'end' });
  return tokens;
}

/** The usual order: comparison, then &, then + -, then * /, then ^, then a sign, then %. */
class Parser {
  private at = 0;

  constructor(private readonly tokens: Token[]) {}

  parse(): Ast {
    const ast = this.comparison();
    if (this.tokens[this.at].t !== 'end') throw new FormulaError(VALUE);

    return ast;
  }

  private op(...ops: string[]): string | null {
    const token = this.tokens[this.at];

    if (token.t === 'op' && ops.includes(token.v)) {
      this.at++;
      return token.v;
    }

    return null;
  }

  private binary(next: () => Ast, ...ops: string[]): Ast {
    let a = next();

    for (let op = this.op(...ops); op; op = this.op(...ops)) {
      a = { k: 'bin', op, a, b: next() };
    }

    return a;
  }

  private comparison = (): Ast => this.binary(this.concat, '=', '<>', '<', '>', '<=', '>=');
  private concat = (): Ast => this.binary(this.sum, '&');
  private sum = (): Ast => this.binary(this.product, '+', '-');
  private product = (): Ast => this.binary(this.power, '*', '/');
  private power = (): Ast => this.binary(this.unary, '^');

  private unary = (): Ast => {
    const op = this.op('-', '+');
    return op ? { k: 'un', op, a: this.unary() } : this.percent();
  };

  private percent(): Ast {
    let a = this.primary();

    while (this.op('%')) a = { k: 'pct', a };

    return a;
  }

  private primary(): Ast {
    const token = this.tokens[this.at++];

    switch (token.t) {
      case 'num':
        return { k: 'num', v: token.v };
      case 'str':
        return { k: 'str', v: token.v };
      case 'bool':
        return { k: 'bool', v: token.v };
      case 'ref': {
        if (!this.op(':')) return { k: 'ref', ref: token.ref };

        const to = this.tokens[this.at++];
        if (to.t !== 'ref') throw new FormulaError(VALUE);

        return { k: 'range', from: token.ref, to: to.ref };
      }
      case 'fn': {
        const args: Ast[] = [];

        this.at++;

        if (!this.op(')')) {
          do {
            args.push(this.comparison());
          } while (this.op(','));

          if (!this.op(')')) throw new FormulaError(VALUE);
        }

        return { k: 'call', name: token.v, args };
      }
      case 'op':
        if (token.v === '(') {
          const a = this.comparison();
          if (!this.op(')')) throw new FormulaError(VALUE);

          return { k: 'paren', a };
        }
    }

    throw new FormulaError(VALUE);
  }
}

const astCache = new Map<string, Ast | CellError>();

/** What a formula says, without its "=". An error if it cannot be read. */
function parseFormula(source: string): Ast | CellError {
  let ast = astCache.get(source);

  if (!ast) {
    try {
      ast = new Parser(tokenize(source)).parse();
    } catch (error) {
      ast = error instanceof FormulaError ? error.error : VALUE;
    }

    if (astCache.size > 2000) astCache.clear();
    astCache.set(source, ast);
  }

  return ast;
}

// ---- Working a sheet out -------------------------------------------------------------------

const isNumberText = (text: string): boolean => /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(text);

function toNumber(value: Value): number | CellError {
  if (typeof value === 'number') return value;
  if (value === null) return 0;
  if (typeof value === 'boolean') return value ? 1 : 0;
  if (value instanceof CellError) return value;

  return isNumberText(value.trim()) ? Number(value) : VALUE;
}

function toText(value: Value): string | CellError {
  if (value instanceof CellError) return value;
  if (value === null) return '';
  if (typeof value === 'boolean') return value ? 'TRUE' : 'FALSE';

  return String(value);
}

function toBool(value: Value): boolean | CellError {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'string') return /^true$/i.test(value) ? true : /^false$/i.test(value) ? false : VALUE;

  const n = toNumber(value);
  return n instanceof CellError ? n : n !== 0;
}

const finite = (n: number): number | CellError => (Number.isFinite(n) ? n : NUM);

function roundTo(n: number, digits: number, mode: 'round' | 'up' | 'down'): number {
  const f = 10 ** Math.trunc(digits);
  const scaled = Math.abs(n) * f;
  // The small push makes 1.005 round to 1.01, as it does on paper.
  const rounded = mode === 'round' ? Math.round(scaled + 1e-9) : mode === 'up' ? Math.ceil(scaled - 1e-9) : Math.floor(scaled + 1e-9);

  return (Math.sign(n) * rounded) / f;
}

function median(numbers: number[]): number | CellError {
  if (!numbers.length) return NUM;

  const sorted = [...numbers].sort((a, b) => a - b);
  const mid = sorted.length >> 1;

  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

/** Functions that take any number of numbers: from a range only its numbers count, as in Excel. */
const AGGREGATES: Record<string, (numbers: number[]) => number | CellError> = {
  SUM: (n) => n.reduce((a, b) => a + b, 0),
  PRODUCT: (n) => n.reduce((a, b) => a * b, 1),
  AVERAGE: (n) => (n.length ? n.reduce((a, b) => a + b, 0) / n.length : DIV0),
  MIN: (n) => (n.length ? Math.min(...n) : 0),
  MAX: (n) => (n.length ? Math.max(...n) : 0),
  COUNT: (n) => n.length,
  MEDIAN: median,
};

/** Functions of a fixed few numbers: [fewest arguments, most, what it works out]. */
const NUMERIC: Record<string, [number, number, (...n: number[]) => number | CellError]> = {
  ABS: [1, 1, Math.abs],
  SQRT: [1, 1, (n) => (n < 0 ? NUM : Math.sqrt(n))],
  INT: [1, 1, Math.floor],
  ROUND: [1, 2, (n, digits = 0) => roundTo(n, digits, 'round')],
  ROUNDUP: [1, 2, (n, digits = 0) => roundTo(n, digits, 'up')],
  ROUNDDOWN: [1, 2, (n, digits = 0) => roundTo(n, digits, 'down')],
  POWER: [2, 2, (a, b) => finite(a ** b)],
  MOD: [2, 2, (a, b) => (b === 0 ? DIV0 : a - b * Math.floor(a / b))],
  PI: [0, 0, () => Math.PI],
};

class Sheet {
  private readonly values = new Map<number, Value>();
  private readonly busy = new Set<number>();

  constructor(private readonly cells: readonly (readonly string[])[]) {}

  /** What the cell works out to. A cell outside the sheet is empty. */
  value(row: number, col: number): Value {
    const text = this.cells[row]?.[col] ?? '';
    if (text === '') return null;
    if (text[0] !== '=' || text.length === 1) return isNumberText(text) ? Number(text) : text;

    const key = row * 20000 + col;
    const known = this.values.get(key);
    if (known !== undefined) return known;
    if (this.busy.has(key)) return CYCLE;

    this.busy.add(key);

    const ast = parseFormula(text.slice(1));
    const value = ast instanceof CellError ? ast : this.scalar(ast);

    this.busy.delete(key);
    this.values.set(key, value);

    return value;
  }

  private scalar(ast: Ast): Value {
    switch (ast.k) {
      case 'num':
      case 'str':
      case 'bool':
        return ast.v;
      case 'ref':
        return this.value(ast.ref.row, ast.ref.col);
      case 'range':
        return VALUE;
      case 'paren':
        return this.scalar(ast.a);
      case 'pct': {
        const n = toNumber(this.scalar(ast.a));
        return n instanceof CellError ? n : n / 100;
      }
      case 'un': {
        const n = toNumber(this.scalar(ast.a));
        return n instanceof CellError ? n : ast.op === '-' ? -n : n;
      }
      case 'bin':
        return this.binary(ast.op, this.scalar(ast.a), this.scalar(ast.b));
      case 'call':
        return this.call(ast.name, ast.args);
    }
  }

  private binary(op: string, a: Value, b: Value): Value {
    if (a instanceof CellError) return a;
    if (b instanceof CellError) return b;

    if (op === '&') return `${toText(a)}${toText(b)}`;

    if ('+-*/^'.includes(op)) {
      const x = toNumber(a);
      const y = toNumber(b);

      if (x instanceof CellError) return x;
      if (y instanceof CellError) return y;

      switch (op) {
        case '+':
          return x + y;
        case '-':
          return x - y;
        case '*':
          return x * y;
        case '/':
          return y === 0 ? DIV0 : x / y;
        default:
          return finite(x ** y);
      }
    }

    // A comparison: numbers by size, anything else as text without regard to case.
    const textual = typeof a === 'string' || typeof b === 'string';
    const x = textual ? (toText(a) as string).toLowerCase() : (toNumber(a) as number);
    const y = textual ? (toText(b) as string).toLowerCase() : (toNumber(b) as number);

    switch (op) {
      case '=':
        return x === y;
      case '<>':
        return x !== y;
      case '<':
        return x < y;
      case '>':
        return x > y;
      case '<=':
        return x <= y;
      default:
        return x >= y;
    }
  }

  /** Every value an argument stands for: a range's cells, or the one value of anything else. */
  private spread(ast: Ast): { values: Value[]; fromCells: boolean } {
    if (ast.k === 'ref') return { values: [this.value(ast.ref.row, ast.ref.col)], fromCells: true };
    if (ast.k !== 'range') return { values: [this.scalar(ast)], fromCells: false };

    const values: Value[] = [];
    const top = Math.min(ast.from.row, ast.to.row);
    const left = Math.min(ast.from.col, ast.to.col);
    // Nothing is to be found past the sheet's edge, however far the range goes.
    const bottom = Math.min(Math.max(ast.from.row, ast.to.row), this.cells.length - 1);
    const right = Math.max(ast.from.col, ast.to.col);

    for (let row = top; row <= bottom; row++) {
      for (let col = left; col <= Math.min(right, (this.cells[row]?.length ?? 0) - 1); col++) {
        values.push(this.value(row, col));
      }
    }

    return { values, fromCells: true };
  }

  private call(name: string, args: Ast[]): Value {
    if (name === 'IF') {
      if (args.length < 2 || args.length > 3) return VALUE;

      const test = toBool(this.scalar(args[0]));
      if (test instanceof CellError) return test;

      return test ? this.scalar(args[1]) : args[2] ? this.scalar(args[2]) : false;
    }

    if (name === 'AND' || name === 'OR' || name === 'NOT') {
      const flags: boolean[] = [];

      for (const arg of args) {
        for (const value of this.spread(arg).values) {
          if (value === null) continue;

          const flag = toBool(value);
          if (flag instanceof CellError) return flag;

          flags.push(flag);
        }
      }

      if (name === 'NOT') return flags.length === 1 ? !flags[0] : VALUE;
      if (!flags.length) return VALUE;

      return name === 'AND' ? flags.every(Boolean) : flags.some(Boolean);
    }

    if (name === 'COUNTA') {
      return args.reduce((count, arg) => count + this.spread(arg).values.filter((value) => value !== null).length, 0);
    }

    const aggregate = AGGREGATES[name];

    if (aggregate) {
      const numbers: number[] = [];

      for (const arg of args) {
        const { values, fromCells } = this.spread(arg);

        for (const value of values) {
          if (value instanceof CellError) return value;

          if (typeof value === 'number') {
            numbers.push(value);
          } else if (!fromCells) {
            // Typed straight into the formula, "3" and TRUE count; in a cell they are skipped.
            const n = toNumber(value);
            if (n instanceof CellError) return name === 'COUNT' ? numbers.length : n;

            numbers.push(n);
          }
        }
      }

      return aggregate(numbers);
    }

    const numeric = NUMERIC[name];

    if (numeric) {
      const [fewest, most, work] = numeric;
      const numbers: number[] = [];

      if (args.length < fewest || args.length > most) return VALUE;

      for (const arg of args) {
        const n = toNumber(this.scalar(arg));
        if (n instanceof CellError) return n;

        numbers.push(n);
      }

      return work(...numbers);
    }

    return NAME;
  }
}

/** Every cell's value, row by row. */
export function evaluateSheet(cells: readonly (readonly string[])[]): Value[][] {
  const sheet = new Sheet(cells);

  return cells.map((row, r) => row.map((_cell, c) => sheet.value(r, c)));
}

// ---- A formula for Excel -------------------------------------------------------------------

function excel(ast: Ast): string {
  switch (ast.k) {
    case 'num':
      return String(ast.v);
    case 'str':
      return `"${ast.v.replace(/"/g, '""')}"`;
    case 'bool':
      return ast.v ? 'TRUE' : 'FALSE';
    case 'ref':
      return ast.ref.text;
    case 'range':
      return `${ast.from.text}:${ast.to.text}`;
    case 'un':
      return `${ast.op}${excel(ast.a)}`;
    case 'pct':
      return `${excel(ast.a)}%`;
    case 'bin':
      return `${excel(ast.a)}${ast.op}${excel(ast.b)}`;
    case 'paren':
      return `(${excel(ast.a)})`;
    case 'call':
      return `${ast.name}(${ast.args.map(excel).join(',')})`;
  }
}

/**
 * A cell's formula as a workbook holds it: English names, commas between arguments, no "=".
 * Null for a formula that cannot be read, which then goes into the workbook as its result alone.
 */
export function excelFormula(cell: string): string | null {
  if (cell[0] !== '=' || cell.length === 1) return null;

  const ast = parseFormula(cell.slice(1));
  return ast instanceof CellError ? null : excel(ast);
}

// ---- Rows and columns that come and go -----------------------------------------------------

const REFERENCE = /(?<![A-Za-z0-9_.$])(\$?)([A-Za-z]{1,3})(\$?)(\d{1,7})(?::(\$?)([A-Za-z]{1,3})(\$?)(\d{1,7}))?(?![A-Za-z0-9_.(])/g;

/**
 * A formula after a row or column was put in at `at` (delta 1) or taken out there (delta -1):
 * what it points at moves with the cells. A cell that is gone leaves #REF! behind; a range that
 * loses an end shrinks.
 */
export function shiftFormula(cell: string, axis: 'row' | 'col', at: number, delta: 1 | -1): string {
  if (cell[0] !== '=') return cell;

  const index = (letters: string, digits: string) => (axis === 'row' ? Number(digits) - 1 : colIndex(letters));
  const write = (dollarCol: string, letters: string, dollarRow: string, digits: string, to: number) =>
    axis === 'row' ? `${dollarCol}${letters}${dollarRow}${to + 1}` : `${dollarCol}${colName(to)}${dollarRow}${digits}`;

  // Text in quotes is left alone: it is not the formula's to change.
  return cell
    .split(/("(?:[^"]|"")*")/)
    .map((part, i) => {
      if (i % 2) return part;

      return part.replace(REFERENCE, (_whole, d1: string, l1: string, d2: string, n1: string, d3?: string, l2?: string, d4?: string, n2?: string) => {
        const from = index(l1, n1);

        if (l2 === undefined || n2 === undefined) {
          if (delta < 0 && from === at) return REF.code;
          return write(d1, l1, d2, n1, from >= at ? from + delta : from);
        }

        const to = index(l2, n2);
        const low = Math.min(from, to);
        const high = Math.max(from, to);
        const newLow = delta > 0 ? (low >= at ? low + 1 : low) : low > at ? low - 1 : low;
        const newHigh = delta > 0 ? (high >= at ? high + 1 : high) : high >= at ? high - 1 : high;

        if (newHigh < newLow) return REF.code;

        const [first, second] = from <= to ? [newLow, newHigh] : [newHigh, newLow];
        return `${write(d1, l1, d2, n1, first)}:${write(d3 ?? '', l2, d4 ?? '', n2, second)}`;
      });
    })
    .join('');
}
