// The style editor's commands: a change to a style is a change to the document's `styleEdits`
// attribute, so it is one step to undo, and `Styles.useEdits` shows it on the page.

import type { Command, EditorState, Transaction } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { type StyleChange, type StyleLook, diffLook, lookOf, newStyleXml, readInto, restyle, styleXml } from '../docx/styleedit';
import type { StyleEdits, Styles } from '../docx/styles';
import { parseFragment, parseXml, val } from '../docx/xml';
import { markAt, selectedParagraphs } from './commands';
import { schema } from './schema';

const M = schema.marks;

export const editsOf = (state: EditorState): StyleEdits => (state.doc.attrs.styleEdits as StyleEdits | null) ?? {};

/** The style's id that `basedOn` would have after `change`, as the file has it now otherwise. */
function basedOnAfter(styles: Styles, id: string, change: StyleChange): string | null {
  if (change.basedOn !== undefined) return change.basedOn;
  return styles.byId.get(id)?.basedOn ?? null;
}

/** What a style looks like with nothing of its own: its base's look. */
export function inheritedLook(styles: Styles, id: string, change: StyleChange = {}): StyleLook {
  const type = styles.byId.get(id)?.type === 'character' ? 'character' : 'paragraph';
  return lookOf(styles, basedOnAfter(styles, id, change), type);
}

/** The style's XML with `change` made, or null for a style the document does not have. */
export function restyled(styles: Styles, id: string, change: StyleChange): string | null {
  const xml = styleXml(styles, id);
  return xml === null ? null : restyle(xml, change, inheritedLook(styles, id, change));
}

/** Changes a style: one step, undone as one. */
export function changeStyle(ctx: DocContext, id: string, change: StyleChange): Command {
  return (state, dispatch) => {
    const xml = restyled(ctx.styles, id, change);
    if (xml === null) return false;
    if (xml === styleXml(ctx.styles, id)) return true;

    dispatch?.(state.tr.setDocAttribute('styleEdits', { ...editsOf(state), [id]: xml }).scrollIntoView());
    return true;
  };
}

/** Puts a style's whole XML in place, as the style editor made it: one step. */
export function setStyleXml(id: string, xml: string): Command {
  return (state, dispatch) => {
    if (editsOf(state)[id] === xml) return true;
    dispatch?.(state.tr.setDocAttribute('styleEdits', { ...editsOf(state), [id]: xml }));
    return true;
  };
}

/** A new style: its XML, given a free id, a name and what it looks like. */
export function newStyle(ctx: DocContext, name: string, type: 'paragraph' | 'character', basedOn: string | null, look: StyleLook, follow?: string | null): { id: string; xml: string } {
  const styles = ctx.styles;
  const id = styles.idFor(name);
  const next = type === 'paragraph' ? (follow === undefined ? id : follow) : null;
  const inherited = lookOf(styles, basedOn, type);
  const xml = restyle(newStyleXml(id, name, type, basedOn, next), { look: diffLook(inherited, look) }, inherited);

  return { id, xml };
}

/**
 * Adds a new style and gives the paragraphs in the selection that style (a paragraph style), in
 * one step. Answers the new style's id.
 */
export function addStyle(ctx: DocContext, state: EditorState, dispatch: (tr: Transaction) => void, style: { id: string; xml: string }, apply: boolean): string {
  const tr = state.tr.setDocAttribute('styleEdits', { ...editsOf(state), [style.id]: style.xml });

  if (apply && parseXml(style.xml).attrs['w:type'] !== 'character') {
    for (const { node, pos } of selectedParagraphs(state)) tr.setNodeMarkup(pos, null, { ...node.attrs, styleId: style.id });
  }

  dispatch(tr.scrollIntoView());
  return style.id;
}

/** The paragraph style the cursor's paragraph has, the default one when it names none. */
export function paragraphStyleAt(ctx: DocContext, state: EditorState): string | null {
  const paragraph = selectedParagraphs(state)[0]?.node ?? null;
  return (paragraph?.attrs.styleId as string | null) ?? ctx.styles.defaultParagraph;
}

/**
 * What the text at the cursor looks like: its paragraph style, with the paragraph's own
 * formatting and the formatting on the text laid over it.
 */
export function lookAtSelection(ctx: DocContext, state: EditorState): StyleLook {
  const paragraph = selectedParagraphs(state)[0]?.node ?? null;
  const look = lookOf(ctx.styles, paragraphStyleAt(ctx, state));

  if (paragraph) {
    readInto(look, parseFragment(paragraph.attrs.ppr), null, ctx.styles.theme);

    const align = paragraph.attrs.align as string | null;
    if (align) readInto(look, parseXml(`<w:pPr><w:jc w:val="${align}"/></w:pPr>`), null, ctx.styles.theme);
  }

  const font = markAt(state, M.fontFamily)?.attrs.name as string | undefined;
  const size = markAt(state, M.fontSize)?.attrs.size as number | undefined;
  const color = markAt(state, M.color)?.attrs.value as string | undefined;
  const bold = markAt(state, M.bold);
  const italic = markAt(state, M.italic);
  const underline = markAt(state, M.underline);

  if (font) look.font = font;
  if (size) look.size = size / 2;
  if (color) look.color = color === 'auto' ? 'auto' : color.replace('#', '').toUpperCase();
  if (bold) look.bold = bold.attrs.on !== false;
  if (italic) look.italic = italic.attrs.on !== false;
  if (underline) look.underline = underline.attrs.kind !== 'none';

  return look;
}

/** "Update style to match selection": the cursor paragraph's style takes on how its text looks. */
export function updateStyleToMatch(ctx: DocContext): Command {
  return (state, dispatch) => {
    const id = paragraphStyleAt(ctx, state);
    if (!id || !ctx.styles.byId.has(id)) return false;

    const change = diffLook(lookOf(ctx.styles, id), lookAtSelection(ctx, state));
    return changeStyle(ctx, id, { look: change })(state, dispatch);
  };
}

/** A style's based-on and next style, as its XML has them. */
export function linksOf(styles: Styles, id: string): { basedOn: string | null; next: string | null } {
  const xml = styleXml(styles, id);
  const el = xml ? parseXml(xml) : null;
  return { basedOn: val(el, 'w:basedOn'), next: val(el, 'w:next') };
}
