// What the toolbar and the keyboard do to a document.
//
// Commands that need to know about the document's styles or lists take its context. Changes to
// those (a new list, a style added on first use) happen on the context, outside the undo
// history: undoing leaves an unused list or style in the file, which costs nothing.

import type { Attrs, Mark, MarkType, Node as PMNode } from 'prosemirror-model';
import { type Command, type EditorState, NodeSelection, TextSelection, type Transaction } from 'prosemirror-state';
import { CellSelection, addRowAfter, goToNextCell, isInTable } from 'prosemirror-tables';
import type { DocContext } from '../docx/import';
import type { ListKind } from '../docx/numbering';
import { parseFragment } from '../docx/xml';
import { listKey, listOf } from './lists';
import { FORMATTING, nextKey, schema } from './schema';

const N = schema.nodes;
const M = schema.marks;

const INDENT_STEP = 720;

interface Found {
  node: PMNode;
  pos: number;
}

/** The paragraphs the selection touches, each once, in document order. */
export function selectedParagraphs(state: EditorState): Found[] {
  const found: Found[] = [];
  const seen = new Set<number>();

  for (const range of state.selection.ranges) {
    state.doc.nodesBetween(range.$from.pos, range.$to.pos, (node, pos) => {
      if (node.type !== N.paragraph) return true;

      if (!seen.has(pos)) {
        seen.add(pos);
        found.push({ node, pos });
      }

      return false;
    });
  }

  return found;
}

/** Changes the attributes of every selected paragraph; `change` returns null to leave one alone. */
export function updateParagraphs(change: (attrs: Attrs, node: PMNode) => Attrs | null, lists = false): Command {
  return (state, dispatch) => {
    const tr = state.tr;
    let changed = false;

    for (const { node, pos } of selectedParagraphs(state)) {
      const next = change(node.attrs, node);

      if (next) {
        tr.setNodeMarkup(pos, null, next);
        changed = true;
      }
    }

    if (!changed) return false;
    if (lists) tr.setMeta(listKey, true);
    if (dispatch) dispatch(tr.scrollIntoView());

    return true;
  };
}

// ---- Character formatting --------------------------------------------------------------------

/** Sets a mark over the selection, or with null attributes takes it off. With no selection, for what is typed next. */
export function setMark(type: MarkType, attrs: Attrs | null): Command {
  return (state, dispatch) => {
    const { empty, ranges } = state.selection;
    const tr = state.tr;

    if (empty) {
      if (attrs) tr.addStoredMark(type.create(attrs));
      else tr.removeStoredMark(type);
    } else {
      for (const { $from, $to } of ranges) {
        if (attrs) tr.addMark($from.pos, $to.pos, type.create(attrs));
        else tr.removeMark($from.pos, $to.pos, type);
      }
    }

    if (dispatch) dispatch(tr.scrollIntoView());
    return true;
  };
}

/** The mark of this type at the cursor, or on the first text of the selection. */
export function markAt(state: EditorState, type: MarkType): Mark | null {
  const { empty, $from, from, to } = state.selection;

  if (empty) {
    return type.isInSet(state.storedMarks ?? $from.marks()) ?? null;
  }

  let found: Mark | null = null;
  let looked = false;

  state.doc.nodesBetween(from, to, (node) => {
    if (looked) return false;

    if (node.isInline) {
      looked = true;
      found = type.isInSet(node.marks) ?? null;
    }

    return !looked;
  });

  return found;
}

export const clearFormatting: Command = (state, dispatch) => {
  const { empty, ranges } = state.selection;
  const tr = state.tr;

  if (empty) {
    tr.setStoredMarks((state.storedMarks ?? state.selection.$from.marks()).filter((mark) => !FORMATTING.includes(mark.type.name)));
  } else {
    for (const { $from, $to } of ranges) {
      for (const name of FORMATTING) tr.removeMark($from.pos, $to.pos, M[name]);
    }
  }

  if (dispatch) dispatch(tr);
  return true;
};

// ---- Paragraph formatting --------------------------------------------------------------------

/** Applies a paragraph style: a style id, or `builtin:<name>` for one that is added on first use. */
export function applyStyle(ctx: DocContext, value: string): Command {
  return (state, dispatch) => {
    if (!dispatch) return true;

    const id = value.startsWith('builtin:') ? ctx.styles.ensureBuiltin(value.slice(8)) : value;
    if (!id) return false;

    // The default style is written as no style at all, as Word does.
    const styleId = id === ctx.styles.defaultParagraph ? null : id;

    return updateParagraphs((attrs) => (attrs.styleId === styleId ? null : { ...attrs, styleId }), true)(state, dispatch);
  };
}

export function setAlign(align: string): Command {
  return updateParagraphs((attrs) => (attrs.align === align ? null : { ...attrs, align }));
}

/** A paragraph's own left indent in twips: set in the editor, or in the file, or none. */
function leftIndent(attrs: Attrs): number {
  if (attrs.indent !== null) return attrs.indent;

  const ind = parseFragment(attrs.ppr)?.children.find((el) => el.name === 'w:ind');
  const left = Number(ind?.attrs['w:left'] ?? ind?.attrs['w:start'] ?? 0);

  return Number.isFinite(left) ? left : 0;
}

/** One level deeper or shallower for list items; half an inch more or less for other paragraphs. */
export function indent(ctx: DocContext, direction: 1 | -1): Command {
  return (state, dispatch) => {
    if (selectedParagraphs(state).some(({ node }) => listOf(node, ctx))) {
      return changeLevel(ctx, direction)(state, dispatch);
    }

    return updateParagraphs((attrs) => {
      const now = leftIndent(attrs);
      const next = Math.max(0, now + direction * INDENT_STEP);

      return next === now ? null : { ...attrs, indent: next };
    })(state, dispatch);
  };
}

// ---- Lists -----------------------------------------------------------------------------------

function changeLevel(ctx: DocContext, direction: 1 | -1): Command {
  return updateParagraphs((attrs, node) => {
    const place = listOf(node, ctx);
    if (!place) return null;

    const ilvl = Math.max(0, Math.min(8, place.ilvl + direction));

    return ilvl === place.ilvl ? null : { ...attrs, numId: place.numId, ilvl };
  }, true);
}

/** The attributes of a paragraph taken out of its list. */
function outOfList(ctx: DocContext, attrs: Attrs): Attrs {
  const listStyle = ctx.styles.byName('List Paragraph');
  const styleId = listStyle && attrs.styleId === listStyle.id ? null : attrs.styleId;

  // A list that comes with the style has to be switched off; one set here is simply removed.
  return { ...attrs, styleId, numId: ctx.styles.numPrOf(styleId) ? 0 : null, ilvl: 0 };
}

/** A list of this kind right before or after the selected paragraphs, to carry on instead of starting anew. */
export function neighbouringList(state: EditorState, ctx: DocContext, paragraphs: Found[], kind: ListKind): number | null {
  const sameKind = (node: PMNode | null | undefined) => {
    const place = node?.type === N.paragraph ? listOf(node, ctx) : null;
    return place && ctx.numbering.kindOf(place.numId, place.ilvl) === kind ? place.numId : null;
  };

  const first = state.doc.resolve(paragraphs[0].pos);
  const last = state.doc.resolve(paragraphs[paragraphs.length - 1].pos);

  return sameKind(first.nodeBefore) ?? sameKind(last.parent.maybeChild(last.index() + 1));
}

/** Turns the selected paragraphs into a bulleted or numbered list, or back if they all are one already. */
export function toggleList(ctx: DocContext, kind: ListKind): Command {
  return (state, dispatch) => {
    const paragraphs = selectedParagraphs(state);
    if (!paragraphs.length) return false;
    if (!dispatch) return true;

    const places = paragraphs.map(({ node }) => listOf(node, ctx));
    const allThisKind = places.every((place) => place && ctx.numbering.kindOf(place.numId, place.ilvl) === kind);
    const tr = state.tr;

    if (allThisKind) {
      for (const { node, pos } of paragraphs) tr.setNodeMarkup(pos, null, outOfList(ctx, node.attrs));
    } else {
      const numId = neighbouringList(state, ctx, paragraphs, kind) ?? ctx.numbering.createList(kind);
      const listStyle = ctx.styles.byName('List Paragraph');

      paragraphs.forEach(({ node, pos }, i) => {
        const plain = !node.attrs.styleId || node.attrs.styleId === ctx.styles.defaultParagraph;

        tr.setNodeMarkup(pos, null, {
          ...node.attrs,
          numId,
          ilvl: places[i]?.ilvl ?? 0,
          styleId: listStyle && plain ? listStyle.id : node.attrs.styleId,
        });
      });
    }

    dispatch(tr.setMeta(listKey, true).scrollIntoView());
    return true;
  };
}

// ---- Keys ------------------------------------------------------------------------------------

/** Splits a paragraph at a position. A section break stays with the paragraph mark, on the second half. */
function splitKeepingSection(tr: Transaction, pos: number, second?: Attrs): void {
  const $pos = tr.doc.resolve(pos);
  const attrs = $pos.parent.attrs;

  tr.split(pos, 1, [{ type: N.paragraph, attrs: second ?? attrs }]);

  if (attrs.sectPr) {
    tr.setNodeMarkup($pos.before(), null, { ...attrs, sectPr: null });
  }
}

/** Enter. */
export function splitParagraph(ctx: DocContext): Command {
  return (state, dispatch) => {
    const selection = state.selection;

    if (selection instanceof CellSelection || (selection instanceof NodeSelection && selection.node.isBlock)) return false;
    if (selection.$from.parent.type !== N.paragraph) return false;

    const node = selection.$from.parent;
    const place = listOf(node, ctx);

    // Enter on an empty list item steps out of the list, a level at a time.
    if (selection.empty && node.content.size === 0 && place) {
      if (dispatch) {
        const attrs = place.ilvl > 0 ? { ...node.attrs, numId: place.numId, ilvl: place.ilvl - 1 } : outOfList(ctx, node.attrs);
        dispatch(state.tr.setNodeMarkup(selection.$from.before(), null, attrs).setMeta(listKey, true));
      }

      return true;
    }

    if (!dispatch) return true;

    const tr = state.tr;
    if (!selection.empty) tr.deleteSelection();

    const $pos = tr.selection.$from;
    const paragraph = $pos.parent;

    if (paragraph.type !== N.paragraph) return false;

    const attrs = paragraph.attrs;
    const atEnd = $pos.parentOffset === paragraph.content.size;
    // After a heading comes body text: the style says which style follows it.
    const next = atEnd && paragraph.content.size > 0 ? ctx.styles.nextOf(attrs.styleId) : null;
    const follows = next !== null && next !== attrs.styleId;
    const marks = state.storedMarks ?? $pos.marks();

    splitKeepingSection(tr, $pos.pos, follows ? { styleId: next === ctx.styles.defaultParagraph ? null : next, sectPr: attrs.sectPr } : undefined);

    // Carry on in the same formatting, unless the new paragraph is in another style.
    if (!follows && marks.length) tr.ensureMarks(marks);

    dispatch(tr.scrollIntoView());
    return true;
  };
}

/** Backspace at the start of a paragraph takes it out of its list, then takes away its indent, before joining. */
export function backspaceAtStart(ctx: DocContext): Command {
  return (state, dispatch) => {
    const { empty, $from } = state.selection;

    if (!empty || $from.parentOffset !== 0 || $from.parent.type !== N.paragraph) return false;

    const node = $from.parent;
    const left = leftIndent(node.attrs);
    let attrs: Attrs;

    if (listOf(node, ctx)) attrs = outOfList(ctx, node.attrs);
    else if (left > 0) attrs = { ...node.attrs, indent: Math.max(0, left - INDENT_STEP) };
    else return false;

    if (dispatch) dispatch(state.tr.setNodeMarkup($from.before(), null, attrs).setMeta(listKey, true));
    return true;
  };
}

/** Tab and Shift+Tab: the next cell in a table, a list level at the start of an item, a tab otherwise. */
export function tab(ctx: DocContext, direction: 1 | -1): Command {
  return (state, dispatch, view) => {
    if (isInTable(state)) {
      if (goToNextCell(direction)(state, dispatch)) return true;

      // Tab in the last cell makes a new row, as in Word.
      if (direction === 1 && dispatch && view) {
        addRowAfter(state, dispatch);
        goToNextCell(1)(view.state, view.dispatch);
      }

      return true;
    }

    const { empty, $from, $to } = state.selection;
    const several = !empty && !$from.sameParent($to);

    if (several || ($from.parentOffset === 0 && listOf($from.parent, ctx))) {
      return indent(ctx, direction)(state, dispatch) || true;
    }

    if (direction === 1 && dispatch) {
      dispatch(state.tr.insertText('\t').scrollIntoView());
    }

    return true;
  };
}

// ---- Inserting things ------------------------------------------------------------------------

export const insertPageBreak: Command = (state, dispatch) => {
  const { $from } = state.selection;

  // Word has no page breaks inside tables.
  if ($from.parent.type !== N.paragraph || isInTable(state)) return false;

  if (dispatch) {
    const tr = state.tr.replaceSelectionWith(N.page_break.create(), false);

    splitKeepingSection(tr, tr.selection.from);
    dispatch(tr.scrollIntoView());
  }

  return true;
};

export const insertLineBreak: Command = (state, dispatch) => {
  if (!state.selection.$from.parent.isTextblock) return false;
  if (dispatch) dispatch(state.tr.replaceSelectionWith(N.hard_break.create(), true).scrollIntoView());
  return true;
};

export function insertImage(src: string, w: number, h: number, alt = ''): Command {
  return (state, dispatch) => {
    if (dispatch) dispatch(state.tr.replaceSelectionWith(N.image.create({ src, w, h, alt }), false).scrollIntoView());
    return true;
  };
}

/** The chart node that is selected, and where it is; null if the selection is anything else. */
export function selectedChart(state: EditorState): Found | null {
  const { selection } = state;

  return selection instanceof NodeSelection && selection.node.type === N.chart ? { node: selection.node, pos: selection.from } : null;
}

/** The text of the table the cursor is in, row by row; null outside a table. */
export function tableAtCursor(state: EditorState): string[][] | null {
  const { $from } = state.selection;

  for (let depth = $from.depth; depth > 0; depth--) {
    const table = $from.node(depth);
    if (table.type !== N.table) continue;

    const rows: string[][] = [];

    table.forEach((row) => {
      const cells: string[] = [];

      row.forEach((cell) => cells.push(cell.textBetween(0, cell.content.size, ' ').trim()));
      rows.push(cells);
    });

    return rows;
  }

  return null;
}

/**
 * Puts a chart into the document: at the selection, or with `afterTable` in a paragraph of its
 * own under the table the cursor is in, which is where a chart made from that table belongs.
 */
export function insertChart(spec: string, w: number, h: number, afterTable = false): Command {
  return (state, dispatch) => {
    if (!dispatch) return true;

    const chart = N.chart.create({ spec, w, h });
    const { $from } = state.selection;

    for (let depth = afterTable ? $from.depth : 0; depth > 0; depth--) {
      if ($from.node(depth).type !== N.table) continue;

      const at = $from.after(depth);
      const tr = state.tr.insert(at, N.paragraph.create(null, chart));

      dispatch(tr.setSelection(NodeSelection.create(tr.doc, at + 1)).scrollIntoView());
      return true;
    }

    dispatch(state.tr.replaceSelectionWith(chart, false).scrollIntoView());
    return true;
  };
}

export function insertTable(ctx: DocContext, rows: number, cols: number): Command {
  return (state, dispatch) => {
    if (!dispatch) return true;

    const styleId = ctx.styles.ensureBuiltin('Table Grid', 'table');
    const available = isInTable(state) ? 300 : ctx.page.width - ctx.page.left - ctx.page.right;
    const colwidth = [Math.max(24, Math.floor(available / cols))];
    const borders = ['top', 'left', 'bottom', 'right', 'insideH', 'insideV'].map((side) => `<w:${side} w:val="single" w:sz="4" w:space="0" w:color="auto"/>`).join('');
    const tblPr =
      `<w:tblPr>${styleId ? `<w:tblStyle w:val="${styleId}"/>` : ''}<w:tblW w:w="0" w:type="auto"/>${styleId ? '' : `<w:tblBorders>${borders}</w:tblBorders>`}` +
      `<w:tblLook w:val="04A0" w:firstRow="1" w:lastRow="0" w:firstColumn="1" w:lastColumn="0" w:noHBand="0" w:noVBand="1"/></w:tblPr>`;

    const row = () => N.table_row.create(null, Array.from({ length: cols }, () => N.table_cell.create({ colwidth }, N.paragraph.create())));
    const table = N.table.create({ tblPr, tstyle: styleId, borders: true }, Array.from({ length: rows }, row));
    const tr = state.tr.replaceSelectionWith(table, false);
    let at = -1;

    tr.doc.descendants((node, pos) => {
      if (node === table) at = pos;
      return at < 0;
    });

    if (at >= 0) {
      const $table = tr.doc.resolve(at);

      // A table at the very end leaves nowhere to click after it.
      if ($table.index() === $table.parent.childCount - 1) tr.insert(at + table.nodeSize, N.paragraph.create());
      tr.setSelection(TextSelection.near(tr.doc.resolve(at + 3)));
    }

    dispatch(tr.scrollIntoView());
    return true;
  };
}

// ---- Links -----------------------------------------------------------------------------------

export interface LinkRange {
  mark: Mark;
  from: number;
  to: number;
}

/** The link the cursor is in or next to, with how far it reaches. */
export function linkAt(state: EditorState): LinkRange | null {
  const { $from } = state.selection;
  const parent = $from.parent;

  if (!parent.isTextblock) return null;

  const start = $from.start();
  let offset = 0;
  let found: LinkRange | null = null;
  let open: LinkRange | null = null;

  parent.forEach((child) => {
    const link = M.link.isInSet(child.marks);
    const from = start + offset;
    const to = from + child.nodeSize;

    if (link && open && open.mark.eq(link)) open.to = to;
    else open = link ? { mark: link, from, to } : null;

    if (open && !found && $from.pos >= open.from && $from.pos <= to) found = open;
    offset += child.nodeSize;
  });

  return found;
}

export function setLink(ctx: DocContext, href: string): Command {
  return (state, dispatch) => {
    if (!dispatch) return true;

    const existing = linkAt(state);
    const { empty, ranges } = state.selection;
    const style = ctx.styles.ensureBuiltin('Hyperlink', 'character');
    const tr = state.tr;

    if (existing && (empty || (state.selection.from >= existing.from && state.selection.to <= existing.to))) {
      // Same link, new address. It keeps what it had in the file; the exporter sees the change.
      tr.removeMark(existing.from, existing.to, M.link);
      tr.addMark(existing.from, existing.to, M.link.create({ ...existing.mark.attrs, href }));
    } else if (empty) {
      const marks = [M.link.create({ href, k: nextKey() })];
      if (style) marks.push(M.charStyle.create({ id: style }));
      tr.replaceSelectionWith(schema.text(href, marks), true);
    } else {
      const link = M.link.create({ href, k: nextKey() });

      for (const { $from, $to } of ranges) {
        tr.addMark($from.pos, $to.pos, link);
        if (style) tr.addMark($from.pos, $to.pos, M.charStyle.create({ id: style }));
      }
    }

    dispatch(tr.scrollIntoView());
    return true;
  };
}

export function removeLink(ctx: DocContext): Command {
  return (state, dispatch) => {
    const existing = linkAt(state);
    if (!existing) return false;

    if (dispatch) {
      const style = ctx.styles.byName('Hyperlink', 'character');
      const tr = state.tr.removeMark(existing.from, existing.to, M.link);

      if (style) tr.removeMark(existing.from, existing.to, M.charStyle.create({ id: style.id }));
      dispatch(tr);
    }

    return true;
  };
}
