// What the page asks of the program around it: files, the window, spelling, the writing assistant.
//
// In the desktop app these calls go to Electron's main process through electron/preload.cjs,
// which puts `window.desktop` on the page. Opened in a plain browser (the Vite dev server), a
// stand-in below does what a page can do by itself: pick a file to open, download a file to save.

export interface OpenedFile {
  /** Where the file is on disk; null in a browser, which never tells. */
  path: string | null;
  name: string;
  bytes: Uint8Array;
}

export interface PickedImage {
  name: string;
  mime: string;
  bytes: Uint8Array;
}

export interface RecentFile {
  path: string;
  name: string;
}

export interface AssistModel {
  name: string;
  /** On disk, in bytes. */
  size: number;
  /** A name to show instead of `name`. */
  label?: string;
}

/**
 * Where the writing assistant's requests go: Ollama on this computer (the default), Anthropic's
 * Claude, or an OpenAI-compatible server at `baseUrl`.
 */
export interface AssistProvider {
  kind: 'ollama' | 'anthropic' | 'openai';
  baseUrl?: string;
}

export interface AssistRequest {
  model: string;
  system: string;
  text: string;
  temperature: number;
  maxTokens: number;
  /** Left out for Ollama. */
  provider?: AssistProvider;
}

/** What the right-click menu asks the writing assistant for. */
export type AssistAction = 'improve' | 'translate';

export interface Desktop {
  readonly isDesktop: boolean;
  openDialog(): Promise<OpenedFile[]>;
  /** Null when the file was written, otherwise a sentence saying why not. */
  saveFile(path: string, bytes: Uint8Array): Promise<string | null>;
  saveDialog(suggestedName: string): Promise<string | null>;
  pickImage(): Promise<PickedImage | null>;
  /** The files the program was started with: double-clicked, or dropped on its icon. */
  startupFiles(): Promise<OpenedFile[]>;
  /** Files opened while the program is already running. */
  onOpenFiles(handler: (files: OpenedFile[]) => void): void;
  /** The window's close button; the page answers with `closeWindow` once nothing is unsaved. */
  onCloseRequest(handler: () => void): void;
  closeWindow(): void;
  /** Colours for the window's own buttons, to match the title bar they sit in. */
  setChrome(background: string, symbols: string): void;
  openExternal(url: string): void;
  recentFiles(): Promise<RecentFile[]>;
  openRecent(path: string): Promise<OpenedFile | null>;
  /** A file dragged in from the file manager, read from where it is so that saving writes back there. */
  openDropped(file: File): Promise<OpenedFile | null>;
  spelling(): Promise<{ available: string[]; enabled: string[] }>;
  setSpelling(languages: string[]): Promise<void>;
  /** The models the local model server (Ollama) has; `error` says why there are none. */
  assistModels(provider?: AssistProvider): Promise<{ models: AssistModel[]; error?: string }>;
  /** Loads a model ahead of its first request. Null when it is ready, otherwise why not. */
  assistWarm(model: string, provider?: AssistProvider): Promise<string | null>;
  /** Whether an API key is saved for a service; the key itself never comes back to the page. */
  assistKeyState(provider: AssistProvider): Promise<{ saved: boolean; secure: boolean }>;
  /** Saves an API key, encrypted, or removes it when empty. Null when done, otherwise why not. */
  assistSetKey(provider: AssistProvider, key: string): Promise<string | null>;
  /** One request, answered in full; `id` is what `assistCancel` stops it by. */
  assistRun(id: string, request: AssistRequest): Promise<{ text?: string; error?: string }>;
  assistCancel(id: string): Promise<void>;
  onAssistCommand(handler: (action: AssistAction) => void): void;
  /** Prints the sheets the page has put up for printing (src/editor/print.ts), through the system's print dialog. */
  print(size: PaperSize): Promise<boolean>;
  /** Asks where to save, and writes the sheets there as a PDF. The path, or null when cancelled. */
  exportPdf(suggestedName: string, size: PaperSize): Promise<string | null>;
  /** "Export as…": asks where, offering Markdown, HTML and ODT (`format` first). The path, or null when cancelled. */
  exportDialog?(suggestedName: string, format: string): Promise<string | null>;
  /** Writes an exported file, and its pictures in a "<name>_files" folder beside it. Null when done, otherwise why not. */
  exportWrite?(path: string, bytes: Uint8Array, extras: { name: string; bytes: Uint8Array }[]): Promise<string | null>;
  /** The name of the user logged in to the computer: who comments and tracked changes are by, until a name is set. */
  userName(): Promise<string>;
  /** A GET to Zotero's local API (and only there), from the main process. */
  zoteroGet?(url: string): Promise<{ status?: number; text?: string; error?: string }>;
  /** Recovery copies of documents with unsaved changes (electron/recovery.cjs, src/session/recovery.ts). */
  recoveryWrite?(key: string, info: { path: string | null; name: string }, bytes: Uint8Array): Promise<boolean>;
  recoveryRemove?(key: string): Promise<void>;
  /** The copies an earlier run left behind. */
  recoveryList?(): Promise<RecoveryEntry[]>;
  /** A copy, with its document's own path, which may then be saved to. */
  recoveryRead?(key: string): Promise<OpenedFile | null>;
  recoveryOpenOriginal?(key: string): Promise<OpenedFile | null>;
}

export interface RecoveryEntry {
  key: string;
  path: string | null;
  name: string;
  /** When the copy was written, in milliseconds. */
  time: number;
}

/** A sheet of paper, in CSS pixels at 96 to the inch. */
export interface PaperSize {
  width: number;
  height: number;
}

declare global {
  interface Window {
    desktop?: Desktop;
  }
}

function pick(accept: string, multiple: boolean): Promise<File[]> {
  return new Promise((resolve) => {
    const input = document.createElement('input');

    input.type = 'file';
    input.accept = accept;
    input.multiple = multiple;
    input.onchange = () => resolve([...(input.files ?? [])]);
    input.oncancel = () => resolve([]);
    input.click();
  });
}

async function read(file: File): Promise<OpenedFile> {
  return { path: null, name: file.name, bytes: new Uint8Array(await file.arrayBuffer()) };
}

const browser: Desktop = {
  isDesktop: false,

  async openDialog() {
    return Promise.all((await pick('.docx,.dotx', true)).map(read));
  },

  // A page cannot write to a path. "Saving" hands the browser a download under that name.
  async saveFile(path, bytes) {
    const url = URL.createObjectURL(new Blob([bytes as BlobPart], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' }));
    const link = document.createElement('a');

    link.href = url;
    link.download = path;
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 10_000);

    return null;
  },

  async saveDialog(suggestedName) {
    return suggestedName;
  },

  async pickImage() {
    const [file] = await pick('image/*', false);
    return file ? { name: file.name, mime: file.type, bytes: new Uint8Array(await file.arrayBuffer()) } : null;
  },

  async startupFiles() {
    return [];
  },

  onOpenFiles() {},
  onCloseRequest() {},
  closeWindow() {},
  setChrome() {},

  openExternal(url) {
    window.open(url, '_blank', 'noopener');
  },

  async recentFiles() {
    return [];
  },

  async openRecent() {
    return null;
  },

  openDropped: read,

  async spelling() {
    return { available: [], enabled: [] };
  },

  async setSpelling() {},

  // The page may not connect anywhere but its own origin, so a local model is out of its reach.
  async assistModels() {
    return { models: [], error: 'The writing assistant works in the desktop app.' };
  },

  async assistWarm() {
    return 'The writing assistant works in the desktop app.';
  },

  async assistRun() {
    return { error: 'The writing assistant works in the desktop app.' };
  },

  async assistKeyState() {
    return { saved: false, secure: false };
  },

  async assistSetKey() {
    return 'The writing assistant works in the desktop app.';
  },

  async assistCancel() {},
  onAssistCommand() {},

  async print() {
    window.print();
    return true;
  },

  async exportPdf() {
    // A browser has no PDF writer of its own to call; its print dialog offers "Save as PDF".
    window.print();
    return null;
  },

  async userName() {
    return '';
  },
};

export const desktop: Desktop = window.desktop ?? browser;
