// The citation dialogs, reached from the References menu: managing sources, inserting and
// editing citations, the bibliography, the style, and bringing sources in from files and Zotero.

import type { Command } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { closePopover, h, toast } from '../ui/dom';
import '../styles/cite.css';
import { citationAt, editCitation, findBibliography, insertBibliography, insertCitation, refreshCitations } from './fields';
import { sourcesFromFile } from './formats';
import { type CitationPart, parseCitation } from './instr';
import {
  FIELD_LABELS, KINDS, KIND_FIELDS, type Kind, type Source, describe, emptySource, kindOf, namesText, parseNames,
} from './model';
import { ibidOn, setIbid } from './note-cite';
import { addSources, deleteSource, findSource, library, saveSource, setStyle } from './store';
import { STYLES, type StyleId, formatCitation, formatEntry } from './styles';
import { searchZotero } from './zotero';

export interface CiteHost {
  tab(): { ctx: DocContext; view: EditorView } | null;
  run(command: Command): void;
  focus(): void;
}

interface Button<T> {
  label: string;
  value: T;
  primary?: boolean;
}

/** A modal dialog. Resolves with the value of the button pressed, or `cancel` for Escape. */
function modal<T>(title: string, body: HTMLElement, buttons: Button<T>[], cancel: T, wide = false): { done: Promise<T>; close: (value: T) => void } {
  let close!: (value: T) => void;
  const done = new Promise<T>((resolve) => {
    const onKey = (event: KeyboardEvent) => {
      const target = event.target as HTMLElement;
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        close(cancel);
      } else if (event.key === 'Enter' && !(target instanceof HTMLSelectElement) && !(target instanceof HTMLButtonElement) && !(target instanceof HTMLTextAreaElement)) {
        const primary = buttons.find((b) => b.primary);
        if (primary && backdrop.contains(target)) {
          event.preventDefault();
          close(primary.value);
        }
      }
    };

    const backdrop = h(
      'div',
      { class: 'dialog-backdrop' },
      h(
        'div',
        { class: `dialog field-dialog cite-dialog${wide ? ' cite-wide' : ''}`, role: 'dialog' },
        h('h2', null, title),
        body,
        h('div', { class: 'buttons' }, ...buttons.map((b) => h('button', { class: b.primary ? 'button primary' : 'button', onclick: () => close(b.value) }, b.label))),
      ),
    );

    close = (value: T) => {
      document.removeEventListener('keydown', onKey, true);
      backdrop.remove();
      resolve(value);
    };

    closePopover();
    document.addEventListener('keydown', onKey, true);
    document.body.append(backdrop);
    body.querySelector<HTMLElement>('input, select')?.focus();
  });
  return { done, close };
}

const row = (label: string, control: HTMLElement) => h('label', { class: 'field-row' }, h('span', null, label), control);
const option = (value: string, label: string) => h('option', { value }, label);

function sourcesChanged(host: CiteHost, ctx: DocContext): void {
  host.run(refreshCitations(ctx));
}

function styleSelect(ctx: DocContext, onChange: () => void): HTMLSelectElement {
  const select = h('select', { class: 'tool-select' }, ...STYLES.map((s) => option(s.id, s.label)));
  select.value = library(ctx).style;
  select.addEventListener('change', () => {
    setStyle(ctx, select.value as StyleId);
    onChange();
  });
  return select;
}

// ---- One source --------------------------------------------------------------------------------------

/** The form for a source. Resolves with the edited source, or null when cancelled. */
async function sourceForm(ctx: DocContext, original: Source | null): Promise<Source | null> {
  const start = original ?? emptySource('book');
  const values: Record<string, string> = { ...start.fields, Author: namesText(start.people.Author ?? []), Editor: namesText(start.people.Editor ?? []) };
  const kind = h('select', { class: 'tool-select' }, ...KINDS.map((k) => option(k.kind, k.label)));
  kind.value = KINDS.some((k) => k.type === start.type) || original === null ? kindOf(start) : 'generic';
  const tag = h('input', { class: 'tool-input', value: start.tag, placeholder: 'Made from the author and year' });
  const fields = h('div', { class: 'cite-fields' });
  const typeNote = KINDS.some((k) => k.type === start.type) ? null : h('p', { class: 'cite-note' }, `Word source type: ${start.type}`);

  const save = () => {
    for (const input of fields.querySelectorAll<HTMLInputElement>('input[data-field]')) values[input.dataset.field!] = input.value;
  };

  const build = () => {
    const shown = KIND_FIELDS[kind.value as Kind];
    const others = Object.keys(start.fields).filter((name) => !shown.includes(name) && FIELD_LABELS[name] && name !== 'ThesisType');
    fields.replaceChildren(
      ...[...shown, ...others].map((name) => {
        const input = h('input', { class: 'tool-input', 'data-field': name, value: values[name] ?? '' });
        if (name === 'Author' || name === 'Editor') input.placeholder = 'Last, First; Last, First; {Organisation}';
        return row(FIELD_LABELS[name] ?? name, input);
      }),
    );
  };

  kind.addEventListener('change', () => {
    save();
    build();
  });
  build();

  const body = h('div', null, row('Type of source', kind), typeNote, fields, row('Tag name', tag));
  const ok = await modal(original ? 'Edit source' : 'Create source', body, [{ label: 'Cancel', value: false }, { label: 'OK', value: true, primary: true }], false).done;
  if (!ok) return null;
  save();

  const chosen = kind.value as Kind;
  const keepType = !KINDS.some((k) => k.type === start.type) && chosen === 'generic';
  const type = keepType ? start.type : KINDS.find((k) => k.kind === chosen)!.type;
  const out: Record<string, string> = {};
  for (const [name, value] of Object.entries(values)) if (name !== 'Author' && name !== 'Editor' && value.trim()) out[name] = value.trim();
  if (chosen === 'thesis') out.ThesisType ||= 'Doctoral dissertation';
  else if (type === 'Report') delete out.ThesisType;

  return {
    tag: tag.value.trim(),
    type,
    fields: out,
    people: { ...start.people, Author: parseNames(values.Author ?? ''), Editor: parseNames(values.Editor ?? '') },
    extra: start.extra,
  };
}

// ---- The source manager ---------------------------------------------------------------------------------

export async function manageSources(host: CiteHost): Promise<void> {
  const tab = host.tab();
  if (!tab) return;
  const { ctx } = tab;

  const search = h('input', { class: 'tool-input', type: 'search', placeholder: 'Search by author, title or year' });
  const list = h('select', { class: 'field-list cite-list', size: 12 });
  const preview = h('div', { class: 'cite-preview' });
  const count = h('span', { class: 'cite-note' });
  let shown: Source[] = [];

  const fill = (select?: string) => {
    const q = search.value.trim().toLowerCase();
    shown = library(ctx).sources.filter((s) => !q || `${describe(s)} ${s.tag}`.toLowerCase().includes(q));
    list.replaceChildren(...shown.map((s) => option(s.tag, describe(s) || s.tag)));
    const at = select ? shown.findIndex((s) => s.tag === select) : 0;
    if (shown.length) list.selectedIndex = Math.max(0, at);
    count.textContent = `${library(ctx).sources.length} sources`;
    showPreview();
  };

  const showPreview = () => {
    const source = shown[list.selectedIndex];
    preview.replaceChildren(...(source ? formatEntry(library(ctx).style, source).map((r) => (r.italic ? h('i', null, r.text) : document.createTextNode(r.text))) : []));
  };

  const changed = (select?: string) => {
    sourcesChanged(host, ctx);
    fill(select);
  };

  const add = async () => {
    const source = await sourceForm(ctx, null);
    if (source) changed(saveSource(ctx, source).tag);
  };

  const edit = async () => {
    const current = shown[list.selectedIndex];
    if (!current) return;
    const source = await sourceForm(ctx, current);
    if (source) changed(saveSource(ctx, source, current.tag).tag);
  };

  const remove = () => {
    const current = shown[list.selectedIndex];
    if (!current) return;
    deleteSource(ctx, current.tag);
    changed();
  };

  search.addEventListener('input', () => fill());
  list.addEventListener('change', showPreview);
  list.addEventListener('dblclick', () => void edit());

  const tools = h(
    'div',
    { class: 'cite-tools' },
    h('button', { class: 'button', onclick: () => void add() }, 'New…'),
    h('button', { class: 'button', onclick: () => void edit() }, 'Edit…'),
    h('button', { class: 'button', onclick: remove }, 'Delete'),
    h('button', { class: 'button', onclick: () => void importFile(host, () => changed()) }, 'Import file…'),
    h('button', { class: 'button', onclick: () => void zoteroDialog(host, () => changed()) }, 'From Zotero…'),
  );

  const body = h('div', null, row('Style', styleSelect(ctx, () => changed(shown[list.selectedIndex]?.tag))), search, list, count, tools, h('div', { class: 'cite-label' }, 'Preview'), preview);
  fill();
  await modal('Manage sources', body, [{ label: 'Close', value: true, primary: true }], true, true).done;
  host.focus();
}

// ---- Citations ----------------------------------------------------------------------------------------------

interface Chosen extends CitationPart {
  source: Source;
}

export async function citationDialog(host: CiteHost): Promise<void> {
  const tab = host.tab();
  if (!tab) return;
  const { ctx, view } = tab;
  const existing = citationAt(view.state);
  const parsed = existing ? parseCitation(existing.instr) : null;
  const chosen: Chosen[] = (parsed?.parts ?? []).flatMap((part) => {
    const source = findSource(ctx, part.tag);
    return source ? [{ ...part, source }] : [];
  });

  const search = h('input', { class: 'tool-input', type: 'search', placeholder: 'Search sources' });
  const list = h('select', { class: 'field-list cite-list', size: 8 });
  const rows = h('div', { class: 'cite-chosen' });
  const preview = h('div', { class: 'cite-preview' });
  let shown: Source[] = [];

  const fill = () => {
    const q = search.value.trim().toLowerCase();
    shown = library(ctx).sources.filter((s) => !q || `${describe(s)} ${s.tag}`.toLowerCase().includes(q));
    list.replaceChildren(...shown.map((s) => option(s.tag, describe(s) || s.tag)));
    if (shown.length) list.selectedIndex = 0;
  };

  const showPreview = () => {
    const runs = formatCitation(library(ctx).style, chosen.map((c) => ({ ...c })));
    preview.replaceChildren(...(chosen.length ? runs.map((r) => (r.italic ? h('i', null, r.text) : document.createTextNode(r.text))) : [h('span', { class: 'cite-note' }, 'Pick one or more sources.')]));
  };

  const drawRows = () => {
    rows.replaceChildren(
      ...chosen.map((c, i) => {
        const input = (key: 'pages' | 'prefix' | 'suffix', placeholder: string) => {
          const el = h('input', { class: 'tool-input', value: c[key] ?? '', placeholder });
          el.addEventListener('input', () => {
            c[key] = el.value.trim() || undefined;
            showPreview();
          });
          return el;
        };
        const noAuthor = h('input', { type: 'checkbox' });
        noAuthor.checked = !!c.noAuthor;
        noAuthor.addEventListener('change', () => {
          c.noAuthor = noAuthor.checked || undefined;
          showPreview();
        });
        return h(
          'div',
          { class: 'cite-row' },
          h('div', { class: 'cite-row-title' }, describe(c.source) || c.tag),
          h(
            'div',
            { class: 'cite-row-inputs' },
            input('prefix', 'Prefix (see)'),
            input('pages', 'Pages'),
            input('suffix', 'Suffix'),
            h('label', { class: 'cite-check' }, noAuthor, 'Without author'),
            h('button', { class: 'button', title: 'Take out of the citation', onclick: () => { chosen.splice(i, 1); drawRows(); } }, '×'),
          ),
        );
      }),
    );
    showPreview();
  };

  const pick = () => {
    const source = shown[list.selectedIndex];
    if (source && !chosen.some((c) => c.source === source)) chosen.push({ tag: source.tag, source });
    drawRows();
  };

  const create = async () => {
    const source = await sourceForm(ctx, null);
    if (!source) return;
    const saved = saveSource(ctx, source);
    chosen.push({ tag: saved.tag, source: saved });
    fill();
    drawRows();
  };

  search.addEventListener('input', fill);
  list.addEventListener('dblclick', pick);
  fill();
  drawRows();

  const body = h(
    'div',
    null,
    row('Style', styleSelect(ctx, () => { sourcesChanged(host, ctx); showPreview(); })),
    search,
    list,
    h('div', { class: 'cite-tools' }, h('button', { class: 'button', onclick: pick }, 'Add to citation'), h('button', { class: 'button', onclick: () => void create() }, 'New source…')),
    h('div', { class: 'cite-label' }, 'In this citation'),
    rows,
    h('div', { class: 'cite-label' }, 'Preview'),
    preview,
  );

  const ok = await modal(existing ? 'Edit citation' : 'Insert citation', body, [{ label: 'Cancel', value: false }, { label: existing ? 'OK' : 'Insert', value: true, primary: true }], false, true).done;
  if (!ok || !chosen.length) return host.focus();

  const citation = { lcid: parsed?.lcid ?? '1033', parts: chosen.map(({ source: _source, ...part }) => part) };
  const fresh = host.tab();
  if (!fresh) return;
  const field = existing ? citationAt(fresh.view.state) : null;
  host.run(field ? editCitation(ctx, field, citation) : insertCitation(ctx, citation));
}

// ---- Bringing sources in ------------------------------------------------------------------------------------

function report(added: number, skipped: number): void {
  if (!added && !skipped) toast('No sources were found.', true);
  else if (!skipped) toast(added === 1 ? 'Added 1 source.' : `Added ${added} sources.`);
  else toast(`Added ${added} sources; ${skipped} were in the document already.`);
}

/** Asks for a .bib, .ris or CSL-JSON file and adds its sources. */
export function importFile(host: CiteHost, after?: () => void): Promise<void> {
  const tab = host.tab();
  if (!tab) return Promise.resolve();

  return new Promise((resolve) => {
    const input = h('input', { type: 'file', accept: '.bib,.bibtex,.ris,.json,.txt' });
    input.addEventListener('change', async () => {
      const file = input.files?.[0];
      if (!file) return resolve();
      try {
        const { added, skipped } = addSources(tab.ctx, sourcesFromFile(file.name, await file.text()));
        report(added.length, skipped);
        if (after) after();
        else sourcesChanged(host, tab.ctx);
      } catch (error) {
        toast(`The file could not be read: ${error instanceof Error ? error.message : String(error)}`, true);
      }
      resolve();
    });
    input.click();
  });
}

/** Searches the Zotero library and adds the items picked. */
export async function zoteroDialog(host: CiteHost, after?: () => void): Promise<void> {
  const tab = host.tab();
  if (!tab) return;

  const search = h('input', { class: 'tool-input', type: 'search', placeholder: 'Search your Zotero library' });
  const list = h('select', { class: 'field-list cite-list', size: 12, multiple: true });
  const status = h('p', { class: 'cite-note' });
  let found: Source[] = [];

  const run = async () => {
    status.textContent = 'Asking Zotero…';
    const answer = await searchZotero(search.value);
    found = answer.sources;
    list.replaceChildren(...found.map((s, i) => option(String(i), describe(s) || '(untitled)')));
    status.textContent = answer.error ?? (found.length ? 'Pick the items to add (Ctrl+click for several).' : 'Nothing in Zotero matches.');
  };

  search.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      event.stopPropagation();
      void run();
    }
  });

  const body = h('div', null, h('div', { class: 'cite-tools' }, search, h('button', { class: 'button', onclick: () => void run() }, 'Search')), list, status);
  void run();
  const ok = await modal('Add sources from Zotero', body, [{ label: 'Cancel', value: false }, { label: 'Add', value: true, primary: true }], false, true).done;
  if (!ok) return host.focus();

  const picked = [...list.selectedOptions].map((o) => found[Number(o.value)]).filter(Boolean);
  const { added, skipped } = addSources(tab.ctx, picked);
  report(added.length, skipped);
  if (after) after();
  else sourcesChanged(host, tab.ctx);
}

// ---- The menu ------------------------------------------------------------------------------------------------

/** The References menu's citation items. `item` makes a menu entry that closes the menu first. */
export function citationMenuItems(host: CiteHost, item: (label: string, action: () => void) => HTMLElement): HTMLElement[] {
  const tab = host.tab();
  if (!tab) return [];
  const { ctx, view } = tab;
  const inCitation = !!citationAt(view.state);
  const style = library(ctx).style;

  return [
    item(inCitation ? 'Edit citation…' : 'Insert citation…', () => void citationDialog(host)),
    item('Manage sources…', () => void manageSources(host)),
    item(findBibliography(view.state.doc) ? 'Update bibliography' : 'Insert bibliography', () => host.run(insertBibliography(ctx))),
    item('Import sources (BibTeX, RIS, CSL-JSON)…', () => void importFile(host)),
    item('Add sources from Zotero…', () => void zoteroDialog(host)),
    ...STYLES.map((s) => {
      const el = item(s.label, () => {
        setStyle(ctx, s.id);
        sourcesChanged(host, ctx);
        host.focus();
      });
      el.classList.add('cite-style-item');
      if (s.id === style) el.classList.add('checked');
      return el;
    }),
    ...(style === 'chicago-nb' ? [ibidItem(host, ctx, item)] : []),
  ];
}

/** Chicago notes: "Ibid." for the same source as the note before, off unless asked for. */
function ibidItem(host: CiteHost, ctx: DocContext, item: (label: string, action: () => void) => HTMLElement): HTMLElement {
  const el = item('Use “Ibid.” for the same source again', () => {
    setIbid(ctx, !ibidOn(ctx));
    sourcesChanged(host, ctx);
    host.focus();
  });
  el.classList.add('cite-style-item');
  if (ibidOn(ctx)) el.classList.add('checked');
  return el;
}
