// The document as OpenDocument Text (.odt), which LibreOffice and Word both open.
//
// The package: `mimetype` first and stored, then META-INF/manifest.xml, content.xml, styles.xml,
// meta.xml, the pictures in Pictures/ and each equation as a MathML object of its own.
// Paragraph and character styles become named ODF styles (headings with their outline level);
// what a paragraph or run sets for itself becomes an automatic style. Lists are text:list with a
// list style for each Word list; tables keep their spans (with covered cells); notes are text:note;
// charts and shapes are SVG pictures. Page size and margins come from the first section; a
// section with columns is a text:section whose style has style:columns.

import type { Node as PMNode } from 'prosemirror-model';
import { TableMap } from 'prosemirror-tables';
import { type Zippable, strToU8, zipSync } from 'fflate';
import { APP_NAME } from '../brand';
import { sectionRanges } from '../columns/model';
import type { DocContext } from '../docx/import';
import { type Decls, alignCss, cellDecls, paraDecls, runDecls, twipsToPt, underlineDecls } from '../docx/props';
import { escAttr, escText, parseFragment } from '../docx/xml';
import { pprDecls } from '../editor/schema';
import { ommlToMathML } from '../math/mathml';
import { ommlToLinear } from '../math/linear';
import {
  FileNames, type Grouped, type ListItem, Lists, N, Notes, type Source, chartSvgOf, childrenOf, groupBlocks, headings, isDeleted, nestList, noteBlocks,
  pictureOf, shapeSvgOf, shapeText, splitAtBreaks, svgFile,
} from './common';

const NS =
  'xmlns:office="urn:oasis:names:tc:opendocument:xmlns:office:1.0" xmlns:style="urn:oasis:names:tc:opendocument:xmlns:style:1.0" ' +
  'xmlns:text="urn:oasis:names:tc:opendocument:xmlns:text:1.0" xmlns:table="urn:oasis:names:tc:opendocument:xmlns:table:1.0" ' +
  'xmlns:draw="urn:oasis:names:tc:opendocument:xmlns:drawing:1.0" xmlns:fo="urn:oasis:names:tc:opendocument:xmlns:xsl-fo-compatible:1.0" ' +
  'xmlns:xlink="http://www.w3.org/1999/xlink" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:meta="urn:oasis:names:tc:opendocument:xmlns:meta:1.0" ' +
  'xmlns:svg="urn:oasis:names:tc:opendocument:xmlns:svg-compatible:1.0" xmlns:math="http://www.w3.org/1998/Math/MathML" office:version="1.3"';

const XML = '<?xml version="1.0" encoding="UTF-8"?>\n';
export const ODT_MIME = 'application/vnd.oasis.opendocument.text';

// ---- CSS declarations as ODF properties -------------------------------------------------------

/** A length ODF takes: pt, in, cm, mm, px. Anything else (em, auto) is left out. */
const length = (value: string | undefined): string | null => {
  if (!value) return null;
  const m = /^(-?[\d.]+)(pt|px|in|cm|mm)$/.exec(value.trim());
  return m ? `${m[1]}${m[2]}` : null;
};

const inches = (px: number) => `${Math.round((px / 96) * 10000) / 10000}in`;
const twipsIn = (twips: number) => `${Math.round((twips / 1440) * 10000) / 10000}in`;

/** An ODF style name: letters, digits, - _ and . only, not starting with a digit. */
const odfName = (id: string) => {
  const name = id.replace(/[^A-Za-z0-9_.-]/g, '_');
  return /^[A-Za-z_]/.test(name) ? name : `_${name}`;
};

/** The first font a CSS font-family names. */
const firstFont = (css: string) => /^"([^"]+)"/.exec(css)?.[1] ?? css.split(',')[0].trim();

function border(value: string | undefined, color: string | undefined): string | null {
  if (!value) return null;
  if (value === 'none') return 'none';

  const [width, style] = value.split(/\s+/);
  const pt = width.endsWith('px') ? `${Math.round(parseFloat(width) * 0.75 * 100) / 100}pt` : width;
  return `${pt} ${style === 'double' ? 'double' : 'solid'} ${color ?? '#000000'}`;
}

function textProps(d: Decls): string {
  let a = '';

  if (d['font-family']) {
    const font = escAttr(firstFont(d['font-family']));
    a += ` style:font-name="${font}" fo:font-family="'${font}'" style:font-family-asian="'${font}'" style:font-family-complex="'${font}'"`;
  }

  const size = length(d['font-size']);
  if (size) a += ` fo:font-size="${size}" style:font-size-asian="${size}" style:font-size-complex="${size}"`;
  if (d['font-weight']) a += ` fo:font-weight="${d['font-weight']}" style:font-weight-asian="${d['font-weight']}" style:font-weight-complex="${d['font-weight']}"`;
  if (d['font-style']) a += ` fo:font-style="${d['font-style']}" style:font-style-asian="${d['font-style']}" style:font-style-complex="${d['font-style']}"`;
  if (d['--c']) a += ` fo:color="${d['--c']}"`;
  else if (d['--od']) a += ' fo:color="#FFFFFF"';
  if (d['--h']) a += ` fo:background-color="${d['--h']}"`;
  if (d['text-transform'] === 'uppercase') a += ' fo:text-transform="uppercase"';
  if (d['font-variant-caps'] === 'small-caps') a += ' fo:font-variant="small-caps"';
  if (d['vertical-align'] === 'super') a += ' style:text-position="super 58%"';
  if (d['vertical-align'] === 'sub') a += ' style:text-position="sub 58%"';
  if (d['display'] === 'none') a += ' text:display="none"';

  const lines = d['text-decoration-line'] ?? '';
  if (lines.includes('underline')) {
    const style = d['text-decoration-style'];
    const odf = style === 'double' ? 'solid" style:text-underline-type="double' : style === 'dotted' ? 'dotted' : style === 'dashed' ? 'dash' : style === 'wavy' ? 'wave' : 'solid';
    a += ` style:text-underline-style="${odf}" style:text-underline-width="auto" style:text-underline-color="font-color"`;
  } else if (lines === 'none') {
    a += ' style:text-underline-style="none" style:text-line-through-style="none"';
  }
  if (lines.includes('line-through')) a += ' style:text-line-through-style="solid"';

  return a ? `<style:text-properties${a}/>` : '';
}

function paragraphProps(d: Decls): string {
  let a = '';

  for (const [css, odf] of [['margin-top', 'fo:margin-top'], ['margin-bottom', 'fo:margin-bottom'], ['margin-left', 'fo:margin-left'], ['margin-right', 'fo:margin-right'], ['text-indent', 'fo:text-indent']]) {
    const value = length(d[css]);
    if (value) a += ` ${odf}="${value}"`;
  }

  const align = d['text-align'];
  if (align) a += ` fo:text-align="${align === 'left' ? 'start' : align === 'right' ? 'end' : align}"`;

  const line = d['line-height'];
  if (line && /^[\d.]+$/.test(line)) a += ` fo:line-height="${Math.round(parseFloat(line) * 100)}%"`;
  else if (length(line)) a += ` fo:line-height="${length(line)}"`;

  if (d['--h']) a += ` fo:background-color="${d['--h']}"`;
  if (d['--pbb']) a += ' fo:break-before="page"';

  for (const side of ['top', 'bottom', 'left', 'right']) {
    const value = border(d[`border-${side}`], d['--bc']);
    if (value && value !== 'none') a += ` fo:border-${side}="${value}"`;
  }

  return a ? `<style:paragraph-properties${a}/>` : '';
}

/** A run's formatting marks as declarations; its character style comes separately. */
function markDecls(node: PMNode, ctx: DocContext): Decls {
  const d: Decls = {};
  const lines: string[] = [];

  for (const mark of node.marks) {
    const a = mark.attrs;

    switch (mark.type.name) {
      case 'rawRPr':
        Object.assign(d, runDecls(parseFragment(a.xml), ctx.styles.theme));
        break;
      case 'fontFamily':
        if (a.name) d['font-family'] = `"${a.name}"`;
        break;
      case 'fontSize':
        d['font-size'] = `${a.size / 2}pt`;
        break;
      case 'color':
        d['--c'] = a.value === 'auto' ? '#000000' : a.value;
        break;
      case 'highlight':
        d['--h'] = a.value;
        break;
      case 'bold':
        d['font-weight'] = a.on ? 'bold' : 'normal';
        break;
      case 'italic':
        d['font-style'] = a.on ? 'italic' : 'normal';
        break;
      case 'underline':
        if (a.kind !== 'none') {
          lines.push('underline');
          d['text-decoration-style'] = underlineDecls(a.kind)['text-decoration-style'] ?? 'solid';
        }
        break;
      case 'strike':
        if (a.on) lines.push('line-through');
        break;
      case 'vert':
        d['vertical-align'] = a.value === 'subscript' ? 'sub' : 'super';
        break;
    }
  }

  if (lines.length) d['text-decoration-line'] = lines.join(' ');
  return d;
}

// ---- The writer ------------------------------------------------------------------------------

interface Picture {
  path: string;
  bytes: Uint8Array;
  mime: string;
}

class OdtWriter {
  private readonly level: (node: PMNode) => number;
  private readonly notes: Notes;
  private readonly names = new FileNames();
  readonly pictures: Picture[] = [];
  readonly objects: { dir: string; xml: string }[] = [];
  /** Automatic styles: their XML by name, and their name by what they hold. */
  private readonly auto = new Map<string, string>();
  private readonly autoNames = new Map<string, string>();
  /** The list styles the text uses (numId), and the bullet each level was seen with. */
  private readonly listStyles = new Set<number>();
  private readonly bullets = new Map<string, string>();
  private pending: string[] = [];
  private frames = 0;
  private tables = 0;
  private sections = 0;

  constructor(private readonly src: Source) {
    this.level = headings(src.ctx);
    this.notes = new Notes(src.ctx, src.doc);
  }

  /** An automatic style for these properties; one per distinct set. */
  private autoStyle(prefix: string, family: string, inside: string, parent: string | null = null): string {
    const key = `${family}|${parent ?? ''}|${inside}`;
    let name = this.autoNames.get(key);

    if (!name) {
      name = `${prefix}${this.autoNames.size + 1}`;
      this.autoNames.set(key, name);
      this.seeFonts(inside);
      this.auto.set(name, `<style:style style:name="${name}" style:family="${family}"${parent ? ` style:parent-style-name="${parent}"` : ''}>${inside}</style:style>`);
    }

    return name;
  }

  // ---- content.xml ----------------------------------------------------------------------------

  content(): string {
    const { ctx, doc } = this.src;
    const lists = new Lists(ctx);
    let body = '';

    for (const section of sectionRanges(doc, ctx.sectPr)) {
      const blocks: PMNode[] = [];
      doc.forEach((node, offset) => {
        if (offset >= section.from && offset < section.to) blocks.push(node);
      });

      const inner = this.blocks(blocks, lists);
      if (section.cols.count <= 1) {
        body += inner;
        continue;
      }

      const { cols } = section;
      const name = this.autoStyle('Sect', 'section', `<style:section-properties text:dont-balance-text-columns="false"><style:columns fo:column-count="${cols.count}" fo:column-gap="${twipsIn(cols.space)}">${cols.sep ? '<style:column-sep style:width="0.5pt" style:color="#000000" style:height="100%"/>' : ''}</style:columns></style:section-properties>`);
      body += `<text:section text:style-name="${name}" text:name="Section${++this.sections}">${inner}</text:section>`;
    }

    if (!body) body = '<text:p/>';
    const listStyles = [...this.listStyles].map((numId) => this.listStyle(numId)).join('');

    return (
      `${XML}<office:document-content ${NS}><office:font-face-decls>${this.fontFaces()}</office:font-face-decls>` +
      `<office:automatic-styles>${[...this.auto.values()].join('')}${listStyles}</office:automatic-styles>` +
      `<office:body><office:text>${body}</office:text></office:body></office:document-content>`
    );
  }

  private blocks(nodes: readonly PMNode[], lists: Lists): string {
    let out = '';

    for (const group of groupBlocks(nodes, lists) as Generator<Grouped>) {
      if (group.run) out += this.list(group.run);
      else if (group.node.type === N.paragraph) out += this.paragraph(group.node);
      else if (group.node.type === N.table) out += this.table(group.node);
      else if (group.node.type === N.block_wrap) out += this.blocks(childrenOf(group.node), lists);

      out += this.pending.join('');
      this.pending = [];
    }

    return out;
  }

  /** The paragraph's named style, and an automatic style over it for what it sets itself. */
  private paragraphStyle(node: PMNode, pageBefore = false): string {
    const a = node.attrs;
    const named = odfName(a.styleId ?? this.src.ctx.styles.defaultParagraph ?? 'Standard');
    const d: Decls = { ...pprDecls(a.ppr) };

    if (a.align) d['text-align'] = alignCss(a.align);
    if (a.indent !== null) d['margin-left'] = `${twipsToPt(a.indent)}pt`;
    if (pageBefore) d['--pbb'] = '1';

    const props = paragraphProps(d);
    return props ? this.autoStyle('P', 'paragraph', props, named) : named;
  }

  private paragraph(node: PMNode): string {
    const level = this.level(node);

    return splitAtBreaks(node)
      .map((part) => {
        const style = this.paragraphStyle(node, part.pageBefore);
        const content = this.inline(part.nodes);
        return level
          ? `<text:h text:style-name="${style}" text:outline-level="${Math.min(10, level)}">${content}</text:h>`
          : `<text:p text:style-name="${style}">${content}</text:p>`;
      })
      .join('');
  }

  private list(run: { node: PMNode; item: ListItem }[]): string {
    let out = '';
    // The number the next item at each open list would have, to see where numbering jumps.
    const next: number[] = [];

    nestList(
      run,
      {
        openList: (first) => {
          const top = !next.length;
          this.listStyles.add(first.numId);
          out += top ? `<text:list text:style-name="L${first.numId}">` : '<text:list>';
          next.push(first.n);
        },
        closeList: () => {
          out += '</text:list>';
          next.pop();
        },
        openItem: (item) => {
          if (item.bullet) this.bullets.set(`${item.numId}:${item.level}`, item.text);
          const jump = !item.bullet && item.n !== next[next.length - 1];
          out += `<text:list-item${jump || (!item.bullet && next.length === 1 && item === run[0].item) ? ` text:start-value="${item.n}"` : ''}>`;
          next[next.length - 1] = item.n + 1;
        },
        closeItem: () => {
          out += '</text:list-item>';
        },
      },
      (node) => {
        out += `<text:p text:style-name="${this.paragraphStyle(node)}">${this.inline(childrenOf(node))}</text:p>`;
      },
    );

    return out;
  }

  private listStyle(numId: number): string {
    const numbering = this.src.ctx.numbering;
    let levels = '';

    for (let ilvl = 0; ilvl < 9; ilvl++) {
      const level = numbering.level(numId, ilvl);
      const left = level?.left ?? 720 * (ilvl + 1);
      const hanging = level?.hanging ?? 360;
      const place =
        '<style:list-level-properties text:list-level-position-and-space-mode="label-alignment">' +
        `<style:list-level-label-alignment text:label-followed-by="listtab" text:list-tab-stop-position="${twipsIn(left)}" fo:text-indent="${twipsIn(-hanging)}" fo:margin-left="${twipsIn(left)}"/>` +
        '</style:list-level-properties>';

      if (!level || level.fmt === 'bullet' || level.fmt === 'none') {
        const char = level?.fmt === 'none' ? ' ' : (this.bullets.get(`${numId}:${ilvl}`) ?? '•');
        levels += `<text:list-level-style-bullet text:level="${ilvl + 1}" text:bullet-char="${escAttr(char)}">${place}</text:list-level-style-bullet>`;
        continue;
      }

      const own = level.text.match(/%\d/g) ?? [];
      const prefix = level.text.slice(0, Math.max(0, level.text.search(/%\d/)));
      const suffix = level.text.slice(level.text.lastIndexOf('%') + 2);
      const format = { lowerLetter: 'a', upperLetter: 'A', lowerRoman: 'i', upperRoman: 'I' }[level.fmt] ?? '1';

      levels +=
        `<text:list-level-style-number text:level="${ilvl + 1}" style:num-format="${format}"` +
        `${prefix ? ` style:num-prefix="${escAttr(prefix)}"` : ''}${suffix ? ` style:num-suffix="${escAttr(suffix)}"` : ''}` +
        ` text:display-levels="${Math.max(1, own.length)}" text:start-value="${level.start}">${place}</text:list-level-style-number>`;
    }

    return `<text:list-style style:name="L${numId}">${levels}</text:list-style>`;
  }

  private table(table: PMNode): string {
    const map = TableMap.get(table);
    const name = `Table${++this.tables}`;
    const widths: number[] = new Array(map.width).fill(0);

    // Column widths from the cells that span one column, in pixels.
    table.forEach((row, _o, r) => {
      let col = 0;
      row.forEach((cell) => {
        while (col < map.width && map.findCell(map.map[r * map.width + col]).left !== col) col++;
        if (cell.attrs.colwidth && cell.attrs.colspan === 1 && !widths[col]) widths[col] = cell.attrs.colwidth[0];
        col += cell.attrs.colspan;
      });
    });

    const fallback = Math.max(40, (this.src.ctx.page.width - this.src.ctx.page.left - this.src.ctx.page.right) / Math.max(1, map.width));
    const columns = widths.map((w) => w || fallback);
    const total = columns.reduce((x, y) => x + y, 0);
    const tableStyle = this.autoStyle('Tbl', 'table', `<style:table-properties style:width="${inches(total)}" table:align="left" fo:margin-bottom="8pt"/>`);

    let out = `<table:table table:name="${name}" table:style-name="${tableStyle}">`;
    for (const w of columns) {
      out += `<table:table-column table:style-name="${this.autoStyle('Col', 'table-column', `<style:table-column-properties style:column-width="${inches(w)}"/>`)}"/>`;
    }

    for (let row = 0; row < map.height; row++) {
      out += '<table:table-row>';

      for (let col = 0; col < map.width; col++) {
        const offset = map.map[row * map.width + col];
        const rect = map.findCell(offset);

        if (rect.left !== col || rect.top !== row) {
          out += '<table:covered-table-cell/>';
          continue;
        }

        const cell = table.nodeAt(offset)!;
        const a = cell.attrs;
        out +=
          `<table:table-cell table:style-name="${this.cellStyle(cell, table.attrs.borders)}" office:value-type="string"` +
          `${a.colspan > 1 ? ` table:number-columns-spanned="${a.colspan}"` : ''}${a.rowspan > 1 ? ` table:number-rows-spanned="${a.rowspan}"` : ''}>` +
          `${this.blocks(childrenOf(cell), new Lists(this.src.ctx)) || '<text:p/>'}</table:table-cell>`;
      }

      out += '</table:table-row>';
    }

    return `${out}</table:table>`;
  }

  private cellStyle(cell: PMNode, grid: boolean): string {
    const d = cellDecls(parseFragment(cell.attrs.tcPr));
    let a = ' fo:padding-left="0.075in" fo:padding-right="0.075in" fo:padding-top="0in" fo:padding-bottom="0in"';
    const own = ['top', 'bottom', 'left', 'right'].some((side) => d[`border-${side}`]);

    if (own) {
      for (const side of ['top', 'bottom', 'left', 'right']) a += ` fo:border-${side}="${border(d[`border-${side}`], d['--bc']) ?? (grid ? '0.5pt solid #000000' : 'none')}"`;
    } else {
      a += ` fo:border="${grid ? '0.5pt solid #000000' : 'none'}"`;
    }

    if (d['--h']) a += ` fo:background-color="${d['--h']}"`;
    const valign = d['vertical-align'];
    if (valign) a += ` style:vertical-align="${valign === 'middle' ? 'middle' : valign === 'bottom' ? 'bottom' : 'top'}"`;

    return this.autoStyle('Cell', 'table-cell', `<style:table-cell-properties${a}/>`);
  }

  // ---- Inline content ---------------------------------------------------------------------------

  private inline(nodes: readonly PMNode[]): string {
    let out = '';
    let link: string | null = null;

    for (const node of nodes) {
      if (isDeleted(node.marks)) continue;

      const href = node.marks.find((m) => m.type.name === 'link' && m.attrs.href)?.attrs.href ?? null;
      if (href !== link) {
        if (link !== null) out += '</text:a>';
        if (href !== null) out += `<text:a xlink:type="simple" xlink:href="${escAttr(href)}">`;
        link = href;
      }

      const content = node.isText ? textOdf(node.text ?? '') : this.atom(node);
      if (!content) continue;

      const charStyle = node.marks.find((m) => m.type.name === 'charStyle')?.attrs.id as string | undefined;
      const props = textProps(markDecls(node, this.src.ctx));
      const parent = charStyle ? odfName(charStyle) : null;
      const style = props ? this.autoStyle('T', 'text', props, parent) : parent;

      // A note is a text:note, which may not sit in a span.
      out += style && !content.startsWith('<text:note ') ? `<text:span text:style-name="${style}">${content}</text:span>` : content;
    }

    if (link !== null) out += '</text:a>';
    return out;
  }

  private atom(node: PMNode): string {
    switch (node.type) {
      case N.hard_break:
        return '<text:line-break/>';
      case N.image: {
        const picture = pictureOf(node);
        return picture ? this.frame(this.picture('image', picture.ext, picture.bytes, picture.mime), node.attrs.w, node.attrs.h, node.attrs.alt) : escText(node.attrs.alt ?? '');
      }
      case N.chart: {
        const svg = chartSvgOf(node);
        return svg ? this.frame(this.picture('chart', 'svg', svgFile(svg), 'image/svg+xml'), node.attrs.w, node.attrs.h, 'Chart') : '';
      }
      case N.shape: {
        const svg = shapeSvgOf(node);
        const text = shapeText(node);
        if (text) this.pending.push(this.blocks(childrenOf(text), new Lists(this.src.ctx)));
        if (!svg) return '';
        const size = /width="([\d.]+)" height="([\d.]+)"/.exec(svg);
        return this.frame(this.picture('shape', 'svg', svgFile(svg), 'image/svg+xml'), Number(size?.[1] ?? 96), Number(size?.[2] ?? 96), 'Shape');
      }
      case N.math:
        return this.equation(node);
      case N.opaque: {
        const note = this.notes.of(node);
        if (!note) return '';
        const body = this.blocks(noteBlocks(note), new Lists(this.src.ctx)) || '<text:p/>';
        return `<text:note text:id="${note.key}" text:note-class="${note.kind}"><text:note-citation>${escText(note.label)}</text:note-citation><text:note-body>${body}</text:note-body></text:note>`;
      }
      default:
        return '';
    }
  }

  private picture(stem: string, ext: string, bytes: Uint8Array, mime: string): string {
    const path = `Pictures/${this.names.next(stem, ext)}`;
    this.pictures.push({ path, bytes, mime });
    return path;
  }

  private frame(href: string, w: number, h: number, title: string): string {
    const style = this.autoStyle('fr', 'graphic', '<style:graphic-properties style:vertical-pos="top" style:vertical-rel="baseline" fo:border="none"/>');
    return (
      `<draw:frame draw:style-name="${style}" draw:name="Picture${++this.frames}" text:anchor-type="as-char" svg:width="${inches(w)}" svg:height="${inches(h)}" draw:z-index="0">` +
      `<draw:image xlink:href="${escAttr(href)}" xlink:type="simple" xlink:show="embed" xlink:actuate="onLoad"/>` +
      `${title ? `<svg:title>${escText(title)}</svg:title>` : ''}</draw:frame>`
    );
  }

  /** An equation as a MathML object, one per line, with no size: LibreOffice sizes it to the formula. */
  private equation(node: PMNode): string {
    const rendered = ommlToMathML(node.attrs.raw);
    const linear = ommlToLinear(node.attrs.raw).text;
    const style = this.autoStyle('fr', 'graphic', '<style:graphic-properties style:vertical-pos="middle" style:vertical-rel="text" fo:border="none"/>');

    return rendered.lines
      .map((line) => {
        const dir = `Object${this.objects.length + 1}`;
        // One row inside <math>: LibreOffice reads several children of <math> as missing operands.
        const math = line.replace(/^<math\b([^>]*)>([\s\S]*)<\/math>$/, '<math xmlns="http://www.w3.org/1998/Math/MathML"$1><mrow>$2</mrow></math>');
        this.objects.push({ dir, xml: XML + math });

        return (
          `<draw:frame draw:style-name="${style}" draw:name="Formula${this.objects.length}" text:anchor-type="as-char" draw:z-index="0">` +
          `<draw:object xlink:href="./${dir}" xlink:type="simple" xlink:show="embed" xlink:actuate="onLoad"/><svg:desc>${escText(linear)}</svg:desc></draw:frame>`
        );
      })
      .join('<text:line-break/>');
  }

  // ---- styles.xml -------------------------------------------------------------------------------

  private readonly fonts = new Set<string>();

  private fontFaces(): string {
    return [...this.fonts].map((font) => `<style:font-face style:name="${escAttr(font)}" svg:font-family="'${escAttr(font)}'"/>`).join('');
  }

  /** Notes the fonts a style or run names, for the font declarations. */
  private seeFonts(xml: string): string {
    for (const m of xml.matchAll(/style:font-name="([^"]+)"/g)) this.fonts.add(m[1].replace(/&quot;/g, '"').replace(/&amp;/g, '&'));
    return xml;
  }

  styles(): string {
    const { ctx } = this.src;
    const { styles } = ctx;
    const level = headings(ctx);
    let named = '';

    for (const def of styles.byId.values()) {
      if (def.type !== 'paragraph' && def.type !== 'character') continue;

      const family = def.type === 'paragraph' ? 'paragraph' : 'text';
      const name = odfName(def.id);
      const parent = def.basedOn && styles.byId.get(def.basedOn)?.type === def.type ? ` style:parent-style-name="${odfName(def.basedOn)}"` : '';
      const next = def.next && styles.byId.has(def.next) ? ` style:next-style-name="${odfName(def.next)}"` : '';
      const outline = family === 'paragraph' ? level(N.paragraph.create({ styleId: def.id })) : 0;
      const inside = (family === 'paragraph' ? paragraphProps(paraDecls(def.pPr)) : '') + textProps(runDecls(def.rPr, styles.theme));

      named +=
        `<style:style style:name="${name}" style:display-name="${escAttr(styles.displayName(def))}" style:family="${family}"${parent}${next}` +
        `${outline ? ` style:default-outline-level="${outline}"` : ''}${family === 'paragraph' ? ' style:class="text"' : ''}>${this.seeFonts(inside)}</style:style>`;
    }

    // Word's own defaults under the document's: 10 point Times New Roman, no spacing.
    const base = textProps({ 'font-family': '"Times New Roman"', 'font-size': '10pt', ...runDecls(styles.docRPr, styles.theme) });
    const defaults =
      `<style:default-style style:family="paragraph">${paragraphProps({ 'margin-top': '0pt', 'margin-bottom': '0pt', ...paraDecls(styles.docPPr) })}${this.seeFonts(base)}</style:default-style>` +
      '<style:default-style style:family="table"><style:table-properties table:border-model="collapsing"/></style:default-style>';

    // Page size and margins from the first section.
    const first = sectionRanges(this.src.doc, ctx.sectPr)[0];
    const sect = parseFragment(first?.sectPr)?.children.find((c) => c.name === 'w:sectPr');
    const pgSz = sect?.children.find((c) => c.name === 'w:pgSz')?.attrs;
    const pgMar = sect?.children.find((c) => c.name === 'w:pgMar')?.attrs;
    const tw = (value: string | undefined, px: number) => (value && /^-?\d+$/.test(value) ? twipsIn(Math.abs(Number(value))) : inches(px));
    const page = ctx.page;
    const layout =
      `<style:page-layout style:name="pm1"><style:page-layout-properties fo:page-width="${tw(pgSz?.['w:w'], page.width)}" fo:page-height="${tw(pgSz?.['w:h'], page.height)}"` +
      ` style:print-orientation="${pgSz?.['w:orient'] === 'landscape' ? 'landscape' : 'portrait'}"` +
      ` fo:margin-top="${tw(pgMar?.['w:top'], page.top)}" fo:margin-bottom="${tw(pgMar?.['w:bottom'], page.bottom)}"` +
      ` fo:margin-left="${tw(pgMar?.['w:left'], page.left)}" fo:margin-right="${tw(pgMar?.['w:right'], page.right)}"/></style:page-layout>`;

    return (
      `${XML}<office:document-styles ${NS}><office:font-face-decls>${this.fontFaces()}</office:font-face-decls>` +
      `<office:styles>${defaults}${named}</office:styles><office:automatic-styles>${layout}</office:automatic-styles>` +
      '<office:master-styles><style:master-page style:name="Standard" style:page-layout-name="pm1"/></office:master-styles></office:document-styles>'
    );
  }

  meta(): string {
    const now = new Date().toISOString().replace(/\.\d+Z$/, '');
    return (
      `${XML}<office:document-meta ${NS}><office:meta><meta:generator>${escText(APP_NAME)}</meta:generator>` +
      `<dc:title>${escText(this.src.name)}</dc:title><meta:creation-date>${now}</meta:creation-date><dc:date>${now}</dc:date></office:meta></office:document-meta>`
    );
  }

  manifest(): string {
    const entry = (path: string, type: string) => `<manifest:file-entry manifest:full-path="${escAttr(path)}" manifest:media-type="${type}"/>`;
    return (
      `${XML}<manifest:manifest xmlns:manifest="urn:oasis:names:tc:opendocument:xmlns:manifest:1.0" manifest:version="1.3">` +
      `<manifest:file-entry manifest:full-path="/" manifest:version="1.3" manifest:media-type="${ODT_MIME}"/>` +
      entry('content.xml', 'text/xml') +
      entry('styles.xml', 'text/xml') +
      entry('meta.xml', 'text/xml') +
      this.pictures.map((p) => entry(p.path, p.mime)).join('') +
      this.objects.map((o) => entry(`${o.dir}/`, 'application/vnd.oasis.opendocument.formula') + entry(`${o.dir}/content.xml`, 'text/xml')).join('') +
      '</manifest:manifest>'
    );
  }
}

/** Text with tabs and runs of spaces as ODF has them. */
function textOdf(text: string): string {
  return escText(text)
    .replace(/\t/g, '<text:tab/>')
    .replace(/ {2,}/g, (spaces) => ` <text:s text:c="${spaces.length - 1}"/>`);
}

/** The document as an .odt package. */
export function toOdt(src: Source): Uint8Array {
  const writer = new OdtWriter(src);
  // content.xml first: writing it finds the fonts, pictures and equations the rest lists.
  const content = writer.content();
  const styles = writer.styles();
  const stored = { level: 0 as const };

  const files: Zippable = {
    mimetype: [strToU8(ODT_MIME), stored],
    'META-INF/manifest.xml': strToU8(writer.manifest()),
    'content.xml': strToU8(content),
    'styles.xml': strToU8(styles),
    'meta.xml': strToU8(writer.meta()),
  };

  for (const picture of writer.pictures) files[picture.path] = [picture.bytes, stored];
  for (const object of writer.objects) files[`${object.dir}/content.xml`] = strToU8(object.xml);

  return zipSync(files, { level: 6 });
}
