// Find and replace.
//
// The matches live in plugin state and are drawn as decorations, so nothing is written into the
// document until something is actually replaced or formatted.
//
// Three ways to search. Text looks for the words as typed. Pattern has wildcards, and each
// wildcard is a variable: `(*)` finds everything in round brackets, and the part the `*` stood
// for can be formatted on its own, or put back by a replacement as `$1`. Regex is a JavaScript
// regular expression, its capture groups the variables.

import { Fragment, type Node as PMNode } from 'prosemirror-model';
import { type Command, type EditorState, Plugin, PluginKey, TextSelection, type Transaction } from 'prosemirror-state';
import { Decoration, DecorationSet } from 'prosemirror-view';
import { formatMatches, type FormatFilter, isEmptyFilter, spanFits, type StyleRuns } from './formatmatch';
import { schema } from './schema';

export type FindMode = 'text' | 'pattern' | 'regex';

export interface Span {
  from: number;
  to: number;
}

export interface Match extends Span {
  /** Where each variable (wildcard or capture group) of the pattern matched, in order. Empty in text mode. */
  groups: Span[];
}

interface FindState {
  query: string;
  matchCase: boolean;
  mode: FindMode;
  matches: Match[];
  /** Index of the match the view is on, or -1. */
  current: number;
  /** Why the query is not a pattern that can be searched for, or null. */
  error: string | null;
  decorations: DecorationSet;
  /** The formatting matches must have, or null for any. */
  filter: FormatFilter | null;
  /** The document's styles, for what a filter makes of text that is formatted by its style. */
  styles: StyleRuns | null;
}

interface FindMeta {
  query?: string;
  matchCase?: boolean;
  mode?: FindMode;
  current?: number;
  filter?: FormatFilter | null;
  styles?: StyleRuns | null;
}

export const findKey = new PluginKey<FindState>('find');

/** More matches than this are not looked for: a pattern like `?` would otherwise mark every letter. */
export const MAX_MATCHES = 20000;

const EMPTY: FindState = { query: '', matchCase: false, mode: 'text', matches: [], current: -1, error: null, decorations: DecorationSet.empty, filter: null, styles: null };

// ---- Patterns --------------------------------------------------------------------------------

/** The wildcards of pattern mode, for the help the find bar shows. */
export const WILDCARDS: { token: string; meaning: string }[] = [
  { token: '*', meaning: 'any text, as little as possible (also … or ...)' },
  { token: '?', meaning: 'any one character' },
  { token: '#', meaning: 'a number: 7, 2024, 3.5' },
  { token: '@', meaning: 'a word' },
  { token: '\\', meaning: 'takes the next character as it is: \\* finds a star' },
];

// Only the characters that may be escaped in a `u` expression; `\-` would be an error there.
const escapeRegex = (text: string) => text.replace(/[.*+?^${}()|[\]\\/]/g, '\\$&');

/**
 * A pattern in pattern mode's syntax as the source of a regular expression, with every wildcard a
 * capture group of its own.
 */
export function patternSource(pattern: string): string {
  let out = '';

  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];

    if (c === '\\' && i + 1 < pattern.length) {
      out += escapeRegex(pattern[++i]);
    } else if (c === '*' || c === '…') {
      out += '([^]*?)';
    } else if (c === '.' && pattern.startsWith('...', i)) {
      out += '([^]*?)';
      i += 2;
    } else if (c === '?') {
      out += '(.)';
    } else if (c === '#') {
      out += '(\\d+(?:[.,]\\d+)*)';
    } else if (c === '@') {
      out += "([\\p{L}\\p{M}\\p{N}'’_-]+)";
    } else {
      out += escapeRegex(c);
    }
  }

  return out;
}

/** The query as a regular expression to search with, or the reason it cannot be one. */
export function compileQuery(query: string, mode: FindMode, matchCase: boolean): RegExp | string {
  const flags = `gd${matchCase ? '' : 'i'}`;

  try {
    if (mode === 'regex') return new RegExp(query, flags);
    return new RegExp(mode === 'pattern' ? patternSource(query) : escapeRegex(query), `${flags}u`);
  } catch (error) {
    return error instanceof Error ? error.message.replace(/^Invalid regular expression: /, '') : 'Not a valid pattern';
  }
}

/** One character per position: text as it is, anything else (a picture, a line break) as a placeholder. */
function textOf(node: PMNode): string {
  let text = '';
  node.forEach((child) => {
    text += child.isText ? child.text : '￼';
  });
  return text;
}

export function search(
  doc: PMNode,
  query: string,
  matchCase: boolean,
  mode: FindMode = 'text',
  filter: FormatFilter | null = null,
  styles: StyleRuns | null = null,
): { matches: Match[]; error: string | null } {
  const matches: Match[] = [];
  const formatted = !isEmptyFilter(filter);

  // Nothing typed but a formatting asked for: every stretch of text that has it.
  if (!query && formatted) return { matches: formatMatches(doc, filter!, styles, MAX_MATCHES), error: null };
  if (!query) return { matches, error: null };

  const re = compileQuery(query, mode, matchCase);
  if (typeof re === 'string') return { matches, error: re };

  doc.descendants((node, pos) => {
    if (matches.length >= MAX_MATCHES) return false;
    if (!node.isTextblock) return true;

    const text = textOf(node);
    const base = pos + 1;

    re.lastIndex = 0;

    for (let m = re.exec(text); m; m = re.exec(text)) {
      // A match of nothing (an empty capture, `a*` before any a) finds nothing to show; step past it.
      if (!m[0].length) {
        re.lastIndex++;
        continue;
      }

      const groups: Span[] = [];

      for (const span of m.indices?.slice(1) ?? []) {
        if (span) groups.push({ from: base + span[0], to: base + span[1] });
      }

      const match = { from: base + m.index, to: base + m.index + m[0].length, groups };

      if (formatted && !spanFits(doc, match, filter!, styles)) continue;
      matches.push(match);
      if (matches.length >= MAX_MATCHES) break;
    }

    return false;
  });

  return { matches, error: null };
}

/** The parts of a match that a formatting or a replacement is for: the whole of it, or only its variables. */
export type FindTarget = 'match' | 'variables';

/**
 * The stretches of text a command acts on, in document order. Variables that matched nothing
 * are left out; a match without any variables counts as a whole.
 */
export function targetSpans(matches: readonly Match[], target: FindTarget): Span[] {
  if (target === 'match') return matches.map(({ from, to }) => ({ from, to }));

  return matches.flatMap((m) => (m.groups.length ? m.groups.filter((g) => g.to > g.from) : [{ from: m.from, to: m.to }]));
}

// ---- Replacing -------------------------------------------------------------------------------

type ReplacePart = { text: string } | { group: number };

/**
 * A replacement in pattern or regex mode: text, with `$1`, `$2`, … for what the variables matched,
 * `$0` or `$&` for the whole match, and `$$` for a dollar sign.
 */
export function parseReplacement(replacement: string): ReplacePart[] {
  const parts: ReplacePart[] = [];
  let text = '';

  for (let i = 0; i < replacement.length; i++) {
    const c = replacement[i];
    const next = replacement[i + 1];

    if (c === '$' && next === '$') {
      text += '$';
      i++;
    } else if (c === '$' && next === '&') {
      if (text) parts.push({ text });
      parts.push({ group: 0 });
      text = '';
      i++;
    } else if (c === '$' && next !== undefined && /\d/.test(next)) {
      // $1 to $99, the way String.replace reads them.
      const two = /^\d\d/.test(replacement.slice(i + 1, i + 3)) ? replacement.slice(i + 1, i + 3) : next;

      if (text) parts.push({ text });
      parts.push({ group: Number(two) });
      text = '';
      i += two.length;
    } else {
      text += c;
    }
  }

  if (text) parts.push({ text });
  return parts;
}

/**
 * What a match is replaced with. The text typed takes the formatting the match starts with; what a
 * variable matched is copied with the formatting it has, pictures and all.
 */
function replacementFor(doc: PMNode, match: Match, replacement: string, mode: FindMode): Fragment {
  const $from = doc.resolve(match.from);
  const marks = $from.marksAcross(doc.resolve(match.to)) ?? $from.marks();

  if (mode === 'text') return replacement ? Fragment.from(schema.text(replacement, marks)) : Fragment.empty;

  const parent = $from.parent;
  const start = $from.start();
  const nodes: PMNode[] = [];

  for (const part of parseReplacement(replacement)) {
    if ('text' in part) {
      nodes.push(schema.text(part.text, marks));
      continue;
    }

    const span = part.group === 0 ? match : match.groups[part.group - 1];
    if (!span || span.to <= span.from) continue;

    parent.content.cut(span.from - start, span.to - start).forEach((node) => nodes.push(node));
  }

  return Fragment.fromArray(nodes);
}

/** Replaces every match, from the last one up so that positions further up stay true. */
export function replaceMatches(tr: Transaction, matches: readonly Match[], replacement: string, mode: FindMode): void {
  for (let i = matches.length - 1; i >= 0; i--) replaceMatch(tr, matches[i], replacement, mode);
}

function replaceMatch(tr: Transaction, match: Match, replacement: string, mode: FindMode): void {
  const content = replacementFor(tr.doc, match, replacement, mode);

  if (content.size) tr.replaceWith(match.from, match.to, content);
  else tr.delete(match.from, match.to);
}

// ---- The plugin ------------------------------------------------------------------------------

function decorate(doc: PMNode, matches: Match[], current: number): DecorationSet {
  const decorations: Decoration[] = [];

  matches.forEach((match, i) => {
    decorations.push(Decoration.inline(match.from, match.to, { class: i === current ? 'find-match current' : 'find-match' }));

    for (const group of match.groups) {
      if (group.to > group.from) decorations.push(Decoration.inline(group.from, group.to, { class: 'find-var' }));
    }
  });

  return DecorationSet.create(doc, decorations);
}

export function findPlugin(): Plugin<FindState> {
  return new Plugin<FindState>({
    key: findKey,
    state: {
      init: () => EMPTY,
      apply(tr, old) {
        const meta = tr.getMeta(findKey) as FindMeta | undefined;

        if (!meta && !tr.docChanged) return old;
        if (!meta && !old.query && !old.filter) return old;

        const query = meta?.query ?? old.query;
        const matchCase = meta?.matchCase ?? old.matchCase;
        const mode = meta?.mode ?? old.mode;
        const filter = meta?.filter !== undefined ? meta.filter : old.filter;
        const styles = meta?.styles !== undefined ? meta.styles : old.styles;
        const { matches, error } = search(tr.doc, query, matchCase, mode, filter, styles);
        let current = meta?.current ?? old.current;

        if (current >= matches.length) current = matches.length - 1;
        if (!matches.length) current = -1;

        return { query, matchCase, mode, matches, current, error, decorations: decorate(tr.doc, matches, current), filter, styles };
      },
    },
    props: {
      decorations: (state) => findKey.getState(state)?.decorations,
    },
  });
}

export const findState = (state: EditorState): FindState => findKey.getState(state) ?? EMPTY;

// ---- Commands --------------------------------------------------------------------------------

/** Sets what is searched for and moves to the first match at or after the cursor. */
export function setQuery(query: string, matchCase: boolean, mode: FindMode = 'text', filter: FormatFilter | null = null, styles: StyleRuns | null = null): Command {
  return (state, dispatch) => {
    if (!dispatch) return true;

    const { matches } = search(state.doc, query, matchCase, mode, filter, styles);
    const first = matches.findIndex((match) => match.from >= state.selection.from);
    const current = matches.length ? (first >= 0 ? first : 0) : -1;
    const tr = state.tr.setMeta(findKey, { query, matchCase, mode, current, filter, styles });

    if (current >= 0) tr.setSelection(TextSelection.create(tr.doc, matches[current].from, matches[current].to)).scrollIntoView();
    dispatch(tr);

    return true;
  };
}

export function findStep(direction: 1 | -1): Command {
  return (state, dispatch) => {
    const { matches, current } = findState(state);
    if (!matches.length) return false;

    if (dispatch) {
      const next = (current + direction + matches.length) % matches.length;
      const match = matches[next];

      dispatch(state.tr.setMeta(findKey, { current: next }).setSelection(TextSelection.create(state.doc, match.from, match.to)).scrollIntoView());
    }

    return true;
  };
}

/** Replaces the match the view is on, then moves to the next one. */
export function replaceCurrent(replacement: string): Command {
  return (state, dispatch) => {
    const { matches, current, mode } = findState(state);
    const match = matches[current];
    if (!match) return false;

    if (dispatch) {
      const tr = state.tr;

      replaceMatch(tr, match, replacement, mode);

      // The match after this one moves into this one's place in the list.
      tr.setMeta(findKey, { current });
      dispatch(tr.scrollIntoView());
    }

    return true;
  };
}

export function replaceAll(replacement: string): Command {
  return (state, dispatch) => {
    const { matches, mode } = findState(state);
    if (!matches.length) return false;

    if (dispatch) {
      const tr = state.tr;

      replaceMatches(tr, matches, replacement, mode);

      dispatch(tr);
    }

    return true;
  };
}

export const clearFind: Command = (state, dispatch) => {
  if (dispatch) dispatch(state.tr.setMeta(findKey, { query: '', current: -1, filter: null }));
  return true;
};
