// Fields in the editor: the result the cursor is in is shaded, F9 updates the fields in the
// selection, captions and references renumber as the document is edited, and Ctrl+click on a
// cross-reference goes to what it refers to.

import { Plugin, PluginKey, TextSelection } from 'prosemirror-state';
import { Decoration, DecorationSet, type EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { measureGaps, pageOfPos, pagesKey } from '../editor/pages';
import './builtin';
import { findBookmark } from './builtin';
import { updateFieldsCommand } from './insert';
import { fieldAt, parseInstr, scanFields } from './model';
import { scopeNeedsPages, touchesFields, updateFields } from './update';

export const fieldsKey = new PluginKey('fields');

/**
 * Page numbers for positions in the document on screen: from the pages shown, or worked out from
 * the layout when the document is shown as one long page. Null when it is not laid out (a tab in
 * the background).
 */
export function pageMapper(view: EditorView, ctx: DocContext): ((pos: number) => number | null) | null {
  const shown = pagesKey.getState(view.state)?.gaps;
  if (shown?.length) return (pos) => pageOfPos(shown, pos);
  if (!view.dom.isConnected || view.dom.getClientRects().length === 0) return null;

  const pageEl = view.dom.closest<HTMLElement>('.page') ?? view.dom;
  const zoom = parseFloat(getComputedStyle(pageEl).zoom) || 1;
  const { gaps } = measureGaps(view, ctx, zoom);

  return (pos) => pageOfPos(gaps, pos);
}

/** Puts the cursor at a bookmark and brings it into view. False if there is no such bookmark. */
export function goToBookmark(view: EditorView, name: string): boolean {
  const bookmark = findBookmark(scanFields(view.state.doc), name);
  if (!bookmark) return false;

  const $pos = view.state.doc.resolve(Math.min(bookmark.from + 1, view.state.doc.content.size));
  view.dispatch(view.state.tr.setSelection(TextSelection.near($pos)).scrollIntoView());
  view.focus();
  return true;
}

/** Updates the fields that are updated before saving (everything but tables of contents). */
export function updateFieldsBeforeSave(view: EditorView, ctx: DocContext): void {
  const scope = { only: 'save' as const };
  const pages = scopeNeedsPages(view.state.doc, scope) ? pageMapper(view, ctx) : null;
  const tr = view.state.tr;

  if (updateFields(tr, ctx, { ...scope, pages })) view.dispatch(tr.setMeta(fieldsKey, true));
}

/** Updates fields: those in the selection, or (with `all`) every one in the document. */
export function runFieldUpdate(view: EditorView, ctx: DocContext, all: boolean): boolean {
  return updateFieldsCommand(ctx, all, pageMapper(view, ctx))(view.state, view.dispatch);
}

export function fieldsPlugin(ctx: DocContext): Plugin {
  return new Plugin({
    key: fieldsKey,
    appendTransaction(transactions, _old, state) {
      if (transactions.some((tr) => tr.getMeta(fieldsKey))) return null;
      if (!transactions.some((tr) => touchesFields(tr))) return null;

      const tr = state.tr;
      return updateFields(tr, ctx, { only: 'live' }) ? tr.setMeta(fieldsKey, true) : null;
    },
    props: {
      decorations(state) {
        const field = fieldAt(state.doc, state.selection.head);
        if (!field || field.resultTo <= field.resultFrom) return null;

        return DecorationSet.create(state.doc, [Decoration.inline(field.resultFrom, field.resultTo, { class: 'field-result' })]);
      },
      handleKeyDown(view, event) {
        if (event.key !== 'F9' || event.ctrlKey || event.altKey || event.metaKey) return false;

        event.preventDefault();
        runFieldUpdate(view, ctx, event.shiftKey);
        return true;
      },
      handleClick(view, pos, event) {
        if (!(event.ctrlKey || event.metaKey)) return false;

        for (let field = fieldAt(view.state.doc, pos); field; field = field.parent) {
          if (field.type !== 'REF' && field.type !== 'PAGEREF') continue;

          const instr = parseInstr(field.instr, 'd');
          if (instr.switches.has('h') && instr.args[0]) return goToBookmark(view, instr.args[0]);
        }

        return false;
      },
    },
  });
}
