// The document as one self-contained web page.
//
// Pictures are data: URLs, charts and shapes inline SVG, equations MathML. A <style> block carries
// the paragraph and character styles (fonts, sizes, colours, spacing) as classes; lists keep the
// markers Word shows, written as each item's list-style-type; tables keep their spans, borders and
// shading; notes are linked and listed at the end; a section's columns are CSS columns. Page size
// and margins go in an @page rule, and page breaks break the page when printed.

import type { Mark, Node as PMNode } from 'prosemirror-model';
import type { DocContext } from '../docx/import';
import { type Decls, alignCss, cellDecls, fontFamilyCss, paraDecls, runDecls, twipsToPt, underlineDecls } from '../docx/props';
import { parseFragment } from '../docx/xml';
import { mathHtml } from '../math/node';
import { sectionRanges } from '../columns/model';
import { pprDecls } from '../editor/schema';
import {
  type Grouped, type ListItem, Lists, N, Notes, type Source, chartSvgOf, childrenOf, groupBlocks, headings, isDeleted, nestList, noteBlocks, shapeSvgOf,
  shapeText, splitAtBreaks,
} from './common';

export const escHtml = (text: string): string => text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** A class name for a style id: letters, digits, - and _ only. */
const styleClass = (prefix: string, id: string) => `${prefix}-${id.replace(/[^A-Za-z0-9_-]/g, '_')}`;

/**
 * Declarations as plain CSS. The editor's own (props.ts) keep colours in custom properties so the
 * page can show them on a dark paper; a web page wants them as they are.
 */
export function plainCss(d: Decls): string {
  let css = '';

  for (const [key, value] of Object.entries(d)) {
    if (key === '--c') css += `color:${value};`;
    else if (key === '--h') css += `background-color:${value};`;
    else if (key === '--bc') css += `border-color:${value};`;
    else if (key === '--pbb') css += 'break-before:page;';
    else if (key === '--od') css += d['--c'] ? '' : 'color:#FFFFFF;';
    else if (!key.startsWith('--')) css += `${key}:${value};`;
  }

  return css;
}

/** A list marker as a CSS string: list-style-type takes one. */
const cssString = (text: string) => `'${text.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}\u00a0'`;

function markerStyle(item: ListItem): string {
  if (item.bullet) {
    if (item.text === '•' || item.text === '●') return 'disc';
    if (item.text === '◦' || item.text === 'o') return 'circle';
    if (item.text === '▪' || item.text === '■') return 'square';
  }
  return cssString(item.text);
}

/** The stylesheet: the document's defaults, its paragraph and character styles, and the page. */
function stylesheet(ctx: DocContext): string {
  const { styles } = ctx;
  const base: Decls = { 'font-family': fontFamilyCss('Times New Roman'), 'font-size': '10pt', ...runDecls(styles.docRPr, styles.theme) };
  const page = ctx.page;
  const inches = (px: number) => `${Math.round((px / 96) * 1000) / 1000}in`;
  const rules: string[] = [
    `@page{size:${inches(page.width)} ${inches(page.height)};margin:${inches(page.top)} ${inches(page.right)} ${inches(page.bottom)} ${inches(page.left)}}`,
    `html{background:#FFFFFF;color:#000000}`,
    `body{${plainCss(base)}max-width:${Math.round(page.width - page.left - page.right)}px;margin:0 auto;padding:48px 24px}`,
    '@media print{body{max-width:none;padding:0}}',
    `p,h1,h2,h3,h4,h5,h6{margin:0;font-size:inherit;font-weight:inherit;${plainCss(paraDecls(styles.docPPr))}}`,
    'ol,ul{margin:0;padding-left:2.25em}',
    'li>p,li>h1,li>h2,li>h3,li>h4,li>h5,li>h6{margin-left:0!important;text-indent:0!important}',
    'table{border-collapse:collapse;margin:0 0 8pt}',
    'td,th{vertical-align:top;padding:0 5.4pt;text-align:left;font-weight:inherit}',
    'table.grid>tbody>tr>td,table.grid>tbody>tr>th{border:0.5pt solid #000000}',
    'img,svg{max-width:100%;height:auto;vertical-align:bottom}',
    '.tab{white-space:pre;display:inline-block;min-width:2em}',
    '.math-display{display:block;margin:6pt 0}',
    '.text-box{border:0.5pt solid #BFBFBF;padding:4pt 8pt;margin:4pt 0}',
    'hr.page-break{border:0;border-top:1px dashed #BFBFBF;margin:24px 0}',
    '@media print{hr.page-break{visibility:hidden;margin:0;break-after:page}.section.new-page{break-before:page}}',
    '.notes{margin-top:24pt;font-size:0.9em}',
    '.notes>hr{width:33%;margin:0 0 6pt;border:0;border-top:0.5pt solid #000000}',
    '.notes a.back{text-decoration:none;margin-left:4pt}',
    'sup.note-ref a{text-decoration:none}',
  ];

  for (const def of styles.byId.values()) {
    const d: Decls = {};

    if (def.type === 'paragraph') {
      for (const link of styles.chain(def.id)) Object.assign(d, paraDecls(link.pPr), runDecls(link.rPr, styles.theme));
      const css = plainCss(d);
      const name = styleClass('s', def.id);
      if (css) rules.push(`.${name}{${css}}`);

      // "Don't add space between paragraphs of the same style", which keeps lists tight.
      if (styles.chain(def.id).some((link) => /<w:contextualSpacing(?![^>]*w:val="(?:0|false|off)")/.test(link.xml))) {
        rules.push(`.${name}+.${name}{margin-top:0}`, `.${name}:has(+.${name}){margin-bottom:0}`, `li>.${name}{margin-top:0;margin-bottom:0}`);
      }
    } else if (def.type === 'character') {
      for (const link of styles.chain(def.id)) Object.assign(d, runDecls(link.rPr, styles.theme));
      const css = plainCss(d);
      if (css) rules.push(`.${styleClass('cs', def.id)}{${css}}`);
    }
  }

  return rules.join('\n');
}

class HtmlWriter {
  private readonly level: (node: PMNode) => number;
  private readonly notes: Notes;
  private pending: string[] = [];

  constructor(private readonly src: Source) {
    this.level = headings(src.ctx);
    this.notes = new Notes(src.ctx, src.doc);
  }

  write(): string {
    const { ctx, doc } = this.src;
    const body: string[] = [];
    const sections = sectionRanges(doc, ctx.sectPr);
    const lists = new Lists(ctx);
    const plain = sections.length === 1 && sections[0].cols.count <= 1;

    for (const section of sections) {
      const blocks: PMNode[] = [];
      doc.forEach((node, offset) => {
        if (offset >= section.from && offset < section.to) blocks.push(node);
      });

      const inner = this.blocks(blocks, lists);
      if (plain) {
        body.push(inner);
        continue;
      }

      const { cols } = section;
      const newPage = section.index > 0 && section.type !== 'continuous' && section.type !== 'nextColumn';
      const style = cols.count > 1
        ? ` style="column-count:${cols.count};column-gap:${twipsToPt(cols.space)}pt${cols.sep ? ';column-rule:0.5pt solid #000000' : ''}"`
        : '';
      body.push(`<div class="section${newPage ? ' new-page' : ''}"${style}>\n${inner}</div>`);
    }

    const notes = this.notes.ordered;
    if (notes.length) {
      body.push(
        '<section class="notes">\n<hr>\n<ol>\n' +
          notes
            .map((note) => {
              const content = this.blocks(noteBlocks(note), new Lists(ctx));
              // The way back goes at the end of the note's last paragraph.
              const back = `<a class="back" href="#ref-${note.key}" aria-label="Back to the text">↩</a>`;
              const end = content.lastIndexOf('</p>');
              const body = end >= 0 ? content.slice(0, end) + back + content.slice(end) : content + back;
              return `<li id="note-${note.key}" style="list-style-type:${cssString(note.label)}">${body}</li>\n`;
            })
            .join('') +
          '</ol>\n</section>',
      );
    }

    return (
      '<!DOCTYPE html>\n<html>\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n' +
      `<title>${escHtml(this.src.name)}</title>\n<style>\n${stylesheet(ctx)}\n</style>\n</head>\n<body>\n${body.join('\n')}\n</body>\n</html>\n`
    );
  }

  // ---- Blocks ----------------------------------------------------------------------------------

  private blocks(nodes: readonly PMNode[], lists: Lists): string {
    let out = '';

    for (const group of groupBlocks(nodes, lists) as Generator<Grouped>) {
      if (group.run) out += this.list(group.run);
      else if (group.node.type === N.paragraph) out += this.paragraph(group.node);
      else if (group.node.type === N.table) out += this.table(group.node);
      else if (group.node.type === N.block_wrap) out += this.blocks(childrenOf(group.node), lists);

      out += this.pending.join('');
      this.pending = [];
    }

    return out;
  }

  /** A paragraph's tag and attributes: a heading level gives h1 to h6. */
  private open(node: PMNode): { tag: string; attrs: string } {
    const level = this.level(node);
    const tag = level ? `h${Math.min(6, level)}` : 'p';
    const a = node.attrs;
    const style = a.styleId ?? this.src.ctx.styles.defaultParagraph;
    const d: Decls = { ...pprDecls(a.ppr) };

    if (a.align) d['text-align'] = alignCss(a.align);
    if (a.indent !== null) d['margin-left'] = `${twipsToPt(a.indent)}pt`;

    const css = plainCss(d);
    return { tag, attrs: `${style ? ` class="${styleClass('s', style)}"` : ''}${css ? ` style="${escHtml(css)}"` : ''}` };
  }

  private paragraph(node: PMNode): string {
    const { tag, attrs } = this.open(node);

    return splitAtBreaks(node)
      .map((part) => {
        const content = this.inline(part.nodes);
        return `${part.pageBefore ? '<hr class="page-break">\n' : ''}<${tag}${attrs}>${content || '<br>'}</${tag}>\n`;
      })
      .join('');
  }

  private list(run: { node: PMNode; item: ListItem }[]): string {
    let out = '';
    // Word also nests by indent alone: an item indented past its level's indent is shown so.
    const extra = new Map<ListItem, number>();
    for (const { node, item } of run) {
      const own = node.attrs.indent ?? /<w:ind\b[^>]*\bw:(?:left|start)="(-?\d+)"/.exec(node.attrs.ppr ?? '')?.[1];
      const by = own !== null && own !== undefined ? twipsToPt(Number(own) - item.left) : 0;
      if (by > 0) extra.set(item, by);
    }

    nestList(
      run,
      {
        openList: (first) => {
          out += first.bullet ? '<ul>\n' : `<ol${first.n !== 1 ? ` start="${first.n}"` : ''}>\n`;
        },
        closeList: (first) => {
          out += first.bullet ? '</ul>\n' : '</ol>\n';
        },
        openItem: (item) => {
          const by = extra.get(item);
          out += `<li${item.bullet ? '' : ` value="${item.n}"`} style="list-style-type:${escHtml(markerStyle(item))}${by ? `;margin-left:${by}pt` : ''}">`;
        },
        closeItem: () => {
          out += '</li>\n';
        },
      },
      (node) => {
        const { tag, attrs } = this.open(node);
        out += `<${tag}${attrs}>${this.inline(childrenOf(node)) || '<br>'}</${tag}>`;
      },
    );

    return out;
  }

  private table(table: PMNode): string {
    let out = `<table class="${table.attrs.borders ? 'grid' : 'nogrid'}">\n<tbody>\n`;

    table.forEach((row) => {
      out += '<tr>';
      row.forEach((cell) => {
        const a = cell.attrs;
        const tag = cell.type === N.table_header ? 'th' : 'td';
        let css = plainCss(a.tcPr ? cellDeclsOf(a.tcPr) : {});
        if (a.colwidth) css = `width:${a.colwidth.reduce((x: number, y: number) => x + y, 0)}px;${css}`;

        out +=
          `<${tag}${a.colspan !== 1 ? ` colspan="${a.colspan}"` : ''}${a.rowspan !== 1 ? ` rowspan="${a.rowspan}"` : ''}` +
          `${css ? ` style="${escHtml(css)}"` : ''}>${this.blocks(childrenOf(cell), new Lists(this.src.ctx))}</${tag}>`;
      });
      out += '</tr>\n';
    });

    return `${out}</tbody>\n</table>\n`;
  }

  // ---- Inline content ---------------------------------------------------------------------------

  private inline(nodes: readonly PMNode[]): string {
    let out = '';
    let link: string | null = null;

    for (const node of nodes) {
      if (isDeleted(node.marks)) continue;

      const href = node.marks.find((m) => m.type.name === 'link' && m.attrs.href)?.attrs.href ?? null;
      if (href !== link) {
        if (link !== null) out += '</a>';
        if (href !== null) out += `<a href="${escHtml(href)}">`;
        link = href;
      }

      const content = node.isText ? textHtml(node.text ?? '') : this.atom(node);
      out += wrapMarks(content, node.marks, this.src.ctx);
    }

    if (link !== null) out += '</a>';
    return out;
  }

  private atom(node: PMNode): string {
    switch (node.type) {
      case N.hard_break:
        return '<br>';
      case N.image:
        return node.attrs.src
          ? `<img src="${escHtml(node.attrs.src)}" width="${Math.round(node.attrs.w)}" height="${Math.round(node.attrs.h)}" alt="${escHtml(node.attrs.alt ?? '')}">`
          : escHtml(node.attrs.alt || 'Picture');
      case N.chart:
        return `<span class="chart">${chartSvgOf(node) ?? ''}</span>`;
      case N.shape: {
        const text = shapeText(node);
        if (text) this.pending.push(`<div class="text-box">\n${this.blocks(childrenOf(text), new Lists(this.src.ctx))}</div>\n`);
        return `<span class="shape">${shapeSvgOf(node) ?? ''}</span>`;
      }
      case N.math:
        return node.attrs.display ? `<span class="math-display">${mathHtml(node.attrs.raw)}</span>` : mathHtml(node.attrs.raw);
      case N.opaque: {
        const note = this.notes.of(node);
        return note ? `<sup class="note-ref"><a href="#note-${note.key}" id="ref-${note.key}">${escHtml(note.label)}</a></sup>` : '';
      }
      default:
        return '';
    }
  }
}

/** A cell's shading, borders and vertical alignment, from its `w:tcPr`. */
const cellDeclsOf = (tcPr: string): Decls => cellDecls(parseFragment(tcPr));

/** Text, with tabs kept as tab characters that a printed page also shows as space. */
function textHtml(text: string): string {
  return escHtml(text).replace(/\t/g, '<span class="tab">\t</span>');
}

/** A node's content wrapped in its formatting marks, innermost last in the mark order. */
function wrapMarks(content: string, marks: readonly Mark[], ctx: DocContext): string {
  for (let i = marks.length - 1; i >= 0; i--) {
    const mark = marks[i];
    const a = mark.attrs;
    const span = (css: string) => (css ? `<span style="${escHtml(css)}">${content}</span>` : content);

    switch (mark.type.name) {
      case 'charStyle':
        content = `<span class="${styleClass('cs', a.id)}">${content}</span>`;
        break;
      case 'fontFamily':
        content = span(a.name ? `font-family:${fontFamilyCss(a.name)}` : '');
        break;
      case 'fontSize':
        content = span(`font-size:${a.size / 2}pt`);
        break;
      case 'color':
        content = span(a.value === 'auto' ? 'color:#000000' : `color:${a.value}`);
        break;
      case 'highlight':
        content = span(`background-color:${a.value}`);
        break;
      case 'bold':
        content = a.on ? `<strong>${content}</strong>` : span('font-weight:normal');
        break;
      case 'italic':
        content = a.on ? `<em>${content}</em>` : span('font-style:normal');
        break;
      case 'underline':
        content = span(plainCss(underlineDecls(a.kind)));
        break;
      case 'strike':
        content = a.on ? `<s>${content}</s>` : span('text-decoration-line:none');
        break;
      case 'vert':
        content = a.value === 'subscript' ? `<sub>${content}</sub>` : `<sup>${content}</sup>`;
        break;
      case 'rawRPr':
        content = span(plainCss(runDecls(parseFragment(a.xml), ctx.styles.theme)));
        break;
    }
  }

  return content;
}

/** The document as a web page. */
export function toHtml(src: Source): string {
  return new HtmlWriter(src).write();
}
