// Keeps the toolbar to one row. Its groups go into a strip that clips what does not fit; the
// buttons cut off at the right are hidden, and a "»" button at the end offers them in a menu.
//
// The hidden buttons stay where they are, so their menus (Shapes, Equation, ...), which open
// under their own button, still have an anchor: popover() pulls one past the window's edge
// back in, under the right end of the toolbar.

import { closePopover, h, popover } from './dom';

/** Moves the toolbar's groups into a clipping strip, and adds the "»" button after it. */
export function overflowMenu(toolbar: HTMLElement): void {
  const strip = h('div', { class: 'toolbar-strip' });
  const more = h('button', { class: 'tool toolbar-more', title: 'More tools', hidden: true, html: '»' });

  strip.append(...[...toolbar.children].filter((child) => child.classList.contains('group')));
  toolbar.append(strip, more);

  const items = () => [...strip.querySelectorAll<HTMLElement>(':scope > .group > *')];
  const hiddenTools = () => items().filter((item) => item.classList.contains('clipped') && item instanceof HTMLButtonElement) as HTMLButtonElement[];

  const fit = () => {
    // Measured with the "»" shown, so the room it takes is kept free whenever it is needed.
    const all = items();
    for (const item of all) item.classList.remove('clipped');

    const fits = (limit: number) => all.every((item) => item.getBoundingClientRect().right <= limit + 0.5);
    more.hidden = true;
    if (fits(strip.getBoundingClientRect().right)) return;

    more.hidden = false;
    const limit = strip.getBoundingClientRect().right;

    for (const item of all) if (item.getBoundingClientRect().right > limit + 0.5) item.classList.add('clipped');
    for (const group of strip.children) group.classList.toggle('clipped', [...group.children].every((child) => child.classList.contains('clipped')));
  };

  more.addEventListener('click', () => {
    const tools = hiddenTools();

    popover(
      more,
      h(
        'div',
        { class: 'toolbar-more-menu' },
        ...tools.map((tool) =>
          h(
            'button',
            {
              class: 'menu-item',
              disabled: tool.disabled,
              'aria-pressed': tool.getAttribute('aria-pressed'),
              onclick: () => {
                closePopover();
                tool.click();
              },
            },
            h('span', { class: 'more-icon', html: tool.innerHTML }),
            h('span', { class: 'path' }, tool.title),
          ),
        ),
      ),
    );
  });

  // The window's width, and any group that grows or shrinks (a tool shown only for a table, say).
  const watch = new ResizeObserver(() => fit());
  watch.observe(toolbar);
  for (const group of strip.children) watch.observe(group);
  // Selects fill in their options after the first layout, and fonts load late.
  requestAnimationFrame(fit);
  void document.fonts?.ready.then(fit);
}
