// Headers, footers and page numbers: what each page shows in its margins.
//
// Every section names its header and footer parts by type (`w:headerReference`,
// `w:footerReference`): `default`, `first` for the section's first page when `w:titlePg` is on,
// and `even` for even pages when settings.xml has `w:evenAndOddHeaders`. A section that names
// none of a type takes the previous section's. `w:pgNumType` restarts the numbering and sets
// its format. None of this is in the editor's document: the parts are read from the package
// when shown, and a part edited on the page is written back into the package as XML, so a part
// nobody edited stays byte for byte as it came.

import type { Mark, Node as PMNode } from 'prosemirror-model';
import { EditorState } from 'prosemirror-state';
import { schema } from '../editor/schema';
import { exportPart } from './export';
import { type DocContext, importPart } from './import';
import { formatNumber } from './numbering';
import { relKind, resolveTarget } from './package';
import { isOn, twipsToPx } from './props';
import { child, childrenNamed, parseFragment } from './xml';

const N = schema.nodes;

export type HfKind = 'header' | 'footer';
export type HfType = 'default' | 'first' | 'even';

export interface Section {
  /** The part shown for each kind and type, already inherited from the sections before. */
  parts: Record<HfKind, Partial<Record<HfType, string>>>;
  titlePg: boolean;
  /** The page number the section starts at, when it restarts the numbering. */
  start: number | null;
  /** `w:pgNumType`'s format: decimal, upperRoman, lowerLetter, … */
  fmt: string;
  /** From the page's top edge to the header, and from its bottom edge to the footer, in CSS pixels. */
  headerDistance: number;
  footerDistance: number;
}

/** The sections' properties in order: each paragraph that ends one, then the body's last. */
export function sectPrsOf(ctx: DocContext, doc: PMNode): (string | null)[] {
  const out: (string | null)[] = [];

  doc.descendants((node) => {
    if (node.type === N.paragraph) {
      if (node.attrs.sectPr) out.push(node.attrs.sectPr);
      return false;
    }
    return node.type !== N.table;
  });

  out.push(doc.attrs.sectPr ?? ctx.sectPr);
  return out;
}

export function sectionsOf(ctx: DocContext, doc: PMNode): Section[] {
  const rels = new Map(ctx.rels.map((rel) => [rel.id, rel]));
  const inherited: Section['parts'] = { header: {}, footer: {} };

  return sectPrsOf(ctx, doc).map((source) => {
    const sectPr = parseFragment(source)?.children.find((c) => c.name === 'w:sectPr') ?? null;
    const parts: Section['parts'] = { header: { ...inherited.header }, footer: { ...inherited.footer } };

    for (const kind of ['header', 'footer'] as const) {
      for (const ref of childrenNamed(sectPr, `w:${kind}Reference`)) {
        const type = (ref.attrs['w:type'] ?? 'default') as HfType;
        const rel = rels.get(ref.attrs['r:id'] ?? '');
        if (rel && !rel.external && relKind(rel) === kind) parts[kind][type] = resolveTarget(ctx.docPath, rel.target);
      }
    }

    inherited.header = parts.header;
    inherited.footer = parts.footer;

    const numType = child(sectPr, 'w:pgNumType');
    const margins = child(sectPr, 'w:pgMar');
    const start = Number(numType?.attrs['w:start']);
    const twips = (name: string) => {
      const n = Number(margins?.attrs[name]);
      return Number.isFinite(n) && n >= 0 ? n : 720;
    };

    return {
      parts,
      titlePg: isOn(child(sectPr, 'w:titlePg')),
      start: numType && Number.isFinite(start) && numType.attrs['w:start'] !== undefined ? start : null,
      fmt: numType?.attrs['w:fmt'] ?? 'decimal',
      headerDistance: twipsToPx(twips('w:header')),
      footerDistance: twipsToPx(twips('w:footer')),
    };
  });
}

/** Whether settings.xml asks for separate headers and footers on even pages. */
export function evenAndOddHeaders(ctx: DocContext): boolean {
  const rel = ctx.rels.find((r) => relKind(r) === 'settings' && !r.external);
  const xml = rel ? ctx.pkg.text(resolveTarget(ctx.docPath, rel.target)) : null;
  const match = xml?.match(/<w:evenAndOddHeaders\b([^>]*?)\/?>/);
  if (!match) return false;

  const value = match[1].match(/w:val="([^"]*)"/)?.[1];
  return value === undefined || !(value === '0' || value === 'false' || value === 'off');
}

// ---- Numbering the pages --------------------------------------------------------------------

export interface PageInfo {
  /** Which section the page starts in, from 0. */
  section: number;
  /** Whether the section starts on this page. */
  first: boolean;
  /** Its page number, and as the section's format writes it. */
  number: number;
  label: string;
  /** How many pages its section has. */
  sectionPages: number;
}

/** Numbers the pages, given the section each starts in. */
export function numberPages(pageSections: readonly number[], sections: readonly Section[]): PageInfo[] {
  const out: PageInfo[] = [];
  const counts = new Map<number, number>();

  for (const s of pageSections) counts.set(s, (counts.get(s) ?? 0) + 1);

  let number = 0;

  pageSections.forEach((s, k) => {
    const first = k === 0 || pageSections[k - 1] !== s;
    const section = sections[Math.min(s, sections.length - 1)];
    const start = first ? section?.start : null;

    number = start !== null && start !== undefined ? start : number + 1;
    out.push({ section: s, first, number, label: formatNumber(number, section?.fmt ?? 'decimal'), sectionPages: counts.get(s) ?? 1 });
  });

  return out;
}

/** The part a page shows as its header or footer, or null for none. */
export function partFor(kind: HfKind, page: PageInfo, sections: readonly Section[], evenOdd: boolean): string | null {
  const section = sections[Math.min(page.section, sections.length - 1)];
  if (!section) return null;

  const parts = section.parts[kind];
  if (page.first && section.titlePg) return parts.first ?? null;
  if (evenOdd && page.number % 2 === 0) return parts.even ?? null;
  return parts.default ?? null;
}

// ---- Fields ---------------------------------------------------------------------------------

export interface FieldValues {
  page: PageInfo;
  numPages: number;
}

const PAGE_FIELD = /^\s*(PAGE|NUMPAGES|SECTIONPAGES)\b(.*)$/i;
const FIELD_TOKEN = /<w:fldChar\b[^>]*?w:fldCharType="(begin|separate|end)"[^>]*?(?:\/>|>[\s\S]*?<\/w:fldChar>)|<w:instrText\b[^>]*?>([\s\S]*?)<\/w:instrText>/g;

const decode = (text: string) => text.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');

/** What a PAGE, NUMPAGES or SECTIONPAGES field shows; null for any other field. */
export function fieldText(instr: string, values: FieldValues, sectionFmt: string): string | null {
  const match = instr.match(PAGE_FIELD);
  if (!match) return null;

  const name = match[1].toUpperCase();
  const format = match[2].match(/\\\*\s*(\w+)/)?.[1];
  const n = name === 'PAGE' ? values.page.number : name === 'NUMPAGES' ? values.numPages : values.page.sectionPages;
  let fmt = name === 'PAGE' ? sectionFmt : 'decimal';

  if (format === 'roman') fmt = 'lowerRoman';
  else if (format === 'ROMAN' || format?.toLowerCase() === 'roman') fmt = 'upperRoman';
  else if (format === 'alphabetic') fmt = 'lowerLetter';
  else if (format?.toLowerCase() === 'alphabetic') fmt = 'upperLetter';
  else if (format?.toLowerCase() === 'arabic') fmt = 'decimal';

  return formatNumber(n, fmt);
}

interface Replacement {
  from: number;
  to: number;
  text: string;
  marks: readonly Mark[];
}

/**
 * The part's document with its page-number fields showing these values. Both kinds of field are
 * found: a simple one (`w:fldSimple`, a `wrap` mark around its result) and one made of markers
 * (`w:fldChar`, kept in hidden `opaque` nodes, with its result as ordinary text between them).
 */
export function fillFields(doc: PMNode, values: FieldValues, sectionFmt: string): PMNode {
  const replacements: Replacement[] = [];

  doc.descendants((block, blockPos) => {
    if (!block.isTextblock) return true;

    interface Open {
      instr: string;
      result: boolean;
      at: number;
      ranges: { from: number; to: number; marks: readonly Mark[] }[];
    }
    const stack: Open[] = [];
    let simple: { mark: Mark; text: string; from: number; to: number; marks: readonly Mark[] } | null = null;

    const flushSimple = () => {
      if (simple) replacements.push({ from: simple.from, to: simple.to, text: simple.text, marks: simple.marks });
      simple = null;
    };

    block.forEach((node, offset) => {
      const pos = blockPos + 1 + offset;

      if (node.type === N.opaque) {
        for (const m of (node.attrs.raw as string).matchAll(FIELD_TOKEN)) {
          if (m[1] === 'begin') stack.push({ instr: '', result: false, at: pos + node.nodeSize, ranges: [] });
          else if (m[1] === 'separate' && stack.length) {
            stack[stack.length - 1].result = true;
            stack[stack.length - 1].at = pos + node.nodeSize;
          } else if (m[1] === 'end') {
            const field = stack.pop();
            const text = field ? fieldText(field.instr, values, sectionFmt) : null;

            if (field && text !== null) {
              if (field.ranges.length) {
                field.ranges.forEach((r, i) => replacements.push({ ...r, text: i === 0 ? text : '' }));
              } else if (field.result) {
                replacements.push({ from: field.at, to: field.at, text, marks: [] });
              }
            }
          } else if (m[2] !== undefined && stack.length && !stack[stack.length - 1].result) {
            stack[stack.length - 1].instr += decode(m[2]);
          }
        }
      }

      if (!node.isText) return;

      const top = stack[stack.length - 1];
      if (top?.result) top.ranges.push({ from: pos, to: pos + node.nodeSize, marks: node.marks });

      const mark = node.marks.find((m) => m.type === schema.marks.wrap && /^<w:fldSimple\b/.test(m.attrs.open));

      if (simple && !(mark && mark.eq(simple.mark))) flushSimple();
      if (!mark) return;

      if (simple) {
        simple.to = pos + node.nodeSize;
        return;
      }

      const instr = decode(mark.attrs.open.match(/w:instr="([^"]*)"/)?.[1] ?? '');
      const text = fieldText(instr, values, sectionFmt);
      if (text !== null) simple = { mark, text, from: pos, to: pos + node.nodeSize, marks: node.marks };
    });

    flushSimple();
    return false;
  });

  if (!replacements.length) return doc;

  const tr = EditorState.create({ doc }).tr;

  for (const r of replacements.sort((a, b) => b.from - a.from)) {
    if (r.text) tr.replaceWith(r.from, r.to, schema.text(r.text, r.marks));
    else tr.delete(r.from, r.to);
  }

  return tr.doc;
}

// ---- Reading and writing the parts ----------------------------------------------------------

interface LoadedPart {
  doc: PMNode;
  head: string;
  tail: string;
}

const loaded = new WeakMap<DocContext, Map<string, LoadedPart | null>>();

/** A header or footer part as the editor's document; read once, and again after it was edited. */
export function loadPart(ctx: DocContext, path: string): LoadedPart | null {
  let cache = loaded.get(ctx);
  if (!cache) loaded.set(ctx, (cache = new Map()));

  if (!cache.has(path)) {
    let part: LoadedPart | null = null;

    try {
      part = importPart(ctx, path);
    } catch {
      // A part that is not sound XML is left alone, and shown as nothing.
    }

    cache.set(path, part);
  }

  return cache.get(path) ?? null;
}

/**
 * Writes an edited header or footer back into the document's package, with any new pictures and
 * links beside it. Saving takes the package as it then is, so the edit goes into the file.
 */
export function savePart(ctx: DocContext, path: string, doc: PMNode): void {
  const part = loadPart(ctx, path);
  if (!part) return;

  const written = exportPart(ctx, path, part.head, doc, part.tail);

  for (const [name, bytes] of written.files) {
    if (ctx.pkg.files.get(name) !== bytes) ctx.pkg.files.set(name, bytes);
  }

  loaded.get(ctx)?.set(path, { ...part, doc });
}

