// The style editor: "Modify style…", "New style…" and "Update style to match selection", from the
// style drop-down or a right-click on it. While the dialog is open the document shows the style as
// it is being set (Styles.previewEdits); OK makes the change one step to undo.

import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { fontFamilyCss } from '../docx/props';
import { type Align, type LineRule, type Special, type StyleLook, diffLook, lookOf } from '../docx/styleedit';
import { addStyle, linksOf, lookAtSelection, newStyle, paragraphStyleAt, restyled, setStyleXml, updateStyleToMatch } from '../editor/styleedits';
import { closePopover, h, popover, toast } from './dom';
import '../styles/styledialog.css';

export type StyleAction = 'modify' | 'new' | 'update';

export interface StyleTab {
  ctx: DocContext;
  view: EditorView;
}

/** The menu a right-click on the style drop-down shows. */
export function styleMenu(anchor: HTMLElement, run: (action: StyleAction) => void): void {
  const item = (label: string, action: StyleAction) =>
    h('button', { class: 'menu-item', onclick: () => (closePopover(), run(action)) }, h('span', { class: 'path' }, label));

  popover(anchor, h('div', null, item('Modify style…', 'modify'), item('New style…', 'new'), item('Update style to match selection', 'update')));
}

/** Runs one of the style drop-down's actions on a document. `refresh` redraws its stylesheet. */
export function styleAction(action: StyleAction, tab: StyleTab, fonts: string[], refresh: () => void): void {
  const { ctx, view } = tab;

  if (action === 'update') {
    if (updateStyleToMatch(ctx)(view.state, view.dispatch)) toast('Style updated to match the selection');
    view.focus();
    return;
  }

  if (document.querySelector('.dialog-backdrop')) return;
  openDialog(action === 'new', tab, fonts, refresh);
}

const LINE_CHOICES = [
  ['single', 'Single'],
  ['onehalf', '1.5 lines'],
  ['double', 'Double'],
  ['atLeast', 'At least'],
  ['exact', 'Exactly'],
  ['multiple', 'Multiple'],
] as const;

type LineChoice = (typeof LINE_CHOICES)[number][0];

function lineChoice(look: StyleLook): LineChoice {
  if (look.lineRule !== 'auto') return look.lineRule;
  return look.line === 1 ? 'single' : look.line === 1.5 ? 'onehalf' : look.line === 2 ? 'double' : 'multiple';
}

/** Inline CSS that shows a look in the preview box. */
export function previewCss(look: StyleLook): string {
  const line = look.lineRule === 'auto' ? String(look.line * 1.15) : `${look.line}pt`;
  const indent = look.special === 'firstLine' ? `text-indent:${look.specialBy}pt;` : look.special === 'hanging' ? `text-indent:-${look.specialBy}pt;padding-left:${look.specialBy}pt;` : '';

  return (
    `font-family:${fontFamilyCss(look.font)};font-size:${look.size}pt;` +
    `color:${look.color === 'auto' ? 'inherit' : `#${look.color}`};` +
    `font-weight:${look.bold ? 700 : 400};font-style:${look.italic ? 'italic' : 'normal'};text-decoration:${look.underline ? 'underline' : 'none'};` +
    `text-align:${look.align === 'both' ? 'justify' : look.align};margin:${look.before}pt 0 ${look.after}pt;line-height:${line};${indent}`
  );
}

function openDialog(isNew: boolean, tab: StyleTab, fonts: string[], refresh: () => void): void {
  const { ctx, view } = tab;
  const styles = ctx.styles;
  const start = paragraphStyleAt(ctx, view.state);

  if (!isNew && !start) {
    toast('This document has no paragraph style to change. Use “New style…”.', true);
    return;
  }

  // ---- Controls -------------------------------------------------------------------------------

  const number = (title: string, step = 1) => h('input', { class: 'field num', type: 'number', min: '0', step: String(step), title });
  const select = (title: string, options: [string, string][]) => h('select', { class: 'tool-select', title }, ...options.map(([value, label]) => h('option', { value }, label)));
  const toggle = (label: string, cls: string, title: string) => h('button', { class: `tool ${cls}`, type: 'button', title, 'aria-pressed': 'false', html: label });

  const name = h('input', { class: 'field', spellcheck: 'false', title: 'Name' });
  const styleSel = select('The style to change', []);
  const typeSel = select('Kind of style', [['paragraph', 'Paragraph'], ['character', 'Character']]);
  const basedSel = select('Based on', []);
  const nextSel = select('Style for the following paragraph', []);
  const font = h('input', { class: 'field font', list: 'style-fonts', spellcheck: 'false', title: 'Font' });
  const size = number('Font size, in points', 0.5);
  const color = h('input', { type: 'color', title: 'Font colour' });
  const autoColor = h('input', { type: 'checkbox', title: 'Automatic colour' });
  const bold = toggle('<b>B</b>', 'bold', 'Bold');
  const italic = toggle('<i>I</i>', 'italic', 'Italic');
  const underline = toggle('<u>U</u>', 'underline', 'Underline');
  const align = select('Alignment', [['left', 'Left'], ['center', 'Centred'], ['right', 'Right'], ['both', 'Justified']]);
  const before = number('Spacing before, in points');
  const after = number('Spacing after, in points');
  const lineSel = select('Line spacing', LINE_CHOICES.map(([v, l]) => [v, l]));
  const lineAt = number('Line spacing value', 0.01);
  const special = select('First-line or hanging indent', [['none', '(none)'], ['firstLine', 'First line'], ['hanging', 'Hanging']]);
  const specialBy = number('Indent by, in points', 0.5);
  const preview = h('div', { class: 'style-preview-text' });
  const previewBox = h('div', { class: 'style-preview' }, h('div', { class: 'style-preview-dim' }, 'Previous paragraph. '.repeat(6)), preview, h('div', { class: 'style-preview-dim' }, 'Following paragraph. '.repeat(6)));
  const paraOnly = h('div', { class: 'style-para-only' });

  // ---- State ----------------------------------------------------------------------------------

  let id = start;
  let type: 'paragraph' | 'character' = isNew ? 'paragraph' : styles.byId.get(start!)?.type === 'character' ? 'character' : 'paragraph';
  let original: StyleLook = isNew ? lookAtSelection(ctx, view.state) : lookOf(styles, id, type);
  let links = isNew ? { basedOn: start, next: null as string | null } : linksOf(styles, id!);
  let originalName = isNew ? '' : (styles.byId.get(id!)?.name ?? id!);

  const pressed = (b: HTMLElement) => b.getAttribute('aria-pressed') === 'true';
  const press = (b: HTMLElement, on: boolean) => b.setAttribute('aria-pressed', String(on));
  const listOf = (kind: string, none: string, except: string | null) => [
    ['', none] as [string, string],
    ...[...styles.byId.values()].filter((d) => d.type === kind && d.id !== except).map((d) => [d.id, styles.displayName(d)] as [string, string]).sort((a, b) => a[1].localeCompare(b[1])),
  ];
  const fill = (sel: HTMLSelectElement, options: [string, string][], value: string) => {
    sel.replaceChildren(...options.map(([v, l]) => h('option', { value: v }, l)));
    sel.value = value;
  };

  const show = (look: StyleLook) => {
    font.value = look.font;
    size.value = String(look.size);
    autoColor.checked = look.color === 'auto';
    color.value = `#${look.color === 'auto' ? '000000' : look.color}`;
    press(bold, look.bold);
    press(italic, look.italic);
    press(underline, look.underline);
    align.value = look.align;
    before.value = String(look.before);
    after.value = String(look.after);
    lineSel.value = lineChoice(look);
    lineAt.value = String(look.line);
    special.value = look.special;
    specialBy.value = String(look.specialBy);
  };

  const load = () => {
    fill(basedSel, listOf(type, '(none)', id), links.basedOn ?? '');
    fill(nextSel, listOf('paragraph', '(same style)', null), links.next ?? (isNew ? '' : (id ?? '')));
    name.value = originalName;
    paraOnly.hidden = type === 'character';
    show(original);
  };

  const read = (): StyleLook => {
    const n = (input: HTMLInputElement, fallback: number) => (Number.isFinite(parseFloat(input.value)) ? Math.max(0, parseFloat(input.value)) : fallback);
    const choice = lineSel.value as LineChoice;
    const lineRule: LineRule = choice === 'atLeast' || choice === 'exact' ? choice : 'auto';
    const line = choice === 'single' ? 1 : choice === 'onehalf' ? 1.5 : choice === 'double' ? 2 : n(lineAt, original.line);

    return {
      font: font.value.trim() || original.font,
      size: Math.min(1638, Math.max(1, n(size, original.size))),
      color: autoColor.checked ? 'auto' : color.value.slice(1).toUpperCase(),
      bold: pressed(bold),
      italic: pressed(italic),
      underline: pressed(underline),
      before: n(before, original.before),
      after: n(after, original.after),
      lineRule,
      line,
      special: special.value as Special,
      specialBy: special.value === 'none' ? 0 : n(specialBy, original.specialBy),
      align: align.value as Align,
    };
  };

  /** The style's XML as the dialog has it now. */
  const edited = (): { id: string; xml: string } | null => {
    const look = read();
    const basedOn = basedSel.value || null;
    const next = type === 'paragraph' ? nextSel.value || null : undefined;

    if (isNew) {
      return newStyle(ctx, name.value.trim() || 'New Style', type, basedOn, look, next === null ? undefined : next);
    }

    const trimmed = name.value.trim();
    const change = {
      look: diffLook(original, look),
      basedOn: basedOn === links.basedOn ? undefined : basedOn,
      // No `w:next` means the same style follows: "(same style)" and the style itself are one choice.
      next: next === undefined || (next ?? id) === (links.next ?? id) ? undefined : next,
      name: trimmed && trimmed !== originalName ? trimmed : undefined,
    };

    // Worked out from the style as the document has it, not as the preview shows it.
    styles.previewEdits(null);
    const xml = restyled(styles, id!, change);
    return xml === null ? null : { id: id!, xml };
  };

  const update = () => {
    const look = read();

    preview.setAttribute('style', previewCss(look));
    preview.textContent = `${name.value.trim() || originalName || 'New style'}: the quick brown fox jumps over the lazy dog. `.repeat(3);
    lineAt.disabled = ['single', 'onehalf', 'double'].includes(lineSel.value);
    specialBy.disabled = special.value === 'none';
    color.disabled = autoColor.checked;

    // The document shows the style as it is being set: the change is laid over it until OK or Cancel.
    if (!isNew) {
      const now = edited();
      if (styles.previewEdits(now ? { [now.id]: now.xml } : null)) refresh();
    }
  };

  // ---- Layout ---------------------------------------------------------------------------------

  const row = (label: string, ...controls: (HTMLElement | false)[]) => h('label', { class: 'style-row' }, h('span', { class: 'style-label' }, label), ...controls.filter((c): c is HTMLElement => !!c));

  if (!isNew) {
    const all = [...styles.byId.values()].filter((d) => (d.type === 'paragraph' || d.type === 'character') && !d.hidden);
    fill(
      styleSel,
      all.sort((a, b) => a.type.localeCompare(b.type) || styles.displayName(a).localeCompare(styles.displayName(b))).map((d) => [d.id, `${styles.displayName(d)}${d.type === 'character' ? ' (character)' : ''}`]),
      id!,
    );
    styleSel.addEventListener('change', () => {
      id = styleSel.value;
      type = styles.byId.get(id)?.type === 'character' ? 'character' : 'paragraph';
      styles.previewEdits(null);
      original = lookOf(styles, id, type);
      links = linksOf(styles, id);
      originalName = styles.byId.get(id)?.name ?? id;
      load();
      update();
    });
  }

  typeSel.addEventListener('change', () => {
    type = typeSel.value as 'paragraph' | 'character';
    links = { basedOn: type === 'paragraph' ? start : null, next: null };
    load();
    update();
  });

  paraOnly.append(
    row('Alignment', align),
    row('Spacing', h('span', { class: 'style-sub' }, 'Before'), before, h('span', { class: 'style-sub' }, 'After'), after, h('span', { class: 'style-unit' }, 'pt')),
    row('Line spacing', lineSel, lineAt),
    row('Indent', special, h('span', { class: 'style-sub' }, 'By'), specialBy, h('span', { class: 'style-unit' }, 'pt')),
    row('Next style', nextSel),
  );

  const body = h(
    'div',
    { class: 'style-body' },
    isNew ? row('Name', name) : row('Style', styleSel),
    isNew ? row('Kind', typeSel) : row('Name', name),
    row('Based on', basedSel),
    row('Font', font, size, h('span', { class: 'style-unit' }, 'pt')),
    row('Look', bold, italic, underline, color, h('span', { class: 'style-sub' }, 'Automatic'), autoColor),
    paraOnly,
    previewBox,
    h('datalist', { id: 'style-fonts' }, ...fonts.map((f) => h('option', { value: f }))),
  );

  const finish = (ok: boolean) => {
    document.removeEventListener('keydown', onKey, true);
    backdrop.remove();

    const result = ok ? edited() : null;

    styles.previewEdits(null);

    if (result && isNew) {
      addStyle(ctx, view.state, view.dispatch, result, type === 'paragraph');
      toast(`Style “${name.value.trim() || 'New Style'}” added`);
    } else if (result && result.xml !== styles.byId.get(result.id)?.xml) {
      setStyleXml(result.id, result.xml)(view.state, view.dispatch);
    }

    refresh();
    view.focus();
  };

  const onKey = (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      finish(false);
    } else if (event.key === 'Enter' && (event.target as HTMLElement).tagName === 'INPUT') {
      event.preventDefault();
      finish(true);
    }
  };

  const backdrop = h(
    'div',
    { class: 'dialog-backdrop' },
    h(
      'div',
      { class: 'dialog style-dialog', role: 'dialog', 'aria-label': isNew ? 'New style' : 'Modify style' },
      h('h2', null, isNew ? 'New style' : 'Modify style'),
      body,
      h(
        'div',
        { class: 'buttons' },
        h('button', { class: 'button', onclick: () => finish(false) }, 'Cancel'),
        h('button', { class: 'button primary', onclick: () => finish(true) }, 'OK'),
      ),
    ),
  );

  for (const b of [bold, italic, underline]) b.addEventListener('click', () => (press(b, !pressed(b)), update()));
  body.addEventListener('input', update);
  body.addEventListener('change', update);

  load();
  if (isNew) name.value = 'New Style';
  update();
  closePopover();
  document.addEventListener('keydown', onKey, true);
  document.body.append(backdrop);
  (isNew ? name : styleSel).focus();
  if (isNew) name.select();
}
