// The equation editor's hooks into the editor: a double-click or Enter on an equation opens it,
// and Alt+= puts in a new one, as in Word.

import { Plugin, NodeSelection, type EditorState } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import '../styles/math.css';
import { equationDialog } from './editor';
import { ommlToLinear } from './linear';
import { linearToOmml } from './parse';

/** The equation that is selected, with its position. */
export function selectedEquation(state: EditorState): { pos: number; raw: string; display: boolean } | null {
  const sel = state.selection;
  if (!(sel instanceof NodeSelection) || sel.node.type.name !== 'math') return null;
  return { pos: sel.from, raw: sel.node.attrs.raw, display: sel.node.attrs.display };
}

/** Opens the equation at `pos` in the editor and writes back what comes out of it. */
export async function editEquation(view: EditorView, pos: number): Promise<void> {
  const node = view.state.doc.nodeAt(pos);
  if (!node || node.type.name !== 'math') return;

  const raw: string = node.attrs.raw;
  const { text, lossy } = ommlToLinear(raw);
  const result = await equationDialog({ text, display: node.attrs.display, isNew: false, lossy });
  view.focus();

  // Nothing changed: the XML stays as it came, byte for byte.
  if (!result || (result.text === text && result.display === node.attrs.display)) return;

  const now = view.state.doc.nodeAt(pos);
  if (!now || now.attrs.raw !== raw) return;

  if (!result.text) {
    view.dispatch(view.state.tr.delete(pos, pos + now.nodeSize).scrollIntoView());
    return;
  }

  const paraPr = /^<m:oMathPara\b[^>]*>(<m:oMathParaPr>[\s\S]*?<\/m:oMathParaPr>|<m:oMathParaPr\/>)/.exec(raw)?.[1];
  const { xml } = linearToOmml(result.text, { display: result.display, paraPr });
  const tr = view.state.tr.setNodeMarkup(pos, null, { raw: xml, display: result.display });
  view.dispatch((result.display ? alone(tr, pos) : tr).scrollIntoView());
}

/** Puts in a new equation where the cursor is. A display equation gets a paragraph of its own. */
export async function insertEquation(view: EditorView, display: boolean): Promise<void> {
  const result = await equationDialog({ text: '', display, isNew: true });
  view.focus();
  if (!result?.text) return;

  const { xml } = linearToOmml(result.text, { display: result.display });
  const node = view.state.schema.nodes.math.create({ raw: xml, display: result.display });
  const tr = view.state.tr.replaceSelectionWith(node, true);
  const pos = tr.selection.from - node.nodeSize;
  const fixed = result.display ? alone(tr, pos) : tr;
  view.dispatch(fixed.scrollIntoView());
}

/** Splits the paragraph around the equation at `pos`, so it stands on a line of its own. */
function alone<T extends import('prosemirror-state').Transaction>(tr: T, pos: number): T {
  const $pos = tr.doc.resolve(pos);
  const parent = $pos.parent;
  if (!parent.isTextblock) return tr;

  const node = tr.doc.nodeAt(pos);
  if (!node) return tr;

  const after = pos + node.nodeSize;
  if (after < $pos.end()) tr.split(after);
  if (pos > $pos.start()) tr.split(pos);
  return tr;
}

/** The current paragraph has nothing in it: Word makes a new equation there a display one. */
const emptyLine = (state: EditorState) => state.selection.empty && state.selection.$from.parent.isTextblock && state.selection.$from.parent.content.size === 0;

export function mathPlugin(): Plugin {
  return new Plugin({
    props: {
      handleDoubleClickOn(view, _pos, node, nodePos) {
        if (node.type.name !== 'math') return false;
        void editEquation(view, nodePos);
        return true;
      },
      handleKeyDown(view, event) {
        if (event.altKey && !event.ctrlKey && !event.metaKey && (event.key === '=' || event.code === 'Equal') && !event.shiftKey) {
          event.preventDefault();
          const selected = selectedEquation(view.state);
          if (selected) void editEquation(view, selected.pos);
          else void insertEquation(view, emptyLine(view.state));
          return true;
        }

        if (event.key === 'Enter' && !event.shiftKey && !event.ctrlKey && !event.altKey) {
          const selected = selectedEquation(view.state);
          if (!selected) return false;
          event.preventDefault();
          void editEquation(view, selected.pos);
          return true;
        }

        return false;
      },
    },
  });
}
