// The workbook a chart carries with it.
//
// Word draws a chart from the values copied into the chart part, but "Edit Data" opens the real
// thing: an .xlsx embedded in the document. This writes one from the chart's sheet, formulas
// included, and reads one back so that a chart keeps its formulas from one session to the next.
// Only the first sheet is looked at, and only its cells: what they hold, not how they look.

import { strToU8, unzipSync, zipSync } from 'fflate';
import { parseRels, relKind, resolveTarget } from '../docx/package';
import { type XmlEl, escAttr, escText, parseXml } from '../docx/xml';
import { SHEET } from './chartxml';
import { CellError, cellName, evaluateSheet, excelFormula, parseCellName } from './formula';
import { MAX_COLS, MAX_ROWS, trimCells } from './model';

const MAIN_NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main';
const R_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const PKG_RELS = 'http://schemas.openxmlformats.org/package/2006/relationships';
const SHEET_TYPES = 'application/vnd.openxmlformats-officedocument.spreadsheetml';
const HEAD = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';

/** The errors Excel knows. Anything else the sheet can say goes into the file as the nearest of them. */
const EXCEL_ERRORS = new Set(['#NULL!', '#DIV/0!', '#VALUE!', '#REF!', '#NAME?', '#NUM!', '#N/A']);

const inlineText = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t xml:space="preserve">${escText(text)}</t></is></c>`;

function cellXml(ref: string, typed: string, value: ReturnType<typeof evaluateSheet>[number][number]): string {
  if (typed === '') return '';

  const formula = excelFormula(typed);

  if (formula === null) {
    return typeof value === 'number' ? `<c r="${ref}"><v>${value}</v></c>` : inlineText(ref, typed);
  }

  const f = `<f>${escText(formula)}</f>`;

  if (typeof value === 'number') return `<c r="${ref}">${f}<v>${value}</v></c>`;
  if (typeof value === 'string') return `<c r="${ref}" t="str">${f}<v>${escText(value)}</v></c>`;
  if (typeof value === 'boolean') return `<c r="${ref}" t="b">${f}<v>${value ? 1 : 0}</v></c>`;
  if (value instanceof CellError) return `<c r="${ref}" t="e">${f}<v>${EXCEL_ERRORS.has(value.code) ? value.code : '#REF!'}</v></c>`;

  return `<c r="${ref}">${f}</c>`;
}

/** The sheet as an .xlsx file. */
export function workbookBytes(sheet: readonly (readonly string[])[]): Uint8Array {
  const cells = trimCells(sheet);
  const values = evaluateSheet(cells);
  const rows = cells
    .map((row, r) => {
      const inside = row.map((typed, c) => cellXml(cellName(r, c), typed, values[r][c])).join('');
      return inside ? `<row r="${r + 1}">${inside}</row>` : '';
    })
    .join('');

  const files: Record<string, string> = {
    '[Content_Types].xml':
      `${HEAD}<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">` +
      `<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/>` +
      `<Override PartName="/xl/workbook.xml" ContentType="${SHEET_TYPES}.sheet.main+xml"/>` +
      `<Override PartName="/xl/worksheets/sheet1.xml" ContentType="${SHEET_TYPES}.worksheet+xml"/></Types>`,
    '_rels/.rels': `${HEAD}<Relationships xmlns="${PKG_RELS}"><Relationship Id="rId1" Type="${R_NS}/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
    'xl/workbook.xml':
      `${HEAD}<workbook xmlns="${MAIN_NS}" xmlns:r="${R_NS}"><sheets><sheet name="${escAttr(SHEET)}" sheetId="1" r:id="rId1"/></sheets></workbook>`,
    'xl/_rels/workbook.xml.rels':
      `${HEAD}<Relationships xmlns="${PKG_RELS}"><Relationship Id="rId1" Type="${R_NS}/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`,
    'xl/worksheets/sheet1.xml': `${HEAD}<worksheet xmlns="${MAIN_NS}"><sheetData>${rows}</sheetData></worksheet>`,
  };

  return zipSync(Object.fromEntries(Object.entries(files).map(([name, content]) => [name, strToU8(content)])));
}

// ---- Reading -------------------------------------------------------------------------------

// A workbook's XML may or may not put a prefix on its names; either way the name after it counts.
const local = (name: string) => name.slice(name.indexOf(':') + 1);
const kids = (el: XmlEl | null | undefined, name: string): XmlEl[] => (el ? el.children.filter((c) => local(c.name) === name) : []);
const kid = (el: XmlEl | null | undefined, name: string): XmlEl | null => kids(el, name)[0] ?? null;

/** The text of a string item: its own, or its runs' put together. Phonetic guides are left out. */
const stringOf = (item: XmlEl | null): string => [...kids(item, 't'), ...kids(item, 'r').flatMap((run) => kids(run, 't'))].map((t) => t.text).join('');

/**
 * The cells of a workbook's first sheet, as the chart's sheet holds them. Null for a file that is
 * not a workbook, or one too large to be a chart's.
 */
export function readWorkbook(bytes: Uint8Array): string[][] | null {
  try {
    const files = unzipSync(bytes);
    const text = (path: string) => (files[path] ? new TextDecoder('utf-8').decode(files[path]) : null);
    const main = parseRels(text('_rels/.rels')).find((rel) => relKind(rel) === 'officeDocument');
    const bookPath = main ? resolveTarget('', main.target) : 'xl/workbook.xml';
    const bookXml = text(bookPath);
    if (!bookXml) return null;

    const slash = bookPath.lastIndexOf('/');
    const rels = parseRels(text(`${bookPath.slice(0, slash + 1)}_rels/${bookPath.slice(slash + 1)}.rels`));
    const sheet = kid(kid(parseXml(bookXml), 'sheets'), 'sheet');
    const sheetRel = rels.find((rel) => rel.id === sheet?.attrs['r:id']) ?? rels.find((rel) => relKind(rel) === 'worksheet');
    const sheetXml = sheetRel ? text(resolveTarget(bookPath, sheetRel.target)) : null;
    if (!sheetXml) return null;

    const stringsRel = rels.find((rel) => relKind(rel) === 'sharedStrings');
    const stringsXml = stringsRel ? text(resolveTarget(bookPath, stringsRel.target)) : null;
    const strings = stringsXml ? kids(parseXml(stringsXml), 'si').map(stringOf) : [];
    const cells: string[][] = [];
    let row = -1;

    for (const rowEl of kids(kid(parseXml(sheetXml), 'sheetData'), 'row')) {
      let col = -1;

      row = rowEl.attrs.r ? Number(rowEl.attrs.r) - 1 : row + 1;

      for (const c of kids(rowEl, 'c')) {
        const at = c.attrs.r ? parseCellName(c.attrs.r) : null;
        const f = kid(c, 'f');
        const v = kid(c, 'v')?.text ?? '';
        const type = c.attrs.t ?? 'n';
        let content: string;

        col = at ? at.col : col + 1;

        // A formula shared between cells is written out in one of them only; the rest keep their result.
        if (f && f.text && !f.attrs.t) content = `=${f.text}`;
        else if (type === 's') content = strings[Number(v)] ?? '';
        else if (type === 'inlineStr') content = stringOf(kid(c, 'is'));
        else if (type === 'b') content = v === '1' ? 'TRUE' : 'FALSE';
        else if (type === 'str' || type === 'e') content = v;
        else content = v === '' || !Number.isFinite(Number(v)) ? v : String(Number(v));

        if (content === '') continue;
        if (!Number.isInteger(row) || row < 0 || row >= MAX_ROWS || col < 0 || col >= MAX_COLS) return null;

        while (cells.length <= row) cells.push([]);
        while (cells[row].length <= col) cells[row].push('');

        cells[row][col] = content;
      }
    }

    return trimCells(cells);
  } catch {
    return null;
  }
}
