// styles.xml: the document's named styles, and the stylesheet the page is drawn with.
//
// A style's formatting is its own plus everything it is based on, down to the document defaults.
// That chain is resolved here into one CSS rule per style, scoped to the document's own page so
// two open documents never style each other.
//
// Word only writes a built-in style (Heading 2, Title, ...) into a file once it has been used.
// `ensureBuiltin` adds the ones this editor offers when they are first applied; `exportXml` writes
// those additions back, leaving the rest of the part as it came.

import { type XmlEl, child, escAttr, parseXml, raw, val } from './xml';
import { type Decls, type Theme, fontFamilyCss, isOn, paraDecls, ruleCss, runDecls } from './props';

export interface StyleDef {
  id: string;
  type: string;
  name: string;
  basedOn: string | null;
  next: string | null;
  isDefault: boolean;
  hidden: boolean;
  semiHidden: boolean;
  qFormat: boolean;
  uiPriority: number;
  pPr: XmlEl | null;
  rPr: XmlEl | null;
  tblPr: XmlEl | null;
  /** The whole `w:style` element, as source. */
  xml: string;
}

/**
 * Changes made in the style editor: style id → that style's whole `w:style` element as edited.
 * The document holds these (its `styleEdits` attribute), so that a change to a style is a step to
 * undo like any other; `Styles.useEdits` lays them over the styles the file came with.
 */
export type StyleEdits = Readonly<Record<string, string>>;

const NO_EDITS: StyleEdits = Object.freeze({});

function sameEdits(a: StyleEdits, b: StyleEdits): boolean {
  const keys = Object.keys(a);
  return keys.length === Object.keys(b).length && keys.every((key) => a[key] === b[key]);
}

export interface StyleChoice {
  /** A style id, or `builtin:<name>` for one that is added on first use. */
  value: string;
  label: string;
}

const W_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';

/** The built-in paragraph styles offered even where the file does not have them yet. */
const OFFERED = ['heading 1', 'heading 2', 'heading 3', 'heading 4', 'Title', 'Subtitle', 'Quote'];

const HEADINGS = [
  { size: 32, color: '2F5496', before: 240, italic: false },
  { size: 26, color: '2F5496', before: 40, italic: false },
  { size: 24, color: '1F3763', before: 40, italic: false },
  { size: 22, color: '2F5496', before: 40, italic: true },
  { size: 22, color: '2F5496', before: 40, italic: false },
  { size: 22, color: '1F3763', before: 40, italic: false },
];

const cssString = (value: string) => value.replace(/["\\\n]/g, '');

export class Styles {
  readonly byId = new Map<string, StyleDef>();
  defaultParagraph: string | null = null;
  docRPr: XmlEl | null = null;
  docPPr: XmlEl | null = null;
  /** Styles added since the file was opened, as XML, for `exportXml`. */
  readonly added: string[] = [];
  /** Goes up whenever a style is added, so the page knows its stylesheet is out of date. */
  version = 0;
  /** The style editor's changes as the document has them, a preview laid over those, and what is shown. */
  private edits: StyleEdits = NO_EDITS;
  private preview: StyleEdits | null = null;
  private applied: StyleEdits = NO_EDITS;
  /** Each edited style as it was before any edit; null for a style the editor made. */
  private readonly unedited = new Map<string, StyleDef | null>();

  constructor(readonly theme: Theme) {}

  static parse(xml: string | null, theme: Theme): Styles {
    const styles = new Styles(theme);
    if (!xml) return styles;

    const root = parseXml(xml);
    const defaults = child(root, 'w:docDefaults');

    styles.docRPr = child(child(defaults, 'w:rPrDefault'), 'w:rPr');
    styles.docPPr = child(child(defaults, 'w:pPrDefault'), 'w:pPr');

    for (const el of root.children) {
      if (el.name === 'w:style') styles.read(el);
    }

    return styles;
  }

  private read(el: XmlEl): StyleDef | null {
    const id = el.attrs['w:styleId'];
    if (!id) return null;

    const def: StyleDef = {
      id,
      type: el.attrs['w:type'] ?? 'paragraph',
      name: val(el, 'w:name') ?? id,
      basedOn: val(el, 'w:basedOn'),
      next: val(el, 'w:next'),
      isDefault: el.attrs['w:default'] === '1' || el.attrs['w:default'] === 'true',
      hidden: isOn(child(el, 'w:hidden')),
      semiHidden: isOn(child(el, 'w:semiHidden')),
      qFormat: isOn(child(el, 'w:qFormat')),
      uiPriority: Number(val(el, 'w:uiPriority') ?? 99),
      pPr: child(el, 'w:pPr'),
      rPr: child(el, 'w:rPr'),
      tblPr: child(el, 'w:tblPr'),
      xml: raw(el),
    };

    this.byId.set(id, def);

    if (def.isDefault && def.type === 'paragraph') {
      this.defaultParagraph = id;
    }

    return def;
  }

  /** The style and everything it is based on, the furthest ancestor first. */
  chain(id: string | null): StyleDef[] {
    const chain: StyleDef[] = [];
    const seen = new Set<string>();
    let at = id;

    while (at && !seen.has(at)) {
      const def = this.byId.get(at);
      if (!def) break;
      seen.add(at);
      chain.unshift(def);
      at = def.basedOn;
    }

    return chain;
  }

  /** Built-in styles keep their English name in every language of Word; their ids do not. */
  byName(name: string, type = 'paragraph'): StyleDef | null {
    const wanted = name.toLowerCase();

    for (const def of this.byId.values()) {
      if (def.type === type && def.name.toLowerCase() === wanted) return def;
    }

    return null;
  }

  displayName(def: StyleDef): string {
    return /^heading \d$/i.test(def.name) ? `Heading ${def.name.slice(-1)}` : def.name;
  }

  /** What the style box offers: the styles Word shows in its gallery, then the rest. */
  choices(): StyleChoice[] {
    const defs = [...this.byId.values()].filter((def) => def.type === 'paragraph' && !def.hidden && !def.semiHidden);

    defs.sort((a, b) => Number(b.qFormat) - Number(a.qFormat) || a.uiPriority - b.uiPriority || a.name.localeCompare(b.name, undefined, { numeric: true }));

    const choices = defs.map((def) => ({ value: def.id, label: this.displayName(def) }));

    for (const name of OFFERED) {
      if (!this.byName(name)) {
        choices.push({ value: `builtin:${name}`, label: /^heading/.test(name) ? `Heading ${name.slice(-1)}` : name });
      }
    }

    return choices;
  }

  /** The style a new paragraph gets after one in this style: Normal after a heading, for one. */
  nextOf(id: string | null): string | null {
    const def = id ? this.byId.get(id) : null;
    return def?.next && this.byId.has(def.next) ? def.next : null;
  }

  /** Numbering a style brings with it, as numbered headings do. */
  numPrOf(id: string | null): { numId: number; ilvl: number | null } | null {
    const chain = this.chain(id ?? this.defaultParagraph);

    for (let i = chain.length - 1; i >= 0; i--) {
      const numPr = child(chain[i].pPr, 'w:numPr');
      const numId = val(numPr, 'w:numId');

      if (numPr && numId !== null) {
        const ilvl = val(numPr, 'w:ilvl');
        return { numId: Number(numId), ilvl: ilvl === null ? null : Number(ilvl) };
      }
    }

    return null;
  }

  /** Whether the style, or one it is based on, sets its own indent. */
  hasIndent(id: string | null): boolean {
    return this.chain(id).some((def) => child(def.pPr, 'w:ind') !== null);
  }

  private resolved(id: string | null): Decls {
    const d: Decls = {};

    for (const def of this.chain(id)) {
      Object.assign(d, paraDecls(def.pPr), runDecls(def.rPr, this.theme));
    }

    return d;
  }

  /**
   * What text looks like before any style has a say: the document's defaults, and under those
   * Word's own, which are 10 point Times New Roman.
   */
  private baseRun(): Decls {
    return { 'font-family': fontFamilyCss('Times New Roman'), 'font-size': '10pt', ...runDecls(this.docRPr, this.theme) };
  }

  /** The font and size text in this paragraph style has when nothing else is set on it. */
  runOf(id: string | null): { font: string | null; size: number | null } {
    const d = { ...this.baseRun(), ...this.resolved(id ?? this.defaultParagraph) };
    const font = /^"([^"]+)"/.exec(d['font-family'] ?? '')?.[1] ?? null;
    const size = d['font-size']?.endsWith('pt') ? parseFloat(d['font-size']) : null;

    return { font, size };
  }

  /** Whether a table draws its grid: from its own borders, or failing that its style's. */
  tableHasBorders(tblPr: XmlEl | null): boolean {
    const drawn = (borders: XmlEl | null) =>
      borders ? borders.children.some((side) => side.attrs['w:val'] && side.attrs['w:val'] !== 'nil' && side.attrs['w:val'] !== 'none') : null;

    const own = drawn(child(tblPr, 'w:tblBorders'));
    if (own !== null) return own;

    const chain = this.chain(val(tblPr, 'w:tblStyle'));

    for (let i = chain.length - 1; i >= 0; i--) {
      const fromStyle = drawn(child(chain[i].tblPr, 'w:tblBorders'));
      if (fromStyle !== null) return fromStyle;
    }

    return false;
  }

  /**
   * The stylesheet for one document's page. `scope` is a selector for that page; its dark and
   * tinted variants are the same element with data-mode="dark" and data-mode="tint".
   */
  css(scope: string): string {
    let css = '';

    css += ruleCss(scope, ['.ProseMirror'], this.baseRun());
    css += ruleCss(scope, ['p'], paraDecls(this.docPPr));

    // A table style's paragraph settings sit between the document defaults and paragraph styles.
    // :where() keeps these rules weaker than the paragraph styles' own.
    for (const def of this.byId.values()) {
      if (def.type !== 'table') continue;

      const d: Decls = {};
      for (const link of this.chain(def.id)) Object.assign(d, paraDecls(link.pPr), runDecls(link.rPr, this.theme));

      const where = `:where(table[data-tstyle="${cssString(def.id)}"]) p`;
      css += ruleCss(scope, [where], d);
    }

    for (const def of this.byId.values()) {
      if (def.type === 'paragraph') {
        const id = cssString(def.id);
        const selectors = [`p[data-style="${id}"]`];
        if (def.id === this.defaultParagraph) selectors.push('p[data-style=""]');

        css += ruleCss(scope, selectors, this.resolved(def.id));

        // "Don't add space between paragraphs of the same style", which is what keeps lists tight.
        if (this.chain(def.id).some((link) => isOn(child(link.pPr, 'w:contextualSpacing')))) {
          const p = `${scope} p[data-style="${id}"]`;
          css += `${p}:has(+ p[data-style="${id}"]){margin-bottom:0}\n${p} + p[data-style="${id}"]{margin-top:0}\n`;
        }
      } else if (def.type === 'character') {
        const d: Decls = {};
        for (const link of this.chain(def.id)) Object.assign(d, runDecls(link.rPr, this.theme));

        const span = `span[data-cs="${cssString(def.id)}"]`;
        css += ruleCss(scope, [span], d);
      }
    }

    return css;
  }

  private freeId(wanted: string): string {
    let id = wanted;
    for (let n = 2; this.byId.has(id); n++) id = `${wanted}${n}`;
    return id;
  }

  /**
   * The id of a built-in style, adding its definition if the file has none yet. Null for a name
   * this editor has no definition for.
   */
  ensureBuiltin(name: string, type = 'paragraph'): string | null {
    const existing = this.byName(name, type);
    if (existing) return existing.id;

    const normal = this.defaultParagraph;
    const based = normal ? `<w:basedOn w:val="${escAttr(normal)}"/>` : '';
    const next = normal ? `<w:next w:val="${escAttr(normal)}"/>` : '';
    const major = escAttr(this.theme.major);
    const fonts = `<w:rFonts w:ascii="${major}" w:hAnsi="${major}" w:eastAsia="${major}" w:cs="${major}"/>`;
    const heading = /^heading ([1-6])$/.exec(name);
    let id: string;
    let xml: string;

    if (heading) {
      const level = Number(heading[1]);
      const look = HEADINGS[level - 1];

      id = this.freeId(`Heading${level}`);
      xml =
        `<w:style w:type="paragraph" w:styleId="${id}"><w:name w:val="heading ${level}"/>${based}${next}<w:uiPriority w:val="9"/><w:qFormat/>` +
        `<w:pPr><w:keepNext/><w:keepLines/><w:spacing w:before="${look.before}" w:after="0"/><w:outlineLvl w:val="${level - 1}"/></w:pPr>` +
        `<w:rPr>${fonts}${look.italic ? '<w:i/><w:iCs/>' : ''}<w:color w:val="${look.color}"/><w:sz w:val="${look.size}"/><w:szCs w:val="${look.size}"/></w:rPr></w:style>`;
    } else if (name === 'Title') {
      id = this.freeId('Title');
      xml =
        `<w:style w:type="paragraph" w:styleId="${id}"><w:name w:val="Title"/>${based}${next}<w:uiPriority w:val="10"/><w:qFormat/>` +
        `<w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/><w:contextualSpacing/></w:pPr>` +
        `<w:rPr>${fonts}<w:spacing w:val="-10"/><w:kern w:val="28"/><w:sz w:val="56"/><w:szCs w:val="56"/></w:rPr></w:style>`;
    } else if (name === 'Subtitle') {
      id = this.freeId('Subtitle');
      xml =
        `<w:style w:type="paragraph" w:styleId="${id}"><w:name w:val="Subtitle"/>${based}${next}<w:uiPriority w:val="11"/><w:qFormat/>` +
        `<w:rPr><w:color w:val="5A5A5A"/><w:spacing w:val="15"/></w:rPr></w:style>`;
    } else if (name === 'Quote') {
      id = this.freeId('Quote');
      xml =
        `<w:style w:type="paragraph" w:styleId="${id}"><w:name w:val="Quote"/>${based}${next}<w:uiPriority w:val="29"/><w:qFormat/>` +
        `<w:pPr><w:spacing w:before="200"/><w:ind w:left="864" w:right="864"/><w:jc w:val="center"/></w:pPr>` +
        `<w:rPr><w:i/><w:iCs/><w:color w:val="404040"/></w:rPr></w:style>`;
    } else if (name === 'List Paragraph') {
      id = this.freeId('ListParagraph');
      xml =
        `<w:style w:type="paragraph" w:styleId="${id}"><w:name w:val="List Paragraph"/>${based}<w:uiPriority w:val="34"/><w:qFormat/>` +
        `<w:pPr><w:ind w:left="720"/><w:contextualSpacing/></w:pPr></w:style>`;
    } else if (name === 'Hyperlink' && type === 'character') {
      const font = this.byName('Default Paragraph Font', 'character');

      id = this.freeId('Hyperlink');
      xml =
        `<w:style w:type="character" w:styleId="${id}"><w:name w:val="Hyperlink"/>${font ? `<w:basedOn w:val="${escAttr(font.id)}"/>` : ''}` +
        `<w:uiPriority w:val="99"/><w:unhideWhenUsed/><w:rPr><w:color w:val="0563C1"/><w:u w:val="single"/></w:rPr></w:style>`;
    } else if (name === 'Table Grid' && type === 'table') {
      const base = this.byName('Normal Table', 'table');
      const side = (which: string) => `<w:${which} w:val="single" w:sz="4" w:space="0" w:color="auto"/>`;

      id = this.freeId('TableGrid');
      xml =
        `<w:style w:type="table" w:styleId="${id}"><w:name w:val="Table Grid"/>${base ? `<w:basedOn w:val="${escAttr(base.id)}"/>` : ''}<w:uiPriority w:val="39"/>` +
        `<w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/></w:pPr>` +
        `<w:tblPr><w:tblBorders>${['top', 'left', 'bottom', 'right', 'insideH', 'insideV'].map(side).join('')}</w:tblBorders></w:tblPr></w:style>`;
    } else {
      return null;
    }

    this.read(parseXml(xml));
    this.added.push(xml);
    this.version++;

    return id;
  }

  /**
   * Adds a style this class has no definition for: `make` gets a free id (the wanted one, or one
   * like it) and returns the `w:style` element. Returns the id.
   */
  addDefinition(wantedId: string, make: (id: string) => string): string {
    const id = this.freeId(wantedId);
    const xml = make(id);

    this.read(parseXml(xml));
    this.added.push(xml);
    this.version++;

    return id;
  }

  /** The edits the document holds. Answers whether anything shown changed. */
  useEdits(edits: StyleEdits | null | undefined): boolean {
    this.edits = edits ?? NO_EDITS;
    return this.applyEdits();
  }

  /** Edits shown on the page but not (yet) in the document: the style editor's live preview. */
  previewEdits(preview: StyleEdits | null): boolean {
    this.preview = preview;
    return this.applyEdits();
  }

  /** The edits the document holds, for the next change to build on. */
  currentEdits(): StyleEdits {
    return this.edits;
  }

  private applyEdits(): boolean {
    const next = this.preview ? { ...this.edits, ...this.preview } : this.edits;
    if (sameEdits(next, this.applied)) return false;

    for (const id of Object.keys(this.applied)) {
      if (id in next) continue;

      const before = this.unedited.get(id);
      if (before) this.byId.set(id, before);
      else this.byId.delete(id);
      if (before?.isDefault && before.type === 'paragraph') this.defaultParagraph = id;
    }

    for (const [id, xml] of Object.entries(next)) {
      if (this.applied[id] === xml) continue;
      if (!this.unedited.has(id)) this.unedited.set(id, this.byId.get(id) ?? null);
      this.read(parseXml(xml));
    }

    this.applied = next;
    this.version++;
    return true;
  }

  /** A style id not yet taken, made from a name: "My Quote" → "MyQuote". */
  idFor(name: string): string {
    return this.freeId(name.replace(/[^A-Za-z0-9]/g, '') || 'Style');
  }

  /**
   * styles.xml with the added styles in it, and the style editor's changes: each edited style's
   * element is replaced where it stands, every other byte stays. Null when the part needs no change.
   */
  exportXml(original: string | null): string | null {
    const edits = this.edits;
    const edited = Object.keys(edits);

    if (!this.added.length && !edited.length) return null;

    const idOf = (xml: string) => /w:styleId="([^"]*)"/.exec(xml)?.[1] ?? '';
    const placed = new Set<string>();
    const added = this.added
      .map((xml) => {
        const id = idOf(xml);
        placed.add(id);
        return edits[id] ?? xml;
      })
      .join('');

    if (!original) {
      const fresh = edited.filter((id) => !placed.has(id)).map((id) => edits[id]).join('');
      return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:styles xmlns:w="${W_NS}">${added}${fresh}</w:styles>`;
    }

    const root = parseXml(original);
    const swaps: { start: number; end: number; xml: string }[] = [];

    for (const el of root.children) {
      const id = el.name === 'w:style' ? el.attrs['w:styleId'] : undefined;

      if (id !== undefined && !placed.has(id) && id in edits) {
        swaps.push({ start: el.start, end: el.end, xml: edits[id] });
        placed.add(id);
      }
    }

    const fresh = edited.filter((id) => !placed.has(id)).map((id) => edits[id]).join('');
    let out = original.slice(0, root.innerEnd) + added + fresh + original.slice(root.innerEnd);

    for (const swap of swaps.reverse()) out = out.slice(0, swap.start) + swap.xml + out.slice(swap.end);

    return out;
  }
}

/** The font a run has when it names none: the default paragraph style's, for the font box. */
export function defaultFontCss(styles: Styles): string {
  const font = styles.runOf(null).font;
  return font ? fontFamilyCss(font) : '';
}
