// Document statistics: words, characters, sentences, how hard the text is to read, and how the
// words are spread over the sections. Nothing here knows about the screen.

import type { Node as PMNode } from 'prosemirror-model';
import { headingLevel, type StyleLevel } from './outline';

export type Lang = 'en' | 'de';

export interface Counts {
  /** Runs of anything but space, as the status bar counts them. */
  words: number;
  characters: number;
  charactersNoSpaces: number;
  /** Paragraphs with something in them. */
  paragraphs: number;
  sentences: number;
  /** Words made of letters, which the readability scores are worked out from. */
  readableWords: number;
  syllables: number;
  /** Words of three syllables or more. */
  polysyllables: number;
  /** Words of one syllable. */
  monosyllables: number;
  /** Words of more than six letters. */
  longWords: number;
}

const EMPTY_COUNTS: Counts = {
  words: 0, characters: 0, charactersNoSpaces: 0, paragraphs: 0, sentences: 0, readableWords: 0, syllables: 0, polysyllables: 0, monosyllables: 0, longWords: 0,
};

// ---- Syllables -----------------------------------------------------------------------------------

/** Syllables in an English word, by the usual rule of thumb: groups of vowels, less a silent e. */
function syllablesEn(word: string): number {
  let w = word.toLowerCase().replace(/[^a-z]/g, '');
  if (!w) return 0;
  if (w.length <= 3) return 1;

  w = w.replace(/(?:[^laeiouy]es|[^laeiouytd]ed|[^laeiouy]e)$/, (end) => end[0]).replace(/^y/, '');
  return Math.max(1, w.match(/[aeiouy]{1,2}/g)?.length ?? 0);
}

/** Syllables in a German word: groups of vowels, a diphthong or a doubled vowel being one. */
function syllablesDe(word: string): number {
  const w = word.toLowerCase().replace(/[^a-zäöüßy]/g, '');
  if (!w) return 0;
  return Math.max(1, w.match(/äu|eu|au|ei|ai|ey|ay|ie|aa|ee|oo|[aeiouyäöü]/g)?.length ?? 0);
}

/** The number of syllables in a word; the parts of a hyphenated word are counted each. */
export function syllables(word: string, lang: Lang): number {
  const count = lang === 'de' ? syllablesDe : syllablesEn;
  return word.split(/[-‐–]/).reduce((sum, part) => sum + count(part), 0);
}

// ---- Counting ------------------------------------------------------------------------------------

/** Abbreviations whose full stop does not end a sentence. */
const ABBREVIATIONS = new Set([
  'e.g.', 'i.e.', 'etc.', 'vs.', 'cf.', 'mr.', 'mrs.', 'ms.', 'dr.', 'prof.', 'st.', 'no.', 'fig.', 'p.', 'pp.', 'vol.', 'ed.', 'eds.', 'al.', 'approx.',
  'z.b.', 'd.h.', 'u.a.', 'usw.', 'bzw.', 'vgl.', 'ca.', 'nr.', 'abb.', 'evtl.', 'ggf.', 's.', 'bspw.', 'inkl.', 'zzgl.', 'sog.', 'hrsg.',
]);

const HAS_WORD = /[\p{L}\p{N}]/u;
const READABLE = /[\p{L}\p{M}]+(?:['’‐-][\p{L}\p{M}]+)*/gu;

/** How many sentences a paragraph has. A paragraph with words and no full stop is one. */
export function sentencesIn(text: string): number {
  const ends = /[.!?…]+["'”’»«)\]]*(?=\s|$)/g;
  let count = 0;
  let start = 0;

  for (let m = ends.exec(text); m; m = ends.exec(text)) {
    const end = m.index + m[0].length;
    const piece = text.slice(start, end);
    const last = /(\S+)$/.exec(piece)?.[1].toLowerCase() ?? '';

    // An abbreviation, or an initial ("J. Smith"), does not end the sentence.
    if (m[0] === '.' && (ABBREVIATIONS.has(last) || /^\p{Lu}\.$/u.test(/(\S+)$/.exec(piece)?.[1] ?? '') || /^(\p{L}\.){2,}$/u.test(last))) continue;

    if (HAS_WORD.test(piece)) {
      count++;
      start = end;
    }
  }

  if (HAS_WORD.test(text.slice(start))) count++;
  return count;
}

/** Counts the words, characters, sentences and syllables of some paragraphs. */
export function countText(paragraphs: readonly string[], lang: Lang): Counts {
  const c = { ...EMPTY_COUNTS };

  for (const text of paragraphs) {
    const chars = [...text];

    c.characters += chars.length;
    c.charactersNoSpaces += chars.filter((ch) => !/\s/.test(ch)).length;
    c.words += text.match(/\S+/g)?.length ?? 0;
    if (!text.trim()) continue;

    c.paragraphs++;
    c.sentences += sentencesIn(text);

    for (const word of text.match(READABLE) ?? []) {
      const n = syllables(word, lang);
      if (!n) continue;

      c.readableWords++;
      c.syllables += n;
      if (n >= 3) c.polysyllables++;
      if (n === 1) c.monosyllables++;
      if ([...word.replace(/['’‐-]/g, '')].length > 6) c.longWords++;
    }
  }

  return c;
}

// ---- Readability ---------------------------------------------------------------------------------

export interface Score {
  name: string;
  value: number;
  /** What the value means, in a few words. */
  meaning: string;
  /** Whether a higher value means easier text. */
  higherIsEasier: boolean;
}

/** Flesch's scale, which Amstad's German version shares. */
function easeMeaning(value: number): string {
  if (value >= 90) return 'Very easy';
  if (value >= 80) return 'Easy';
  if (value >= 70) return 'Fairly easy';
  if (value >= 60) return 'Plain';
  if (value >= 50) return 'Fairly difficult';
  if (value >= 30) return 'Difficult';
  return 'Very difficult';
}

const gradeMeaning = (grade: number) => (grade < 1 ? 'Below school grade 1' : grade > 16 ? 'University and above' : `About school grade ${Math.round(grade)}`);

const round1 = (n: number) => Math.round(n * 10) / 10;

/**
 * The readability scores for the language: Flesch Reading Ease and the Flesch-Kincaid grade for
 * English; Amstad's Flesch for German and the first Wiener Sachtextformel. None without sentences.
 */
export function readability(c: Counts, lang: Lang): Score[] {
  if (!c.sentences || !c.readableWords) return [];

  const asl = c.readableWords / c.sentences;
  const asw = c.syllables / c.readableWords;

  if (lang === 'de') {
    const amstad = 180 - asl - 58.5 * asw;
    const pct = (n: number) => (100 * n) / c.readableWords;
    const wstf = 0.1935 * pct(c.polysyllables) + 0.1672 * asl + 0.1297 * pct(c.longWords) - 0.0327 * pct(c.monosyllables) - 0.875;

    return [
      { name: 'Flesch (Amstad)', value: round1(amstad), meaning: easeMeaning(amstad), higherIsEasier: true },
      { name: 'Wiener Sachtextformel', value: round1(wstf), meaning: wstf < 4 ? 'Very easy' : wstf > 15 ? 'Very difficult' : `About school year ${Math.round(wstf)}`, higherIsEasier: false },
    ];
  }

  const ease = 206.835 - 1.015 * asl - 84.6 * asw;
  const grade = 0.39 * asl + 11.8 * asw - 15.59;

  return [
    { name: 'Flesch Reading Ease', value: round1(ease), meaning: easeMeaning(ease), higherIsEasier: true },
    { name: 'Flesch-Kincaid grade', value: round1(grade), meaning: gradeMeaning(grade), higherIsEasier: false },
  ];
}

// ---- Language ------------------------------------------------------------------------------------

const STOP_EN = new Set('the of and to in is that it for was on are as with be by this have from or at which but not an they were you we has had their there been would can will its'.split(' '));
const STOP_DE = new Set('der die und in den von zu das mit sich des auf für ist im dem nicht ein eine als auch es an werden aus er hat dass sie nach wird bei einer um am sind noch wie einem über einen so zum war haben nur oder aber vor zur bis mehr durch man'.split(' '));

/** The language a text reads as, by its commonest words; null when it is not clear. */
export function guessLanguage(text: string): Lang | null {
  let en = 0;
  let de = 0;

  for (const word of text.toLowerCase().match(/[\p{L}]+/gu) ?? []) {
    if (STOP_EN.has(word)) en++;
    if (STOP_DE.has(word)) de++;
    if (/[äöüß]/.test(word)) de += 0.5;
  }

  if (de >= 3 && de > en * 1.5) return 'de';
  if (en >= 3 && en > de * 1.5) return 'en';
  return null;
}

/** `de-DE` → `de`; a language the scores are not made for → null. */
export function langOf(tag: string | null | undefined): Lang | null {
  const base = tag?.toLowerCase().split(/[-_]/)[0];
  return base === 'de' || base === 'en' ? base : null;
}

/** The language most of the text is marked as in the file (`w:lang`), or null. */
export function declaredLanguage(doc: PMNode, fallback: string | null): Lang | null {
  const chars = new Map<string, number>();

  doc.descendants((node) => {
    if (!node.isText) return true;

    const raw = node.marks.find((m) => m.type.name === 'rawRPr')?.attrs.xml as string | undefined;
    const tag = (raw && /<w:lang\b[^>]*w:val="([^"]+)"/.exec(raw)?.[1]) || fallback || '';
    chars.set(tag, (chars.get(tag) ?? 0) + node.text!.length);
    return false;
  });

  let best: string | null = null;
  for (const [tag, n] of chars) if (best === null || n > chars.get(best)!) best = tag;

  return langOf(best);
}

// ---- The whole document ------------------------------------------------------------------------

export interface Section {
  /** The heading's text, or null for what comes before the first heading. */
  title: string | null;
  level: number;
  pos: number;
  words: number;
}

export interface DocumentStats {
  counts: Counts;
  lang: Lang;
  /** Where the language came from. */
  langFrom: 'text' | 'file' | 'default' | 'chosen';
  scores: Score[];
  sections: Section[];
}

/** Every paragraph's text in order, with the outline level of those that are headings. */
export function paragraphsOf(doc: PMNode, styleLevel: StyleLevel | null): { text: string; level: number | null; pos: number }[] {
  const out: { text: string; level: number | null; pos: number }[] = [];

  doc.descendants((node, pos) => {
    if (!node.isTextblock) return true;
    out.push({ text: node.textContent, level: node.type.name === 'paragraph' ? headingLevel(node, styleLevel) : null, pos });
    return false;
  });

  return out;
}

export function documentStats(doc: PMNode, options: { styleLevel?: StyleLevel | null; fileLang?: string | null; lang?: Lang | null } = {}): DocumentStats {
  const paragraphs = paragraphsOf(doc, options.styleLevel ?? null);
  const texts = paragraphs.map((p) => p.text);

  let lang: Lang = 'en';
  let langFrom: DocumentStats['langFrom'] = 'default';

  if (options.lang) {
    lang = options.lang;
    langFrom = 'chosen';
  } else {
    const guessed = guessLanguage(texts.join('\n').slice(0, 200000));
    const declared = guessed ? null : declaredLanguage(doc, options.fileLang ?? null);

    if (guessed) [lang, langFrom] = [guessed, 'text'];
    else if (declared) [lang, langFrom] = [declared, 'file'];
  }

  const counts = countText(texts, lang);
  const sections: Section[] = [];

  for (const p of paragraphs) {
    if (p.level && p.text.trim()) sections.push({ title: p.text.replace(/\s+/g, ' ').trim(), level: p.level, pos: p.pos, words: 0 });
    else if (!sections.length) sections.push({ title: null, level: 0, pos: 0, words: 0 });

    sections[sections.length - 1].words += p.text.match(/\S+/g)?.length ?? 0;
  }

  // Nothing before the first heading: no section for it.
  if (sections[0]?.title === null && !sections[0].words && sections.length > 1) sections.shift();

  return { counts, lang, langFrom, scores: readability(counts, lang), sections };
}

// ---- A limit -------------------------------------------------------------------------------------

export interface CountLimit {
  unit: 'words' | 'characters';
  value: number;
}

export function parseLimit(json: string | null): CountLimit | null {
  try {
    const v = JSON.parse(json ?? 'null');
    if (v && (v.unit === 'words' || v.unit === 'characters') && Number.isFinite(v.value) && v.value > 0) return { unit: v.unit, value: Math.round(v.value) };
  } catch {
    // Not a limit.
  }
  return null;
}

/** How far the document is towards its limit. */
export function limitState(words: number, characters: number, limit: CountLimit): { used: number; over: boolean; fraction: number } {
  const used = limit.unit === 'words' ? words : characters;
  return { used, over: used > limit.value, fraction: used / limit.value };
}
