// Which palette the editor wears, and what that means for the page.
//
// The palettes themselves are CSS, in styles/themes.css. This file knows their names and tones,
// remembers the one that was picked, and works out the numbers the page's colour mappings need:
// how light the paper and the ink of the theme are for the dark page, and the paper's red, green
// and blue for the tinted one (page.css explains what they are for).

import { desktop } from '../desktop';
import { h } from './dom';

export type Tone = 'light' | 'medium' | 'dark';

export interface Theme {
  id: string;
  label: string;
  tone: Tone;
}

export const THEMES: Theme[] = [
  { id: 'paper', label: 'Paper', tone: 'light' },
  { id: 'linen', label: 'Linen', tone: 'light' },
  { id: 'frost', label: 'Frost', tone: 'light' },
  { id: 'blossom', label: 'Blossom', tone: 'light' },
  { id: 'meadow', label: 'Meadow', tone: 'light' },
  { id: 'slate', label: 'Slate', tone: 'medium' },
  { id: 'dusk', label: 'Dusk', tone: 'medium' },
  { id: 'moss', label: 'Moss', tone: 'medium' },
  { id: 'clay', label: 'Clay', tone: 'medium' },
  { id: 'harbor', label: 'Harbor', tone: 'medium' },
  { id: 'studio', label: 'Studio', tone: 'dark' },
  { id: 'ember', label: 'Ember', tone: 'dark' },
  { id: 'deep-sea', label: 'Deep Sea', tone: 'dark' },
  { id: 'forest', label: 'Forest', tone: 'dark' },
  { id: 'plum', label: 'Plum', tone: 'dark' },
  { id: 'carbon', label: 'Carbon', tone: 'dark' },
];

const TONES: { id: Tone; label: string }[] = [
  { id: 'light', label: 'Light' },
  { id: 'medium', label: 'Medium' },
  { id: 'dark', label: 'Dark' },
];

const KEY = 'text-studio:theme';
const DEFAULT = 'studio';

const find = (id: string | null) => THEMES.find((theme) => theme.id === id) ?? THEMES.find((theme) => theme.id === DEFAULT)!;

/** A colour's red, green and blue, each 0 to 1. Null for anything but #rrggbb. */
function channels(hex: string): number[] | null {
  const value = /^#([0-9a-f]{6})$/i.exec(hex.trim())?.[1];

  return value ? [0, 2, 4].map((at) => parseInt(value.slice(at, at + 2), 16) / 255) : null;
}

/** How light a colour is, 0 to 1, on the scale the page's colour mapping works in (OKLCH). */
function lightness(hex: string): number {
  const rgb = channels(hex);
  if (!rgb) return 0.5;

  const [r, g, b] = rgb.map((c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4));

  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);

  return 0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s;
}

let current = find(null);
let tinted = false;

export const currentTheme = (): Theme => current;

/** Whether the theme in use is a light one whose paper is a shade off white, which the page can take. */
export const paperIsTinted = (): boolean => tinted;

/** Wears a theme: the palette, the numbers for the page, and the window's own buttons. */
export function applyTheme(id: string | null): Theme {
  const root = document.documentElement;

  current = find(id);
  root.dataset.theme = current.id;
  root.dataset.tone = current.tone;

  const style = getComputedStyle(root);
  const paper = style.getPropertyValue('--bg');
  const ink = style.getPropertyValue('--ink');

  const rgb = channels(paper) ?? [1, 1, 1];

  root.style.setProperty('--pl', lightness(paper).toFixed(3));
  root.style.setProperty('--il', lightness(ink).toFixed(3));
  ['--pr', '--pg', '--pb'].forEach((name, at) => root.style.setProperty(name, rgb[at].toFixed(4)));
  tinted = current.tone === 'light' && rgb.some((c) => c < 1);
  desktop.setChrome(style.getPropertyValue('--bg-2').trim(), style.getPropertyValue('--ink-dim').trim());

  return current;
}

export function chooseTheme(id: string): Theme {
  const theme = applyTheme(id);

  try {
    localStorage.setItem(KEY, theme.id);
  } catch {
    // Storage switched off: the choice lasts for this run.
  }

  return theme;
}

export function savedTheme(): string | null {
  try {
    return localStorage.getItem(KEY);
  } catch {
    return null;
  }
}

/** The theme menu: one column per tone, each sample drawn in its own theme's colours. */
export function themeMenu(onPick: (theme: Theme) => void): HTMLElement {
  const columns = h('div', { class: 'theme-columns' });

  for (const tone of TONES) {
    const column = h('div', { class: 'theme-column' }, h('div', { class: 'menu-label' }, tone.label));

    for (const theme of THEMES.filter((t) => t.tone === tone.id)) {
      const sample = h(
        'button',
        {
          class: theme.id === current.id ? 'theme-sample current' : 'theme-sample',
          'data-theme': theme.id,
          onclick: () => {
            // The menu stays open, so themes can be clicked through and compared.
            onPick(chooseTheme(theme.id));
            columns.querySelector('.current')?.classList.remove('current');
            sample.classList.add('current');
          },
        },
        h('i'),
        theme.label,
      );

      column.append(sample);
    }

    columns.append(column);
  }

  return columns;
}
