// The outline pane at the workspace's left edge: the document's headings, to jump between. The
// section the cursor is in is marked, and the list follows the document as it is written.

import { TextSelection } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { type Heading, outline, sectionAt, type StyleLevel, styleLevels } from '../editor/outline';
import type { Styles } from '../docx/styles';
import { h, keepFocus, store, stored } from './dom';
import { icon } from './icons';

const OPEN_KEY = 'text-studio:outline-open';

export interface OutlineHost {
  tab(): { view: EditorView; ctx: DocContext } | null;
  /** The pane opened or closed: the documents make room for it. */
  layout(): void;
}

export class OutlinePane {
  readonly el = h('aside', { class: 'outline', hidden: true, 'aria-label': 'Outline' });
  /** The status bar's switch for the pane. */
  readonly button = h('button', { class: 'status-button', title: 'Outline: the headings, to jump between (Ctrl+Shift+O)', onclick: () => this.toggle() });

  private readonly list = h('div', { class: 'outline-list', role: 'tree' });
  private readonly empty = h('p', { class: 'outline-empty' }, 'No headings yet. Paragraphs in a Heading style show here.');
  private headings: Heading[] = [];
  private rows: HTMLElement[] = [];
  private signature = '';
  private current = -1;
  /** Headings whose subheadings are folded away, by their place in the list and text. */
  private readonly folded = new Set<string>();
  private levels: { styles: Styles; version: number; level: StyleLevel } | null = null;

  constructor(private readonly host: OutlineHost) {
    keepFocus(this.el);

    this.el.append(
      h(
        'div',
        { class: 'outline-head' },
        h('span', { class: 'outline-title' }, 'Outline'),
        h('button', { class: 'tool', title: 'Close the outline (Ctrl+Shift+O)', html: icon('close'), onclick: () => this.toggle() }),
      ),
      this.list,
      this.empty,
    );

    this.button.innerHTML = `<span class="glyph">☰</span>Outline`;
    // Opened again as it was left, once the window around it is built.
    if (stored(OPEN_KEY) === 'on') queueMicrotask(() => this.show(true));
  }

  get isOpen(): boolean {
    return !this.el.hidden;
  }

  toggle(): void {
    this.show(!this.isOpen);
    store(OPEN_KEY, this.isOpen ? 'on' : 'off');
  }

  private show(open: boolean): void {
    this.el.hidden = !open;
    this.button.setAttribute('aria-pressed', String(open));
    this.signature = '';
    this.host.layout();
    this.refresh();
  }

  /** The document or the cursor moved: the list and the marked section follow. */
  refresh(): void {
    if (!this.isOpen) return;

    const tab = this.host.tab();
    if (!tab) {
      this.draw([]);
      return;
    }

    const { styles } = tab.ctx;
    if (!this.levels || this.levels.styles !== styles || this.levels.version !== styles.version) {
      this.levels = { styles, version: styles.version, level: styleLevels(styles) };
      this.signature = '';
    }

    const headings = outline(tab.view.state.doc, this.levels.level);
    const signature = headings.map((x) => `${x.level}\u0001${x.text}`).join('\u0000');

    this.headings = headings;
    if (signature !== this.signature) {
      this.signature = signature;
      this.draw(headings);
    }

    this.mark(sectionAt(headings, tab.view.state.selection.from));
  }

  private keyOf(index: number): string {
    return `${index}\u0000${this.headings[index]?.text}`;
  }

  private draw(headings: Heading[]): void {
    this.headings = headings;
    this.empty.hidden = headings.length > 0;
    this.current = -1;

    this.rows = headings.map((heading, i) => {
      const hasChildren = headings[i + 1]?.level > heading.level;
      const fold = h('button', { class: 'outline-fold', tabindex: '-1', title: 'Fold or unfold the subheadings', html: hasChildren ? icon('chevron') : '' });
      const row = h(
        'div',
        { class: 'outline-item', role: 'treeitem', style: `--level:${heading.level}`, title: heading.text },
        fold,
        h('span', { class: 'outline-text' }, heading.text),
      );

      if (!hasChildren) fold.disabled = true;
      fold.addEventListener('click', (event) => {
        event.stopPropagation();
        const key = this.keyOf(i);
        if (this.folded.has(key)) this.folded.delete(key);
        else this.folded.add(key);
        this.applyFolds();
      });

      row.addEventListener('click', () => this.jump(i));
      return row;
    });

    this.list.replaceChildren(...this.rows);
    this.applyFolds();
  }

  /** Hides the headings under a folded one. */
  private applyFolds(): void {
    let hideBelow = Infinity;

    this.headings.forEach((heading, i) => {
      if (heading.level <= hideBelow) hideBelow = Infinity;

      const row = this.rows[i];
      const folded = this.folded.has(this.keyOf(i));

      row.hidden = heading.level > hideBelow;
      row.classList.toggle('folded', folded);
      if (folded && hideBelow === Infinity) hideBelow = heading.level;
    });
  }

  private mark(index: number): void {
    if (index === this.current) return;

    this.rows[this.current]?.classList.remove('current');
    this.current = index;

    const row = this.rows[index];
    if (!row) return;

    row.classList.add('current');
    const box = this.list.getBoundingClientRect();
    const at = row.getBoundingClientRect();
    if (at.top < box.top || at.bottom > box.bottom) row.scrollIntoView({ block: 'nearest' });
  }

  /** Puts the cursor at the start of a heading and brings it to the top of the window. */
  private jump(index: number): void {
    const tab = this.host.tab();
    const heading = this.headings[index];
    if (!tab || !heading) return;

    const { view } = tab;
    const pos = Math.min(heading.pos + 1, view.state.doc.content.size);

    view.dispatch(view.state.tr.setSelection(TextSelection.near(view.state.doc.resolve(pos))));
    view.focus();

    const dom = view.nodeDOM(heading.pos);
    if (dom instanceof HTMLElement) dom.scrollIntoView({ block: 'start', behavior: 'smooth' });
    else view.dispatch(view.state.tr.scrollIntoView());
  }
}
