// Comments: read from comments.xml (with commentsExtended.xml for replies and resolved state, and
// commentsIds.xml / commentsExtensible.xml kept in step), anchored in the text by Word's own
// markers, and written back.
//
// The markers (`w:commentRangeStart`, `w:commentRangeEnd` and the run holding `w:commentReference`)
// stay where the importer put them: in hidden `opaque` nodes, as source. The document is what says
// whether a comment is there: one whose markers were deleted (or undone back out) is not written.
// A comment that was not touched goes back as the XML it came as.

import type { Node as PMNode } from 'prosemirror-model';
import type { EditorState, Transaction } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { REL_TYPE, type Rel, relKind, resolveTarget } from '../docx/package';
import { type XmlEl, childrenNamed, descendants, escAttr, escText, parseXml } from '../docx/xml';
import { schema } from '../editor/schema';
import { authorName, initialsOf, revisionDate } from './author';
import { editHidden, elementWithId, hiddenNode, isHidden, referenceRun } from './opaque';

const N = schema.nodes;

const W_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
const W14_NS = 'http://schemas.microsoft.com/office/word/2010/wordml';
const W15_NS = 'http://schemas.microsoft.com/office/word/2012/wordml';
const MC_NS = 'http://schemas.openxmlformats.org/markup-compatibility/2006';
const WML = 'application/vnd.openxmlformats-officedocument.wordprocessingml';

export const COMMENTS_REL = `${REL_TYPE}/comments`;
export const COMMENTS_EX_REL = 'http://schemas.microsoft.com/office/2011/relationships/commentsExtended';

export interface Comment {
  /** `w:id`: what the markers in the text name it by. */
  id: string;
  author: string;
  initials: string;
  /** As written in the file, ISO 8601; may be empty. */
  date: string;
  /** Plain text; paragraphs separated by newlines. */
  text: string;
  /** `w14:paraId` of its last paragraph: what commentsExtended.xml knows it by. */
  paraId: string | null;
  /** The comment this one answers. */
  parentId: string | null;
  done: boolean;
  /** `w16cid:durableId`, for a comment added here to a document that keeps those. */
  durableId: string | null;
  /** The `w:comment` element as read; null once edited, or for a comment made here. */
  source: string | null;
  /** Its commentsExtended entry needs writing anew (resolved, or new). */
  exChanged: boolean;
  /** Anchored in the body: written only while its markers are there. Otherwise (a comment in a header) kept regardless. */
  anchored: boolean;
  /** Deleted, for a comment that is not anchored in the body. */
  deleted: boolean;
  /** Where it sat in comments.xml as read. */
  span: [number, number] | null;
}

export interface Anchor {
  start: number | null;
  end: number | null;
  ref: number | null;
}

/** Where a comment stands in the text: from, to. */
export interface Placed {
  comment: Comment;
  from: number;
  to: number;
}

interface Part {
  path: string;
  xml: string;
}

export class CommentStore {
  readonly comments: Comment[] = [];
  /** Counts edits that are not in the text (wording, resolved); compared with `saved`. */
  version = 0;
  saved = 0;
  readonly part: Part | null;
  readonly ex: Part | null;
  readonly ids: Part | null;
  readonly extensible: Part | null;
  /** commentsExtended entries by paraId, as read. */
  readonly exEntries = new Map<string, { source: string; span: [number, number] }>();
  private next: number;

  constructor(ctx: DocContext) {
    const partOf = (kind: string): Part | null => {
      const rel = ctx.rels.find((r) => !r.external && relKind(r) === kind);
      if (!rel) return null;
      const path = resolveTarget(ctx.docPath, rel.target);
      const xml = ctx.pkg.text(path);
      return xml === null ? null : { path, xml };
    };

    this.part = partOf('comments');
    this.ex = partOf('commentsExtended');
    this.ids = partOf('commentsIds');
    this.extensible = partOf('commentsExtensible');

    const body = ctx.pkg.text(ctx.docPath) ?? '';
    const inBody = new Set<string>();
    for (const m of body.matchAll(/<w:comment(?:RangeStart|RangeEnd|Reference)\b[^>]*?\bw:id="([^"]*)"/g)) inBody.add(m[1]);

    let max = 0;
    for (const m of body.matchAll(/\bw:id="(\d+)"/g)) max = Math.max(max, Number(m[1]));

    const exByPara = new Map<string, XmlEl>();

    if (this.ex) {
      for (const el of descendants(parseXml(this.ex.xml), 'w15:commentEx')) {
        const paraId = el.attrs['w15:paraId'];
        if (!paraId) continue;
        exByPara.set(paraId, el);
        this.exEntries.set(paraId, { source: this.ex.xml.slice(el.start, el.end), span: [el.start, el.end] });
      }
    }

    if (this.part) {
      const byPara = new Map<string, Comment>();
      const parents = new Map<Comment, string>();

      for (const el of childrenNamed(parseXml(this.part.xml), 'w:comment')) {
        const paras = descendants(el, 'w:p');
        const paraId = paras.length ? (paras[paras.length - 1].attrs['w14:paraId'] ?? null) : null;
        const ex = paraId ? exByPara.get(paraId) : undefined;
        const id = el.attrs['w:id'] ?? '';
        const comment: Comment = {
          id,
          author: el.attrs['w:author'] ?? '',
          initials: el.attrs['w:initials'] ?? '',
          date: el.attrs['w:date'] ?? '',
          text: paras.map(paraText).join('\n'),
          paraId,
          parentId: null,
          done: ex?.attrs['w15:done'] === '1',
          durableId: null,
          source: this.part.xml.slice(el.start, el.end),
          exChanged: false,
          anchored: inBody.has(id),
          deleted: false,
          span: [el.start, el.end],
        };

        if (paraId) byPara.set(paraId, comment);
        if (ex?.attrs['w15:paraIdParent']) parents.set(comment, ex.attrs['w15:paraIdParent']);
        this.comments.push(comment);
        max = Math.max(max, Number(id) || 0);
      }

      for (const [comment, parentPara] of parents) comment.parentId = byPara.get(parentPara)?.id ?? null;
    }

    this.next = max + 1;
  }

  get dirty(): boolean {
    return this.version !== this.saved;
  }

  byId(id: string): Comment | undefined {
    return this.comments.find((c) => c.id === id);
  }

  replies(id: string): Comment[] {
    return this.comments.filter((c) => c.parentId === id);
  }

  newId(): string {
    return String(this.next++);
  }

  /** Whether a comment is there to show and to write, with the text's markers as they are now. */
  isLive(comment: Comment, anchors: ReadonlyMap<string, Anchor>): boolean {
    return comment.anchored ? anchors.has(comment.id) : !comment.deleted;
  }
}

function paraText(p: XmlEl): string {
  let text = '';
  const walk = (el: XmlEl) => {
    for (const c of el.children) {
      if (c.name === 'w:t') text += c.text;
      else if (c.name === 'w:tab') text += '\t';
      else if (c.name === 'w:br') text += '\n';
      else walk(c);
    }
  };
  walk(p);
  return text;
}

const stores = new WeakMap<DocContext, CommentStore>();

/** The comments of an open document, read on first use. */
export function commentsOf(ctx: DocContext): CommentStore {
  let store = stores.get(ctx);

  if (!store) {
    store = new CommentStore(ctx);
    stores.set(ctx, store);
  }

  return store;
}

// ---- Markers in the text ------------------------------------------------------------------------

const MARKER = /<w:(commentRangeStart|commentRangeEnd|commentReference)\b[^>]*?\bw:id="([^"]*)"/g;

/** Every comment's markers in the text, by comment id. */
export function anchorsIn(doc: PMNode): Map<string, Anchor> {
  const anchors = new Map<string, Anchor>();

  doc.descendants((node, pos) => {
    if (!isHidden(node)) return !node.isInline;
    const raw: string = node.attrs.raw;
    if (!raw.includes('<w:comment')) return false;

    for (const m of raw.matchAll(MARKER)) {
      const anchor = anchors.get(m[2]) ?? { start: null, end: null, ref: null };
      if (m[1] === 'commentRangeStart') anchor.start = pos + 1;
      else if (m[1] === 'commentRangeEnd') anchor.end = pos;
      else anchor.ref = pos;
      anchors.set(m[2], anchor);
    }

    return false;
  });

  return anchors;
}

/** The stretch of text a comment is about. */
export function rangeOf(anchor: Anchor): { from: number; to: number } {
  const from = anchor.start ?? anchor.end ?? anchor.ref ?? 0;
  const to = Math.max(from, anchor.end ?? anchor.ref ?? from);
  return { from, to };
}

/** The comments to show: live ones, in the order of the text, each with its stretch. Replies are left to `replies`. */
export function placedComments(store: CommentStore, anchors: ReadonlyMap<string, Anchor>): Placed[] {
  const placed: Placed[] = [];

  for (const comment of store.comments) {
    if (comment.parentId && store.byId(comment.parentId) && store.isLive(store.byId(comment.parentId)!, anchors)) continue;
    if (!store.isLive(comment, anchors)) continue;

    const anchor = anchors.get(comment.id);
    const { from, to } = anchor ? rangeOf(anchor) : { from: -1, to: -1 };
    placed.push({ comment, from, to });
  }

  return placed.sort((a, b) => a.from - b.from || a.to - b.to);
}

// ---- Changes ------------------------------------------------------------------------------------

const randomHex = () => Math.floor(Math.random() * 0x7ffffffe + 1).toString(16).toUpperCase().padStart(8, '0');

function newComment(store: CommentStore, text: string, author: string, date: string, parentId: string | null): Comment {
  const comment: Comment = {
    id: store.newId(),
    author,
    initials: initialsOf(author),
    date,
    text,
    paraId: randomHex(),
    parentId,
    done: false,
    durableId: store.ids ? randomHex() : null,
    source: null,
    exChanged: true,
    anchored: true,
    deleted: false,
    span: null,
  };

  store.comments.push(comment);
  return comment;
}

/** The word around an empty selection, which is what Word comments on. */
function wordAround(state: EditorState): { from: number; to: number } {
  const { from, to, $from } = state.selection;
  if (from !== to || !$from.parent.isTextblock) return { from, to };

  const text = $from.parent.textBetween(0, $from.parent.content.size, '￼', '￼');
  let a = $from.parentOffset;
  let b = a;
  while (a > 0 && /[\p{L}\p{N}_'’-]/u.test(text[a - 1])) a--;
  while (b < text.length && /[\p{L}\p{N}_'’-]/u.test(text[b])) b++;

  return { from: $from.start() + a, to: $from.start() + b };
}

/** Adds a comment on the selection (or the word at the cursor). Returns the transaction and the comment's id. */
export function addComment(state: EditorState, store: CommentStore, text: string, author = authorName(), date = revisionDate()): { tr: Transaction; id: string } {
  const { from, to } = wordAround(state);
  const comment = newComment(store, text, author, date, null);
  const { id } = comment;

  const tr = state.tr;
  tr.insert(to, hiddenNode(`<w:commentRangeEnd w:id="${id}"/>${referenceXml(id)}`));
  tr.insert(from, hiddenNode(`<w:commentRangeStart w:id="${id}"/>`));
  store.version++;

  return { tr: tr.setMeta('review', 'comments'), id };
}

const referenceXml = (id: string) => `<w:r><w:rPr><w:rStyle w:val="CommentReference"/></w:rPr><w:commentReference w:id="${id}"/></w:r>`;

/** A reply: its markers go beside its parent's, as Word puts them. */
export function replyTo(state: EditorState, store: CommentStore, parentId: string, text: string, author = authorName(), date = revisionDate()): Transaction | null {
  const parent = store.byId(parentId);
  if (!parent) return null;

  const root = parent.parentId ? (store.byId(parent.parentId) ?? parent) : parent;
  const reply = newComment(store, text, author, date, root.id);
  const id = reply.id;
  const tr = state.tr;
  let placedStart = false;
  let placedEnd = false;

  editHidden(tr, (raw) => {
    let out = raw;

    out = out.replace(elementWithId('w:commentRangeStart', root.id), (el) => {
      placedStart = true;
      return `${el}<w:commentRangeStart w:id="${id}"/>`;
    });

    const ref = referenceRun(root.id);
    if (ref.test(out)) {
      out = out.replace(referenceRun(root.id), (el) => {
        placedEnd = true;
        return `${el}<w:commentRangeEnd w:id="${id}"/>${referenceXml(id)}`;
      });
    }

    return out;
  });

  if (!placedEnd) {
    // The parent's reference is gone (or never was in the body): the reply goes where the text ends.
    const anchors = anchorsIn(tr.doc);
    const at = anchors.get(root.id);
    const pos = at ? rangeOf(at).to : state.selection.to;
    tr.insert(pos, hiddenNode(`${placedStart ? `<w:commentRangeEnd w:id="${id}"/>` : ''}${referenceXml(id)}`));
  }

  store.version++;
  return tr.setMeta('review', 'comments');
}

/** Deletes a comment and its replies: their markers leave the text. */
export function deleteComment(state: EditorState, store: CommentStore, id: string): Transaction {
  const gone = new Set([id, ...store.replies(id).map((r) => r.id)]);
  const tr = state.tr;

  editHidden(tr, (raw) => {
    if (!raw.includes('<w:comment')) return raw;
    let out = raw;

    for (const g of gone) {
      out = out.replace(referenceRun(g), '').replace(elementWithId('w:commentRangeStart', g), '').replace(elementWithId('w:commentRangeEnd', g), '').replace(elementWithId('w:commentReference', g), '');
    }

    return out;
  });

  for (const g of gone) {
    const comment = store.byId(g);
    if (comment && !comment.anchored) comment.deleted = true;
  }

  store.version++;
  return tr.setMeta('review', 'comments');
}

export function editComment(store: CommentStore, id: string, text: string): void {
  const comment = store.byId(id);
  if (!comment || comment.text === text) return;

  comment.text = text;
  comment.source = null;
  store.version++;
}

export function setResolved(store: CommentStore, id: string, done: boolean): void {
  const comment = store.byId(id);
  if (!comment || comment.done === done) return;

  comment.done = done;
  comment.exChanged = true;
  if (!comment.paraId) comment.paraId = randomHex();
  if (comment.source && !/w14:paraId=/.test(comment.source)) comment.source = null;
  store.version++;
}

// ---- Writing ------------------------------------------------------------------------------------

/** What the exporter lends for new parts: the package, unique relationship ids, and its lists. */
export interface PartWriter {
  pkg: { text(path: string): string | null; setText(path: string, text: string): void };
  relId(): string;
  rels: Rel[];
  overrides: Map<string, string>;
  docPath: string;
}

function commentXml(c: Comment, rootHasW14: boolean): string {
  const ns = rootHasW14 ? '' : ` xmlns:w14="${W14_NS}"`;
  const paras = c.text.split('\n');

  const body = paras
    .map((line, i) => {
      const last = i === paras.length - 1;
      const id = last && c.paraId ? ` w14:paraId="${c.paraId}" w14:textId="77777777"${ns}` : '';
      const mark = i === 0 ? '<w:r><w:rPr><w:rStyle w:val="CommentReference"/></w:rPr><w:annotationRef/></w:r>' : '';
      const runs = line
        .split('\t')
        .map((part) => (part ? `<w:t xml:space="preserve">${escText(part)}</w:t>` : ''))
        .join('<w:tab/>');
      return `<w:p${id}><w:pPr><w:pStyle w:val="CommentText"/></w:pPr>${mark}${runs ? `<w:r>${runs}</w:r>` : ''}</w:p>`;
    })
    .join('');

  const date = c.date ? ` w:date="${escAttr(c.date)}"` : '';
  const initials = c.initials ? ` w:initials="${escAttr(c.initials)}"` : '';
  return `<w:comment w:id="${c.id}" w:author="${escAttr(c.author)}"${date}${initials}>${body}</w:comment>`;
}

function exXml(c: Comment, store: CommentStore): string {
  const parent = c.parentId ? store.byId(c.parentId)?.paraId : null;
  return `<w15:commentEx w15:paraId="${c.paraId}"${parent ? ` w15:paraIdParent="${parent}"` : ''} w15:done="${c.done ? 1 : 0}"/>`;
}

/** Replaces spans of `xml` and adds before its root's closing tag. */
function splice(xml: string, edits: { span: [number, number]; text: string }[], append: string): string {
  let out = '';
  let at = 0;

  for (const { span, text } of edits.sort((a, b) => a.span[0] - b.span[0])) {
    out += xml.slice(at, span[0]) + text;
    at = span[1];
  }

  const rest = xml.slice(at);
  const close = rest.lastIndexOf('</');
  return close >= 0 ? out + rest.slice(0, close) + append + rest.slice(close) : out + rest + append;
}

function addPart(w: PartWriter, name: string, relType: string, contentType: string): string {
  const dir = w.docPath.includes('/') ? w.docPath.slice(0, w.docPath.lastIndexOf('/') + 1) : '';
  w.rels.push({ id: w.relId(), type: relType, target: name, external: false });
  w.overrides.set(dir + name, contentType);
  return dir + name;
}

const XML_HEAD = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\r\n';

/** Writes the comment parts for the text `doc`, when anything about them changed. */
export function writeComments(ctx: DocContext, doc: PMNode, w: PartWriter): void {
  if (!stores.has(ctx) && !ctx.rels.some((r) => relKind(r) === 'comments')) return;

  const store = commentsOf(ctx);
  const anchors = anchorsIn(doc);
  const live = store.comments.filter((c) => store.isLive(c, anchors));
  const liveSet = new Set(live);
  const dead = store.comments.filter((c) => !liveSet.has(c));

  // comments.xml
  if (store.part || live.length) {
    const rootTag = store.part ? (/<w:comments\b[^>]*>/.exec(store.part.xml)?.[0] ?? '') : '';
    const hasW14 = rootTag.includes(W14_NS);
    const edits: { span: [number, number]; text: string }[] = [];
    let append = '';

    for (const c of store.comments) {
      const text = liveSet.has(c) ? (c.source ?? commentXml(c, hasW14)) : '';
      if (c.span) {
        if (text !== c.source) edits.push({ span: c.span, text });
      } else {
        append += text;
      }
    }

    if (store.part) {
      if (edits.length || append) w.pkg.setText(store.part.path, splice(store.part.xml, edits, append));
    } else {
      const path = addPart(w, 'comments.xml', COMMENTS_REL, `${WML}.comments+xml`);
      w.pkg.setText(path, `${XML_HEAD}<w:comments xmlns:w="${W_NS}" xmlns:w14="${W14_NS}" xmlns:mc="${MC_NS}" mc:Ignorable="w14">${append}</w:comments>`);
    }
  }

  // commentsExtended.xml: replies and resolved state.
  const needsEx = live.some((c) => c.paraId && (c.parentId || c.done));

  if (store.ex || needsEx) {
    const edits: { span: [number, number]; text: string }[] = [];
    let append = '';

    for (const c of store.comments) {
      if (!c.paraId) continue;
      const entry = store.exEntries.get(c.paraId);
      const text = !liveSet.has(c) ? '' : c.exChanged || !entry ? exXml(c, store) : entry.source;

      if (entry) {
        if (text !== entry.source) edits.push({ span: entry.span, text });
      } else if (text) {
        append += text;
      }
    }

    if (store.ex) {
      if (edits.length || append) w.pkg.setText(store.ex.path, splice(store.ex.xml, edits, append));
    } else {
      const path = addPart(w, 'commentsExtended.xml', COMMENTS_EX_REL, `${WML}.commentsExtended+xml`);
      w.pkg.setText(path, `${XML_HEAD}<w15:commentsEx xmlns:w15="${W15_NS}" xmlns:mc="${MC_NS}" mc:Ignorable="w15">${append}</w15:commentsEx>`);
    }
  }

  // commentsIds.xml and commentsExtensible.xml: entries for comments gone come out, new ones go in.
  const goneParas = new Set(dead.map((c) => c.paraId).filter(Boolean) as string[]);
  const goneDurable = new Set<string>();

  if (store.ids) {
    let xml = store.ids.xml.replace(/<w16cid:commentId\b[^>]*\/>/g, (el) => {
      const para = /w16cid:paraId="([^"]*)"/.exec(el)?.[1];
      if (!para || !goneParas.has(para)) return el;
      const durable = /w16cid:durableId="([^"]*)"/.exec(el)?.[1];
      if (durable) goneDurable.add(durable);
      return '';
    });

    const added = live.filter((c) => !c.span && c.durableId && c.paraId);
    const append = added.map((c) => `<w16cid:commentId w16cid:paraId="${c.paraId}" w16cid:durableId="${c.durableId}"/>`).join('');
    if (append) xml = splice(xml, [], append);
    if (xml !== store.ids.xml) w.pkg.setText(store.ids.path, xml);

    if (store.extensible) {
      let ext = store.extensible.xml.replace(/<w16cex:commentExtensible\b[^>]*?(?:\/>|>[\s\S]*?<\/w16cex:commentExtensible>)/g, (el) => {
        const durable = /w16cex:durableId="([^"]*)"/.exec(el)?.[1];
        return durable && goneDurable.has(durable) ? '' : el;
      });
      const extAppend = added.map((c) => `<w16cex:commentExtensible w16cex:durableId="${c.durableId}" w16cex:dateUtc="${escAttr(c.date)}"/>`).join('');
      if (extAppend) ext = splice(ext, [], extAppend);
      if (ext !== store.extensible.xml) w.pkg.setText(store.extensible.path, ext);
    }
  }
}

/** For a test, or a caller without a view: whether text positions hold a comment marker node. */
export const isMarker = (node: PMNode): boolean => node.type === N.opaque && isHidden(node) && /<w:comment/.test(node.attrs.raw);
