// A new, empty document: the smallest package Word opens without complaint, with the styles
// people reach for already in it. It is built as bytes and then read like any other file, so a
// new document and an opened one go through exactly the same code.

import { DocxPackage } from './package';
import { DEFAULT_THEME } from './props';
import { Styles } from './styles';

const W = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
const R = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const PKG_REL = 'http://schemas.openxmlformats.org/package/2006/relationships';
const WML = 'application/vnd.openxmlformats-officedocument.wordprocessingml';
const HEAD = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';

const CONTENT_TYPES =
  `${HEAD}<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">` +
  `<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>` +
  `<Default Extension="xml" ContentType="application/xml"/>` +
  `<Override PartName="/word/document.xml" ContentType="${WML}.document.main+xml"/>` +
  `<Override PartName="/word/styles.xml" ContentType="${WML}.styles+xml"/>` +
  `<Override PartName="/word/settings.xml" ContentType="${WML}.settings+xml"/>` +
  `</Types>`;

const ROOT_RELS =
  `${HEAD}<Relationships xmlns="${PKG_REL}"><Relationship Id="rId1" Type="${R}/officeDocument" Target="word/document.xml"/></Relationships>`;

const DOC_RELS =
  `${HEAD}<Relationships xmlns="${PKG_REL}">` +
  `<Relationship Id="rId1" Type="${R}/styles" Target="styles.xml"/>` +
  `<Relationship Id="rId2" Type="${R}/settings" Target="settings.xml"/>` +
  `</Relationships>`;

// A4 with the margins Word uses in Germany: 2.5 cm, and 2 cm at the bottom.
const DOCUMENT =
  `${HEAD}<w:document xmlns:w="${W}" xmlns:r="${R}" ` +
  `xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" ` +
  `xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" ` +
  `xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture">` +
  `<w:body><w:p/><w:sectPr><w:pgSz w:w="11906" w:h="16838"/>` +
  `<w:pgMar w:top="1417" w:right="1417" w:bottom="1134" w:left="1417" w:header="708" w:footer="708" w:gutter="0"/>` +
  `<w:cols w:space="708"/><w:docGrid w:linePitch="360"/></w:sectPr></w:body></w:document>`;

// Without the compatibility setting Word opens the file in "Compatibility Mode", as if it were
// from Word 2007.
const SETTINGS =
  `${HEAD}<w:settings xmlns:w="${W}"><w:defaultTabStop w:val="708"/><w:characterSpacingControl w:val="doNotCompress"/>` +
  `<w:compat><w:compatSetting w:name="compatibilityMode" w:uri="http://schemas.microsoft.com/office/word" w:val="15"/></w:compat>` +
  `</w:settings>`;

const BASE_STYLES =
  `${HEAD}<w:styles xmlns:w="${W}">` +
  `<w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii="Calibri" w:hAnsi="Calibri" w:eastAsia="Calibri" w:cs="Calibri"/>` +
  `<w:sz w:val="22"/><w:szCs w:val="22"/></w:rPr></w:rPrDefault>` +
  `<w:pPrDefault><w:pPr><w:spacing w:after="160" w:line="259" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults>` +
  `<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:qFormat/></w:style>` +
  `<w:style w:type="character" w:default="1" w:styleId="DefaultParagraphFont"><w:name w:val="Default Paragraph Font"/>` +
  `<w:uiPriority w:val="1"/><w:semiHidden/><w:unhideWhenUsed/></w:style>` +
  `<w:style w:type="table" w:default="1" w:styleId="TableNormal"><w:name w:val="Normal Table"/><w:uiPriority w:val="99"/>` +
  `<w:semiHidden/><w:unhideWhenUsed/><w:tblPr><w:tblInd w:w="0" w:type="dxa"/><w:tblCellMar><w:top w:w="0" w:type="dxa"/>` +
  `<w:left w:w="108" w:type="dxa"/><w:bottom w:w="0" w:type="dxa"/><w:right w:w="108" w:type="dxa"/></w:tblCellMar></w:tblPr></w:style>` +
  `<w:style w:type="numbering" w:default="1" w:styleId="NoList"><w:name w:val="No List"/><w:uiPriority w:val="99"/>` +
  `<w:semiHidden/><w:unhideWhenUsed/></w:style>` +
  `</w:styles>`;

/** The bytes of an empty .docx. */
export function blankDocx(): Uint8Array {
  const styles = Styles.parse(BASE_STYLES, DEFAULT_THEME);

  for (const name of ['heading 1', 'heading 2', 'heading 3', 'heading 4', 'Title', 'Subtitle', 'Quote', 'List Paragraph']) {
    styles.ensureBuiltin(name);
  }

  styles.ensureBuiltin('Hyperlink', 'character');
  styles.ensureBuiltin('Table Grid', 'table');

  const pkg = new DocxPackage(new Map());

  pkg.setText('[Content_Types].xml', CONTENT_TYPES);
  pkg.setText('_rels/.rels', ROOT_RELS);
  pkg.setText('word/document.xml', DOCUMENT);
  pkg.setText('word/_rels/document.xml.rels', DOC_RELS);
  pkg.setText('word/styles.xml', styles.exportXml(BASE_STYLES) ?? BASE_STYLES);
  pkg.setText('word/settings.xml', SETTINGS);

  return pkg.toBytes();
}
