// OMML to MathML, for Chromium's own MathML to draw.
//
// Pure: strings in, a string out. Every OMML structure maps onto MathML Core's elements; the
// letter styles MathML Core has no attribute for (bold, script, fraktur, ...) become Unicode's
// mathematical alphabets, as Word itself shows them. A colour becomes the class the page's text
// colours have (`.c` with `--c`), so a dark page maps it the same way. Anything not understood is
// drawn as a dashed box with its text in it: shown, never dropped.

import { type XmlEl, child, childrenNamed, escAttr, escText } from '../docx/xml';
import { allText, chr, flag, linesOf, mval, naryLimLoc, paraAlign, parseEquation, rowItems, runStyle, runText } from './omml';
import { ACCENT_GLYPHS, alphabetOf, styled } from './symbols';

interface Ctx {
  display: boolean;
  /** Inside an equation array, where `&` marks alignment and is not shown. */
  eqArr: boolean;
}

const LETTER = /\p{L}/u;
const DIGITS = /^[0-9]+(?:[.,][0-9]+)*/;

/** A run's text as tokens: numbers, letters (one each unless upright), operators. */
function runTokens(text: string, sty: string | null, scr: string | null): string {
  const alphabet = alphabetOf(scr, sty);
  const upright = sty === 'p' || (alphabet !== null && sty !== 'i' && sty !== 'bi' && alphabet !== 'script' && alphabet !== 'fraktur');
  let out = '';
  let i = 0;
  const chars = [...text];

  while (i < chars.length) {
    const rest = chars.slice(i).join('');
    const num = DIGITS.exec(rest);

    if (num) {
      out += `<mn>${escText(styled(num[0], alphabet))}</mn>`;
      i += [...num[0]].length;
      continue;
    }

    const ch = chars[i];

    if (LETTER.test(ch)) {
      if (sty === 'p') {
        // Upright letters run together, as a function's name does.
        let word = '';
        while (i < chars.length && LETTER.test(chars[i])) word += chars[i++];
        out += [...word].length === 1 ? `<mi mathvariant="normal">${escText(word)}</mi>` : `<mi>${escText(styled(word, alphabet))}</mi>`;
      } else {
        const shown = styled(ch, alphabet);
        out += upright || shown !== ch ? `<mi mathvariant="normal">${escText(shown)}</mi>` : `<mi>${escText(ch)}</mi>`;
        i++;
      }
      continue;
    }

    if (ch === ' ' || ch === ' ' || ch === '\t') out += '<mspace width="0.25em"></mspace>';
    else out += `<mo>${escText(ch)}</mo>`;
    i++;
  }

  return out;
}

function run(r: XmlEl, ctx: Ctx): string {
  const style = runStyle(r);
  let text = runText(r);
  if (ctx.eqArr) text = text.replace(/&/g, '');
  if (!text) return '';

  const body = style.nor ? `<mtext>${escText(text)}</mtext>` : runTokens(text, style.sty, style.scr);
  return style.color ? `<mrow class="c" style="--c:#${style.color}">${body}</mrow>` : body;
}

/** A row: an argument's runs and structures, in an mrow so it stays one thing. */
function row(el: XmlEl | null | undefined, ctx: Ctx): string {
  return `<mrow>${el ? rowItems(el).map((c) => item(c, ctx)).join('') : ''}</mrow>`;
}

const arg = (el: XmlEl, name: string, ctx: Ctx) => row(child(el, name), ctx);

const op = (text: string, attrs = '') => (text ? `<mo${attrs}>${escText(text)}</mo>` : '');

function item(el: XmlEl, ctx: Ctx): string {
  const pr = child(el, `${el.name}Pr`);

  switch (el.name) {
    case 'm:r':
    case 'w:r':
      return run(el, ctx);

    case 'm:f': {
      const type = mval(pr, 'm:type') ?? 'bar';
      const num = arg(el, 'm:num', ctx);
      const den = arg(el, 'm:den', ctx);
      if (type === 'lin' || type === 'skw') return `<mrow>${num}<mo>/</mo>${den}</mrow>`;
      return type === 'noBar' ? `<mfrac linethickness="0">${num}${den}</mfrac>` : `<mfrac>${num}${den}</mfrac>`;
    }

    case 'm:sSub':
      return `<msub>${arg(el, 'm:e', ctx)}${arg(el, 'm:sub', ctx)}</msub>`;
    case 'm:sSup':
      return `<msup>${arg(el, 'm:e', ctx)}${arg(el, 'm:sup', ctx)}</msup>`;
    case 'm:sSubSup':
      return `<msubsup>${arg(el, 'm:e', ctx)}${arg(el, 'm:sub', ctx)}${arg(el, 'm:sup', ctx)}</msubsup>`;
    case 'm:sPre':
      return `<mmultiscripts>${arg(el, 'm:e', ctx)}<mprescripts></mprescripts>${arg(el, 'm:sub', ctx)}${arg(el, 'm:sup', ctx)}</mmultiscripts>`;

    case 'm:rad': {
      const deg = child(el, 'm:deg');
      const hide = flag(pr, 'm:degHide') || !deg || rowItems(deg).length === 0;
      return hide ? `<msqrt>${arg(el, 'm:e', ctx)}</msqrt>` : `<mroot>${arg(el, 'm:e', ctx)}${row(deg, ctx)}</mroot>`;
    }

    case 'm:nary': {
      const c = chr(pr, 'm:chr', '∫') || '∫';
      const loc = naryLimLoc(pr, c);
      const sub = flag(pr, 'm:subHide') ? null : arg(el, 'm:sub', ctx);
      const sup = flag(pr, 'm:supHide') ? null : arg(el, 'm:sup', ctx);
      const mo = op(c, ` largeop="true"${loc === 'undOvr' && ctx.display ? ' movablelimits="false"' : ''}`);
      let base = mo;
      if (loc === 'undOvr') {
        if (sub && sup) base = `<munderover>${mo}${sub}${sup}</munderover>`;
        else if (sub) base = `<munder>${mo}${sub}</munder>`;
        else if (sup) base = `<mover>${mo}${sup}</mover>`;
      } else {
        if (sub && sup) base = `<msubsup>${mo}${sub}${sup}</msubsup>`;
        else if (sub) base = `<msub>${mo}${sub}</msub>`;
        else if (sup) base = `<msup>${mo}${sup}</msup>`;
      }
      return `<mrow>${base}${arg(el, 'm:e', ctx)}</mrow>`;
    }

    case 'm:d': {
      const beg = chr(pr, 'm:begChr', '(');
      const end = chr(pr, 'm:endChr', ')');
      const sep = chr(pr, 'm:sepChr', '|');
      const parts = childrenNamed(el, 'm:e').map((e) => row(e, ctx));
      const fence = ' fence="true" stretchy="true" symmetric="true"';
      return `<mrow>${op(beg, fence)}${parts.join(op(sep, ' stretchy="true"'))}${op(end, fence)}</mrow>`;
    }

    case 'm:func': {
      // A thin space after the name, as Word leaves, unless brackets follow.
      const first = rowItems(child(el, 'm:e'))[0];
      const space = first?.name === 'm:d' ? '' : '<mspace width="0.17em"></mspace>';
      return `<mrow>${arg(el, 'm:fName', ctx)}<mo>⁡</mo>${space}${arg(el, 'm:e', ctx)}</mrow>`;
    }

    case 'm:acc': {
      const c = chr(pr, 'm:chr', '̂');
      return `<mover accent="true">${arg(el, 'm:e', ctx)}${op(ACCENT_GLYPHS[c] ?? c, ' stretchy="false"')}</mover>`;
    }

    case 'm:bar':
      // A line over or under: MathML Core stretches no overline character, so a border draws it.
      return `<mrow class="${mval(pr, 'm:pos') === 'top' ? 'math-over' : 'math-under'}">${arg(el, 'm:e', ctx)}</mrow>`;

    case 'm:limLow':
      return `<munder>${arg(el, 'm:e', ctx)}${arg(el, 'm:lim', ctx)}</munder>`;
    case 'm:limUpp':
      return `<mover>${arg(el, 'm:e', ctx)}${arg(el, 'm:lim', ctx)}</mover>`;

    case 'm:groupChr': {
      const c = chr(pr, 'm:chr', '⏟');
      const top = mval(pr, 'm:pos') === 'top';
      const mo = op(c, ' stretchy="true"');
      return top ? `<mover>${arg(el, 'm:e', ctx)}${mo}</mover>` : `<munder>${arg(el, 'm:e', ctx)}${mo}</munder>`;
    }

    case 'm:m': {
      const rows = childrenNamed(el, 'm:mr').map((mr) => `<mtr>${childrenNamed(mr, 'm:e').map((e) => `<mtd>${row(e, ctx)}</mtd>`).join('')}</mtr>`);
      return `<mtable>${rows.join('')}</mtable>`;
    }

    case 'm:eqArr': {
      const inner = { ...ctx, eqArr: true };
      const rows = childrenNamed(el, 'm:e').map((e) => `<mtr><mtd>${row(e, inner)}</mtd></mtr>`);
      return `<mtable class="math-eqarr">${rows.join('')}</mtable>`;
    }

    case 'm:box':
      return arg(el, 'm:e', ctx);
    case 'm:borderBox':
      return `<mrow class="math-border">${arg(el, 'm:e', ctx)}</mrow>`;
    case 'm:phant':
      return child(pr, 'm:show') && !flag(pr, 'm:show') ? `<mphantom>${arg(el, 'm:e', ctx)}</mphantom>` : arg(el, 'm:e', ctx);

    case 'm:oMath':
      return row(el, ctx);

    default:
      return unknown(el);
  }
}

function unknown(el: XmlEl): string {
  const text = allText(el) || el.name;
  return `<mrow class="math-unknown" title="${escAttr(el.name)}"><mtext>${escText(text)}</mtext></mrow>`;
}

/** One `m:oMath` as a `<math>` element. */
export function lineToMathML(el: XmlEl, display: boolean): string {
  const body = rowItems(el).map((c) => item(c, { display, eqArr: false })).join('');
  return `<math${display ? ' display="block"' : ''}>${body}</math>`;
}

export interface Rendered {
  /** One `<math>` per line: an inline equation has one. */
  lines: string[];
  display: boolean;
  align: string;
}

/** An equation's XML as MathML. XML that does not read as an equation comes back as a dashed box. */
export function ommlToMathML(xml: string): Rendered {
  const el = parseEquation(xml);
  if (!el) return { lines: [`<math><mrow class="math-unknown"><mtext>${escText(xml.replace(/<[^>]*>/g, '') || '?')}</mtext></mrow></math>`], display: false, align: 'center' };

  const display = el.name === 'm:oMathPara';
  return { lines: linesOf(el).map((line) => lineToMathML(line, display)), display, align: display ? paraAlign(el) : 'center' };
}
