// Citations in footnotes, for Chicago notes and bibliography.
//
// In that style a citation is a footnote: inserting one puts a reference at the cursor and a
// CITATION field in the new note. Each note citation is rendered in the full form the first time
// its source is cited (in the order of the references in the text), the short form after that, and
// as "Ibid." for the same single source as the citation just before it, when that is switched on.
// Notes are rendered again whenever the citations are (after the style or the sources changed,
// or a citation was inserted); a note whose text comes out the same is left as it is.

import type { Node as PMNode } from 'prosemirror-model';
import { EditorState } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { fieldNodes } from '../fields/build';
import { scanFields } from '../fields/model';
import { updateFields } from '../fields/update';
import { insertNote } from '../notes/commands';
import { notesOf, refsIn } from '../notes/model';
import type { NoteForm } from './chicago-notes';
import { CITE_TYPES, noteHooks } from './fields';
import { type Citation, citationInstr, parseCitation } from './instr';
import { library } from './store';
import type { CiteItem } from './styles';

const ibid = new WeakMap<DocContext, boolean>();

/** Whether a repeated source right after itself is cited as "Ibid." (off, as CMOS 17 prefers). */
export const ibidOn = (ctx: DocContext): boolean => ibid.get(ctx) ?? false;
export const setIbid = (ctx: DocContext, on: boolean): void => void ibid.set(ctx, on);

export const isNoteStyle = (ctx: DocContext): boolean => library(ctx).style === 'chicago-nb';

/** The footnotes the text refers to, in order, with their content. */
function footnotesInOrder(ctx: DocContext, doc: PMNode): { id: string; doc: PMNode }[] {
  const store = notesOf(ctx);
  const seen = new Set<string>();
  const out: { id: string; doc: PMNode }[] = [];

  for (const ref of refsIn(doc)) {
    const note = ref.kind === 'footnote' ? store.get('footnote', ref.id) : undefined;
    if (!note || note.type !== null || seen.has(ref.id)) continue;
    seen.add(ref.id);
    out.push({ id: ref.id, doc: store.docOf(note) });
  }

  return out;
}

/** The citations of a note's content, in order, as tag lists. */
const citationsOf = (doc: PMNode) => scanFields(doc).fields.filter((f) => f.type === 'CITATION');

/**
 * The form each item of each note citation takes: by note id, one entry per CITATION field in
 * the note, a form for each of the citation's tags.
 */
export function noteForms(ctx: DocContext, doc: PMNode, useIbid = ibidOn(ctx)): Map<string, NoteForm[][]> {
  const cited = new Set<string>();
  const out = new Map<string, NoteForm[][]>();
  let previous: string | null = null;

  for (const note of footnotesInOrder(ctx, doc)) {
    const forms = citationsOf(note.doc).map((field) => {
      const tags = parseCitation(field.instr).parts.map((p) => p.tag);
      const result = tags.map((tag): NoteForm => {
        const form: NoteForm = !cited.has(tag) ? 'full' : useIbid && tags.length === 1 && previous === tag ? 'ibid' : 'short';
        cited.add(tag);
        return form;
      });
      previous = tags.length === 1 ? tags[0] : null;
      return result;
    });

    if (forms.length) out.set(note.id, forms);
  }

  return out;
}

/** Renders every citation in the footnotes again; returns whether any note changed. */
export function renderNoteCitations(ctx: DocContext, doc: PMNode): boolean {
  const store = notesOf(ctx);
  const forms = isNoteStyle(ctx) ? noteForms(ctx, doc) : new Map<string, NoteForm[][]>();
  let changed = false;

  for (const { id, doc: noteDoc } of footnotesInOrder(ctx, doc)) {
    if (!citationsOf(noteDoc).length) continue;

    const mine = forms.get(id) ?? [];
    let state = EditorState.create({ doc: noteDoc });
    const tr = state.tr;

    noteHooks.form = isNoteStyle(ctx)
      ? (field, inDoc) => {
          const k = citationsOf(inDoc).findIndex((f) => f.from === field.from);
          const list = mine[k];
          return list ? (item: CiteItem) => list[Math.max(0, parseCitation(field.instr).parts.findIndex((p) => p.tag === item.tag))] ?? 'short' : null;
        }
      : null;

    try {
      updateFields(tr, ctx, { types: ['CITATION'] });
    } finally {
      noteHooks.form = null;
    }

    state = state.apply(tr);
    const note = store.get('footnote', id);
    if (note && !state.doc.eq(noteDoc)) {
      store.setDoc(note, state.doc);
      changed = true;
    }
  }

  return changed;
}

/** Inserts a citation as a new footnote at the cursor (Chicago notes and bibliography). */
export function insertNoteCitation(ctx: DocContext, citation: Citation) {
  return (state: EditorState, dispatch?: (tr: import('prosemirror-state').Transaction) => void): boolean => {
    if (!citation.parts.length) return false;
    if (!dispatch) return true;

    const { tr } = insertNote(state, ctx, 'footnote', () => fieldNodes(citationInstr(citation), ' '));
    // The bibliography in the text may list a source more now.
    updateFields(tr, ctx, { types: CITE_TYPES.filter((t) => t !== 'CITATION') });
    renderNoteCitations(ctx, tr.doc);
    dispatch(tr);
    return true;
  };
}

/** The sources cited in footnotes, for the bibliography. */
noteHooks.tags = (ctx, doc) => {
  const tags: string[] = [];
  for (const note of footnotesInOrder(ctx, doc)) {
    for (const field of citationsOf(note.doc)) tags.push(...parseCitation(field.instr).parts.map((p) => p.tag));
  }
  return tags;
};

noteHooks.render = renderNoteCitations;
noteHooks.insert = insertNoteCitation;
