// The find bar's recipes: saved searches with what to do to every match, kept in settings.

import type { FindMode, FindTarget } from '../editor/find';
import { describeFilter, type FormatFilter } from '../editor/formatmatch';
import {
  addRecipe, deleteRecipe, parseRecipes, type Recipe, type RecipeFormat, renameRecipe, restoreBuiltins, serializeRecipes,
} from '../editor/recipes';
import { ask, h, store, stored } from './dom';

const KEY = 'text-studio:find-recipes';

export const loadRecipes = (): Recipe[] => parseRecipes(stored(KEY));
const saveRecipes = (recipes: readonly Recipe[]) => store(KEY, serializeRecipes(recipes));

/** What the find bar holds now, to save as a recipe. */
export interface FindBarState {
  mode: FindMode;
  query: string;
  matchCase: boolean;
  filter: FormatFilter | null;
  replacement: string;
  target: FindTarget;
  /** The formatting last given to matches from the Format menu, with its name. */
  lastFormat: { format: RecipeFormat; label: string } | null;
}

export interface RecipeMenuHost {
  state(): FindBarState;
  run(recipe: Recipe): void;
  /** Puts a recipe's search into the find bar without running it. */
  load(recipe: Recipe): void;
}

/** The simple actions a recipe can have, for the list to pick from. */
const ACTIONS: { label: string; format: RecipeFormat }[] = [
  { label: 'Bold', format: { kind: 'toggle', mark: 'bold', on: true } },
  { label: 'Italic', format: { kind: 'toggle', mark: 'italic', on: true } },
  { label: 'Underline', format: { kind: 'toggle', mark: 'underline', on: true } },
  { label: 'Strikethrough', format: { kind: 'toggle', mark: 'strike', on: true } },
  { label: 'Not bold', format: { kind: 'toggle', mark: 'bold', on: false } },
  { label: 'Not italic', format: { kind: 'toggle', mark: 'italic', on: false } },
  { label: 'Superscript', format: { kind: 'vert', value: 'superscript', on: true } },
  { label: 'Subscript', format: { kind: 'vert', value: 'subscript', on: true } },
  { label: 'Highlight yellow', format: { kind: 'set', mark: 'highlight', attrs: { value: '#FFFF00' } } },
  { label: 'Clear formatting', format: { kind: 'clear' } },
];

/** A recipe in a few words: what it finds and what it does. */
export function recipeSummary(recipe: Recipe): string {
  const parts: string[] = [];

  if (recipe.query) parts.push(recipe.query);
  if (recipe.filter) parts.push(describeFilter(recipe.filter));
  if (recipe.format) {
    const action = ACTIONS.find((a) => JSON.stringify(a.format) === JSON.stringify(recipe.format));
    parts.push(action ? `→ ${action.label}` : '→ Format');
    if (recipe.target === 'variables' && recipe.mode !== 'text') parts.push('(variables)');
  }
  if (recipe.replace !== null) parts.push(`→ “${recipe.replace}”`);

  return parts.join(' ');
}

/** The contents of the recipes pop-up. */
export function recipesMenu(host: RecipeMenuHost, close: () => void): HTMLElement {
  let recipes = loadRecipes();
  const list = h('div', { class: 'recipe-list' });
  const el = h('div', { class: 'recipes' });

  const commit = (next: Recipe[]) => {
    recipes = next;
    saveRecipes(recipes);
    draw();
  };

  const row = (recipe: Recipe) => {
    const name = h('button', { class: 'menu-item recipe-run', title: 'Run this recipe on the document' }, h('span', { class: 'name' }, recipe.name), h('span', { class: 'hint' }, recipeSummary(recipe)));
    const load = h('button', { class: 'tool', title: 'Put this search into the find bar without running it', html: '<span class="glyph">⤓</span>' });
    const rename = h('button', { class: 'tool', title: 'Rename', html: '<span class="glyph">✎</span>' });
    const remove = h('button', { class: 'tool', title: 'Delete', html: '<span class="glyph">×</span>' });
    const line = h('div', { class: 'recipe' }, name, load, rename, remove);

    name.addEventListener('click', () => {
      close();
      host.run(recipe);
    });

    load.addEventListener('click', () => {
      close();
      host.load(recipe);
    });

    rename.addEventListener('click', () => {
      const input = h('input', { class: 'field', value: recipe.name });
      const done = (keep: boolean) => (keep && input.value.trim() ? commit(renameRecipe(recipes, recipe.id, input.value)) : draw());

      input.addEventListener('keydown', (event) => {
        if (event.key === 'Enter' || event.key === 'Escape') {
          event.preventDefault();
          event.stopPropagation();
          done(event.key === 'Enter');
        }
      });
      input.addEventListener('blur', () => done(true));
      name.replaceWith(input);
      input.focus();
      input.select();
    });

    remove.addEventListener('click', async () => {
      const yes = await ask('Delete recipe', `Delete the recipe “${recipe.name}”?`, [{ label: 'Delete', value: true, primary: true }, { label: 'Keep', value: false }], false);
      if (yes) commit(deleteRecipe(recipes, recipe.id));
    });

    return line;
  };

  const draw = () => {
    list.replaceChildren(...(recipes.length ? recipes.map(row) : [h('p', { class: 'note' }, 'No recipes yet.')]));
  };

  // Saving what the bar holds now.
  const saveForm = () => {
    const state = host.state();
    const name = h('input', { class: 'field', placeholder: 'Name of the recipe' });
    const action = h('select', { class: 'tool-select', title: 'What is done to every match' }, h('option', { value: '' }, 'No formatting'));
    const choices: RecipeFormat[] = [];

    const option = (label: string, format: RecipeFormat) => {
      action.append(h('option', { value: String(choices.length) }, label));
      choices.push(format);
    };

    if (state.lastFormat && !ACTIONS.some((a) => JSON.stringify(a.format) === JSON.stringify(state.lastFormat!.format))) option(state.lastFormat.label, state.lastFormat.format);
    for (const a of ACTIONS) option(a.label, a.format);

    const target = h('select', { class: 'tool-select', title: 'Where the formatting goes' }, h('option', { value: 'variables' }, 'Only the variables'), h('option', { value: 'match' }, 'The whole match'));
    target.value = state.target;
    target.hidden = state.mode === 'text';

    const replace = h('input', { type: 'checkbox' });
    replace.checked = state.replacement !== '';

    const save = h('button', { class: 'button primary' }, 'Save');
    const form = h(
      'div',
      { class: 'recipe-form' },
      h('div', { class: 'menu-label' }, 'Save the current search'),
      name,
      h('div', { class: 'find-format-row' }, action, target),
      h('label', { class: 'check' }, replace, state.replacement ? `Replace with “${state.replacement}”` : 'Replace with nothing (delete the matches)'),
      h('div', { class: 'find-format-row' }, save),
    );

    const submit = () => {
      if (!state.query && !state.filter) {
        name.placeholder = 'Search for something first';
        return;
      }

      const format = action.value === '' ? null : choices[Number(action.value)];
      const replacement = replace.checked ? state.replacement : null;
      if (!format && replacement === null) {
        action.focus();
        return;
      }

      commit(
        addRecipe(recipes, {
          name: name.value.trim() || state.query || describeFilter(state.filter ?? {}),
          mode: state.mode,
          query: state.query,
          matchCase: state.matchCase,
          filter: state.filter,
          replace: replacement,
          format,
          target: target.value === 'variables' ? 'variables' : 'match',
        }),
      );
      form.remove();
      saveButton.hidden = false;
    };

    save.addEventListener('click', submit);
    name.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        submit();
      }
    });

    // Something to do is needed: the formatting last used, or the replacement typed.
    if (state.lastFormat) action.value = '0';
    else if (!state.replacement) action.value = '0';

    return { form, name };
  };

  const saveButton = h('button', { class: 'button', title: 'Save what the find bar holds now as a recipe' }, 'Save current search…');
  saveButton.addEventListener('click', () => {
    const { form, name } = saveForm();
    saveButton.hidden = true;
    el.append(form);
    name.focus();
  });

  const restore = h('button', { class: 'button', title: 'Bring back the recipes that came with the editor' }, 'Restore built-ins');
  restore.addEventListener('click', () => commit(restoreBuiltins(recipes)));

  draw();
  el.append(h('div', { class: 'menu-label' }, 'Recipes: click one to run it'), list, h('div', { class: 'find-format-row' }, saveButton, restore));

  return el;
}
