// Citation styles: how a citation and a bibliography entry read in APA 7, MLA 9 and Chicago 17
// (author-date). Pure functions from sources to runs of text, some of them italic.

import { formatNote, nbEntry } from './chicago-notes';
import { type Kind, type Name, type Source, bareDoi, field, kindOf, people } from './model';

export type StyleId = 'apa' | 'mla' | 'chicago' | 'chicago-nb';

export const STYLES: { id: StyleId; label: string }[] = [
  { id: 'apa', label: 'APA 7th edition' },
  { id: 'mla', label: 'MLA 9th edition' },
  { id: 'chicago', label: 'Chicago 17th edition (author-date)' },
  { id: 'chicago-nb', label: 'Chicago 17th edition (notes and bibliography)' },
];

/** Bibliography headings Word gives each style's list. */
export const LIST_TITLES: Record<StyleId, string> = { apa: 'References', mla: 'Works Cited', chicago: 'References', 'chicago-nb': 'Bibliography' };

export interface Run {
  text: string;
  italic?: boolean;
}

/** One source in a citation, with what the citation adds to it (Word's CITATION switches). */
export interface CiteItem {
  source: Source | null;
  tag: string;
  pages?: string;
  volume?: string;
  prefix?: string;
  suffix?: string;
  noAuthor?: boolean;
  noYear?: boolean;
  noTitle?: boolean;
}

/** What a style needs to know about the other sources a document cites. */
export interface Cited {
  /** The letter that tells works by the same authors in the same year apart: "a", "b", or "". */
  letter: (source: Source) => string;
  /** MLA: whether the authors have more than one cited work, so a citation also gives the title. */
  needsTitle: (source: Source) => boolean;
}

export const NO_CITED: Cited = { letter: () => '', needsTitle: () => false };

// ---- Text building ---------------------------------------------------------------------------------

export class Out {
  runs: Run[] = [];

  add(text: string | undefined | null, italic = false): this {
    if (!text) return this;
    const last = this.runs[this.runs.length - 1];
    if (last && !!last.italic === italic) last.text += text;
    else this.runs.push(italic ? { text, italic } : { text });
    return this;
  }

  addRuns(runs: Run[]): this {
    for (const run of runs) this.add(run.text, !!run.italic);
    return this;
  }

  get text(): string {
    return this.runs.map((r) => r.text).join('');
  }

  get empty(): boolean {
    return !this.text;
  }

  /** Ends what is there with a mark, unless it already ends with one. */
  end(mark = '.'): this {
    const text = this.text.trimEnd();
    if (!text) return this;
    if (/[.?!]["”’]*$/.test(text) && mark === '.') return this;
    return this.add(mark);
  }
}

export const plain = (runs: Run[]): string => runs.map((r) => r.text).join('');

const CURLY_OPEN = '“';
const CURLY_CLOSE = '”';

/** A quoted title, the closing mark inside the quotes: “Title.” or “Why?” */
export function quoted(out: Out, title: string, mark: string): Out {
  const ends = /[.?!]$/.test(title);
  return out.add(`${CURLY_OPEN}${title}${ends || !mark ? '' : mark}${CURLY_CLOSE}`);
}

// ---- Pieces ------------------------------------------------------------------------------------------

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
const MLA_MONTHS = ['Jan.', 'Feb.', 'Mar.', 'Apr.', 'May', 'June', 'July', 'Aug.', 'Sept.', 'Oct.', 'Nov.', 'Dec.'];

function monthIndex(text: string): number {
  const t = text.trim().toLowerCase();
  if (!t) return -1;
  if (/^\d{1,2}$/.test(t)) return Number(t) - 1;
  return MONTHS.findIndex((m) => m.toLowerCase().startsWith(t.slice(0, 3)));
}

export const monthName = (text: string, mla = false) => {
  const i = monthIndex(text);
  return i >= 0 && i < 12 ? (mla ? MLA_MONTHS : MONTHS)[i] : text.trim();
};

function ordinal(n: number): string {
  const tens = n % 100;
  if (tens >= 11 && tens <= 13) return `${n}th`;
  return `${n}${['th', 'st', 'nd', 'rd'][n % 10] ?? 'th'}`;
}

/** "2" → "2nd ed."; text that is not a number stays as it is. */
export function edition(source: Source): string {
  const ed = field(source, 'Edition');
  if (!ed) return '';
  if (/^\d+$/.test(ed)) return Number(ed) > 1 ? `${ordinal(Number(ed))} ed.` : '';
  return /\bed\b|edition/i.test(ed) ? ed : `${ed} ed.`;
}

/** A page range with the style's dash. */
const pageRange = (pages: string, dash: string) => pages.trim().replace(/\s*[-–—]+\s*/g, dash);

/** "p. 5", "pp. 5–7"; a locator that names its own unit ("chap. 3", "para. 2") as it is. */
function locator(pages: string, dash: string, prefixed: boolean): string {
  const p = pageRange(pages, dash);
  if (!prefixed || /^[^\d\s]/.test(p)) return p;
  return /[–\-,]/.test(p) ? `pp. ${p}` : `p. ${p}`;
}

export function link(source: Source, style: StyleId): string {
  const doi = bareDoi(field(source, 'DOI'));
  if (doi) return `https://doi.org/${doi}`;
  const url = field(source, 'URL');
  return style === 'mla' ? url.replace(/^https?:\/\//i, '') : url;
}

/** Books, reports, theses and websites have italic titles; parts of something else are quoted. */
export const ITALIC_TITLE: Record<Kind, boolean> = {
  book: true, chapter: false, article: false, conference: false, report: true, thesis: true, website: true, generic: true,
};

export const authorsOf = (source: Source): Name[] => {
  const authors = people(source, 'Author');
  return authors.length ? authors : [];
};

/** "John Paul" → "J. P."; "Jean-Paul" → "J.-P." */
export function initials(given: string): string {
  return given
    .split(/\s+/)
    .filter(Boolean)
    .map((word) =>
      word
        .split('-')
        .map((part) => (part.endsWith('.') && part.length <= 3 ? part : `${part.charAt(0).toUpperCase()}.`))
        .join('-'),
    )
    .join(' ');
}

export const given = (name: Name) => [name.first, name.middle].filter(Boolean).join(' ');
export const familyOf = (name: Name) => name.corporate ?? name.last ?? given(name);

/** "Smith, J. P." */
const apaInverted = (n: Name) => (n.corporate ? n.corporate : [n.last, initials(given(n))].filter(Boolean).join(', '));
/** "J. P. Smith" */
const apaDirect = (n: Name) => (n.corporate ? n.corporate : [initials(given(n)), n.last].filter(Boolean).join(' '));
/** "Smith, John Paul" */
const fullInverted = (n: Name) => (n.corporate ? n.corporate : [n.last, given(n)].filter(Boolean).join(', '));
/** "John Paul Smith" */
export const fullDirect = (n: Name) => (n.corporate ? n.corporate : [given(n), n.last].filter(Boolean).join(' '));

/** "A, B, and C" with the style's word for "and" and serial comma. */
export function series(items: string[], and: string): string {
  if (items.length <= 1) return items.join('');
  if (items.length === 2) return `${items[0]} ${and} ${items[1]}`;
  return `${items.slice(0, -1).join(', ')}, ${and} ${items[items.length - 1]}`;
}

function apaAuthors(names: Name[]): string {
  const all = names.map(apaInverted);
  if (all.length === 1) return all[0];
  if (all.length <= 20) return `${all.slice(0, -1).join(', ')}, & ${all[all.length - 1]}`;
  return `${all.slice(0, 19).join(', ')}, . . . ${all[all.length - 1]}`;
}

function mlaAuthors(names: Name[]): string {
  if (names.length === 1) return fullInverted(names[0]);
  if (names.length === 2) return `${fullInverted(names[0])}, and ${fullDirect(names[1])}`;
  return `${fullInverted(names[0])}, et al.`;
}

export function chicagoAuthors(names: Name[]): string {
  const list = names.length > 10 ? names.slice(0, 7) : names;
  const all = list.map((n, i) => (i === 0 ? fullInverted(n) : fullDirect(n)));
  if (names.length > 10) return `${all.join(', ')}, et al.`;
  if (all.length === 2) return `${all[0]}, and ${all[1]}`;
  return series(all, 'and');
}

/** The names a citation gives. */
function citeNames(names: Name[], style: StyleId): string {
  const last = names.map(familyOf);
  if (last.length === 1) return last[0];
  if (style === 'apa') return last.length === 2 ? `${last[0]} & ${last[1]}` : `${last[0]} et al.`;
  if (style === 'mla') return last.length === 2 ? `${last[0]} and ${last[1]}` : `${last[0]} et al.`;
  if (last.length === 2) return `${last[0]} and ${last[1]}`;
  return last.length === 3 ? series(last, 'and') : `${last[0]} et al.`;
}

export const yearOf = (source: Source) => field(source, 'Year');

function dated(source: Source, cited: Cited): string {
  const year = yearOf(source);
  const letter = cited.letter(source);
  return year ? `${year}${letter}` : `n.d.${letter ? `-${letter}` : ''}`;
}

const shortTitle = (source: Source) => field(source, 'ShortTitle') || field(source, 'Title');

/** A title in a citation (when there are no authors): italic or quoted, by kind. */
function citeTitle(out: Out, source: Source): void {
  const title = shortTitle(source);
  if (ITALIC_TITLE[kindOf(source)]) out.add(title, true);
  else out.add(`${CURLY_OPEN}${title}${CURLY_CLOSE}`);
}

// ---- Citations ------------------------------------------------------------------------------------------

function citeItem(item: CiteItem, style: StyleId, cited: Cited): Run[] {
  const out = new Out();
  const source = item.source;

  if (!source) return out.add(item.tag ? `${item.tag}?` : '?').runs;

  const names = authorsOf(source);
  const showAuthor = !item.noAuthor;
  const head = new Out();

  if (showAuthor) {
    if (names.length) head.add(citeNames(names, style));
    else if (!item.noTitle) citeTitle(head, source);
  }

  if (style === 'mla') {
    // MLA gives no year; a second work by the same authors is told apart by its title.
    if (!item.noTitle && names.length && cited.needsTitle(source)) {
      if (!head.empty) head.add(', ');
      citeTitle(head, source);
    }
    const where = [item.volume, item.pages && locator(item.pages, '-', false)].filter(Boolean).join(':');
    out.addRuns(head.runs);
    if (where) out.add(out.empty ? where : ` ${where}`);
    if (out.empty && !item.noTitle) citeTitle(out, source);
  } else {
    const year = item.noYear ? '' : dated(source, cited);
    const where = [item.volume && `Vol. ${item.volume}`, item.pages && locator(item.pages, '–', style === 'apa')].filter(Boolean).join(', ');

    out.addRuns(head.runs);
    if (year) out.add(head.empty ? year : style === 'apa' ? `, ${year}` : ` ${year}`);
    if (where) out.add(out.empty ? where : `, ${where}`);
  }

  const result = new Out();
  if (item.prefix) result.add(`${item.prefix.trimEnd()} `);
  result.addRuns(out.runs);
  if (item.suffix) result.add(/^[,;.:]/.test(item.suffix.trim()) ? item.suffix.trim() : `, ${item.suffix.trim()}`);
  return result.runs;
}

/** A citation: "(Smith, 2020, p. 4; Jones, 2019)". */
export function formatCitation(style: StyleId, items: CiteItem[], cited: Cited = NO_CITED): Run[] {
  // In the text rather than in a note: the short note in parentheses (src/cite/chicago-notes.ts).
  if (style === 'chicago-nb') return new Out().add('(').addRuns(formatNote(items, 'short', false)).add(')').runs;
  const list = style === 'apa' ? [...items].sort((a, b) => compareKeys(citeSortKey(a, cited), citeSortKey(b, cited))) : items;
  const out = new Out().add('(');
  list.forEach((item, i) => {
    if (i) out.add('; ');
    out.addRuns(citeItem(item, style, cited));
  });
  return out.add(')').runs;
}

/** APA lists the works in a citation as its reference list does: by author, then year. */
const citeSortKey = (item: CiteItem, cited: Cited) => (item.source ? `${sortKey(item.source)}${dated(item.source, cited)}` : item.tag.toLowerCase());

// ---- Bibliography entries ---------------------------------------------------------------------------------

function editorsApa(source: Source): string {
  const eds = people(source, 'Editor');
  if (!eds.length) return '';
  const list = eds.map(apaDirect);
  const joined = list.length === 2 ? `${list[0]} & ${list[1]}` : list.length > 2 ? `${list.slice(0, -1).join(', ')}, & ${list[list.length - 1]}` : list[0];
  return `${joined} (${eds.length > 1 ? 'Eds.' : 'Ed.'})`;
}

export const editorsFull = (source: Source) => series(people(source, 'Editor').map(fullDirect), 'and');

function apaEntry(source: Source, cited: Cited): Run[] {
  const kind = kindOf(source);
  const out = new Out();
  const names = authorsOf(source);
  const title = field(source, 'Title');
  const italic = ITALIC_TITLE[kind];

  let date = dated(source, cited);
  if (kind === 'website' && yearOf(source) && field(source, 'Month')) {
    date = `${yearOf(source)}${cited.letter(source)}, ${monthName(field(source, 'Month'))}${field(source, 'Day') ? ` ${field(source, 'Day')}` : ''}`;
  }

  const titlePart = (o: Out) => o.add(title, italic);
  const details = (o: Out, inner: string[]) => {
    const list = inner.filter(Boolean);
    if (list.length) o.add(` (${list.join(', ')})`);
  };

  if (names.length) {
    out.add(apaAuthors(names)).end().add(` (${date}). `);
    titlePart(out);
  } else {
    titlePart(out);
  }

  const pages = field(source, 'Pages') && `pp. ${pageRange(field(source, 'Pages'), '–')}`;
  const volume = field(source, 'Volume');

  switch (kind) {
    case 'book':
      details(out, [edition(source), volume && `Vol. ${volume}`]);
      break;
    case 'report': {
      const number = field(source, 'StandardNumber');
      details(out, [number ? `${field(source, 'ReportType') || 'Report'} No. ${number}` : '']);
      break;
    }
    case 'thesis':
      out.add(` [${[field(source, 'ThesisType'), field(source, 'Institution')].filter(Boolean).join(', ')}]`);
      break;
  }

  out.end();
  if (!names.length) out.add(` (${date}).`);

  const container = (name: string) => {
    out.add(' In ');
    const eds = editorsApa(source);
    if (eds) out.add(`${eds}, `);
    out.add(name, true);
    details(out, [kind === 'chapter' ? edition(source) : '', pages]);
    out.end();
  };

  switch (kind) {
    case 'chapter':
      container(field(source, 'BookTitle'));
      if (field(source, 'Publisher')) out.add(` ${field(source, 'Publisher')}`).end();
      break;
    case 'conference':
      container(field(source, 'ConferenceName'));
      if (field(source, 'Publisher')) out.add(` ${field(source, 'Publisher')}`).end();
      break;
    case 'article': {
      const journal = field(source, 'JournalName') || field(source, 'PeriodicalTitle');
      if (journal) {
        out.add(' ').add(journal, true);
        if (volume) out.add(', ', true).add(volume, true);
        if (field(source, 'Issue')) out.add(`(${field(source, 'Issue')})`);
        if (field(source, 'Pages')) out.add(`, ${pageRange(field(source, 'Pages'), '–')}`);
        out.end();
      }
      break;
    }
    case 'website':
      if (field(source, 'InternetSiteTitle')) out.add(` ${field(source, 'InternetSiteTitle')}`).end();
      break;
    case 'thesis':
      break;
    default:
      if (field(source, 'Publisher')) out.add(` ${field(source, 'Publisher')}`).end();
  }

  const at = link(source, 'apa');
  if (at) out.add(` ${at}`);
  return out.runs;
}

function mlaEntry(source: Source): Run[] {
  const kind = kindOf(source);
  const out = new Out();
  const names = authorsOf(source);
  const title = field(source, 'Title');

  if (names.length) out.add(mlaAuthors(names)).end().add(' ');
  if (ITALIC_TITLE[kind]) out.add(title, true).end();
  else quoted(out, title, '.');

  const year = yearOf(source);
  const month = field(source, 'Month') && monthName(field(source, 'Month'), true);
  const day = field(source, 'Day');
  const date = [day && month ? day : '', month, year].filter(Boolean).join(' ');
  const pages = field(source, 'Pages') && `pp. ${pageRange(field(source, 'Pages'), '-')}`;
  const elements: Out[] = [];
  const el = (text: string, italic = false) => text && elements.push(new Out().add(text, italic));
  const editors = editorsFull(source);
  const at = link(source, 'mla');

  switch (kind) {
    case 'chapter':
    case 'conference':
      el(kind === 'chapter' ? field(source, 'BookTitle') : field(source, 'ConferenceName'), true);
      if (editors) el(`edited by ${editors}`);
      el(edition(source));
      el(field(source, 'Publisher'));
      el(year);
      el(pages);
      break;
    case 'article':
      el(field(source, 'JournalName') || field(source, 'PeriodicalTitle'), true);
      el(field(source, 'Volume') && `vol. ${field(source, 'Volume')}`);
      el(field(source, 'Issue') && `no. ${field(source, 'Issue')}`);
      el(date);
      el(pages);
      break;
    case 'website':
      el(field(source, 'InternetSiteTitle'), true);
      el(date);
      break;
    case 'thesis':
      break;
    default:
      if (editors) el(`edited by ${editors}`);
      el(edition(source));
      el(field(source, 'Publisher'));
      el(year);
  }

  el(at);

  if (elements.length) {
    out.add(' ');
    elements.forEach((e, i) => {
      if (i) out.add(', ');
      out.addRuns(e.runs);
    });
    out.end();
  }

  if (kind === 'thesis') {
    if (year) out.add(` ${year}.`);
    const where = [field(source, 'Institution'), field(source, 'ThesisType')].filter(Boolean).join(', ');
    if (where) out.add(` ${where}`).end();
  }

  return out.runs;
}

function chicagoEntry(source: Source, cited: Cited): Run[] {
  const kind = kindOf(source);
  const out = new Out();
  const names = authorsOf(source);
  const title = field(source, 'Title');
  const date = dated(source, cited);
  const place = [field(source, 'City'), field(source, kind === 'thesis' ? 'Institution' : 'Publisher')].filter(Boolean).join(': ');
  const italic = ITALIC_TITLE[kind] && kind !== 'thesis';
  const titled = (o: Out) => (italic ? o.add(title, true).end() : quoted(o, title, '.'));

  if (names.length) {
    out.add(chicagoAuthors(names)).end().add(` ${date}. `);
    titled(out);
  } else {
    titled(out);
    out.add(` ${date}.`);
  }

  const sentence = (text: string, italicText = false) => {
    if (text) out.add(' ').add(text, italicText).end();
  };

  switch (kind) {
    case 'chapter':
    case 'conference': {
      out.add(' In ').add(kind === 'chapter' ? field(source, 'BookTitle') : field(source, 'ConferenceName'), true);
      const editors = editorsFull(source);
      if (editors) out.add(`, edited by ${editors}`);
      if (field(source, 'Pages')) out.add(`, ${pageRange(field(source, 'Pages'), '–')}`);
      out.end();
      sentence(edition(source));
      sentence(place);
      break;
    }
    case 'article': {
      const journal = field(source, 'JournalName') || field(source, 'PeriodicalTitle');
      out.add(' ').add(journal, true);
      if (field(source, 'Volume')) out.add(` ${field(source, 'Volume')}`);
      if (field(source, 'Issue')) out.add(` (${field(source, 'Issue')})`);
      if (field(source, 'Pages')) out.add(`: ${pageRange(field(source, 'Pages'), '–')}`);
      out.end();
      break;
    }
    case 'report': {
      sentence([field(source, 'ReportType'), field(source, 'StandardNumber')].filter(Boolean).join(' '));
      sentence(place);
      break;
    }
    case 'thesis':
      sentence([field(source, 'ThesisType'), field(source, 'Institution')].filter(Boolean).join(', '));
      break;
    case 'website':
      sentence(field(source, 'InternetSiteTitle'));
      if (field(source, 'Month')) sentence([monthName(field(source, 'Month')), field(source, 'Day') && `${field(source, 'Day')},`, yearOf(source)].filter(Boolean).join(' '));
      break;
    default:
      sentence(edition(source));
      sentence(place);
  }

  const at = link(source, 'chicago');
  if (at) out.add(` ${at}`).end();
  return out.runs;
}

/** A bibliography entry. */
export function formatEntry(style: StyleId, source: Source, cited: Cited = NO_CITED): Run[] {
  if (style === 'mla') return mlaEntry(source);
  if (style === 'chicago') return chicagoEntry(source, cited);
  if (style === 'chicago-nb') return nbEntry(source);
  return apaEntry(source, cited);
}

// ---- Order and telling works apart ------------------------------------------------------------------------

const withoutArticle = (title: string) => title.replace(/^(?:the|an?)\s+/i, '');

/** What a bibliography is sorted by: the authors' names, or the title when there are none. */
function sortKey(source: Source): string {
  const names = authorsOf(source);
  if (!names.length) return withoutArticle(field(source, 'Title')).toLowerCase();
  return names.map((n) => (n.corporate ? n.corporate : `${n.last ?? ''} ${given(n)}`).toLowerCase()).join('\u0001');
}

const compareKeys = (a: string, b: string) => a.localeCompare(b, undefined, { sensitivity: 'base', numeric: true });

/** Sources in the order the style lists them. */
export function sortSources(style: StyleId, sources: Source[]): Source[] {
  return [...sources].sort((a, b) => {
    const byName = compareKeys(sortKey(a), sortKey(b));
    if (byName) return byName;
    if (style !== 'mla') {
      // Works with no date first, then by year.
      const ya = yearOf(a) || '0';
      const yb = yearOf(b) || '0';
      const byYear = compareKeys(ya, yb);
      if (byYear) return byYear;
    }
    return compareKeys(withoutArticle(field(a, 'Title')), withoutArticle(field(b, 'Title')));
  });
}

/** Works out the letters and titles that tell the cited sources apart. */
export function citedContext(sources: Source[]): Cited {
  const letters = new Map<Source, string>();
  const byAuthors = new Map<string, Source[]>();
  const groups = new Map<string, Source[]>();

  for (const source of sources) {
    const names = authorsOf(source);
    if (!names.length) continue;
    const authors = sortKey(source);
    byAuthors.set(authors, [...(byAuthors.get(authors) ?? []), source]);
    const key = `${authors}\u0002${yearOf(source)}`;
    groups.set(key, [...(groups.get(key) ?? []), source]);
  }

  for (const group of groups.values()) {
    if (group.length < 2) continue;
    const ordered = [...group].sort((a, b) => compareKeys(withoutArticle(field(a, 'Title')), withoutArticle(field(b, 'Title'))));
    ordered.forEach((source, i) => letters.set(source, i < 26 ? String.fromCharCode(97 + i) : `${i + 1}`));
  }

  return {
    letter: (source) => letters.get(source) ?? '',
    needsTitle: (source) => (byAuthors.get(sortKey(source))?.length ?? 0) > 1,
  };
}
