// The field types the editor calculates: SEQ, REF, PAGEREF and TOC. Each is registered with
// update.ts; see the top of that file for how to add another.

import type { Node as PMNode } from 'prosemirror-model';
import type { Transaction } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { schema } from '../editor/schema';
import { bookmarkNodes, ensureFieldStyle, fieldNodes, newBookmarkName, textWidthTwips } from './build';
import { type Bookmark, type Field, type FieldScan, parseInstr, scanFields, visibleText } from './model';
import { formatNumber, formatText, outlineLevel } from './seq';
import { type UpdateEnv, registerField } from './update';

const N = schema.nodes;
const M = schema.marks;

export const NO_REFERENCE = 'Error! Reference source not found.';
export const NO_TOC_ENTRIES = 'No table of contents entries found.';
export const NO_FIGURE_ENTRIES = 'No table of figures entries found.';

/** A bookmark by name; Word's names are not case-sensitive. */
export function findBookmark(scan: FieldScan, name: string): Bookmark | null {
  const exact = scan.bookmarks.get(name);
  if (exact) return exact;

  const lower = name.toLowerCase();
  for (const [key, bookmark] of scan.bookmarks) if (key.toLowerCase() === lower) return bookmark;

  return null;
}

/** The text a bookmark holds, as REF shows it. */
export function bookmarkText(doc: PMNode, bookmark: Bookmark): string {
  return visibleText(doc, bookmark.from, bookmark.to).replace(/\s+/g, ' ').trim();
}

// ---- SEQ -----------------------------------------------------------------------------------------

registerField('SEQ', {
  phase: 0,
  live: true,
  update(field, env) {
    const number = env.seq().get(field.from);
    if (number === undefined) return null;

    const instr = parseInstr(field.instr, 'rs');
    return instr.switches.has('h') ? '' : formatNumber(number, instr.formats);
  },
});

// ---- REF and PAGEREF -----------------------------------------------------------------------------

registerField('REF', {
  phase: 1,
  live: true,
  update(field, env) {
    const instr = parseInstr(field.instr, 'd');
    const bookmark = findBookmark(env.scan, instr.args[0] ?? '');
    if (!bookmark) return NO_REFERENCE;

    // Paragraph numbers (\n, \r, \w) are not worked out by the editor: the result stays.
    if (instr.switches.has('n') || instr.switches.has('r') || instr.switches.has('w')) return null;
    if (instr.switches.has('p')) return bookmark.from < field.from ? 'above' : 'below';

    return formatText(bookmarkText(env.doc, bookmark), instr.formats);
  },
});

registerField('PAGEREF', {
  phase: 1,
  pages: true,
  update(field, env) {
    const instr = parseInstr(field.instr);
    const bookmark = findBookmark(env.scan, instr.args[0] ?? '');
    if (!bookmark) return NO_REFERENCE;

    const page = env.pageOf(bookmark.from);
    if (page === null) return null;

    if (instr.switches.has('p')) {
      const here = env.pageOf(field.from);
      if (here === page) return bookmark.from < field.from ? 'above' : 'below';
      return `on page ${formatNumber(page, instr.formats)}`;
    }

    return formatNumber(page, instr.formats);
  },
});

// ---- TOC -----------------------------------------------------------------------------------------

interface TocEntry {
  /** The paragraph's position and its content's end. */
  pos: number;
  end: number;
  level: number;
  text: string;
}

function range(spec: string | true | undefined, fallback: [number, number]): [number, number] {
  if (typeof spec !== 'string') return fallback;
  const match = /^\s*(\d+)\s*-\s*(\d+)\s*$/.exec(spec);
  return match ? [Number(match[1]), Number(match[2])] : fallback;
}

/** The paragraphs a TOC field lists: headings by outline level or style, or captions for `\c`. */
export function tocEntries(field: Field, doc: PMNode, ctx: DocContext): TocEntry[] {
  const instr = parseInstr(field.instr, 'otcblnpsdf');
  const outline = instr.switches.has('o') ? range(instr.switches.get('o'), [1, 9]) : null;
  const own = instr.switches.has('u');
  const caption = instr.switches.get('c');
  const byStyle = new Map<string, number>();
  const tSwitch = instr.switches.get('t');

  if (typeof tSwitch === 'string') {
    const parts = tSwitch.split(/[,;]/).map((part) => part.trim());
    for (let i = 0; i < parts.length; i += 2) if (parts[i]) byStyle.set(parts[i].toLowerCase(), Number(parts[i + 1]) || 1);
  }

  const seqParagraphs = new Set<number>();

  if (typeof caption === 'string') {
    for (const f of scanFields(doc).fields) {
      if (f.type === 'SEQ' && (parseInstr(f.instr).args[0] ?? '').toLowerCase() === caption.toLowerCase()) {
        seqParagraphs.add(doc.resolve(f.from).before());
      }
    }
  }

  const entries: TocEntry[] = [];

  doc.descendants((node, pos) => {
    if (node.type !== N.paragraph) return !node.isInline;
    if (pos >= field.from && pos < field.to) return false;

    let level: number | null = null;

    if (typeof caption === 'string') {
      level = seqParagraphs.has(pos) ? 1 : null;
    } else {
      const name = ctx.styles.byId.get(node.attrs.styleId ?? '')?.name.toLowerCase();
      if (name && byStyle.has(name)) level = byStyle.get(name)!;

      if (level === null && own) {
        const ownLevel = outlineLevel(ctx, node, true);
        if (ownLevel !== null && (!outline || (ownLevel + 1 >= outline[0] && ownLevel + 1 <= outline[1]))) level = ownLevel + 1;
      }

      if (level === null && outline) {
        const styleLevel = outlineLevel(ctx, node);
        if (styleLevel !== null && styleLevel + 1 >= outline[0] && styleLevel + 1 <= outline[1]) level = styleLevel + 1;
      }
    }

    if (level === null) return false;

    const text = visibleText(doc, pos + 1, pos + node.nodeSize - 1).replace(/\s+/g, ' ').trim();
    if (text) entries.push({ pos, end: pos + node.nodeSize - 1, level: Math.min(9, Math.max(1, level)), text });
    return false;
  });

  return entries;
}

/** The `_Toc` bookmark that starts in a paragraph, if there is one. */
function tocBookmark(scan: FieldScan, entry: TocEntry): Bookmark | null {
  for (const bookmark of scan.bookmarks.values()) {
    if (bookmark.name.startsWith('_Toc') && bookmark.from >= entry.pos && bookmark.from <= entry.end) return bookmark;
  }

  return null;
}

/** Puts a `_Toc` bookmark around every heading a TOC lists that has none yet. */
function prepareToc(fields: Field[], tr: Transaction, env: UpdateEnv): void {
  const scan = scanFields(tr.doc);
  const wanted = new Map<number, TocEntry>();

  for (const field of fields) {
    for (const entry of tocEntries(field, tr.doc, env.ctx)) if (!tocBookmark(scan, entry)) wanted.set(entry.pos, entry);
  }

  let id = scan.maxId;
  const taken = new Set<string>();
  const list = [...wanted.values()].sort((a, b) => b.pos - a.pos);

  for (const entry of list) {
    const [start, end] = bookmarkNodes(newBookmarkName('_Toc', scan, taken), ++id);
    tr.insert(entry.end, end);
    tr.insert(entry.pos + 1, start);
  }
}

/** The same key for the same entry every time, so a TOC updated twice over is the same document. */
function linkKey(name: string): number {
  let hash = 0;
  for (const c of name) hash = (hash * 31 + c.charCodeAt(0)) | 0;
  return -Math.abs(hash) - 1;
}

function tocUpdate(field: Field, env: UpdateEnv) {
  const { doc, ctx, scan } = env;
  const instr = parseInstr(field.instr, 'otcblnpsdf');
  const figures = typeof instr.switches.get('c') === 'string';
  const links = instr.switches.has('h');
  const noPages = instr.switches.get('n');
  const noPageLevels = noPages === undefined ? null : noPages === true ? ([1, 9] as [number, number]) : range(noPages, [1, 9]);
  const width = textWidthTwips(ctx);
  const ppr = `<w:tabs><w:tab w:val="right" w:leader="dot" w:pos="${width}"/></w:tabs>`;
  const entries = tocEntries(field, doc, ctx);

  if (!entries.length) {
    return { blocks: [N.paragraph.create(null, schema.text(figures ? NO_FIGURE_ENTRIES : NO_TOC_ENTRIES))] };
  }

  const blocks = entries.map((entry) => {
    const bookmark = tocBookmark(scan, entry);
    const styleId = ensureFieldStyle(ctx, figures ? 'table of figures' : `toc ${entry.level}`);
    const marks = links && bookmark ? [M.link.create({ href: `#${bookmark.name}`, k: linkKey(bookmark.name), depth: 0 })] : [];
    const content: PMNode[] = [schema.text(entry.text, marks)];
    const showPage = !noPageLevels || entry.level < noPageLevels[0] || entry.level > noPageLevels[1];

    if (showPage && bookmark) {
      const page = env.pageOf(entry.pos + 1);
      content.push(schema.text('\t', marks), ...fieldNodes(`PAGEREF ${bookmark.name} \\h`, page === null ? '' : String(page), marks));
    }

    return N.paragraph.create({ styleId, ppr }, content);
  });

  return { blocks };
}

registerField('TOC', {
  phase: 2,
  pages: true,
  onSave: false,
  prepare: prepareToc,
  update: tocUpdate,
});
