// A .docx as what it is on disk: a zip of parts, most of them XML, tied together by
// relationship files. Parts the editor never looks at stay as the bytes they came as.

import { unzipSync, zipSync, type Zippable } from 'fflate';
import { escAttr, parseXml } from './xml';

export interface Rel {
  id: string;
  type: string;
  target: string;
  external: boolean;
}

const REL_NS = 'http://schemas.openxmlformats.org/package/2006/relationships';
export const REL_TYPE = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';

/** Formats that are compressed already; deflating them again costs time and saves nothing. */
const STORED = /\.(png|jpe?g|gif|webp|zip|mp4|mp3)$/i;

export class NotDocxError extends Error {}

export class DocxPackage {
  constructor(readonly files: Map<string, Uint8Array>) {}

  static open(bytes: Uint8Array): DocxPackage {
    // A password-protected or pre-2007 .doc file is an OLE container, not a zip.
    if (bytes.length > 8 && bytes[0] === 0xd0 && bytes[1] === 0xcf && bytes[2] === 0x11 && bytes[3] === 0xe0) {
      throw new NotDocxError('This file is password-protected or in the old .doc format. Only .docx files without a password can be opened.');
    }

    let entries: Record<string, Uint8Array>;

    try {
      entries = unzipSync(bytes);
    } catch {
      throw new NotDocxError('This file is not a .docx document, or it is damaged.');
    }

    const files = new Map<string, Uint8Array>();

    for (const [name, data] of Object.entries(entries)) {
      if (!name.endsWith('/')) files.set(name, data);
    }

    if (!files.has('[Content_Types].xml')) {
      throw new NotDocxError('This file is a zip archive, but not a .docx document.');
    }

    return new DocxPackage(files);
  }

  /** A copy that can be changed without touching this one. The bytes themselves are shared. */
  clone(): DocxPackage {
    return new DocxPackage(new Map(this.files));
  }

  has(path: string): boolean {
    return this.files.has(path);
  }

  get(path: string): Uint8Array | null {
    return this.files.get(path) ?? null;
  }

  set(path: string, bytes: Uint8Array): void {
    this.files.set(path, bytes);
  }

  text(path: string): string | null {
    const bytes = this.files.get(path);
    if (!bytes) return null;

    // Word writes UTF-8. A few other programs write UTF-16, with a byte-order mark saying so.
    if (bytes.length >= 2 && bytes[0] === 0xff && bytes[1] === 0xfe) {
      return new TextDecoder('utf-16le').decode(bytes).replace(/encoding=(["'])[^"']*\1/, 'encoding="UTF-8"');
    }

    if (bytes.length >= 2 && bytes[0] === 0xfe && bytes[1] === 0xff) {
      return new TextDecoder('utf-16be').decode(bytes).replace(/encoding=(["'])[^"']*\1/, 'encoding="UTF-8"');
    }

    return new TextDecoder('utf-8').decode(bytes);
  }

  setText(path: string, text: string): void {
    this.files.set(path, new TextEncoder().encode(text));
  }

  toBytes(): Uint8Array {
    const zippable: Zippable = {};

    for (const [name, data] of this.files) {
      zippable[name] = [data, { level: STORED.test(name) ? 0 : 6 }];
    }

    return zipSync(zippable);
  }
}

/** Where a part's relationships are kept: word/document.xml → word/_rels/document.xml.rels. */
export function relsPathFor(part: string): string {
  const slash = part.lastIndexOf('/');
  return `${part.slice(0, slash + 1)}_rels/${part.slice(slash + 1)}.rels`;
}

/** The folder a part is in, with its trailing slash; '' for the package root. */
export function dirOf(part: string): string {
  return part.slice(0, part.lastIndexOf('/') + 1);
}

/** A relationship's target as a part name: relative to the part that owns it, or from the root. */
export function resolveTarget(ownerPart: string, target: string): string {
  if (target.startsWith('/')) return target.slice(1);

  const parts = dirOf(ownerPart).split('/').filter(Boolean);

  for (const piece of target.split('/')) {
    if (piece === '..') parts.pop();
    else if (piece !== '.' && piece !== '') parts.push(piece);
  }

  return parts.join('/');
}

export function parseRels(xml: string | null): Rel[] {
  if (!xml) return [];

  return parseXml(xml).children
    .filter((el) => el.name === 'Relationship' || el.name.endsWith(':Relationship'))
    .map((el) => ({
      id: el.attrs.Id ?? '',
      type: el.attrs.Type ?? '',
      target: el.attrs.Target ?? '',
      external: el.attrs.TargetMode === 'External',
    }));
}

/** A relationship's kind without its namespace, which differs between the two flavours of the format. */
export function relKind(rel: Rel): string {
  return rel.type.slice(rel.type.lastIndexOf('/') + 1);
}

export function relXml(rel: Rel): string {
  return `<Relationship Id="${escAttr(rel.id)}" Type="${escAttr(rel.type)}" Target="${escAttr(rel.target)}"${rel.external ? ' TargetMode="External"' : ''}/>`;
}

/** Adds relationships to a relationships part, making the part if there is none. */
export function addRels(xml: string | null, rels: Rel[]): string {
  const added = rels.map(relXml).join('');

  if (!xml) {
    return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="${REL_NS}">${added}</Relationships>`;
  }

  const root = parseXml(xml);

  // <Relationships/> with nothing in it has no closing tag to put them before.
  if (root.innerStart === root.end) {
    return `${xml.slice(0, root.start)}${xml.slice(root.start, root.end).replace(/\s*\/>$/, '>')}${added}</${root.name}>${xml.slice(root.end)}`;
  }

  return xml.slice(0, root.innerEnd) + added + xml.slice(root.innerEnd);
}

/** Makes sure [Content_Types].xml names a type for these extensions and these parts. */
export function addContentTypes(xml: string, defaults: Map<string, string>, overrides: Map<string, string>): string {
  const root = parseXml(xml);
  const knownExt = new Set(root.children.filter((c) => c.name === 'Default').map((c) => (c.attrs.Extension ?? '').toLowerCase()));
  const knownPart = new Set(root.children.filter((c) => c.name === 'Override').map((c) => c.attrs.PartName ?? ''));
  let added = '';

  for (const [ext, type] of defaults) {
    if (!knownExt.has(ext.toLowerCase())) added += `<Default Extension="${escAttr(ext)}" ContentType="${escAttr(type)}"/>`;
  }

  for (const [part, type] of overrides) {
    if (!knownPart.has(`/${part}`)) added += `<Override PartName="/${escAttr(part)}" ContentType="${escAttr(type)}"/>`;
  }

  return added ? xml.slice(0, root.innerStart) + added + xml.slice(root.innerStart) : xml;
}

export const IMAGE_TYPES: Record<string, string> = {
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  gif: 'image/gif',
  bmp: 'image/bmp',
  webp: 'image/webp',
  svg: 'image/svg+xml',
  tif: 'image/tiff',
  tiff: 'image/tiff',
  emf: 'image/x-emf',
  wmf: 'image/x-wmf',
};

/** Image formats Chromium can draw. Word's own vector formats (EMF, WMF) and TIFF are not among them. */
export const DRAWABLE = new Set(['png', 'jpg', 'jpeg', 'gif', 'bmp', 'webp', 'svg']);

export function toBase64(bytes: Uint8Array): string {
  let binary = '';

  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000) as unknown as number[]);
  }

  return btoa(binary);
}

export function fromBase64(text: string): Uint8Array {
  const binary = atob(text);
  const bytes = new Uint8Array(binary.length);

  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }

  return bytes;
}

/** Splits a data: URL into its type and its bytes, or null if it is not a base64 one. */
export function parseDataUrl(url: string): { mime: string; bytes: Uint8Array } | null {
  const match = /^data:([^;,]+);base64,(.*)$/s.exec(url);
  if (!match) return null;

  try {
    return { mime: match[1], bytes: fromBase64(match[2]) };
  } catch {
    return null;
  }
}
