// Reading and writing Word's bibliography part: `b:Sources` with one `b:Source` per source, and
// the citation style on the root (`SelectedStyle`, `StyleName`, `Version`).

import { type XmlEl, escAttr, escText, openTag, parseXml, raw } from '../docx/xml';
import { type Name, ROLES, type Source } from './model';

export const BIB_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/bibliography';

const local = (el: XmlEl) => el.name.replace(/^.*:/, '');
const kids = (el: XmlEl | null | undefined, name: string) => (el ? el.children.filter((c) => local(c) === name) : []);
const kid = (el: XmlEl | null | undefined, name: string) => kids(el, name)[0] ?? null;

export interface SourcesPart {
  sources: Source[];
  /** The root's attributes, as read: SelectedStyle, StyleName, Version. */
  attrs: Record<string, string>;
  /** The root's open tag, kept so its namespaces and anything else on it survive. */
  open: string | null;
}

/** Whether an XML part is a bibliography part. */
export const isSourcesXml = (xml: string): boolean => /<(?:\w+:)?Sources\b[^>]*bibliography/.test(xml.slice(0, 2000));

export function readSources(xml: string): SourcesPart {
  const root = parseXml(xml);
  const sources = kids(root, 'Source').map(readSource);
  const attrs: Record<string, string> = {};
  for (const [key, value] of Object.entries(root.attrs)) if (!key.startsWith('xmlns')) attrs[key] = value;

  return { sources, attrs, open: openTag(root) };
}

function readNames(role: XmlEl): Name[] | null {
  const corporate = kid(role, 'Corporate');
  if (corporate) return [{ corporate: corporate.text.trim() }];

  const list = kid(role, 'NameList');
  if (!list) return null;

  return kids(list, 'Person').map((person) => {
    const name: Name = {};
    for (const part of ['Last', 'First', 'Middle'] as const) {
      const text = kid(person, part)?.text.trim();
      if (text) name[part.toLowerCase() as 'last' | 'first' | 'middle'] = text;
    }
    return name;
  });
}

function readSource(el: XmlEl): Source {
  const source: Source = { tag: '', type: 'Misc', fields: {}, people: {}, extra: [], raw: raw(el) };

  for (const c of el.children) {
    const name = local(c);

    if (name === 'Tag') source.tag = c.text.trim();
    else if (name === 'SourceType') source.type = c.text.trim();
    else if (name === 'Author') {
      // The people, by role. A role written some way the editor does not read stays as it was.
      const unread: XmlEl[] = [];
      for (const role of c.children) {
        const names = ROLES.has(local(role)) ? readNames(role) : null;
        if (names) source.people[local(role)] = names;
        else unread.push(role);
      }
      if (unread.length) source.extra.push(`<b:Author>${unread.map(raw).join('')}</b:Author>`);
    } else if (!c.children.length) source.fields[name] = c.text;
    else source.extra.push(raw(c));
  }

  return source;
}

function namesXml(names: Name[]): string {
  if (names.length === 1 && names[0].corporate) return `<b:Corporate>${escText(names[0].corporate)}</b:Corporate>`;

  const persons = names
    .filter((n) => !n.corporate)
    .map(
      (n) =>
        '<b:Person>' +
        (n.last ? `<b:Last>${escText(n.last)}</b:Last>` : '') +
        (n.first ? `<b:First>${escText(n.first)}</b:First>` : '') +
        (n.middle ? `<b:Middle>${escText(n.middle)}</b:Middle>` : '') +
        '</b:Person>',
    );
  return `<b:NameList>${persons.join('')}</b:NameList>`;
}

/** A source as a `b:Source` element: as it was read while unchanged, otherwise written afresh. */
export function sourceXml(source: Source): string {
  if (source.raw) return source.raw;

  let out = `<b:Source><b:Tag>${escText(source.tag)}</b:Tag><b:SourceType>${escText(source.type)}</b:SourceType>`;
  for (const [name, value] of Object.entries(source.fields)) {
    if (value !== '' && /^[A-Za-z][\w.-]*$/.test(name)) out += `<b:${name}>${escText(value)}</b:${name}>`;
  }

  const roles = Object.entries(source.people).filter(([, names]) => names.length);
  // Word writes one Corporate per role; a role with several organisations keeps the first.
  if (roles.length) out += `<b:Author>${roles.map(([role, names]) => `<b:${role}>${namesXml(names)}</b:${role}>`).join('')}</b:Author>`;

  // A second b:Author holding roles the editor could not read: merged into the first by Word, kept here.
  return `${out}${source.extra.join('')}</b:Source>`;
}

/** The whole part. `open` is the root's open tag as read, if there was one. */
export function writeSources(sources: Source[], attrs: Record<string, string>, open: string | null): string {
  let tag = open ?? `<b:Sources xmlns:b="${BIB_NS}" xmlns="${BIB_NS}">`;
  if (tag.endsWith('/>')) tag = `${tag.slice(0, -2)}>`;

  for (const [key, value] of Object.entries(attrs)) {
    const re = new RegExp(`\\s${key}="[^"]*"`);
    const attr = ` ${key}="${escAttr(value)}"`;
    tag = re.test(tag) ? tag.replace(re, attr) : tag.replace(/^(<[\w:]+)/, `$1${attr}`);
  }

  const name = /^<([\w:]+)/.exec(tag)![1];
  return `<?xml version="1.0" encoding="UTF-8" standalone="no"?>${tag}${sources.map(sourceXml).join('')}</${name}>`;
}
