// The document statistics dialog, and the word or character limit the status bar's count shows.

import { TextSelection } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { child } from '../docx/xml';
import { styleLevels } from '../editor/outline';
import { type CountLimit, documentStats, type Lang, limitState, parseLimit } from '../editor/stats';
import { h, store, stored } from './dom';

const LIMIT_KEY = 'text-studio:count-limit';
const LANG_KEY = 'text-studio:stats-lang';

export interface StatsHost {
  tab(): { view: EditorView; ctx: DocContext } | null;
  /** The limit changed: the status bar's count is shown again. */
  recount(): void;
}

const format = (n: number) => n.toLocaleString('en');

const LANG_FROM: Record<string, string> = {
  text: 'Recognised from the text',
  file: 'As marked in the file',
  default: 'Neither the text nor the file says; English assumed',
  chosen: 'As chosen here',
};

export class Statistics {
  limit: CountLimit | null = parseLimit(stored(LIMIT_KEY));

  constructor(private readonly host: StatsHost) {}

  /** Adds the limit to the status bar's word count, and marks it when it is passed. */
  decorate(el: HTMLElement, words: number, doc: EditorView['state']['doc'] | null): void {
    el.classList.add('stats-link');
    el.title = 'Document statistics (Ctrl+Shift+G)';
    el.classList.remove('over');

    const limit = this.limit;
    if (!limit || !doc) return;

    const characters = limit.unit === 'characters' ? [...doc.textBetween(0, doc.content.size, '', '')].length : 0;
    const state = limitState(words, characters, limit);
    const unit = limit.unit === 'words' ? 'words' : 'characters';

    el.textContent = `${format(state.used)} / ${format(limit.value)} ${unit}`;
    el.classList.toggle('over', state.over);
    el.title = state.over
      ? `${format(state.used - limit.value)} ${unit} over the limit. Click for the document statistics (Ctrl+Shift+G)`
      : `${format(limit.value - state.used)} ${unit} left. Click for the document statistics (Ctrl+Shift+G)`;
  }

  private setLimit(limit: CountLimit | null): void {
    this.limit = limit;
    store(LIMIT_KEY, limit ? JSON.stringify(limit) : '');
    this.host.recount();
  }

  open(): void {
    if (document.querySelector('.dialog-backdrop')) return;

    const tab = this.host.tab();
    if (!tab) return;

    const body = h('div', { class: 'stats-body' });
    const close = () => {
      document.removeEventListener('keydown', onKey, true);
      backdrop.remove();
      this.host.tab()?.view.focus();
    };
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        close();
      }
    };

    const langSelect = h(
      'select',
      { class: 'tool-select', title: 'Which language the readability scores are worked out for' },
      h('option', { value: '' }, 'Language: automatic'),
      h('option', { value: 'en' }, 'English'),
      h('option', { value: 'de' }, 'German'),
    );
    langSelect.value = stored(LANG_KEY) ?? '';
    langSelect.addEventListener('change', () => {
      store(LANG_KEY, langSelect.value);
      draw();
    });

    const draw = () => body.replaceChildren(...this.content(tab, (langSelect.value || null) as Lang | null, close));
    draw();

    const backdrop = h(
      'div',
      { class: 'dialog-backdrop' },
      h(
        'div',
        { class: 'dialog stats-dialog', role: 'dialog', 'aria-label': 'Document statistics' },
        h('div', { class: 'stats-title' }, h('h2', null, 'Document statistics'), langSelect),
        body,
        h('div', { class: 'buttons' }, h('button', { class: 'button primary', onclick: close }, 'Close')),
      ),
    );

    backdrop.addEventListener('mousedown', (event) => event.target === backdrop && close());
    document.addEventListener('keydown', onKey, true);
    document.body.append(backdrop);
    (backdrop.querySelector('.button.primary') as HTMLButtonElement).focus();
  }

  private content(tab: { view: EditorView; ctx: DocContext }, lang: Lang | null, close: () => void): HTMLElement[] {
    const { view, ctx } = tab;
    const fileLang = child(ctx.styles.docRPr, 'w:lang')?.attrs['w:val'] ?? null;
    const stats = documentStats(view.state.doc, { styleLevel: styleLevels(ctx.styles), fileLang, lang });
    const c = stats.counts;
    const row = (label: string, value: string, title?: string) => h('tr', { title: title ?? null }, h('th', null, label), h('td', null, value));

    const counts = h(
      'table',
      { class: 'stats-table' },
      row('Words', format(c.words)),
      row('Characters (with spaces)', format(c.characters)),
      row('Characters (without spaces)', format(c.charactersNoSpaces)),
      row('Paragraphs', format(c.paragraphs)),
      row('Sentences', format(c.sentences)),
      row('Words per sentence', c.sentences ? (c.readableWords / c.sentences).toFixed(1) : '–'),
      row('Syllables per word', c.readableWords ? (c.syllables / c.readableWords).toFixed(2) : '–'),
    );

    const scores = stats.scores.length
      ? h('table', { class: 'stats-table' }, ...stats.scores.map((s) => row(s.name, `${s.value.toLocaleString('en')}  ·  ${s.meaning}`, s.higherIsEasier ? 'Higher is easier to read' : 'Lower is easier to read')))
      : h('p', { class: 'note' }, 'There is no text to score yet.');

    const sections = stats.sections.length
      ? h(
          'div',
          { class: 'stats-sections' },
          ...stats.sections.map((s) => {
            const label = s.title ?? 'Before the first heading';
            const line = h(
              'button',
              { class: 'stats-section', style: `--level:${Math.max(1, s.level)}`, title: 'Go to this section' },
              h('span', { class: s.title ? 'name' : 'name dim' }, label),
              h('span', { class: 'value' }, format(s.words)),
            );

            line.addEventListener('click', () => {
              close();
              const pos = Math.min(s.pos + 1, view.state.doc.content.size);
              view.dispatch(view.state.tr.setSelection(TextSelection.near(view.state.doc.resolve(pos))).scrollIntoView());
              view.focus();
            });

            return line;
          }),
        )
      : h('p', { class: 'note' }, 'No headings: the whole document is one section.');

    // The limit.
    const unit = h('select', { class: 'tool-select' }, h('option', { value: 'words' }, 'words'), h('option', { value: 'characters' }, 'characters'));
    const value = h('input', { class: 'tool-input stats-limit', inputmode: 'numeric', placeholder: 'No limit' });
    unit.value = this.limit?.unit ?? 'words';
    value.value = this.limit ? String(this.limit.value) : '';

    const apply = () => {
      const n = Math.round(Number(value.value.replace(/[^\d]/g, '')));
      this.setLimit(n > 0 ? { unit: unit.value as CountLimit['unit'], value: n } : null);
      if (!(n > 0)) value.value = '';
    };
    unit.addEventListener('change', apply);
    value.addEventListener('change', apply);
    value.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        apply();
      }
    });

    const limitNote = (() => {
      if (!this.limit) return h('p', { class: 'note' }, 'Set a limit and the count in the status bar shows how much is left; it turns red when the limit is passed.');
      const state = limitState(c.words, c.characters, this.limit);
      return h('p', { class: state.over ? 'note over' : 'note' }, state.over ? 'Over the limit.' : 'Within the limit.');
    })();

    return [
      counts,
      h('div', { class: 'menu-label' }, 'Readability'),
      h('p', { class: 'note' }, `${stats.lang === 'de' ? 'German' : 'English'}: ${LANG_FROM[stats.langFrom]}.`),
      scores,
      h('div', { class: 'menu-label' }, 'Words per section'),
      sections,
      h('div', { class: 'menu-label' }, 'Limit'),
      h('div', { class: 'stats-limit-row' }, value, unit, h('button', { class: 'button', onclick: () => ((value.value = ''), apply()) }, 'No limit')),
      limitNote,
    ];
  }
}
