// The Shapes button's menu: a text box, a gallery of shapes, and the selected shape's fill and outline.

import type { Command } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import { closePopover, h, popover } from '../ui/dom';
import { insertShape, selectedShape, setShapeFill, setShapeLine } from './commands';
import { GALLERY, LINE_LIKE, presetOutline } from './geometry';

export interface ShapesHost {
  tab(): { view: EditorView } | null;
  run(command: Command): void;
}

/** The Shapes button: a rectangle over a circle. */
export const SHAPES_ICON =
  '<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.2">' +
  '<rect x="1.5" y="1.5" width="8" height="7" rx="0.5"/><circle cx="10.5" cy="10.5" r="4"/></svg>';

const COLORS = [
  '#FFFFFF', '#000000', '#E7E6E6', '#44546A', '#4472C4', '#ED7D31', '#A5A5A5', '#FFC000', '#5B9BD5', '#70AD47',
  '#F2F2F2', '#7F7F7F', '#D0CECE', '#D6DCE4', '#D9E2F3', '#FBE5D5', '#EDEDED', '#FFF2CC', '#DEEBF6', '#E2EFD9',
  '#C00000', '#FF0000', '#FFC000', '#FFFF00', '#92D050', '#00B050', '#00B0F0', '#0070C0', '#002060', '#7030A0',
];

function icon(geom: string): string {
  const lineLike = LINE_LIKE.has(geom);
  const [w, hgt] = lineLike ? [16, 12] : /^(right|left)Arrow$/.test(geom) ? [18, 10] : /^(up|down)Arrow$/.test(geom) ? [10, 18] : [18, 14];
  const paths = presetOutline(geom, w, hgt).map((o) => `<path d="${o.d}"/>`).join('');
  const head = geom === 'straightConnector1' ? `<path d="M${w} ${hgt}l-4.5 -1l1.5 -2.5z" fill="currentColor"/>` : '';

  return (
    `<svg viewBox="-1 -1 20 20" width="20" height="20" fill="${lineLike ? 'none' : 'currentColor'}" fill-opacity="0.18" stroke="currentColor" stroke-width="1.2">` +
    `<g transform="translate(${(18 - w) / 2} ${(18 - hgt) / 2})">${paths}${head}</g></svg>`
  );
}

export function shapesMenu(anchor: HTMLElement, host: ShapesHost): void {
  const tab = host.tab();
  if (!tab) return;

  const selected = selectedShape(tab.view.state);
  const run = (command: Command) => () => (closePopover(), host.run(command));
  const item = (label: string, action: () => void) => h('button', { class: 'menu-item', onclick: action }, label);

  const swatches = (set: (c: string | null) => Command, none: string, current: string | null) => {
    const custom = h('input', { type: 'color', class: 'shape-custom-color', title: 'More colours', value: current ?? '#4472C4' }) as HTMLInputElement;
    custom.addEventListener('change', () => run(set(custom.value.toUpperCase()))());

    return h(
      'div',
      { class: 'swatches' },
      h('button', { class: 'swatch none', title: none, onclick: run(set(null)) }),
      ...COLORS.slice(0, 28).map((c) => h('button', { class: 'swatch', title: c, style: `background:${c}`, onclick: run(set(c)) })),
      custom,
    );
  };

  const gallery = h(
    'div',
    { class: 'shape-gallery' },
    ...GALLERY.map((g) => h('button', { class: 'shape-gallery-item', title: g.label, html: icon(g.geom), onclick: run(insertShape(g.geom)) })),
  );

  popover(
    anchor,
    h(
      'div',
      { class: 'shapes-menu' },
      item('Text box', run(insertShape('rect', true))),
      h('div', { class: 'menu-sep' }),
      gallery,
      ...(selected
        ? [
            h('div', { class: 'menu-sep' }),
            h('div', { class: 'menu-label' }, 'Fill'),
            swatches(setShapeFill, 'No fill', selected.spec.fill),
            h('div', { class: 'menu-label' }, 'Outline'),
            swatches(setShapeLine, 'No outline', selected.spec.line),
          ]
        : []),
    ),
  );
}
