// Making fields, bookmarks and the styles they need, as the importer would have read them from Word.

import type { Mark, Node as PMNode } from 'prosemirror-model';
import type { DocContext } from '../docx/import';
import { escAttr, escText } from '../docx/xml';
import { WRAPPERS, schema } from '../editor/schema';
import type { FieldScan } from './model';

const N = schema.nodes;

const hidden = (raw: string, marks: readonly Mark[] = []) =>
  N.opaque.create({ raw, kind: 'para', look: 'hidden' }, null, marks.filter((m) => WRAPPERS.has(m.type.name)));

/** A complex field's codes: begin, instruction and separate in one hidden node, end in another. */
export function fieldCodes(instr: string, marks: readonly Mark[] = []): [PMNode, PMNode] {
  const begin =
    '<w:r><w:fldChar w:fldCharType="begin"/></w:r>' +
    `<w:r><w:instrText xml:space="preserve"> ${escText(instr)} </w:instrText></w:r>` +
    '<w:r><w:fldChar w:fldCharType="separate"/></w:r>';

  return [hidden(begin, marks), hidden('<w:r><w:fldChar w:fldCharType="end"/></w:r>', marks)];
}

/** A field with its result, ready to insert. */
export function fieldNodes(instr: string, result: string, marks: readonly Mark[] = []): PMNode[] {
  const [begin, end] = fieldCodes(instr, marks);
  return result ? [begin, schema.text(result, marks), end] : [begin, end];
}

export function bookmarkNodes(name: string, id: number): [PMNode, PMNode] {
  return [hidden(`<w:bookmarkStart w:id="${id}" w:name="${escAttr(name)}"/>`), hidden(`<w:bookmarkEnd w:id="${id}"/>`)];
}

/** A bookmark name Word would make: `_Ref` or `_Toc` and nine digits, not yet in the document. */
export function newBookmarkName(prefix: string, scan: FieldScan, taken: Set<string> = new Set()): string {
  for (;;) {
    const name = `${prefix}${String(Math.floor(100000000 + Math.random() * 899999999))}`;
    if (!scan.bookmarks.has(name) && !taken.has(name)) {
      taken.add(name);
      return name;
    }
  }
}

// ---- Styles --------------------------------------------------------------------------------------

const style = (id: string, name: string, base: string | null, rest: string) =>
  `<w:style w:type="paragraph" w:styleId="${escAttr(id)}"><w:name w:val="${escAttr(name)}"/>` +
  (base ? `<w:basedOn w:val="${escAttr(base)}"/>` : '') +
  rest +
  `</w:style>`;

/**
 * The id of one of the built-in styles fields use (caption, toc 1 to toc 9, table of figures,
 * TOC Heading), added with Word's own definition when the file has none.
 */
export function ensureFieldStyle(ctx: DocContext, name: string): string {
  const styles = ctx.styles;
  const existing = styles.byName(name);
  if (existing) return existing.id;

  const normal = styles.defaultParagraph;
  const next = normal ? `<w:next w:val="${escAttr(normal)}"/>` : '';
  const toc = /^toc ([1-9])$/.exec(name);

  if (toc) {
    const level = Number(toc[1]);
    const indent = level > 1 ? `<w:ind w:left="${(level - 1) * 220}"/>` : '';
    return styles.addDefinition(`TOC${level}`, (id) =>
      style(id, name, normal, `${next}<w:autoRedefine/><w:uiPriority w:val="39"/><w:unhideWhenUsed/><w:pPr><w:spacing w:after="100"/>${indent}</w:pPr>`),
    );
  }

  if (name === 'caption') {
    return styles.addDefinition('Caption', (id) =>
      style(
        id, name, normal,
        `${next}<w:uiPriority w:val="35"/><w:unhideWhenUsed/><w:qFormat/><w:pPr><w:spacing w:after="200" w:line="240" w:lineRule="auto"/></w:pPr>` +
          '<w:rPr><w:i/><w:iCs/><w:color w:val="44546A" w:themeColor="text2"/><w:sz w:val="18"/><w:szCs w:val="18"/></w:rPr>',
      ),
    );
  }

  if (name === 'table of figures') {
    return styles.addDefinition('TableofFigures', (id) =>
      style(id, name, normal, `${next}<w:uiPriority w:val="99"/><w:unhideWhenUsed/><w:pPr><w:spacing w:after="0"/></w:pPr>`),
    );
  }

  // TOC Heading: a Heading 1 that does not go into the table of contents itself.
  const heading = styles.ensureBuiltin('heading 1');
  return styles.addDefinition('TOCHeading', (id) =>
    style(id, 'TOC Heading', heading, `${next}<w:uiPriority w:val="39"/><w:unhideWhenUsed/><w:qFormat/><w:pPr><w:outlineLvl w:val="9"/></w:pPr>`),
  );
}

/** The width of the text column, in twips: where a TOC's right-aligned page numbers go. */
export function textWidthTwips(ctx: DocContext): number {
  const page = ctx.page;
  return Math.max(1440, Math.round((page.width - page.left - page.right) * 15));
}
