// Making shapes and changing how they look.

import type { Node as PMNode } from 'prosemirror-model';
import { type Command, type EditorState, NodeSelection } from 'prosemirror-state';
import { schema } from '../editor/schema';
import { newSpec, parseShapeSpec, textJson } from './io';
import type { ShapeSpec } from './model';

const N = schema.nodes;

/** The shape that is selected, if one is. */
export function selectedShape(state: EditorState): { node: PMNode; pos: number; spec: ShapeSpec } | null {
  const sel = state.selection;
  if (!(sel instanceof NodeSelection) || sel.node.type !== N.shape) return null;

  const spec = parseShapeSpec(sel.node.attrs.spec);
  return spec ? { node: sel.node, pos: sel.from, spec } : null;
}

/** Puts a new shape (or, with `text`, a text box) at the selection, floating from its paragraph, and selects it. */
export function insertShape(geom: string, text = false): Command {
  return (state, dispatch) => {
    const spec = newSpec(geom, { x: 0, y: 0 }, text);
    const content = spec.text ? textJson(N.doc.create(null, [N.paragraph.create()])) : null;
    const node = N.shape.create({ spec: JSON.stringify(spec), text: content });
    const { $from } = state.selection;
    if (!$from.parent.inlineContent && !(state.selection instanceof NodeSelection)) return false;

    if (dispatch) {
      const tr = state.tr.replaceSelectionWith(node, false);
      const pos = tr.selection.from - node.nodeSize;
      if (tr.doc.nodeAt(pos)?.type === N.shape) tr.setSelection(NodeSelection.create(tr.doc, pos));
      dispatch(tr.scrollIntoView());
    }

    return true;
  };
}

/** Changes the selected shape's spec: its fill, its outline, how text goes round it. */
export function changeShape(change: (spec: ShapeSpec) => ShapeSpec): Command {
  return (state, dispatch) => {
    const found = selectedShape(state);
    if (!found) return false;

    if (dispatch) {
      const spec = change(found.spec);
      const tr = state.tr.setNodeMarkup(found.pos, null, { ...found.node.attrs, spec: JSON.stringify(spec) });
      dispatch(tr.setSelection(NodeSelection.create(tr.doc, found.pos)));
    }

    return true;
  };
}

export const setShapeFill = (color: string | null): Command => changeShape((spec) => ({ ...spec, fill: color }));
export const setShapeLine = (color: string | null): Command => changeShape((spec) => ({ ...spec, line: color }));
