// What a document review finds, in terms of paragraphs and offsets in their text (as text.ts reads
// them), so that the checks are plain functions of strings and can be tested without an editor.

/** A stretch of one paragraph's text, and what it said when the review was made. */
export interface Spot {
  para: number;
  from: number;
  to: number;
  text: string;
}

/** A change to make: the spot's text becomes `insert`. */
export interface TextEdit extends Spot {
  insert: string;
}

export interface Finding {
  kind: 'terms' | 'spelling' | 'abbrev' | 'style' | 'model';
  /** One line for the list. */
  title: string;
  /** Why it is a finding: the "why". */
  detail: string;
  /** Where it is, in reading order; a click goes to the first, and on to the next. */
  spots: Spot[];
  /** What would fix it, if it can be fixed mechanically. */
  fix?: TextEdit[];
  /** Findings that share a group can be fixed together. */
  group?: string;
  /** A style rule's id, so the rule can be switched off from the finding. */
  rule?: string;
}

export interface Word {
  word: string;
  from: number;
  to: number;
}

const WORD = /[\p{L}\p{N}]+(?:[-'’][\p{L}\p{N}]+)*/gu;

/** The words of a text, with hyphenated words and contractions kept whole. */
export function wordsOf(text: string): Word[] {
  return [...text.matchAll(WORD)].map((m) => ({ word: m[0], from: m.index, to: m.index + m[0].length }));
}

/** `to` written with the capitals of `from`: all capitals, a capital first, or none. */
export function matchCase(from: string, to: string): string {
  if (from.length > 1 && from === from.toUpperCase() && from !== from.toLowerCase()) return to.toUpperCase();
  if (from[0] && from[0] === from[0].toUpperCase() && from[0] !== from[0].toLowerCase()) return to.charAt(0).toUpperCase() + to.slice(1);
  return to;
}

/** Applies edits to paragraph texts (for tests, and to know what a fix would give). */
export function applyEdits(paragraphs: string[], edits: TextEdit[]): string[] {
  const out = [...paragraphs];
  const sorted = [...edits].sort((a, b) => b.para - a.para || b.from - a.from);

  for (const e of sorted) out[e.para] = out[e.para].slice(0, e.from) + e.insert + out[e.para].slice(e.to);
  return out;
}
