// Column flow: which column of which page each block of a multi-column section goes in.
//
// Pure arithmetic over measured heights, so it can be tested without a window. The blocks are
// measured at their column's width (src/columns/view.ts); here they are poured into column 1,
// then column 2, and so on, then the next page's column 1, as Word does. A paragraph that does
// not fit at the foot of a column is split between its lines into the next column on the same
// page (not one line alone at either end, if it can be helped). A column break starts the next
// column, a page break the next page. With `balance` (a section that a continuous one follows,
// and anything in the continuous view), the columns on the run's last page are made as even as
// the blocks allow, with the shortest height that still holds them.

export interface FlowBlock {
  /** Its border box's height, and its margins (they collapse between blocks, as on screen). */
  height: number;
  marginTop: number;
  marginBottom: number;
  breakBefore?: 'column' | 'page' | null;
  breakAfter?: 'column' | 'page' | null;
  /** Room its footnotes take at the foot of its page. */
  foot?: number;
  /** Its lines (from its top), for a paragraph that may be split. */
  lines?: readonly { top: number; bottom: number }[];
}

export interface FlowOptions {
  cols: number;
  /** Where the run starts on its first page, from the top of the body. */
  startY: number;
  /** The height of the body on the run's page k (k = 0 is the first). */
  bodyHeight: (k: number) => number;
  /** Footnote room already taken on the first page by what came before. */
  footUsed?: number;
  /** The line over the footnotes, with its room. */
  footSep?: number;
  balance?: boolean;
}

export interface Placement {
  /** Page from the run's first, column, and its top from the top of the body. */
  page: number;
  col: number;
  y: number;
  /** For a paragraph split into the next column: the first line that goes there, and that column's top. */
  split?: { line: number; tailTop: number };
}

export interface FlowPage {
  /** Where the columns start on the page, and where the longest ends. */
  top: number;
  bottom: number;
  /** The footnote room taken by the run's blocks on the page. */
  foot: number;
}

export interface FlowResult {
  placements: Placement[];
  pages: FlowPage[];
}

interface Limits {
  cols: number;
  startY: number;
  limit: (page: number, foot: number) => number;
  /** False while balancing: everything must go on the one page. */
  morePages: boolean;
  /** Whether the first block keeps its space before (it starts the run, not a page). */
  firstMargin: boolean;
}

/** The fewest lines left at the foot of a column, or taken to the next, when a paragraph is split. */
const MIN_LINES = 2;

function pour(blocks: readonly FlowBlock[], o: Limits, footUsed: number): FlowResult & { overflow: boolean } {
  const placements: Placement[] = [];
  const pages: FlowPage[] = [{ top: o.startY, bottom: o.startY, foot: 0 }];
  let page = 0;
  let col = 0;
  let top = o.startY;
  let y = top;
  let empty = true;
  let prevMargin = 0;
  let foot = footUsed;
  let overflow = false;

  const nextPage = () => {
    if (!o.morePages) overflow = true;
    page++;
    col = 0;
    top = 0;
    y = 0;
    empty = true;
    foot = 0;
    pages.push({ top: 0, bottom: 0, foot: 0 });
  };

  const nextColumn = () => {
    if (col + 1 >= o.cols) return nextPage();
    col++;
    y = top;
    empty = true;
  };

  const mark = (bottom: number) => {
    pages[page].bottom = Math.max(pages[page].bottom, bottom);
  };

  blocks.forEach((block, i) => {
    if (block.breakBefore === 'page' && !(empty && col === 0)) nextPage();
    else if (block.breakBefore === 'column' && !empty) nextColumn();

    for (;;) {
      // The very first block keeps its space before; at the top of any other column it goes.
      const gap = empty ? (i === 0 && o.firstMargin ? block.marginTop : 0) : Math.max(prevMargin, block.marginTop);
      const need = block.foot ?? 0;
      const limit = o.limit(page, foot + need);
      const at = y + gap;

      if (at + block.height <= limit + 0.5 || (empty && (col === o.cols - 1 || !block.lines))) {
        // It fits; or it is alone in a column and cannot be split there (a picture, a table): it runs over.
        if (at + block.height > limit + 0.5 && !o.morePages) overflow = true;
        placements.push({ page, col, y: at });
        y = at + block.height;
        foot += need;
        pages[page].foot += need;
        mark(y);
        break;
      }

      const lines = block.lines;

      if (lines && lines.length > 1 && col + 1 < o.cols) {
        // Split it: as many lines as fit stay, the rest start the next column.
        let k = 0;
        while (k < lines.length && at + lines[k].bottom <= limit + 0.5) k++;

        const minHead = lines.length >= 2 * MIN_LINES ? MIN_LINES : 1;
        if (k > lines.length - minHead && lines.length >= 2 * MIN_LINES) k = lines.length - minHead;

        if (k >= minHead || (empty && k >= 1)) {
          placements.push({ page, col, y: at, split: { line: k, tailTop: top } });
          mark(at + lines[k - 1].bottom);
          col++;
          y = top + (block.height - lines[k].top);
          empty = false;
          foot += need;
          pages[page].foot += need;
          mark(y);
          break;
        }
      }

      if (empty) {
        // Alone at the top of the last column and too long for it: it runs over.
        placements.push({ page, col, y: at });
        y = at + block.height;
        mark(y);
        if (!o.morePages) overflow = true;
        break;
      }

      nextColumn();
    }

    empty = false;
    prevMargin = block.marginBottom;

    if (block.breakAfter === 'page') nextPage();
    else if (block.breakAfter === 'column') nextColumn();
  });

  return { placements, pages, overflow };
}

/** Lays a run of blocks out in columns. */
export function flowColumns(blocks: readonly FlowBlock[], options: FlowOptions): FlowResult {
  const sep = options.footSep ?? 0;
  const footUsed = options.footUsed ?? 0;
  const limit = (page: number, foot: number) => options.bodyHeight(page) - (foot > 0 ? foot + sep : 0);
  const cols = Math.max(1, options.cols);
  const full = pour(blocks, { cols, startY: options.startY, limit, morePages: true, firstMargin: true }, footUsed);

  if (!options.balance || cols < 2 || !blocks.length) return full;

  // Balance the last page: the blocks on it, poured again into the shortest columns that hold them.
  const last = full.pages.length - 1;
  const first = full.placements.findIndex((p) => p.page === last);
  if (first < 0 || blocks.slice(first).some((b) => b.breakAfter || (b !== blocks[first] && b.breakBefore))) return full;

  const rest = blocks.slice(first);
  const startY = last === 0 ? options.startY : 0;
  const footBefore = last === 0 ? footUsed : 0;
  const room = full.pages[last].bottom - startY;
  const tryHeight = (h: number) => pour(rest, { cols, startY, limit: (_p, foot) => Math.min(startY + h, limit(last, foot)), morePages: false, firstMargin: last === 0 }, footBefore);

  let lo = Math.max(...rest.map((b) => Math.min(b.height, room) / (b.lines ? Math.max(1, b.lines.length) : 1)));
  let hi = room;
  let best = tryHeight(hi);
  if (best.overflow) return full;

  for (let step = 0; step < 24 && hi - lo > 0.5; step++) {
    const mid = (lo + hi) / 2;
    const attempt = tryHeight(mid);
    if (attempt.overflow) lo = mid;
    else {
      hi = mid;
      best = attempt;
    }
  }

  const placements = [...full.placements.slice(0, first), ...best.placements.map((p) => ({ ...p, page: last }))];
  const pages = [...full.pages.slice(0, last), best.pages[0]];
  return { placements, pages };
}
