// "Review document": checks that look at the whole document at once. Most of them are word lists
// and patterns (src/assist/review); the model is asked only for terms used for the same concept,
// which no list can know. Each finding can be shown in the text, fixed where that is mechanical,
// or ignored; a style rule can be switched off from its finding.

import { TextSelection } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import { abbreviationProblems } from '../assist/review/abbrev';
import { mixedSpelling } from '../assist/review/spelling';
import { activeRules, guessLanguage, styleFindings } from '../assist/review/style';
import { termVariants } from '../assist/review/terms';
import type { Finding } from '../assist/review/types';
import { chunkParagraphs, parseTermPairs, termReviewRequest } from '../assist/summary';
import { allBlocks, pieceOf, type Piece, rangeOf } from '../assist/text';
import type { AssistRequest } from '../desktop';
import { clearReview, markReview, replaceReviewed, reviewSpot } from '../editor/suggest';
import { allRules, manageRules, rulesOff, setRuleOn } from './assist-dialogs';
import { h, store, stored, toast } from './dom';
import { icon } from './icons';

export interface ReviewContext {
  view(): EditorView | null;
  canRun(): boolean;
  ask(request: AssistRequest): Promise<{ text?: string; error?: string }>;
  model(): string;
  /** What the active writing profile says about the work. */
  context(): string;
  /** Runs a job with progress and a Stop button; `work` gets a function that says whether to stop. */
  job(label: string, total: number, work: (step: () => boolean) => Promise<void>): Promise<void>;
  /** Asks the model to rewrite the words around a finding, as suggestions. */
  rewrite(view: EditorView, from: number, to: number, instruction: string): Promise<void>;
  /** Room in characters for one request: small for a local model. */
  room(): number;
}

interface Shown {
  finding: Finding;
  /** Review marks for the spots, and for the fix's edits. */
  spots: number[];
  edits: { id: number; insert: string }[];
  /** Which spot a click goes to next. */
  next: number;
}

const LIVE_KEY = 'text-studio:assist-live';
const MODEL_KEY = 'text-studio:assist-review-model';

const KIND_LABEL: Record<Finding['kind'], string> = {
  terms: 'Terms',
  spelling: 'British/American',
  abbrev: 'Abbreviations',
  style: 'Style',
  model: 'Terms (model)',
};

/** The checks that need no model, on the paragraphs' text. */
export function deterministicReview(paragraphs: string[]): Finding[] {
  const language = guessLanguage(paragraphs.join('\n'));

  return [
    ...termVariants(paragraphs),
    ...mixedSpelling(paragraphs),
    ...abbreviationProblems(paragraphs),
    ...styleFindings(paragraphs, activeRules(allRules(), language, rulesOff())),
  ];
}

export class ReviewSection {
  readonly el: HTMLElement;
  private shown: Shown[] = [];
  private view: EditorView | null = null;
  private live = stored(LIVE_KEY) === '1';
  private useModel = stored(MODEL_KEY) !== '0';
  private liveTimer = 0;
  private lastDoc: unknown = null;

  private readonly head = h('div', { class: 'assist-list-head' });
  private readonly list = h('div', { class: 'assist-list review' });
  readonly button = h('button', { class: 'button primary', onclick: () => void this.run(true) }, 'Review document');

  constructor(private readonly ctx: ReviewContext) {
    const live = h('input', { type: 'checkbox', checked: this.live });
    const model = h('input', { type: 'checkbox', checked: this.useModel });

    live.addEventListener('change', () => {
      this.live = live.checked;
      store(LIVE_KEY, this.live ? '1' : '0');
      if (this.live) void this.run(false);
    });
    model.addEventListener('change', () => {
      this.useModel = model.checked;
      store(MODEL_KEY, this.useModel ? '1' : '0');
    });

    this.el = h(
      'div',
      { class: 'assist-section' },
      h('div', { class: 'menu-label' }, 'Review document'),
      h('div', { class: 'assist-hint' }, 'Terms written in different ways, mixed British and American spelling, abbreviations, and style rules.'),
      h('label', { class: 'assist-check' }, model, h('span', null, 'Also ask the model about terms')),
      h('label', { class: 'assist-check' }, live, h('span', null, 'Check as I type (without the model)')),
      h('div', { class: 'assist-buttons' }, this.button, h('button', { class: 'button', onclick: () => void manageRules(() => this.rerun()) }, 'Style rules…')),
    );
  }

  /** The list of findings, which the panel places under everything else. */
  get listEls(): HTMLElement[] {
    return [this.head, this.list];
  }

  private rerun(): void {
    if (this.shown.length || this.live) void this.run(false);
  }

  /** The document changed or another tab came forward: with live checking on, look again soon. */
  changed(view: EditorView | null): void {
    if (view !== this.view && this.view) {
      this.shown = [];
      this.render();
    }

    if (!this.live || !view || view.state.doc === this.lastDoc) return;

    clearTimeout(this.liveTimer);
    this.liveTimer = window.setTimeout(() => void this.run(false), 1200);
  }

  /** Runs the review. `full` also asks the model, when that is switched on. */
  async run(full: boolean): Promise<void> {
    const view = this.ctx.view();
    if (!view) return;

    const pieces: Piece[] = allBlocks(view.state.doc).map((r) => pieceOf(view.state.doc, r.from, r.to));
    const paragraphs = pieces.map((p) => p.text);
    const findings = deterministicReview(paragraphs);

    this.lastDoc = view.state.doc;

    if (full && this.useModel && this.ctx.canRun()) {
      const parts = chunkParagraphs(paragraphs, this.ctx.room());
      const pairs: ReturnType<typeof parseTermPairs> = [];
      let failure: string | null = null;

      await this.ctx.job('Reviewing part', parts.length, async (step) => {
        for (const part of parts) {
          const answer = await this.ctx.ask(termReviewRequest(this.ctx.model(), part, this.ctx.context()));

          if (answer.error) {
            if (answer.error !== 'stopped') failure = answer.error;
            return;
          }

          for (const pair of parseTermPairs(answer.text ?? '', part)) if (!pairs.some((p) => p.from === pair.from)) pairs.push(pair);
          if (step()) return;
        }
      });

      if (failure) toast(failure, true);
      findings.push(...pairs.map((pair) => termFinding(paragraphs, pair)).filter((f): f is Finding => !!f));
    }

    if (view.isDestroyed) return;
    this.show(view, pieces, findings);

    if (full && findings.length) this.head.scrollIntoView({ block: 'start', behavior: 'smooth' });
    if (full) toast(findings.length ? `${findings.length} ${findings.length === 1 ? 'finding' : 'findings'}. Click one to see it in the text.` : 'The review found nothing to report.');
  }

  private show(view: EditorView, pieces: Piece[], findings: Finding[]): void {
    const toDoc = (s: { para: number; from: number; to: number }) => rangeOf(pieces[s.para], s.from, s.to);
    const ranges = findings.flatMap((f) => [...f.spots.map(toDoc), ...(f.fix ?? []).map(toDoc)]);
    const ids = markReview(view, ranges);
    let at = 0;

    this.view = view;
    this.shown = findings.map((finding) => {
      const spots = finding.spots.map(() => ids[at++]);
      const edits = (finding.fix ?? []).map((e) => ({ id: ids[at++], insert: e.insert }));
      return { finding, spots, edits, next: 0 };
    });
    this.render();
  }

  private remove(item: Shown): void {
    this.shown = this.shown.filter((s) => s !== item);
    this.render();
  }

  private goTo(item: Shown): void {
    const view = this.view;
    if (!view) return;

    for (let tries = 0; tries < item.spots.length; tries++) {
      const spot = reviewSpot(view.state, item.spots[item.next % item.spots.length]);
      item.next++;

      if (spot) {
        view.dispatch(view.state.tr.setSelection(TextSelection.create(view.state.doc, spot.from, spot.to)).scrollIntoView());
        view.focus();
        return;
      }
    }

    toast('That text has changed since the review. Review the document again.');
  }

  private fix(items: Shown[]): void {
    const view = this.view;
    if (!view) return;

    const edits = items.flatMap((i) => i.edits);

    if (!replaceReviewed(view, edits)) {
      toast('That text has changed since the review. Review the document again.', true);
      return;
    }

    this.shown = this.shown.filter((s) => !items.includes(s));
    this.render();
    view.focus();
  }

  private render(): void {
    this.head.replaceChildren();
    this.list.replaceChildren();

    if (!this.shown.length) {
      if (this.view && !this.view.isDestroyed) clearReview(this.view);
      return;
    }

    this.head.append(
      h('span', null, `${this.shown.length} ${this.shown.length === 1 ? 'finding' : 'findings'}`),
      h('span', { class: 'spacer' }),
      h('button', { class: 'button small', onclick: () => ((this.shown = []), this.render()) }, 'Close review'),
    );

    for (const item of this.shown) {
      const { finding } = item;
      const group = finding.group ? this.shown.filter((s) => s.finding.group === finding.group && s.edits.length) : [];
      const view = this.view!;

      this.list.append(
        h(
          'div',
          { class: 'assist-item finding' },
          h(
            'button',
            { class: 'assist-item-text', title: 'Show in the document (again for the next place)', onclick: () => this.goTo(item) },
            h('span', { class: 'finding-kind' }, KIND_LABEL[finding.kind]),
            h('span', { class: 'finding-title' }, finding.spots.length > 1 && finding.kind !== 'abbrev' ? `${finding.title} (${finding.spots.length}×)` : finding.title),
            h('span', { class: 'why' }, finding.detail),
          ),
          h(
            'div',
            { class: 'finding-actions' },
            item.edits.length > 0 && h('button', { class: 'button small', onclick: () => this.fix([item]) }, 'Fix'),
            group.length > 1 && h('button', { class: 'button small', title: 'Fix every finding of this kind', onclick: () => this.fix(group) }, `Fix all ${group.length}`),
            finding.kind === 'style' &&
              h('button', {
                class: 'button small',
                title: 'Ask the model to rewrite the words around it',
                onclick: () => {
                  const spot = reviewSpot(view.state, item.spots[0]);
                  if (spot) void this.ctx.rewrite(view, spot.from, spot.to, `${finding.detail}${finding.title.includes('→') ? ` Instead: ${finding.title.split('→')[1].trim()}.` : ''}`);
                },
              }, 'Rewrite'),
            finding.rule &&
              h('button', {
                class: 'button small',
                title: 'Stop checking for this',
                onclick: () => {
                  setRuleOn(finding.rule!, false);
                  this.shown = this.shown.filter((s) => s.finding.rule !== finding.rule);
                  this.render();
                },
              }, 'Rule off'),
            h('button', { class: 'tool', title: 'Ignore', html: icon('close'), onclick: () => this.remove(item) }),
          ),
        ),
      );
    }
  }
}

/** A term the model found used for another, as a finding at each place it is used. */
function termFinding(paragraphs: string[], pair: { from: string; to: string; why: string }): Finding | null {
  const pattern = new RegExp(`(?<![\\p{L}\\p{N}])${pair.from.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?![\\p{L}\\p{N}])`, 'giu');
  const spots = paragraphs.flatMap((text, para) => [...text.matchAll(pattern)].map((m) => ({ para, from: m.index, to: m.index + m[0].length, text: m[0] })));

  if (!spots.length) return null;

  return {
    kind: 'model',
    title: `${pair.from} → ${pair.to}`,
    detail: pair.why ? `${pair.why}. The text also says “${pair.to}” for this.` : `The text also says “${pair.to}” for this.`,
    spots,
    fix: spots.map((s) => ({ ...s, insert: s.text[0] === s.text[0].toUpperCase() ? pair.to.charAt(0).toUpperCase() + pair.to.slice(1) : pair.to })),
  };
}
