// The style editor's model: what a style looks like, read from styles.xml, and the change to the
// style's XML that a new look asks for.
//
// Only the properties the editor has a control for are touched (font, size, colour, bold, italic,
// underline, spacing, line spacing, first-line and hanging indent, alignment, based-on, next), and
// of those only the ones that were changed. Everything else in the style element stays as it came.
// A property set back to what the style would inherit anyway is taken out of the style rather
// than written twice.

import { PPR_LAST, PPR_ORDER, RPR_LAST, RPR_ORDER, type Theme, fontOf, isOn } from './props';
import type { Styles } from './styles';
import { type XmlEl, child, escAttr, inner, openTag, parseXml, splitElements } from './xml';

export type Align = 'left' | 'center' | 'right' | 'both';
export type LineRule = 'auto' | 'exact' | 'atLeast';
export type Special = 'none' | 'firstLine' | 'hanging';

/** What text in a style looks like. Sizes and spacing in points; `line` is a multiple for 'auto'. */
export interface StyleLook {
  font: string;
  size: number;
  /** 'auto' or six hex digits, as the file has it. */
  color: string;
  bold: boolean;
  italic: boolean;
  underline: boolean;
  before: number;
  after: number;
  lineRule: LineRule;
  line: number;
  special: Special;
  specialBy: number;
  align: Align;
}

export type LookChange = Partial<StyleLook>;

export const RUN_KEYS = ['font', 'size', 'color', 'bold', 'italic', 'underline'] as const;
export const PARA_KEYS = ['before', 'after', 'lineRule', 'line', 'special', 'specialBy', 'align'] as const;

/** Word's own defaults, under everything a file says. */
export const BASE_LOOK: Readonly<StyleLook> = {
  font: 'Times New Roman',
  size: 10,
  color: 'auto',
  bold: false,
  italic: false,
  underline: false,
  before: 0,
  after: 0,
  lineRule: 'auto',
  line: 1,
  special: 'none',
  specialBy: 0,
  align: 'left',
};

const ALIGN: Record<string, Align> = { left: 'left', start: 'left', center: 'center', right: 'right', end: 'right', both: 'both', distribute: 'both' };

const num = (value: string | undefined): number | null => {
  if (value === undefined) return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const round = (n: number) => Math.round(n * 100) / 100;

/** Lays what a `w:pPr` and a `w:rPr` say over `look`. */
export function readInto(look: StyleLook, pPr: XmlEl | null | undefined, rPr: XmlEl | null | undefined, theme: Theme): StyleLook {
  for (const c of rPr?.children ?? []) {
    const a = c.attrs;

    switch (c.name) {
      case 'w:rFonts':
        look.font = fontOf(c, theme) ?? look.font;
        break;
      case 'w:sz': {
        const size = num(a['w:val']);
        if (size !== null) look.size = size / 2;
        break;
      }
      case 'w:color':
        if (a['w:val'] && (a['w:val'] === 'auto' || /^[0-9a-fA-F]{6}$/.test(a['w:val']))) look.color = a['w:val'].toUpperCase().replace('AUTO', 'auto');
        break;
      case 'w:b':
        look.bold = isOn(c);
        break;
      case 'w:i':
        look.italic = isOn(c);
        break;
      case 'w:u':
        look.underline = !!a['w:val'] && a['w:val'] !== 'none';
        break;
    }
  }

  for (const c of pPr?.children ?? []) {
    const a = c.attrs;

    switch (c.name) {
      case 'w:jc':
        look.align = ALIGN[a['w:val'] ?? ''] ?? look.align;
        break;
      case 'w:spacing': {
        const before = num(a['w:before']);
        const after = num(a['w:after']);
        const line = num(a['w:line']);

        if (before !== null) look.before = round(before / 20);
        if (after !== null) look.after = round(after / 20);

        if (line !== null) {
          const rule = a['w:lineRule'];
          look.lineRule = rule === 'exact' ? 'exact' : rule === 'atLeast' ? 'atLeast' : 'auto';
          look.line = look.lineRule === 'auto' ? round(line / 240) : round(line / 20);
        }
        break;
      }
      case 'w:ind': {
        const hanging = num(a['w:hanging']);
        const firstLine = num(a['w:firstLine']);

        if (hanging !== null && hanging > 0) {
          look.special = 'hanging';
          look.specialBy = round(hanging / 20);
        } else if (firstLine !== null) {
          look.special = firstLine > 0 ? 'firstLine' : 'none';
          look.specialBy = firstLine > 0 ? round(firstLine / 20) : 0;
        } else if (hanging !== null) {
          look.special = 'none';
          look.specialBy = 0;
        }
        break;
      }
    }
  }

  return look;
}

/**
 * What a style looks like, everything it is based on included. A character style is laid over
 * the default paragraph style, which is what text in it looks like when nothing else is set.
 * With `id` null: what a paragraph or character style based on nothing would look like.
 */
export function lookOf(styles: Styles, id: string | null, type = 'paragraph'): StyleLook {
  const look = readInto({ ...BASE_LOOK }, styles.docPPr, styles.docRPr, styles.theme);

  if (type === 'character') {
    for (const def of styles.chain(styles.defaultParagraph)) readInto(look, def.pPr, def.rPr, styles.theme);
  }

  for (const def of styles.chain(id)) readInto(look, type === 'character' ? null : def.pPr, def.rPr, styles.theme);

  return look;
}

/** The fields that differ between two looks. Line spacing and the special indent go as pairs. */
export function diffLook(from: StyleLook, to: StyleLook, keys: readonly (keyof StyleLook)[] = [...RUN_KEYS, ...PARA_KEYS]): LookChange {
  const change: Record<string, unknown> = {};

  for (const key of keys) {
    if (from[key] !== to[key]) change[key] = to[key];
  }

  if ('lineRule' in change || 'line' in change) Object.assign(change, { lineRule: to.lineRule, line: to.line });
  if ('special' in change || 'specialBy' in change) Object.assign(change, { special: to.special, specialBy: to.specialBy });

  return change as LookChange;
}

/**
 * Like `orderProps`, but keeps repeated names (a style may hold several `w:tblStylePr`): a stable
 * sort, so children already in order keep their bytes and their order.
 */
function orderPropsSafe(entries: [string, string][], order: readonly string[], last: readonly string[]): string {
  const rank = (name: string) => {
    const tail = last.indexOf(name);
    if (tail >= 0) return order.length + 1 + tail;
    const at = order.indexOf(name);
    return at >= 0 ? at : order.length;
  };

  return entries
    .map((entry, index) => ({ entry, index, rank: rank(entry[0]) }))
    .sort((a, b) => a.rank - b.rank || a.index - b.index)
    .map((item) => item.entry[1])
    .join('');
}

// ---- Writing --------------------------------------------------------------------------------

type Parts = [string, string][];

/** The order the schema wants a style's children in. */
const STYLE_ORDER = [
  'w:name', 'w:aliases', 'w:basedOn', 'w:next', 'w:link', 'w:autoRedefine', 'w:hidden', 'w:uiPriority', 'w:semiHidden',
  'w:unhideWhenUsed', 'w:qFormat', 'w:locked', 'w:personal', 'w:personalCompose', 'w:personalReply', 'w:rsid', 'w:pPr',
  'w:rPr', 'w:tblPr', 'w:trPr', 'w:tcPr', 'w:tblStylePr',
] as const;

const elementXml = (name: string, attrs: [string, string][], body = '') => {
  const a = attrs.map(([key, value]) => ` ${key}="${escAttr(value)}"`).join('');
  return body ? `<${name}${a}>${body}</${name}>` : `<${name}${a}/>`;
};

const find = (parts: Parts, name: string) => parts.find(([n]) => n === name)?.[1] ?? null;

function put(parts: Parts, name: string, xml: string | null): Parts {
  const at = parts.findIndex(([n]) => n === name);
  const kept = parts.filter(([n]) => n !== name);

  if (xml === null) return kept;
  if (at < 0) return [...kept, [name, xml]];

  kept.splice(at, 0, [name, xml]);
  return kept;
}

/** Changes some attributes of an element kept as source; null removes one. Null when none are left. */
function patchAttrs(source: string | null, name: string, changes: Record<string, string | null>): string | null {
  const el = source ? parseXml(source) : null;
  const attrs = new Map(Object.entries(el?.attrs ?? {}));

  for (const [key, value] of Object.entries(changes)) {
    if (value === null) attrs.delete(key);
    else attrs.set(key, value);
  }

  const body = el && el.innerEnd > el.innerStart ? inner(el) : '';
  if (!attrs.size && !body) return null;

  return elementXml(name, [...attrs], body);
}

const toggle = (on: boolean) => (on ? '' : ' w:val="0"');
const twips = (pt: number) => String(Math.round(pt * 20));

function patchRun(parts: Parts, change: LookChange, inherited: StyleLook): Parts {
  const same = <K extends keyof StyleLook>(key: K) => change[key] === inherited[key];

  if (change.font !== undefined) {
    const font = same('font') ? null : change.font;
    const fonts = patchAttrs(find(parts, 'w:rFonts'), 'w:rFonts', { 'w:ascii': font, 'w:hAnsi': font, 'w:asciiTheme': null, 'w:hAnsiTheme': null });
    parts = put(parts, 'w:rFonts', fonts);
  }

  if (change.size !== undefined) {
    const half = String(Math.round(change.size * 2));
    parts = put(parts, 'w:sz', same('size') ? null : `<w:sz w:val="${half}"/>`);
    parts = put(parts, 'w:szCs', same('size') ? null : `<w:szCs w:val="${half}"/>`);
  }

  if (change.color !== undefined) {
    parts = put(parts, 'w:color', same('color') ? null : `<w:color w:val="${escAttr(change.color)}"/>`);
  }

  if (change.bold !== undefined) {
    parts = put(parts, 'w:b', same('bold') ? null : `<w:b${toggle(change.bold)}/>`);
    parts = put(parts, 'w:bCs', same('bold') ? null : `<w:bCs${toggle(change.bold)}/>`);
  }

  if (change.italic !== undefined) {
    parts = put(parts, 'w:i', same('italic') ? null : `<w:i${toggle(change.italic)}/>`);
    parts = put(parts, 'w:iCs', same('italic') ? null : `<w:iCs${toggle(change.italic)}/>`);
  }

  if (change.underline !== undefined) {
    parts = put(parts, 'w:u', same('underline') ? null : `<w:u w:val="${change.underline ? 'single' : 'none'}"/>`);
  }

  return parts;
}

function patchPara(parts: Parts, change: LookChange, inherited: StyleLook): Parts {
  const spacing: Record<string, string | null> = {};

  if (change.before !== undefined) {
    const own = change.before === inherited.before ? null : twips(change.before);
    Object.assign(spacing, { 'w:before': own, 'w:beforeLines': null, 'w:beforeAutospacing': null });
  }

  if (change.after !== undefined) {
    const own = change.after === inherited.after ? null : twips(change.after);
    Object.assign(spacing, { 'w:after': own, 'w:afterLines': null, 'w:afterAutospacing': null });
  }

  if (change.lineRule !== undefined && change.line !== undefined) {
    const same = change.lineRule === inherited.lineRule && change.line === inherited.line;
    const line = change.lineRule === 'auto' ? String(Math.round(change.line * 240)) : twips(change.line);
    Object.assign(spacing, { 'w:line': same ? null : line, 'w:lineRule': same ? null : change.lineRule });
  }

  if (Object.keys(spacing).length) parts = put(parts, 'w:spacing', patchAttrs(find(parts, 'w:spacing'), 'w:spacing', spacing));

  if (change.special !== undefined && change.specialBy !== undefined) {
    const same = change.special === inherited.special && (change.special === 'none' || change.specialBy === inherited.specialBy);
    const ind: Record<string, string | null> = { 'w:firstLine': null, 'w:hanging': null, 'w:firstLineChars': null, 'w:hangingChars': null };

    if (!same) {
      if (change.special === 'hanging') ind['w:hanging'] = twips(change.specialBy);
      else ind['w:firstLine'] = change.special === 'firstLine' ? twips(change.specialBy) : '0';
    }

    parts = put(parts, 'w:ind', patchAttrs(find(parts, 'w:ind'), 'w:ind', ind));
  }

  if (change.align !== undefined) {
    parts = put(parts, 'w:jc', change.align === inherited.align ? null : `<w:jc w:val="${change.align}"/>`);
  }

  return parts;
}

/** A properties element (`w:pPr`, `w:rPr`) with some of its children changed. Null when it is left empty. */
function patchProps(source: string | null, name: string, patch: (parts: Parts) => Parts, order: readonly string[], last: readonly string[]): string | null {
  const el = source ? parseXml(source) : null;
  const before = el ? splitElements(inner(el)) : [];
  const after = patch(before);

  if (after.length === before.length && after.every((part, i) => part[1] === before[i][1])) return source;
  if (!after.length) return null;

  const open = el ? openTag(el).replace(/\s*\/>$/, '>') : `<${name}>`;
  return `${open}${orderPropsSafe(after, order, last)}</${name}>`;
}

export interface StyleChange {
  look?: LookChange;
  /** A style id, or null for none; left out, unchanged. */
  basedOn?: string | null;
  next?: string | null;
  name?: string;
}

/**
 * The style's XML with `change` made to it. `inherited` is what the style would look like with
 * nothing of its own: a property set to that is taken out of the style instead.
 */
export function restyle(xml: string, change: StyleChange, inherited: StyleLook, theme?: Theme): string {
  void theme;
  const el = parseXml(xml);
  const selfClosing = el.innerStart === el.end;
  const open = selfClosing ? openTag(el).replace(/\s*\/>$/, '>') : openTag(el);
  const isCharacter = el.attrs['w:type'] === 'character';
  let parts: Parts = selfClosing ? [] : splitElements(inner(el));

  if (change.name !== undefined) parts = put(parts, 'w:name', `<w:name w:val="${escAttr(change.name)}"/>`);
  if (change.basedOn !== undefined) parts = put(parts, 'w:basedOn', change.basedOn ? `<w:basedOn w:val="${escAttr(change.basedOn)}"/>` : null);
  if (change.next !== undefined) parts = put(parts, 'w:next', change.next ? `<w:next w:val="${escAttr(change.next)}"/>` : null);

  const look = change.look ?? {};

  if (!isCharacter && PARA_KEYS.some((key) => look[key] !== undefined)) {
    parts = put(parts, 'w:pPr', patchProps(find(parts, 'w:pPr'), 'w:pPr', (p) => patchPara(p, look, inherited), PPR_ORDER, PPR_LAST));
  }

  if (RUN_KEYS.some((key) => look[key] !== undefined)) {
    parts = put(parts, 'w:rPr', patchProps(find(parts, 'w:rPr'), 'w:rPr', (p) => patchRun(p, look, inherited), RPR_ORDER, RPR_LAST));
  }

  return `${open}${orderPropsSafe(parts, STYLE_ORDER, [])}</w:style>`;
}

/** A new, empty style's XML, for `restyle` to give its look. */
export function newStyleXml(id: string, name: string, type: 'paragraph' | 'character', basedOn: string | null, next: string | null): string {
  const based = basedOn ? `<w:basedOn w:val="${escAttr(basedOn)}"/>` : '';
  const follow = type === 'paragraph' && next ? `<w:next w:val="${escAttr(next)}"/>` : '';

  return `<w:style w:type="${type}" w:customStyle="1" w:styleId="${escAttr(id)}"><w:name w:val="${escAttr(name)}"/>${based}${follow}<w:qFormat/></w:style>`;
}

/** A style's XML from its id, as the editor currently has it. */
export function styleXml(styles: Styles, id: string): string | null {
  return styles.byId.get(id)?.xml ?? null;
}

/** The `w:rPr` child the inherited look is read from, for a test or two. */
export const rPrOf = (xml: string): XmlEl | null => child(parseXml(xml), 'w:rPr');
