// The Columns button's menu: One, Two, Three, Left, Right, and Custom columns.

import type { Command } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { closePopover, h, popover } from '../ui/dom';
import { formDialog } from '../ui/references';
import { setColumns } from './commands';
import { type Cols, presetCols, sectionAt } from './model';
import { sectionRangesIn } from './view';

export interface ColumnsHost {
  tab(): { ctx: DocContext; view: EditorView } | null;
  run(command: Command): void;
  focus(): void;
}

const bodyTwips = (ctx: DocContext) => Math.round((ctx.page.width - ctx.page.left - ctx.page.right) * 15);

export function columnsMenu(anchor: HTMLElement, host: ColumnsHost): void {
  const tab = host.tab();
  if (!tab) return;

  const ranges = sectionRangesIn(tab.view.state);
  const current = ranges.length ? sectionAt(ranges, tab.view.state.selection.from).cols : null;
  const apply = (cols: Cols) => host.run(setColumns(tab.ctx, cols));
  const item = (label: string, action: () => void) =>
    h('button', { class: 'menu-item', onclick: () => (closePopover(), action()) }, label);
  const preset = (label: string, which: Parameters<typeof presetCols>[0]) =>
    item(label, () => apply(presetCols(which, bodyTwips(tab.ctx), current?.sep ?? false, current?.space ?? 720)));

  popover(
    anchor,
    h(
      'div',
      null,
      preset('One', 'one'),
      preset('Two', 'two'),
      preset('Three', 'three'),
      preset('Left', 'left'),
      preset('Right', 'right'),
      h('div', { class: 'menu-sep' }),
      item('Custom columns…', () => void customColumns(host, current)),
    ),
  );
}

async function customColumns(host: ColumnsHost, current: Cols | null): Promise<void> {
  const tab = host.tab();
  if (!tab) return;

  const count = h('input', { type: 'number', min: '1', max: '12', value: String(current?.count ?? 2) }) as HTMLInputElement;
  // Spacing in centimetres, as Word shows it: 567 twips to the centimetre.
  const space = h('input', { type: 'number', min: '0', max: '10', step: '0.05', value: ((current?.space ?? 720) / 567).toFixed(2) }) as HTMLInputElement;
  const sep = h('input', { type: 'checkbox' }) as HTMLInputElement;
  sep.checked = current?.sep ?? false;

  const body = h(
    'div',
    { class: 'columns-form' },
    h('label', null, 'Number of columns ', count),
    h('label', null, 'Spacing (cm) ', space),
    h('label', null, sep, ' Line between'),
  );

  if (!(await formDialog('Columns', body, 'Apply'))) return host.focus();

  const n = Math.max(1, Math.min(12, Math.round(Number(count.value)) || 1));
  const twips = Math.max(0, Math.round((Number(space.value) || 0) * 567));
  const cols: Cols = n === 1 ? presetCols('one', bodyTwips(tab.ctx), false, twips) : { count: n, space: twips, equal: true, widths: [], sep: sep.checked };

  host.run(setColumns(tab.ctx, cols));
}
