// Printing, and PDF: the document as sheets of paper.
//
// The sheets are made from the document as laid out in Pages view, so they break exactly where
// the screen shows. Page k of that layout is the stretch of the one flow from k × (page height +
// gap) down by a page's height; each sheet is a box of the page's size that shows just that
// stretch: a copy of the blocks that reach into it, set at the height they have on screen, with
// the page's header and footer. The sheets are white paper with the file's own colours whatever
// the theme, and without gaps, shadows or anything of the window: page.css shows them, and only
// them, in print.

import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { PAGE_GAP, type Paginator } from './pages';

/** A document on screen, as app.ts has it. */
export interface Printable {
  view: EditorView;
  ctx: DocContext;
  page: HTMLElement;
  pages: Paginator;
}

export interface PaperSize {
  /** In CSS pixels, at 96 to the inch. */
  width: number;
  height: number;
}

/**
 * Puts the document's sheets into the window, for printing; returns the paper size, and a
 * function that takes the sheets away again. Pages view is switched on while they are made.
 */
export function prepareSheets(doc: Printable): { size: PaperSize; done: () => void } {
  const { view, ctx, pages } = doc;
  const wasOn = pages.isEnabled;

  pages.furniture.finish();
  if (wasOn) pages.run();
  else pages.setEnabled(true);

  const page = ctx.page;
  const pitch = page.height + PAGE_GAP;
  const zoom = parseFloat(getComputedStyle(doc.page).zoom) || 1;
  const origin = view.dom.getBoundingClientRect();
  const count = Math.max(1, pages.furniture.pageInfo.length);

  // Every block of the flow, where it stands without the zoom.
  const blocks = [...view.dom.children]
    .filter((el): el is HTMLElement => el instanceof HTMLElement && el.getClientRects().length > 0)
    .map((el) => {
      const rect = el.getBoundingClientRect();
      return { el, top: (rect.top - origin.top) / zoom, bottom: (rect.bottom - origin.top) / zoom };
    });

  const root = document.createElement('div');
  root.className = 'print-root';

  for (let k = 0; k < count; k++) {
    // The sheet's top edge, in the flow's own measure: the flow starts below the top margin.
    const top = k * pitch - page.top;
    const bottom = top + page.height;
    const sheet = document.createElement('div');

    sheet.className = `page ${ctx.key} print-sheet`;
    sheet.dataset.mode = 'light';
    sheet.style.width = `${page.width}px`;
    sheet.style.height = `${page.height}px`;

    const first = blocks.findIndex((b) => b.bottom > top || (b.top >= top && b.top < bottom));

    if (first >= 0 && blocks[first].top < bottom) {
      const flow = view.dom.cloneNode(false) as HTMLElement;

      flow.removeAttribute('contenteditable');
      flow.removeAttribute('style');
      flow.classList.add('print-flow');
      flow.style.left = `${page.left}px`;
      flow.style.width = `${page.width - page.left - page.right}px`;
      flow.style.top = `${blocks[first].top - top}px`;

      // Footnote marks count with a CSS counter; it carries on from the blocks left out.
      let footnotes = 0;
      let endnotes = 0;

      for (const b of blocks.slice(0, first)) {
        footnotes += b.el.querySelectorAll('.opaque-footnote').length;
        endnotes += b.el.querySelectorAll('.opaque-endnote').length;
      }

      flow.style.counterReset = `footnote ${footnotes} endnote ${endnotes}`;

      const origin = blocks[first].top;
      let inFlow = false;

      for (let i = first; i < blocks.length && blocks[i].top < bottom; i++) {
        const b = blocks[i];
        const copy = b.el.cloneNode(true) as HTMLElement;

        if (b.el.classList.contains('col-block')) {
          // A block of a multi-column section (src/columns/view.ts) is placed in the editor's pixels.
          copy.style.top = `${b.top - origin}px`;
        } else if (b.el.classList.contains('col-spacer')) {
          // The room under a multi-column section: only its part on this sheet, with the lines between the columns.
          const from = Math.max(b.top, top);
          copy.style.height = `${Math.max(0, b.bottom - from)}px`;
          copy.style.marginTop = inFlow ? '0' : `${from - origin}px`;
          copy.querySelectorAll<HTMLElement>('.col-rule').forEach((rule) => (rule.style.top = `${parseFloat(rule.style.top) - origin}px`));
          inFlow = true;
        } else {
          if (!inFlow) copy.style.marginTop = `${b.top - origin}px`;
          inFlow = true;
        }

        flow.append(copy);
      }

      flow.querySelectorAll('[contenteditable]').forEach((el) => el.removeAttribute('contenteditable'));
      sheet.append(flow);
    }

    sheet.append(...pages.furniture.sheetBoxes(k, 0));
    root.append(sheet);
  }

  const paper = document.createElement('style');
  paper.textContent = `@page { size: ${page.width}px ${page.height}px; margin: 0; }`;

  document.head.append(paper);
  document.body.append(root);

  return {
    size: { width: page.width, height: page.height },
    done: () => {
      root.remove();
      paper.remove();
      if (!wasOn) pages.setEnabled(false);
    },
  };
}
