// A shape's outline as SVG: preset geometries, freeforms, dashes and arrowheads.
//
// Presets follow DrawingML's presetShapeDefinitions closely enough to look right; each takes its
// adjust values (`adj`, `adj1`...) in the same units Word writes them, 100000 to the whole. A preset
// this does not know is drawn as a rectangle. Colours go out in `--c`, as text's do, so that
// page.css can map them on a dark page (src/styles/shapes.css).

import type { CustomPath, ShapeSpec } from './model';

export interface Outline {
  d: string;
  /** False for an open path that is only stroked: a line, an arc. */
  filled: boolean;
}

/** The presets offered for drawing, in the order the gallery shows them. */
export const GALLERY: readonly { geom: string; label: string }[] = [
  { geom: 'rect', label: 'Rectangle' },
  { geom: 'roundRect', label: 'Rounded rectangle' },
  { geom: 'ellipse', label: 'Oval' },
  { geom: 'triangle', label: 'Triangle' },
  { geom: 'rightArrow', label: 'Right arrow' },
  { geom: 'leftArrow', label: 'Left arrow' },
  { geom: 'upArrow', label: 'Up arrow' },
  { geom: 'downArrow', label: 'Down arrow' },
  { geom: 'star5', label: 'Star' },
  { geom: 'wedgeRectCallout', label: 'Callout' },
  { geom: 'line', label: 'Line' },
  { geom: 'straightConnector1', label: 'Arrow line' },
];

const DEFAULTS: Record<string, Record<string, number>> = {
  roundRect: { adj: 16667 },
  triangle: { adj: 50000 },
  parallelogram: { adj: 25000 },
  trapezoid: { adj: 25000 },
  hexagon: { adj: 25000 },
  octagon: { adj: 29289 },
  rightArrow: { adj1: 50000, adj2: 50000 },
  leftArrow: { adj1: 50000, adj2: 50000 },
  upArrow: { adj1: 50000, adj2: 50000 },
  downArrow: { adj1: 50000, adj2: 50000 },
  leftRightArrow: { adj1: 50000, adj2: 50000 },
  upDownArrow: { adj1: 50000, adj2: 50000 },
  star4: { adj: 12500 },
  star5: { adj: 19098 },
  star6: { adj: 28868 },
  wedgeRectCallout: { adj1: -20833, adj2: 62500 },
  wedgeRoundRectCallout: { adj1: -20833, adj2: 62500, adj3: 16667 },
  wedgeEllipseCallout: { adj1: -20833, adj2: 62500 },
  plus: { adj: 25000 },
};

/** Lines and connectors: drawn open, with arrowheads, never filled. */
export const LINE_LIKE = new Set(['line', 'straightConnector1', 'bentConnector2', 'bentConnector3', 'curvedConnector3']);

const r2 = (n: number) => Math.round(n * 100) / 100;
const poly = (pts: [number, number][]) => `M${pts.map(([x, y]) => `${r2(x)} ${r2(y)}`).join('L')}Z`;

function roundRectPath(w: number, h: number, r: number): string {
  r = Math.max(0, Math.min(r, w / 2, h / 2));
  if (r === 0) return poly([[0, 0], [w, 0], [w, h], [0, h]]);

  return (
    `M${r2(r)} 0L${r2(w - r)} 0A${r2(r)} ${r2(r)} 0 0 1 ${r2(w)} ${r2(r)}L${r2(w)} ${r2(h - r)}` +
    `A${r2(r)} ${r2(r)} 0 0 1 ${r2(w - r)} ${r2(h)}L${r2(r)} ${r2(h)}A${r2(r)} ${r2(r)} 0 0 1 0 ${r2(h - r)}` +
    `L0 ${r2(r)}A${r2(r)} ${r2(r)} 0 0 1 ${r2(r)} 0Z`
  );
}

function ellipsePath(w: number, h: number): string {
  const rx = r2(w / 2);
  const ry = r2(h / 2);
  return `M0 ${ry}A${rx} ${ry} 0 1 1 ${r2(w)} ${ry}A${rx} ${ry} 0 1 1 0 ${ry}Z`;
}

/** A star of `n` points with its inner radius `inner` of the outer, filling the box. */
function starPath(n: number, inner: number, w: number, h: number): string {
  const pts: [number, number][] = [];

  for (let i = 0; i < n * 2; i++) {
    const a = -Math.PI / 2 + (i * Math.PI) / n;
    const r = i % 2 ? inner : 1;
    pts.push([Math.cos(a) * r, Math.sin(a) * r]);
  }

  const xs = pts.map((p) => p[0]);
  const ys = pts.map((p) => p[1]);
  const [x0, x1, y0, y1] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];

  return poly(pts.map(([x, y]) => [((x - x0) / (x1 - x0)) * w, ((y - y0) / (y1 - y0)) * h]));
}

/** A right-pointing block arrow in a box `len` long and `thick` across, before it is turned. */
function arrowPoints(len: number, thick: number, adj1: number, adj2: number, ss: number): [number, number][] {
  const shaft = (thick * Math.max(0, Math.min(100000, adj1))) / 100000;
  const head = Math.min(len, (ss * Math.max(0, adj2)) / 100000);
  const y1 = (thick - shaft) / 2;
  const y2 = y1 + shaft;
  const x1 = len - head;

  return [[0, y1], [x1, y1], [x1, 0], [len, thick / 2], [x1, thick], [x1, y2], [0, y2]];
}

/** A rectangle or rounded rectangle with a wedge out to the point the adjust values give. */
function calloutPath(w: number, h: number, adj1: number, adj2: number, radius: number): string {
  const tx = w / 2 + (w * adj1) / 100000;
  const ty = h / 2 + (h * adj2) / 100000;
  const inside = tx >= 0 && tx <= w && ty >= 0 && ty <= h;
  const box = roundRectPath(w, h, radius);
  if (inside) return box;

  // The wedge leaves the side the point is furthest beyond, from a base a sixth of that side wide.
  const dx = (tx - w / 2) / w;
  const dy = (ty - h / 2) / h;
  let wedge: [number, number][];

  if (Math.abs(dy) >= Math.abs(dx)) {
    const y = dy > 0 ? h : 0;
    const x = dx < 0 ? w * (3 / 12) : w * (7 / 12);
    wedge = [[x, y], [tx, ty], [x + w / 6, y]];
  } else {
    const x = dx > 0 ? w : 0;
    const y = dy < 0 ? h * (3 / 12) : h * (7 / 12);
    wedge = [[x, y], [tx, ty], [x, y + h / 6]];
  }

  // Drawn as a second filled polygon over the box, with the box's edge under the wedge's base hidden
  // by the fill: close enough to Word's single outline at the line widths shapes use.
  return `${box}${poly(wedge)}`;
}

function ellipseCalloutPath(w: number, h: number, adj1: number, adj2: number): string {
  const rx = w / 2;
  const ry = h / 2;
  const tx = rx + (w * adj1) / 100000;
  const ty = ry + (h * adj2) / 100000;
  const angle = Math.atan2((ty - ry) / ry, (tx - rx) / rx);
  const at = (a: number): [number, number] => [rx + rx * Math.cos(a), ry + ry * Math.sin(a)];
  const [ax, ay] = at(angle - 0.2);
  const [bx, by] = at(angle + 0.2);

  return `M${r2(bx)} ${r2(by)}A${r2(rx)} ${r2(ry)} 0 1 1 ${r2(ax)} ${r2(ay)}L${r2(tx)} ${r2(ty)}Z`;
}

/** The outline of a preset at a size, with its adjust values. Unknown presets are rectangles. */
export function presetOutline(geom: string, w: number, h: number, adjust: Record<string, number> = {}): Outline[] {
  const adj = { ...DEFAULTS[geom], ...adjust };
  const ss = Math.min(w, h);
  const rect = poly([[0, 0], [w, 0], [w, h], [0, h]]);
  const one = (d: string, filled = true): Outline[] => [{ d, filled }];

  switch (geom) {
    case 'rect':
    case 'flowChartProcess':
    case 'textBox':
      return one(rect);
    case 'roundRect':
    case 'flowChartAlternateProcess':
      return one(roundRectPath(w, h, (ss * (adj.adj ?? 16667)) / 100000));
    case 'flowChartTerminator':
      return one(roundRectPath(w, h, ss / 2));
    case 'ellipse':
    case 'flowChartConnector':
      return one(ellipsePath(w, h));
    case 'triangle':
    case 'flowChartExtract':
      return one(poly([[(w * (adj.adj ?? 50000)) / 100000, 0], [w, h], [0, h]]));
    case 'rtTriangle':
      return one(poly([[0, 0], [w, h], [0, h]]));
    case 'diamond':
    case 'flowChartDecision':
      return one(poly([[w / 2, 0], [w, h / 2], [w / 2, h], [0, h / 2]]));
    case 'parallelogram': {
      const x = (ss * adj.adj) / 100000;
      return one(poly([[x, 0], [w, 0], [w - x, h], [0, h]]));
    }
    case 'trapezoid': {
      const x = (ss * adj.adj) / 100000;
      return one(poly([[x, 0], [w - x, 0], [w, h], [0, h]]));
    }
    case 'hexagon': {
      const x = (ss * adj.adj) / 100000;
      return one(poly([[x, 0], [w - x, 0], [w, h / 2], [w - x, h], [x, h], [0, h / 2]]));
    }
    case 'octagon': {
      const x = (ss * adj.adj) / 100000;
      return one(poly([[x, 0], [w - x, 0], [w, x], [w, h - x], [w - x, h], [x, h], [0, h - x], [0, x]]));
    }
    case 'pentagon':
      return one(poly([[w / 2, 0], [w, h * 0.38], [w * 0.81, h], [w * 0.19, h], [0, h * 0.38]]));
    case 'plus': {
      const x = (ss * adj.adj) / 100000;
      return one(poly([[x, 0], [w - x, 0], [w - x, x], [w, x], [w, h - x], [w - x, h - x], [w - x, h], [x, h], [x, h - x], [0, h - x], [0, x], [x, x]]));
    }
    case 'rightArrow':
      return one(poly(arrowPoints(w, h, adj.adj1, adj.adj2, ss)));
    case 'leftArrow':
      return one(poly(arrowPoints(w, h, adj.adj1, adj.adj2, ss).map(([x, y]) => [w - x, y])));
    case 'downArrow':
      return one(poly(arrowPoints(h, w, adj.adj1, adj.adj2, ss).map(([x, y]) => [y, x])));
    case 'upArrow':
      return one(poly(arrowPoints(h, w, adj.adj1, adj.adj2, ss).map(([x, y]) => [y, h - x])));
    case 'leftRightArrow': {
      const shaft = (h * adj.adj1) / 100000;
      const head = Math.min(w / 2, (ss * adj.adj2) / 100000);
      const y1 = (h - shaft) / 2;
      return one(poly([[0, h / 2], [head, 0], [head, y1], [w - head, y1], [w - head, 0], [w, h / 2], [w - head, h], [w - head, y1 + shaft], [head, y1 + shaft], [head, h]]));
    }
    case 'upDownArrow': {
      const shaft = (w * adj.adj1) / 100000;
      const head = Math.min(h / 2, (ss * adj.adj2) / 100000);
      const x1 = (w - shaft) / 2;
      return one(poly([[w / 2, 0], [w, head], [x1 + shaft, head], [x1 + shaft, h - head], [w, h - head], [w / 2, h], [0, h - head], [x1, h - head], [x1, head], [0, head]]));
    }
    case 'star4':
      return one(starPath(4, (adj.adj / 50000) || 0.25, w, h));
    case 'star5':
      return one(starPath(5, (adj.adj / 50000) || 0.382, w, h));
    case 'star6':
      return one(starPath(6, (adj.adj / 50000) || 0.577, w, h));
    case 'wedgeRectCallout':
      return one(calloutPath(w, h, adj.adj1, adj.adj2, 0));
    case 'wedgeRoundRectCallout':
      return one(calloutPath(w, h, adj.adj1, adj.adj2, (ss * (adj.adj3 ?? 16667)) / 100000));
    case 'wedgeEllipseCallout':
      return one(ellipseCalloutPath(w, h, adj.adj1, adj.adj2));
    case 'line':
    case 'straightConnector1':
      return one(`M0 0L${r2(w)} ${r2(h)}`, false);
    case 'bentConnector2':
      return one(`M0 0L${r2(w)} 0L${r2(w)} ${r2(h)}`, false);
    case 'bentConnector3': {
      const x = (w * (adjust.adj1 ?? 50000)) / 100000;
      return one(`M0 0L${r2(x)} 0L${r2(x)} ${r2(h)}L${r2(w)} ${r2(h)}`, false);
    }
    case 'curvedConnector3':
      return one(`M0 0C${r2(w / 2)} 0 ${r2(w / 2)} ${r2(h)} ${r2(w)} ${r2(h)}`, false);
    default:
      return one(rect);
  }
}

/** A freeform's paths scaled to the shape's box. */
export function customOutline(paths: CustomPath[], w: number, h: number): Outline[] {
  return paths.map((p) => {
    const kx = w / p.w;
    const ky = h / p.h;
    let i = 0;
    // Coordinates alternate x, y throughout: every command here takes whole points.
    const d = p.d.replace(/-?[\d.]+/g, (n) => String(r2(Number(n) * (i++ % 2 ? ky : kx))));
    return { d, filled: p.filled };
  });
}

const DASHES: Record<string, number[]> = {
  dash: [4, 3], sysDash: [3, 1], dot: [1, 3], sysDot: [1, 1], dashDot: [4, 3, 1, 3], lgDash: [8, 3],
  lgDashDot: [8, 3, 1, 3], lgDashDotDot: [8, 3, 1, 3, 1, 3], sysDashDot: [3, 1, 1, 1], sysDashDotDot: [3, 1, 1, 1, 1, 1],
  // VML's names.
  shortdash: [3, 1], shortdot: [1, 1], longdash: [8, 3], dashdot: [4, 3, 1, 3], longdashdot: [8, 3, 1, 3], shortdashdot: [3, 1, 1, 1],
};

/** An SVG stroke-dasharray for a line style at a width, or '' for a solid line. */
export function dashArray(dash: string, lw: number): string {
  const pattern = DASHES[dash];
  return pattern ? pattern.map((n) => r2(n * Math.max(1, lw))).join(' ') : '';
}

/** An arrowhead at the end of a line from (fx, fy) to (x, y). */
export function arrowHead(kind: string, fx: number, fy: number, x: number, y: number, lw: number): string {
  if (!kind || kind === 'none') return '';

  const size = Math.max(6, lw * 3);
  const a = Math.atan2(y - fy, x - fx);
  const at = (back: number, side: number): string =>
    `${r2(x - Math.cos(a) * back - Math.sin(a) * side)} ${r2(y - Math.sin(a) * back + Math.cos(a) * side)}`;

  switch (kind) {
    case 'oval':
      return `M${r2(x - size / 3)} ${r2(y)}A${r2(size / 3)} ${r2(size / 3)} 0 1 1 ${r2(x + size / 3)} ${r2(y)}A${r2(size / 3)} ${r2(size / 3)} 0 1 1 ${r2(x - size / 3)} ${r2(y)}Z`;
    case 'diamond':
      return `M${at(0, 0)}L${at(size / 2, size / 3)}L${at(size, 0)}L${at(size / 2, -size / 3)}Z`;
    case 'stealth':
      return `M${at(0, 0)}L${at(size, size / 2.5)}L${at(size * 0.7, 0)}L${at(size, -size / 2.5)}Z`;
    default:
      return `M${at(0, 0)}L${at(size, size / 2.5)}L${at(size, -size / 2.5)}Z`;
  }
}

const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');

/** The paths of one shape (or a group's member) in its own box, without the `<svg>` around it. */
export function shapeMarks(spec: ShapeSpec): string {
  const { w, h } = spec;
  const lineLike = LINE_LIKE.has(spec.geom);
  const outlines = spec.geom === 'custom' && spec.paths?.length ? customOutline(spec.paths, w, h) : presetOutline(spec.geom, w, h, spec.adj);
  const fill = !lineLike && spec.fill ? spec.fill : null;
  const line = spec.line;
  const lw = Math.max(0.5, spec.lw);
  const dash = line ? dashArray(spec.dash, lw) : '';
  let out = '';

  for (const o of outlines) {
    const f = fill && o.filled ? `class="shp-f${line ? ' shp-s' : ''}" style="--c:${fill};${line ? `--l:${line};` : ''}" fill="${fill}"` : `class="${line ? 'shp-s' : ''}" style="${line ? `--l:${line};` : ''}" fill="none"`;
    const s = line ? ` stroke="${line}" stroke-width="${r2(lw)}"${dash ? ` stroke-dasharray="${dash}"` : ''} stroke-linejoin="round"` : '';
    out += `<path d="${esc(o.d)}" ${f}${s}/>`;
  }

  if (lineLike && line) {
    const heads = arrowHead(spec.head, w, h, 0, 0, lw) + arrowHead(spec.tail, 0, 0, w, h, lw);
    if (heads) out += `<path d="${heads}" class="shp-f" style="--c:${line}" fill="${line}"/>`;
  }

  return out;
}

/** A shape (or a group of them) drawn as an `<svg>` the size of its box, flipped as it says. */
export function shapeSvg(spec: ShapeSpec): string {
  const { w, h } = spec;
  const flip = spec.flipH || spec.flipV ? ` transform="translate(${spec.flipH ? r2(w) : 0} ${spec.flipV ? r2(h) : 0}) scale(${spec.flipH ? -1 : 1} ${spec.flipV ? -1 : 1})"` : '';
  let body = '';

  if (spec.geom === 'group') {
    for (const part of spec.parts ?? []) {
      const turn = part.rot ? ` rotate(${r2(part.rot)} ${r2(part.w / 2)} ${r2(part.h / 2)})` : '';
      const pflip = part.flipH || part.flipV ? ` translate(${part.flipH ? r2(part.w) : 0} ${part.flipV ? r2(part.h) : 0}) scale(${part.flipH ? -1 : 1} ${part.flipV ? -1 : 1})` : '';
      body += `<g transform="translate(${r2(part.x)} ${r2(part.y)})${turn}${pflip}">${shapeMarks(part)}</g>`;
    }
  } else {
    body = shapeMarks(spec);
  }

  return `<svg class="shape-svg" xmlns="http://www.w3.org/2000/svg" width="${r2(w)}" height="${r2(h)}" viewBox="0 0 ${r2(w)} ${r2(h)}" overflow="visible"><g${flip}>${body}</g></svg>`;
}
