// Reading OMML, Word's equation markup: the pieces both converters (mathml.ts, linear.ts) need.
//
// An equation is `m:oMath`, or `m:oMathPara` holding one or more of them for an equation on a
// line of its own. Inside, every structure has the same shape: an optional `…Pr` element with its
// properties, then named arguments (`m:e`, `m:num`, `m:sub`, ...), each a row of runs and
// structures again.

import { type XmlEl, child, parseXml, val } from '../docx/xml';
import { INTEGRALS } from './symbols';

export const M_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/math';

/** Elements inside an equation that have nothing to show: bookmarks, proofing marks, comment ranges. */
const SILENT = /^(w:bookmark|w:proofErr|w:comment|w:perm|w:moveFromRange|w:moveToRange|w:customXmlInsRange|w:customXmlDelRange|m:ctrlPr$|m:argPr$|w:lastRenderedPageBreak)/;

/** Wrappers whose content is part of the equation: tracked changes, content controls and the like. */
const TRANSPARENT = new Set(['w:ins', 'w:del', 'w:moveTo', 'w:moveFrom', 'w:sdt', 'w:sdtContent', 'w:customXml', 'w:smartTag', 'w:hyperlink']);

export const isSilent = (el: XmlEl): boolean => SILENT.test(el.name) || (el.name.endsWith('Pr') && el.name !== 'm:oMathPara');

/** The elements that make up a row, with wrappers opened and silent ones left out. */
export function rowItems(el: XmlEl | null | undefined, out: XmlEl[] = []): XmlEl[] {
  if (!el) return out;

  for (const c of el.children) {
    if (isSilent(c)) continue;
    if (TRANSPARENT.has(c.name)) rowItems(c, out);
    else out.push(c);
  }

  return out;
}

/** A property's `m:val`, the shape OMML's properties have. */
export const mval = (pr: XmlEl | null | undefined, name: string): string | null => child(pr, name)?.attrs['m:val'] ?? null;

/** An on/off property: present without a value means on. */
export function flag(pr: XmlEl | null | undefined, name: string): boolean {
  const el = child(pr, name);
  if (!el) return false;
  const v = el.attrs['m:val'];
  return v === undefined || v === '1' || v === 'on' || v === 'true';
}

/** A character property, with OMML's default when it is absent. An empty value means none. */
export const chr = (pr: XmlEl | null | undefined, name: string, fallback: string): string => {
  const el = child(pr, name);
  if (!el) return fallback;
  return el.attrs['m:val'] ?? '';
};

/** The text of a run: `m:t`, and `w:t`/`w:delText` for a plain Word run inside an equation. */
export function runText(r: XmlEl): string {
  let text = '';

  for (const c of r.children) {
    if (c.name === 'm:t' || c.name === 'w:t' || c.name === 'w:delText') text += c.text;
    else if (c.name === 'w:tab') text += '\t';
  }

  return text;
}

/** All the text inside an element, for things neither converter knows. */
export function allText(el: XmlEl): string {
  if (el.name === 'm:t' || el.name === 'w:t' || el.name === 'w:delText') return el.text;
  return el.children.map(allText).join('');
}

export interface RunStyle {
  /** `m:sty`: p, b, i or bi; null for the default (italic letters, upright everything else). */
  sty: string | null;
  scr: string | null;
  /** Normal text: shown as the document's text is, not as math. */
  nor: boolean;
  /** The run's colour as six hex digits, if it has one. */
  color: string | null;
}

export function runStyle(r: XmlEl): RunStyle {
  const mpr = child(r, 'm:rPr');
  const wpr = child(r, 'w:rPr');
  const color = val(wpr, 'w:color');

  return {
    sty: mval(mpr, 'm:sty'),
    scr: mval(mpr, 'm:scr'),
    nor: flag(mpr, 'm:nor') || r.name === 'w:r',
    color: color && /^[0-9a-fA-F]{6}$/.test(color) ? color.toUpperCase() : null,
  };
}

/** Where an n-ary operator puts its limits: under and over it, or beside it as scripts. */
export function naryLimLoc(pr: XmlEl | null | undefined, op: string): 'undOvr' | 'subSup' {
  const loc = mval(pr, 'm:limLoc');
  if (loc === 'undOvr' || loc === 'subSup') return loc;
  return INTEGRALS.has(op) ? 'subSup' : 'undOvr';
}

/** Parses an equation's XML; null if it is not one. */
export function parseEquation(xml: string): XmlEl | null {
  try {
    const el = parseXml(xml);
    return el.name === 'm:oMath' || el.name === 'm:oMathPara' ? el : null;
  } catch {
    return null;
  }
}

/** The `m:oMath` elements of an equation: itself, or the lines of an `m:oMathPara`. */
export function linesOf(el: XmlEl): XmlEl[] {
  if (el.name === 'm:oMath') return [el];
  return rowItems(el).filter((c) => c.name === 'm:oMath');
}

/** How an equation on a line of its own is aligned: left, right or center. */
export function paraAlign(el: XmlEl): string {
  const jc = mval(child(el, 'm:oMathParaPr'), 'm:jc');
  return jc === 'left' || jc === 'right' ? jc : 'center';
}
