// Multi-column sections on screen.
//
// A section with more than one column is a run of the doc's own blocks (src/columns/model.ts),
// with no element around them, so CSS columns have nothing to apply to. Instead each block of
// the run is set at its column's width and placed where the column flow (src/columns/flow.ts)
// puts it: node decorations make it `position: absolute` with its column's left and right edges
// and its top. A spacer after the run, in the ordinary flow, is as tall as the columns, so what
// follows starts below them. A paragraph split between two columns is drawn as two CSS columns
// of its own, the first pushed down by a lead to where its head belongs.
//
// The layout is measured with the blocks at their column widths and the spacers at nothing,
// then set: in Pages view by pages.ts (`measureGaps`, page by page with the footnotes), in the
// continuous view here (`layoutContinuous`), as sets of columns a page's body tall, one under
// the other, with the last balanced.

import type { Node as PMNode } from 'prosemirror-model';
import { type EditorState, Plugin, PluginKey } from 'prosemirror-state';
import { Decoration, DecorationSet, type EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { lineBoxes } from '../editor/pages';
import { schema } from '../editor/schema';
import '../styles/columns.css';
import { type FlowBlock, type FlowResult, flowColumns } from './flow';
import { type SectionRange, columnBoxes, sectionRanges } from './model';

const N = schema.nodes;

/** In the continuous view, between one page's worth of columns and the next. */
const SET_GAP = 24;

export interface Run {
  index: number;
  range: SectionRange;
  blocks: { pos: number; node: PMNode }[];
}

export interface BlockSpot {
  col: number;
  /** In the editor's own pixels, from its top. */
  top: number;
  /** A paragraph split into the next column: the room above its head, and its height down to the cut. */
  split?: { lead: number; height: number };
}

export interface RunLayout {
  spots: BlockSpot[];
  /** The spacer's height, and the space after the run's last block. */
  spacer: number;
  after: number;
  rules: { left: number; top: number; height: number }[];
}

interface ColumnsState {
  ranges: SectionRange[];
  runs: Run[];
  layouts: (RunLayout | null)[];
  measuring: boolean;
  decorations: DecorationSet;
}

interface Meta {
  layouts?: (RunLayout | null)[];
  measuring?: boolean;
}

export const columnsKey = new PluginKey<ColumnsState>('columns');

/** The body's width, which the columns share. */
export const bodyWidth = (ctx: DocContext) => Math.max(20, ctx.page.width - ctx.page.left - ctx.page.right);

function runsOf(doc: PMNode, ranges: readonly SectionRange[]): Run[] {
  const runs: Run[] = [];

  for (const range of ranges) {
    if (range.cols.count < 2 || range.to <= range.from) continue;

    const blocks: Run['blocks'] = [];
    doc.nodesBetween(range.from, range.to, (node, pos) => {
      if (pos >= range.from && pos < range.to) blocks.push({ pos, node });
      return false;
    });
    runs.push({ index: runs.length, range, blocks });
  }

  return runs;
}

function spacerDom(index: number, layout: RunLayout | null, measuring: boolean): HTMLElement {
  const el = document.createElement('div');

  el.className = 'col-spacer';
  el.dataset.run = String(index);
  el.contentEditable = 'false';
  el.setAttribute('aria-hidden', 'true');
  el.style.height = `${measuring || !layout ? 0 : layout.spacer}px`;
  el.style.marginBottom = `${measuring || !layout ? 0 : layout.after}px`;

  for (const rule of measuring || !layout ? [] : layout.rules) {
    const line = document.createElement('div');
    line.className = 'col-rule';
    line.style.left = `${rule.left}px`;
    line.style.top = `${rule.top}px`;
    line.style.height = `${rule.height}px`;
    el.append(line);
  }

  return el;
}

function decorate(doc: PMNode, ctx: DocContext, runs: readonly Run[], layouts: readonly (RunLayout | null)[], measuring: boolean): DecorationSet {
  const width = bodyWidth(ctx);
  const decos: Decoration[] = [];

  for (const run of runs) {
    const layout = layouts[run.index] ?? null;
    const boxes = columnBoxes(run.range.cols, width);

    run.blocks.forEach(({ pos, node }, i) => {
      const spot = layout?.spots[i];
      const col = Math.min(spot?.col ?? 0, boxes.length - 1);
      const box = boxes[col];
      const split = !measuring && spot?.split && boxes[col + 1] ? spot.split : null;
      const last = split ? boxes[col + 1] : box;
      let style = `left:${box.x}px;right:${width - last.x - last.width}px;top:${measuring || !spot ? 0 : spot.top}px;`;

      if (split) {
        style += `column-count:2;column-gap:${last.x - box.x - box.width}px;height:${split.height}px;`;
        decos.push(
          Decoration.widget(pos + 1, () => {
            const lead = document.createElement('span');
            lead.className = 'col-lead';
            lead.style.height = `${split.lead}px`;
            return lead;
          }, { side: -1, ignoreSelection: true, key: `col-lead:${split.lead.toFixed(1)}` }),
        );
      }

      decos.push(Decoration.node(pos, pos + node.nodeSize, { class: split ? 'col-block col-split' : 'col-block', style }));
    });

    const key = `col-spacer:${run.index}:${measuring || !layout ? 0 : `${layout.spacer.toFixed(1)}:${layout.after}:${JSON.stringify(layout.rules)}`}`;
    decos.push(Decoration.widget(run.range.to, () => spacerDom(run.index, layout, measuring), { side: -1, ignoreSelection: true, key }));
  }

  return DecorationSet.create(doc, decos);
}

export function columnsPlugin(ctx: DocContext): Plugin<ColumnsState> {
  const make = (doc: PMNode, layouts: (RunLayout | null)[], measuring: boolean): ColumnsState => {
    const ranges = sectionRanges(doc, ctx.sectPr);
    const runs = runsOf(doc, ranges);
    return { ranges, runs, layouts, measuring, decorations: runs.length ? decorate(doc, ctx, runs, layouts, measuring) : DecorationSet.empty };
  };

  return new Plugin<ColumnsState>({
    key: columnsKey,
    state: {
      init: (_config, state) => make(state.doc, [], false),
      apply(tr, old) {
        const meta = tr.getMeta(columnsKey) as Meta | undefined;
        if (meta) return make(tr.doc, meta.layouts ?? old.layouts, meta.measuring ?? false);
        // Until it is measured again, each block keeps the place it had.
        return tr.docChanged ? make(tr.doc, old.layouts, old.measuring) : old;
      },
    },
    props: {
      decorations: (state) => columnsKey.getState(state)?.decorations,
      attributes: (state): Record<string, string> => (columnsKey.getState(state)?.runs.length ? { class: 'has-columns' } : {}),
    },
  });
}

export function runsIn(state: EditorState): readonly Run[] {
  return columnsKey.getState(state)?.runs ?? [];
}

export function sectionRangesIn(state: EditorState): readonly SectionRange[] {
  return columnsKey.getState(state)?.ranges ?? [];
}

/** Puts the runs' blocks at their column widths with no places and no spacers, to be measured. */
export function startMeasure(view: EditorView): void {
  if (runsIn(view.state).length) view.dispatch(view.state.tr.setMeta(columnsKey, { measuring: true }));
}

export function setLayouts(view: EditorView, layouts: (RunLayout | null)[]): void {
  if (runsIn(view.state).length || columnsKey.getState(view.state)?.layouts.length) view.dispatch(view.state.tr.setMeta(columnsKey, { layouts, measuring: false }));
}

/** Where a run sits in the flow while measured (its spacer's top), in the editor's own pixels. */
export function runAnchor(view: EditorView, run: Run, toY: (clientY: number) => number): number {
  const spacer = view.dom.querySelector<HTMLElement>(`.col-spacer[data-run="${run.index}"]`);
  return spacer ? toY(spacer.getBoundingClientRect().top) : 0;
}

/** The run's blocks as measured at their column widths, with the footnote room each needs. */
export function measureRun(
  view: EditorView,
  run: Run,
  toY: (clientY: number) => number,
  notes: readonly { pos: number; height: number }[] = [],
): FlowBlock[] {
  return run.blocks.map(({ pos, node }) => {
    const dom = view.nodeDOM(pos);
    if (!(dom instanceof HTMLElement)) return { height: 0, marginTop: 0, marginBottom: 0 };

    const rect = dom.getBoundingClientRect();
    const style = getComputedStyle(dom);
    const top = toY(rect.top);
    const block: FlowBlock = {
      height: toY(rect.bottom) - top,
      marginTop: parseFloat(style.marginTop) || 0,
      marginBottom: parseFloat(style.marginBottom) || 0,
      foot: notes.filter((n) => n.pos >= pos && n.pos < pos + node.nodeSize).reduce((sum, n) => sum + n.height, 0),
    };

    if (node.type === N.paragraph) {
      block.lines = lineBoxes(dom, toY).map((l) => ({ top: l.top - top, bottom: l.bottom - top }));

      // A column or page break: at the start of the paragraph it comes before it, otherwise after.
      let text = false;
      node.forEach((inline) => {
        if (inline.type === N.page_break) {
          const kind = inline.attrs.column ? 'column' : 'page';
          if (text) block.breakAfter = kind;
          else block.breakBefore = kind;
        } else if (inline.isText || inline.type === N.image || inline.type === N.chart || inline.type === N.math) {
          text = true;
        }
      });
    }

    return block;
  });
}

/** Where the flow puts the run's blocks, in the editor's pixels; `pageTop(p)` is the top of the body on the run's page p. */
export function placeRun(run: Run, blocks: readonly FlowBlock[], flow: FlowResult, ctx: DocContext, pageTop: (p: number) => number): RunLayout {
  const boxes = columnBoxes(run.range.cols, bodyWidth(ctx));

  const spots = flow.placements.map((p, i): BlockSpot => {
    const lines = blocks[i].lines;
    const k = p.split?.line ?? 0;

    if (!p.split || !lines || k < 1 || k >= lines.length) return { col: p.col, top: pageTop(p.page) + p.y };

    const lead = p.y - p.split.tailTop;
    // The text boxes are a little shorter than the line boxes: the first line that goes is cut at its top.
    const cut = lines[k].top;
    return { col: p.col, top: pageTop(p.page) + p.split.tailTop, split: { lead, height: lead + cut } };
  });

  const rules: RunLayout['rules'] = [];

  if (run.range.cols.sep) {
    flow.pages.forEach((page, p) => {
      if (page.bottom - page.top < 1) return;
      for (let c = 1; c < boxes.length; c++) {
        const left = (boxes[c - 1].x + boxes[c - 1].width + boxes[c].x) / 2;
        rules.push({ left, top: pageTop(p) + page.top, height: page.bottom - page.top });
      }
    });
  }

  return { spots, spacer: 0, after: blocks[blocks.length - 1]?.marginBottom ?? 0, rules };
}

/** Lays the runs out in the continuous view: each one balanced, where it stands in the flow. */
export function layoutContinuous(view: EditorView, ctx: DocContext, zoom: number): void {
  const runs = runsIn(view.state);
  if (!runs.length) {
    setLayouts(view, []);
    return;
  }

  startMeasure(view);

  const origin = view.dom.getBoundingClientRect();
  const toY = (clientY: number) => (clientY - origin.top) / zoom;
  const layouts: RunLayout[] = [];
  /** How much the spacers above have pushed this run down. */
  let pushed = 0;

  for (const run of runs) {
    const anchor = runAnchor(view, run, toY) + pushed;
    const blocks = measureRun(view, run, toY);
    // Column sets a page's body tall, one under the other, the last balanced.
    const height = Math.max(100, ctx.page.height - ctx.page.top - ctx.page.bottom);
    const flow = flowColumns(blocks, { cols: run.range.cols.count, startY: 0, bodyHeight: () => height, balance: true });
    const tops: number[] = [];
    let y = anchor;

    for (const page of flow.pages) {
      tops.push(y);
      y += page.bottom + SET_GAP;
    }

    const layout = placeRun(run, blocks, flow, ctx, (p) => tops[p] ?? anchor);
    layout.spacer = Math.max(0, y - SET_GAP - anchor);
    pushed += layout.spacer + layout.after;
    layouts.push(layout);
  }

  setLayouts(view, layouts);
}
