// The equation editor's linear form to OMML.
//
// Pure. Reads LaTeX (`\frac{a}{b}`, `x^2`, `\sqrt[n]{x}`, `\sum_{i=1}^n`, `\left( … \right)`,
// matrices and the rest of what linear.ts writes) and the practical part of Word's UnicodeMath:
// `a/b` for a fraction, `x^(n+1)` with the brackets dropped, `√x`, `∑_(i=1)^n▒…`, and Unicode
// characters typed as they are. Unknown commands are kept as their text and reported.

import { escAttr, escText } from '../docx/xml';
import { M_NS } from './omml';
import { ACCENTS, DELIMITERS, FUNCTIONS, GROUP_CHARS, INTEGRALS, LIMIT_FUNCTIONS, NARY, NARY_CHARS, SHORT, STYLE_COMMANDS, SYMBOLS } from './symbols';

// ---- The tree -----------------------------------------------------------------------------------

interface Style {
  sty?: string;
  scr?: string;
  nor?: boolean;
  color?: string;
}

type Row = Node[];

type Node =
  | { t: 'c'; text: string; style: Style }
  | { t: 'group'; row: Row }
  | { t: 'paren'; row: Row; close: boolean }
  | { t: 'f'; type: string; num: Row; den: Row }
  | { t: 'sub' | 'sup' | 'subsup'; e: Row; sub: Row; sup: Row }
  | { t: 'pre'; e: Row; sub: Row; sup: Row }
  | { t: 'rad'; deg: Row | null; e: Row }
  | { t: 'nary'; chr: string; limLoc: string | null; sub: Row | null; sup: Row | null; e: Row }
  | { t: 'd'; beg: string; end: string; sep: string; parts: Row[] }
  | { t: 'func'; name: Row; e: Row }
  | { t: 'acc'; chr: string; e: Row }
  | { t: 'bar'; pos: string; e: Row }
  | { t: 'lim'; low: boolean; e: Row; lim: Row }
  | { t: 'group-chr'; chr: string; pos: string; e: Row }
  | { t: 'm'; rows: Row[][] }
  | { t: 'eqArr'; rows: Row[] }
  | { t: 'box' | 'borderBox' | 'phant'; e: Row }
  | { t: 'split'; kind: 'atop' | 'over' | 'choose' };

// ---- Tokens -------------------------------------------------------------------------------------

type Tok = { k: 'cmd'; v: string } | { k: 'ch'; v: string } | { k: '{' | '}' | '^' | '_' | '&' | 'nl' | 'sp'; v: string };

function tokenize(src: string): Tok[] {
  const out: Tok[] = [];
  const chars = [...src];
  let i = 0;

  while (i < chars.length) {
    const c = chars[i];

    if (c === '\\') {
      const next = chars[i + 1] ?? '';
      if (next === '\\') {
        out.push({ k: 'nl', v: '\\\\' });
        i += 2;
      } else if (/[a-zA-Z]/.test(next)) {
        let name = '';
        i++;
        while (i < chars.length && /[a-zA-Z]/.test(chars[i])) name += chars[i++];
        out.push({ k: 'cmd', v: name });
      } else {
        out.push({ k: 'cmd', v: next });
        i += 2;
      }
    } else if (c === '{' || c === '}' || c === '^' || c === '_' || c === '&') {
      out.push({ k: c, v: c });
      i++;
    } else if (/\s/.test(c)) {
      out.push({ k: 'sp', v: c });
      i++;
    } else {
      out.push({ k: 'ch', v: c });
      i++;
    }
  }

  return out;
}

// ---- The parser ---------------------------------------------------------------------------------

/** Characters that end an n-ary operator's body when it is not braced. */
const ENDS_BODY = new Set('+-−=<>≤≥≠±∓,;≈≡∼≅∝→←⇒⇔'.split(''));

const MATRIX_DELIMS: Record<string, [string, string]> = {
  matrix: ['', ''], pmatrix: ['(', ')'], bmatrix: ['[', ']'], vmatrix: ['|', '|'], Vmatrix: ['‖', '‖'], Bmatrix: ['{', '}'], smallmatrix: ['', ''],
};

const ROW_ENVS = new Set(['aligned', 'align', 'align*', 'eqnarray', 'eqnarray*', 'gathered', 'gather', 'gather*', 'split', 'cases']);

class Parser {
  i = 0;
  readonly problems: string[] = [];

  constructor(private readonly toks: Tok[]) {}

  peek(): Tok | undefined {
    return this.toks[this.i];
  }

  private skipSpace(): void {
    while (this.peek()?.k === 'sp') this.i++;
  }

  private isCmd(name: string): boolean {
    const t = this.peek();
    return t?.k === 'cmd' && t.v === name;
  }

  /** A row, up to (not taking) `}`, `&`, `\\`, `\right`, `\middle`, `\end` or a closing bracket. */
  row(opts: { amp?: boolean; paren?: boolean; bracket?: boolean; style?: Style } = {}): Row {
    const row: Row = [];
    const style = opts.style ?? {};

    for (;;) {
      const t = this.peek();
      if (!t || t.k === '}' || t.k === 'nl') break;
      if (t.k === '&' && !opts.amp) break;
      if (t.k === 'cmd' && (t.v === 'right' || t.v === 'middle' || t.v === 'end')) break;
      if (opts.paren && t.k === 'ch' && t.v === ')') break;
      if (opts.bracket && t.k === 'ch' && t.v === ']') break;

      if (t.k === 'sp') {
        this.i++;
        continue;
      }

      if (t.k === '^' || t.k === '_') {
        this.scripts(row);
        continue;
      }

      if (t.k === 'ch' && t.v === '/' && !style.nor) {
        this.i++;
        // Letters and digits written together make one operand, as in Word's linear format: 12/5x.
        const num: Row = [];
        while (row.length && isWordChar(row[row.length - 1])) num.unshift(row.pop()!);
        if (!num.length && row.length) num.push(...operand(row.pop()!));
        const den = this.operand();
        if (den.length === 1 && isWordChar(den[0])) {
          for (let n = this.peek(); n?.k === 'ch' && WORD.test(n.v); n = this.peek()) {
            den.push({ t: 'c', text: n.v, style });
            this.i++;
          }
        }
        row.push({ t: 'f', type: 'bar', num, den });
        continue;
      }

      if (t.k === '&') {
        this.i++;
        row.push({ t: 'c', text: '&', style });
        continue;
      }

      this.item(row, style);
    }

    return splitRow(row);
  }

  /** `^` and `_` after the last thing in the row. */
  private scripts(row: Row): void {
    let sub: Row | null = null;
    let sup: Row | null = null;

    for (;;) {
      this.skipSpace();
      const t = this.peek();
      if (t?.k === '_' && !sub) {
        this.i++;
        sub = this.operand();
      } else if (t?.k === '^' && !sup) {
        this.i++;
        sup = this.operand();
      } else break;
    }

    const base = row.pop();

    // An underbrace's label goes under it, an overbrace's over it.
    if (base?.t === 'group-chr' && ((base.pos === 'bot' && sub && !sup) || (base.pos === 'top' && sup && !sub))) {
      row.push({ t: 'lim', low: base.pos === 'bot', e: [base], lim: (sub ?? sup)! });
      return;
    }

    const e = base ? (base.t === 'group' ? base.row : [base]) : [];
    if (sub && sup) row.push({ t: 'subsup', e, sub, sup });
    else if (sub) row.push({ t: 'sub', e, sub, sup: [] });
    else if (sup) row.push({ t: 'sup', e, sub: [], sup });
  }

  /** One argument: a braced group, a bracketed one (brackets dropped), or a single item. */
  operand(): Row {
    this.skipSpace();
    const t = this.peek();
    if (!t) return [];

    if (t.k === '{') return this.group();

    if (t.k === 'ch' && t.v === '(') {
      const node = this.paren();
      return node.t === 'paren' && node.close ? node.row : [node];
    }

    if (t.k === 'ch' || t.k === 'cmd') {
      const row: Row = [];
      this.item(row, {});
      return row;
    }

    return [];
  }

  private group(style?: Style): Row {
    this.i++; // {
    const row = this.row({ style });
    if (this.peek()?.k === '}') this.i++;
    else this.problems.push('A { is not closed');
    return row;
  }

  private paren(): Node {
    this.i++; // (
    const row = this.row({ paren: true });
    const close = this.peek()?.k === 'ch' && this.peek()!.v === ')';
    if (close) this.i++;
    return { t: 'paren', row, close };
  }

  /** Raw text up to the matching `}`, for `\text{…}`, `\operatorname{…}` and colours. */
  private rawGroup(): string {
    this.skipSpace();
    if (this.peek()?.k !== '{') return '';
    this.i++;
    let depth = 0;
    let out = '';

    for (let t = this.peek(); t; t = this.peek()) {
      this.i++;
      if (t.k === '{') depth++;
      if (t.k === '}' && depth-- === 0) return out;
      out += t.k === 'cmd' ? (/^[a-zA-Z]+$/.test(t.v) ? `\\${t.v}` : t.v) : t.v;
    }

    this.problems.push('A { is not closed');
    return out;
  }

  private delimiter(): string {
    this.skipSpace();
    const t = this.peek();
    if (!t) return '';
    this.i++;
    const key = t.k === 'cmd' ? `\\${t.v}` : t.v;
    if (key in DELIMITERS) return DELIMITERS[key];
    if (t.k === 'cmd' && SYMBOLS[t.v]) return SYMBOLS[t.v];
    return t.k === 'ch' ? t.v : '';
  }

  private nary(chr: string, row: Row): void {
    let limLoc: string | null = null;
    let sub: Row | null = null;
    let sup: Row | null = null;

    for (;;) {
      this.skipSpace();
      const t = this.peek();
      if (t?.k === 'cmd' && (t.v === 'limits' || t.v === 'nolimits')) {
        limLoc = t.v === 'limits' ? 'undOvr' : 'subSup';
        this.i++;
      } else if (t?.k === '_' && !sub) {
        this.i++;
        sub = this.operand();
      } else if (t?.k === '^' && !sup) {
        this.i++;
        sup = this.operand();
      } else break;
    }

    this.skipSpace();
    if (this.peek()?.k === 'ch' && this.peek()!.v === '▒') this.i++;
    this.skipSpace();

    let e: Row;
    if (this.peek()?.k === '{') {
      e = this.group();
    } else {
      // The body runs to the next operator or relation at this level, as Word's linear format has it.
      e = [];
      for (let t = this.peek(); t; t = this.peek()) {
        if (t.k === 'ch' && ENDS_BODY.has(t.v)) break;
        if (t.k === 'cmd' && SYMBOLS[t.v] && ENDS_BODY.has(SYMBOLS[t.v])) break;
        if (t.k === '}' || t.k === '&' || t.k === 'nl' || (t.k === 'cmd' && (t.v === 'right' || t.v === 'middle' || t.v === 'end'))) break;
        if (t.k === 'ch' && t.v === ')') break;
        if (t.k === 'sp') {
          this.i++;
          continue;
        }
        if (t.k === '^' || t.k === '_') this.scripts(e);
        else this.item(e, {});
      }
    }

    row.push({ t: 'nary', chr, limLoc, sub, sup, e });
  }

  private func(name: Row, nameText: string, row: Row): void {
    let head: Row = name;
    let sub: Row | null = null;
    let sup: Row | null = null;

    for (;;) {
      this.skipSpace();
      const t = this.peek();
      if (t?.k === '_' && !sub) {
        this.i++;
        sub = this.operand();
      } else if (t?.k === '^' && !sup) {
        this.i++;
        sup = this.operand();
      } else break;
    }

    if (sub && !sup && LIMIT_FUNCTIONS.has(nameText)) head = [{ t: 'lim', low: true, e: name, lim: sub }];
    else if (sub && sup) head = [{ t: 'subsup', e: name, sub, sup }];
    else if (sub) head = [{ t: 'sub', e: name, sub, sup: [] }];
    else if (sup) head = [{ t: 'sup', e: name, sub: [], sup }];

    this.skipSpace();
    const t = this.peek();
    let e: Row = [];

    if (t?.k === '{') e = this.group();
    else if (t && (t.k === 'ch' || t.k === 'cmd') && !(t.k === 'cmd' && (t.v === 'right' || t.v === 'middle' || t.v === 'end'))) {
      if (!(t.k === 'ch' && (ENDS_BODY.has(t.v) || t.v === ')'))) {
        this.item(e, {});
        this.skipSpace();
        if (this.peek()?.k === '^' || this.peek()?.k === '_') this.scripts(e);
      }
    }

    row.push({ t: 'func', name: head, e });
  }

  private env(row: Row): void {
    const name = this.rawGroup();
    const matrix = MATRIX_DELIMS[name];
    const rows: Row[][] = [];

    // Column specs (`array`'s {cc}) are read and left aside.
    if (name === 'array') this.rawGroup();

    for (;;) {
      const cells: Row[] = [];
      for (;;) {
        cells.push(this.row({ amp: !matrix && name !== 'array' }));
        if (this.peek()?.k === '&') this.i++;
        else break;
      }
      rows.push(cells);
      if (this.peek()?.k === 'nl') this.i++;
      else break;
    }

    if (this.isCmd('end')) {
      this.i++;
      this.rawGroup();
    } else this.problems.push(`\\begin{${name}} has no \\end`);

    // A trailing `\\` leaves an empty last row.
    if (rows.length > 1 && rows[rows.length - 1].every((c) => c.length === 0)) rows.pop();

    if (matrix || name === 'array') {
      const m: Node = { t: 'm', rows };
      const [beg, end] = matrix ?? ['', ''];
      row.push(beg || end ? { t: 'd', beg, end, sep: '|', parts: [[m]] } : m);
    } else {
      const arr: Node = { t: 'eqArr', rows: rows.map((cells) => cells.flatMap((c, i) => (i ? [{ t: 'c', text: '&', style: {} } as Node, ...c] : c))) };
      row.push(name === 'cases' ? { t: 'd', beg: '{', end: '', sep: '|', parts: [[arr]] } : arr);
      if (!ROW_ENVS.has(name)) this.problems.push(`Unknown environment ${name}, read as aligned rows`);
    }
  }

  /** One thing: a character, a group or a command with its arguments. */
  item(row: Row, style: Style): void {
    const t = this.peek()!;

    if (t.k === '{') {
      row.push({ t: 'group', row: this.group(style) });
      return;
    }

    if (t.k === 'ch') {
      this.i++;
      if (style.nor) row.push({ t: 'c', text: t.v, style });
      else if (t.v === '(') {
        this.i--;
        row.push(this.paren());
      } else if (NARY_CHARS.has(t.v)) this.nary(t.v, row);
      else if (t.v === '√') row.push({ t: 'rad', deg: null, e: this.operand() });
      else if (t.v === '▒') return;
      else row.push({ t: 'c', text: t.v, style });
      return;
    }

    if (t.k !== 'cmd') {
      this.i++;
      return;
    }

    this.i++;
    const name = t.v;

    if (SHORT[name] !== undefined) {
      if (SHORT[name]) row.push({ t: 'c', text: SHORT[name], style });
      return;
    }
    if (name === 'slash') return void row.push({ t: 'c', text: '/', style });
    if (SYMBOLS[name]) return void row.push({ t: 'c', text: SYMBOLS[name], style });
    if (NARY[name]) return this.nary(NARY[name], row);
    if (FUNCTIONS.has(name)) return this.func([{ t: 'c', text: name, style: { sty: 'p' } }], name, row);

    switch (name) {
      case 'operatorname': {
        const text = this.rawGroup();
        return this.func([{ t: 'c', text, style: { sty: 'p' } }], text, row);
      }
      case 'frac': case 'dfrac': case 'tfrac': case 'cfrac':
        return void row.push({ t: 'f', type: 'bar', num: this.operand(), den: this.operand() });
      case 'sfrac':
        return void row.push({ t: 'f', type: 'skw', num: this.operand(), den: this.operand() });
      case 'linfrac':
        return void row.push({ t: 'f', type: 'lin', num: this.operand(), den: this.operand() });
      case 'binom': case 'dbinom': case 'tbinom':
        return void row.push({ t: 'd', beg: '(', end: ')', sep: '|', parts: [[{ t: 'f', type: 'noBar', num: this.operand(), den: this.operand() }]] });
      case 'atop': case 'over': case 'choose':
        return void row.push({ t: 'split', kind: name });
      case 'sqrt': {
        this.skipSpace();
        let deg: Row | null = null;
        if (this.peek()?.k === 'ch' && this.peek()!.v === '[') {
          this.i++;
          deg = this.row({ bracket: true });
          if (this.peek()?.k === 'ch' && this.peek()!.v === ']') this.i++;
        }
        return void row.push({ t: 'rad', deg, e: this.operand() });
      }
      case 'left': {
        const beg = this.delimiter();
        const parts: Row[] = [this.row()];
        let sep = '|';
        while (this.isCmd('middle')) {
          this.i++;
          sep = this.delimiter();
          parts.push(this.row());
        }
        let end = '';
        if (this.isCmd('right')) {
          this.i++;
          end = this.delimiter();
        } else this.problems.push('\\left has no \\right');
        return void row.push({ t: 'd', beg, end, sep, parts });
      }
      case 'overline':
        return void row.push({ t: 'bar', pos: 'top', e: this.operand() });
      case 'underline':
        return void row.push({ t: 'bar', pos: 'bot', e: this.operand() });
      case 'underset': case 'overset': case 'stackrel': {
        const lim = this.operand();
        return void row.push({ t: 'lim', low: name === 'underset', e: this.operand(), lim });
      }
      case 'prescript': {
        const sup = this.operand();
        const sub = this.operand();
        return void row.push({ t: 'pre', sub, sup, e: this.operand() });
      }
      case 'boxed': case 'fbox':
        return void row.push({ t: 'borderBox', e: this.operand() });
      case 'box':
        return void row.push({ t: 'box', e: this.operand() });
      case 'phantom':
        return void row.push({ t: 'phant', e: this.operand() });
      case 'textcolor': case 'color': {
        const color = this.rawGroup().replace(/^#/, '').toUpperCase();
        this.skipSpace();
        if (this.peek()?.k !== '{') return;
        const inner = { ...style, color: /^[0-9A-F]{6}$/.test(color) ? color : undefined };
        return void row.push({ t: 'group', row: this.group(inner) });
      }
      case 'begin':
        return this.env(row);
      case 'limits': case 'nolimits': case 'displaystyle': case 'textstyle': case 'scriptstyle': case 'mathop': case 'mathord':
        return;
    }

    if (ACCENTS[name]) return void row.push({ t: 'acc', chr: ACCENTS[name], e: this.operand() });

    if (GROUP_CHARS[name]) {
      const g = GROUP_CHARS[name];
      return void row.push({ t: 'group-chr', chr: g.chr, pos: g.pos, e: this.operand() });
    }

    const look = STYLE_COMMANDS[name];
    if (look) {
      if (look.nor) {
        const text = this.rawGroup().replace(/\\([{}])/g, '$1').replace(/\\backslash/g, '\\');
        if (text) row.push({ t: 'c', text, style: { nor: true, color: style.color } });
        return;
      }
      this.skipSpace();
      const inner: Style = { ...style, ...(look.sty ? { sty: look.sty } : {}), ...(look.scr ? { scr: look.scr } : {}) };
      // \mathbf around \mathcal and the like: the bold goes with the script.
      if (style.scr && look.sty === 'b') inner.scr = style.scr;
      if (this.peek()?.k === '{') row.push({ t: 'group', row: this.group(inner) });
      else if (this.peek()) this.item(row, inner);
      return;
    }

    this.problems.push(`Unknown command \\${name}`);
    row.push({ t: 'c', text: `\\${name}`, style });
  }
}

const WORD = /^[\p{L}\p{N}.]$/u;
const isWordChar = (n: Node): boolean => n.t === 'c' && !n.style.nor && WORD.test(n.text);

/** The bracketed operand of `/`, `^` or `_` loses its brackets; any other thing is itself. */
function operand(node: Node): Row {
  if (node.t === 'group') return node.row;
  if (node.t === 'paren' && node.close) return node.row;
  return [node];
}

/** `{a \atop b}` and `{a \over b}`: a row with a split in it is a fraction. */
function splitRow(row: Row): Row {
  const at = row.findIndex((n) => n.t === 'split');
  if (at < 0) return row;

  const kind = (row[at] as { kind: string }).kind;
  const num = row.slice(0, at);
  const den = row.slice(at + 1).filter((n) => n.t !== 'split');
  const f: Node = { t: 'f', type: kind === 'over' ? 'bar' : 'noBar', num, den };
  return kind === 'choose' ? [{ t: 'd', beg: '(', end: ')', sep: '|', parts: [[f]] }] : [f];
}

// ---- Writing OMML -------------------------------------------------------------------------------

const FONT = '<w:rFonts w:ascii="Cambria Math" w:hAnsi="Cambria Math"/>';
const CTRL = `<m:ctrlPr><w:rPr>${FONT}<w:i/></w:rPr></m:ctrlPr>`;

const styleKey = (s: Style) => `${s.sty ?? ''}|${s.scr ?? ''}|${s.nor ? 1 : 0}|${s.color ?? ''}`;

function runXml(text: string, style: Style): string {
  let mpr = '';
  if (style.nor) mpr = '<m:nor/>';
  else {
    if (style.scr) mpr += `<m:scr m:val="${escAttr(style.scr)}"/>`;
    if (style.sty) mpr += `<m:sty m:val="${escAttr(style.sty)}"/>`;
  }
  // Normal text keeps the document's font; math text is in Cambria Math, as Word writes it.
  const wpr = (style.nor ? '' : FONT) + (style.color ? `<w:color w:val="${style.color}"/>` : '');
  const space = /^\s|\s$/.test(text) ? ' xml:space="preserve"' : '';
  return `<m:r>${mpr ? `<m:rPr>${mpr}</m:rPr>` : ''}${wpr ? `<w:rPr>${wpr}</w:rPr>` : ''}<m:t${space}>${escText(text)}</m:t></m:r>`;
}

const el = (name: string, inner: string) => (inner ? `<m:${name}>${inner}</m:${name}>` : `<m:${name}/>`);
const pr = (name: string, inner: string) => `<m:${name}Pr>${inner}${CTRL}</m:${name}Pr>`;
const v = (name: string, value: string) => `<m:${name} m:val="${escAttr(value)}"/>`;

function rowXml(row: Row): string {
  let out = '';
  let text = '';
  let style: Style = {};

  const flush = () => {
    if (text) out += runXml(text, style);
    text = '';
  };

  const walk = (nodes: Row) => {
    for (const n of nodes) {
      if (n.t === 'c') {
        if (text && styleKey(n.style) !== styleKey(style)) flush();
        style = n.style;
        text += n.text;
      } else if (n.t === 'group') {
        walk(n.row);
      } else if (n.t === 'paren') {
        walk([{ t: 'c', text: '(', style: {} }, ...n.row, ...(n.close ? [{ t: 'c', text: ')', style: {} } as Node] : [])]);
      } else {
        flush();
        out += nodeXml(n);
      }
    }
  };

  walk(row);
  flush();
  return out;
}

function nodeXml(n: Node): string {
  const R = rowXml;

  switch (n.t) {
    case 'f':
      return `<m:f>${pr('f', n.type === 'bar' ? '' : v('type', n.type))}${el('num', R(n.num))}${el('den', R(n.den))}</m:f>`;
    case 'sub':
      return `<m:sSub>${pr('sSub', '')}${el('e', R(n.e))}${el('sub', R(n.sub))}</m:sSub>`;
    case 'sup':
      return `<m:sSup>${pr('sSup', '')}${el('e', R(n.e))}${el('sup', R(n.sup))}</m:sSup>`;
    case 'subsup':
      return `<m:sSubSup>${pr('sSubSup', '')}${el('e', R(n.e))}${el('sub', R(n.sub))}${el('sup', R(n.sup))}</m:sSubSup>`;
    case 'pre':
      return `<m:sPre>${pr('sPre', '')}${el('sub', R(n.sub))}${el('sup', R(n.sup))}${el('e', R(n.e))}</m:sPre>`;
    case 'rad':
      return `<m:rad>${pr('rad', n.deg?.length ? '' : v('degHide', '1'))}${el('deg', n.deg ? R(n.deg) : '')}${el('e', R(n.e))}</m:rad>`;
    case 'nary': {
      const usual = INTEGRALS.has(n.chr) ? 'subSup' : 'undOvr';
      const props =
        (n.chr === '∫' ? '' : v('chr', n.chr)) +
        v('limLoc', n.limLoc ?? usual) +
        (n.sub ? '' : v('subHide', '1')) +
        (n.sup ? '' : v('supHide', '1'));
      return `<m:nary>${pr('nary', props)}${el('sub', R(n.sub ?? []))}${el('sup', R(n.sup ?? []))}${el('e', R(n.e))}</m:nary>`;
    }
    case 'd': {
      const props = (n.beg === '(' ? '' : v('begChr', n.beg)) + (n.sep === '|' ? '' : v('sepChr', n.sep)) + (n.end === ')' ? '' : v('endChr', n.end));
      return `<m:d>${pr('d', props)}${n.parts.map((p) => el('e', R(p))).join('')}</m:d>`;
    }
    case 'func':
      return `<m:func>${pr('func', '')}${el('fName', R(n.name))}${el('e', R(n.e))}</m:func>`;
    case 'acc':
      return `<m:acc>${pr('acc', n.chr === '̂' ? '' : v('chr', n.chr))}${el('e', R(n.e))}</m:acc>`;
    case 'bar':
      return `<m:bar>${pr('bar', v('pos', n.pos))}${el('e', R(n.e))}</m:bar>`;
    case 'lim': {
      const name = n.low ? 'limLow' : 'limUpp';
      return `<m:${name}>${pr(name, '')}${el('e', R(n.e))}${el('lim', R(n.lim))}</m:${name}>`;
    }
    case 'group-chr':
      return `<m:groupChr>${pr('groupChr', v('chr', n.chr) + v('pos', n.pos) + v('vertJc', n.pos === 'top' ? 'bot' : 'top'))}${el('e', R(n.e))}</m:groupChr>`;
    case 'm': {
      const cols = Math.max(1, ...n.rows.map((r) => r.length));
      const mpr = `<m:mPr><m:mcs><m:mc><m:mcPr>${v('count', String(cols))}${v('mcJc', 'center')}</m:mcPr></m:mc></m:mcs>${CTRL}</m:mPr>`;
      const rows = n.rows.map((r) => `<m:mr>${Array.from({ length: cols }, (_, i) => el('e', R(r[i] ?? []))).join('')}</m:mr>`);
      return `<m:m>${mpr}${rows.join('')}</m:m>`;
    }
    case 'eqArr':
      return `<m:eqArr>${pr('eqArr', '')}${n.rows.map((r) => el('e', R(r))).join('')}</m:eqArr>`;
    case 'box':
      return `<m:box>${pr('box', '')}${el('e', R(n.e))}</m:box>`;
    case 'borderBox':
      return `<m:borderBox>${pr('borderBox', '')}${el('e', R(n.e))}</m:borderBox>`;
    case 'phant':
      return `<m:phant>${pr('phant', v('show', '0'))}${el('e', R(n.e))}</m:phant>`;
    default:
      return '';
  }
}

// ---- The whole --------------------------------------------------------------------------------

export interface Parsed {
  /** The equation's XML: `m:oMath`, or `m:oMathPara` for one on a line of its own. */
  xml: string;
  problems: string[];
}

export interface ParseOptions {
  display: boolean;
  /** `m:oMathParaPr` to keep, from the equation this one replaces. */
  paraPr?: string;
  /** Declare the math namespace on the element itself, for XML that has to stand alone. */
  namespace?: boolean;
}

/** Linear text to OMML. A display equation gets a line per top-level `\\`; an inline one an array. */
export function linearToOmml(text: string, options: ParseOptions): Parsed {
  const parser = new Parser(tokenize(text));
  const lines: Row[] = [];

  for (;;) {
    lines.push(parser.row());
    const t = parser.peek();
    if (!t) break;
    parser.i++;
    if (t.k === '}') parser.problems.push('A } has no {');
    else if (t.k !== 'nl') parser.problems.push(`Unexpected ${t.v}`);
  }

  const ns = options.namespace ? ` xmlns:m="${M_NS}"` : '';
  const nonEmpty = lines.length > 1 ? lines.filter((l, i) => l.length || i === 0) : lines;

  if (options.display) {
    const maths = nonEmpty.map((l) => `<m:oMath>${rowXml(l)}</m:oMath>`).join('');
    return { xml: `<m:oMathPara${ns}>${options.paraPr ?? ''}${maths}</m:oMathPara>`, problems: parser.problems };
  }

  const body = nonEmpty.length > 1 ? nodeXml({ t: 'eqArr', rows: nonEmpty }) : rowXml(nonEmpty[0]);
  return { xml: `<m:oMath${ns}>${body}</m:oMath>`, problems: parser.problems };
}
