// Zotero, while it runs: its local API (Zotero 7) answers searches of the user's library with
// CSL-JSON. The desktop app asks it from the main process; in a browser, the page asks itself.

import { cslToSource } from './formats';
import type { Source } from './model';

export const ZOTERO_API = 'http://localhost:23119/api/';

export const ZOTERO_UNAVAILABLE =
  'Zotero did not answer. Start Zotero 7, and in its Settings, under Advanced, turn on "Allow other applications on this computer to communicate with Zotero".';

export function zoteroSearchUrl(query: string): string {
  const q = query.trim();
  return `${ZOTERO_API}users/0/items/top?format=csljson&limit=50${q ? `&q=${encodeURIComponent(q)}` : ''}`;
}

async function get(url: string): Promise<{ status?: number; text?: string; error?: string }> {
  // Loaded here, not on import, so that the parsers can be used where there is no window.
  const { desktop } = await import('../desktop');
  if (desktop.zoteroGet) return desktop.zoteroGet(url);

  try {
    const response = await fetch(url);
    return { status: response.status, text: await response.text() };
  } catch (error) {
    return { error: String(error) };
  }
}

/** Items in the user's Zotero library that match a search, as sources; or why there are none. */
export async function searchZotero(query: string): Promise<{ sources: Source[]; error?: string }> {
  const answer = await get(zoteroSearchUrl(query));
  if (answer.error || answer.status === undefined) return { sources: [], error: ZOTERO_UNAVAILABLE };
  if (answer.status === 403) return { sources: [], error: ZOTERO_UNAVAILABLE };
  if (answer.status !== 200) return { sources: [], error: `Zotero answered with an error (${answer.status}).` };

  try {
    const data = JSON.parse(answer.text ?? '') as unknown;
    const items = Array.isArray(data) ? data : ((data as { items?: unknown[] })?.items ?? []);
    return { sources: items.filter((x): x is Record<string, unknown> => !!x && typeof x === 'object').map(cslToSource) };
  } catch {
    return { sources: [], error: 'Zotero sent an answer the editor could not read.' };
  }
}
