// Abbreviations: used before they are defined, or defined more than once. A definition is the
// long form followed by the abbreviation in brackets, "magnetic resonance imaging (MRI)", where
// the long form's words start with the abbreviation's letters.

import { type Finding, type Spot, wordsOf } from './types';

const ABBREVIATION = /^(?=(?:[^A-Z]*[A-Z]){2})[A-Z][A-Za-z0-9&]{0,8}[A-Z0-9]$/;
const ROMAN = /^[IVXLCDM]+$/;
const DEFINED = /\(\s*([A-Z][A-Za-z0-9&]{0,8}[A-Z0-9])(s?)\s*\)/g;
const SKIP = new Set(['of', 'the', 'and', 'for', 'in', 'on', 'a', 'an', 'to', 'with', 'by', 'der', 'die', 'das', 'und', 'für', 'von']);

interface Definition {
  abbr: string;
  long: string;
  /** From the long form's first word to the closing bracket. */
  spot: Spot;
  /** Just the abbreviation inside the brackets. */
  inner: Spot;
}

const before = (a: Spot, b: Spot) => a.para < b.para || (a.para === b.para && a.from < b.from);

/** The long form in front of "(ABC)" at `open`, or null when the words there do not fit. */
function longForm(text: string, open: number, abbr: string): { from: number; long: string } | null {
  const words = wordsOf(text.slice(0, open)).slice(-(abbr.length + 4));
  const letters = abbr.replace(/[^A-Z]/g, '').length;
  let best: { from: number; long: string; score: number } | null = null;

  for (let i = words.length - 1; i >= 0; i--) {
    if (words[i].word[0].toLowerCase() !== abbr[0].toLowerCase()) continue;

    const run = words.slice(i);
    // Hyphenated words give a letter for each part: "time-of-flight" is TOF.
    const counted = run.flatMap((w) => w.word.split('-')).filter((w) => !SKIP.has(w.toLowerCase())).length;
    const score = Math.abs(counted - letters);

    if (!best || score < best.score) best = { from: words[i].from, long: text.slice(words[i].from, open).trim(), score };
  }

  return best && best.score <= 2 ? { from: best.from, long: best.long } : null;
}

export function abbreviationProblems(paragraphs: string[]): Finding[] {
  const definitions = new Map<string, Definition[]>();
  const uses = new Map<string, Spot[]>();

  paragraphs.forEach((text, para) => {
    const inside = new Set<number>();

    for (const m of text.matchAll(DEFINED)) {
      const abbr = m[1];
      if (!ABBREVIATION.test(abbr) || ROMAN.test(abbr)) continue;

      const found = longForm(text, m.index, abbr);
      if (!found) continue;

      const at = m.index + m[0].indexOf(abbr);
      inside.add(at);

      const list = definitions.get(abbr) ?? [];
      list.push({
        abbr,
        long: found.long,
        spot: { para, from: found.from, to: m.index + m[0].length, text: text.slice(found.from, m.index + m[0].length) },
        inner: { para, from: at, to: at + abbr.length, text: abbr },
      });
      definitions.set(abbr, list);
    }

    for (const w of wordsOf(text)) {
      const abbr = w.word.replace(/s$/, '');
      const name = ABBREVIATION.test(w.word) && !ROMAN.test(w.word) ? w.word : ABBREVIATION.test(abbr) ? abbr : null;
      if (!name || inside.has(w.from)) continue;

      uses.set(name, [...(uses.get(name) ?? []), { para, from: w.from, to: w.from + name.length, text: name }]);
    }
  });

  const findings: Finding[] = [];

  for (const [abbr, defs] of definitions) {
    const first = defs[0];
    const early = (uses.get(abbr) ?? []).filter((u) => before(u, first.spot));

    if (early.length) {
      const use = early[0];

      findings.push({
        kind: 'abbrev',
        title: `${abbr} is used before it is defined`,
        detail: `“${abbr}” first appears before its definition, “${first.long} (${abbr})”. Define an abbreviation where it is first used.`,
        spots: [use, first.spot],
        fix: [
          { ...use, insert: `${first.long} (${abbr})` },
          { ...first.spot, insert: abbr },
        ],
      });
    }

    for (const again of defs.slice(1)) {
      const same = again.long.toLowerCase() === first.long.toLowerCase();

      findings.push({
        kind: 'abbrev',
        title: `${abbr} is defined again`,
        detail: same
          ? `“${abbr}” was already defined earlier. After the first definition, the abbreviation alone is enough.`
          : `“${abbr}” was already defined earlier as “${first.long}”, here as “${again.long}”. One abbreviation should mean one thing.`,
        spots: [again.spot, first.spot],
        fix: same ? [{ ...again.spot, insert: abbr }] : undefined,
      });
    }
  }

  return findings.sort((a, b) => a.spots[0].para - b.spots[0].para || a.spots[0].from - b.spots[0].from);
}
