// SEQ numbering (Figure 1, Table 2, ...), headings' outline levels, and number formats.

import type { Node as PMNode } from 'prosemirror-model';
import type { DocContext } from '../docx/import';
import type { Styles } from '../docx/styles';
import { child } from '../docx/xml';
import { schema } from '../editor/schema';
import { parseInstr, scanFields } from './model';

const levelCache = new WeakMap<Styles, Map<string, number | null>>();

/** A paragraph's outline level, 0 for a Heading 1; null for body text. Its own setting, or its style's. */
export function outlineLevel(ctx: DocContext, node: PMNode, ownOnly = false): number | null {
  if (node.type !== schema.nodes.paragraph) return null;

  const own = /<w:outlineLvl\b[^>]*\bw:val="(\d+)"/.exec(node.attrs.ppr ?? '');
  if (own) return Number(own[1]) < 9 ? Number(own[1]) : null;
  if (ownOnly) return null;

  const styles = ctx.styles;
  const id = node.attrs.styleId ?? styles.defaultParagraph ?? '';
  let cache = levelCache.get(styles);
  if (!cache) levelCache.set(styles, (cache = new Map()));

  const key = `${styles.version}|${id}`;
  if (cache.has(key)) return cache.get(key)!;

  let level: number | null = null;
  const chain = styles.chain(id);

  for (let i = chain.length - 1; i >= 0; i--) {
    const value = child(chain[i].pPr, 'w:outlineLvl')?.attrs['w:val'];
    if (value !== undefined) {
      level = Number(value) < 9 ? Number(value) : null;
      break;
    }
  }

  // A heading style a file defines without an outline level still counts, by its built-in name.
  if (level === null && chain.length) {
    const named = /^heading ([1-9])$/i.exec(chain[chain.length - 1].name);
    if (named) level = Number(named[1]) - 1;
  }

  cache.set(key, level);
  return level;
}

/** The numbers each SEQ field shows, by the field's position, counted as Word counts them. */
export function seqNumbers(doc: PMNode, ctx: DocContext): Map<number, number> {
  const numbers = new Map<number, number>();
  const seqs = scanFields(doc).fields.filter((field) => field.type === 'SEQ');
  if (!seqs.length) return numbers;

  // Headings, for `\s`: how many headings of each level come before a position.
  const headings: { pos: number; level: number }[] = [];
  const needsHeadings = seqs.some((field) => /\\s/i.test(field.instr));

  if (needsHeadings) {
    doc.descendants((node, pos) => {
      if (node.type !== schema.nodes.paragraph) return !node.isInline;

      const level = outlineLevel(ctx, node);
      if (level !== null) headings.push({ pos, level });
      return false;
    });
  }

  const counters = new Map<string, number>();
  const resetMark = new Map<string, number>();
  let h = 0;
  const seen = new Array<number>(9).fill(0);

  for (const field of seqs) {
    while (h < headings.length && headings[h].pos < field.from) seen[headings[h++].level]++;

    const instr = parseInstr(field.instr, 'rs');
    const id = (instr.args[0] ?? '').toLowerCase();
    let value = counters.get(id) ?? 0;
    const reset = instr.switches.get('r');
    const atLevel = instr.switches.get('s');

    if (typeof atLevel === 'string' && Number(atLevel) >= 1) {
      const upTo = Math.min(9, Number(atLevel));
      const mark = seen.slice(0, upTo).reduce((a, b) => a + b, 0);
      if (resetMark.has(id) && resetMark.get(id) !== mark) value = 0;
      resetMark.set(id, mark);
    }

    if (typeof reset === 'string' && /^\d+$/.test(reset)) value = Number(reset);
    else if (!instr.switches.has('c')) value++;

    counters.set(id, value);
    numbers.set(field.from, value);
  }

  return numbers;
}

function roman(n: number): string {
  if (n <= 0 || n >= 4000) return String(n);

  const table: [number, string][] = [
    [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'], [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'], [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I'],
  ];
  let out = '';

  for (const [value, letters] of table) {
    while (n >= value) {
      out += letters;
      n -= value;
    }
  }

  return out;
}

/** Word's letters: A to Z, then AA to ZZ, then AAA... */
function alphabetic(n: number): string {
  if (n <= 0) return String(n);
  const letter = String.fromCharCode(65 + ((n - 1) % 26));
  return letter.repeat(Math.floor((n - 1) / 26) + 1);
}

/** A number in the format a field's `\*` switches ask for: ARABIC, ROMAN, roman, ALPHABETIC, alphabetic. */
export function formatNumber(n: number, formats: readonly string[]): string {
  for (const format of formats) {
    switch (format) {
      case 'ROMAN':
        return roman(n);
      case 'roman':
        return roman(n).toLowerCase();
      case 'ALPHABETIC':
        return alphabetic(n);
      case 'alphabetic':
        return alphabetic(n).toLowerCase();
      case 'Arabic':
      case 'ARABIC':
        return String(n);
    }
  }

  return String(n);
}

/** Text in the case a field's `\*` switches ask for: Upper, Lower, FirstCap, Caps. */
export function formatText(text: string, formats: readonly string[]): string {
  for (const format of formats) {
    switch (format.toLowerCase()) {
      case 'upper':
        return text.toUpperCase();
      case 'lower':
        return text.toLowerCase();
      case 'firstcap':
        return text.charAt(0).toUpperCase() + text.slice(1);
      case 'caps':
        return text.replace(/(^|\s)(\S)/g, (_m, space: string, letter: string) => space + letter.toUpperCase());
    }
  }

  return text;
}
