// The equation node: its OMML as it came (or as the equation editor wrote it), drawn as MathML.
//
// The XML is the whole truth: export writes it back as it stands, so an equation nobody edited
// goes back byte for byte. `display` says it is an `m:oMathPara`, an equation on a line of its own.

import type { NodeSpec } from 'prosemirror-model';
import { ommlToMathML } from './mathml';
import { M_NS } from './omml';

const cache = new Map<string, string>();

/** The inside of an equation's element: one `<math>` per line, as HTML source. */
export function mathHtml(raw: string): string {
  let html = cache.get(raw);

  if (html === undefined) {
    const rendered = ommlToMathML(raw);
    html = rendered.lines.join('');
    if (cache.size > 2000) cache.clear();
    cache.set(raw, html);
  }

  return html;
}

const alignOf = (raw: string): string => /<m:jc m:val="(left|right)"/.exec(raw.slice(0, 400))?.[1] ?? 'center';

export const mathNodeSpec: NodeSpec = {
  inline: true,
  group: 'inline',
  atom: true,
  selectable: true,
  draggable: true,
  attrs: { raw: { default: '' }, display: { default: false } },
  parseDOM: [
    {
      tag: 'span.math-eq[data-omml]',
      getAttrs: (dom) => {
        const raw = (dom as HTMLElement).dataset.omml ?? '';
        return /^<m:oMath/.test(raw) ? { raw, display: raw.startsWith('<m:oMathPara') } : false;
      },
    },
  ],
  toDOM: (node) => {
    const dom = document.createElement('span');
    dom.className = node.attrs.display ? 'math-eq math-display' : 'math-eq';
    dom.contentEditable = 'false';
    dom.dataset.omml = node.attrs.raw;
    dom.title = 'Double-click to edit the equation';
    if (node.attrs.display) dom.style.textAlign = alignOf(node.attrs.raw);
    dom.innerHTML = mathHtml(node.attrs.raw);
    return dom;
  },
};

/**
 * An equation's XML as it goes into a part. A part whose root does not declare the math namespace
 * (one this editor started, say) gets it declared on the equation itself; otherwise the XML goes
 * back exactly as it stands.
 */
export function ommlForPart(raw: string, rootHead: string): string {
  if (rootHead.includes('xmlns:m=') || /^<m:oMath(?:Para)?\b[^>]*\sxmlns:m=/.test(raw)) return raw;
  return raw.replace(/^<(m:oMath(?:Para)?)\b/, `<$1 xmlns:m="${M_NS}"`);
}
