// Making a note: a reference at the cursor and a new, empty note it refers to.

import type { Node as PMNode } from 'prosemirror-model';
import type { EditorState, Transaction } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { type Note, type NoteKind, emptyNoteDoc, notesOf, refNode, refsIn } from './model';

/**
 * Puts a reference to a new note at the cursor, or after the selection. `content`
 * fills the note after its number, a citation's text say.
 */
export function insertNote(state: EditorState, ctx: DocContext, kind: NoteKind, content?: (note: Note) => PMNode[]): { tr: Transaction; note: Note } {
  const store = notesOf(ctx);
  const note = store.create(kind);

  if (content) note.doc = emptyNoteDoc(ctx, kind, content(note));

  // After a selection, as Word puts it: the selected words are what the note is about.
  const tr = state.tr.insert(state.selection.to, refNode(ctx, kind, note.id));

  return { tr: tr.scrollIntoView(), note };
}

/**
 * A reference copied and pasted refers to the same note as the one it was copied from; Word makes
 * the copy a note of its own, with the same content. Returns the transaction that does so, if any.
 */
export function splitDuplicateRefs(state: EditorState, ctx: DocContext): Transaction | null {
  const store = notesOf(ctx);
  const seen = new Set<string>();
  let tr: Transaction | null = null;

  for (const ref of refsIn(state.doc)) {
    const key = `${ref.kind}:${ref.id}`;
    const note = store.get(ref.kind, ref.id);

    if (!seen.has(key) || !note || note.type !== null) {
      seen.add(key);
      continue;
    }

    const copy = store.create(ref.kind);
    copy.doc = store.docOf(note).copy(store.docOf(note).content);

    const node = state.doc.nodeAt(ref.pos);
    if (!node) continue;

    const raw = (node.attrs.raw as string).replace(/\bw:id="-?\d+"/, `w:id="${copy.id}"`);
    tr ??= state.tr;
    tr.setNodeMarkup(ref.pos, undefined, { ...node.attrs, raw });
  }

  return tr;
}
