// A chart as the editor holds it: its kind, its title, and the sheet its numbers come from.
//
// The sheet is laid out the way Word lays out a chart's own workbook. The first row names the
// series, the first column names the categories, and the numbers are in between:
//
//             Series 1   Series 2
//   January        4.3        2.4
//   February       2.5        4.4
//
// For a scatter chart the first column holds the x values. A pie shows the first series only.

import { CellError, type Value, evaluateSheet } from './formula';

export type ChartKind = 'column' | 'bar' | 'line' | 'area' | 'pie' | 'scatter';

export const KINDS: { id: ChartKind; label: string }[] = [
  { id: 'column', label: 'Column' },
  { id: 'bar', label: 'Bar' },
  { id: 'line', label: 'Line' },
  { id: 'area', label: 'Area' },
  { id: 'pie', label: 'Pie' },
  { id: 'scatter', label: 'Scatter' },
];

export interface ChartSpec {
  kind: ChartKind;
  title: string;
  /** Column, bar and area charts: the series on top of each other, not side by side. */
  stacked: boolean;
  legend: boolean;
  /** The sheet, each cell as typed: a number as a program writes it, text, or "=" and a formula. */
  cells: string[][];
  /** #RRGGBB for each series, or for each slice of a pie. '' or missing: the palette's colour. */
  colors: string[];
}

export interface Series {
  name: string;
  values: (number | null)[];
}

/** What a chart draws, worked out from its sheet. */
export interface ChartData {
  categories: string[];
  /** The first column as numbers: a scatter chart's x values. */
  xs: (number | null)[];
  series: Series[];
}

/** Office's accent colours, and their darker turns for a seventh series and beyond. */
export const PALETTE = [
  '#4472C4', '#ED7D31', '#A5A5A5', '#FFC000', '#5B9BD5', '#70AD47', '#264478', '#9E480E', '#636363', '#997300', '#255E91', '#43682B',
];

export const MAX_ROWS = 200;
export const MAX_COLS = 26;

export const isColor = (value: unknown): value is string => typeof value === 'string' && /^#[0-9A-Fa-f]{6}$/.test(value);

/** The colour of series (or slice) `index`. */
export function colorOf(spec: ChartSpec, index: number): string {
  const own = spec.colors[index];
  return isColor(own) ? own.toUpperCase() : PALETTE[index % PALETTE.length];
}

/** Whether the kind has a stacked form. */
export const canStack = (kind: ChartKind): boolean => kind === 'column' || kind === 'bar' || kind === 'area';

/** The sheet without the empty rows and columns after its last filled cell. */
export function trimCells(cells: readonly (readonly string[])[]): string[][] {
  let rows = 0;
  let cols = 0;

  cells.forEach((row, r) => {
    row.forEach((cell, c) => {
      if (cell !== '') {
        rows = Math.max(rows, r + 1);
        cols = Math.max(cols, c + 1);
      }
    });
  });

  return Array.from({ length: rows }, (_row, r) => Array.from({ length: cols }, (_cell, c) => cells[r]?.[c] ?? ''));
}

/** A value as a category's or a series' name. Numbers are written plainly: 2024, not 2,024. */
function label(value: Value): string {
  if (value === null) return '';
  if (value instanceof CellError) return value.code;
  if (typeof value === 'boolean') return value ? 'TRUE' : 'FALSE';

  return String(value);
}

export function dataOf(spec: ChartSpec): ChartData {
  const cells = trimCells(spec.cells);
  const values = evaluateSheet(cells);
  const rows = cells.length;
  const cols = cells[0]?.length ?? 0;
  const number = (value: Value) => (typeof value === 'number' && Number.isFinite(value) ? value : null);
  const categories: string[] = [];
  const xs: (number | null)[] = [];
  const series: Series[] = [];

  for (let r = 1; r < rows; r++) {
    categories.push(label(values[r][0]));
    xs.push(number(values[r][0]));
  }

  for (let c = 1; c < cols; c++) {
    series.push({
      name: label(values[0][c]) || `Series ${c}`,
      values: Array.from({ length: rows - 1 }, (_value, i) => number(values[i + 1][c])),
    });
  }

  return { categories, xs, series };
}

/** Whether there is anything to draw: a series with at least one number in it. */
export function hasData(data: ChartData): boolean {
  return data.series.some((one) => one.values.some((value) => value !== null));
}

/** Whether two charts would draw the same marks, give or take the last digits of a number. */
export function sameData(a: ChartData, b: ChartData): boolean {
  const close = (x: number | null, y: number | null) => x === y || (x !== null && y !== null && Math.abs(x - y) <= 1e-9 * Math.max(1, Math.abs(x), Math.abs(y)));

  return (
    a.categories.length === b.categories.length &&
    a.series.length === b.series.length &&
    a.categories.every((name, i) => name === b.categories[i]) &&
    a.series.every((one, i) => one.name === b.series[i].name && one.values.every((value, k) => close(value, b.series[i].values[k])))
  );
}

/** The chart a new one starts as: Word's own sample numbers. */
export function sampleSpec(): ChartSpec {
  return {
    kind: 'column',
    title: '',
    stacked: false,
    legend: true,
    cells: [
      ['', 'Series 1', 'Series 2', 'Series 3'],
      ['Category 1', '4.3', '2.4', '2'],
      ['Category 2', '2.5', '4.4', '2'],
      ['Category 3', '3.5', '1.8', '3'],
      ['Category 4', '4.5', '2.8', '5'],
    ],
    colors: [],
  };
}

/** The chart as the text a document node carries. Two charts that are the same give the same text. */
export function specJson(spec: ChartSpec): string {
  const colors = spec.colors.map((color) => (isColor(color) ? color.toUpperCase() : ''));

  while (colors.length && !colors[colors.length - 1]) colors.pop();

  return JSON.stringify({
    kind: spec.kind,
    title: spec.title,
    stacked: spec.stacked && canStack(spec.kind),
    legend: spec.legend,
    cells: trimCells(spec.cells),
    colors,
  });
}

/** Reads that text back. Null for anything that is not a chart, whoever put it on the clipboard. */
export function parseSpec(json: unknown): ChartSpec | null {
  if (typeof json !== 'string' || !json) return null;

  try {
    const read = JSON.parse(json) as Partial<ChartSpec> | null;

    if (!read || !KINDS.some((kind) => kind.id === read.kind) || !Array.isArray(read.cells) || read.cells.length > MAX_ROWS) return null;
    if (!read.cells.every((row) => Array.isArray(row) && row.length <= MAX_COLS && row.every((cell) => typeof cell === 'string'))) return null;

    return {
      kind: read.kind!,
      title: typeof read.title === 'string' ? read.title : '',
      stacked: read.stacked === true,
      legend: read.legend !== false,
      cells: read.cells.map((row) => [...row]),
      colors: Array.isArray(read.colors) ? read.colors.map((color) => (isColor(color) ? color.toUpperCase() : '')) : [],
    };
  } catch {
    return null;
  }
}

// ---- Numbers as people write them ----------------------------------------------------------

let localDecimal: string | null = null;

/** The sign this computer puts before the decimals: a point, or a comma. */
export function decimalSign(): string {
  localDecimal ??= new Intl.NumberFormat().formatToParts(1.5).find((part) => part.type === 'decimal')?.value === ',' ? ',' : '.';
  return localDecimal;
}

/**
 * What was typed into a cell, as the sheet keeps it. A number written the local way (1.234,5 where
 * the comma is the decimal sign) becomes 1234.5; 25% becomes 0.25; everything else stays as typed.
 */
export function storedText(typed: string, decimal = decimalSign()): string {
  const text = typed.trim();
  if (!text || text[0] === '=') return text;

  const percent = text.endsWith('%');
  const body = percent ? text.slice(0, -1).trim() : text;
  const group = decimal === ',' ? '.' : ',';
  const local = new RegExp(`^[+-]?(\\d{1,3}(\\${group}\\d{3})+|\\d+)(\\${decimal}\\d+)?$`);
  let plain: string | null = null;

  if (local.test(body)) plain = body.split(group).join('').replace(decimal, '.');
  else if (/^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(body)) plain = body;
  else if (/^[+-]?\d+,\d+$/.test(body)) plain = body.replace(',', '.');

  if (plain === null) return typed.trim();

  const n = Number(plain) / (percent ? 100 : 1);
  return Number.isFinite(n) ? String(percent ? Number(n.toPrecision(15)) : n) : typed.trim();
}

/** A cell as it is put back into its box for editing: a number with the local decimal sign. */
export function editText(stored: string, decimal = decimalSign()): string {
  return decimal === ',' && /^[+-]?\d+\.\d+$/.test(stored) ? stored.replace('.', ',') : stored;
}

/** A value as a cell shows it. */
export function shownText(value: Value): string {
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return '#NUM!';
    return new Intl.NumberFormat(undefined, { maximumFractionDigits: 6, useGrouping: Math.abs(value) >= 10000 }).format(Number(value.toPrecision(12)));
  }

  return label(value);
}
