// The writing assistant's settings that are lists: style rules (built in and the user's own) and
// writing profiles, with the dialogs that edit them. All of it is kept like the other settings;
// none of it goes into a document.

import { emptyProfile, PROFILE_FIELDS, parseProfiles, type WritingProfile } from '../assist/profiles';
import { BUILT_IN_RULES, patternProblem, type RuleLanguage, type StyleRule } from '../assist/review/style';
import { closePopover, h, store, stored } from './dom';

const RULES_KEY = 'text-studio:assist-rules';
const RULES_OFF_KEY = 'text-studio:assist-rules-off';
const PROFILES_KEY = 'text-studio:assist-profiles';
const LINKS_KEY = 'text-studio:assist-profile-links';

const readJson = <T>(key: string, fallback: T): T => {
  try {
    const value = JSON.parse(stored(key) ?? 'null');
    return value ?? fallback;
  } catch {
    return fallback;
  }
};

const newId = (prefix: string) => `${prefix}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

// ---- Style rules --------------------------------------------------------------------------------

export function ownRules(): StyleRule[] {
  const list = readJson<unknown[]>(RULES_KEY, []);

  return (Array.isArray(list) ? list : [])
    .filter((r): r is StyleRule => !!r && typeof r === 'object' && typeof (r as StyleRule).id === 'string' && typeof (r as StyleRule).pattern === 'string')
    .map((r) => ({
      id: r.id,
      language: (['en', 'de', 'any'] as const).includes(r.language) ? r.language : 'any',
      pattern: r.pattern,
      explanation: String(r.explanation ?? ''),
      suggestion: r.suggestion ? String(r.suggestion) : undefined,
      replace: typeof r.replace === 'string' ? r.replace : undefined,
      own: true,
    }));
}

export const allRules = (): StyleRule[] => [...BUILT_IN_RULES, ...ownRules()];

export function rulesOff(): Set<string> {
  const list = readJson<unknown[]>(RULES_OFF_KEY, []);
  return new Set((Array.isArray(list) ? list : []).filter((id): id is string => typeof id === 'string'));
}

export function setRuleOn(id: string, on: boolean): void {
  const off = rulesOff();

  if (on) off.delete(id);
  else off.add(id);
  store(RULES_OFF_KEY, JSON.stringify([...off]));
}

const saveOwnRules = (rules: StyleRule[]) => store(RULES_KEY, JSON.stringify(rules.map(({ own: _own, ...r }) => r)));

// ---- Profiles -----------------------------------------------------------------------------------

export const profiles = (): WritingProfile[] => parseProfiles(stored(PROFILES_KEY));
const saveProfiles = (list: WritingProfile[]) => store(PROFILES_KEY, JSON.stringify(list));

/** Which profile each document uses, by its path. */
export const profileLinks = (): Record<string, string> => {
  const links = readJson<Record<string, unknown>>(LINKS_KEY, {});
  return Object.fromEntries(Object.entries(links).filter((e): e is [string, string] => typeof e[1] === 'string'));
};

export function linkProfile(path: string, id: string | null): void {
  const links = profileLinks();

  if (id) links[path] = id;
  else delete links[path];
  store(LINKS_KEY, JSON.stringify(links));
}

// ---- Dialogs ------------------------------------------------------------------------------------

/** A dialog with a form in it; resolves when it is closed. */
function dialog(title: string, body: HTMLElement, buttons: HTMLElement[], wide = false): { close(): void; done: Promise<void> } {
  let close = () => {};
  const done = new Promise<void>((resolve) => {
    const backdrop = h('div', { class: 'dialog-backdrop' }, h('div', { class: `dialog assist-dialog${wide ? ' wide' : ''}`, role: 'dialog' }, h('h2', null, title), body, h('div', { class: 'buttons' }, ...buttons)));
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        close();
      }
    };

    close = () => {
      document.removeEventListener('keydown', onKey, true);
      backdrop.remove();
      resolve();
    };

    closePopover();
    document.addEventListener('keydown', onKey, true);
    document.body.append(backdrop);
    (body.querySelector('input, textarea, select') as HTMLElement | null)?.focus();
  });

  return { close: () => close(), done };
}

const labelled = (label: string, field: HTMLElement) => h('label', { class: 'assist-field' }, h('span', null, label), field);
const LANGUAGE_NAMES: Record<RuleLanguage, string> = { en: 'English', de: 'German', any: 'Any language' };

/** Edits one of the user's own rules, or makes a new one. Resolves with the rule, or null. */
function editRule(rule: StyleRule | null): Promise<StyleRule | null> {
  return new Promise((resolve) => {
    const language = h('select', { class: 'tool-select' }, ...(Object.keys(LANGUAGE_NAMES) as RuleLanguage[]).map((l) => h('option', { value: l }, LANGUAGE_NAMES[l])));
    const pattern = h('textarea', { class: 'field', rows: '3', spellcheck: 'false', placeholder: 'stell* ... dar\ndarstell*|dargestellt*' });
    const explanation = h('input', { class: 'field', placeholder: 'Why it is worth changing' });
    const suggestion = h('input', { class: 'field', placeholder: 'What to write instead (advice)' });
    const replace = h('input', { class: 'field', placeholder: 'Replacement offered as a fix (patterns without gaps only)' });
    const problem = h('div', { class: 'assist-hint bad' });
    let result: StyleRule | null = null;

    language.value = rule?.language ?? 'any';
    pattern.value = rule?.pattern ?? '';
    explanation.value = rule?.explanation ?? '';
    suggestion.value = rule?.suggestion ?? '';
    replace.value = rule?.replace ?? '';

    const save = () => {
      const why = patternProblem(pattern.value);
      if (why) return void (problem.textContent = why);
      if (!explanation.value.trim()) return void (problem.textContent = 'Say why the structure is worth avoiding.');

      result = {
        id: rule?.id ?? newId('own'),
        language: language.value as RuleLanguage,
        pattern: pattern.value.trim(),
        explanation: explanation.value.trim(),
        suggestion: suggestion.value.trim() || undefined,
        replace: replace.value.trim() ? replace.value.trim() : undefined,
        own: true,
      };
      d.close();
    };

    const d = dialog(
      rule ? 'Edit rule' : 'New rule',
      h(
        'div',
        { class: 'assist-form' },
        labelled('Language', language),
        labelled('Pattern, one form per line', pattern),
        h('div', { class: 'assist-hint' }, 'Words in any case. stell* = any word starting “stell”; a|b = either; !a|b = any word but these; @ = any one word; ... or ...4 = up to 8 (or 4) words within the sentence; ^ first = at the start of a sentence.'),
        labelled('Why', explanation),
        labelled('Instead', suggestion),
        labelled('Replacement', replace),
        problem,
      ),
      [h('button', { class: 'button primary', onclick: save }, 'Save'), h('button', { class: 'button', onclick: () => d.close() }, 'Cancel')],
    );

    void d.done.then(() => resolve(result));
  });
}

/** The rule manager: every rule with a switch, and the user's own to add, edit and delete. */
export async function manageRules(onChange: () => void): Promise<void> {
  const list = h('div', { class: 'assist-rules' });

  const render = () => {
    const off = rulesOff();

    list.replaceChildren(
      ...allRules().map((rule) => {
        const toggle = h('input', { type: 'checkbox', checked: !off.has(rule.id), title: 'Check for this' });

        toggle.addEventListener('change', () => (setRuleOn(rule.id, toggle.checked), onChange()));

        return h(
          'div',
          { class: 'assist-rule' },
          toggle,
          h(
            'div',
            { class: 'assist-rule-text' },
            h('code', null, rule.pattern.split('\n')[0]),
            h('span', { class: 'assist-hint' }, `${LANGUAGE_NAMES[rule.language]}${rule.own ? ' · your rule' : ''} · ${rule.explanation}`),
          ),
          rule.own && h('button', { class: 'button small', onclick: () => void edit(rule) }, 'Edit'),
          rule.own && h('button', { class: 'button small', onclick: () => remove(rule) }, 'Delete'),
        );
      }),
    );
  };

  const edit = async (rule: StyleRule | null) => {
    const changed = await editRule(rule);
    if (!changed) return;

    const own = ownRules();
    const at = own.findIndex((r) => r.id === changed.id);

    if (at >= 0) own[at] = changed;
    else own.push(changed);
    saveOwnRules(own);
    render();
    onChange();
  };

  const remove = (rule: StyleRule) => {
    saveOwnRules(ownRules().filter((r) => r.id !== rule.id));
    render();
    onChange();
  };

  render();

  const d = dialog('Style rules', list, [
    h('button', { class: 'button', onclick: () => void edit(null) }, 'New rule…'),
    h('button', { class: 'button primary', onclick: () => d.close() }, 'Done'),
  ], true);

  await d.done;
}

/** Edits a profile, or makes a new one; resolves with its id, or null when nothing was saved. */
export function editProfile(id: string | null): Promise<string | null> {
  return new Promise((resolve) => {
    const profile = profiles().find((p) => p.id === id) ?? emptyProfile(newId('profile'));
    const name = h('input', { class: 'field', placeholder: 'Master’s thesis', value: profile.name });
    const instruction = h('textarea', { class: 'field', rows: '3', placeholder: 'What should be done with each paragraph? E.g. “Polish it into clear academic English; keep my argument as it is.”' });
    const fields = PROFILE_FIELDS.map((f) => ({ key: f.key, input: h('input', { class: 'field', placeholder: f.placeholder, value: profile[f.key] }), label: f.label }));
    const problem = h('div', { class: 'assist-hint bad' });
    let saved: string | null = null;

    instruction.value = profile.instruction;

    const save = () => {
      if (!name.value.trim()) return void (problem.textContent = 'Give the profile a name.');

      const next: WritingProfile = { ...profile, name: name.value.trim(), instruction: instruction.value.trim() };
      for (const f of fields) next[f.key] = f.input.value.trim();

      const list = profiles();
      const at = list.findIndex((p) => p.id === next.id);

      if (at >= 0) list[at] = next;
      else list.push(next);
      saveProfiles(list);
      saved = next.id;
      d.close();
    };

    const remove = () => {
      saveProfiles(profiles().filter((p) => p.id !== profile.id));
      saved = '';
      d.close();
    };

    const d = dialog(
      id ? 'Edit writing profile' : 'New writing profile',
      h(
        'div',
        { class: 'assist-form' },
        labelled('Name', name),
        labelled('Instruction', instruction),
        h('div', { class: 'assist-hint' }, 'What you say about the work goes with every request about the document: improving, reviewing, summaries and abstracts.'),
        ...fields.map((f) => labelled(f.label, f.input)),
        problem,
      ),
      [
        h('button', { class: 'button primary', onclick: save }, 'Save'),
        id ? h('button', { class: 'button', onclick: remove }, 'Delete') : h('span'),
        h('button', { class: 'button', onclick: () => d.close() }, 'Cancel'),
      ],
      true,
    );

    void d.done.then(() => resolve(saved));
  });
}
