// Writing profiles: what the user tells the assistant about a piece of work ("a master's thesis in
// marine biology on …"), saved under a name. A profile is an aim for Improve writing, and its
// context goes into every request about the document, so that the model judges the text with
// the topic, field and audience in mind.

import type { AssistRequest } from '../desktop';
import { writeRequest } from './prompts';

export interface WritingProfile {
  id: string;
  name: string;
  /** What to do with each paragraph, as in the custom mode. */
  instruction: string;
  /** "Master's thesis", "journal article", "grant proposal". */
  kind: string;
  field: string;
  topic: string;
  audience: string;
  citation: string;
  /** "British English", "Swiss German". */
  variant: string;
  /** Terms to keep as written, one per line or separated by commas. */
  keep: string;
  /** Things to watch for. */
  watch: string;
}

export const PROFILE_FIELDS: { key: Exclude<keyof WritingProfile, 'id' | 'name' | 'instruction'>; label: string; placeholder: string }[] = [
  { key: 'kind', label: 'Type and level', placeholder: 'Master’s thesis' },
  { key: 'field', label: 'Field or discipline', placeholder: 'Marine biology' },
  { key: 'topic', label: 'Topic or research question', placeholder: 'How does warming affect coral spawning?' },
  { key: 'audience', label: 'Readers', placeholder: 'Examiners in the field' },
  { key: 'citation', label: 'Citation style', placeholder: 'APA 7' },
  { key: 'variant', label: 'Language variant', placeholder: 'British English' },
  { key: 'keep', label: 'Terms to keep as written', placeholder: 'zooxanthellae, bleaching threshold' },
  { key: 'watch', label: 'Watch for', placeholder: 'Overclaiming causality; passive voice in the methods' },
];

export function emptyProfile(id: string): WritingProfile {
  return { id, name: '', instruction: '', kind: '', field: '', topic: '', audience: '', citation: '', variant: '', keep: '', watch: '' };
}

const clean = (value: unknown, max = 2000) => (typeof value === 'string' ? value.slice(0, max).trim() : '');

/** Profiles read back from settings, with anything malformed left out. */
export function parseProfiles(json: string | null): WritingProfile[] {
  let list: unknown;

  try {
    list = JSON.parse(json ?? '[]');
  } catch {
    return [];
  }

  if (!Array.isArray(list)) return [];

  return list
    .filter((p): p is Record<string, unknown> => !!p && typeof p === 'object' && typeof p.id === 'string' && typeof p.name === 'string')
    .map((p) => {
      const profile = emptyProfile(clean(p.id, 100));
      for (const key of Object.keys(profile) as (keyof WritingProfile)[]) if (key !== 'id') profile[key] = clean(p[key]);
      return profile;
    })
    .filter((p) => p.id && p.name);
}

/**
 * What the model is told about the work, as sentences for the system prompt; '' for a profile
 * that says nothing about it.
 */
export function profileContext(profile: WritingProfile | null | undefined): string {
  if (!profile) return '';

  const parts: string[] = [];
  const keep = profile.keep.split(/[\n,;]+/).map((t) => t.trim()).filter(Boolean);

  if (profile.kind || profile.field) {
    parts.push(`The document is ${profile.kind ? `a ${profile.kind}` : 'a text'}${profile.field ? ` in ${profile.field}` : ''}.`);
  }
  if (profile.topic) parts.push(`Its topic or research question: ${profile.topic}.`);
  if (profile.audience) parts.push(`It is written for: ${profile.audience}.`);
  if (profile.citation) parts.push(`Citations follow ${profile.citation}; keep them in that style.`);
  if (profile.variant) parts.push(`Use ${profile.variant} spelling and usage.`);
  if (keep.length) parts.push(`Keep these terms exactly as written: ${keep.join(', ')}.`);
  if (profile.watch) parts.push(`Pay particular attention to: ${profile.watch}.`);
  if (profile.field || profile.topic) {
    parts.push('Keep the terminology of the field, and judge the text with its topic in mind: a claim or term that does not fit the field is worth correcting.');
  }

  return parts.length ? `About the work: ${parts.join(' ')}`.replace(/\.\./g, '.') : '';
}

/** Improve writing with a profile as the aim: its instruction, with its context. */
export function profileWriteRequest(model: string, profile: WritingProfile, text: string): AssistRequest {
  const instruction = profile.instruction.trim() || 'Improve its clarity, correctness and register for this kind of work';
  return writeRequest(model, 'custom', text, instruction, profileContext(profile));
}

/** The profile linked to a file, by its path, if it still exists. */
export function profileForFile(links: Record<string, string>, path: string | null | undefined, profiles: WritingProfile[]): WritingProfile | null {
  const id = path ? links[path] : undefined;
  return (id && profiles.find((p) => p.id === id)) || null;
}
