// Drawing a chart, as SVG.
//
// The picture is made to look like the one Word draws from the same chart part (chartxml.ts):
// the same colours, the legend underneath, light gridlines, grey text. It is text, not a canvas,
// so that the page's stylesheet can do with a chart's colours what it does with the document's:
// every fill and line carries its colour in --c, and page.css decides what is shown, which on a
// dark page is that colour with its lightness turned over.

import { escAttr, escText } from '../docx/xml';
import { type ChartData, type ChartSpec, canStack, colorOf, dataOf, hasData } from './model';

interface Box {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
}

interface Scale {
  min: number;
  max: number;
  ticks: number[];
}

const round = (n: number) => Math.round(n * 100) / 100;

/** How wide a text comes out, near enough to lay a chart out by. Nothing here can measure it. */
const widthOf = (text: string, size: number) => text.length * size * 0.54;

// Each mark says its colour twice: in --c for the page's stylesheet, and as a plain attribute for
// wherever the picture goes without that stylesheet (another program's clipboard, say).
const paint = (hex: string) => `style="--c:${hex}" fill="${hex}"`;
const ink = (hex: string) => `style="--c:${hex}" stroke="${hex}"`;

function label(x: number, y: number, text: string, size: number, anchor: 'start' | 'middle' | 'end', cls = 'ct'): string {
  return `<text class="${cls}" fill="#595959" x="${round(x)}" y="${round(y)}" font-size="${round(size)}" text-anchor="${anchor}">${escText(text)}</text>`;
}

/** A text cut short to fit a width, with an ellipsis where it was cut. */
function fitted(text: string, size: number, room: number): string {
  if (widthOf(text, size) <= room) return text;

  const keep = Math.max(1, Math.floor(room / (size * 0.54)) - 1);
  return `${text.slice(0, keep).trimEnd()}…`;
}

/** A number on an axis: as short as the step between ticks allows. */
function tickText(value: number, step: number): string {
  // The step's own decimals: 2.5 has one, 0.25 two, 20 none.
  const digits = step >= 1e-6 ? Math.min(8, (String(Number(step.toPrecision(6))).split('.')[1] ?? '').length) : 8;

  return new Intl.NumberFormat(undefined, { minimumFractionDigits: digits, maximumFractionDigits: digits }).format(value);
}

/**
 * An axis for values from `low` to `high`: round numbers a round step apart. Like Excel, it
 * starts at zero unless the values sit in a narrow band far from it.
 */
function scaleFor(low: number, high: number, wanted: number, fromZero: boolean): Scale {
  let min = Math.min(low, high);
  let max = Math.max(low, high);

  if (!Number.isFinite(min) || !Number.isFinite(max)) [min, max] = [0, 1];

  if (fromZero || (min > 0 && (max - min) / max > 1 / 6)) min = Math.min(min, 0);
  if (fromZero || (max < 0 && (max - min) / -min > 1 / 6)) max = Math.max(max, 0);
  if (min === max) [min, max] = min === 0 ? [0, 1] : min > 0 ? [0, max] : [min, 0];

  const rough = (max - min) / Math.max(2, wanted);
  const power = 10 ** Math.floor(Math.log10(rough));
  const step = [1, 2, 5, 10].map((m) => m * power).find((s) => s >= rough - 1e-12) ?? power * 10;
  const first = Math.floor(min / step + 1e-9) * step;
  const last = Math.ceil(max / step - 1e-9) * step;
  const ticks: number[] = [];

  for (let i = 0; first + i * step <= last + step * 1e-6; i++) ticks.push(Number((first + i * step).toPrecision(12)));

  return { min: first, max: last, ticks };
}

const stepOf = (scale: Scale) => (scale.ticks.length > 1 ? scale.ticks[1] - scale.ticks[0] : 1);

// ---- The parts of a chart ------------------------------------------------------------------

/** The legend, centred along the bottom, on as many lines as it needs. Returns what it drew and how tall it is. */
function legend(names: string[], colors: string[], lines: boolean, width: number, bottom: number, size: number): { svg: string; height: number } {
  const mark = size * 0.75;
  const gap = size * 1.4;
  const room = width - 24;
  const items = names.map((name) => fitted(name, size, room - mark - 6));
  const widths = items.map((name) => mark + 5 + widthOf(name, size));
  const rows: number[][] = [[]];
  let used = 0;

  widths.forEach((w, i) => {
    const row = rows[rows.length - 1];

    if (row.length && used + gap + w > room) {
      rows.push([i]);
      used = w;
    } else {
      used += (row.length ? gap : 0) + w;
      row.push(i);
    }
  });

  const lineHeight = size * 1.55;
  const shown = rows.slice(0, 4);
  const height = shown.length * lineHeight;
  let svg = '';

  shown.forEach((row, r) => {
    const total = row.reduce((sum, i) => sum + widths[i], 0) + gap * (row.length - 1);
    const y = bottom - height + r * lineHeight + lineHeight / 2;
    let x = (width - total) / 2;

    for (const i of row) {
      svg += lines
        ? `<line class="cs" ${ink(colors[i])} x1="${round(x - 2)}" y1="${round(y)}" x2="${round(x + mark + 2)}" y2="${round(y)}" stroke-width="2.25"/>` +
          `<circle class="cf" ${paint(colors[i])} cx="${round(x + mark / 2)}" cy="${round(y)}" r="${round(mark / 3)}"/>`
        : `<rect class="cf" ${paint(colors[i])} x="${round(x)}" y="${round(y - mark / 2)}" width="${round(mark)}" height="${round(mark)}"/>`;
      svg += label(x + mark + 5, y + size * 0.35, items[i], size, 'start');
      x += widths[i] + gap;
    }
  });

  return { svg, height };
}

/** Columns, bars, lines and areas: categories along one axis, values along the other. */
function categoryChart(spec: ChartSpec, data: ChartData, box: Box, size: number): string {
  const { kind } = spec;
  const sideways = kind === 'bar';
  const stacked = spec.stacked && canStack(kind);
  const count = data.categories.length;
  const series = data.series;
  let low = Infinity;
  let high = -Infinity;

  // What the value axis has to hold: each value, or with stacking the piles above and below zero.
  for (let k = 0; k < count; k++) {
    let up = 0;
    let down = 0;

    for (const one of series) {
      const value = one.values[k];
      if (value === null) continue;

      if (!stacked) {
        low = Math.min(low, value);
        high = Math.max(high, value);
      } else if (value >= 0) {
        up += value;
      } else {
        down += value;
      }
    }

    if (stacked) {
      low = Math.min(low, down);
      high = Math.max(high, up);
    }
  }

  const along = sideways ? box.x1 - box.x0 : box.y1 - box.y0;
  const scale = scaleFor(low, high, Math.max(2, Math.min(8, Math.floor(along / (sideways ? 60 : 34)))), kind !== 'line');
  const step = stepOf(scale);
  const tickTexts = scale.ticks.map((tick) => tickText(tick, step));
  const plot = { ...box };
  let svg = '';

  // Room for the axes' own texts: the numbers on one side, the names on the other.
  if (sideways) {
    const widest = Math.max(0, ...data.categories.map((name) => widthOf(name, size)));

    plot.x0 += Math.min(widest, (box.x1 - box.x0) * 0.32) + 8;
    plot.y1 -= size * 1.7;
    plot.x1 -= widthOf(tickTexts[tickTexts.length - 1] ?? '', size) / 2;
  } else {
    plot.x0 += Math.max(0, ...tickTexts.map((text) => widthOf(text, size))) + 8;
    plot.y1 -= size * 1.7;
    plot.y0 += size * 0.5;
  }

  const width = Math.max(10, plot.x1 - plot.x0);
  const height = Math.max(10, plot.y1 - plot.y0);
  const span = scale.max - scale.min || 1;
  /** Where a value falls along the value axis, in pixels. */
  const at = (value: number) => (sideways ? plot.x0 + ((value - scale.min) / span) * width : plot.y1 - ((value - scale.min) / span) * height);
  const band = (sideways ? height : width) / Math.max(1, count);
  /** The start of category k's band. Sideways, the first category is at the bottom, as Word has it. */
  const bandStart = (k: number) => (sideways ? plot.y1 - (k + 1) * band : plot.x0 + k * band);
  const zero = at(Math.max(scale.min, Math.min(scale.max, 0)));

  scale.ticks.forEach((tick, i) => {
    const p = round(at(tick));

    if (sideways) {
      svg += `<line class="cg" stroke="#D9D9D9" x1="${p}" y1="${round(plot.y0)}" x2="${p}" y2="${round(plot.y1)}"/>`;
      svg += label(p, plot.y1 + size * 1.25, tickTexts[i], size, 'middle');
    } else {
      svg += `<line class="cg" stroke="#D9D9D9" x1="${round(plot.x0)}" y1="${p}" x2="${round(plot.x1)}" y2="${p}"/>`;
      svg += label(plot.x0 - 6, p + size * 0.35, tickTexts[i], size, 'end');
    }
  });

  // Category names: every one if they fit, else every second, third, ...
  if (sideways) {
    const every = Math.max(1, Math.ceil((size * 1.25) / band));

    data.categories.forEach((name, k) => {
      if (k % every === 0) svg += label(plot.x0 - 6, bandStart(k) + band / 2 + size * 0.35, fitted(name, size, plot.x0 - box.x0 - 8), size, 'end');
    });
  } else {
    const widest = Math.max(0, ...data.categories.map((name) => widthOf(name, size)));
    const every = Math.max(1, Math.ceil((Math.min(widest, 120) + 8) / band));

    data.categories.forEach((name, k) => {
      if (k % every === 0) svg += label(bandStart(k) + band / 2, plot.y1 + size * 1.25, fitted(name, size, Math.max(band * every - 6, 24)), size, 'middle');
    });
  }

  if (kind === 'column' || kind === 'bar') {
    // The gap between two groups is one and a half bars wide: gapWidth 150 in the chart part.
    const bars = stacked ? 1 : series.length;
    const thick = band / (bars + 1.5);

    for (let k = 0; k < count; k++) {
      let up = 0;
      let down = 0;

      series.forEach((one, s) => {
        const value = one.values[k];
        if (value === null || value === 0) return;

        const from = stacked ? (value >= 0 ? up : down) : 0;
        const to = from + value;
        const a = at(Math.max(scale.min, Math.min(scale.max, from)));
        const b = at(Math.max(scale.min, Math.min(scale.max, to)));
        const slot = stacked ? 0 : s;

        if (value >= 0) up = to;
        else down = to;

        if (sideways) {
          const y = bandStart(k) + band - thick * 0.75 - (slot + 1) * thick;
          svg += `<rect class="cf" ${paint(colorOf(spec, s))} x="${round(Math.min(a, b))}" y="${round(y)}" width="${round(Math.abs(b - a))}" height="${round(thick)}"/>`;
        } else {
          const x = bandStart(k) + thick * 0.75 + slot * thick;
          svg += `<rect class="cf" ${paint(colorOf(spec, s))} x="${round(x)}" y="${round(Math.min(a, b))}" width="${round(thick)}" height="${round(Math.abs(b - a))}"/>`;
        }
      });
    }
  } else {
    const x = (k: number) => bandStart(k) + band / 2;
    const totals: number[] = new Array(count).fill(0);
    const layers: string[] = [];

    series.forEach((one, s) => {
      const filled = paint(colorOf(spec, s));
      const stroked = ink(colorOf(spec, s));
      // Stretches of neighbouring points; a cell with no number breaks the line.
      const runs: { k: number; from: number; to: number }[][] = [[]];

      one.values.forEach((value, k) => {
        if (value === null) {
          if (runs[runs.length - 1].length) runs.push([]);
          return;
        }

        const from = stacked ? totals[k] : 0;

        if (stacked) totals[k] += value;
        runs[runs.length - 1].push({ k, from, to: from + value });
      });

      let drawn = '';

      for (const run of runs) {
        if (!run.length) continue;

        if (kind === 'area') {
          const top = run.map((p) => `${round(x(p.k))},${round(at(p.to))}`);
          const base = [...run].reverse().map((p) => `${round(x(p.k))},${round(stacked ? at(p.from) : zero)}`);

          drawn += `<polygon class="cf" ${filled} points="${[...top, ...base].join(' ')}"/>`;
        } else {
          if (run.length > 1) drawn += `<polyline class="cs" ${stroked} fill="none" stroke-width="2.25" points="${run.map((p) => `${round(x(p.k))},${round(at(p.to))}`).join(' ')}"/>`;
          drawn += run.map((p) => `<circle class="cf" ${filled} cx="${round(x(p.k))}" cy="${round(at(p.to))}" r="3"/>`).join('');
        }
      }

      layers.push(drawn);
    });

    // Areas that are not stacked lie over each other in the order of the series, as in Word.
    svg += layers.join('');
  }

  // The line the bars stand on, drawn last so that it is not covered by them.
  svg += sideways
    ? `<line class="ca" stroke="#BFBFBF" x1="${round(zero)}" y1="${round(plot.y0)}" x2="${round(zero)}" y2="${round(plot.y1)}"/>`
    : `<line class="ca" stroke="#BFBFBF" x1="${round(plot.x0)}" y1="${round(zero)}" x2="${round(plot.x1)}" y2="${round(zero)}"/>`;

  return svg;
}

/** Points by two numbers: the first column across, every other column up. */
function scatterChart(spec: ChartSpec, data: ChartData, box: Box, size: number): string {
  const xs = data.xs.filter((x): x is number => x !== null);
  const ys = data.series.flatMap((one) => one.values.filter((y, k): y is number => y !== null && data.xs[k] !== null));
  const xScale = scaleFor(Math.min(...xs), Math.max(...xs), Math.max(2, Math.min(8, Math.floor((box.x1 - box.x0) / 70))), false);
  const yScale = scaleFor(Math.min(...ys), Math.max(...ys), Math.max(2, Math.min(8, Math.floor((box.y1 - box.y0) / 34))), false);
  const xTexts = xScale.ticks.map((tick) => tickText(tick, stepOf(xScale)));
  const yTexts = yScale.ticks.map((tick) => tickText(tick, stepOf(yScale)));
  const plot = {
    x0: box.x0 + Math.max(0, ...yTexts.map((text) => widthOf(text, size))) + 8,
    y0: box.y0 + size * 0.5,
    x1: box.x1 - widthOf(xTexts[xTexts.length - 1] ?? '', size) / 2,
    y1: box.y1 - size * 1.7,
  };
  const px = (x: number) => plot.x0 + ((x - xScale.min) / (xScale.max - xScale.min || 1)) * Math.max(10, plot.x1 - plot.x0);
  const py = (y: number) => plot.y1 - ((y - yScale.min) / (yScale.max - yScale.min || 1)) * Math.max(10, plot.y1 - plot.y0);
  let svg = '';

  xScale.ticks.forEach((tick, i) => {
    svg += `<line class="cg" stroke="#D9D9D9" x1="${round(px(tick))}" y1="${round(plot.y0)}" x2="${round(px(tick))}" y2="${round(plot.y1)}"/>`;
    svg += label(px(tick), plot.y1 + size * 1.25, xTexts[i], size, 'middle');
  });

  yScale.ticks.forEach((tick, i) => {
    svg += `<line class="cg" stroke="#D9D9D9" x1="${round(plot.x0)}" y1="${round(py(tick))}" x2="${round(plot.x1)}" y2="${round(py(tick))}"/>`;
    svg += label(plot.x0 - 6, py(tick) + size * 0.35, yTexts[i], size, 'end');
  });

  data.series.forEach((one, s) => {
    one.values.forEach((y, k) => {
      const x = data.xs[k];
      if (x !== null && y !== null) svg += `<circle class="cf" ${paint(colorOf(spec, s))} cx="${round(px(x))}" cy="${round(py(y))}" r="3.3"/>`;
    });
  });

  return svg;
}

/** The first series as slices of a circle, clockwise from the top. A pie has no use for a sign: -3 is a slice of 3. */
function pieChart(spec: ChartSpec, data: ChartData, box: Box): string {
  const values = (data.series[0]?.values ?? []).map((value) => Math.abs(value ?? 0));
  const total = values.reduce((sum, value) => sum + value, 0);
  const cx = (box.x0 + box.x1) / 2;
  const cy = (box.y0 + box.y1) / 2;
  const r = Math.max(4, Math.min(box.x1 - box.x0, box.y1 - box.y0) / 2 - 4);
  let turned = 0;
  let svg = '';

  if (total <= 0) return '';

  values.forEach((value, k) => {
    if (value <= 0) return;

    const from = (turned / total) * 2 * Math.PI;
    const to = ((turned + value) / total) * 2 * Math.PI;
    const point = (angle: number) => `${round(cx + r * Math.sin(angle))} ${round(cy - r * Math.cos(angle))}`;

    turned += value;

    // A slice that is the whole pie has no two edges to draw an arc between.
    svg +=
      value >= total * 0.999999
        ? `<circle class="cf slice" ${paint(colorOf(spec, k))} cx="${round(cx)}" cy="${round(cy)}" r="${round(r)}"/>`
        : `<path class="cf slice" ${paint(colorOf(spec, k))} d="M${round(cx)} ${round(cy)}L${point(from)}A${round(r)} ${round(r)} 0 ${to - from > Math.PI ? 1 : 0} 1 ${point(to)}Z"/>`;
  });

  return svg;
}

/**
 * The chart as an SVG element, `width` by `height` CSS pixels. A chart with no numbers in it
 * comes out as a frame that says so.
 */
export function chartSvg(spec: ChartSpec, width: number, height: number): string {
  const data = dataOf(spec);
  const w = Math.max(40, Math.round(width));
  const h = Math.max(30, Math.round(height));
  const scale = Math.max(0.7, Math.min(1, w / 400, h / 240));
  const size = 12 * scale;
  const open = `<svg class="chart-svg" xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${escAttr(spec.title || 'Chart')}">`;
  const drawable = hasData(data) && (spec.kind !== 'scatter' || data.xs.some((x, k) => x !== null && data.series.some((one) => one.values[k] !== null)));

  if (!drawable) {
    return `${open}<rect class="cx" fill="none" stroke="#BFBFBF" x="0.5" y="0.5" width="${w - 1}" height="${h - 1}"/>${label(w / 2, h / 2 + 4, 'Chart without numbers', size, 'middle')}</svg>`;
  }

  const box: Box = { x0: 12, y0: 10, x1: w - 14, y1: h - 8 };
  let svg = '';

  if (spec.title.trim()) {
    const titleSize = 18.6 * scale;

    svg += label(w / 2, box.y0 + titleSize, fitted(spec.title.trim(), titleSize, w - 24), titleSize, 'middle', 'ct title');
    box.y0 += titleSize * 1.7;
  }

  if (spec.legend) {
    const pie = spec.kind === 'pie';
    const names = pie ? data.categories : data.series.map((one) => one.name);
    const key = legend(names, names.map((_name, i) => colorOf(spec, i)), spec.kind === 'line', w, box.y1, size);

    svg += key.svg;
    box.y1 -= key.height + 4;
  }

  if (spec.kind === 'pie') svg += pieChart(spec, data, box);
  else if (spec.kind === 'scatter') svg += scatterChart(spec, data, box, size);
  else svg += categoryChart(spec, data, box, size);

  return `${open}${svg}</svg>`;
}
