// Shapes in and out of the .docx.
//
// A shape is read into a `shape` node: its spec (model.ts) as JSON twice, as it is and as it came,
// its text box's content as an editor document in JSON, and the XML it came from. Export writes
// that XML back byte for byte unless something was changed; then it patches in only what was:
// size, place, fill, outline colour, and the text of each `w:txbxContent` (the Word 2010 copy and
// the VML one alike). A shape made here is written as Word 2010's `wps:wsp` with a VML fallback.

import { type Mark, Node as PMNode } from 'prosemirror-model';
import { pxToEmu } from '../docx/props';
import { type XmlEl, child, descendants, escAttr, parseXml, raw } from '../docx/xml';
import { schema } from '../editor/schema';
import { LINE_LIKE } from './geometry';
import { type ShapeSpec, type ThemeColors, mainTextBox, parseStyle, readShape } from './model';

const N = schema.nodes;

export const WPS_NS = 'http://schemas.microsoft.com/office/word/2010/wordprocessingShape';
const MC_NS = 'http://schemas.openxmlformats.org/markup-compatibility/2006';
const WP_NS = 'http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing';
const A_NS = 'http://schemas.openxmlformats.org/drawingml/2006/main';
const V_NS = 'urn:schemas-microsoft-com:vml';
const W10_NS = 'urn:schemas-microsoft-com:office:word';

export const parseShapeSpec = (json: string | null | undefined): ShapeSpec | null => {
  try {
    return json ? (JSON.parse(json) as ShapeSpec) : null;
  } catch {
    return null;
  }
};

/** A text box's content as an editor document. */
export function textDoc(json: string | null | undefined): PMNode | null {
  if (!json) return null;

  try {
    return PMNode.fromJSON(schema, JSON.parse(json));
  } catch {
    return null;
  }
}

export const textJson = (doc: PMNode): string => JSON.stringify(doc.toJSON());

/**
 * A run's `w:drawing`, `mc:AlternateContent` or `w:pict` as a shape node, or null if it is not a
 * shape this reads. `blocks` reads a text box's paragraphs as the document's own are read.
 */
export function shapeNode(el: XmlEl, colors: ThemeColors | undefined, blocks: (children: XmlEl[]) => PMNode[], marks: readonly Mark[]): PMNode | null {
  const spec = readShape(el, colors);
  if (!spec) return null;

  let text: string | null = null;

  if (spec.text) {
    const box = mainTextBox(el);
    const content = box ? blocks(box.children).filter((n) => n.isBlock) : [];

    if (box) text = textJson(N.doc.create(null, content.length ? content : [N.paragraph.create()]));
    else spec.text = false;
  }

  const json = JSON.stringify(spec);
  return N.shape.create({ raw: raw(el), spec: json, orig: json, text, edited: false }, null, marks);
}

// ---- Writing ---------------------------------------------------------------------------------

interface Edit {
  start: number;
  end: number;
  text: string;
}

function applyEdits(src: string, edits: Edit[]): string {
  const sorted = edits.map((e, i) => ({ ...e, i })).sort((a, b) => a.start - b.start || a.i - b.i);
  let out = '';
  let at = 0;

  for (const e of sorted) {
    if (e.start < at) continue; // Overlaps an edit already made: the first one wins.
    out += src.slice(at, e.start) + e.text;
    at = e.end;
  }

  return out + src.slice(at);
}

/** An open tag with one attribute set (added if it was not there), or removed for null. */
function setAttr(tag: string, name: string, value: string | null): string {
  const re = new RegExp(`(\\s${name.replace(':', '\\:')}=)("[^"]*"|'[^']*')`);
  if (re.test(tag)) return value === null ? tag.replace(new RegExp(`\\s${name}=("[^"]*"|'[^']*')`), '') : tag.replace(re, `$1"${escAttr(value)}"`);
  if (value === null) return tag;

  const close = tag.endsWith('/>') ? tag.length - 2 : tag.length - 1;
  return `${tag.slice(0, close)} ${name}="${escAttr(value)}"${tag.slice(close)}`;
}

const openEnd = (el: XmlEl) => el.innerStart;
const tagEdit = (el: XmlEl, change: (tag: string) => string): Edit => ({ start: el.start, end: openEnd(el), text: change(el.src.slice(el.start, openEnd(el))) });

const hex = (c: string) => c.replace('#', '').toUpperCase();
const solid = (c: string | null) => (c ? `<a:solidFill><a:srgbClr val="${hex(c)}"/></a:solidFill>` : '<a:noFill/>');
const FILLS = new Set(['a:noFill', 'a:solidFill', 'a:gradFill', 'a:pattFill', 'a:blipFill', 'a:grpFill']);
const pt = (px: number) => `${Math.round(px * 0.75 * 100) / 100}pt`;

/** The changes to one `wps:spPr` for a new fill or outline colour. */
function spPrEdits(spPr: XmlEl, was: ShapeSpec, now: ShapeSpec): Edit[] {
  const edits: Edit[] = [];
  const fill = spPr.children.find((c) => FILLS.has(c.name));
  const ln = child(spPr, 'a:ln');
  // Where a fill goes if there is none: after the geometry, or the transform, or at the start.
  const before = [...spPr.children].reverse().find((c) => c.name === 'a:prstGeom' || c.name === 'a:custGeom' || c.name === 'a:xfrm');
  const fillAt = fill ? fill.end : before ? before.end : spPr.innerStart;

  if (now.fill !== was.fill) {
    if (fill) edits.push({ start: fill.start, end: fill.end, text: solid(now.fill) });
    else if (spPr.innerStart === spPr.end) return [{ start: spPr.start, end: spPr.end, text: `<wps:spPr>${solid(now.fill)}${now.line !== was.line ? `<a:ln>${solid(now.line)}</a:ln>` : ''}</wps:spPr>` }];
    else edits.push({ start: fillAt, end: fillAt, text: solid(now.fill) });
  }

  if (now.line !== was.line) {
    if (ln && ln.innerStart !== ln.end) {
      const lnFill = ln.children.find((c) => FILLS.has(c.name));
      if (lnFill) edits.push({ start: lnFill.start, end: lnFill.end, text: solid(now.line) });
      else edits.push({ start: ln.innerStart, end: ln.innerStart, text: solid(now.line) });
    } else if (ln) {
      edits.push({ start: ln.start, end: ln.end, text: `${ln.src.slice(ln.start, ln.end - 2)}>${solid(now.line)}</a:ln>` });
    } else {
      edits.push({ start: fillAt, end: fillAt, text: `<a:ln>${solid(now.line)}</a:ln>` });
    }
  }

  return edits;
}

/** The changes to a VML shape's open tag for a new size, place, fill or outline colour. */
function vmlEdit(shape: XmlEl, was: ShapeSpec, now: ShapeSpec): Edit {
  return tagEdit(shape, (tag) => {
    const style = parseStyle(shape.attrs.style);
    const order = Object.keys(style);
    const set = (k: string, v: string) => {
      if (!(k in style)) order.push(k);
      style[k] = v;
    };

    if (now.w !== was.w || now.h !== was.h) {
      set('width', pt(now.w));
      set('height', pt(now.h));
    }

    if (now.anchor && was.anchor && (now.anchor.x !== was.anchor.x || now.anchor.alignH !== was.anchor.alignH)) {
      set('margin-left', pt(now.anchor.x));
      if ('mso-position-horizontal' in style) set('mso-position-horizontal', 'absolute');
    }

    if (now.anchor && was.anchor && (now.anchor.y !== was.anchor.y || now.anchor.alignV !== was.anchor.alignV)) {
      set('margin-top', pt(now.anchor.y));
      if ('mso-position-vertical' in style) set('mso-position-vertical', 'absolute');
    }

    let out = setAttr(tag, 'style', order.map((k) => `${k}:${style[k]}`).join(';'));

    if (now.fill !== was.fill) {
      out = setAttr(out, 'filled', now.fill ? 't' : 'f');
      if (now.fill) out = setAttr(out, 'fillcolor', now.fill);
    }

    if (now.line !== was.line) {
      out = setAttr(out, 'stroked', now.line ? 't' : 'f');
      if (now.line) out = setAttr(out, 'strokecolor', now.line);
    }

    return out;
  });
}

const VML_KINDS = new Set(['v:shape', 'v:rect', 'v:roundrect', 'v:oval', 'v:line']);

/** The shape's XML with what changed written in, and the rest as it came. */
export function patchShape(source: string, was: ShapeSpec, now: ShapeSpec, text: string | null): string {
  const root = parseXml(source);
  const edits: Edit[] = [];
  const sized = now.w !== was.w || now.h !== was.h;
  const looks = now.fill !== was.fill || now.line !== was.line;

  for (const drawing of root.name === 'w:drawing' ? [root] : descendants(root, 'w:drawing')) {
    const container = child(drawing, 'wp:inline') ?? child(drawing, 'wp:anchor');
    if (!container) continue;

    const extent = child(container, 'wp:extent');
    if (sized && extent) edits.push(tagEdit(extent, (t) => setAttr(setAttr(t, 'cx', String(pxToEmu(now.w))), 'cy', String(pxToEmu(now.h)))));

    if (container.name === 'wp:anchor' && now.anchor && was.anchor) {
      for (const [name, axis] of [['wp:positionH', 'x'], ['wp:positionV', 'y']] as const) {
        const el = child(container, name);
        const align = axis === 'x' ? 'alignH' : 'alignV';
        if (el && (now.anchor[axis] !== was.anchor[axis] || now.anchor[align] !== was.anchor[align])) {
          edits.push({ start: el.innerStart, end: el.innerEnd, text: `<wp:posOffset>${pxToEmu(now.anchor[axis])}</wp:posOffset>` });
        }
      }
    }

    const data = child(child(container, 'a:graphic'), 'a:graphicData');
    const wsp = child(data, 'wps:wsp');
    const group = child(data, 'wpg:wgp');
    const spPr = child(wsp, 'wps:spPr') ?? child(group, 'wpg:grpSpPr');
    const ext = child(child(spPr, 'a:xfrm'), 'a:ext');

    if (sized && ext) edits.push(tagEdit(ext, (t) => setAttr(setAttr(t, 'cx', String(pxToEmu(now.w))), 'cy', String(pxToEmu(now.h)))));
    if (looks && wsp && spPr) edits.push(...spPrEdits(spPr, was, now));
  }

  for (const pict of root.name === 'w:pict' ? [root] : descendants(root, 'w:pict')) {
    for (const shape of pict.children.filter((c) => VML_KINDS.has(c.name))) edits.push(vmlEdit(shape, was, now));
  }

  if (text !== null) {
    for (const box of descendants(root, 'w:txbxContent')) edits.push({ start: box.innerStart, end: box.innerEnd, text });
  }

  return applyEdits(source, edits);
}

let relHeight = 251659264;

/** A shape made here, as Word 2010 writes one: `wps:wsp` in a floating `wp:anchor`, with VML for older readers. */
export function newShapeXml(spec: ShapeSpec, text: string | null, id: number): string {
  const a = spec.anchor ?? { x: 0, y: 0, relH: 'column', relV: 'paragraph', alignH: null, alignV: null, wrap: 'square', behind: false };
  const cx = pxToEmu(spec.w);
  const cy = pxToEmu(spec.h);
  const lineLike = LINE_LIKE.has(spec.geom);
  const name = text !== null ? `Text Box ${id}` : `Shape ${id}`;
  const ins = spec.inset.map((n) => pxToEmu(n));
  const flips = `${spec.flipH ? ' flipH="1"' : ''}${spec.flipV ? ' flipV="1"' : ''}`;
  const dash = spec.dash !== 'solid' ? `<a:prstDash val="${spec.dash}"/>` : '';
  const ends = `${spec.head !== 'none' ? `<a:headEnd type="${spec.head}"/>` : ''}${spec.tail !== 'none' ? `<a:tailEnd type="${spec.tail}"/>` : ''}`;
  const box = text !== null ? `<w:txbxContent>${text}</w:txbxContent>` : '';
  const wrap = a.wrap === 'square' ? '<wp:wrapSquare wrapText="bothSides"/>' : a.wrap === 'topBottom' ? '<wp:wrapTopAndBottom/>' : '<wp:wrapNone/>';
  relHeight += 2;

  const wsp =
    `<wps:wsp>${lineLike ? '<wps:cNvCnPr/>' : `<wps:cNvSpPr${spec.geom === 'rect' && text !== null ? ' txBox="1"' : ''}/>`}` +
    `<wps:spPr><a:xfrm${flips}><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="${spec.geom}"><a:avLst/></a:prstGeom>` +
    `${lineLike ? '' : solid(spec.fill)}<a:ln w="${pxToEmu(spec.lw)}">${solid(spec.line)}${dash}${ends}</a:ln></wps:spPr>` +
    (text !== null ? `<wps:txbx>${box}</wps:txbx>` : '') +
    `<wps:bodyPr rot="0" vert="horz" wrap="square" lIns="${ins[0]}" tIns="${ins[1]}" rIns="${ins[2]}" bIns="${ins[3]}" anchor="${spec.valign}" anchorCtr="0"><a:noAutofit/></wps:bodyPr></wps:wsp>`;

  const drawing =
    `<w:drawing><wp:anchor xmlns:wp="${WP_NS}" distT="0" distB="0" distL="114300" distR="114300" simplePos="0" relativeHeight="${relHeight}" ` +
    `behindDoc="${a.behind ? 1 : 0}" locked="0" layoutInCell="1" allowOverlap="1"><wp:simplePos x="0" y="0"/>` +
    `<wp:positionH relativeFrom="${a.relH}"><wp:posOffset>${pxToEmu(a.x)}</wp:posOffset></wp:positionH>` +
    `<wp:positionV relativeFrom="${a.relV}"><wp:posOffset>${pxToEmu(a.y)}</wp:posOffset></wp:positionV>` +
    `<wp:extent cx="${cx}" cy="${cy}"/><wp:effectExtent l="0" t="0" r="0" b="0"/>${wrap}` +
    `<wp:docPr id="${id}" name="${name}"/><wp:cNvGraphicFramePr/>` +
    `<a:graphic xmlns:a="${A_NS}"><a:graphicData uri="${WPS_NS}">${wsp}</a:graphicData></a:graphic></wp:anchor></w:drawing>`;

  // VML for readers before Word 2010: a rectangle, rounded rectangle, oval or line, else a rectangle.
  const vmlTag = spec.geom === 'ellipse' ? 'v:oval' : spec.geom === 'roundRect' ? 'v:roundrect' : lineLike ? 'v:line' : 'v:rect';
  const relH = { page: 'page', margin: 'margin', column: 'text', character: 'char' }[a.relH] ?? 'text';
  const relV = { page: 'page', margin: 'margin', paragraph: 'text', line: 'line' }[a.relV] ?? 'text';
  const place = lineLike
    ? `from="${pt(a.x)},${pt(a.y)}" to="${pt(a.x + spec.w)},${pt(a.y + spec.h)}" style="position:absolute;z-index:${id}"`
    : `style="position:absolute;margin-left:${pt(a.x)};margin-top:${pt(a.y)};width:${pt(spec.w)};height:${pt(spec.h)};z-index:${id};` +
      `mso-position-horizontal-relative:${relH};mso-position-vertical-relative:${relV}"`;
  const look =
    `${!lineLike && spec.fill ? ` fillcolor="${spec.fill}"` : ' filled="f"'}${spec.line ? ` strokecolor="${spec.line}" strokeweight="${pt(spec.lw)}"` : ' stroked="f"'}` +
    `${spec.geom === 'roundRect' ? ' arcsize="10923f"' : ''}`;
  const vml =
    `<w:pict><${vmlTag} xmlns:v="${V_NS}" id="${name}" ${place}${look}>` +
    (box ? `<v:textbox>${box}</v:textbox>` : '') +
    `<w10:wrap xmlns:w10="${W10_NS}"${a.wrap === 'square' ? ' type="square"' : a.wrap === 'topBottom' ? ' type="topAndBottom"' : ''}/></${vmlTag}></w:pict>`;

  return `<mc:AlternateContent xmlns:mc="${MC_NS}"><mc:Choice xmlns:wps="${WPS_NS}" Requires="wps">${drawing}</mc:Choice><mc:Fallback>${vml}</mc:Fallback></mc:AlternateContent>`;
}

/**
 * A shape node as run content. `blocks` writes a text box's content as the document's paragraphs
 * are written; `nextId` gives a drawing id no other drawing has.
 */
export function shapeXml(node: PMNode, blocks: (doc: PMNode) => string, nextId: () => number): string {
  const a = node.attrs;
  const now = parseShapeSpec(a.spec);
  const doc = textDoc(a.text);

  if (a.raw) {
    const was = parseShapeSpec(a.orig);
    if (!now || !was || (a.spec === a.orig && !a.edited)) return a.raw;

    return patchShape(a.raw, was, now, a.edited && doc ? blocks(doc) : null);
  }

  if (!now) return '';

  const text = now.text ? (doc ? blocks(doc) : '<w:p/>') : null;
  return newShapeXml(now, text || (now.text ? '<w:p/>' : null), nextId());
}


/** A shape as the gallery makes one: floating at an offset from its paragraph's column, with square wrapping. */
export function newSpec(geom: string, at: { x: number; y: number } = { x: 0, y: 0 }, text = false): ShapeSpec {
  const lineLike = LINE_LIKE.has(geom);
  const wide = /Arrow$/.test(geom) && (geom === 'rightArrow' || geom === 'leftArrow');
  const tall = geom === 'upArrow' || geom === 'downArrow';
  const w = text ? 192 : lineLike ? 128 : wide ? 128 : tall ? 64 : 96;
  const h = text ? 96 : lineLike ? 0 : wide ? 64 : tall ? 128 : 96;

  return {
    geom, adj: {}, w, h,
    fill: text ? '#FFFFFF' : lineLike ? null : '#4472C4',
    line: text ? '#000000' : lineLike ? '#4472C4' : '#2F528F',
    lw: text ? 1 : 1.33,
    dash: 'solid', head: 'none', tail: geom === 'straightConnector1' ? 'triangle' : 'none',
    rot: 0, flipH: false, flipV: false,
    anchor: { x: at.x, y: at.y, relH: 'column', relV: 'paragraph', alignH: null, alignV: null, wrap: lineLike ? 'none' : 'square', behind: false },
    text: text || geom === 'wedgeRectCallout',
    inset: [9.6, 4.8, 9.6, 4.8],
    valign: text ? 't' : 'ctr',
  };
}
