// Why a suggestion helps, in a few words: "spelling", "subject-verb agreement".
//
// The plain cases are told from the change itself, at once. The rest are asked of the model in
// one short follow-up per paragraph, after its suggestions are already on the page, so that
// checking a paragraph is no slower than before.

import type { AssistRequest } from '../desktop';
import { spellingVariant } from './review/spelling';

export interface ChangeText {
  original: string;
  insert: string;
}

const words = (text: string) => text.toLowerCase().match(/[\p{L}\p{N}'’]+/gu) ?? [];
const letters = (text: string) => text.replace(/[^\p{L}\p{N}]/gu, '');

/** How many single-letter edits turn one word into the other. */
export function editDistance(a: string, b: string): number {
  if (Math.abs(a.length - b.length) > 3) return 4;

  let row = Array.from({ length: b.length + 1 }, (_, j) => j);

  for (let i = 1; i <= a.length; i++) {
    const next = [i];
    for (let j = 1; j <= b.length; j++) next[j] = Math.min(row[j] + 1, next[j - 1] + 1, row[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    row = next;
  }

  return row[b.length];
}

/** Wordy phrases and what replaces them, for "wordiness". */
const WORDY: [RegExp, RegExp][] = [
  [/\bin order to\b/i, /^to$/i],
  [/\bdue to the fact that\b/i, /^because$/i],
  [/\bat this point in time\b/i, /^(now|currently)$/i],
  [/\bin spite of the fact that\b/i, /^(although|though)$/i],
  [/\bfor the purpose of\b/i, /^(to|for)$/i],
  [/\bit is important to note that\b/i, /^$/],
];

const HEDGES = /^(very|really|quite|rather|somewhat|perhaps|possibly|basically|actually|just|fairly|arguably|probably|maybe|literally|certainly|definitely)$/i;

/**
 * The reason for a change that can be told without a model, or null. Only clear-cut cases: a
 * wrong reason is worse than none.
 */
export function quickReason(original: string, insert: string): string | null {
  const a = original.trim();
  const b = insert.trim();

  if (a === b) return 'spacing';
  if (!a && /^[,;:.!?]+$/.test(b)) return b === ',' ? 'missing comma' : 'missing punctuation';
  if (!b && /^[,;:.!?]+$/.test(a)) return a === ',' ? 'unneeded comma' : 'unneeded punctuation';
  if (a && b && a.replace(/-/g, '').replace(/\s+/g, '') === b.replace(/-/g, '').replace(/\s+/g, '')) return 'hyphenation';
  if (a && b && letters(a) === letters(b) && a.toLowerCase() !== b.toLowerCase()) return 'punctuation';
  if (a && a.toLowerCase() === b.toLowerCase()) return 'capitalisation';

  const before = words(a);
  const after = words(b);

  if (before.length === 1 && after.length === 1) {
    const [x, y] = [before[0], after[0]];
    const variant = spellingVariant(x);

    if (variant && spellingVariant(y)?.family === variant.family && variant.side !== spellingVariant(y)?.side) {
      return variant.side === 'GB' ? 'American spelling' : 'British spelling';
    }

    if (/^(an?)$/.test(x) && /^(an?)$/.test(y)) return 'a or an';
    if (x.length > 3 && editDistance(x, y) <= 2 && x[0] === y[0] && !/^(is|are|was|were|has|have)$/.test(y)) return 'spelling';
  }

  if (!b && before.length === 1 && HEDGES.test(before[0])) return 'removes an unneeded hedge';
  if (!b && before.length === 2 && before[0] === before[1]) return 'repeated word';
  if (WORDY.some(([long, short]) => long.test(a) && short.test(b))) return 'wordiness';

  return null;
}

/** The request for why each of a paragraph's changes is made, numbered from 1. */
export function explainRequest(model: string, paragraph: string, changes: ChangeText[]): AssistRequest {
  const list = changes
    .map((c, i) => `${i + 1}. ${c.original ? `"${c.original}"` : '(nothing)'} → ${c.insert ? `"${c.insert}"` : '(removed)'}`)
    .join('\n');

  return {
    model,
    system:
      'You are a writing tutor. The user sends a paragraph and numbered edits made to it. For each edit, give the reason ' +
      'it improves the text in two to six words, naming the rule or effect, such as "subject-verb agreement", "missing ' +
      'article", "removes redundant hedge", "wrong preposition", "clearer word order", "more formal register". Answer with ' +
      'one line per edit, in the form "1: reason", in the order given, and nothing else. Write the reasons in English.',
    text: `Paragraph:\n${paragraph}\n\nEdits:\n${list}`,
    temperature: 0,
    maxTokens: 16 * changes.length + 32,
  };
}

/** The reasons in a model's answer, by edit number from 0; null where it gave none. */
export function parseReasons(answer: string, count: number): (string | null)[] {
  const reasons: (string | null)[] = Array.from({ length: count }, () => null);
  const text = answer.replace(/<think>[\s\S]*?<\/think>/g, '');

  for (const line of text.split('\n')) {
    const match = /^\s*(?:[-*]\s*)?(?:edit\s*)?(\d+)\s*[:.)\-–]\s*(.+?)\s*$/i.exec(line);
    if (!match) continue;

    const index = Number(match[1]) - 1;
    const reason = match[2].replace(/^["'“*]+|["'”*.]+$/g, '').trim();

    if (index >= 0 && index < count && reason && reason.length <= 80 && reasons[index] === null) {
      reasons[index] = /^(British|American|English|Oxford|APA|Latin)\b/.test(reason) ? reason : reason.charAt(0).toLowerCase() + reason.slice(1);
    }
  }

  return reasons;
}
