// Word's CITATION instruction: `CITATION Smi20 \l 1033 \p 23 \f "see" \m Jon19 \n`.
// \m starts another source of the same citation; the switches after it are that source's.

export interface CitationPart {
  tag: string;
  pages?: string;
  volume?: string;
  prefix?: string;
  suffix?: string;
  noAuthor?: boolean;
  noYear?: boolean;
  noTitle?: boolean;
}

export interface Citation {
  parts: CitationPart[];
  /** The language (`\l`), 1033 for English (US) unless the instruction says otherwise. */
  lcid: string;
}

function tokens(instr: string): { text: string; quoted: boolean }[] {
  const out: { text: string; quoted: boolean }[] = [];
  for (const match of instr.matchAll(/"((?:[^"\\]|\\.)*)"|(\\\S)|([^\s"]+)/g)) {
    if (match[1] !== undefined) out.push({ text: match[1].replace(/\\(.)/g, '$1'), quoted: true });
    else out.push({ text: match[2] ?? match[3], quoted: false });
  }
  return out;
}

const WITH_ARG = new Set(['l', 'f', 's', 'p', 'v', 'm']);

export function parseCitation(instr: string): Citation {
  const list = tokens(instr);
  if (list[0]?.text.toUpperCase() === 'CITATION') list.shift();

  const parts: CitationPart[] = [];
  let lcid = '1033';
  let current: CitationPart | null = null;

  for (let i = 0; i < list.length; i++) {
    const token = list[i];
    const isSwitch = !token.quoted && /^\\\S$/.test(token.text);

    if (!isSwitch) {
      if (!current) parts.push((current = { tag: token.text }));
      continue;
    }

    const letter = token.text[1].toLowerCase();
    const arg = WITH_ARG.has(letter) && i + 1 < list.length ? list[++i].text : '';

    if (letter === 'm') {
      parts.push((current = { tag: arg }));
      continue;
    }
    if (letter === 'l') {
      lcid = arg || lcid;
      continue;
    }
    if (!current) parts.push((current = { tag: '' }));

    if (letter === 'p') current.pages = arg;
    else if (letter === 'v') current.volume = arg;
    else if (letter === 'f') current.prefix = arg;
    else if (letter === 's') current.suffix = arg;
    else if (letter === 'n') current.noAuthor = true;
    else if (letter === 'y') current.noYear = true;
    else if (letter === 't') current.noTitle = true;
  }

  return { parts: parts.filter((p) => p.tag), lcid };
}

const quote = (text: string) => (/[\s"\\]/.test(text) || !text ? `"${text.replace(/(["\\])/g, '\\$1')}"` : text);

export function citationInstr(citation: Citation): string {
  return citation.parts
    .map((part, i) => {
      let out = i === 0 ? `CITATION ${quote(part.tag)} \\l ${citation.lcid}` : `\\m ${quote(part.tag)}`;
      if (part.pages) out += ` \\p ${quote(part.pages)}`;
      if (part.volume) out += ` \\v ${quote(part.volume)}`;
      if (part.prefix) out += ` \\f ${quote(part.prefix)}`;
      if (part.suffix) out += ` \\s ${quote(part.suffix)}`;
      if (part.noAuthor) out += ' \\n';
      if (part.noYear) out += ' \\y';
      if (part.noTitle) out += ' \\t';
      return out;
    })
    .join(' ');
}
