// Setting a section's columns, as Word's Layout > Columns does.
//
// With no selection the section the cursor is in gets the columns. With a selection, the
// blocks it touches become a section of their own between continuous section breaks: the
// paragraph before them ends the section before (with its properties as they were), the last
// of them ends the new one, and the section they were in carries on after them, starting
// continuously. It is all one step, so one undo takes it back. Sections nobody touched keep
// their `w:sectPr` exactly as read.

import type { Node as PMNode } from 'prosemirror-model';
import type { Command, Transaction } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { schema } from '../editor/schema';
import { type Cols, type SectionRange, sectionAt, sectionRanges, withCols, withType } from './model';

const N = schema.nodes;
const EMPTY_SECT = '<w:sectPr></w:sectPr>';

/** The top-level block a position is in, and where it starts. */
function blockAt(doc: PMNode, pos: number): { node: PMNode; pos: number } {
  const $pos = doc.resolve(Math.max(0, Math.min(pos, doc.content.size)));
  const index = Math.min($pos.index(0), doc.childCount - 1);
  return { node: doc.child(index), pos: $pos.posAtIndex(index, 0) };
}

/** Sets the properties of the section ending with the paragraph at `endPos` (null: the body's last). */
function setSectPr(tr: Transaction, endPos: number | null, sectPr: string): void {
  if (endPos === null) tr.setDocAttribute('sectPr', sectPr);
  else tr.setNodeAttribute(tr.mapping.map(endPos), 'sectPr', sectPr);
}

export function setColumns(ctx: DocContext, cols: Cols): Command {
  return (state, dispatch) => {
    const doc = state.doc;
    const ranges = sectionRanges(doc, ctx.sectPr);
    const { from, to, empty } = state.selection;
    const section = sectionAt(ranges, from);
    const base = section.sectPr ?? EMPTY_SECT;

    /** Where the paragraph that ends a section starts; null for the body's own section. */
    const endOf = (range: SectionRange): number | null | false => {
      if (range.index === ranges.length - 1) return null;
      const last = blockAt(doc, range.to - 1);
      return last.node.type === N.paragraph ? last.pos : false;
    };

    const holder = endOf(section);
    // A section ended inside a content control is left alone.
    if (holder === false) return false;

    const tr = state.tr;

    if (empty || section.to <= section.from) {
      setSectPr(tr, holder, withCols(base, cols));
      if (dispatch) dispatch(tr.scrollIntoView());
      return true;
    }

    // The blocks the selection touches, within its first section.
    const first = blockAt(doc, Math.max(from, section.from));
    const last = blockAt(doc, Math.min(to, section.to - 1));
    const lastEnd = last.pos + last.node.nodeSize;
    const before = first.pos > section.from ? blockAt(doc, first.pos - 1) : null;
    const inner = withType(withCols(base, cols), before ? 'continuous' : section.type);

    if (lastEnd >= section.to) {
      // The selection runs to the section's end: that end is the new section's.
      setSectPr(tr, holder, inner);
    } else {
      // The rest of the section it was in, after it, starts continuously.
      setSectPr(tr, holder, withType(base, 'continuous'));
      if (last.node.type === N.paragraph) tr.setNodeAttribute(last.pos, 'sectPr', inner);
      else tr.insert(lastEnd, N.paragraph.create({ sectPr: inner }));
    }

    // The section before keeps the properties it had.
    if (before) {
      if (before.node.type === N.paragraph) tr.setNodeAttribute(before.pos, 'sectPr', base);
      else tr.insert(first.pos, N.paragraph.create({ sectPr: base }));
    }

    if (dispatch) dispatch(tr.scrollIntoView());
    return true;
  };
}
