// List markers on the page.
//
// A bullet or number is not in the document: it follows from the paragraph's list and level and
// from the list paragraphs before it. This plugin counts through the document and hangs each
// marker on its paragraph as a decoration, which page.css draws in front of the text.

import type { Node as PMNode } from 'prosemirror-model';
import { Plugin, PluginKey } from 'prosemirror-state';
import { Decoration, DecorationSet } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { ListCounter } from '../docx/numbering';
import { twipsToPt } from '../docx/props';
import { schema } from './schema';

export const listKey = new PluginKey<DecorationSet>('lists');

export interface ListPlace {
  numId: number;
  ilvl: number;
  /** Set on the paragraph itself, as opposed to coming with its style, as numbered headings do. */
  direct: boolean;
}

/** The list a paragraph is an item of, if any. */
export function listOf(node: PMNode, ctx: DocContext): ListPlace | null {
  const a = node.attrs;

  if (a.numId !== null) {
    return a.numId > 0 && ctx.numbering.has(a.numId) ? { numId: a.numId, ilvl: a.ilvl, direct: true } : null;
  }

  const fromStyle = ctx.styles.numPrOf(a.styleId);

  if (!fromStyle || fromStyle.numId <= 0 || !ctx.numbering.has(fromStyle.numId)) return null;

  const styleId = a.styleId ?? ctx.styles.defaultParagraph ?? '';
  const ilvl = fromStyle.ilvl ?? ctx.numbering.levelForStyle(fromStyle.numId, styleId) ?? 0;

  return { numId: fromStyle.numId, ilvl, direct: false };
}

function build(doc: PMNode, ctx: DocContext): DecorationSet {
  const counter = new ListCounter(ctx.numbering);
  const decorations: Decoration[] = [];

  doc.descendants((node, pos) => {
    if (node.type !== schema.nodes.paragraph) return true;

    const place = listOf(node, ctx);
    const label = place ? counter.next(place.numId, place.ilvl) : null;

    if (place && label) {
      // The list's own indent applies unless the paragraph's style brought the list and an indent
      // of its own with it; page.css reads data-num for that.
      const ownIndent = place.direct || !ctx.styles.hasIndent(node.attrs.styleId);

      decorations.push(
        Decoration.node(pos, pos + node.nodeSize, {
          'data-label': label.text,
          'data-num': ownIndent ? 'list' : 'style',
          style: `--num-left:${twipsToPt(label.left)}pt;--num-hang:${twipsToPt(label.hanging)}pt`,
        }),
      );
    }

    return false;
  });

  return DecorationSet.create(doc, decorations);
}

export function listPlugin(ctx: DocContext): Plugin {
  return new Plugin({
    key: listKey,
    state: {
      init: (_config, state) => build(state.doc, ctx),
      // Recounted whenever the text changes, or when a command says the lists themselves did.
      apply: (tr, old) => (tr.docChanged || tr.getMeta(listKey) ? build(tr.doc, ctx) : old),
    },
    props: {
      decorations: (state) => listKey.getState(state),
    },
  });
}
