// The formats "Export as…" writes, without anything of the window: what tests call.

import type { SideFile, Source } from './common';
import { toHtml } from './html';
import { toMarkdown } from './markdown';
import { toOdt } from './odt';

export type ExportFormat = 'md' | 'html' | 'odt';

/** The format a file name asks for, by its extension. */
export function formatOf(path: string): ExportFormat | null {
  const ext = /\.([^.\\/]+)$/.exec(path)?.[1]?.toLowerCase();
  if (ext === 'md' || ext === 'markdown') return 'md';
  if (ext === 'html' || ext === 'htm') return 'html';
  if (ext === 'odt') return 'odt';
  return null;
}

export interface Exported {
  bytes: Uint8Array;
  /** Files that go in "<name>_files" beside it: a Markdown file's pictures. */
  files: SideFile[];
}

/** The document in one of the formats. */
export function convert(src: Source, format: ExportFormat): Exported {
  if (format === 'md') {
    const { text, files } = toMarkdown(src);
    return { bytes: new TextEncoder().encode(text), files };
  }

  if (format === 'html') return { bytes: new TextEncoder().encode(toHtml(src)), files: [] };
  return { bytes: toOdt(src), files: [] };
}
