// The document as the writing assistant reads it: paragraphs as plain text, each character
// knowing where in the document it is, and back again.
//
// A model reads and writes text, not ProseMirror nodes. Line breaks become "\n". Everything else
// that is not text (pictures, bookmarks, fields, the placeholders for what the editor cannot show)
// is left out of the text, and is never removed by a change made from it: export keeps those
// things through an edit, and so must the assistant.

import { type Mark, type Node as PMNode, type Schema } from 'prosemirror-model';
import type { Transaction } from 'prosemirror-state';

/** A stretch of one paragraph as plain text. */
export interface Piece {
  text: string;
  /** Where in the document each character of `text` is. */
  map: number[];
  /** The document position just after the stretch. */
  end: number;
}

export interface Range {
  from: number;
  to: number;
}

const isBreak = (node: PMNode) => node.type.name === 'hard_break';

/**
 * The paragraphs (and other text blocks) that `from`–`to` touches, each as the part of its
 * content inside that range. An empty range gives the whole paragraph it is in.
 */
export function blocksIn(doc: PMNode, from: number, to: number): Range[] {
  const ranges: Range[] = [];

  if (from === to) {
    const $at = doc.resolve(from);

    if ($at.parent.isTextblock) ranges.push({ from: $at.start(), to: $at.end() });
    return ranges;
  }

  doc.nodesBetween(from, to, (node, pos) => {
    if (!node.isTextblock) return true;

    const start = Math.max(from, pos + 1);
    const end = Math.min(to, pos + 1 + node.content.size);

    if (end > start) ranges.push({ from: start, to: end });
    return false;
  });

  return ranges;
}

/** Every text block of the document, whole. */
export function allBlocks(doc: PMNode): Range[] {
  return blocksIn(doc, 0, doc.content.size);
}

/** The text of a range in one paragraph, and where each character of it is. */
export function pieceOf(doc: PMNode, from: number, to: number): Piece {
  let text = '';
  const map: number[] = [];

  doc.nodesBetween(from, to, (node, pos) => {
    if (node.isText) {
      const start = Math.max(from, pos);
      const end = Math.min(to, pos + node.nodeSize);

      text += node.text!.slice(start - pos, end - pos);
      for (let at = start; at < end; at++) map.push(at);
    } else if (node.isInline && isBreak(node) && pos >= from && pos < to) {
      text += '\n';
      map.push(pos);
    }

    return true;
  });

  return { text, map, end: to };
}

/** Whether a piece has anything worth sending: two words, or one long one. */
export function worthChecking(text: string): boolean {
  const words = text.match(/[\p{L}\p{N}]+/gu) ?? [];
  return words.length >= 2 || (words.length === 1 && words[0].length > 3);
}

/**
 * Cuts a long piece into shorter ones at the ends of sentences, so that each fits a request. A
 * sentence longer than `max` on its own stays whole.
 */
export function splitPiece(piece: Piece, max: number): Piece[] {
  if (piece.text.length <= max) return [piece];

  const pieces: Piece[] = [];
  const ends = [...piece.text.matchAll(/[.!?…:;]+["'”’)\]]*\s+|\n/g)].map((match) => match.index + match[0].length);
  let start = 0;
  let cut = 0;

  const take = (end: number) => {
    pieces.push({ text: piece.text.slice(start, end), map: piece.map.slice(start, end), end: end < piece.map.length ? piece.map[end] : piece.end });
    start = end;
  };

  for (const end of [...ends, piece.text.length]) {
    if (end - start > max && cut > start) take(cut);
    cut = end;
  }

  if (start < piece.text.length) take(piece.text.length);
  return pieces.filter((part) => part.text.length > 0);
}

/** Where in the document the characters from `from` to `to` of a piece are. */
export function rangeOf(piece: Piece, from: number, to: number): Range {
  const at = (i: number) => (i < piece.map.length ? piece.map[i] : piece.end);

  return to > from ? { from: at(from), to: piece.map[to - 1] + 1 } : { from: at(from), to: at(from) };
}

/**
 * Replaces the text from `from` to `to` with `text`, keeping whatever else is in the range
 * (pictures, bookmarks, line breaks): those stay, after the new text. The new text takes the
 * formatting of the first text it replaces, or of the text before it when it is only added.
 */
export function replaceKeepingLeaves(tr: Transaction, from: number, to: number, text: string): void {
  const schema = tr.doc.type.schema;
  const texts: Range[] = [];
  let marks: readonly Mark[] | null = null;

  tr.doc.nodesBetween(from, to, (node, pos) => {
    if (!node.isText) return true;

    marks ??= node.marks;
    texts.push({ from: Math.max(from, pos), to: Math.min(to, pos + node.nodeSize) });
    return false;
  });

  for (let i = texts.length - 1; i >= 0; i--) tr.delete(texts[i].from, texts[i].to);

  const clean = text.replace(/\n/g, ' ');
  if (clean) tr.insert(from, schema.text(clean, marks ?? tr.doc.resolve(from).marks()));
}

// ---- Text with its formatting, for translation -----------------------------------------------
//
// A translation moves words around, so formatting cannot follow the characters. Instead each run
// of differently formatted text is wrapped in a numbered tag, <s1>…</s1>, which the model is told
// to keep around the words that mean the same; anything that is not text is <x1/>. A paragraph in
// one formatting throughout, the usual case, goes as plain text.

export interface Tagged {
  text: string;
  /** Whether `text` carries tags; false when the whole range has one formatting. */
  tagged: boolean;
  /** The formattings, by the number in their tag. The first is the one for untagged text. */
  sets: (readonly Mark[])[];
  /** What is not text, by the number in its tag. */
  leaves: PMNode[];
  /** Whether formatting changes inside a word somewhere ("<s1>Haus</s1><s2>tür</s2>"). */
  glued: boolean;
}

const WORD_END = /[\p{L}\p{N}]$/u;
const WORD_START = /^[\p{L}\p{N}]/u;

export function taggedOf(doc: PMNode, from: number, to: number): Tagged {
  const sets: (readonly Mark[])[] = [];
  const leaves: PMNode[] = [];
  const parts: { set: number; text: string }[] = [];
  const setOf = (marks: readonly Mark[]) => {
    let at = sets.findIndex((set) => set.length === marks.length && set.every((mark, i) => mark.eq(marks[i])));

    if (at < 0) at = sets.push(marks) - 1;
    return at;
  };

  doc.nodesBetween(from, to, (node, pos) => {
    if (node.isText) {
      const text = node.text!.slice(Math.max(from, pos) - pos, Math.min(to, pos + node.nodeSize) - pos);
      const set = setOf(node.marks);
      const last = parts[parts.length - 1];

      if (last && last.set === set) last.text += text;
      else parts.push({ set, text });
    } else if (node.isInline && pos >= from && pos < to) {
      if (isBreak(node)) {
        const last = parts[parts.length - 1];

        if (last && last.set >= 0) last.text += '\n';
        else parts.push({ set: sets.length ? 0 : setOf(node.marks), text: '\n' });
      } else {
        parts.push({ set: -1 - (leaves.push(node) - 1), text: '' });
      }
    }

    return true;
  });

  if (!sets.length) sets.push([]);

  const tagged = sets.length > 1 || leaves.length > 0;
  const text = parts
    .map((part) => (part.set < 0 ? `<x${-part.set}/>` : tagged ? `<s${part.set + 1}>${part.text}</s${part.set + 1}>` : part.text))
    .join('');
  const words = parts.filter((part) => part.text);
  const glued = words.some((part, i) => i > 0 && WORD_END.test(words[i - 1].text) && WORD_START.test(part.text));

  return { text, tagged, sets, leaves, glued };
}

/**
 * The nodes for a translation that came back with the tags of `taggedOf`. Text outside every tag
 * takes the first formatting. Tags the model made up are dropped; things that are not text and
 * that the model lost are put at the end, so that nothing goes missing from the document.
 *
 * Models often drop the space next to a tag ("<s1>This is an</s1><s2>important</s2>"). Where the
 * original had no formatting change inside a word, two words that meet at a tag get their space
 * back; `spaced` is false for a language written without spaces between words.
 */
export function untag(schema: Schema, answer: string, source: Tagged, spaced = true): PMNode[] {
  const nodes: PMNode[] = [];
  const used = new Set<number>();
  const breakType = schema.nodes.hard_break;
  const mend = spaced && !source.glued;
  let marks = source.sets[0];
  let before = '';
  let atTag = false;

  const addText = (text: string) => {
    if (mend && atTag && WORD_END.test(before) && WORD_START.test(text)) text = ` ${text}`;

    text.split('\n').forEach((line, i) => {
      if (i > 0) nodes.push(breakType.create(null, null, marks));
      if (line) nodes.push(schema.text(line, marks));
    });

    if (text) {
      before = text;
      atTag = false;
    }
  };

  if (!source.tagged) {
    addText(answer);
    return nodes;
  }

  const pattern = /<s(\d+)>|<\/s(\d+)>|<x(\d+)\s*\/?>(?:<\/x\3>)?/g;
  let last = 0;

  for (const match of answer.matchAll(pattern)) {
    addText(answer.slice(last, match.index));
    last = match.index + match[0].length;
    atTag = true;

    if (match[1]) {
      marks = source.sets[Number(match[1]) - 1] ?? source.sets[0];
    } else if (match[2]) {
      marks = source.sets[0];
    } else {
      const index = Number(match[3]) - 1;

      if (source.leaves[index] && !used.has(index)) {
        used.add(index);
        nodes.push(source.leaves[index]);
      }
    }
  }

  addText(answer.slice(last));

  source.leaves.forEach((leaf, index) => {
    if (!used.has(index)) nodes.push(leaf);
  });

  return nodes;
}
