// The toolbar: what it offers, and how it shows the formatting at the cursor.

import { toggleMark } from 'prosemirror-commands';
import { COLUMNS_ICON } from '../columns/icon';
import { columnsMenu } from '../columns/menu';
import { SHAPES_ICON, shapesMenu } from '../shapes/menu';
import { redo, redoDepth, undo, undoDepth } from 'prosemirror-history';
import type { MarkType } from 'prosemirror-model';
import type { Command, EditorState } from 'prosemirror-state';
import {
  addColumnAfter, addColumnBefore, addRowAfter, addRowBefore, deleteColumn, deleteRow, deleteTable, isInTable, mergeCells, splitCell,
} from 'prosemirror-tables';
import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import {
  applyStyle, clearFormatting, indent, insertPageBreak, insertTable, linkAt, markAt, removeLink, selectedChart, selectedParagraphs, setAlign, setLink, setMark,
  toggleList,
} from '../editor/commands';
import { listOf } from '../editor/lists';
import { schema } from '../editor/schema';
import { closePopover, h, keepFocus, popover } from './dom';
import { icon } from './icons';
import { overflowMenu } from './overflow';
import { EQUATION_ICON, equationMenu } from '../math/menu';
import { type StyleAction, styleMenu } from './styledialog';
import { REFERENCES_ICON, referencesMenu } from './references';

const M = schema.marks;

export interface ToolbarHost {
  tab(): { ctx: DocContext; view: EditorView } | null;
  /** Runs a command on the document in front and puts the cursor back in it. */
  run(command: Command): void;
  focus(): void;
  pickImage(): void;
  /** Opens the chart editor: on the chart that is selected, or for a new one. */
  editChart(): void;
  toggleFind(): void;
  /** Opens or closes the writing assistant beside the page. */
  toggleAssist(): void;
  /** The style drop-down's "Modify style…", "New style…" and "Update style to match selection". */
  styleAction?(action: StyleAction): void;
}

const STYLE_ACTIONS = [
  ['', '──────────'],
  ['@modify', 'Modify style…'],
  ['@new', 'New style…'],
  ['@update', 'Update style to match selection'],
];

const SIZES = [8, 9, 10, 10.5, 11, 12, 14, 16, 18, 20, 24, 28, 36, 48, 72];

export const TEXT_COLORS = [
  '#000000', '#404040', '#7F7F7F', '#BFBFBF', '#FFFFFF', '#C00000', '#FF0000', '#FFC000', '#FFFF00', '#92D050',
  '#00B050', '#00B0F0', '#0070C0', '#002060', '#7030A0', '#1F3864', '#2F5496', '#833C0B', '#C55A11', '#BF8F00',
  '#F2F2F2', '#D9E2F3', '#DEEAF6', '#E2EFD9', '#FFF2CC', '#FBE4D5', '#EDEDED', '#D5DCE4', '#F4B083', '#A8D08D',
];

/** Word's highlighter colours, which are the only ones its highlighter has. */
export const HIGHLIGHT_COLORS = [
  '#FFFF00', '#00FF00', '#00FFFF', '#FF00FF', '#0000FF', '#FF0000', '#000080', '#008080', '#008000', '#800080',
  '#800000', '#808000', '#808080', '#C0C0C0', '#000000',
];

/** Fonts looked for when the system will not hand over its list. */
const CANDIDATES = [
  'Aptos', 'Arial', 'Arial Narrow', 'Bahnschrift', 'Book Antiqua', 'Calibri', 'Calibri Light', 'Cambria', 'Candara', 'Century Gothic',
  'Comic Sans MS', 'Consolas', 'Constantia', 'Corbel', 'Courier New', 'Franklin Gothic Medium', 'Garamond', 'Georgia', 'Helvetica', 'Impact',
  'Liberation Sans', 'Liberation Serif', 'Lucida Console', 'Lucida Sans Unicode', 'Open Sans', 'Palatino Linotype', 'Roboto', 'Segoe UI',
  'Sitka Text', 'Tahoma', 'Times New Roman', 'Trebuchet MS', 'Verdana',
];

/** Whether a font is installed: text set in it measures differently from the fallback it would otherwise get. */
function installed(name: string): boolean {
  const context = document.createElement('canvas').getContext('2d');
  if (!context) return true;

  const sample = 'mmmmmmmmmlli10WQ';

  return ['monospace', 'serif'].some((fallback) => {
    context.font = `72px ${fallback}`;
    const plain = context.measureText(sample).width;

    context.font = `72px "${name}", ${fallback}`;
    return context.measureText(sample).width !== plain;
  });
}

/** Whether an on/off mark is on at the cursor, or anywhere in the selection. */
function toggled(state: EditorState, type: MarkType, value?: string): boolean {
  const { empty, $from, from, to } = state.selection;

  if (!empty && value === undefined) return state.doc.rangeHasMark(from, to, type);

  const mark = empty ? type.isInSet(state.storedMarks ?? $from.marks()) : markAt(state, type);

  return !!mark && mark.attrs.on !== false && (value === undefined || mark.attrs.value === value);
}

/** An address as typed, made into one a link can carry: example.com becomes https://example.com. */
function asHref(typed: string): string {
  const text = typed.trim();

  if (!text || /^(#|[a-z][a-z0-9+.-]*:)/i.test(text)) return text;
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text)) return `mailto:${text}`;

  return `https://${text}`;
}

export class Toolbar {
  readonly el = h('div', { class: 'toolbar' });

  private readonly tools = new Map<string, HTMLButtonElement>();
  private readonly styleSelect = h('select', { class: 'tool-select style', title: 'Paragraph style' });
  private readonly fontSelect = h('select', { class: 'tool-select font', title: 'Font' });
  private readonly sizeInput = h('input', { class: 'tool-input size', title: 'Font size', list: 'font-sizes', inputmode: 'decimal' });
  private readonly textBar = h('span', { class: 'bar', style: 'background:#FF0000' });
  private readonly markBar = h('span', { class: 'bar', style: 'background:#FFFF00' });
  private fonts: string[] = CANDIDATES.filter(installed);
  private stylesShown = '';
  private fontsShown = '';

  constructor(private readonly host: ToolbarHost) {
    const mark = (type: MarkType, attrs: Record<string, unknown>) => () => host.run(toggleMark(type, attrs));
    const group = (...children: HTMLElement[]) => h('div', { class: 'group' }, ...children);
    const glyph = (cls: string, text: string) => `<span class="glyph ${cls}">${text}</span>`;

    keepFocus(this.el);

    this.styleSelect.addEventListener('change', () => {
      const value = this.styleSelect.value;
      const ctx = host.tab()?.ctx;

      if (value.startsWith('@')) {
        this.update();
        host.styleAction?.(value.slice(1) as StyleAction);
      } else if (ctx) host.run(applyStyle(ctx, value));
    });
    this.styleSelect.addEventListener('contextmenu', (event) => {
      event.preventDefault();
      if (host.tab() && host.styleAction) styleMenu(this.styleSelect, (action) => host.styleAction!(action));
    });

    this.fontSelect.addEventListener('change', () => host.run(setMark(M.fontFamily, { name: this.fontSelect.value })));

    const applySize = () => {
      const size = parseFloat(this.sizeInput.value.replace(',', '.'));

      if (size >= 1 && size <= 1638) host.run(setMark(M.fontSize, { size: Math.round(size * 2) }));
      else this.update();
    };

    this.sizeInput.addEventListener('change', applySize);
    this.sizeInput.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        applySize();
      } else if (event.key === 'Escape') {
        this.update();
        host.focus();
      }
    });

    this.el.append(
      h('datalist', { id: 'font-sizes' }, ...SIZES.map((size) => h('option', { value: String(size) }))),
      group(this.tool('undo', 'Undo (Ctrl+Z)', icon('undo'), () => host.run(undo)), this.tool('redo', 'Redo (Ctrl+Y)', icon('redo'), () => host.run(redo))),
      group(this.styleSelect),
      group(this.fontSelect, this.sizeInput),
      group(
        this.tool('bold', 'Bold (Ctrl+B)', glyph('b', 'B'), mark(M.bold, { on: true })),
        this.tool('italic', 'Italic (Ctrl+I)', glyph('i', 'I'), mark(M.italic, { on: true })),
        this.tool('underline', 'Underline (Ctrl+U)', glyph('u', 'U'), mark(M.underline, { kind: 'single' })),
        this.tool('strike', 'Strikethrough (Ctrl+Shift+X)', glyph('s', 'S'), mark(M.strike, { on: true })),
        this.tool('sub', 'Subscript', glyph('', 'x<small>2</small>'), () => this.vert('subscript')),
        this.tool('sup', 'Superscript', glyph('', 'x<small style="vertical-align:super">2</small>'), () => this.vert('superscript')),
      ),
      group(
        this.tool('color', 'Text colour', glyph('', 'A'), () => this.colorMenu('color')),
        this.tool('highlight', 'Highlight', icon('marker'), () => this.colorMenu('highlight')),
        this.tool('clear', 'Clear formatting (Ctrl+Space)', icon('clear'), () => host.run(clearFormatting)),
      ),
      group(
        this.tool('left', 'Align left (Ctrl+L)', icon('alignLeft'), () => host.run(setAlign('left'))),
        this.tool('center', 'Centre (Ctrl+E)', icon('alignCenter'), () => host.run(setAlign('center'))),
        this.tool('right', 'Align right (Ctrl+R)', icon('alignRight'), () => host.run(setAlign('right'))),
        this.tool('both', 'Justify (Ctrl+J)', icon('justify'), () => host.run(setAlign('both'))),
      ),
      group(
        this.tool('bullet', 'Bulleted list (Ctrl+Shift+L)', icon('bullets'), () => this.withCtx((ctx) => toggleList(ctx, 'bullet'))),
        this.tool('number', 'Numbered list', icon('numbers'), () => this.withCtx((ctx) => toggleList(ctx, 'number'))),
        this.tool('outdent', 'Decrease indent (Shift+Tab)', icon('outdent'), () => this.withCtx((ctx) => indent(ctx, -1))),
        this.tool('indent', 'Increase indent (Tab)', icon('indent'), () => this.withCtx((ctx) => indent(ctx, 1))),
      ),
      group(
        this.tool('link', 'Link (Ctrl+K)', icon('link'), () => this.linkMenu()),
        this.tool('image', 'Picture', icon('image'), () => host.pickImage()),
        this.tool('table', 'Table', icon('table'), () => this.tableMenu()),
        this.tool('chart', 'Chart', icon('chart'), () => host.editChart()),
        this.tool('shapes', 'Text box and shapes', SHAPES_ICON, () => shapesMenu(this.tools.get('shapes')!, host)),
        this.tool('equation', 'Equation (Alt+=)', EQUATION_ICON, () => equationMenu(this.tools.get('equation')!, host)),
        this.tool('refs', 'Captions, citations, cross-references and table of contents', REFERENCES_ICON, () => referencesMenu(this.tools.get('refs')!, host)),
        this.tool('break', 'Page break (Ctrl+Enter)', icon('pageBreak'), () => host.run(insertPageBreak)),
        this.tool('columns', 'Columns', COLUMNS_ICON, () => columnsMenu(this.tools.get('columns')!, host)),
      ),
      group(
        this.tool('find', 'Find and replace (Ctrl+F)', icon('find'), () => host.toggleFind()),
        this.tool('assist', 'Writing assistant: suggestions and translation (F7)', icon('assist'), () => host.toggleAssist()),
      ),
    );

    overflowMenu(this.el);
    this.tools.get('color')!.append(this.textBar);
    this.tools.get('highlight')!.append(this.markBar);

    // The system's own font list needs a click before it may be asked for. Until then, and
    // where it is refused, the list is the well-known fonts that are installed.
    document.addEventListener('pointerdown', () => void this.loadFonts(), { once: true, capture: true });
  }

  /** The fonts on offer: the system's, once it has handed them over, else the well-known ones installed. */
  get fontNames(): string[] {
    return this.fonts;
  }

  private tool(name: string, title: string, content: string, action: () => void): HTMLButtonElement {
    const button = h('button', { class: 'tool', title, html: content, onclick: action });

    this.tools.set(name, button);
    return button;
  }

  private withCtx(make: (ctx: DocContext) => Command): void {
    const ctx = this.host.tab()?.ctx;
    if (ctx) this.host.run(make(ctx));
  }

  private async loadFonts(): Promise<void> {
    try {
      const query = (window as unknown as { queryLocalFonts?: () => Promise<{ family: string }[]> }).queryLocalFonts;
      const families = query ? [...new Set((await query()).map((font) => font.family))] : [];

      if (families.length > 5) {
        this.fonts = families.sort((a, b) => a.localeCompare(b));
        this.update();
      }
    } catch {
      // Refused: the list stays as it is.
    }
  }

  private vert(value: 'subscript' | 'superscript'): void {
    const state = this.host.tab()?.view.state;
    if (state) this.host.run(setMark(M.vert, toggled(state, M.vert, value) ? null : { value }));
  }

  // ---- Menus ---------------------------------------------------------------------------------

  private colorMenu(kind: 'color' | 'highlight'): void {
    const type = kind === 'color' ? M.color : M.highlight;
    const bar = kind === 'color' ? this.textBar : this.markBar;
    const apply = (value: string | null) => {
      if (value) bar.style.background = value;
      this.host.run(setMark(type, value ? { value } : null));
      closePopover();
    };

    const custom = h('input', { type: 'color', style: 'position:absolute;opacity:0;pointer-events:none;width:0;height:0' });
    custom.addEventListener('change', () => apply(custom.value.toUpperCase()));

    const swatches = h(
      'div',
      { class: 'swatches' },
      ...(kind === 'color' ? TEXT_COLORS : HIGHLIGHT_COLORS).map((value) => h('button', { class: 'swatch', title: value, style: `background:${value}`, onclick: () => apply(value) })),
    );

    popover(
      this.tools.get(kind)!,
      h(
        'div',
        null,
        h('button', { class: 'menu-item', onclick: () => apply(null) }, kind === 'color' ? 'Automatic' : 'No highlight'),
        swatches,
        // Word's highlighter has no other colours; a custom one is written as shading, which Word shows the same.
        h('button', { class: 'menu-item', onclick: () => custom.click() }, 'More colours…'),
        custom,
      ),
    );
  }

  linkMenu(): void {
    const tab = this.host.tab();
    if (!tab) return;

    const existing = linkAt(tab.view.state);
    const field = h('input', { class: 'field', placeholder: 'https://…', value: existing?.mark.attrs.href ?? '', spellcheck: 'false', style: 'width:300px' });
    const apply = () => {
      const href = asHref(field.value);

      closePopover();
      if (href) this.host.run(setLink(tab.ctx, href));
      else if (existing) this.host.run(removeLink(tab.ctx));
      else this.host.focus();
    };

    field.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        apply();
      }
    });

    popover(
      this.tools.get('link')!,
      h(
        'div',
        null,
        h('div', { class: 'field-row' }, field, h('button', { class: 'button primary', onclick: apply }, existing ? 'Change' : 'Add link')),
        existing &&
          h(
            'button',
            {
              class: 'menu-item',
              onclick: () => {
                closePopover();
                this.host.run(removeLink(tab.ctx));
              },
            },
            'Remove link',
          ),
      ),
      () => this.host.focus(),
    );

    field.focus();
    field.select();
  }

  private tableMenu(): void {
    const tab = this.host.tab();
    if (!tab) return;

    const item = (label: string, command: Command) =>
      h(
        'button',
        {
          class: 'menu-item',
          disabled: !command(tab.view.state),
          onclick: () => {
            closePopover();
            this.host.run(command);
          },
        },
        label,
      );

    let content: HTMLElement;

    if (isInTable(tab.view.state)) {
      content = h(
        'div',
        null,
        item('Insert row above', addRowBefore),
        item('Insert row below', addRowAfter),
        item('Insert column left', addColumnBefore),
        item('Insert column right', addColumnAfter),
        h('div', { class: 'menu-sep' }),
        item('Merge cells', mergeCells),
        item('Split cell', splitCell),
        h('div', { class: 'menu-sep' }),
        item('Delete row', deleteRow),
        item('Delete column', deleteColumn),
        item('Delete table', deleteTable),
      );
    } else {
      const size = h('div', { class: 'grid-size' }, 'Insert table');
      const cells: HTMLElement[] = [];
      const grid = h('div', { class: 'grid-picker' });
      const COLS = 8;
      const ROWS = 6;

      for (let i = 0; i < COLS * ROWS; i++) {
        const row = Math.floor(i / COLS) + 1;
        const col = (i % COLS) + 1;
        const cell = h('i', {
          onmouseenter: () => {
            cells.forEach((other, at) => other.classList.toggle('on', Math.floor(at / COLS) < row && at % COLS < col));
            size.textContent = `${col} × ${row}`;
          },
          onclick: () => {
            closePopover();
            this.host.run(insertTable(tab.ctx, row, col));
          },
        });

        cells.push(cell);
        grid.append(cell);
      }

      content = h('div', null, size, grid);
    }

    popover(this.tools.get('table')!, content);
  }

  // ---- Showing the state at the cursor -------------------------------------------------------

  private fill(select: HTMLSelectElement, options: { value: string; label: string }[], shown: string): void {
    select.replaceChildren(...options.map((option) => h('option', { value: option.value }, option.label)));
    select.dataset.shown = shown;
  }

  /** Sets a drop-down to a value, adding the value to it first if the list does not have it. */
  private show(select: HTMLSelectElement, value: string, label: string): void {
    select.querySelector('option[data-extra]')?.remove();

    if (![...select.options].some((option) => option.value === value)) {
      select.prepend(h('option', { value, 'data-extra': '' }, label));
    }

    select.value = value;
  }

  update(): void {
    const tab = this.host.tab();

    for (const control of [this.styleSelect, this.fontSelect, this.sizeInput, ...this.tools.values()]) {
      control.disabled = !tab;
    }

    if (!tab) return;

    const { ctx, view } = tab;
    const state = view.state;
    const paragraph = selectedParagraphs(state)[0]?.node ?? null;
    const styleId: string | null = paragraph?.attrs.styleId ?? null;

    // Styles: rebuilt when another document comes to the front, or a style was added to this one.
    const stylesKey = `${ctx.key}:${ctx.styles.version}`;

    if (this.stylesShown !== stylesKey) {
      const choices = ctx.styles.choices();

      if (!ctx.styles.defaultParagraph) choices.unshift({ value: '', label: 'Normal' });
      this.fill(this.styleSelect, choices, stylesKey);
      if (this.host.styleAction) this.styleSelect.append(...STYLE_ACTIONS.map(([value, label]) => h('option', { value, disabled: !value }, label)));
      this.stylesShown = stylesKey;
    }

    const effective = styleId ?? ctx.styles.defaultParagraph ?? '';
    const def = ctx.styles.byId.get(effective);

    this.show(this.styleSelect, effective, def ? ctx.styles.displayName(def) : effective || 'Normal');

    // Font and size: what is set on the text, or else what its paragraph style gives it.
    const fontsKey = `${this.fonts.length}:${this.fonts[0] ?? ''}`;

    if (this.fontsShown !== fontsKey) {
      this.fill(this.fontSelect, this.fonts.map((name) => ({ value: name, label: name })), fontsKey);
      this.fontsShown = fontsKey;
    }

    const fromStyle = ctx.styles.runOf(styleId);
    const font = markAt(state, M.fontFamily)?.attrs.name ?? fromStyle.font ?? '';
    const size = markAt(state, M.fontSize)?.attrs.size;

    this.show(this.fontSelect, font, font);

    if (document.activeElement !== this.sizeInput) {
      this.sizeInput.value = size ? String(size / 2) : fromStyle.size ? String(fromStyle.size) : '';
    }

    const press = (name: string, on: boolean) => this.tools.get(name)!.setAttribute('aria-pressed', String(on));
    const align: string = paragraph?.attrs.align ?? 'left';
    const place = paragraph ? listOf(paragraph, ctx) : null;
    const kind = place ? ctx.numbering.kindOf(place.numId, place.ilvl) : null;

    press('bold', toggled(state, M.bold));
    press('italic', toggled(state, M.italic));
    press('underline', toggled(state, M.underline));
    press('strike', toggled(state, M.strike));
    press('sub', toggled(state, M.vert, 'subscript'));
    press('sup', toggled(state, M.vert, 'superscript'));
    press('left', align === 'left' || align === 'start');
    press('center', align === 'center');
    press('right', align === 'right' || align === 'end');
    press('both', align === 'both' || align === 'distribute');
    press('bullet', kind === 'bullet');
    press('number', kind === 'number');
    press('link', linkAt(state) !== null);
    press('table', isInTable(state));
    press('chart', selectedChart(state) !== null);

    this.tools.get('undo')!.disabled = undoDepth(state) === 0;
    this.tools.get('redo')!.disabled = redoDepth(state) === 0;
    this.tools.get('break')!.disabled = !insertPageBreak(state);
  }
}
