// The document as separate pages.
//
// The text stays one flow; what makes pages of it is a gap put in wherever a page is full: a
// spacer as tall as the room left on the page, the bottom margin, a strip of desk, and the next
// page's top margin. Between paragraphs the spacer is a block; inside a paragraph that runs over
// the end of a page it is an inline block as wide as the paragraph, so the line after it starts
// the next page. Nothing of it is in the document: the gaps are decorations, and they are
// measured again from the laid-out text whenever the text has settled after a change.
//
// What decides a break, as Word decides it: a page that is full; a page break, a paragraph set to
// start a new page, a section that starts on a new page; a single line left at the bottom or the
// top of a page (widow and orphan control); a heading kept with the paragraph after it. A table
// breaks between its rows, and its heading rows (`w:tblHeader`) are drawn again at the top of
// each page it carries on to; a row is never split. A picture or a row taller than a page runs
// over the end of its page.
//
// A page, then, is made of regions, each of which can be extended on its own:
//   - header:   drawn over the page's top margin by furniture.ts, from the section's header part;
//   - body:     the stretch of the one flow between two gaps, measured here (`measureGaps`);
//   - footnote area: at the bottom of the body. A line that refers to a footnote fits on its page
//     only with the note under it, so each page's footnotes shorten its body; furniture.ts draws
//     them above the footer (src/notes/view.ts has the notes themselves);
//   - footer:   drawn over the bottom margin by furniture.ts;
// and between two pages, the strip of desk, also drawn by furniture.ts. `measureGaps` reports
// for each page the section it starts in, which is what picks its header, footer and number.

import type { Node as PMNode } from 'prosemirror-model';
import { type EditorState, Plugin, PluginKey } from 'prosemirror-state';
import { TableMap } from 'prosemirror-tables';
import { Decoration, DecorationSet, type EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { isOn } from '../docx/props';
import { child, parseFragment } from '../docx/xml';
import { notesViewOf } from '../notes/view';
import { flowColumns } from '../columns/flow';
import { type RunLayout, layoutContinuous, measureRun, placeRun, runAnchor, runsIn, sectionRangesIn, setLayouts, startMeasure } from '../columns/view';
import { PageFurniture } from './furniture';
import { schema } from './schema';

const N = schema.nodes;

/** The strip of desk between two pages, in CSS pixels at 100%. */
export const PAGE_GAP = 24;

/** The line above a page's footnotes, with the room around it (src/styles/notes.css, `.foot-sep`). */
export const FOOT_SEPARATOR = 11;

export interface PageGap {
  /** Where the spacer goes: before a block, before the first character of a line, or before a table row. */
  pos: number;
  inline: boolean;
  height: number;
  /** The number of the page that starts after this gap. */
  page: number;
  /** For a gap between table rows: how many columns the row spans, and the heading rows drawn again under it. */
  row?: { cols: number; repeat: HTMLElement | null };
}

interface PagesState {
  gaps: readonly PageGap[];
  count: number;
  decorations: DecorationSet;
}

export const pagesKey = new PluginKey<PagesState>('pages');

const EMPTY: PagesState = { gaps: [], count: 1, decorations: DecorationSet.empty };

function gapDom(gap: PageGap): HTMLElement {
  if (gap.row) {
    // Between table rows: a row of its own, one cell across, with the heading rows at its foot.
    const tr = document.createElement('tr');
    const td = document.createElement('td');
    const spacer = document.createElement('div');

    tr.className = 'page-gap-row';
    tr.contentEditable = 'false';
    tr.setAttribute('aria-hidden', 'true');
    td.colSpan = gap.row.cols;
    spacer.className = 'page-gap';
    spacer.style.height = `${gap.height}px`;
    td.append(spacer);
    if (gap.row.repeat) td.append(gap.row.repeat.cloneNode(true));
    tr.append(td);
    return tr;
  }

  const el = document.createElement(gap.inline ? 'span' : 'div');

  el.className = gap.inline ? 'page-gap inline' : 'page-gap';
  el.contentEditable = 'false';
  el.setAttribute('aria-hidden', 'true');
  el.style.height = `${gap.height}px`;
  return el;
}

function decorate(doc: PMNode, gaps: readonly PageGap[]): DecorationSet {
  return DecorationSet.create(
    doc,
    gaps.map((gap) =>
      Decoration.widget(gap.pos, () => gapDom(gap), {
        side: -1,
        ignoreSelection: true,
        page: gap.page,
        // The same gap is not drawn again when nothing about it changed.
        key: `page:${gap.row ? 'r' : gap.inline ? 'i' : 'b'}:${gap.page}:${gap.height.toFixed(1)}:${gap.row?.repeat ? gap.row.repeat.childElementCount : 0}`,
      }),
    ),
  );
}

export function pagesPlugin(): Plugin<PagesState> {
  return new Plugin<PagesState>({
    key: pagesKey,
    state: {
      init: () => EMPTY,
      apply(tr, old) {
        const meta = tr.getMeta(pagesKey) as { gaps: PageGap[]; count: number } | undefined;

        if (meta) return meta.gaps.length ? { gaps: meta.gaps, count: meta.count, decorations: decorate(tr.doc, meta.gaps) } : EMPTY;
        if (tr.docChanged && old.gaps.length) return { ...old, decorations: old.decorations.map(tr.mapping, tr.doc) };

        return old;
      },
    },
    props: {
      decorations: (state) => pagesKey.getState(state)?.decorations,
    },
  });
}

/** Which page the cursor is on, and how many there are; null when the document is not shown as pages. */
export function pageAt(state: EditorState): { page: number; count: number } | null {
  const pages = pagesKey.getState(state);
  if (!pages || !pages.gaps.length) return null;

  const head = state.selection.head;
  let page = 1;

  for (const gap of pages.decorations.find()) {
    if (gap.from <= head) page = Math.max(page, (gap.spec.page as number) ?? 1);
  }

  return { page, count: pages.count };
}

/** The page a document position is on, given where the pages break (the plugin's gaps, or `measureGaps`'s). */
export function pageOfPos(gaps: readonly PageGap[], pos: number): number {
  let page = 1;

  for (const gap of gaps) if (gap.pos <= pos) page = Math.max(page, gap.page);
  return page;
}

// ---- What the document asks for ---------------------------------------------------------------

/** Whether a paragraph is kept on the same page as the one after it: its own setting, or its style's. */
function keepsWithNext(ctx: DocContext, node: PMNode): boolean {
  if (node.type !== N.paragraph) return false;

  const own = child(parseFragment(node.attrs.ppr), 'w:keepNext');
  if (own) return isOn(own);

  const chain = ctx.styles.chain(node.attrs.styleId ?? ctx.styles.defaultParagraph);

  for (let i = chain.length - 1; i >= 0; i--) {
    const keep = child(chain[i].pPr, 'w:keepNext');
    if (keep) return isOn(keep);
  }

  return false;
}

/** Whether a table row is a heading row, drawn again at the top of each page the table carries on to. */
export function isHeadingRow(row: PMNode): boolean {
  return /<w:tblHeader\b(?![^>]*w:val="(?:0|false|off)")/.test(row.attrs.trPr ?? '');
}

/** Whether a paragraph ends a section after which the next one starts on a new page. */
function endsSectionWithPage(node: PMNode): boolean {
  const sectPr: string | null = node.type === N.paragraph ? node.attrs.sectPr : null;
  return !!sectPr && !/<w:type\s+w:val="continuous"/.test(sectPr);
}

// ---- Measuring -------------------------------------------------------------------------------

interface LineBox {
  /** In the editor's own pixels, from its top. */
  top: number;
  bottom: number;
  /** In the window's pixels: a point on the line's first character. */
  x: number;
  y: number;
}

/** The lines a paragraph is laid out in, from the boxes of its text. */
export function lineBoxes(dom: HTMLElement, toY: (clientY: number) => number): LineBox[] {
  const range = document.createRange();
  range.selectNodeContents(dom);

  const rects = [...range.getClientRects()].filter((r) => r.height >= 2 && r.width > 0).sort((a, b) => a.top - b.top || a.left - b.left);
  const lines: { top: number; bottom: number; left: number }[] = [];

  for (const r of rects) {
    const line = lines[lines.length - 1];

    if (line && r.top < line.bottom - 2) {
      line.bottom = Math.max(line.bottom, r.bottom);
      line.top = Math.min(line.top, r.top);
      line.left = Math.min(line.left, r.left);
    } else {
      lines.push({ top: r.top, bottom: r.bottom, left: r.left });
    }
  }

  return lines.map((l) => ({ top: toY(l.top), bottom: toY(l.bottom), x: l.left + 1, y: (l.top + l.bottom) / 2 }));
}

/** A block as laid out without any gaps. */
interface Placed {
  pos: number;
  node: PMNode;
  dom: HTMLElement;
  top: number;
  bottom: number;
  marginTop: number;
  marginBottom: number;
  /** Where the block before it ends, and its bottom margin; null for the first block in its container. */
  prevBottom: number | null;
  prevMargin: number;
  keepNext: boolean;
}

/**
 * Works out where the pages break in a view laid out without gaps. Every measure is in the
 * editor's own pixels, which are the page's at 100%; the page's zoom is taken out.
 */
export function measureGaps(
  view: EditorView,
  ctx: DocContext,
  zoom: number,
  /** For the last page of the ones listed by section: how much a footer taller than the bottom margin takes off its body. */
  footerClearance: (pageSections: readonly number[]) => number = () => 0,
): { gaps: PageGap[]; count: number; sections: number[]; notes: string[][]; columns: (RunLayout | null)[] } {
  const page = ctx.page;
  const contentHeight = Math.max(100, page.height - page.top - page.bottom);
  const pitch = page.height + PAGE_GAP;
  const origin = view.dom.getBoundingClientRect();
  const toY = (clientY: number) => (clientY - origin.top) / zoom;

  const gaps: PageGap[] = [];
  let shift = 0;
  let pageNo = 0;
  let forceNext = false;
  let prev: Placed | null = null;
  /** The section each page starts in; a paragraph with section properties ends one. */
  let section = 0;
  const sections = [0];

  const pageStart = () => pageNo * pitch;
  /** The height of this page's body, short of a footer that is taller than the bottom margin. */
  let bodyHeight = Math.max(20, contentHeight - footerClearance(sections));

  // Footnotes: each reference's note takes room at the foot of the page the reference is on.
  const notesView = notesViewOf(view);
  const foot = notesView?.footnotes(toY, Math.max(20, page.width - page.left - page.right), zoom) ?? [];

  // Multi-column sections (src/columns/view.ts): their blocks are placed by the column flow.
  // Notes referred to in them are counted there, not by where the reference was measured.
  const ranges = sectionRangesIn(view.state);
  const runs = runsIn(view.state);
  const columns: (RunLayout | null)[] = runs.map(() => null);
  const inRun = (pos: number) => runs.find((r) => pos >= r.range.from && pos < r.range.to) ?? null;
  for (const f of foot) if (inRun(f.pos)) f.y = Infinity;
  /** The first footnote not yet on a page, and the first on this one. */
  let fi = 0;
  let pageFirst = 0;
  let footHeight = 0;
  const pageNotes: number[] = [0];

  /** Whether text down to `bottom` (laid out without gaps) fits on this page, with the footnotes it refers to. */
  const fits = (bottom: number) => {
    let extra = 0;
    let j = fi;
    while (j < foot.length && foot[j].y < bottom) extra += foot[j++].height;

    const room = footHeight + extra ? footHeight + extra + FOOT_SEPARATOR : 0;
    if (bottom + shift > pageNo * pitch + bodyHeight - room) return false;

    footHeight += extra;
    fi = j;
    return true;
  };

  /** Text from `y` on goes onto the next page, and the footnotes it refers to with it. */
  const cutNotes = (y: number) => {
    while (fi > pageFirst && foot[fi - 1].y >= y) footHeight -= foot[--fi].height;
  };

  const nextPage = () => {
    pageNo++;
    sections.push(section);
    bodyHeight = Math.max(20, contentHeight - footerClearance(sections));
    pageFirst = fi;
    footHeight = 0;
    pageNotes.push(fi);
  };

  /** A gap before a block, which then starts the next page. */
  const breakBefore = (block: Placed) => {
    const target = (pageNo + 1) * pitch;
    // The spacer stands between the two blocks, so their margins no longer collapse into one.
    const spacerTop = block.prevBottom !== null ? block.prevBottom + shift + block.prevMargin : block.top + shift - block.marginTop;
    const height = Math.max(0, target - block.marginTop - spacerTop);

    cutNotes(block.top);
    gaps.push({ pos: block.pos, inline: false, height, page: pageNo + 2 });
    shift = target - block.top;
    nextPage();
  };

  /** A gap before a line, which then starts the next page. `lineTop` is where the line's box starts. */
  const breakInside = (pos: number, lineTop: number) => {
    const target = (pageNo + 1) * pitch;
    const spacerTop = lineTop + shift;

    cutNotes(lineTop);
    gaps.push({ pos, inline: true, height: Math.max(0, target - spacerTop), page: pageNo + 2 });
    shift = target - lineTop;
    nextPage();
  };

  const atPageTop = (top: number) => top + shift <= pageStart() + 1;

  /** Moves a block to the next page, or the heading before it along with it. */
  const moveBlock = (block: Placed) => {
    if (prev && prev !== block && prev.keepNext && !atPageTop(prev.top) && prev.top + shift >= pageStart()) breakBefore(prev);
    else breakBefore(block);
  };

  const placeParagraph = (block: Placed) => {
    const { node, dom, pos } = block;
    const forced: { pos: number; y: number }[] = [];

    // Page breaks inside the paragraph. One at its end makes the next block start a page.
    node.forEach((inline, offset) => {
      if (inline.type !== N.page_break || inline.attrs.column) return;

      let textAfter = false;
      node.nodesBetween(offset + inline.nodeSize, node.content.size, (n) => {
        if (n.isText || n.type === N.image || n.type === N.chart || n.type === N.math) textAfter = true;
        return !textAfter;
      });

      if (!textAfter) {
        forceNext = true;
        return;
      }

      const el = view.nodeDOM(pos + 1 + offset);
      if (!(el instanceof HTMLElement)) return;

      const after = parseFloat(getComputedStyle(el).marginBottom) || 0;
      forced.push({ pos: pos + 1 + offset + inline.nodeSize, y: toY(el.getBoundingClientRect().bottom) + after });
    });

    if (!forced.length && fits(block.bottom)) return;

    const lines = lineBoxes(dom, toY);
    const end = pos + node.nodeSize - 1;
    let last = pos + 1;
    let moved = false;
    let f = 0;

    const lineStart = (line: LineBox) => {
      const hit = view.posAtCoords({ left: line.x, top: line.y });
      return hit && hit.pos > last && hit.pos < end ? hit.pos : null;
    };

    for (let k = 0; k < lines.length; k++) {
      while (f < forced.length && forced[f].y <= lines[k].top + 1) {
        if (!atPageTop(forced[f].y)) {
          breakInside(forced[f].pos, forced[f].y);
          last = forced[f].pos;
        }
        f++;
      }

      const line = lines[k];

      if (fits(line.bottom)) continue;
      // A line taller than a page, a big picture say: nothing can be done about it.
      if (atPageTop(line.top)) continue;

      let at = k;

      // Not one line alone at the bottom of a page, and not one alone at the top of the next.
      if (at === 1 && lines.length > 2) at = 0;
      else if (at === lines.length - 1 && at >= 2) at -= 1;

      if (at === 0 || lines[at].top + shift <= pageStart() + 1) {
        // Moved whole, unless a page break inside it has already started a page in it.
        if (!moved && last === pos + 1 && !atPageTop(block.top)) {
          moved = true;
          moveBlock(block);
          k = -1;
          continue;
        }

        // It starts the page already: break where it runs over, however short that leaves it.
        at = Math.max(1, k);
      }

      const start = lineStart(lines[at]);
      if (start === null) continue;

      breakInside(start, (lines[at - 1].bottom + lines[at].top) / 2);
      last = start;
      k = at;
    }
  };

  /** A table that runs over the end of its page breaks before the first row that does not fit. */
  const placeTable = (block: Placed) => {
    if (fits(block.bottom)) return;

    const rows: { pos: number; el: HTMLElement; top: number; bottom: number; heading: boolean }[] = [];

    block.node.forEach((row, offset) => {
      const el = view.nodeDOM(block.pos + 1 + offset);
      if (!(el instanceof HTMLElement)) return;

      const rect = el.getBoundingClientRect();
      rows.push({ pos: block.pos + 1 + offset, el, top: toY(rect.top), bottom: toY(rect.bottom), heading: isHeadingRow(row) });
    });

    let heads = 0;
    while (heads < rows.length && rows[heads].heading) heads++;
    // A table of nothing but heading rows has nothing to repeat them over.
    if (heads === rows.length) heads = 0;

    const tableEl = rows[0]?.el.closest('table');
    const cols = TableMap.get(block.node).width;
    let repeat: HTMLElement | null = null;
    let repeatHeight = 0;

    if (heads && tableEl) {
      repeat = document.createElement('table');
      repeat.className = `${tableEl.className} page-repeat`;
      repeat.dataset.tstyle = tableEl.dataset.tstyle ?? '';
      repeat.style.width = `${tableEl.getBoundingClientRect().width / zoom}px`;

      const colgroup = tableEl.querySelector(':scope > colgroup');
      const body = document.createElement('tbody');

      if (colgroup) repeat.append(colgroup.cloneNode(true));
      for (const row of rows.slice(0, heads)) body.append(row.el.cloneNode(true));
      repeat.append(body);
      repeat.querySelectorAll('[contenteditable]').forEach((el) => el.removeAttribute('contenteditable'));
      repeatHeight = rows[heads - 1].bottom - rows[0].top;
    }

    let moved = false;

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i];

      if (fits(row.bottom)) continue;
      // A row taller than a page: nothing can be done about it.
      if (atPageTop(row.top)) continue;

      // Not even the first row after the headings fits: the table starts on the next page.
      if (i <= heads) {
        if (!moved && !atPageTop(block.top)) {
          moved = true;
          moveBlock(block);
          i = -1;
        }
        continue;
      }

      const target = (pageNo + 1) * pitch;
      const height = Math.max(0, target - (row.top + shift));

      cutNotes(row.top);
      gaps.push({ pos: row.pos, inline: false, height, page: pageNo + 2, row: { cols, repeat } });
      shift = target + repeatHeight - row.top;
      nextPage();
    }
  };

  /** Notes pushed onto the next page, by a top margin set once everything is measured. */
  const pushed: { el: HTMLElement; margin: number }[] = [];

  const placeNotes = (area: HTMLElement) => {
    const items = [...area.children] as HTMLElement[];

    items.forEach((el, i) => {
      if (el.classList.contains('notes-title')) return;

      // The heading goes with the first note.
      const first = i > 0 && items[i - 1].classList.contains('notes-title') ? items[i - 1] : el;
      const top = toY(first.getBoundingClientRect().top);
      const bottom = toY(el.getBoundingClientRect().bottom);
      if (fits(bottom) || atPageTop(top) || bottom - top > contentHeight) return;

      const target = (pageNo + 1) * pitch;
      pushed.push({ el: first, margin: target - (top + shift) });
      shift = target - top;
      nextPage();
    });
  };

  const place = (node: PMNode, pos: number, dom: HTMLElement) => {
    const rect = dom.getBoundingClientRect();
    if (rect.height < 1) return;

    const style = getComputedStyle(dom);
    const block: Placed = {
      pos,
      node,
      dom,
      top: toY(rect.top),
      bottom: toY(rect.bottom),
      marginTop: parseFloat(style.marginTop) || 0,
      marginBottom: parseFloat(style.marginBottom) || 0,
      prevBottom: prev && prev.dom.parentElement === dom.parentElement ? prev.bottom : null,
      prevMargin: prev?.marginBottom ?? 0,
      keepNext: keepsWithNext(ctx, node),
    };

    if ((forceNext || dom.classList.contains('pbb')) && !atPageTop(block.top)) breakBefore(block);
    forceNext = false;

    if (node.type === N.paragraph) {
      placeParagraph(block);
    } else if (node.type === N.table) {
      placeTable(block);
    } else if (!fits(block.bottom) && !atPageTop(block.top) && block.bottom - block.top <= contentHeight) {
      moveBlock(block);
    }

    // Endnotes drawn after this block (src/notes/view.ts): a note that does not fit starts the next page.
    for (let sib = dom.nextElementSibling; sib instanceof HTMLElement && sib.classList.contains('notes-area'); sib = sib.nextElementSibling) {
      if (sib.classList.contains('notes-end')) placeNotes(sib);
    }

    if (node.type === N.paragraph && node.attrs.sectPr) {
      // How the next section starts is its own w:type (ECMA-376 17.6.22).
      const next = ranges[section + 1];
      if (next ? next.type !== 'continuous' : endsSectionWithPage(node)) forceNext = true;
      section++;
    }
    prev = block;
  };

  /** A multi-column section: its blocks poured into columns, page by page. */
  const placeRunOnPages = (run: (typeof runs)[number]) => {
    const anchor = runAnchor(view, run, toY);

    if (forceNext && !atPageTop(anchor)) {
      const target = (pageNo + 1) * pitch;
      gaps.push({ pos: run.blocks[0].pos, inline: false, height: Math.max(0, target - (anchor + shift)), page: pageNo + 2 });
      shift = target - anchor;
      nextPage();
    }
    forceNext = false;

    const startPage = pageNo;
    let n = fi;
    while (n < foot.length && foot[n].pos < run.range.to) n++;
    const runNotes = foot.slice(fi, n);
    const blocks = measureRun(view, run, toY, runNotes);
    const next = ranges[run.range.index + 1];
    const flow = flowColumns(blocks, {
      cols: run.range.cols.count,
      startY: anchor + shift - pageNo * pitch,
      bodyHeight: (k) => (k === 0 ? bodyHeight : Math.max(20, contentHeight - footerClearance([...sections, ...Array<number>(k).fill(section)]))),
      footUsed: footHeight,
      footSep: FOOT_SEPARATOR,
      balance: next?.type === 'continuous',
    });
    const pageOfNote = (pos: number) => flow.placements[run.blocks.findIndex((b) => pos >= b.pos && pos < b.pos + b.node.nodeSize)]?.page ?? 0;

    flow.pages.forEach((pg, p) => {
      if (p > 0) nextPage();
      footHeight += pg.foot;
      while (fi < n && pageOfNote(foot[fi].pos) <= p) fi++;
    });

    const layout = placeRun(run, blocks, flow, ctx, (p) => (startPage + p) * pitch);
    const last = flow.pages[flow.pages.length - 1];
    layout.spacer = Math.max(0, pageNo * pitch + (last?.bottom ?? 0) - (anchor + shift));
    shift += layout.spacer + layout.after;
    columns[run.index] = layout;
    prev = null;

    if (next) {
      section++;
      forceNext = next.type !== 'continuous';
    }
  };

  const walk = (parent: PMNode, base: number) => {
    parent.forEach((node, offset) => {
      const pos = base + offset;

      const run = parent === view.state.doc ? inRun(pos) : null;
      if (run) {
        if (pos === run.blocks[0].pos) placeRunOnPages(run);
        return;
      }

      // A wrapper around blocks (a content control) breaks between the blocks inside it.
      if (node.type === N.block_wrap) return walk(node, pos + 1);

      const dom = view.nodeDOM(pos);
      if (dom instanceof HTMLElement) place(node, pos, dom);
    });
  };

  walk(view.state.doc, 0);

  for (const { el, margin } of pushed) el.style.marginTop = `${margin}px`;

  // Footnotes still left over (a reference on a line taller than a page) go on the last page.
  pageNotes.push(fi);
  const notes = pageNotes.slice(1).map((end, k) => foot.slice(pageNotes[k], end).map((f) => f.id));
  notes[notes.length - 1].push(...foot.slice(fi).map((f) => f.id));

  const pageOf = new Map<number, number>();
  notes.forEach((ids, k) => ids.forEach((id) => {
    const f = foot.find((x) => x.id === id);
    if (f) pageOf.set(f.pos, k);
  }));
  notesView?.pagesMeasured(pageOf);

  return { gaps, count: pageNo + 1, sections, notes, columns };
}

// ---- Keeping the pages up to date --------------------------------------------------------------

/** Lays one document out as pages while that is switched on, and again whenever its text settles. */
export class Paginator {
  private enabled = false;
  private stale = true;
  private timer = 0;
  /** What is drawn around the text on each page: headers, footers, the desk between pages. */
  readonly furniture: PageFurniture;

  constructor(
    private readonly view: EditorView,
    private readonly ctx: DocContext,
    /** The `.page` element the editor is in; its zoom is the page's. */
    private readonly pageEl: HTMLElement,
  ) {
    this.furniture = new PageFurniture(view, ctx, pageEl);
    // A note edited or made changes how much room the footnotes take.
    const notes = notesViewOf(view);
    if (notes) notes.onLayout = () => this.schedule(0);
  }

  get isEnabled(): boolean {
    return this.enabled;
  }

  private get contentHeight(): number {
    const page = this.ctx.page;
    return Math.max(100, page.height - page.top - page.bottom);
  }

  setEnabled(on: boolean): void {
    if (on === this.enabled && !this.stale) return;

    this.enabled = on;
    this.run();
  }

  /** The text changed: lay it out again once it has been left alone for a moment. */
  schedule(delay = 300): void {
    this.stale = true;
    // The continuous view lays out multi-column sections too.
    if (!this.enabled && !runsIn(this.view.state).length) return;

    clearTimeout(this.timer);
    this.timer = window.setTimeout(() => this.run(), delay);
  }

  run(): void {
    clearTimeout(this.timer);

    const view = this.view;
    if (view.isDestroyed) return;

    const had = pagesKey.getState(view.state)?.gaps.length ?? 0;

    if (!this.enabled) {
      if (had) view.dispatch(view.state.tr.setMeta(pagesKey, { gaps: [], count: 1 }));
      view.dom.style.minHeight = `${this.contentHeight}px`;
      this.pageEl.classList.remove('paged');
      this.furniture.clear();
      this.stale = true;
      if (view.dom.isConnected && view.dom.getClientRects().length && !view.composing) {
        layoutContinuous(view, this.ctx, parseFloat(getComputedStyle(this.pageEl).zoom) || 1);
      }
      return;
    }

    // A document in a tab that is not in front has no layout to measure; it is done when it comes forward.
    if (!view.dom.isConnected || view.dom.getClientRects().length === 0) {
      this.stale = true;
      return;
    }

    // Redrawing around the cursor would break up a word being composed (an IME, a dead key).
    if (view.composing) {
      this.schedule();
      return;
    }

    const scroller = this.pageEl.closest<HTMLElement>('.desk');
    const scrollTop = scroller?.scrollTop ?? 0;
    const zoom = parseFloat(getComputedStyle(this.pageEl).zoom) || 1;

    // Measured without the old gaps; both changes happen before anything is drawn. The editor
    // keeps its height meanwhile, so the window does not scroll.
    if (had) view.dispatch(view.state.tr.setMeta(pagesKey, { gaps: [], count: 1 }));

    notesViewOf(view)?.resetLayout();
    startMeasure(view);
    const { gaps, count, sections, notes, columns } = measureGaps(view, this.ctx, zoom, (s) => this.furniture.footerClearance(s));
    const page = this.ctx.page;

    view.dispatch(view.state.tr.setMeta(pagesKey, { gaps, count }));
    setLayouts(view, columns);
    view.dom.style.minHeight = `${(count - 1) * (page.height + PAGE_GAP) + this.contentHeight}px`;
    this.pageEl.classList.add('paged');
    this.furniture.draw(sections, notes);
    notesViewOf(view)?.laidOut();

    if (scroller) scroller.scrollTop = scrollTop;
    this.stale = false;
  }

  destroy(): void {
    clearTimeout(this.timer);
    this.furniture.destroy();
  }
}
