// Saved searches: a recipe names what to look for (text, a pattern or a regular expression, and
// the formatting it must have) and what to do with every match (format it, replace it, or both).
// Running one is a single step to undo.

import type { Command } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { type FindMode, type FindTarget, replaceMatches, search, targetSpans } from './find';
import { type FormatAction, formatSpans } from './format';
import { cleanFilter, type FormatFilter, type StyleRuns } from './formatmatch';

/** A format action that can be written down: a paragraph style by its id or `builtin:<name>`. */
export type RecipeFormat = Exclude<FormatAction, { kind: 'style' }> | { kind: 'style'; value: string };

export interface Recipe {
  id: string;
  name: string;
  mode: FindMode;
  query: string;
  matchCase: boolean;
  /** The formatting matches must have, or null for any. */
  filter: FormatFilter | null;
  /** What each match is replaced with, or null to leave the text as it is. */
  replace: string | null;
  /** The formatting given to every match, or null for none. */
  format: RecipeFormat | null;
  /** Whether the formatting goes on the whole match or only on its variables. */
  target: FindTarget;
}

export const BUILTIN_RECIPES: readonly Recipe[] = [
  {
    id: 'builtin-italic-brackets',
    name: 'Italicise bracketed text',
    mode: 'pattern',
    query: '(*)',
    matchCase: false,
    filter: null,
    replace: null,
    format: { kind: 'toggle', mark: 'italic', on: true },
    target: 'variables',
  },
  {
    id: 'builtin-bold-figures',
    name: 'Bold every Figure #',
    mode: 'pattern',
    query: 'Figure #',
    matchCase: true,
    filter: null,
    replace: null,
    format: { kind: 'toggle', mark: 'bold', on: true },
    target: 'match',
  },
  {
    id: 'builtin-double-spaces',
    name: 'Collapse double spaces',
    mode: 'regex',
    query: ' {2,}',
    matchCase: false,
    filter: null,
    replace: ' ',
    format: null,
    target: 'match',
  },
  {
    id: 'builtin-straight-quotes',
    name: 'Curly quotes for "straight" ones',
    mode: 'pattern',
    query: '"*"',
    matchCase: false,
    filter: null,
    replace: '“$1”',
    format: null,
    target: 'match',
  },
];

// ---- Keeping them ------------------------------------------------------------------------------

const MODES: FindMode[] = ['text', 'pattern', 'regex'];
const FORMAT_KINDS = ['toggle', 'vert', 'set', 'clear', 'style'];

/** A recipe as read back from storage, or null if it is not one. */
function readRecipe(value: unknown): Recipe | null {
  if (!value || typeof value !== 'object') return null;

  const r = value as Record<string, unknown>;
  if (typeof r.id !== 'string' || typeof r.name !== 'string' || typeof r.query !== 'string') return null;

  const format = r.format && typeof r.format === 'object' && FORMAT_KINDS.includes((r.format as { kind: string }).kind) ? (r.format as RecipeFormat) : null;

  return {
    id: r.id,
    name: r.name,
    mode: MODES.includes(r.mode as FindMode) ? (r.mode as FindMode) : 'text',
    query: r.query,
    matchCase: r.matchCase === true,
    filter: cleanFilter(r.filter as FormatFilter | null),
    replace: typeof r.replace === 'string' ? r.replace : null,
    format,
    target: r.target === 'variables' ? 'variables' : 'match',
  };
}

/** The recipes kept in settings; the built-in ones when none were ever kept. */
export function parseRecipes(json: string | null): Recipe[] {
  if (json === null) return BUILTIN_RECIPES.map((r) => ({ ...r }));

  try {
    const list = JSON.parse(json);
    return Array.isArray(list) ? list.map(readRecipe).filter((r): r is Recipe => r !== null) : [];
  } catch {
    return BUILTIN_RECIPES.map((r) => ({ ...r }));
  }
}

export const serializeRecipes = (recipes: readonly Recipe[]): string => JSON.stringify(recipes);

export function newRecipeId(existing: readonly Recipe[]): string {
  let n = existing.length + 1;
  while (existing.some((r) => r.id === `recipe-${n}`)) n++;
  return `recipe-${n}`;
}

export function addRecipe(recipes: readonly Recipe[], recipe: Omit<Recipe, 'id'>): Recipe[] {
  return [...recipes, { ...recipe, filter: cleanFilter(recipe.filter), id: newRecipeId(recipes) }];
}

export function renameRecipe(recipes: readonly Recipe[], id: string, name: string): Recipe[] {
  const trimmed = name.trim();
  return trimmed ? recipes.map((r) => (r.id === id ? { ...r, name: trimmed } : r)) : [...recipes];
}

export function deleteRecipe(recipes: readonly Recipe[], id: string): Recipe[] {
  return recipes.filter((r) => r.id !== id);
}

/** Puts back the built-in recipes that were deleted, after the user's own. */
export function restoreBuiltins(recipes: readonly Recipe[]): Recipe[] {
  return [...recipes, ...BUILTIN_RECIPES.filter((b) => !recipes.some((r) => r.id === b.id)).map((r) => ({ ...r }))];
}

// ---- Running one ---------------------------------------------------------------------------------

/** The recipe's format action for a document, or null if there is none. */
export function formatActionOf(format: RecipeFormat | null, ctx: DocContext | null): FormatAction | null {
  if (!format) return null;
  if (format.kind !== 'style') return format;
  return ctx ? { kind: 'style', ctx, value: format.value } : null;
}

export interface RecipeResult {
  matches: number;
  error: string | null;
}

/**
 * Runs a recipe on a document: formats every match, then replaces it. Formatting first, so that a
 * replacement that puts a variable back (`$1`) keeps the formatting just given.
 */
export function runRecipe(recipe: Recipe, ctx: DocContext | null, styles: StyleRuns | null, result?: (r: RecipeResult) => void): Command {
  return (state, dispatch) => {
    const found = search(state.doc, recipe.query, recipe.matchCase, recipe.mode, recipe.filter, styles);

    result?.({ matches: found.matches.length, error: found.error });
    if (found.error || !found.matches.length) return false;

    const action = formatActionOf(recipe.format, ctx);
    if (!action && recipe.replace === null) return false;
    if (!dispatch) return true;

    let tr = state.tr;

    if (action) {
      const target = recipe.mode === 'text' ? 'match' : recipe.target;
      formatSpans(targetSpans(found.matches, target), action)(state, (formatted) => (tr = formatted));
    }

    // Formatting moves no text, so the matches are where they were; the replacement copies the
    // variables from the document as it is now, formatting and all.
    if (recipe.replace !== null) replaceMatches(tr, found.matches, recipe.replace, recipe.mode);

    if (!tr.docChanged) return false;

    dispatch(tr.scrollIntoView());
    return true;
  };
}
