// A document's sources and citation style. Read from the bibliography part the first time they
// are asked for, and written back into it when the document is saved, only if they changed.

import type { DocContext } from '../docx/import';
import { REL_TYPE, addContentTypes, addRels, parseRels, relsPathFor, type DocxPackage } from '../docx/package';
import { addPartWriter } from '../docx/part-writers';
import { escAttr } from '../docx/xml';
import { type Source, identity, newTag } from './model';
import { BIB_NS, isSourcesXml, readSources, writeSources } from './sources-xml';
import type { StyleId } from './styles';

export interface Library {
  sources: Source[];
  style: StyleId;
  /** Where the sources were read from; null when the document has no bibliography part yet. */
  part: string | null;
  attrs: Record<string, string>;
  open: string | null;
  changed: boolean;
}

const libraries = new WeakMap<DocContext, Library>();
const listeners = new WeakMap<DocContext, Set<() => void>>();

/** Word's names for its styles, on the root of the sources part. */
const WORD_STYLES: Record<StyleId, Record<string, string>> = {
  apa: { SelectedStyle: '\\APASixthEditionOfficeOnline.xsl', StyleName: 'APA', Version: '6' },
  mla: { SelectedStyle: '\\MLASeventhEditionOfficeOnline.xsl', StyleName: 'MLA', Version: '7' },
  chicago: { SelectedStyle: '\\Chicago.XSL', StyleName: 'Chicago', Version: '16' },
  // Word has no notes style of its own; its Chicago one is the nearest. Citations in footnotes tell them apart.
  'chicago-nb': { SelectedStyle: '\\Chicago.XSL', StyleName: 'Chicago', Version: '16' },
};

function styleFrom(attrs: Record<string, string>): StyleId {
  const name = `${attrs.StyleName ?? ''} ${attrs.SelectedStyle ?? ''}`;
  if (/mla/i.test(name)) return 'mla';
  if (/chicago/i.test(name)) return 'chicago';
  return 'apa';
}

/** Chicago with its citations in footnotes is the notes and bibliography style. */
function notesStyle(ctx: DocContext, style: StyleId): StyleId {
  if (style !== 'chicago') return style;
  const notes = [...ctx.pkg.files.keys()].find((name) => /(^|\/)footnotes\.xml$/.test(name));
  return notes && /<w:instrText[^>]*>\s*CITATION\b/.test(ctx.pkg.text(notes) ?? '') ? 'chicago-nb' : style;
}

/** The bibliography part in a package, if there is one. */
function findPart(pkg: DocxPackage): string | null {
  for (const path of pkg.files.keys()) {
    if (!/^customXml\/item\d+\.xml$/i.test(path)) continue;
    const text = pkg.text(path);
    if (text && isSourcesXml(text)) return path;
  }
  return null;
}

export function library(ctx: DocContext): Library {
  let lib = libraries.get(ctx);
  if (lib) return lib;

  const part = findPart(ctx.pkg);
  const read = part ? readSources(ctx.pkg.text(part)!) : null;
  lib = {
    sources: read?.sources ?? [],
    style: notesStyle(ctx, styleFrom(read?.attrs ?? {})),
    part,
    attrs: read?.attrs ?? {},
    open: read?.open ?? null,
    changed: false,
  };
  libraries.set(ctx, lib);
  return lib;
}

export function onSourcesChanged(ctx: DocContext, listener: () => void): void {
  const set = listeners.get(ctx) ?? new Set();
  set.add(listener);
  listeners.set(ctx, set);
}

function changed(ctx: DocContext): void {
  library(ctx).changed = true;
  for (const listener of listeners.get(ctx) ?? []) listener();
}

export const findSource = (ctx: DocContext, tag: string): Source | null =>
  library(ctx).sources.find((s) => s.tag.toLowerCase() === tag.toLowerCase()) ?? null;

/** Adds a source, or replaces the one with the same tag. Gives it a tag if it has none. */
export function saveSource(ctx: DocContext, source: Source, replacing: string | null = null): Source {
  const lib = library(ctx);
  const others = lib.sources.filter((s) => s.tag !== replacing);
  const fresh: Source = { ...source, raw: undefined };
  if (!fresh.tag || others.some((s) => s.tag.toLowerCase() === fresh.tag.toLowerCase())) fresh.tag = newTag(fresh, others.map((s) => s.tag));
  if (!fresh.fields.Guid) fresh.fields = { ...fresh.fields, Guid: newGuid() };

  const at = replacing === null ? -1 : lib.sources.findIndex((s) => s.tag === replacing);
  if (at >= 0) lib.sources[at] = fresh;
  else lib.sources.push(fresh);
  changed(ctx);
  return fresh;
}

export function deleteSource(ctx: DocContext, tag: string): void {
  const lib = library(ctx);
  lib.sources = lib.sources.filter((s) => s.tag !== tag);
  changed(ctx);
}

/** Adds sources not in the document yet (by DOI, or title and year). Returns how many were added. */
export function addSources(ctx: DocContext, sources: Source[]): { added: Source[]; skipped: number } {
  const known = new Set(library(ctx).sources.map(identity));
  const added: Source[] = [];
  let skipped = 0;

  for (const source of sources) {
    const id = identity(source);
    if (known.has(id)) {
      skipped++;
      continue;
    }
    known.add(id);
    added.push(saveSource(ctx, { ...source, tag: source.tag }));
  }

  return { added, skipped };
}

export function setStyle(ctx: DocContext, style: StyleId): void {
  const lib = library(ctx);
  if (lib.style === style) return;
  lib.style = style;
  changed(ctx);
}

export function newGuid(): string {
  const hex = Array.from({ length: 32 }, () => Math.floor(Math.random() * 16).toString(16).toUpperCase()).join('');
  return `{${hex.slice(0, 8)}-${hex.slice(8, 12)}-4${hex.slice(13, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}}`;
}

// ---- Writing the part ----------------------------------------------------------------------------------

const PROPS_TYPE = 'application/vnd.openxmlformats-officedocument.customXmlProperties+xml';

function writeLibrary(ctx: DocContext, pkg: DocxPackage): void {
  const lib = libraries.get(ctx);
  if (!lib || !lib.changed) return;
  if (!lib.part && !lib.sources.length) return;

  const attrs = { ...lib.attrs, ...WORD_STYLES[lib.style] };

  // The style named on the root is Word's own one only while it is the style the editor uses.
  if (styleFrom(lib.attrs) === lib.style && lib.attrs.SelectedStyle) Object.assign(attrs, lib.attrs);

  const xml = writeSources(lib.sources, attrs, lib.open);
  if (lib.part && pkg.has(lib.part)) {
    pkg.setText(lib.part, xml);
    return;
  }

  // A new part, as Word makes it: the item, its properties naming the bibliography schema, and a
  // relationship from the document to the item.
  let n = 1;
  while (pkg.has(`customXml/item${n}.xml`) || pkg.has(`customXml/itemProps${n}.xml`)) n++;
  const item = `customXml/item${n}.xml`;

  pkg.setText(item, xml);
  pkg.setText(
    `customXml/itemProps${n}.xml`,
    `<?xml version="1.0" encoding="UTF-8" standalone="no"?><ds:datastoreItem ds:itemID="${escAttr(newGuid())}" xmlns:ds="http://schemas.openxmlformats.org/officeDocument/2006/customXml">` +
      `<ds:schemaRefs><ds:schemaRef ds:uri="${BIB_NS}"/></ds:schemaRefs></ds:datastoreItem>`,
  );
  pkg.setText(relsPathFor(item), addRels(null, [{ id: 'rId1', type: `${REL_TYPE}/customXmlProps`, target: `itemProps${n}.xml`, external: false }]));

  const docRels = relsPathFor(ctx.docPath);
  const used = new Set(parseRels(pkg.text(docRels)).map((r) => r.id));
  let id = 1;
  while (used.has(`rId${id}`)) id++;
  const depth = ctx.docPath.split('/').length - 1;
  pkg.setText(docRels, addRels(pkg.text(docRels), [{ id: `rId${id}`, type: `${REL_TYPE}/customXml`, target: `${'../'.repeat(depth)}${item}`, external: false }]));
  pkg.setText(
    '[Content_Types].xml',
    addContentTypes(pkg.text('[Content_Types].xml') ?? '', new Map([['xml', 'application/xml']]), new Map([[`customXml/itemProps${n}.xml`, PROPS_TYPE]])),
  );
}

addPartWriter(writeLibrary);
