// Parts of the package that something other than the document body keeps (the bibliography's
// sources, for one). Each writer gets the package as the exporter is about to zip it, after the
// document, its relationships and the content types are written, and adds or changes its parts.

import type { Node as PMNode } from 'prosemirror-model';
import type { DocContext } from './import';
import type { DocxPackage } from './package';

/** `doc` is the text being saved. */
export type PartWriter = (ctx: DocContext, pkg: DocxPackage, doc: PMNode) => void;

export const partWriters: PartWriter[] = [];

export function addPartWriter(writer: PartWriter): void {
  if (!partWriters.includes(writer)) partWriters.push(writer);
}
