// Chicago 17th edition, notes and bibliography (CMOS chapter 14): the text of a footnote that cites
// a source, in its full form the first time the source is cited and its short form after that
// ("Ibid." for the same source as the note before, when asked for), and the bibliography entry.
// Pure functions, as the other styles in styles.ts; src/cite/note-cite.ts puts them into notes.

import { type Source, field, kindOf, people } from './model';
import {
  type CiteItem,
  ITALIC_TITLE,
  Out,
  type Run,
  authorsOf,
  chicagoAuthors,
  edition,
  editorsFull,
  familyOf,
  fullDirect,
  link,
  monthName,
  quoted,
  series,
  yearOf,
} from './styles';

export type NoteForm = 'full' | 'short' | 'ibid';

/**
 * Inclusive numbers as CMOS 9.61 abbreviates them: 3–10, 100–104, 101–8, 321–28, 498–532,
 * 1087–89, 1496–500, 11564–615, 12991–3001. Anything that is not a plain range just gets an en dash.
 */
export function pageRangeNb(pages: string): string {
  const text = pages.trim().replace(/\s*[-–—]+\s*/g, '–');

  return text.replace(/\b(\d+)–(\d+)\b/g, (whole, from: string, to: string) => {
    const a = Number(from);
    const b = Number(to);
    if (b <= a || from.length !== to.length || a < 100 || a % 100 === 0) return whole;

    let i = 0;
    while (from[i] === to[i]) i++;

    // 101–8: only what changed; 321–28: at least two digits.
    const kept = a % 100 < 10 ? to.slice(i).replace(/^0+/, '') : to.slice(Math.min(i, to.length - 2));
    return `${from}–${kept}`;
  });
}

/** Names as a note gives them: "Michael Pollan", "Ward and Burns", "Dana Barnes et al.". */
function noteNames(source: Source, short: boolean): string {
  const names = authorsOf(source);
  const shown = short ? names.map(familyOf) : names.map(fullDirect);
  if (shown.length > 3) return `${shown[0]} et al.`;
  return series(shown, 'and');
}

/** The short title: the source's own, or the main title without its subtitle and leading article, up to four words. */
export function shortTitleNb(source: Source): string {
  const own = field(source, 'ShortTitle');
  if (own) return own;

  const main = field(source, 'Title').split(/:\s/)[0].replace(/^(?:the|an?)\s+/i, '');
  const words = main.split(/\s+/);
  return words.length > 4 ? words.slice(0, 4).join(' ') : main;
}

/** Where and when a book came out: "New York: Penguin, 2006". */
function imprint(source: Source): string {
  const place = [field(source, 'City'), field(source, kindOf(source) === 'thesis' ? 'Institution' : 'Publisher')].filter(Boolean).join(': ');
  return [place, yearOf(source)].filter(Boolean).join(', ');
}

const editorsNote = (source: Source) => {
  const eds = people(source, 'Editor').map(fullDirect);
  if (!eds.length) return '';
  return `${eds.length > 1 ? 'eds.' : 'ed.'} ${eds.length > 3 ? `${eds[0]} et al.` : series(eds, 'and')}`;
};

/** The journal's volume, issue and date: "111, no. 2 (April 2016)". */
function issueOf(source: Source): string {
  const volume = field(source, 'Volume');
  const issue = field(source, 'Issue');
  const date = [field(source, 'Month') && monthName(field(source, 'Month')), yearOf(source)].filter(Boolean).join(' ');
  return [volume, issue && `${volume ? ', ' : ''}no. ${issue}`, date && ` (${date})`].filter(Boolean).join('');
}

/** A title as the style sets it: italic for a whole work, quoted for a part of one; `mark` goes inside the quotes. */
function title(out: Out, source: Source, text: string, mark: string): Out {
  if (ITALIC_TITLE[kindOf(source)]) return out.add(text, true).add(mark);
  return quoted(out, text, mark);
}

function fullNote(item: CiteItem, source: Source): Run[] {
  const kind = kindOf(source);
  const out = new Out();
  const names = noteNames(source, false);
  const at = item.pages ? pageRangeNb(item.pages) : '';
  const name = field(source, 'Title');

  if (names) out.add(`${names}, `);

  switch (kind) {
    case 'chapter':
    case 'conference': {
      quoted(out, name, ',');
      out.add(' in ').add(kind === 'chapter' ? field(source, 'BookTitle') : field(source, 'ConferenceName'), true);
      const eds = editorsNote(source);
      if (eds) out.add(`, ${eds}`);
      const ed = edition(source);
      if (ed) out.add(`, ${ed}`);
      const pub = imprint(source);
      if (pub) out.add(` (${pub})`);
      if (at) out.add(`, ${at}`);
      break;
    }
    case 'article': {
      quoted(out, name, ',');
      out.add(' ').add(field(source, 'JournalName') || field(source, 'PeriodicalTitle'), true);
      const issue = issueOf(source);
      if (issue) out.add(issue.startsWith(' ') ? issue : ` ${issue}`);
      if (at) out.add(`: ${at}`);
      break;
    }
    case 'website': {
      quoted(out, name, ',');
      const site = field(source, 'InternetSiteTitle');
      if (site) out.add(` ${site}`);
      const date = [field(source, 'Month') && monthName(field(source, 'Month')), field(source, 'Day') && `${field(source, 'Day')},`, yearOf(source)].filter(Boolean).join(' ');
      if (date) out.add(`, ${date}`);
      break;
    }
    default: {
      title(out, source, name, '');
      const ed = edition(source);
      const what = kind === 'thesis' ? field(source, 'ThesisType') : kind === 'report' ? [field(source, 'ReportType'), field(source, 'StandardNumber')].filter(Boolean).join(' ') : '';
      const pub = [what, ed, imprint(source)].filter(Boolean).join(', ');
      if (pub) out.add(` (${pub})`);
      if (at) out.add(`, ${at}`);
    }
  }

  const url = link(source, 'chicago');
  if (url && !at) out.add(`, ${url}`);
  return out.runs;
}

function shortNote(item: CiteItem, source: Source): Run[] {
  const out = new Out();
  const names = noteNames(source, true);
  if (names) out.add(`${names}, `);

  title(out, source, shortTitleNb(source), item.pages ? ',' : '');
  if (item.pages) out.add(` ${pageRangeNb(item.pages)}`);
  return out.runs;
}

/**
 * A note's text for the sources one citation names, each in the form asked for, joined with
 * semicolons and ended with a full stop: "1. Michael Pollan, *The Omnivore's Dilemma* (New York:
 * Penguin, 2006), 99–100." without the number, which the note has already.
 */
export function formatNote(items: CiteItem[], form: NoteForm | ((item: CiteItem) => NoteForm), stop = true): Run[] {
  const out = new Out();

  items.forEach((item, i) => {
    if (i) out.add('; ');
    if (item.prefix) out.add(`${item.prefix} `);

    const f = typeof form === 'function' ? form(item) : form;
    if (!item.source) out.add(item.tag);
    else if (f === 'ibid') out.add(item.pages ? `Ibid., ${pageRangeNb(item.pages)}` : 'Ibid');
    else out.addRuns(f === 'full' ? fullNote(item, item.source) : shortNote(item, item.source));

    if (item.suffix) out.add(`, ${item.suffix}`);
  });

  return stop ? out.end().runs : out.runs;
}

/** A bibliography entry: "Pollan, Michael. *The Omnivore's Dilemma: A Natural History of Four Meals*. New York: Penguin, 2006." */
export function nbEntry(source: Source): Run[] {
  const kind = kindOf(source);
  const out = new Out();
  const names = authorsOf(source);
  const name = field(source, 'Title');
  const sentence = (text: string) => {
    if (text) out.add(' ').add(text).end();
  };

  if (names.length) out.add(chicagoAuthors(names)).end().add(' ');

  switch (kind) {
    case 'chapter':
    case 'conference': {
      quoted(out, name, '.');
      out.add(' In ').add(kind === 'chapter' ? field(source, 'BookTitle') : field(source, 'ConferenceName'), true);
      const eds = editorsFull(source);
      if (eds) out.add(`, edited by ${eds}`);
      if (field(source, 'Pages')) out.add(`, ${pageRangeNb(field(source, 'Pages'))}`);
      out.end();
      sentence(edition(source));
      sentence(imprint(source));
      break;
    }
    case 'article': {
      quoted(out, name, '.');
      out.add(' ').add(field(source, 'JournalName') || field(source, 'PeriodicalTitle'), true);
      const issue = issueOf(source);
      if (issue) out.add(issue.startsWith(' ') ? issue : ` ${issue}`);
      if (field(source, 'Pages')) out.add(`: ${pageRangeNb(field(source, 'Pages'))}`);
      out.end();
      break;
    }
    case 'website': {
      quoted(out, name, '.');
      sentence(field(source, 'InternetSiteTitle'));
      sentence([field(source, 'Month') && monthName(field(source, 'Month')), field(source, 'Day') && `${field(source, 'Day')},`, yearOf(source)].filter(Boolean).join(' '));
      break;
    }
    default: {
      title(out, source, name, '').end();
      if (kind === 'thesis') sentence(field(source, 'ThesisType'));
      if (kind === 'report') sentence([field(source, 'ReportType'), field(source, 'StandardNumber')].filter(Boolean).join(' '));
      sentence(edition(source));
      sentence(imprint(source));
    }
  }

  const url = link(source, 'chicago');
  if (url) out.add(` ${url}`).end();
  return out.runs;
}
