// Copy, cut, paste and drop.
//
// Copying puts three things on the clipboard: HTML and plain text for other programs, and the
// selection as the editor's own data. Pasting that back into the document it came from loses
// nothing. Pasting it into another document strips what only made sense in the first one:
// kept source that points at parts, lists and styles of that file.
//
// HTML from elsewhere comes in through the schema's parse rules, which leave hints on headings
// and list items (schema.ts); those are turned into this document's styles and lists here.

import { Fragment, type Node as PMNode, Slice } from 'prosemirror-model';
import { Plugin, Selection } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import type { ListKind } from '../docx/numbering';
import { insertImage } from './commands';
import { listOf } from './lists';
import { schema } from './schema';

const MIME = 'application/x-text-studio';
const N = schema.nodes;
const M = schema.marks;

/** Formats Word takes as they are. Anything else is redrawn as PNG before it goes into a document. */
const KEPT_AS_IS = new Set(['image/png', 'image/jpeg', 'image/gif']);

/** Rebuilds a fragment node by node. `change` returns the node, a replacement, or null to drop it. */
function mapFragment(fragment: Fragment, change: (node: PMNode) => PMNode | null): Fragment {
  const out: PMNode[] = [];

  fragment.forEach((child) => {
    let node = child;

    if (node.content.size) {
      const content = mapFragment(node.content, change);
      // A cell or wrapper emptied by what was dropped still needs something in it.
      node = node.type.validContent(content) ? node.copy(content) : (node.type.createAndFill(node.attrs) ?? node);
    }

    const mapped = change(node);
    if (mapped) out.push(mapped);
  });

  return Fragment.fromArray(out);
}

/** Before copying: notes each paragraph's style name and list kind, for a paste into another document. */
function annotate(slice: Slice, ctx: DocContext): Slice {
  const content = mapFragment(slice.content, (node) => {
    if (node.type !== N.paragraph) return node;

    const place = listOf(node, ctx);
    const kind = place ? ctx.numbering.kindOf(place.numId, place.ilvl) : null;
    const style = node.attrs.styleId ? ctx.styles.byId.get(node.attrs.styleId) : null;
    const hint = kind && place ? `li:${kind}:${place.ilvl}` : style ? `style:${style.name}` : null;

    return hint ? N.paragraph.create({ ...node.attrs, hint }, node.content, node.marks) : node;
  });

  return new Slice(content, slice.openStart, slice.openEnd);
}

/**
 * Turns the hints on pasted paragraphs into styles and lists of this document, and gives pasted
 * links the Hyperlink style, without which Word shows a link as ordinary text.
 */
function resolveHints(slice: Slice, ctx: DocContext, foreign: boolean): Slice {
  const lists = new Map<string, number>();
  let touched = false;

  const content = mapFragment(slice.content, (node) => {
    if (node.isInline && M.link.isInSet(node.marks) && !M.charStyle.isInSet(node.marks)) {
      const style = ctx.styles.ensureBuiltin('Hyperlink', 'character');

      if (style) {
        touched = true;
        return node.mark(M.charStyle.create({ id: style }).addToSet(node.marks));
      }
    }

    if (node.type !== N.paragraph || !node.attrs.hint) return node;

    const hint: string = node.attrs.hint;
    const attrs: Record<string, unknown> = { ...node.attrs, hint: null };
    const heading = /^h([1-6])$/.exec(hint);
    const item = /^li:(bullet|number):(\d)$/.exec(hint);

    touched = true;

    if (heading) {
      attrs.styleId = ctx.styles.ensureBuiltin(`heading ${heading[1]}`);
    } else if (item && (foreign || attrs.numId === null)) {
      // One new list per kind for the whole paste, so its items number together.
      let numId = lists.get(item[1]);

      if (numId === undefined) {
        numId = ctx.numbering.createList(item[1] as ListKind);
        lists.set(item[1], numId);
      }

      attrs.numId = numId;
      attrs.ilvl = Number(item[2]);
      // The list style is what keeps the items of a list close together.
      attrs.styleId ??= ctx.styles.ensureBuiltin('List Paragraph');
    } else if (hint.startsWith('style:') && foreign) {
      const name = hint.slice(6);
      attrs.styleId = ctx.styles.byName(name)?.id ?? ctx.styles.ensureBuiltin(name);
    }

    return N.paragraph.create(attrs, node.content, node.marks);
  });

  return touched ? new Slice(content, slice.openStart, slice.openEnd) : slice;
}

/** Makes content copied from another document safe to put into this one. */
function sanitize(slice: Slice, ctx: DocContext): Slice {
  const content = mapFragment(slice.content, (node) => {
    // Placeholders hold source that refers to the other file's footnotes, bookmarks and parts.
    if (node.type === N.opaque || node.type === N.opaque_block) return null;

    let marks = node.marks;

    if (marks.length) {
      // Deleted text of a tracked change is gone; the rest loses the tracking, not the text.
      if (marks.some((mark) => mark.type.name === 'track' && (mark.attrs.kind === 'del' || mark.attrs.kind === 'moveFrom'))) return null;

      marks = marks
        .filter((mark) => mark.type.name !== 'track' && mark.type.name !== 'wrap')
        .filter((mark) => mark.type.name !== 'charStyle' || ctx.styles.byId.has(mark.attrs.id))
        .map((mark) => (mark.type.name === 'link' ? mark.type.create({ ...mark.attrs, tag: null, rid: null, orig: null }) : mark));
    }

    if (node.isText) return node.mark(marks);
    if (node.type === N.image) return N.image.create({ ...node.attrs, raw: null, ow: null, oh: null }, null, marks);
    // A chart leaves its part behind in the other file and is written as a new one here.
    if (node.type === N.chart) return N.chart.create({ ...node.attrs, raw: null, part: null, orig: null, ow: null, oh: null }, null, marks);
    if (node.type === N.paragraph) return N.paragraph.create({ ...node.attrs, numId: null, ilvl: 0, styleId: null, sectPr: null }, node.content);
    if (node.type === N.table) return N.table.create({ ...node.attrs, tblPr: null, tstyle: null, borders: true }, node.content);

    return node.mark(marks);
  });

  return new Slice(content, slice.openStart, slice.openEnd);
}

/**
 * Whether a paste is whole blocks going into an empty paragraph. Left to itself the editor pours
 * the first block's text into that paragraph, which then keeps its own formatting: a pasted
 * heading turns into body text, and the first item of a pasted list loses its bullet.
 */
function replacesEmptyParagraph(view: EditorView, slice: Slice): boolean {
  const { empty, $from } = view.state.selection;
  const first = slice.content.firstChild;

  return (
    empty &&
    $from.depth > 0 &&
    $from.parent.type === N.paragraph &&
    $from.parent.content.size === 0 &&
    !!first?.isBlock &&
    (slice.content.childCount > 1 || first.type !== N.paragraph)
  );
}

function paste(view: EditorView, slice: Slice): void {
  const tr = view.state.tr;

  if (replacesEmptyParagraph(view, slice)) {
    const { $from } = view.state.selection;

    // The blocks take the empty paragraph's place, each as it was copied.
    tr.replaceRange($from.before(), $from.after(), new Slice(slice.content, 0, 0));
    tr.setSelection(Selection.near(tr.doc.resolve(tr.mapping.map($from.after(), -1)), -1));
  } else {
    tr.replaceSelection(slice);
  }

  view.dispatch(tr.scrollIntoView().setMeta('paste', true).setMeta('uiEvent', 'paste'));
}

function copy(view: EditorView, event: ClipboardEvent, cut: boolean, ctx: DocContext): boolean {
  const selection = view.state.selection;
  const data = event.clipboardData;

  if (selection.empty || !data) return false;

  const slice = selection.content();
  const { dom, text } = view.serializeForClipboard(slice);

  event.preventDefault();
  data.clearData();
  data.setData('text/html', dom.innerHTML);
  data.setData('text/plain', text);
  data.setData(MIME, JSON.stringify({ origin: ctx.key, slice: annotate(slice, ctx).toJSON() }));

  if (cut) view.dispatch(view.state.tr.deleteSelection().scrollIntoView().setMeta('uiEvent', 'cut'));

  return true;
}

/** Reads a picture file into something a document can hold: a data URL in a format Word accepts, and its size. */
export async function readImage(file: Blob): Promise<{ src: string; w: number; h: number } | null> {
  const dataUrl = await new Promise<string | null>((resolve) => {
    const reader = new FileReader();
    reader.onload = () => resolve(typeof reader.result === 'string' ? reader.result : null);
    reader.onerror = () => resolve(null);
    reader.readAsDataURL(file);
  });

  if (!dataUrl) return null;

  const image = new Image();

  try {
    image.src = dataUrl;
    await image.decode();
  } catch {
    return null;
  }

  const w = image.naturalWidth || 300;
  const h = image.naturalHeight || 150;

  if (KEPT_AS_IS.has(file.type)) return { src: dataUrl, w, h };

  // WebP, SVG, BMP and the rest: drawn once and kept as PNG.
  const canvas = document.createElement('canvas');
  canvas.width = w;
  canvas.height = h;
  canvas.getContext('2d')?.drawImage(image, 0, 0, w, h);

  return { src: canvas.toDataURL('image/png'), w, h };
}

/** Puts a picture file into the document at the selection, scaled down to fit between the margins. */
export async function insertImageFile(view: EditorView, file: Blob, ctx: DocContext, name = ''): Promise<boolean> {
  const image = await readImage(file);
  if (!image) return false;

  const room = ctx.page.width - ctx.page.left - ctx.page.right;
  const scale = Math.min(1, room / image.w);

  return insertImage(image.src, Math.round(image.w * scale), Math.round(image.h * scale), name)(view.state, view.dispatch);
}

export function clipboardPlugin(ctx: DocContext): Plugin {
  return new Plugin({
    props: {
      handleDOMEvents: {
        copy: (view, event) => copy(view, event, false, ctx),
        cut: (view, event) => copy(view, event, true, ctx),
      },

      handlePaste(view, event, pasted) {
        const data = event.clipboardData;
        if (!data) return false;

        const own = data.getData(MIME);

        if (own) {
          try {
            const parsed = JSON.parse(own) as { origin: string; slice: unknown };
            const foreign = parsed.origin !== ctx.key;
            let slice = Slice.fromJSON(schema, parsed.slice);

            if (foreign) slice = sanitize(slice, ctx);
            slice = resolveHints(slice, ctx, foreign);

            paste(view, slice);
            return true;
          } catch {
            // Not ours after all, or from a version with another schema: paste it as HTML.
            return false;
          }
        }

        // A screenshot or a copied picture, with no text beside it.
        const picture = [...data.files].find((file) => file.type.startsWith('image/'));

        if (picture && !data.getData('text/html')) {
          void insertImageFile(view, picture, ctx);
          return true;
        }

        // HTML from another program, already read into a slice: only the one case needs help.
        if (replacesEmptyParagraph(view, pasted)) {
          paste(view, pasted);
          return true;
        }

        return false;
      },

      transformPasted: (slice) => resolveHints(slice, ctx, false),

      handleDrop(view, event) {
        const pictures = [...(event.dataTransfer?.files ?? [])].filter((file) => file.type.startsWith('image/'));
        if (!pictures.length) return false;

        const at = view.posAtCoords({ left: event.clientX, top: event.clientY });

        event.preventDefault();

        void (async () => {
          for (const picture of pictures) {
            const image = await readImage(picture);
            if (!image) continue;

            const room = ctx.page.width - ctx.page.left - ctx.page.right;
            const scale = Math.min(1, room / image.w);
            const node = N.image.create({ src: image.src, w: Math.round(image.w * scale), h: Math.round(image.h * scale), alt: picture.name });
            const pos = Math.min(at?.pos ?? view.state.selection.from, view.state.doc.content.size);

            view.dispatch(view.state.tr.insert(pos, node));
          }
        })();

        return true;
      },
    },
  });
}
