// Finding text by how it looks: everything italic, everything in one font, every "Figure 3" in
// bold. A filter names the formatting wanted; text matches it where its own formatting, or failing
// that its paragraph's style, says so.

import type { Mark, Node as PMNode } from 'prosemirror-model';
import { isOn } from '../docx/props';
import type { Styles } from '../docx/styles';
import { child, type XmlEl } from '../docx/xml';
import type { Match, Span } from './find';

/** The formatting looked for. A property left out may be anything. */
export interface FormatFilter {
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  strike?: boolean;
  /** A font's name; upper and lower case are the same. */
  font?: string;
  /** In points. */
  size?: number;
  /** `#RRGGBB`, or `auto` for the automatic colour. */
  color?: string;
  /** `#RRGGBB`, or `none` for text that is not highlighted. */
  highlight?: string;
  /** A paragraph style's id; `''` is the document's default style. */
  style?: string;
}

/** How a piece of text looks, all things taken together. */
export interface RunFormat {
  bold: boolean;
  italic: boolean;
  underline: boolean;
  strike: boolean;
  font: string | null;
  size: number | null;
  color: string;
  highlight: string | null;
  /** The paragraph's style, or null for the default one. */
  style: string | null;
}

/** What text in a style looks like when nothing is set on the text itself. */
export interface StyleRuns {
  defaultParagraph: string | null;
  base(paragraphStyle: string | null, charStyle: string | null): Partial<RunFormat>;
}

export const FILTER_KEYS = ['bold', 'italic', 'underline', 'strike', 'font', 'size', 'color', 'highlight', 'style'] as const;

export function isEmptyFilter(filter: FormatFilter | null | undefined): boolean {
  return !filter || FILTER_KEYS.every((key) => filter[key] === undefined);
}

/** The filter without the properties that are left open, or null if nothing is left. */
export function cleanFilter(filter: FormatFilter | null | undefined): FormatFilter | null {
  if (!filter) return null;

  const out: FormatFilter = {};
  for (const key of FILTER_KEYS) {
    if (filter[key] !== undefined && filter[key] !== null && filter[key] !== '') (out as Record<string, unknown>)[key] = filter[key];
  }
  if (filter.style === '') out.style = '';

  return isEmptyFilter(out) ? null : out;
}

const sameColor = (a: string | null | undefined, b: string | null | undefined) => (a ?? '').replace(/^#/, '').toUpperCase() === (b ?? '').replace(/^#/, '').toUpperCase();

// ---- Styles --------------------------------------------------------------------------------------

/** Run properties of one `w:rPr`, the ones a filter can ask about. */
function fromRPr(rPr: XmlEl | null): Partial<RunFormat> {
  if (!rPr) return {};

  const out: Partial<RunFormat> = {};
  const b = child(rPr, 'w:b');
  const i = child(rPr, 'w:i');
  const u = child(rPr, 'w:u');
  const strike = child(rPr, 'w:strike');
  const color = child(rPr, 'w:color')?.attrs['w:val'];

  if (b) out.bold = isOn(b);
  if (i) out.italic = isOn(i);
  if (u) out.underline = (u.attrs['w:val'] ?? 'single') !== 'none';
  if (strike) out.strike = isOn(strike);
  if (color) out.color = /^[0-9a-f]{6}$/i.test(color) ? `#${color.toUpperCase()}` : 'auto';

  return out;
}

const resolvers = new WeakMap<Styles, { version: number; runs: StyleRuns }>();

/** Looks styles up for a filter: what each style makes its text look like. Kept per document. */
export function styleRuns(styles: Styles): StyleRuns {
  const known = resolvers.get(styles);
  if (known && known.version === styles.version) return known.runs;

  const cache = new Map<string, Partial<RunFormat>>();

  const runs: StyleRuns = {
    defaultParagraph: styles.defaultParagraph,
    base(paragraphStyle, charStyle) {
      const key = `${paragraphStyle ?? ''}\u0000${charStyle ?? ''}`;
      let found = cache.get(key);

      if (!found) {
        const { font, size } = styles.runOf(paragraphStyle);
        found = { ...fromRPr(styles.docRPr), font, size };

        for (const def of styles.chain(paragraphStyle ?? styles.defaultParagraph)) Object.assign(found, fromRPr(def.rPr));
        if (charStyle) for (const def of styles.chain(charStyle)) Object.assign(found, fromRPr(def.rPr));

        cache.set(key, found);
      }

      return found;
    },
  };

  resolvers.set(styles, { version: styles.version, runs });
  return runs;
}

// ---- One piece of text ---------------------------------------------------------------------------

const markOf = (marks: readonly Mark[], name: string) => marks.find((m) => m.type.name === name);

/** How a piece of text in a paragraph looks: its marks over its styles. */
export function runFormat(marks: readonly Mark[], paragraph: PMNode, styles: StyleRuns | null): RunFormat {
  const paragraphStyle = (paragraph.attrs.styleId as string | null) ?? null;
  const charStyle = (markOf(marks, 'charStyle')?.attrs.id as string | undefined) ?? null;
  const base = styles?.base(paragraphStyle, charStyle) ?? {};
  const on = (name: string, fallback: boolean | undefined) => {
    const mark = markOf(marks, name);
    return mark ? mark.attrs.on !== false : !!fallback;
  };

  const underline = markOf(marks, 'underline');
  const font = markOf(marks, 'fontFamily');
  const size = markOf(marks, 'fontSize');
  const color = markOf(marks, 'color');
  const highlight = markOf(marks, 'highlight');

  return {
    bold: on('bold', base.bold),
    italic: on('italic', base.italic),
    underline: underline ? underline.attrs.kind !== 'none' : !!base.underline,
    strike: on('strike', base.strike),
    font: (font?.attrs.name as string | undefined) || base.font || null,
    size: size ? (size.attrs.size as number) / 2 : (base.size ?? null),
    color: (color?.attrs.value as string | undefined) ?? base.color ?? 'auto',
    highlight: (highlight?.attrs.value as string | undefined) ?? null,
    style: paragraphStyle === styles?.defaultParagraph ? null : paragraphStyle,
  };
}

/** Whether text formatted like this is what the filter looks for. */
export function fits(format: RunFormat, filter: FormatFilter): boolean {
  for (const key of ['bold', 'italic', 'underline', 'strike'] as const) {
    if (filter[key] !== undefined && format[key] !== filter[key]) return false;
  }

  if (filter.font !== undefined && (format.font ?? '').toLowerCase() !== filter.font.toLowerCase()) return false;
  if (filter.size !== undefined && (format.size === null || Math.abs(format.size - filter.size) > 0.01)) return false;
  if (filter.color !== undefined && !(filter.color === 'auto' ? format.color === 'auto' : sameColor(format.color, filter.color))) return false;
  if (filter.highlight !== undefined && !(filter.highlight === 'none' ? !format.highlight : sameColor(format.highlight, filter.highlight))) return false;
  if (filter.style !== undefined && (format.style ?? '') !== filter.style) return false;

  return true;
}

// ---- Searching ---------------------------------------------------------------------------------

/** Every stretch of text that has the formatting, as long as each can be. */
export function formatMatches(doc: PMNode, filter: FormatFilter, styles: StyleRuns | null, limit = Infinity): Match[] {
  const matches: Match[] = [];

  doc.descendants((node, pos) => {
    if (matches.length >= limit) return false;
    if (!node.isTextblock) return true;

    let open: Span | null = null;

    node.forEach((inline, offset) => {
      const from = pos + 1 + offset;
      const yes = inline.isText && fits(runFormat(inline.marks, node, styles), filter);

      if (yes && open && open.to === from) open.to = from + inline.nodeSize;
      else if (yes) {
        if (open) matches.push({ ...open, groups: [] });
        open = { from, to: from + inline.nodeSize };
      } else if (open) {
        matches.push({ ...open, groups: [] });
        open = null;
      }
    });

    if (open) matches.push({ ...(open as Span), groups: [] });
    return false;
  });

  return matches.slice(0, limit);
}

/** Whether all the text in a stretch has the formatting. */
export function spanFits(doc: PMNode, span: Span, filter: FormatFilter, styles: StyleRuns | null): boolean {
  let all = true;
  let any = false;

  doc.nodesBetween(span.from, span.to, (node, _pos, parent) => {
    if (!all) return false;

    if (node.isText && parent) {
      any = true;
      if (!fits(runFormat(node.marks, parent, styles), filter)) all = false;
    }

    return true;
  });

  return all && any;
}

// ---- Words for the find bar ----------------------------------------------------------------------

/** The filter in a few words, for a button's label: "Italic, Arial, 12 pt". */
export function describeFilter(filter: FormatFilter, styleName: (id: string) => string = (id) => id): string {
  const parts: string[] = [];
  const toggle = (value: boolean | undefined, yes: string, no: string) => value !== undefined && parts.push(value ? yes : no);

  toggle(filter.bold, 'Bold', 'Not bold');
  toggle(filter.italic, 'Italic', 'Not italic');
  toggle(filter.underline, 'Underlined', 'Not underlined');
  toggle(filter.strike, 'Struck through', 'Not struck through');
  if (filter.font !== undefined) parts.push(filter.font);
  if (filter.size !== undefined) parts.push(`${filter.size} pt`);
  if (filter.color !== undefined) parts.push(filter.color === 'auto' ? 'Automatic colour' : `Colour ${filter.color}`);
  if (filter.highlight !== undefined) parts.push(filter.highlight === 'none' ? 'No highlight' : `Highlight ${filter.highlight}`);
  if (filter.style !== undefined) parts.push(filter.style ? styleName(filter.style) : 'Default style');

  return parts.join(', ');
}

/** The fonts that text in a document is set in by its own formatting. */
export function fontsUsed(doc: PMNode): string[] {
  const fonts = new Set<string>();

  doc.descendants((node) => {
    for (const mark of node.marks) if (mark.type.name === 'fontFamily' && mark.attrs.name) fonts.add(mark.attrs.name as string);
    return true;
  });

  return [...fonts].sort((a, b) => a.localeCompare(b));
}
