// "Export as…": the document as Markdown, HTML or OpenDocument Text, by the file type picked in
// the save dialog. The writers work from the editor's document (src/convert/markdown.ts, html.ts,
// odt.ts); the desktop side only writes the bytes (electron/export.cjs).

import type { EditorView } from 'prosemirror-view';
import { desktop } from '../desktop';
import type { DocContext } from '../docx/import';
import { updateFieldsBeforeSave } from '../fields/plugin';
import { store, stored, tell, toast } from '../ui/dom';
import { type ExportFormat, type Exported, convert, formatOf } from './formats';

const FORMAT_KEY = 'export-format';

/** The file's name without folder and extension. */
const baseName = (path: string) => path.replace(/^.*[\\/]/, '').replace(/\.[^.]*$/, '') || 'Document';

/** Asks where and as what, converts the document, and writes it there. */
export async function exportAs(tab: { ctx: DocContext; view: EditorView; name: string }): Promise<void> {
  const last = (stored(FORMAT_KEY) as ExportFormat | null) ?? 'md';
  const suggested = `${baseName(tab.name)}.${last}`;

  // A browser has no save dialog to choose a type in: it downloads the format used last.
  const path = desktop.exportDialog ? await desktop.exportDialog(suggested, last) : suggested;
  if (!path) return;

  const format = formatOf(path);
  if (!format) {
    await tell('The file could not be exported', 'Choose Markdown (.md), HTML (.html) or OpenDocument Text (.odt) as the file type.');
    return;
  }

  store(FORMAT_KEY, format);
  updateFieldsBeforeSave(tab.view, tab.ctx);

  let out: Exported;
  try {
    out = convert({ ctx: tab.ctx, doc: tab.view.state.doc, name: baseName(path) }, format);
  } catch (error) {
    await tell('The file could not be exported', String((error as Error)?.message ?? error));
    return;
  }

  if (!desktop.exportWrite) {
    download(path, out.bytes);
    return;
  }

  const problem = await desktop.exportWrite(path, out.bytes, out.files.map(({ name, bytes }) => ({ name, bytes })));
  if (problem) await tell('The file could not be exported', problem);
  else toast(format === 'md' ? 'Exported to Markdown' : format === 'html' ? 'Exported to HTML' : 'Exported to OpenDocument Text');
}

function download(name: string, bytes: Uint8Array): void {
  const url = URL.createObjectURL(new Blob([bytes as BlobPart]));
  const link = document.createElement('a');

  link.href = url;
  link.download = name;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}
