// The editor's window: tabs, files, the toolbar and the status bar around the documents.

import type { Node as PMNode } from 'prosemirror-model';
import type { Command } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import { APP_NAME } from './brand';
import { type OpenedFile, desktop } from './desktop';
import { blankDocx } from './docx/blank';
import { exportDocx } from './docx/export';
import { exportAs } from './convert';
import { type DocContext, type Imported, importDocx } from './docx/import';
import { chartXml, workbookRelOf } from './chart/chartxml';
import { type ChartSpec, parseSpec, sampleSpec, specJson, storedText } from './chart/model';
import { insertImageFile } from './editor/clipboard';
import { insertChart, selectedChart, tableAtCursor } from './editor/commands';
import { Paginator, pageAt } from './editor/pages';
import { prepareSheets } from './editor/print';
import { createEditor } from './editor/view';
import { goToBookmark, updateFieldsBeforeSave } from './fields/plugin';
import { onNotesChanged } from './notes/model';
import { onSourcesChanged } from './cite/store';
import { AssistPanel } from './ui/assistpanel';
import { chartDialog } from './ui/charteditor';
import { ask, closePopover, h, keepFocus, popover, store, stored, tell, toast } from './ui/dom';
import { FindBar } from './ui/findbar';
import { icon } from './ui/icons';
import { applyTheme, currentTheme, paperIsTinted, savedTheme, themeMenu } from './ui/themes';
import { HIGHLIGHT_COLORS, TEXT_COLORS, Toolbar } from './ui/toolbar';
import { ReviewPanel } from './ui/reviewpanel';
import { OutlinePane } from './ui/outlinepane';
import { Statistics } from './ui/statsdialog';
import { type StyleAction, styleAction } from './ui/styledialog';
import { RecoveryKeeper, intervalFrom } from './session/recovery';
import { offerRecoveries } from './session/recoveryui';

type PageMode = 'match' | 'white';

const ZOOM_KEY = 'text-studio:zoom';
const PAGE_KEY = 'text-studio:page';
const PAGES_KEY = 'text-studio:pages';
const AUTOSAVE_KEY = 'text-studio:autosave';
/** Seconds between recovery copies, 60 unless set (at least 10). */
const RECOVERY_KEY = 'text-studio:recovery-interval';
const DOCUMENT = /\.(docx|dotx)$/i;

const baseName = (path: string) => path.slice(Math.max(path.lastIndexOf('\\'), path.lastIndexOf('/')) + 1);

/** One open document: its package, its editor, and the page it is shown on. */
class DocTab {
  readonly ctx: DocContext;
  readonly view: EditorView;
  readonly desk = h('div', { class: 'desk', hidden: true });
  readonly page: HTMLElement;
  readonly label = h('div', { class: 'tab' });
  /** Lays the document out as separate pages, when that is switched on. */
  readonly pages: Paginator;
  /** The document as it was last written to disk, or as it was opened. */
  saved: PMNode;
  /** A new, empty document that nothing was typed into; opening a file takes its place. */
  pristine: boolean;
  private readonly styleEl = h('style');
  private cssVersion = -1;
  /** A header or footer was edited since the last save; those live in the package, not in `saved`. */
  partsChanged = false;

  constructor(
    app: App,
    imported: Imported,
    public path: string | null,
    public name: string,
  ) {
    const { page } = imported.ctx;

    this.ctx = imported.ctx;
    this.pristine = path === null;
    this.page = h('div', { class: `page ${this.ctx.key}` });
    this.page.style.width = `${page.width}px`;
    this.page.style.minHeight = `${page.height}px`;
    this.page.style.padding = `${page.top}px ${page.right}px ${page.bottom}px ${page.left}px`;
    this.desk.append(this.page);
    document.head.append(this.styleEl);

    this.view = createEditor({
      ctx: this.ctx,
      doc: imported.doc,
      mount: this.page,
      onChange: (_view, tr) => {
        if (tr.docChanged) {
          this.pristine = false;
          this.pages?.schedule();
        }
        app.changed(this);
      },
      onOpenLink: (href) => {
        if (/^(https?|mailto):/i.test(href)) desktop.openExternal(href);
        else if (href.startsWith('#')) goToBookmark(this.view, decodeURIComponent(href.slice(1)));
      },
      onEditChart: (pos) => void app.editChart(pos),
      onSuggestion: (view, id, target) => app.showSuggestion(view, id, target),
    });

    this.view.dom.style.minHeight = `${Math.max(100, page.height - page.top - page.bottom)}px`;
    this.pages = new Paginator(this.view, this.ctx, this.page);
    this.pages.furniture.onEdited = () => {
      this.partsChanged = true;
      app.changed(this);
    };
    // The bibliography's sources are kept outside the text: a change to them is unsaved work too.
    onSourcesChanged(this.ctx, () => {
      this.partsChanged = true;
      app.changed(this);
    });
    // So are footnotes and endnotes, kept in their own parts.
    onNotesChanged(this.ctx, () => {
      this.partsChanged = true;
      app.changed(this);
    });
    this.saved = this.view.state.doc;
    this.refreshCss();

    // A click in the margins or under the text still lands in the document.
    this.desk.addEventListener('mousedown', (event) => {
      if (!this.view.dom.contains(event.target as Node)) {
        event.preventDefault();
        this.view.focus();
      }
    });
  }

  get dirty(): boolean {
    return !this.view.state.doc.eq(this.saved) || this.partsChanged;
  }

  /** The stylesheet built from the document's styles, rebuilt when a style was added. */
  refreshCss(): void {
    // The style editor's changes, as the document (and so undo) has them.
    this.ctx.styles.useEdits(this.view.state.doc.attrs.styleEdits);

    if (this.cssVersion !== this.ctx.styles.version) {
      this.cssVersion = this.ctx.styles.version;
      this.styleEl.textContent = this.ctx.styles.css(`.${this.ctx.key}`);
    }
  }

  destroy(): void {
    this.pages.destroy();
    this.view.destroy();
    this.styleEl.remove();
    this.desk.remove();
    this.label.remove();
  }
}

class App {
  private readonly tabs: DocTab[] = [];
  private active: DocTab | null = null;
  private untitled = 0;
  private zoom = Math.min(3, Math.max(0.5, Number(stored(ZOOM_KEY)) || 1));
  private pageMode: PageMode = stored(PAGE_KEY) === 'white' ? 'white' : 'match';
  /** Whether documents are shown as separate pages, or as one long page. */
  private pagesOn = stored(PAGES_KEY) === 'on';
  private refreshQueued = false;
  private countTimer = 0;

  private readonly tabsEl = h('div', { class: 'tabs' });
  private readonly workspace = h('main', { class: 'workspace' });
  private readonly words = h('span', { class: 'text' });
  private readonly zoomLabel = h('button', { class: 'status-button', title: 'Reset zoom (Ctrl+0)', onclick: () => this.setZoom(1) });
  private readonly pageButton = h('button', { class: 'status-button', onclick: () => this.togglePageMode() });
  private readonly pagesButton = h('button', { class: 'status-button', onclick: () => this.togglePages() });
  private readonly spellButton = h('button', { class: 'status-button', title: 'Spelling languages', onclick: () => void this.spellingMenu() }, 'Spelling');
  private readonly fileButton = h('button', { class: 'app-button', onclick: () => void this.fileMenu() }, 'File');
  private readonly themeButton = h('button', { class: 'status-button', title: 'Theme', html: icon('theme'), onclick: () => this.themes() });

  private readonly host = {
    tab: () => this.active,
    run: (command: Command) => this.run(command),
    focus: () => this.active?.view.focus(),
    pickImage: () => void this.pickImage(),
    editChart: () => void this.editChart(),
    toggleFind: () => (this.findbar.isOpen ? this.findbar.close() : this.findbar.open()),
    toggleAssist: () => this.assist.toggle(),
    openCopy: (tab: DocTab, name: string) => this.openCopy(tab, name),
    layout: () => this.workspace.classList.toggle('with-assist', this.assist.isOpen),
    fonts: () => this.toolbar.fontNames,
    colors: () => ({ text: TEXT_COLORS, highlight: HIGHLIGHT_COLORS }),
    styleAction: (action: StyleAction) => {
      const tab = this.active;
      if (tab) styleAction(action, tab, this.toolbar.fontNames, () => this.changed(tab));
    },
  };

  private readonly toolbar = new Toolbar(this.host);
  private readonly findbar = new FindBar(this.host);
  private readonly assist = new AssistPanel(this.host);
  private readonly review = new ReviewPanel({
    tab: () => this.active,
    layout: () => this.workspace.classList.toggle('with-review', this.review.isOpen),
  });
  private readonly outline = new OutlinePane({
    tab: () => this.active,
    layout: () => this.workspace.classList.toggle('with-outline', this.outline.isOpen),
  });
  private readonly stats = new Statistics({ tab: () => this.active, recount: () => this.count() });
  /** Recovery copies of unsaved documents, and AutoSave (src/session/recovery.ts). */
  private readonly recovery = new RecoveryKeeper<DocTab>(
    {
      docs: () => this.tabs,
      bytes: (tab) => exportDocx(tab.ctx, tab.view.state.doc),
      save: (tab) => this.save(tab, false, true),
      write: desktop.recoveryWrite,
      remove: desktop.recoveryRemove,
    },
    intervalFrom(stored(RECOVERY_KEY)),
    stored(AUTOSAVE_KEY) === 'on',
  );
  private readonly recoverySeen = new WeakMap<DocTab, { doc: PMNode; parts: boolean }>();
  private readonly autoSaveButton = h('button', { class: 'status-button', onclick: () => this.toggleAutoSave() }, 'AutoSave');

  constructor(root: HTMLElement) {
    const titlebar = h(
      'header',
      { class: 'titlebar' },
      this.fileButton,
      this.tabsEl,
      h('button', { class: 'new-tab', title: 'New document (Ctrl+N)', html: icon('plus'), onclick: () => this.newDocument() }),
      h('div', { class: 'drag' }),
    );

    const statusbar = h(
      'footer',
      { class: 'statusbar' },
      this.outline.button,
      this.words,
      h('span', { class: 'spacer' }),
      desktop.isDesktop && this.spellButton,
      desktop.isDesktop && this.autoSaveButton,
      this.review.trackButton,
      this.review.paneButton,
      this.pagesButton,
      this.pageButton,
      h('button', { class: 'status-button', title: 'Zoom out (Ctrl+-)', onclick: () => this.setZoom(this.zoom - 0.1) }, '−'),
      this.zoomLabel,
      h('button', { class: 'status-button', title: 'Zoom in (Ctrl++)', onclick: () => this.setZoom(this.zoom + 0.1) }, '+'),
      this.themeButton,
    );

    keepFocus(titlebar);
    keepFocus(statusbar);

    // The window's own minimise, maximise and close buttons are drawn over the title bar's right end.
    if (desktop.isDesktop) document.documentElement.style.setProperty('--window-controls', '140px');

    this.workspace.append(this.assist.el, this.review.el);
    this.workspace.append(this.outline.el);
    this.words.addEventListener('click', () => this.stats.open());
    root.append(titlebar, this.toolbar.el, this.findbar.el, this.workspace, statusbar);

    window.addEventListener('keydown', (event) => this.onKey(event), true);
    this.workspace.addEventListener('wheel', (event) => this.onWheel(event), { passive: false });
    document.addEventListener('dragover', (event) => {
      if (event.dataTransfer?.types.includes('Files')) event.preventDefault();
    });
    document.addEventListener('drop', (event) => void this.onDrop(event));

    window.addEventListener('beforeunload', (event) => {
      // In a browser tab there is no close request to answer; the browser's own warning has to do.
      if (!desktop.isDesktop && this.tabs.some((tab) => tab.dirty)) event.preventDefault();
    });

    desktop.onOpenFiles((files) => void this.openFiles(files));
    desktop.onCloseRequest(() => void this.closeWindow());
    desktop.onAssistCommand((action) => this.assist.command(action));

    // A font that arrives late sets the text differently: the pages are laid out again.
    document.fonts?.addEventListener('loadingdone', () => this.active?.pages.schedule(50));
  }

  async start(): Promise<void> {
    const files = await desktop.startupFiles();

    if (files.length) await this.openFiles(files);

    // Copies of documents an earlier run did not get to save: offered back one by one.
    await offerRecoveries((file, key, outcome) => {
      try {
        const tab = this.add(importDocx(file.bytes), file.path, file.name);

        if (outcome.modified) {
          tab.partsChanged = true;
          tab.pristine = false;
          this.recovery.adopt(tab, key);
          this.refresh();
        }
      } catch (error) {
        void tell(`“${file.name}” could not be opened`, error instanceof Error ? error.message : String(error));
      }
    });

    if (!this.tabs.length) this.newDocument();
    this.showAutoSave();

    this.applyPage();
  }

  // ---- Tabs ----------------------------------------------------------------------------------

  private add(imported: Imported, path: string | null, name: string): DocTab {
    const tab = new DocTab(this, imported, path, name);
    const close = h('button', { class: 'close', title: 'Close (Ctrl+W)', html: icon('close') });

    close.addEventListener('click', (event) => {
      event.stopPropagation();
      void this.closeTab(tab);
    });

    tab.label.append(h('span', { class: 'name' }), h('span', { class: 'dot' }), close);
    tab.label.addEventListener('mousedown', (event) => {
      if (event.button === 0) this.activate(tab);
    });
    tab.label.addEventListener('auxclick', (event) => {
      if (event.button === 1) void this.closeTab(tab);
    });

    this.tabs.push(tab);
    this.tabsEl.append(tab.label);
    this.workspace.append(tab.desk);
    this.activate(tab);

    return tab;
  }

  private activate(tab: DocTab): void {
    closePopover();

    for (const other of this.tabs) {
      other.desk.hidden = other !== tab;
      other.label.classList.toggle('active', other === tab);
    }

    this.active = tab;
    this.applyPage();
    this.findbar.sync();
    this.refresh();
    tab.view.focus();
  }

  private newDocument(): void {
    this.add(importDocx(blankDocx()), null, `Document ${++this.untitled}`);
  }

  /**
   * A copy of a document in a new tab, not yet saved anywhere. It is written out and read in again,
   * so that the two share nothing: the copy's styles and lists can change without touching the
   * original's.
   */
  private openCopy(tab: DocTab, name: string): DocTab {
    return this.add(importDocx(exportDocx(tab.ctx, tab.view.state.doc)), null, name);
  }

  /** A click on a word the writing assistant would change. */
  showSuggestion(view: EditorView, id: number, target: HTMLElement): void {
    this.assist.showPopover(view, id, target);
  }

  private async closeTab(tab: DocTab): Promise<boolean> {
    if (tab.dirty) {
      this.activate(tab);

      const answer = await ask(
        `Save changes to “${tab.name}”?`,
        'Your changes will be lost if you do not save them.',
        [
          { label: 'Cancel', value: 'cancel' },
          { label: "Don't save", value: 'discard' },
          { label: 'Save', value: 'save', primary: true },
        ],
        'cancel',
      );

      if (answer === 'cancel' || (answer === 'save' && !(await this.save(tab, false)))) {
        tab.view.focus();
        return false;
      }
    }

    const at = this.tabs.indexOf(tab);

    this.tabs.splice(at, 1);
    tab.destroy();
    this.recovery.settled(tab);

    if (this.active === tab) {
      this.active = null;

      const next = this.tabs[Math.min(at, this.tabs.length - 1)];
      if (next) this.activate(next);
    }

    return true;
  }

  private async closeWindow(): Promise<void> {
    for (const tab of [...this.tabs]) {
      if (tab.dirty && !(await this.closeTab(tab))) return;
    }

    desktop.closeWindow();
  }

  // ---- Files ---------------------------------------------------------------------------------

  private async openFiles(files: OpenedFile[]): Promise<void> {
    for (const file of files) {
      const already = file.path ? this.tabs.find((tab) => tab.path === file.path) : null;

      if (already) {
        this.activate(already);
        continue;
      }

      try {
        const empty = this.tabs.length === 1 && this.tabs[0].pristine && !this.tabs[0].dirty ? this.tabs[0] : null;

        this.add(importDocx(file.bytes), file.path, file.name);
        // The untouched new document a file was opened over goes away, as a browser's new tab does.
        if (empty) void this.closeTab(empty);
      } catch (error) {
        await tell(`“${file.name}” could not be opened`, error instanceof Error ? error.message : String(error));
      }
    }
  }

  /** Prints the document, or writes it as a PDF: its pages as Pages view lays them out. */
  private async print(tab: DocTab, pdf: boolean): Promise<void> {
    updateFieldsBeforeSave(tab.view, tab.ctx);
    const { size, done } = prepareSheets(tab);

    try {
      if (!pdf) await desktop.print(size);
      else if (await desktop.exportPdf(`${tab.name.replace(/\.(docx|dotx)$/i, '')}.pdf`, size)) toast('Exported to PDF');
    } catch (error) {
      await tell(pdf ? 'The PDF could not be written' : 'The document could not be printed', String((error as Error)?.message ?? error));
    } finally {
      done();
    }
  }

  /** For `--pdf`: puts up the sheets of the document in front, and leaves them there. */
  prepareSheets(): { width: number; height: number } | null {
    return this.active ? prepareSheets(this.active).size : null;
  }

  /** `quiet`: AutoSave's save, which says nothing unless it fails. */
  private async save(tab: DocTab, saveAs: boolean, quiet = false): Promise<boolean> {
    let path = saveAs ? null : tab.path;

    if (!path) {
      path = await desktop.saveDialog(DOCUMENT.test(tab.name) ? tab.name : `${tab.name}.docx`);
      if (!path) return false;
    }

    updateFieldsBeforeSave(tab.view, tab.ctx);
    const doc = tab.view.state.doc;
    let problem: string | null;

    try {
      problem = await desktop.saveFile(path, exportDocx(tab.ctx, doc));
    } catch (error) {
      problem = error instanceof Error ? error.message : String(error);
    }

    if (problem) {
      if (quiet) toast(`AutoSave could not save “${tab.name}”: ${problem}`, true);
      else await tell(`“${tab.name}” could not be saved`, problem);
      return false;
    }

    if (desktop.isDesktop) {
      tab.path = path;
      tab.name = baseName(path);
    }

    tab.saved = doc;
    tab.partsChanged = false;
    tab.pristine = false;
    this.recovery.settled(tab);
    this.refresh();
    if (!quiet) toast('Saved');

    return true;
  }

  private async pickImage(): Promise<void> {
    const tab = this.active;
    const picked = await desktop.pickImage();

    if (!tab || !picked) return;

    const ok = await insertImageFile(tab.view, new Blob([picked.bytes as BlobPart], { type: picked.mime }), tab.ctx, picked.name);

    if (!ok) toast(`“${picked.name}” is not a picture the editor can read.`, true);
    tab.view.focus();
  }

  /**
   * The chart editor. With a position, or with a chart selected, it changes that chart; otherwise
   * it makes a new one, from the table the cursor is in if it is in one.
   */
  async editChart(pos?: number): Promise<void> {
    const tab = this.active;
    if (!tab || document.querySelector('.dialog-backdrop')) return;

    const state = tab.view.state;
    const at = pos ?? selectedChart(state)?.pos ?? null;
    const node = at === null ? null : state.doc.nodeAt(at);
    const existing = node?.type.name === 'chart' ? parseSpec(node.attrs.spec) : null;
    const table = existing ? null : tableAtCursor(state);
    let start: ChartSpec = existing ?? sampleSpec();
    let note: string | null = null;

    if (table) {
      start = { ...start, cells: table.map((row) => row.map((cell) => storedText(cell))) };
      note = 'Filled in from the table the cursor is in. The chart goes under the table.';
    } else if (existing && node?.attrs.part) {
      // A chart this editor wrote reads back as exactly what it would write again.
      const source = tab.ctx.pkg.text(node.attrs.part) ?? '';
      const original = parseSpec(node.attrs.orig);

      if (!original || chartXml(original, workbookRelOf(source)) !== source) {
        note = 'This chart was made in another program. Changing it here redraws it in the editor’s own style.';
      }
    }

    const spec = await chartDialog({ spec: start, isNew: !existing, note, pageMode: tab.page.dataset.mode ?? 'light' });

    if (spec && existing && at !== null) {
      // The dialog kept the document from changing under it, so the chart is where it was.
      if (tab.view.state.doc.nodeAt(at) === node) {
        tab.view.dispatch(tab.view.state.tr.setNodeMarkup(at, null, { ...node!.attrs, spec: specJson(spec) }));
      }
    } else if (spec) {
      const room = tab.ctx.page.width - tab.ctx.page.left - tab.ctx.page.right;
      const w = Math.max(160, Math.min(room, 528));

      insertChart(specJson(spec), w, Math.round(w * 0.58), !!table)(tab.view.state, tab.view.dispatch);
    }

    tab.view.focus();
  }

  private async onDrop(event: DragEvent): Promise<void> {
    const files = [...(event.dataTransfer?.files ?? [])];
    if (!files.length || event.defaultPrevented) return;

    // Without this the window would navigate to the dropped file.
    event.preventDefault();

    const opened: OpenedFile[] = [];

    for (const file of files.filter((f) => DOCUMENT.test(f.name))) {
      const read = await desktop.openDropped(file);
      if (read) opened.push(read);
    }

    await this.openFiles(opened);
  }

  // ---- Commands and keys ---------------------------------------------------------------------

  private run(command: Command): void {
    const view = this.active?.view;
    if (!view) return;

    command(view.state, view.dispatch, view);
    view.focus();
  }

  private onKey(event: KeyboardEvent): void {
    // F7, Word's key for checking the text: the writing assistant.
    if (event.key === 'F7' && !event.ctrlKey && !event.altKey && !document.querySelector('.dialog-backdrop')) {
      event.preventDefault();
      this.assist.toggle();
      return;
    }

    // Ctrl+Shift+O shows or hides the outline; Ctrl+Shift+G, Word's key for it, the statistics.
    if ((event.ctrlKey || event.metaKey) && event.shiftKey && !event.altKey && !document.querySelector('.dialog-backdrop') && (event.code === 'KeyO' || event.code === 'KeyG')) {
      event.preventDefault();
      event.stopPropagation();
      if (event.code === 'KeyO') this.outline.toggle();
      else this.stats.open();
      return;
    }

    // Word's keys for review: Ctrl+Shift+E switches tracking changes, Ctrl+Alt+M adds a comment.
    if ((event.ctrlKey || event.metaKey) && !document.querySelector('.dialog-backdrop')) {
      const review = event.shiftKey && !event.altKey && event.code === 'KeyE' ? 'track' : event.altKey && !event.shiftKey && event.code === 'KeyM' ? 'comment' : null;

      if (review) {
        event.preventDefault();
        event.stopPropagation();
        if (review === 'track') this.review.toggleTracking();
        else this.review.newComment();
        return;
      }
    }

    if (!(event.ctrlKey || event.metaKey) || event.altKey || document.querySelector('.dialog-backdrop')) return;

    const key = event.key.toLowerCase();
    const tab = this.active;
    let handled = true;

    if (key === 'n') this.newDocument();
    else if (key === 'o') void desktop.openDialog().then((files) => this.openFiles(files));
    else if (key === 's' && tab) void this.save(tab, event.shiftKey);
    else if (key === 'p' && tab) void this.print(tab, false);
    else if (key === 'w' && tab) void this.closeTab(tab).then(() => !this.tabs.length && this.newDocument());
    else if (key === 'tab' && this.tabs.length > 1 && tab) {
      const step = event.shiftKey ? -1 : 1;
      this.activate(this.tabs[(this.tabs.indexOf(tab) + step + this.tabs.length) % this.tabs.length]);
    } else if (key === 'f' || key === 'h') this.findbar.open();
    else if (key === 'k') this.toolbar.linkMenu();
    else if (key === '0') this.setZoom(1);
    else if (key === '+' || key === '=') this.setZoom(this.zoom + 0.1);
    else if (key === '-') this.setZoom(this.zoom - 0.1);
    else handled = false;

    if (handled) {
      event.preventDefault();
      event.stopPropagation();
    }
  }

  private onWheel(event: WheelEvent): void {
    if (!event.ctrlKey) return;

    event.preventDefault();
    this.setZoom(this.zoom + (event.deltaY < 0 ? 0.1 : -0.1));
  }

  // ---- Page, zoom and theme ------------------------------------------------------------------

  private setZoom(zoom: number): void {
    this.zoom = Math.round(Math.min(3, Math.max(0.5, zoom)) * 10) / 10;
    store(ZOOM_KEY, String(this.zoom));
    this.applyPage();
    // Text can wrap a little differently at another zoom.
    for (const tab of this.tabs) tab.pages.schedule(150);
  }

  private togglePages(): void {
    this.pagesOn = !this.pagesOn;
    store(PAGES_KEY, this.pagesOn ? 'on' : 'off');
    this.applyPage();
    this.refresh();
  }

  private togglePageMode(): void {
    this.pageMode = this.pageMode === 'match' ? 'white' : 'match';
    store(PAGE_KEY, this.pageMode);
    this.applyPage();
  }

  /**
   * Gives every page its mode and zoom. A page that follows its theme is dark in a medium or dark
   * one and takes the paper's tint in a light one; a theme whose paper is white has a white page
   * whatever the setting.
   */
  private applyPage(): void {
    const light = currentTheme().tone === 'light';
    const follows = this.pageMode === 'match' && (!light || paperIsTinted());
    const mode = !follows ? 'light' : light ? 'tint' : 'dark';

    for (const tab of this.tabs) {
      tab.page.dataset.mode = mode;
      tab.page.style.setProperty('--zoom', String(this.zoom));
    }

    // Only the document in front can be measured; the others are laid out when they come forward.
    this.active?.pages.setEnabled(this.pagesOn);
    for (const tab of this.tabs) if (tab !== this.active && !this.pagesOn) tab.pages.setEnabled(false);

    this.zoomLabel.textContent = `${Math.round(this.zoom * 100)}%`;
    this.pageButton.innerHTML = `${icon('page')}${{ light: 'White page', tint: 'Tinted page', dark: 'Dark page' }[mode]}`;
    this.pageButton.title =
      light && !paperIsTinted()
        ? 'The page is white in this theme'
        : mode === 'dark'
          ? 'The page follows the theme. Click to see it as it prints: white, in its own colours'
          : mode === 'tint'
            ? 'The page has the theme’s tint. Click to see it as it prints: white'
            : 'The page is shown as it prints. Click to have it follow the theme';
  }

  private toggleAutoSave(): void {
    this.recovery.autoSave = !this.recovery.autoSave;
    store(AUTOSAVE_KEY, this.recovery.autoSave ? 'on' : 'off');
    this.showAutoSave();
    if (this.recovery.autoSave) for (const tab of this.tabs) if (tab.dirty) this.recovery.touched(tab);
  }

  private showAutoSave(): void {
    this.autoSaveButton.setAttribute('aria-pressed', String(this.recovery.autoSave));
    this.autoSaveButton.textContent = this.recovery.autoSave ? 'AutoSave on' : 'AutoSave off';
    this.autoSaveButton.title = this.recovery.autoSave
      ? 'Documents that have a file are saved to it a few seconds after typing stops. Click to switch off'
      : 'Click to save documents that have a file to it automatically, a few seconds after typing stops';
  }

  private themes(): void {
    popover(this.themeButton, themeMenu(() => this.applyPage()), () => this.active?.view.focus());
  }

  // ---- Menus ---------------------------------------------------------------------------------

  private async fileMenu(): Promise<void> {
    const tab = this.active;
    const recent = await desktop.recentFiles();
    const item = (label: string, keys: string, action: () => void, enabled = true) =>
      h(
        'button',
        {
          class: 'menu-item',
          disabled: !enabled,
          onclick: () => {
            closePopover();
            action();
          },
        },
        h('span', { class: 'path' }, label),
        h('kbd', null, keys),
      );

    popover(
      this.fileButton,
      h(
        'div',
        null,
        item('New', 'Ctrl+N', () => this.newDocument()),
        item('Open…', 'Ctrl+O', () => void desktop.openDialog().then((files) => this.openFiles(files))),
        item('Save', 'Ctrl+S', () => tab && void this.save(tab, false), !!tab),
        item('Save as…', 'Ctrl+Shift+S', () => tab && void this.save(tab, true), !!tab),
        h('div', { class: 'menu-sep' }),
        item('Print…', 'Ctrl+P', () => tab && void this.print(tab, false), !!tab),
        item('Export to PDF…', '', () => tab && void this.print(tab, true), !!tab),
        item('Export as…', '', () => tab && void exportAs(tab), !!tab),
        recent.length > 0 && h('div', { class: 'menu-sep' }),
        recent.length > 0 && h('div', { class: 'menu-label' }, 'Recent'),
        ...recent.slice(0, 10).map((file) =>
          item(file.name, '', () => {
            void desktop.openRecent(file.path).then((opened) => {
              if (opened) return this.openFiles([opened]);
              return tell(`“${file.name}” could not be opened`, 'The file is no longer where it was.');
            });
          }),
        ),
        h('div', { class: 'menu-sep' }),
        item('Close document', 'Ctrl+W', () => tab && void this.closeTab(tab).then(() => !this.tabs.length && this.newDocument()), !!tab),
      ),
      () => this.active?.view.focus(),
    );
  }

  private async spellingMenu(): Promise<void> {
    const { available, enabled } = await desktop.spelling();
    const names = new Intl.DisplayNames(['en'], { type: 'language' });
    const chosen = new Set(enabled);
    const label = (code: string) => {
      try {
        return names.of(code) ?? code;
      } catch {
        return code;
      }
    };

    const sorted = [...available].sort((a, b) => Number(chosen.has(b)) - Number(chosen.has(a)) || label(a).localeCompare(label(b)));
    const list = h('div', { style: 'max-height:360px;overflow:auto' });

    for (const code of sorted) {
      const box = h('input', { type: 'checkbox', checked: chosen.has(code) });

      box.addEventListener('change', () => {
        if (box.checked) chosen.add(code);
        else chosen.delete(code);

        void desktop.setSpelling([...chosen]);
      });

      list.append(h('label', { class: 'check' }, box, label(code)));
    }

    popover(this.spellButton, h('div', null, h('div', { class: 'menu-label' }, 'Check spelling in'), list), () => this.active?.view.focus());
  }

  // ---- Keeping the interface in step ---------------------------------------------------------

  /**
   * A document's state changed. Everything that shows it is brought up to date a moment later,
   * once for however many changes came together. A timer, not an animation frame: a window that
   * is covered or minimised draws no frames, and its buttons would be left showing an old state.
   */
  changed(tab: DocTab): void {
    tab.refreshCss();

    // A change to the text, or to a part kept outside it, is for the next recovery copy.
    const seen = this.recoverySeen.get(tab);
    if (seen?.doc !== tab.view.state.doc || seen.parts !== tab.partsChanged) {
      this.recoverySeen.set(tab, { doc: tab.view.state.doc, parts: tab.partsChanged });
      this.recovery.touched(tab);
    }

    if (tab === this.active && !this.refreshQueued) {
      this.refreshQueued = true;

      setTimeout(() => {
        this.refreshQueued = false;
        this.refresh();
      }, 16);
    }
  }

  private refresh(): void {
    const tab = this.active;

    for (const each of this.tabs) {
      each.label.classList.toggle('dirty', each.dirty);
      each.label.title = each.path ?? each.name;
      each.label.querySelector('.name')!.textContent = each.name;
    }

    document.title = tab ? `${tab.name} — ${APP_NAME}` : APP_NAME;
    this.showPages();
    this.toolbar.update();
    this.findbar.refresh();
    this.assist.refresh();
    this.review.refresh();
    this.outline.refresh();

    // Counting words reads the whole text; it waits until typing pauses.
    clearTimeout(this.countTimer);
    this.countTimer = window.setTimeout(() => this.count(), 200);
  }

  /** The page the cursor is on, when the document is shown as pages; a switch to show it so otherwise. */
  private showPages(): void {
    const at = this.pagesOn && this.active ? pageAt(this.active.view.state) : null;

    this.pagesButton.innerHTML = `${icon('pages')}${this.pagesOn ? (at ? `Page ${at.page} of ${at.count}` : 'Page 1 of 1') : 'Pages'}`;
    this.pagesButton.setAttribute('aria-pressed', String(this.pagesOn));
    this.pagesButton.title = this.pagesOn
      ? 'Shown as pages. Click to show the document as one continuous page'
      : 'Shown as one continuous page. Click to show it as separate pages';
  }

  private count(): void {
    const view = this.active?.view;

    if (!view) {
      this.words.textContent = '';
      return;
    }

    const { doc, selection } = view.state;
    const words = (text: string) => text.match(/\S+/g)?.length ?? 0;
    const total = words(doc.textBetween(0, doc.content.size, ' ', ' '));
    const format = (n: number) => n.toLocaleString('en');

    this.words.textContent = selection.empty
      ? `${format(total)} ${total === 1 ? 'word' : 'words'}`
      : `${format(words(doc.textBetween(selection.from, selection.to, ' ', ' ')))} of ${format(total)} words`;
    // With a limit set, the count shows it, and turns red past it; a selection's count does not.
    this.stats.decorate(this.words, total, selection.empty ? doc : null);
  }
}

// For trying things out: #theme=paper&page=white in the address picks a look for this run only.
const params = new URLSearchParams(location.hash.slice(1));

applyTheme(params.get('theme') ?? savedTheme());

const app = new App(document.getElementById('app')!);

if (params.get('page') === 'white') (app as unknown as { pageMode: PageMode }).pageMode = 'white';

void app.start();

// A handle for the developer tools' console.
(window as unknown as { textStudio: App }).textStudio = app;
