// Turns a model's rewrite of a paragraph into separate changes, word by word, so that each one can
// be shown where it is and taken or left on its own.

/** A change to the original text: the characters from `from` to `to` become `insert`. */
export interface Change {
  from: number;
  to: number;
  insert: string;
}

interface Token {
  text: string;
  at: number;
}

// A word (letters and digits, with an apostrophe inside: don't, geht's), a line break, a run of
// other white space, or any other single character (punctuation).
const TOKEN = /\n|[^\S\n]+|[\p{L}\p{M}\p{N}_]+(?:['’][\p{L}\p{M}\p{N}_]+)*|[^\s\p{L}\p{M}\p{N}_]/gu;

export function tokenize(text: string): Token[] {
  return [...text.matchAll(TOKEN)].map((match) => ({ text: match[0], at: match.index }));
}

/** Past this many token pairs the table below gets too big; the paragraph becomes one change. */
const MAX_CELLS = 4_000_000;

/** For each pair of positions, how many tokens from there on the two have in common, in order. */
function commonTable(a: Token[], b: Token[]): Uint32Array {
  const width = b.length + 1;
  const table = new Uint32Array((a.length + 1) * width);

  for (let i = a.length - 1; i >= 0; i--) {
    for (let j = b.length - 1; j >= 0; j--) {
      table[i * width + j] = a[i].text === b[j].text ? table[(i + 1) * width + j + 1] + 1 : Math.max(table[(i + 1) * width + j], table[i * width + j + 1]);
    }
  }

  return table;
}

const isSpace = (text: string) => /^[^\S\n]+$/.test(text);

/**
 * The changes that make `before` into `after`. Tokens that are the same in both, in the same
 * order, stay; every stretch between them is a change. Two changes with only a space between them
 * are one, so that "help with edits" → "help editing" reads as a single suggestion.
 */
export function diffWords(before: string, after: string): Change[] {
  if (before === after) return [];

  const a = tokenize(before);
  const b = tokenize(after);

  if (a.length * b.length > MAX_CELLS) return [{ from: 0, to: before.length, insert: after }];

  const width = b.length + 1;
  const table = commonTable(a, b);
  const changes: Change[] = [];
  const endOf = (tokens: Token[], i: number, text: string) => (i < tokens.length ? tokens[i].at : text.length);
  let i = 0;
  let j = 0;

  while (i < a.length || j < b.length) {
    if (i < a.length && j < b.length && a[i].text === b[j].text) {
      i++;
      j++;
      continue;
    }

    // A stretch that differs: as far as the next token the two have in common.
    const startA = i;
    const startB = j;

    while (i < a.length || j < b.length) {
      if (i < a.length && j < b.length && a[i].text === b[j].text) break;

      if (j >= b.length || (i < a.length && table[(i + 1) * width + j] >= table[i * width + j + 1])) i++;
      else j++;
    }

    const from = endOf(a, startA, before);
    const to = endOf(a, i, before);
    const insert = after.slice(endOf(b, startB, after), endOf(b, j, after));
    const last = changes[changes.length - 1];
    const gap = last ? before.slice(last.to, from) : '';

    if (last && (gap === '' || isSpace(gap))) {
      last.to = to;
      last.insert += gap + insert;
    } else {
      changes.push({ from, to, insert });
    }
  }

  return changes.filter((change) => !isNoise(before.slice(change.from, change.to), change.insert));
}

/** A change only to the white space at a line break: the page would show nothing for it. */
function isNoise(removed: string, inserted: string): boolean {
  return removed.includes('\n') && /^\s*$/.test(removed) && /^\s*$/.test(inserted);
}
