// OMML to the equation editor's linear form: LaTeX, as parse.ts reads it back.
//
// Pure. Each structure has one way of writing it, chosen so that reading it back gives the same
// structure: `\frac{a}{b}`, `x_{i}^{2}`, `\left( … \right)`, `\sum_{i=1}^{n}{…}`. What has no
// linear form is written as its text, and the result says so (`lossy`), so the editor can warn.

import { type XmlEl, child, childrenNamed } from '../docx/xml';
import { allText, chr, flag, linesOf, mval, naryLimLoc, parseEquation, rowItems, runStyle, runText } from './omml';
import { ACCENT_NAMES, FUNCTIONS, GROUP_CHARS, INTEGRALS, LIMIT_FUNCTIONS, NARY, SYMBOLS } from './symbols';

/** The command a character is written as: the first name the symbol table gives it. */
const NAME_OF = new Map<string, string>();
for (const [name, c] of Object.entries(SYMBOLS)) {
  if (c.length === 1 && c.charCodeAt(0) > 127 && !NAME_OF.has(c)) NAME_OF.set(c, name);
}
// Spaces are not written as commands: space in an equation's text is not kept.
NAME_OF.delete(' ');

const NARY_NAME = new Map(Object.entries(NARY).map(([name, c]) => [c, name]));

/** Delimiter characters as `\left`/`\right` take them. */
const DELIM_OUT: Record<string, string> = {
  '': '.', '{': '\\{', '}': '\\}', '⟨': '\\langle', '⟩': '\\rangle', '‖': '\\|', '⌊': '\\lfloor', '⌋': '\\rfloor', '⌈': '\\lceil', '⌉': '\\rceil',
};

/** Characters that mean something in the linear form and are written escaped. */
const ESCAPED: Record<string, string> = {
  '{': '\\{', '}': '\\}', '\\': '\\backslash', '^': '\\^', '_': '\\_', '&': '\\&', '%': '\\%', '#': '\\#', '$': '\\$', '/': '\\slash',
};

const STYLE_OUT: Record<string, string> = { p: 'mathrm', b: 'mathbf', bi: 'boldsymbol' };
const SCRIPT_OUT: Record<string, string> = { script: 'mathcal', fraktur: 'mathfrak', 'double-struck': 'mathbb', 'sans-serif': 'mathsf', monospace: 'mathtt' };

const MATRIX_ENV: Record<string, string> = { '()': 'pmatrix', '[]': 'bmatrix', '||': 'vmatrix', '‖‖': 'Vmatrix', '{}': 'Bmatrix' };

/** Joins pieces, with a space where a command would otherwise run into the letter after it. */
function cat(pieces: string[]): string {
  let out = '';

  for (const piece of pieces) {
    if (!piece) continue;
    if (/\\[a-zA-Z]+$/.test(out) && /^[a-zA-Z0-9]/.test(piece)) out += ' ';
    out += piece;
  }

  return out;
}

class Writer {
  lossy = false;

  row(el: XmlEl | null | undefined, eqArr = false): string {
    return el ? cat(rowItems(el).map((c) => this.item(c, eqArr))) : '';
  }

  /** An argument, braced. */
  arg(el: XmlEl, name: string, eqArr = false): string {
    return `{${this.row(child(el, name), eqArr)}}`;
  }

  /** A script or base: braced unless it is one character. */
  small(el: XmlEl, name: string): string {
    const inner = this.row(child(el, name));
    return [...inner].length === 1 && !/[{}\\^_&]/.test(inner) ? inner : `{${inner}}`;
  }

  text(text: string, eqArr: boolean): string {
    let out = '';

    for (const c of text) {
      if (c === '&' && eqArr) out = cat([out, '&']);
      else if (ESCAPED[c]) out = cat([out, ESCAPED[c]]);
      else if (NAME_OF.has(c)) out = cat([out, `\\${NAME_OF.get(c)}`]);
      else out = cat([out, c === ' ' ? ' ' : c]);
    }

    return out;
  }

  run(r: XmlEl, eqArr: boolean): string {
    const style = runStyle(r);
    const text = runText(r);
    if (!text) return '';

    let out: string;

    if (style.nor) {
      out = `\\text{${text.replace(/[{}\\]/g, (c) => ESCAPED[c])}}`;
    } else if (style.sty === 'p' && !style.scr && FUNCTIONS.has(text)) {
      out = `\\${text}`;
    } else {
      out = this.text(text, eqArr);
      if (style.scr && SCRIPT_OUT[style.scr]) out = `\\${SCRIPT_OUT[style.scr]}{${out}}`;
      else if (style.sty && STYLE_OUT[style.sty]) out = `\\${STYLE_OUT[style.sty]}{${out}}`;
      if (style.scr && (style.sty === 'b' || style.sty === 'bi')) out = `\\mathbf{${out}}`;
    }

    return style.color ? `\\textcolor{#${style.color}}{${out}}` : out;
  }

  /** A function's name: `\sin`, `\lim_{x\to 0}`, `\operatorname{foo}`. */
  fname(el: XmlEl | null): string {
    const items = rowItems(el);
    const one = items.length === 1 ? items[0] : null;

    if (one?.name === 'm:limLow' || one?.name === 'm:sSub' || one?.name === 'm:sSup') {
      const base = rowItems(child(one, 'm:e'));
      const name = base.length === 1 && base[0].name === 'm:r' ? runText(base[0]) : '';

      if (/^[a-zA-Z]+$/.test(name)) {
        const head = FUNCTIONS.has(name) ? `\\${name}` : `\\operatorname{${name}}`;
        if (one.name === 'm:limLow') return LIMIT_FUNCTIONS.has(name) ? `${head}_{${this.row(child(one, 'm:lim'))}}` : `\\underset{${this.row(child(one, 'm:lim'))}}{${head}}`;
        return one.name === 'm:sSub' ? `${head}_{${this.row(child(one, 'm:sub'))}}` : `${head}^{${this.row(child(one, 'm:sup'))}}`;
      }
    }

    if (one?.name === 'm:r') {
      const name = runText(one);
      if (FUNCTIONS.has(name)) return `\\${name}`;
      if (/^[a-zA-Z]+$/.test(name)) return `\\operatorname{${name}}`;
    }

    return `\\operatorname{${this.row(el)}}`;
  }

  item(el: XmlEl, eqArr: boolean): string {
    const pr = child(el, `${el.name}Pr`);

    switch (el.name) {
      case 'm:r':
      case 'w:r':
        return this.run(el, eqArr);

      case 'm:f': {
        const type = mval(pr, 'm:type') ?? 'bar';
        const num = this.row(child(el, 'm:num'));
        const den = this.row(child(el, 'm:den'));
        if (type === 'noBar') return `{${num} \\atop ${den}}`;
        if (type === 'skw') return `\\sfrac{${num}}{${den}}`;
        if (type === 'lin') return `\\linfrac{${num}}{${den}}`;
        return `\\frac{${num}}{${den}}`;
      }

      case 'm:sSub':
        return `${this.small(el, 'm:e')}_${this.small(el, 'm:sub')}`;
      case 'm:sSup':
        return `${this.small(el, 'm:e')}^${this.small(el, 'm:sup')}`;
      case 'm:sSubSup':
        return `${this.small(el, 'm:e')}_${this.small(el, 'm:sub')}^${this.small(el, 'm:sup')}`;
      case 'm:sPre':
        return `\\prescript${this.arg(el, 'm:sup')}${this.arg(el, 'm:sub')}${this.arg(el, 'm:e')}`;

      case 'm:rad': {
        const deg = this.row(child(el, 'm:deg'));
        return flag(pr, 'm:degHide') || !deg ? `\\sqrt${this.arg(el, 'm:e')}` : `\\sqrt[${deg}]${this.arg(el, 'm:e')}`;
      }

      case 'm:nary': {
        const c = chr(pr, 'm:chr', '∫') || '∫';
        const name = NARY_NAME.get(c);
        let out = name ? `\\${name}` : c;
        const loc = naryLimLoc(pr, c);
        const usual = INTEGRALS.has(c) ? 'subSup' : 'undOvr';
        if (mval(pr, 'm:limLoc') && loc !== usual) out += loc === 'undOvr' ? '\\limits' : '\\nolimits';
        if (!flag(pr, 'm:subHide')) out += `_${this.arg(el, 'm:sub')}`;
        if (!flag(pr, 'm:supHide')) out += `^${this.arg(el, 'm:sup')}`;
        return out + this.arg(el, 'm:e');
      }

      case 'm:d': {
        const beg = chr(pr, 'm:begChr', '(');
        const end = chr(pr, 'm:endChr', ')');
        const sep = chr(pr, 'm:sepChr', '|');
        const parts = childrenNamed(el, 'm:e');
        const only = parts.length === 1 ? rowItems(parts[0]) : [];

        if (only.length === 1 && only[0].name === 'm:m' && MATRIX_ENV[beg + end]) return this.matrix(only[0], MATRIX_ENV[beg + end]);
        if (only.length === 1 && only[0].name === 'm:eqArr' && beg === '{' && end === '') return this.rows(only[0], 'cases');

        const delim = (c: string) => DELIM_OUT[c] ?? (c.length === 1 && NAME_OF.has(c) ? `\\${NAME_OF.get(c)}` : c);
        const middle = ` \\middle${delim(sep).startsWith('\\') ? '' : ' '}${delim(sep)} `;
        return `\\left${delim(beg)}${parts.map((p) => this.row(p)).join(middle)}\\right${delim(end)}`;
      }

      case 'm:func':
        return `${this.fname(child(el, 'm:fName'))}${this.arg(el, 'm:e')}`;

      case 'm:acc': {
        const c = chr(pr, 'm:chr', '̂');
        if (!ACCENT_NAMES[c]) this.lossy = true;
        return `\\${ACCENT_NAMES[c] ?? 'hat'}${this.arg(el, 'm:e')}`;
      }

      case 'm:bar':
        return `\\${mval(pr, 'm:pos') === 'top' ? 'overline' : 'underline'}${this.arg(el, 'm:e')}`;

      case 'm:limLow':
      case 'm:limUpp': {
        const low = el.name === 'm:limLow';
        const base = rowItems(child(el, 'm:e'));
        const lim = this.arg(el, 'm:lim');

        // An underbrace with its label, as Word builds `\underbrace{…}_{…}`.
        if (base.length === 1 && base[0].name === 'm:groupChr') {
          const gpos = mval(child(base[0], 'm:groupChrPr'), 'm:pos') === 'top' ? 'top' : 'bot';
          if ((gpos === 'bot') === low) return `${this.item(base[0], false)}${low ? '_' : '^'}${lim}`;
        }

        return `\\${low ? 'underset' : 'overset'}${lim}${this.arg(el, 'm:e')}`;
      }

      case 'm:groupChr': {
        const c = chr(pr, 'm:chr', '⏟');
        const pos = mval(pr, 'm:pos') === 'top' ? 'top' : 'bot';
        const name = Object.entries(GROUP_CHARS).find(([, g]) => g.chr === c && g.pos === pos)?.[0];
        if (!name) this.lossy = true;
        return `\\${name ?? (pos === 'top' ? 'overbrace' : 'underbrace')}${this.arg(el, 'm:e')}`;
      }

      case 'm:m':
        return this.matrix(el, 'matrix');
      case 'm:eqArr':
        return this.rows(el, 'aligned');

      case 'm:box':
        return `\\box${this.arg(el, 'm:e')}`;
      case 'm:borderBox':
        return `\\boxed${this.arg(el, 'm:e')}`;
      case 'm:phant':
        return child(pr, 'm:show') && !flag(pr, 'm:show') ? `\\phantom${this.arg(el, 'm:e')}` : this.arg(el, 'm:e');

      default:
        this.lossy = true;
        return `\\text{${allText(el).replace(/[{}\\]/g, (c) => ESCAPED[c])}}`;
    }
  }

  matrix(el: XmlEl, env: string): string {
    const rows = childrenNamed(el, 'm:mr').map((mr) => childrenNamed(mr, 'm:e').map((e) => this.row(e)).join(' & '));
    return `\\begin{${env}}${rows.join(' \\\\ ')}\\end{${env}}`;
  }

  rows(el: XmlEl, env: string): string {
    const rows = childrenNamed(el, 'm:e').map((e) => this.row(e, true));
    return `\\begin{${env}}${rows.join(' \\\\ ')}\\end{${env}}`;
  }
}

export interface Linear {
  text: string;
  /** Some of the equation has no linear form and was written as its text. */
  lossy: boolean;
}

/** An equation's XML in linear form. The lines of a display equation are separated by `\\`. */
export function ommlToLinear(xml: string): Linear {
  const el = parseEquation(xml);
  if (!el) return { text: '', lossy: true };

  const writer = new Writer();
  const text = linesOf(el).map((line) => writer.row(line)).join(' \\\\ ');
  return { text, lossy: writer.lossy };
}
