// A chart as Word keeps it: a part of its own (word/charts/chart1.xml) that says what kind of
// chart it is, points at the cells of an embedded workbook, and carries a copy of their values
// so that it can be drawn without opening the workbook.
//
// `chartXml` writes that part from the editor's chart; `readChart` reads one back, whoever wrote
// it. What it reads is the kind, the title, the legend, the colours and the numbers. A chart of a
// kind the editor does not draw (radar, stock, a column chart with a line on a second axis, ...)
// reads as null and stays the placeholder it always was.

import { escAttr, escText, type XmlEl, child, childrenNamed, descendants } from '../docx/xml';
import { colName } from './formula';
import { type ChartKind, type ChartSpec, MAX_COLS, MAX_ROWS, PALETTE, colorOf, dataOf, isColor } from './model';

const C_NS = 'http://schemas.openxmlformats.org/drawingml/2006/chart';
const A_NS = 'http://schemas.openxmlformats.org/drawingml/2006/main';
const R_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';

/** The workbook's one sheet. */
export const SHEET = 'Sheet1';

const CAT_AXIS = 111111111;
const VAL_AXIS = 222222222;
const GREY = 'D9D9D9';
const TEXT = '595959';

// ---- Writing -------------------------------------------------------------------------------

const solid = (color: string) => `<a:solidFill><a:srgbClr val="${color.replace('#', '')}"/></a:solidFill>`;
const stroke = (color: string, width: number) => `<a:ln w="${width}" cap="rnd">${solid(color)}<a:round/></a:ln>`;
const NO_LINE = '<a:ln><a:noFill/></a:ln>';
const HAIRLINE = `<a:ln w="9525" cap="flat">${solid(GREY)}<a:round/></a:ln>`;
const GRIDLINES = `<c:majorGridlines><c:spPr>${HAIRLINE}</c:spPr></c:majorGridlines>`;

const cellRef = (row: number, col: number) => `${SHEET}!$${colName(col)}$${row + 1}`;
const columnRef = (col: number, count: number) => `${cellRef(1, col)}:$${colName(col)}$${count + 1}`;

function strRef(ref: string, texts: string[]): string {
  const points = texts.map((text, i) => `<c:pt idx="${i}"><c:v>${escText(text)}</c:v></c:pt>`).join('');

  return `<c:strRef><c:f>${ref}</c:f><c:strCache><c:ptCount val="${texts.length}"/>${points}</c:strCache></c:strRef>`;
}

function numRef(ref: string, values: (number | null)[]): string {
  const points = values.map((value, i) => (value === null ? '' : `<c:pt idx="${i}"><c:v>${value}</c:v></c:pt>`)).join('');

  return `<c:numRef><c:f>${ref}</c:f><c:numCache><c:formatCode>General</c:formatCode><c:ptCount val="${values.length}"/>${points}</c:numCache></c:numRef>`;
}

function text(size: number, content: string): string {
  return (
    `<c:tx><c:rich><a:bodyPr/><a:lstStyle/><a:p><a:pPr><a:defRPr sz="${size}" b="0">${solid(TEXT)}</a:defRPr></a:pPr>` +
    `<a:r><a:rPr lang="en-US" sz="${size}" b="0">${solid(TEXT)}</a:rPr><a:t>${escText(content)}</a:t></a:r></a:p></c:rich></c:tx>`
  );
}

function axis(kind: 'cat' | 'val', id: number, crosses: number, position: string, options: { grid?: boolean; line?: boolean; between?: string }): string {
  const look = options.line ? `<c:spPr><a:noFill/>${HAIRLINE}</c:spPr>` : `<c:spPr><a:noFill/>${NO_LINE}</c:spPr>`;
  const head =
    `<c:axId val="${id}"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:delete val="0"/><c:axPos val="${position}"/>` +
    `${options.grid ? GRIDLINES : ''}<c:numFmt formatCode="General" sourceLinked="1"/><c:majorTickMark val="none"/><c:minorTickMark val="none"/>` +
    `<c:tickLblPos val="low"/>${look}<c:crossAx val="${crosses}"/><c:crosses val="autoZero"/>`;

  return kind === 'cat'
    ? `<c:catAx>${head}<c:auto val="1"/><c:lblAlgn val="ctr"/><c:lblOffset val="100"/><c:noMultiLvlLbl val="0"/></c:catAx>`
    : `<c:valAx>${head}<c:crossBetween val="${options.between ?? 'between'}"/></c:valAx>`;
}

/**
 * The chart part. `workbookRel` is the id of the part's relationship to its workbook, or null for
 * a chart that has none and is drawn from the values written here.
 */
export function chartXml(spec: ChartSpec, workbookRel: string | null): string {
  const data = dataOf(spec);
  const count = data.categories.length;
  const { kind } = spec;
  const stacked = spec.stacked && (kind === 'column' || kind === 'bar' || kind === 'area');
  const marker = (color: string) => `<c:marker><c:symbol val="circle"/><c:size val="5"/><c:spPr>${solid(color)}<a:ln w="9525">${solid(color)}</a:ln></c:spPr></c:marker>`;

  const series = (kind === 'pie' ? data.series.slice(0, 1) : data.series).map((one, i) => {
    const color = colorOf(spec, i);
    const head = `<c:idx val="${i}"/><c:order val="${i}"/><c:tx>${strRef(cellRef(0, i + 1), [one.name])}</c:tx>`;
    const cat = `<c:cat>${strRef(columnRef(0, count), data.categories)}</c:cat>`;
    const val = `<c:val>${numRef(columnRef(i + 1, count), one.values)}</c:val>`;

    switch (kind) {
      case 'column':
      case 'bar':
        return `<c:ser>${head}<c:spPr>${solid(color)}${NO_LINE}</c:spPr><c:invertIfNegative val="0"/>${cat}${val}</c:ser>`;
      case 'area':
        return `<c:ser>${head}<c:spPr>${solid(color)}${NO_LINE}</c:spPr>${cat}${val}</c:ser>`;
      case 'line':
        return `<c:ser>${head}<c:spPr>${stroke(color, 28575)}</c:spPr>${marker(color)}${cat}${val}<c:smooth val="0"/></c:ser>`;
      case 'scatter':
        return (
          `<c:ser>${head}<c:spPr><a:ln w="19050" cap="rnd"><a:noFill/><a:round/></a:ln></c:spPr>${marker(color)}` +
          `<c:xVal>${numRef(columnRef(0, count), data.xs)}</c:xVal><c:yVal>${numRef(columnRef(i + 1, count), one.values)}</c:yVal><c:smooth val="0"/></c:ser>`
        );
      case 'pie': {
        const slices = data.categories
          .map((_name, k) => `<c:dPt><c:idx val="${k}"/><c:bubble3D val="0"/><c:spPr>${solid(colorOf(spec, k))}<a:ln w="19050">${solid('FFFFFF')}</a:ln></c:spPr></c:dPt>`)
          .join('');

        return `<c:ser>${head}${slices}${cat}${val}</c:ser>`;
      }
    }
  });

  const all = series.join('');
  const axes = `<c:axId val="${CAT_AXIS}"/><c:axId val="${VAL_AXIS}"/>`;
  let plot: string;

  switch (kind) {
    case 'column':
    case 'bar':
      plot =
        `<c:barChart><c:barDir val="${kind === 'bar' ? 'bar' : 'col'}"/><c:grouping val="${stacked ? 'stacked' : 'clustered'}"/><c:varyColors val="0"/>${all}` +
        `<c:gapWidth val="150"/>${stacked ? '<c:overlap val="100"/>' : ''}${axes}</c:barChart>` +
        axis('cat', CAT_AXIS, VAL_AXIS, kind === 'bar' ? 'l' : 'b', { line: true }) +
        axis('val', VAL_AXIS, CAT_AXIS, kind === 'bar' ? 'b' : 'l', { grid: true });
      break;
    case 'line':
      plot =
        `<c:lineChart><c:grouping val="standard"/><c:varyColors val="0"/>${all}<c:marker val="1"/>${axes}</c:lineChart>` +
        axis('cat', CAT_AXIS, VAL_AXIS, 'b', { line: true }) +
        axis('val', VAL_AXIS, CAT_AXIS, 'l', { grid: true });
      break;
    case 'area':
      plot =
        `<c:areaChart><c:grouping val="${stacked ? 'stacked' : 'standard'}"/><c:varyColors val="0"/>${all}${axes}</c:areaChart>` +
        axis('cat', CAT_AXIS, VAL_AXIS, 'b', { line: true }) +
        axis('val', VAL_AXIS, CAT_AXIS, 'l', { grid: true });
      break;
    case 'scatter':
      plot =
        `<c:scatterChart><c:scatterStyle val="lineMarker"/><c:varyColors val="0"/>${all}${axes}</c:scatterChart>` +
        axis('val', CAT_AXIS, VAL_AXIS, 'b', { grid: true, line: true, between: 'midCat' }) +
        axis('val', VAL_AXIS, CAT_AXIS, 'l', { grid: true, between: 'midCat' });
      break;
    case 'pie':
      plot = `<c:pieChart><c:varyColors val="1"/>${all}<c:firstSliceAng val="0"/></c:pieChart>`;
      break;
  }

  const title = spec.title.trim();

  return (
    `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n` +
    `<c:chartSpace xmlns:c="${C_NS}" xmlns:a="${A_NS}" xmlns:r="${R_NS}"><c:date1904 val="0"/><c:roundedCorners val="0"/><c:chart>` +
    (title ? `<c:title>${text(1400, title)}<c:overlay val="0"/></c:title><c:autoTitleDeleted val="0"/>` : '<c:autoTitleDeleted val="1"/>') +
    `<c:plotArea><c:layout/>${plot}</c:plotArea>` +
    (spec.legend ? '<c:legend><c:legendPos val="b"/><c:overlay val="0"/></c:legend>' : '') +
    `<c:plotVisOnly val="1"/><c:dispBlanksAs val="gap"/></c:chart><c:spPr><a:noFill/>${NO_LINE}</c:spPr>` +
    `<c:txPr><a:bodyPr/><a:lstStyle/><a:p><a:pPr><a:defRPr sz="900">${solid(TEXT)}</a:defRPr></a:pPr><a:endParaRPr lang="en-US"/></a:p></c:txPr>` +
    (workbookRel ? `<c:externalData r:id="${escAttr(workbookRel)}"><c:autoUpdate val="0"/></c:externalData>` : '') +
    `</c:chartSpace>`
  );
}

/** The id of the chart part's relationship to its workbook, as the part names it. */
export function workbookRelOf(xml: string): string | null {
  return /<c:externalData\b[^>]*?\br:id="([^"]*)"/.exec(xml)?.[1] ?? null;
}

// ---- Reading -------------------------------------------------------------------------------

const KIND_OF: Record<string, ChartKind> = {
  'c:barChart': 'column', 'c:bar3DChart': 'column', 'c:lineChart': 'line', 'c:line3DChart': 'line', 'c:areaChart': 'area', 'c:area3DChart': 'area',
  'c:pieChart': 'pie', 'c:pie3DChart': 'pie', 'c:scatterChart': 'scatter',
};

const valOf = (el: XmlEl | null, name: string): string | null => child(el, name)?.attrs.val ?? null;

/** A cache of points as a list as long as the cache says it is; null where it has no point. */
function points(cache: XmlEl | null): (string | null)[] | null {
  if (!cache) return null;

  const list: (string | null)[] = new Array(Math.max(0, Number(valOf(cache, 'c:ptCount')) || 0)).fill(null);

  for (const pt of childrenNamed(cache, 'c:pt')) {
    const at = Number(pt.attrs.idx);
    if (!Number.isInteger(at) || at < 0 || at >= MAX_ROWS) continue;

    while (list.length <= at) list.push(null);
    list[at] = child(pt, 'c:v')?.text ?? '';
  }

  return list;
}

/** The points under `c:cat`, `c:val` and the like, from whichever of the four shapes they have. */
function pointsUnder(el: XmlEl | null): (string | null)[] | null {
  const ref = child(el, 'c:strRef') ?? child(el, 'c:numRef');

  return points(child(ref, 'c:strCache') ?? child(ref, 'c:numCache') ?? child(el, 'c:strLit') ?? child(el, 'c:numLit'));
}

/** The plain colour a shape is filled with; '' for none, a gradient, or a colour worked out from another. */
function fill(holder: XmlEl | null, accents: readonly string[]): string {
  const solidFill = child(holder, 'a:solidFill');
  const rgb = child(solidFill, 'a:srgbClr')?.attrs.val;

  if (rgb && isColor(`#${rgb}`)) return `#${rgb.toUpperCase()}`;

  const scheme = /^accent([1-6])$/.exec(child(solidFill, 'a:schemeClr')?.attrs.val ?? '');
  return scheme ? (accents[Number(scheme[1]) - 1] ?? '') : '';
}

const numberText = (value: string | null): string => {
  const n = value === null || value.trim() === '' ? NaN : Number(value);
  return Number.isFinite(n) ? String(n) : '';
};

/** Whether a number format shows a date: it has day, month or year letters, and no hours. */
function isDateFormat(code: string): boolean {
  const letters = code.replace(/"[^"]*"|\[[^\]]*\]|\\./g, '');

  return /[dmy]/i.test(letters) && !/[hs0#]/i.test(letters) && !/general/i.test(letters);
}

/** A day number as Excel counts them, written as a date the way this computer writes dates. */
function dateText(serial: string | null, from1904: boolean): string | null {
  const days = serial === null || serial.trim() === '' ? NaN : Number(serial);
  if (!Number.isFinite(days)) return serial;

  const date = new Date(Date.UTC(1899, 11, 30) + (days + (from1904 ? 1462 : 0)) * 86400000);

  return new Intl.DateTimeFormat(undefined, { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'UTC' }).format(date);
}

/** The six accent colours of a document's theme, which its charts take their colours from. */
export function accentColors(theme: XmlEl | null): string[] {
  const scheme = child(child(theme, 'a:themeElements'), 'a:clrScheme');
  const colors: string[] = [];

  for (let i = 1; i <= 6; i++) {
    const accent = child(scheme, `a:accent${i}`);
    const rgb = child(accent, 'a:srgbClr')?.attrs.val ?? child(accent, 'a:sysClr')?.attrs.lastClr ?? '';

    colors.push(isColor(`#${rgb}`) ? `#${rgb.toUpperCase()}` : PALETTE[i - 1]);
  }

  return colors;
}

/**
 * Reads a chart part. `accents` are the document theme's six accent colours, which a chart that
 * names no colours of its own is drawn in.
 */
export function readChart(root: XmlEl, accents: readonly string[] = PALETTE): ChartSpec | null {
  const chart = child(root, 'c:chart');
  const plotArea = child(chart, 'c:plotArea');
  const groups = (plotArea?.children ?? []).filter((el) => /^c:\w+Chart$/.test(el.name));

  // Two groups are a chart of two kinds at once, a line over columns say; that is not drawn here.
  if (root.name !== 'c:chartSpace' || groups.length !== 1) return null;

  const group = groups[0];
  const grouping = valOf(group, 'c:grouping');
  let kind = KIND_OF[group.name];

  if (!kind || grouping === 'percentStacked') return null;
  if (kind === 'column' && valOf(group, 'c:barDir') === 'bar') kind = 'bar';

  const sers = childrenNamed(group, 'c:ser')
    .map((ser, i) => ({ ser, order: Number(valOf(ser, 'c:order') ?? i) }))
    .sort((a, b) => a.order - b.order)
    .map((item) => item.ser);

  if (!sers.length || sers.length >= MAX_COLS) return null;

  const first = sers[0];

  // Categories on two levels (months under years) have no place in a sheet with one column of names.
  if (sers.some((ser) => child(child(ser, 'c:cat'), 'c:multiLvlStrRef'))) return null;

  const names = pointsUnder(child(first, kind === 'scatter' ? 'c:xVal' : 'c:cat')) ?? [];
  const dated = kind !== 'scatter' && isDateFormat(child(child(child(child(first, 'c:cat'), 'c:numRef'), 'c:numCache'), 'c:formatCode')?.text ?? '');

  // Categories that are dates are kept as day numbers; a sheet of plain cells holds them written out.
  if (dated) names.forEach((name, k) => (names[k] = dateText(name, valOf(root, 'c:date1904') === '1')));

  const columns: (string | null)[][] = [];
  const header: string[] = [''];
  const colors: string[] = [];

  for (const [i, ser] of sers.entries()) {
    const tx = child(ser, 'c:tx');
    const spPr = child(ser, 'c:spPr');
    const markerFill = fill(child(child(ser, 'c:marker'), 'c:spPr'), accents);
    const lineFill = fill(child(spPr, 'a:ln'), accents);

    // Every series of a scatter chart has to share the first one's x values to share a column.
    if (kind === 'scatter' && i > 0 && JSON.stringify(pointsUnder(child(ser, 'c:xVal')) ?? []) !== JSON.stringify(names)) return null;

    header.push(pointsUnder(tx)?.[0] ?? child(tx, 'c:v')?.text ?? '');
    columns.push(pointsUnder(child(ser, kind === 'scatter' ? 'c:yVal' : 'c:val')) ?? []);

    if (kind !== 'pie') {
      colors.push((kind === 'line' ? lineFill : kind === 'scatter' ? markerFill || lineFill : fill(spPr, accents)) || (accents[i % accents.length] ?? ''));
    }
  }

  const count = Math.max(names.length, ...columns.map((column) => column.length));

  if (count < 1 || count >= MAX_ROWS) return null;

  if (kind === 'pie') {
    for (let k = 0; k < count; k++) colors.push(accents[k % accents.length] ?? '');

    for (const dPt of childrenNamed(first, 'c:dPt')) {
      const at = Number(valOf(dPt, 'c:idx'));
      const color = fill(child(dPt, 'c:spPr'), accents);

      if (color && at >= 0 && at < count) colors[at] = color;
    }
  }

  const cells = [header];

  for (let k = 0; k < count; k++) {
    const name = names[k] ?? '';
    cells.push([kind === 'scatter' ? numberText(name) : name, ...columns.map((column) => numberText(column[k] ?? null))]);
  }

  const titleEl = child(chart, 'c:title');
  const paragraphs = titleEl ? descendants(titleEl, 'a:p').map((p) => descendants(p, 'a:t').map((t) => t.text).join('')) : [];
  let title = paragraphs.join(' ').trim();

  // A title with no words of its own is Word's automatic one: the name of the only series.
  if (titleEl && !title && sers.length === 1 && !child(titleEl, 'c:tx')) title = header[1];

  return {
    kind,
    title,
    stacked: grouping === 'stacked',
    legend: !!child(chart, 'c:legend'),
    cells,
    colors: colors.map((color, i) => (color === PALETTE[i % PALETTE.length] ? '' : color)),
  };
}
