// The find bar's formatting filter: what the text that is looked for must look like.

import type { FormatFilter } from '../editor/formatmatch';
import { cleanFilter } from '../editor/formatmatch';
import { h } from './dom';

export interface FilterOptions {
  fonts: string[];
  colors: { text: string[]; highlight: string[] };
  /** The document's paragraph styles that exist: id and name. */
  styles: { value: string; label: string }[];
  onChange(filter: FormatFilter | null): void;
}

type Toggle = 'bold' | 'italic' | 'underline' | 'strike';

const TOGGLES: { key: Toggle; glyph: string; cls: string; any: string; yes: string; no: string }[] = [
  { key: 'bold', glyph: 'B', cls: 'b', any: 'Bold or not', yes: 'Only bold text', no: 'Only text that is not bold' },
  { key: 'italic', glyph: 'I', cls: 'i', any: 'Italic or not', yes: 'Only italic text', no: 'Only text that is not italic' },
  { key: 'underline', glyph: 'U', cls: 'u', any: 'Underlined or not', yes: 'Only underlined text', no: 'Only text that is not underlined' },
  { key: 'strike', glyph: 'S', cls: 's', any: 'Struck through or not', yes: 'Only struck-through text', no: 'Only text that is not struck through' },
];

/** The controls for a filter. Every change is reported at once. */
export function filterEditor(start: FormatFilter | null, options: FilterOptions): HTMLElement {
  const filter: FormatFilter = { ...(start ?? {}) };
  const changed = () => options.onChange(cleanFilter(filter));

  // Bold, italic, …: any, yes, no, round and round.
  const toggles = TOGGLES.map((t) => {
    const button = h('button', { class: 'tool tri', html: `<span class="glyph ${t.cls}">${t.glyph}</span>` });
    const show = () => {
      const value = filter[t.key];
      button.dataset.state = value === undefined ? 'any' : value ? 'yes' : 'no';
      button.setAttribute('aria-pressed', String(value !== undefined));
      button.title = value === undefined ? t.any : value ? t.yes : t.no;
    };

    button.addEventListener('click', () => {
      const value = filter[t.key];
      filter[t.key] = value === undefined ? true : value ? false : undefined;
      show();
      changed();
    });

    show();
    return button;
  });

  // Font and size.
  const font = h('select', { class: 'tool-select font', title: 'Font' }, h('option', { value: '' }, 'Any font'), ...options.fonts.map((f) => h('option', { value: f }, f)));
  if (filter.font && !options.fonts.some((f) => f.toLowerCase() === filter.font!.toLowerCase())) font.append(h('option', { value: filter.font }, filter.font));
  font.value = filter.font ?? '';
  font.addEventListener('change', () => {
    filter.font = font.value || undefined;
    changed();
  });

  const size = h('input', { class: 'tool-input size', title: 'Font size, in points', placeholder: 'Any size', list: 'font-sizes', inputmode: 'decimal' });
  size.value = filter.size !== undefined ? String(filter.size) : '';
  size.addEventListener('change', () => {
    const pt = parseFloat(size.value.replace(',', '.'));
    filter.size = pt >= 1 && pt <= 1638 ? Math.round(pt * 2) / 2 : undefined;
    if (filter.size === undefined) size.value = '';
    changed();
  });

  // Colours: any, a "none" choice, then the palette.
  const swatches = (key: 'color' | 'highlight', colors: string[], none: string, noneValue: string) => {
    const row = h('div', { class: 'swatches' });
    const buttons: HTMLButtonElement[] = [];
    const show = () => {
      for (const b of buttons) b.setAttribute('aria-pressed', String((b.dataset.value ?? '') === (filter[key] ?? '').toUpperCase()));
    };
    const pick = (value: string | undefined) => {
      filter[key] = filter[key] === value ? undefined : value;
      show();
      changed();
    };

    buttons.push(h('button', { class: 'swatch any', title: 'Any', 'data-value': '', onclick: () => pick(undefined) }, '∗'));
    buttons.push(h('button', { class: 'swatch none', title: none, 'data-value': noneValue.toUpperCase(), onclick: () => pick(noneValue) }));
    for (const value of colors) {
      buttons.push(h('button', { class: 'swatch', title: value, style: `background:${value}`, 'data-value': value.toUpperCase(), onclick: () => pick(value) }));
    }

    row.append(...buttons);
    show();
    return row;
  };

  // Paragraph style.
  const style = h('select', { class: 'tool-select style', title: 'Only text in paragraphs of this style' }, h('option', { value: '\u0000' }, 'Any paragraph style'));
  for (const choice of options.styles) style.append(h('option', { value: choice.value }, choice.label));
  style.value = filter.style ?? '\u0000';
  style.addEventListener('change', () => {
    filter.style = style.value === '\u0000' ? undefined : style.value;
    changed();
  });

  const clear = h('button', { class: 'button', title: 'Look for text however it is formatted' }, 'Any formatting');
  const el = h(
    'div',
    { class: 'find-format find-filter' },
    h('div', { class: 'menu-label' }, 'Find only text that is'),
    h('div', { class: 'find-format-row' }, ...toggles),
    h('div', { class: 'find-format-row' }, font, size),
    h('div', { class: 'menu-label' }, 'Text colour'),
    swatches('color', options.colors.text.slice(0, 20), 'Automatic', 'auto'),
    h('div', { class: 'menu-label' }, 'Highlight'),
    swatches('highlight', options.colors.highlight, 'No highlight', 'none'),
    h('div', { class: 'menu-label' }, 'Paragraph style'),
    style,
    h('div', { class: 'find-format-row' }, clear),
    h('p', { class: 'note' }, 'With nothing typed in Find, every stretch of text with this formatting is found.'),
  );

  clear.addEventListener('click', () => {
    for (const key of Object.keys(filter)) delete filter[key as keyof FormatFilter];
    options.onChange(null);
    el.replaceWith(filterEditor(null, options));
  });

  return el;
}
