// Terms written more than one way in a document: "e-mail" and "email", "data set", "data-set"
// and "dataset". Forms are the same term when they are the same letters once spaces and hyphens
// are taken out. Pairs of short everyday words ("in to", "may be", "every day") are left alone:
// those are different words, not spellings of one term.

import { type Finding, matchCase, type Spot, type TextEdit, wordsOf } from './types';

const STOP = new Set(
  `a an the and or but nor so yet of to in on at by for from with into onto upon as is are was were be been being am do does did
  have has had may might can could will would shall should must not no any every some all each one ones other another this that
  these those there here who whom whose which what when where why how it its it's he she we they you i me my our your their his her
  them us than then also too very more most less least such out up down off over under again once only own same few both else ever
  never per via about above after before below between during through until while against among within without whatever
  der die das ein eine einer eines einem einen und oder aber in im an am auf aus bei mit nach von vor zu zur zum ist sind war
  waren wird werden hat haben nicht kein keine es er sie wir ihr ich du man so wie als auch noch nur schon sehr mehr dass ob`
    .split(/\s+/)
    .filter(Boolean),
);

interface Form {
  /** The form as written, in lower case: "data set", "data-set", "dataset". */
  form: string;
  spots: Spot[];
}

const keyOf = (text: string) => text.toLowerCase().replace(/[-\s]/g, '');
const plain = (word: string) => /^\p{L}{2,}$/u.test(word);

export function termVariants(paragraphs: string[]): Finding[] {
  const byKey = new Map<string, Map<string, Form>>();

  const note = (text: string, spot: Spot) => {
    const key = keyOf(text);
    if (key.length < 4) return;

    const forms = byKey.get(key) ?? new Map<string, Form>();
    const lower = text.toLowerCase();
    const form = forms.get(lower) ?? { form: lower, spots: [] };

    form.spots.push(spot);
    forms.set(lower, form);
    byKey.set(key, forms);
  };

  paragraphs.forEach((text, para) => {
    const words = wordsOf(text);

    words.forEach((w, i) => {
      if (/\p{L}/u.test(w.word) && !/^\p{N}/u.test(w.word) && !/['’]/.test(w.word)) note(w.word, { para, from: w.from, to: w.to, text: w.word });

      // Two words with one space between them: "data set".
      const next = words[i + 1];

      if (next && text.slice(w.to, next.from) === ' ' && plain(w.word) && plain(next.word) && !STOP.has(w.word.toLowerCase()) && !STOP.has(next.word.toLowerCase())) {
        const both = text.slice(w.from, next.to);
        note(both, { para, from: w.from, to: next.to, text: both });
      }
    });
  });

  const findings: Finding[] = [];

  for (const forms of byKey.values()) {
    if (forms.size < 2) continue;

    // An open pair ("data set") only counts if the closed or hyphenated form is there as well,
    // which it is, since there are two forms. But two open pairs cannot differ, so nothing more.
    const list = [...forms.values()].sort((a, b) => b.spots.length - a.spots.length || a.spots[0].para - b.spots[0].para || a.spots[0].from - b.spots[0].from);
    const main = list[0];
    const others = list.slice(1);
    const spots = others.flatMap((f) => f.spots).sort((a, b) => a.para - b.para || a.from - b.from);
    const edits: TextEdit[] = spots.map((s) => ({ ...s, insert: matchCase(s.text, main.form) }));
    const counts = list.map((f) => `“${f.form}” ${f.spots.length}×`).join(', ');

    findings.push({
      kind: 'terms',
      title: `${others.map((f) => f.form).join(', ')} → ${main.form}`,
      detail: `The same term is written in different ways (${counts}). Using one form throughout reads as more careful.`,
      spots,
      fix: edits,
    });
  }

  return findings.sort((a, b) => a.spots[0].para - b.spots[0].para || a.spots[0].from - b.spots[0].from);
}
