// Updating fields: the registry of field types the editor can calculate, and the engine that
// puts their new results into the document.
//
// ---- Adding a field type ------------------------------------------------------------------------
//
// A field type is a function from a field to its new result, registered under the field's name:
//
//   registerField('NUMWORDS', {
//     update: (field, env) => String(countWords(env.doc)),
//   });
//
// `update` gets the field (fields/model.ts: its instruction, where its result is) and an
// `UpdateEnv`: the document, the DocContext, every field and bookmark, the SEQ numbers, and
// `pageOf(pos)` for page numbers (null when no layout is at hand). It returns
//   - a string, put in place of the result with the formatting of the result's first character;
//   - `{ inline: nodes }`, inline nodes made by the updater (formatted text, nested fields);
//   - `{ blocks: paragraphs }`, for a field whose result is whole paragraphs (TOC, BIBLIOGRAPHY);
//   - null, to leave the result as it is (what every field the editor does not know gets).
// Options on the registration:
//   - `phase`: fields are updated phase by phase, so a later phase reads the results of an
//     earlier one. SEQ is 0; REF and PAGEREF are 1; TOC is 2. Default 1.
//   - `live`: also updated as the document is edited, when a change touches a field or bookmark.
//     Only for fields that are cheap and need no page layout. Default false.
//   - `onSave`: updated before the document is saved (and printed). Default true.
//   - `pages`: needs page numbers; the update measures the layout first. Default false.
//   - `prepare(fields, tr, env)`: runs before any result of the phase is worked out, to make
//     what the results will point at (TOC puts `_Toc` bookmarks on headings).
// Nothing else needs to change: F9, "Update all fields" and the update before saving find the
// new type by its name. `fields/builtin.ts` has SEQ, REF, PAGEREF and TOC as examples, and
// `fields/build.ts` the helpers for making field codes, bookmarks and paragraphs.

import { Fragment, type Mark, type Node as PMNode } from 'prosemirror-model';
import type { Transaction } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { WRAPPERS, schema } from '../editor/schema';
import { seqNumbers } from './seq';
import { type Field, type FieldScan, eventsIn, isHidden, scanFields, splitRawAfter, visibleText } from './model';

const N = schema.nodes;

export type FieldResult = string | { inline: PMNode[] } | { blocks: PMNode[] } | null;

export interface UpdateEnv {
  doc: PMNode;
  ctx: DocContext;
  scan: FieldScan;
  /** The page a position in `doc` is on; null without a layout. */
  pageOf: (pos: number) => number | null;
  /** SEQ numbers, worked out once per phase: the number each SEQ field shows, by its position. */
  seq: () => Map<number, number>;
  /** Shared between the updaters of one run, for anything worth working out once. */
  memo: Map<string, unknown>;
}

export interface FieldUpdater {
  update: (field: Field, env: UpdateEnv) => FieldResult;
  phase?: number;
  live?: boolean;
  onSave?: boolean;
  pages?: boolean;
  prepare?: (fields: Field[], tr: Transaction, env: UpdateEnv) => void;
}

const registry = new Map<string, FieldUpdater>();

/** Teaches the editor to calculate a field type. A second registration of a name replaces the first. */
export function registerField(type: string, updater: FieldUpdater): void {
  registry.set(type.toUpperCase(), updater);
}

export function fieldUpdater(type: string): FieldUpdater | undefined {
  return registry.get(type.toUpperCase());
}

/** Which fields an update takes. */
export interface UpdateScope {
  /** Only fields that overlap this range (of the document the update starts from). */
  range?: [number, number];
  /** Only field types registered as `live`, or with `onSave` not false. */
  only?: 'live' | 'save';
  /** Page numbers for positions in the document the update starts from. */
  pages?: ((pos: number) => number | null) | null;
  /** The step of the transaction whose document `pages` speaks of; by default, where the update starts. */
  pagesFrom?: number;
  /** Only fields of these types (CITATION, BIBLIOGRAPHY, ...). */
  types?: string[];
}

function wanted(field: Field, scope: UpdateScope): FieldUpdater | null {
  const updater = registry.get(field.type);
  if (!updater) return null;
  if (scope.only === 'live' && !updater.live) return null;
  if (scope.only === 'save' && updater.onSave === false) return null;
  if (scope.types && !scope.types.includes(field.type)) return null;

  return updater;
}

/** Whether a scope needs page numbers. */
export function scopeNeedsPages(doc: PMNode, scope: UpdateScope): boolean {
  return scanFields(doc).fields.some((field) => wanted(field, scope)?.pages && inRange(field, scope.range));
}

const inRange = (field: Field, range: [number, number] | undefined) => !range || (field.from <= range[1] && field.to >= range[0]);

/**
 * Updates fields into a transaction, phase by phase. Returns whether anything changed. Fields
 * inside another field that is being updated are left to it.
 */
export function updateFields(tr: Transaction, ctx: DocContext, scope: UpdateScope = {}): boolean {
  const startDoc = tr.doc;
  const startSteps = tr.steps.length;
  const phases = [...new Set([...registry.values()].map((u) => u.phase ?? 1))].sort((a, b) => a - b);
  const memo = new Map<string, unknown>();

  const env = (): UpdateEnv => {
    const doc = tr.doc;
    const back = tr.mapping.slice(scope.pagesFrom ?? startSteps).invert();
    let seq: Map<number, number> | null = null;

    return {
      doc,
      ctx,
      scan: scanFields(doc),
      pageOf: (pos) => (scope.pages ? scope.pages(back.map(pos)) : null),
      seq: () => (seq ??= seqNumbers(doc, ctx)),
      memo,
    };
  };

  const select = (phase: number): Field[] => {
    const forward = tr.mapping.slice(startSteps);
    const range = scope.range ? ([forward.map(scope.range[0], -1), forward.map(scope.range[1], 1)] as [number, number]) : undefined;
    const chosen = scanFields(tr.doc).fields.filter((field) => {
      const updater = wanted(field, scope);
      return updater && (updater.phase ?? 1) === phase && inRange(field, range);
    });
    const set = new Set(chosen);

    return chosen.filter((field) => {
      for (let p = field.parent; p; p = p.parent) if (set.has(p)) return false;
      return true;
    });
  };

  for (const phase of phases) {
    let fields = select(phase);
    if (!fields.length) continue;

    const byType = new Map<string, Field[]>();
    for (const field of fields) byType.set(field.type, [...(byType.get(field.type) ?? []), field]);

    const before = tr.steps.length;
    for (const [type, list] of byType) registry.get(type)?.prepare?.(list, tr, env());
    if (tr.steps.length !== before) fields = select(phase);

    const e = env();
    const results = fields.map((field) => ({ field, result: safeUpdate(field, e) }));

    // From the end backwards, so the positions of the fields still to come stay as they are.
    for (const { field, result } of results.reverse()) {
      if (result !== null) applyResult(tr, field, result);
    }
  }

  return tr.doc !== startDoc && !tr.doc.eq(startDoc);
}

function safeUpdate(field: Field, env: UpdateEnv): FieldResult {
  try {
    return registry.get(field.type)?.update(field, env) ?? null;
  } catch (error) {
    console.warn(`Field ${field.type} could not be updated`, error);
    return null;
  }
}

/** The marks new result text takes: those of the old result's first text, or the field code's. */
function resultMarks(doc: PMNode, field: Field): readonly Mark[] {
  let marks: readonly Mark[] | null = null;

  doc.nodesBetween(field.resultFrom, field.resultTo, (node) => {
    if (marks) return false;
    if (node.isText) marks = node.marks;
    return !node.isInline;
  });

  if (marks) return marks;
  if (field.simple) return [field.simple];

  return (field.separate?.node ?? field.begin?.node)?.marks ?? [];
}

/** Hidden nodes in an old result that are not field codes (bookmarks, comment anchors): they stay. */
function keptInResult(doc: PMNode, from: number, to: number): { before: PMNode[]; after: PMNode[] } {
  const before: PMNode[] = [];
  const after: PMNode[] = [];

  doc.nodesBetween(from, to, (node) => {
    if (!isHidden(node)) return !node.isInline;

    const events = eventsIn(node.attrs.raw);
    if (events.some((e) => e.kind === 'begin' || e.kind === 'separate' || e.kind === 'end' || e.kind === 'instr')) return false;

    (events.length && events.every((e) => e.kind === 'bmStart') ? before : after).push(node);
    return false;
  });

  return { before, after };
}

function applyResult(tr: Transaction, field: Field, result: Exclude<FieldResult, null>): void {
  const doc = tr.doc;

  if (typeof result === 'object' && 'blocks' in result) {
    applyBlocks(tr, field, result.blocks);
    return;
  }

  const marks = resultMarks(doc, field);
  const inline =
    typeof result === 'string'
      ? result
        ? [schema.text(result, marks)]
        : []
      : result.inline.map((node) => (field.simple && !field.simple.isInSet(node.marks) ? node.mark(field.simple.addToSet(node.marks)) : node));

  // A simple field with no result would lose the element that holds its instruction.
  if (field.simple && !inline.length) return;

  const oldContent = doc.slice(field.resultFrom, field.resultTo).content;
  const kept = keptInResult(doc, field.resultFrom, field.resultTo);
  const fresh = Fragment.from([...kept.before, ...inline, ...kept.after]);

  if (fresh.eq(oldContent)) return;

  // Separate and end in one hidden node: the node is split to make room for the result.
  if (field.separate && field.end && field.separate.pos === field.end.pos) {
    const node = field.separate.node;
    const parts = splitRawAfter(node.attrs.raw, field.separate.index);
    if (!parts || node.attrs.kind !== 'para') return;

    const a = node.type.create({ ...node.attrs, raw: parts[0] }, null, node.marks);
    const b = node.type.create({ ...node.attrs, raw: parts[1] }, null, node.marks);
    tr.replaceWith(field.separate.pos, field.separate.pos + node.nodeSize, [a, ...inline, b]);
    return;
  }

  if (!field.simple && !field.separate) return;

  tr.replaceWith(field.resultFrom, field.resultTo, fresh);
}

/** A result of whole paragraphs, from the paragraph the field starts in to the one it ends in. */
function applyBlocks(tr: Transaction, field: Field, blocks: PMNode[]): void {
  const doc = tr.doc;
  if (!field.separate || !field.end || field.separate.pos === field.end.pos) return;

  const $b = doc.resolve(field.resultFrom);
  const $e = doc.resolve(field.resultTo);
  if ($b.parent.type !== N.paragraph || $e.parent.type !== N.paragraph || $b.depth !== $e.depth) return;
  if ($b.depth > 1 && $b.before($b.depth - 1) !== $e.before($e.depth - 1)) return;

  const paraB = $b.parent;
  const paraE = $e.parent;
  const prefix = paraB.content.cut(0, $b.parentOffset);
  const suffix = paraE.content.cut($e.parentOffset);
  const list = blocks.length ? blocks : [N.paragraph.create(paraB.attrs)];
  const out: PMNode[] = [];

  list.forEach((block, i) => {
    let content = block.content;
    if (i === 0) content = prefix.append(content);
    out.push(block.type.create(block.attrs, content, block.marks));
  });

  const ownLine = paraE !== paraB && $e.parentOffset === 0;

  if (ownLine) {
    out.push(paraE.type.create(paraE.attrs, suffix));
  } else {
    const last = out[out.length - 1];
    out[out.length - 1] = last.type.create({ ...last.attrs, sectPr: paraE.attrs.sectPr }, last.content.append(suffix));
  }

  const from = $b.before();
  const to = $e.after();
  const old = doc.slice(from, to).content;
  const fresh = Fragment.from(out);

  if (!fresh.eq(old)) tr.replaceWith(from, to, fresh);
}

/** Whether a transaction added or removed a field code or a bookmark. */
export function touchesFields(tr: Transaction): boolean {
  if (!tr.docChanged) return false;

  const marked = (doc: PMNode, from: number, to: number) => {
    let found = false;

    doc.nodesBetween(Math.max(0, from), Math.min(doc.content.size, to), (node) => {
      if (found) return false;
      if ((node.type === N.opaque || node.type === N.opaque_block) && eventsIn(node.attrs.raw).length) found = true;
      if (node.marks.some((m) => m.type === schema.marks.wrap && String(m.attrs.open).startsWith('<w:fldSimple'))) found = true;
      return !found;
    });

    return found;
  };

  let doc = tr.before;

  for (let i = 0; i < tr.steps.length; i++) {
    const map = tr.mapping.maps[i];
    const next = tr.docs[i + 1] ?? tr.doc;
    let hit = false;

    map.forEach((oldStart, oldEnd, newStart, newEnd) => {
      if (!hit && (marked(doc, oldStart, oldEnd) || marked(next, newStart, newEnd))) hit = true;
    });

    if (hit) return true;
    doc = next;
  }

  return false;
}

/** The plain text of a field's current result. */
export const resultText = (doc: PMNode, field: Field): string => visibleText(doc, field.resultFrom, field.resultTo);

/** True for marks that stand for an element (a link), not formatting. */
export const isWrapper = (mark: Mark): boolean => WRAPPERS.has(mark.type.name);
