// British and American spelling: a word list, and a check for a document that mixes the two.
//
// The -ise/-ize words are a convention of their own: Oxford spelling is British with -ize, so a
// British text with "organize" is not mixed. They are counted apart from the other words.

import type { Finding, Spot, TextEdit } from './types';
import { matchCase, wordsOf } from './types';

export type Side = 'GB' | 'US';
export type Convention = 'spelling' | 'ize';

export interface Variant {
  side: Side;
  /** The British form; the same for both forms of a pair. */
  family: string;
  /** The other side's form. */
  other: string;
  convention: Convention;
}

