const TABLE = new Map<string, Variant>();

function add(gb: string, us: string, convention: Convention): void {
  TABLE.set(gb, { side: 'GB', family: gb, other: us, convention });
  TABLE.set(us, { side: 'US', family: gb, other: gb, convention });
}

function load(list: string, convention: Convention): void {
  for (const line of list.trim().split('\n')) {
    const [stems, suffixes] = line.split(':');
    const [gb, us] = stems.trim().split(/\s+/);

    for (const suffix of suffixes.split(',').map((s) => s.trim())) {
      const end = suffix === '-' ? '' : suffix;
      add(gb + end, us + end, convention);
    }
  }
}

load(OUR, 'spelling');
load(RE, 'spelling');
load(MISC, 'spelling');
load(YSE, 'spelling');
load(IZE, 'ize');

for (const line of LL.trim().split('\n')) {
  const [stem, suffixes] = line.split(':');

  for (const suffix of suffixes.split(',').map((s) => s.trim())) {
    add(stem.trim() + 'l' + suffix.slice(1), stem.trim() + suffix.slice(1), 'spelling');
  }
}

/** The word's place in the list, if it has one: which side, and its other form. */
export function spellingVariant(word: string): Variant | null {
  return TABLE.get(word.toLowerCase()) ?? null;
}

/** How many word forms the list knows, for the tests. */
export const spellingListSize = () => TABLE.size;

const SIDE_NAME: Record<Side, string> = { GB: 'British', US: 'American' };

/**
 * Where a document mixes British and American spelling: for each convention, the words of the
 * side used less, each with its other form as the fix. Nothing when one side is not clearly in
 * the minority (a tie leaves the choice to the writer, but is still reported, without a fix).
 */
export function mixedSpelling(paragraphs: string[]): Finding[] {
  const findings: Finding[] = [];

  for (const convention of ['spelling', 'ize'] as Convention[]) {
    const seen: { side: Side; word: string; variant: Variant; spot: Spot }[] = [];

    paragraphs.forEach((text, para) => {
      for (const w of wordsOf(text)) {
        const variant = spellingVariant(w.word);
        if (variant?.convention === convention) seen.push({ side: variant.side, word: w.word, variant, spot: { para, from: w.from, to: w.to, text: w.word } });
      }
    });

    const gb = seen.filter((s) => s.side === 'GB').length;
    const us = seen.length - gb;

    if (!gb || !us) continue;

    const minority: Side = gb < us ? 'GB' : 'US';
    const majority: Side = minority === 'GB' ? 'US' : 'GB';
    const tie = gb === us;
    const odd = seen.filter((s) => s.side === minority);

    // One finding per word family, so that the list says "colour (2×)" rather than repeating it.
    const families = new Map<string, typeof odd>();
    for (const s of odd) families.set(s.variant.family, [...(families.get(s.variant.family) ?? []), s]);

    for (const group of families.values()) {
      const first = group[0];
      const edits: TextEdit[] = group.map((s) => ({ ...s.spot, insert: matchCase(s.word, s.variant.other) }));
      const what = convention === 'ize' ? (minority === 'GB' ? '-ise' : '-ize') : SIDE_NAME[minority];

      findings.push({
        kind: 'spelling',
        title: `${first.word} → ${first.variant.other}`,
        detail: tie
          ? `The document uses British and American spelling equally often (${gb} each). Pick one.`
          : convention === 'ize'
            ? `${what} spelling; the rest of the document uses ${majority === 'GB' ? '-ise' : '-ize'} (${Math.max(gb, us)} to ${Math.min(gb, us)}).`
            : `${what} spelling; the rest of the document is ${SIDE_NAME[majority]} (${Math.max(gb, us)} to ${Math.min(gb, us)}).`,
        spots: group.map((s) => s.spot),
        fix: tie ? undefined : edits,
        group: convention === 'ize' ? 'ize' : `spelling-${minority}`,
      });
    }
  }

  return findings;
}
