// Review: a panel at the workspace's right edge with the document's comments beside the text they
// are about, or comments and tracked changes together in a list with filters; and the controls for
// tracking changes, in the panel and in the status bar.

import { TextSelection } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import { desktop } from '../desktop';
import type { DocContext } from '../docx/import';
import { authorName, authorSetting, setAuthorName, setSystemAuthor } from '../review/author';
import { type Comment, type Placed, addComment, commentsOf, deleteComment, editComment, placedComments, replyTo, setResolved } from '../review/comments';
import { commentAt, reviewKey } from '../review/plugin';
import { type Change, changesAtSelection, changesIn, isTracking, resolveChanges, selectChange, setTracking } from '../review/track';
import { h, keepFocus, toast } from './dom';
import { icon } from './icons';

export interface ReviewHost {
  tab(): { view: EditorView; ctx: DocContext; desk: HTMLElement; partsChanged: boolean } | null;
  /** The panel was opened or closed: the page makes room for it, or takes the room back. */
  layout(): void;
}

type Filter = 'all' | 'comments' | 'ins' | 'del';

function when(date: string): string {
  const d = new Date(date);
  return date && !Number.isNaN(d.getTime()) ? d.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' }) : '';
}

const kindLabel = (kind: Change['kind']): string => {
  if (kind === 'ins') return 'Inserted';
  if (kind === 'del') return 'Deleted';
  if (kind === 'moveFrom') return 'Moved away';
  return 'Moved here';
};

export class ReviewPanel {
  readonly el = h('aside', { class: 'review', hidden: true });
  readonly trackButton = h('button', { class: 'status-button track-button', title: 'Track changes (Ctrl+Shift+E)', onclick: () => this.toggleTracking() }, 'Track changes');
  readonly paneButton = h('button', { class: 'status-button', title: 'Comments and changes', onclick: () => this.toggle() }, 'Review');

  private mode: 'margin' | 'list' = 'margin';
  private filter: Filter = 'all';
  private authorFilter = '';
  private showResolved = true;
  /** A comment being written: new (on the selection), a reply to a comment, or an edit of one. */
  private draft: { kind: 'new' | 'reply' | 'edit'; id: string | null } | null = null;
  private shown = '';
  private desk: HTMLElement | null = null;

  private readonly nameField = h('input', { class: 'field review-name', type: 'text', spellcheck: 'false', title: 'The name your comments and changes carry' });
  private readonly trackBox = h('input', { type: 'checkbox' });
  private readonly marginTab = h('button', { class: 'review-tab', onclick: () => this.setMode('margin') }, 'Beside the text');
  private readonly listTab = h('button', { class: 'review-tab', onclick: () => this.setMode('list') }, 'List');
  private readonly typeSelect = h('select', { class: 'tool-select', title: 'Show' });
  private readonly authorSelect = h('select', { class: 'tool-select', title: 'By' });
  private readonly resolvedBox = h('input', { type: 'checkbox' });
  private readonly filters = h('div', { class: 'review-filters' });
  private readonly margin = h('div', { class: 'review-margin' });
  private readonly marginInner = h('div', { class: 'review-margin-inner' });
  private readonly list = h('div', { class: 'review-list' });
  private readonly onDeskScroll = () => {
    if (this.desk) this.margin.scrollTop = this.desk.scrollTop;
  };

  constructor(private readonly host: ReviewHost) {
    keepFocus(this.el);
    void desktop.userName?.().then((name) => {
      setSystemAuthor(name);
      this.nameField.placeholder = authorName();
    });

    this.nameField.value = authorSetting();
    this.nameField.placeholder = authorName();
    this.nameField.addEventListener('change', () => setAuthorName(this.nameField.value));
    this.trackBox.addEventListener('change', () => this.toggleTracking(this.trackBox.checked));

    for (const [value, label] of [
      ['all', 'Comments and changes'],
      ['comments', 'Comments'],
      ['ins', 'Insertions'],
      ['del', 'Deletions'],
    ] as const) {
      this.typeSelect.append(h('option', { value }, label));
    }

    this.typeSelect.addEventListener('change', () => {
      this.filter = this.typeSelect.value as Filter;
      this.refresh(true);
    });
    this.authorSelect.addEventListener('change', () => {
      this.authorFilter = this.authorSelect.value;
      this.refresh(true);
    });
    this.resolvedBox.checked = true;
    this.resolvedBox.addEventListener('change', () => {
      this.showResolved = this.resolvedBox.checked;
      this.refresh(true);
    });

    this.filters.append(this.typeSelect, this.authorSelect, h('label', { class: 'review-check' }, this.resolvedBox, 'Resolved comments'));
    this.margin.append(this.marginInner);
    // The margin follows the page; the wheel over it scrolls the page.
    this.margin.addEventListener('wheel', (event) => {
      if (this.desk) this.desk.scrollTop += event.deltaY;
    });

    const button = (label: string, title: string, run: () => void) => h('button', { class: 'button small', title, onclick: run }, label);

    this.el.append(
      h(
        'div',
        { class: 'assist-head' },
        h('span', { class: 'assist-title' }, 'Review'),
        h('button', { class: 'tool', title: 'Close', html: icon('close'), onclick: () => this.close() }),
      ),
      h(
        'div',
        { class: 'review-section' },
        h('label', { class: 'review-check' }, this.trackBox, 'Track changes'),
        h('label', { class: 'review-row' }, h('span', { class: 'menu-label' }, 'Your name'), this.nameField),
        h(
          'div',
          { class: 'review-buttons' },
          button('Previous', 'Previous change', () => this.step(false)),
          button('Next', 'Next change', () => this.step(true)),
          button('Accept', 'Accept the change at the cursor, or every change in the selection', () => this.resolve(true, false)),
          button('Reject', 'Reject the change at the cursor, or every change in the selection', () => this.resolve(false, false)),
          button('Accept all', 'Accept every change in the document', () => this.resolve(true, true)),
          button('Reject all', 'Reject every change in the document', () => this.resolve(false, true)),
        ),
        h('div', { class: 'review-buttons' }, h('button', { class: 'button primary small', title: 'New comment on the selection (Ctrl+Alt+M)', onclick: () => this.newComment() }, 'New comment')),
      ),
      h('div', { class: 'review-tabs' }, this.marginTab, this.listTab),
      this.filters,
      this.margin,
      this.list,
    );

    this.setMode('margin');
  }

  get isOpen(): boolean {
    return !this.el.hidden;
  }

  open(): void {
    this.el.hidden = false;
    this.host.layout();
    this.refresh(true);
  }

  close(): void {
    this.el.hidden = true;
    this.draft = null;
    this.host.layout();
  }

  toggle(): void {
    if (this.isOpen) this.close();
    else this.open();
  }

  // ---- Actions ------------------------------------------------------------------------------------

  toggleTracking(on?: boolean): void {
    const tab = this.host.tab();
    if (!tab) return;

    const next = on ?? !isTracking(tab.view.state);
    tab.view.dispatch(setTracking(tab.view.state, next));
    toast(next ? 'Track changes is on' : 'Track changes is off');
    this.refresh();
  }

  /** Opens a comment to write on the selection. */
  newComment(): void {
    if (!this.host.tab()) return;

    this.draft = { kind: 'new', id: null };
    this.setMode('margin');
    if (!this.isOpen) this.open();
    this.refresh(true);
  }

  private step(forward: boolean): void {
    const tab = this.host.tab();
    if (!tab) return;

    const tr = selectChange(tab.view.state, forward);
    if (tr) tab.view.dispatch(tr);
    else toast('There are no tracked changes');
    tab.view.focus();
  }

  private resolve(accept: boolean, all: boolean): void {
    const tab = this.host.tab();
    if (!tab) return;

    const state = tab.view.state;
    const changes = all ? changesIn(state.doc) : changesAtSelection(state);

    if (!changes.length) {
      toast(all ? 'There are no tracked changes' : 'There is no tracked change here');
      return;
    }

    tab.view.dispatch(resolveChanges(state, changes, accept));
    if (!all) {
      const next = selectChange(tab.view.state, true);
      if (next && changesIn(tab.view.state.doc).length) tab.view.dispatch(next);
    }
    tab.view.focus();
  }

  private resolveOne(change: Change, accept: boolean): void {
    const tab = this.host.tab();
    if (!tab) return;
    tab.view.dispatch(resolveChanges(tab.view.state, [change], accept));
  }

  /** Something about the comments changed that the text does not show: the document has unsaved changes. */
  private commentsEdited(): void {
    const tab = this.host.tab();
    if (!tab) return;

    tab.partsChanged = true;
    tab.view.dispatch(tab.view.state.tr.setMeta('review', 'comments').setMeta('addToHistory', false));
  }

  private save(text: string): void {
    const tab = this.host.tab();
    const draft = this.draft;
    if (!tab || !draft) return;

    const store = commentsOf(tab.ctx);
    const view = tab.view;
    this.draft = null;

    if (draft.kind === 'edit' && draft.id) {
      editComment(store, draft.id, text);
      this.commentsEdited();
    } else if (!text.trim()) {
      this.refresh(true);
      return;
    } else if (draft.kind === 'reply' && draft.id) {
      const tr = replyTo(view.state, store, draft.id, text);
      if (tr) view.dispatch(tr);
    } else {
      const { tr, id } = addComment(view.state, store, text);
      view.dispatch(tr.setMeta(reviewKey, { active: id }));
    }

    this.refresh(true);
  }

  private remove(id: string): void {
    const tab = this.host.tab();
    if (!tab) return;
    tab.view.dispatch(deleteComment(tab.view.state, commentsOf(tab.ctx), id));
    tab.partsChanged = true;
  }

  private resolveComment(id: string, done: boolean): void {
    const tab = this.host.tab();
    if (!tab) return;
    setResolved(commentsOf(tab.ctx), id, done);
    this.commentsEdited();
  }

  private goTo(from: number, to: number, id: string | null): void {
    const tab = this.host.tab();
    if (!tab || from < 0) return;

    const { view } = tab;
    const tr = view.state.tr.setSelection(TextSelection.create(view.state.doc, from, to)).scrollIntoView();
    view.dispatch(id ? tr.setMeta(reviewKey, { active: id }) : tr);
  }

  // ---- Showing ------------------------------------------------------------------------------------

  private setMode(mode: 'margin' | 'list'): void {
    this.mode = mode;
    this.marginTab.classList.toggle('on', mode === 'margin');
    this.listTab.classList.toggle('on', mode === 'list');
    this.margin.hidden = mode !== 'margin';
    this.list.hidden = mode !== 'list';
    this.filters.hidden = mode !== 'list';
    this.refresh(true);
  }

  /** Brings the panel and the status bar up to date with the active document. */
  refresh(force = false): void {
    const tab = this.host.tab();
    const tracking = tab ? isTracking(tab.view.state) : false;

    this.trackButton.classList.toggle('on', tracking);
    this.trackButton.textContent = tracking ? 'Tracking changes' : 'Track changes';
    this.trackBox.checked = tracking;

    if (!this.isOpen) return;

    if (this.desk !== (tab?.desk ?? null)) {
      this.desk?.removeEventListener('scroll', this.onDeskScroll);
      this.desk = tab?.desk ?? null;
      this.desk?.addEventListener('scroll', this.onDeskScroll, { passive: true });
    }

    if (!tab) {
      this.marginInner.replaceChildren();
      this.list.replaceChildren();
      this.shown = '';
      return;
    }

    const state = tab.view.state;
    const store = commentsOf(tab.ctx);
    const review = reviewKey.getState(state);
    const anchors = review?.anchors ?? new Map();
    const placed = placedComments(store, anchors);
    const ids = placed.map((p) => p.comment.id).join(',');
    const key = `${tab.ctx.key}|${this.mode}|${store.version}|${ids}|${this.draft?.kind}:${this.draft?.id}|${this.mode === 'list' ? `${this.filter}|${this.authorFilter}|${this.showResolved}|${changesIn(state.doc).length}` : ''}`;

    // While a comment is being written, the cards stay as they are.
    const typing = this.el.contains(document.activeElement) && document.activeElement?.tagName === 'TEXTAREA';

    if (force || (key !== this.shown && !typing) || (this.mode === 'list' && !typing)) {
      this.shown = key;
      if (this.mode === 'margin') this.buildMargin(placed, tab.ctx);
      else this.buildList(placed, tab.ctx, state.doc);
    }

    const active = review?.active ?? commentAt(state, store, state.selection.from);
    for (const card of this.el.querySelectorAll<HTMLElement>('.review-card[data-id]')) card.classList.toggle('active', card.dataset.id === active);

    if (this.mode === 'margin') requestAnimationFrame(() => this.place());
  }

  private commentCard(comment: Comment, ctx: DocContext, placed: Placed | null): HTMLElement {
    const store = commentsOf(ctx);
    const card = h('div', { class: `review-card comment${comment.done ? ' resolved' : ''}`, 'data-id': comment.id });
    if (placed) card.dataset.from = String(placed.from);

    const entry = (c: Comment, reply: boolean) => {
      const editing = this.draft?.kind === 'edit' && this.draft.id === c.id;
      return h(
        'div',
        { class: reply ? 'review-entry reply' : 'review-entry' },
        h('div', { class: 'review-meta' }, h('span', { class: 'review-author' }, c.author || 'Unknown'), h('span', { class: 'review-date' }, when(c.date))),
        editing ? this.editor(c.text) : h('div', { class: 'review-text' }, c.text),
        !editing &&
          h(
            'div',
            { class: 'review-actions' },
            h('button', { class: 'link-button', onclick: () => this.startDraft('edit', c.id) }, 'Edit'),
            h('button', { class: 'link-button', onclick: () => this.remove(c.id) }, 'Delete'),
          ),
      );
    };

    card.append(entry(comment, false));
    for (const reply of store.replies(comment.id)) card.append(entry(reply, true));

    if (this.draft?.kind === 'reply' && this.draft.id === comment.id) {
      card.append(this.editor(''));
    } else {
      card.append(
        h(
          'div',
          { class: 'review-actions' },
          h('button', { class: 'link-button', onclick: () => this.startDraft('reply', comment.id) }, 'Reply'),
          h('button', { class: 'link-button', onclick: () => this.resolveComment(comment.id, !comment.done) }, comment.done ? 'Reopen' : 'Resolve'),
        ),
      );
    }

    card.addEventListener('mousedown', (event) => {
      if ((event.target as HTMLElement).closest('button, textarea')) return;
      if (placed) this.goTo(placed.from, placed.to, comment.id);
    });

    return card;
  }

  private startDraft(kind: 'reply' | 'edit', id: string): void {
    this.draft = { kind, id };
    this.refresh(true);
  }

  private editor(text: string): HTMLElement {
    const field = h('textarea', { class: 'field review-field', rows: '3', spellcheck: 'true', placeholder: 'Write a comment' });
    field.value = text;

    const done = () => this.save(field.value);
    const cancel = () => {
      this.draft = null;
      this.refresh(true);
      this.host.tab()?.view.focus();
    };

    field.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' && (event.ctrlKey || event.metaKey)) {
        event.preventDefault();
        done();
      } else if (event.key === 'Escape') {
        event.preventDefault();
        cancel();
      }
    });

    requestAnimationFrame(() => field.focus());

    return h(
      'div',
      { class: 'review-draft' },
      field,
      h('div', { class: 'review-buttons' }, h('button', { class: 'button primary small', onclick: done }, 'Save'), h('button', { class: 'button small', onclick: cancel }, 'Cancel')),
    );
  }

  private buildMargin(placed: Placed[], ctx: DocContext): void {
    const cards: HTMLElement[] = placed.map((p) => this.commentCard(p.comment, ctx, p));

    if (this.draft?.kind === 'new') {
      const tab = this.host.tab();
      const card = h('div', { class: 'review-card comment draft' }, h('div', { class: 'review-meta' }, h('span', { class: 'review-author' }, authorName())), this.editor(''));
      card.dataset.from = String(tab?.view.state.selection.from ?? 0);
      cards.push(card);
    }

    if (!cards.length) cards.push(h('div', { class: 'review-empty' }, 'No comments. Select some text and choose New comment.'));
    this.marginInner.replaceChildren(...cards);
  }

  /** Puts each card level with its text, pushed down where it would overlap the one above. */
  private place(): void {
    const tab = this.host.tab();
    if (!tab || this.mode !== 'margin' || !this.isOpen) return;

    const { view, desk } = tab;
    const deskTop = desk.getBoundingClientRect().top;
    const offset = deskTop - this.margin.getBoundingClientRect().top;
    const size = view.state.doc.content.size;
    let bottom = 0;

    const cards = [...this.marginInner.children] as HTMLElement[];
    const tops = cards.map((card) => {
      const from = Number(card.dataset.from ?? -1);
      if (from < 0) return Number.POSITIVE_INFINITY;
      try {
        return view.coordsAtPos(Math.min(from, size)).top - deskTop + desk.scrollTop + offset;
      } catch {
        return Number.POSITIVE_INFINITY;
      }
    });

    cards.forEach((card, i) => {
      const top = Math.max(bottom, Number.isFinite(tops[i]) ? tops[i] : bottom);
      card.style.top = `${top}px`;
      bottom = top + card.offsetHeight + 8;
    });

    this.marginInner.style.height = `${Math.max(desk.scrollHeight + offset, bottom + 40)}px`;
    this.margin.scrollTop = desk.scrollTop;
  }

  private buildList(placed: Placed[], ctx: DocContext, doc: EditorView['state']['doc']): void {
    const changes = changesIn(doc);
    const authors = new Set<string>([...placed.map((p) => p.comment.author), ...changes.map((c) => c.author)]);

    this.authorSelect.replaceChildren(h('option', { value: '' }, 'Everyone'), ...[...authors].sort().map((a) => h('option', { value: a }, a || 'Unknown')));
    this.authorSelect.value = authors.has(this.authorFilter) ? this.authorFilter : '';
    this.typeSelect.value = this.filter;

    const byAuthor = (author: string) => !this.authorFilter || author === this.authorFilter;
    const items: { from: number; el: HTMLElement }[] = [];

    if (this.filter === 'all' || this.filter === 'comments') {
      for (const p of placed) {
        if (!byAuthor(p.comment.author) || (p.comment.done && !this.showResolved)) continue;
        items.push({ from: p.from, el: this.commentCard(p.comment, ctx, p) });
      }
    }

    if (this.filter !== 'comments') {
      for (const change of changes) {
        const removes = change.kind === 'del' || change.kind === 'moveFrom';
        if ((this.filter === 'ins' && removes) || (this.filter === 'del' && !removes) || !byAuthor(change.author)) continue;

        const text = change.text.length > 120 ? `${change.text.slice(0, 120)}…` : change.text;
        const card = h(
          'div',
          { class: `review-card change ${removes ? 'removed' : 'added'}` },
          h('div', { class: 'review-meta' }, h('span', { class: 'review-author' }, change.author || 'Unknown'), h('span', { class: 'review-date' }, when(change.date))),
          h('div', { class: 'review-text' }, h('span', { class: 'review-kind' }, kindLabel(change.kind)), ' ', h(removes ? 'del' : 'ins', null, text)),
          h(
            'div',
            { class: 'review-actions' },
            h('button', { class: 'link-button', onclick: () => this.resolveOne(change, true) }, 'Accept'),
            h('button', { class: 'link-button', onclick: () => this.resolveOne(change, false) }, 'Reject'),
          ),
        );
        card.addEventListener('mousedown', (event) => {
          if (!(event.target as HTMLElement).closest('button')) this.goTo(change.from, change.to, null);
        });
        items.push({ from: change.from, el: card });
      }
    }

    items.sort((a, b) => a.from - b.from);
    this.list.replaceChildren(...(items.length ? items.map((i) => i.el) : [h('div', { class: 'review-empty' }, 'Nothing to show.')]));
  }
}
