// Word's formatting properties, read into CSS declarations for the screen.
//
// The same reading serves the stylesheet built from styles.xml and the inline styles on
// paragraphs, cells and runs. Colours are not written as plain CSS colours: they go into custom
// properties (--c text, --h fill, --bc border) that page.css turns into what is shown, so a dark
// page can re-map every colour in a document without the document changing.

import { type XmlEl, child } from './xml';

export type Decls = Record<string, string>;

export interface Theme {
  major: string;
  minor: string;
}

export const DEFAULT_THEME: Theme = { major: 'Calibri Light', minor: 'Calibri' };

/** The order the schema wants a paragraph's properties in. */
export const PPR_ORDER = [
  'w:pStyle', 'w:keepNext', 'w:keepLines', 'w:pageBreakBefore', 'w:framePr', 'w:widowControl', 'w:numPr',
  'w:suppressLineNumbers', 'w:pBdr', 'w:shd', 'w:tabs', 'w:suppressAutoHyphens', 'w:kinsoku', 'w:wordWrap',
  'w:overflowPunct', 'w:topLinePunct', 'w:autoSpaceDE', 'w:autoSpaceDN', 'w:bidi', 'w:adjustRightInd',
  'w:snapToGrid', 'w:spacing', 'w:ind', 'w:contextualSpacing', 'w:mirrorIndents', 'w:suppressOverlap', 'w:jc',
  'w:textDirection', 'w:textAlignment', 'w:textboxTightWrap', 'w:outlineLvl', 'w:divId', 'w:cnfStyle',
] as const;
export const PPR_LAST = ['w:rPr', 'w:sectPr', 'w:pPrChange'] as const;

export const RPR_ORDER = [
  'w:rStyle', 'w:rFonts', 'w:b', 'w:bCs', 'w:i', 'w:iCs', 'w:caps', 'w:smallCaps', 'w:strike', 'w:dstrike',
  'w:outline', 'w:shadow', 'w:emboss', 'w:imprint', 'w:noProof', 'w:snapToGrid', 'w:vanish', 'w:webHidden',
  'w:color', 'w:spacing', 'w:w', 'w:kern', 'w:position', 'w:sz', 'w:szCs', 'w:highlight', 'w:u', 'w:effect',
  'w:bdr', 'w:shd', 'w:fitText', 'w:vertAlign', 'w:rtl', 'w:cs', 'w:em', 'w:lang', 'w:eastAsianLayout',
  'w:specVanish', 'w:oMath',
] as const;
export const RPR_LAST = ['w:rPrChange'] as const;

export const TCPR_ORDER = [
  'w:cnfStyle', 'w:tcW', 'w:gridSpan', 'w:hMerge', 'w:vMerge', 'w:tcBorders', 'w:shd', 'w:noWrap', 'w:tcMar',
  'w:textDirection', 'w:tcFitText', 'w:vAlign', 'w:hideMark', 'w:headers', 'w:cellIns', 'w:cellDel', 'w:cellMerge',
] as const;
export const TCPR_LAST = ['w:tcPrChange'] as const;

/** Word's sixteen highlighter colours, by the names the file uses. */
export const HIGHLIGHTS: Record<string, string> = {
  yellow: '#FFFF00', green: '#00FF00', cyan: '#00FFFF', magenta: '#FF00FF', blue: '#0000FF', red: '#FF0000',
  darkBlue: '#000080', darkCyan: '#008080', darkGreen: '#008000', darkMagenta: '#800080', darkRed: '#800000',
  darkYellow: '#808000', darkGray: '#808080', lightGray: '#C0C0C0', black: '#000000', white: '#FFFFFF',
};

export function highlightName(hex: string): string | null {
  const wanted = hex.toUpperCase();

  for (const [name, value] of Object.entries(HIGHLIGHTS)) {
    if (value === wanted) return name;
  }

  return null;
}

/** A property that is on by being there: <w:b/> is bold, <w:b w:val="0"/> is explicitly not. */
export function isOn(el: XmlEl | null | undefined): boolean {
  if (!el) return false;
  const v = el.attrs['w:val'];
  return v === undefined || !(v === '0' || v === 'false' || v === 'off');
}

/** "2F5496" → "#2F5496"; "auto" and anything unreadable → null. */
export function hex(value: string | undefined | null): string | null {
  return value && /^[0-9a-fA-F]{6}$/.test(value) ? `#${value.toUpperCase()}` : null;
}

const num = (value: string | undefined): number | null => {
  if (value === undefined) return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
};

const round = (n: number, digits = 2) => {
  const f = 10 ** digits;
  return Math.round(n * f) / f;
};

export const twipsToPt = (twips: number) => round(twips / 20);
export const twipsToPx = (twips: number) => twips / 15;
export const pxToTwips = (px: number) => Math.round(px * 15);
export const emuToPx = (emu: number) => emu / 9525;
export const pxToEmu = (px: number) => Math.round(px * 9525);

const SERIF = /times|cambria|georgia|garamond|palatino|book antiqua|bookman|century|constantia|minion|baskerville|didot|serif/i;
const MONO = /courier|consolas|lucida console|monaco|menlo|mono|cascadia/i;

export function fontFamilyCss(name: string): string {
  const generic = /sans/i.test(name) ? 'sans-serif' : MONO.test(name) ? 'monospace' : SERIF.test(name) ? 'serif' : 'sans-serif';
  return `"${name.replace(/["\\]/g, '')}", ${generic}`;
}

/** The Latin font a `w:rFonts` names, with theme fonts looked up. Null if it names none. */
export function fontOf(rFonts: XmlEl | null | undefined, theme: Theme): string | null {
  if (!rFonts) return null;

  const themed = rFonts.attrs['w:asciiTheme'] ?? rFonts.attrs['w:hAnsiTheme'];

  if (themed) {
    return themed.startsWith('major') ? theme.major : theme.minor;
  }

  return rFonts.attrs['w:ascii'] ?? rFonts.attrs['w:hAnsi'] ?? null;
}

export function parseTheme(root: XmlEl | null): Theme {
  const scheme = child(child(root, 'a:themeElements'), 'a:fontScheme');
  const major = child(child(scheme, 'a:majorFont'), 'a:latin')?.attrs.typeface;
  const minor = child(child(scheme, 'a:minorFont'), 'a:latin')?.attrs.typeface;

  return { major: major || DEFAULT_THEME.major, minor: minor || DEFAULT_THEME.minor };
}

/** How bright a colour looks, 0 (black) to 1 (white). */
export function luminance(hexColor: string): number {
  const n = parseInt(hexColor.slice(1), 16);
  const channel = (v: number) => {
    const s = v / 255;
    return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
  };

  return 0.2126 * channel((n >> 16) & 255) + 0.7152 * channel((n >> 8) & 255) + 0.0722 * channel(n & 255);
}

/**
 * Word's "single" line spacing is the font's own line height, about 1.2 times its size, where
 * CSS counts from the size itself. One factor for every font is a few percent off for some.
 */
const LINE = 1.18;

const ALIGN: Record<string, string> = {
  left: 'left', start: 'left', center: 'center', right: 'right', end: 'right',
  both: 'justify', distribute: 'justify',
};

/** `w:jc` as CSS text-align. */
export const alignCss = (value: string): string => ALIGN[value] ?? 'left';

const UNDERLINE_STYLE: Record<string, string> = {
  double: 'double', dotted: 'dotted', dottedHeavy: 'dotted', dash: 'dashed', dashedHeavy: 'dashed',
  dashLong: 'dashed', dashLongHeavy: 'dashed', dotDash: 'dashed', dashDotHeavy: 'dashed', dotDotDash: 'dashed',
  dashDotDotHeavy: 'dashed', wave: 'wavy', wavyHeavy: 'wavy', wavyDouble: 'wavy',
};

export function underlineDecls(kind: string, d: Decls = {}): Decls {
  if (kind === 'none') {
    d['text-decoration-line'] = 'none';
    return d;
  }

  d['text-decoration-line'] = 'underline';
  if (UNDERLINE_STYLE[kind]) d['text-decoration-style'] = UNDERLINE_STYLE[kind];
  if (kind === 'thick' || kind.endsWith('Heavy')) d['text-decoration-thickness'] = '2px';
  return d;
}

/** Character formatting (`w:rPr`) as CSS. */
export function runDecls(rPr: XmlEl | null | undefined, theme: Theme): Decls {
  const d: Decls = {};
  if (!rPr) return d;

  let strike: boolean | null = null;
  let underline: string | null = null;

  for (const c of rPr.children) {
    const a = c.attrs;

    switch (c.name) {
      case 'w:rFonts': {
        const font = fontOf(c, theme);
        if (font) d['font-family'] = fontFamilyCss(font);
        break;
      }
      case 'w:sz': {
        const size = num(a['w:val']);
        if (size) d['font-size'] = `${size / 2}pt`;
        break;
      }
      case 'w:b':
        d['font-weight'] = isOn(c) ? 'bold' : 'normal';
        break;
      case 'w:i':
        d['font-style'] = isOn(c) ? 'italic' : 'normal';
        break;
      case 'w:caps':
        d['text-transform'] = isOn(c) ? 'uppercase' : 'none';
        break;
      case 'w:smallCaps':
        d['font-variant-caps'] = isOn(c) ? 'small-caps' : 'normal';
        break;
      case 'w:strike':
      case 'w:dstrike':
        strike = isOn(c);
        break;
      case 'w:u':
        underline = a['w:val'] ?? 'single';
        break;
      case 'w:color': {
        const color = hex(a['w:val']);
        if (color) d['--c'] = color;
        else if (a['w:val'] === 'auto') d.color = 'var(--page-ink)';
        break;
      }
      case 'w:highlight': {
        const color = HIGHLIGHTS[a['w:val'] ?? ''];
        if (color) d['--h'] = color;
        break;
      }
      case 'w:shd': {
        const fill = hex(a['w:fill']);
        if (fill && !d['--h']) d['--h'] = fill;
        break;
      }
      case 'w:spacing': {
        const spacing = num(a['w:val']);
        if (spacing) d['letter-spacing'] = `${twipsToPt(spacing)}pt`;
        break;
      }
      case 'w:vertAlign':
        if (a['w:val'] === 'superscript' || a['w:val'] === 'subscript') {
          d['vertical-align'] = a['w:val'] === 'superscript' ? 'super' : 'sub';
          d['font-size'] = '0.75em';
        }
        break;
      case 'w:vanish':
        // Hidden text: shown, dimmed, so that nothing in the file is out of reach.
        if (isOn(c)) d.opacity = '0.45';
        break;
    }
  }

  if (underline !== null) underlineDecls(underline, d);

  if (strike !== null) {
    const lines = [d['text-decoration-line'] === 'underline' ? 'underline' : '', strike ? 'line-through' : ''].filter(Boolean);
    if (strike || underline === null) d['text-decoration-line'] = lines.join(' ') || 'none';
  }

  return d;
}

const BORDER_STYLE: Record<string, string> = {
  single: 'solid', thick: 'solid', double: 'double', dotted: 'dotted', dashed: 'dashed', dashSmallGap: 'dashed',
  dotDash: 'dashed', dotDotDash: 'dashed', triple: 'double', wave: 'solid', doubleWave: 'double',
};

/** One side of a border as CSS, or null where the file says there is none. */
function borderSide(el: XmlEl): { css: string; color: string | null } | null {
  const kind = el.attrs['w:val'];
  if (!kind || kind === 'nil' || kind === 'none') return null;

  // Widths are in eighths of a point.
  const px = Math.max(1, Math.round(((num(el.attrs['w:sz']) ?? 4) / 8) * (96 / 72)));
  const style = BORDER_STYLE[kind] ?? 'solid';

  return { css: `${style === 'double' ? Math.max(3, px) : px}px ${style}`, color: hex(el.attrs['w:color']) };
}

const SIDES: Record<string, string> = {
  'w:top': 'top', 'w:bottom': 'bottom', 'w:left': 'left', 'w:start': 'left', 'w:right': 'right', 'w:end': 'right',
};

/** `w:pBdr` or `w:tcBorders` as CSS. Sides the file switches off are written as none. */
function borderDecls(borders: XmlEl, d: Decls): void {
  for (const c of borders.children) {
    const side = SIDES[c.name];
    if (!side) continue;

    const border = borderSide(c);

    if (!border) {
      d[`border-${side}`] = 'none';
      continue;
    }

    d[`border-${side}`] = border.css;
    if (border.color && !d['--bc']) d['--bc'] = border.color;
  }
}

function shadeDecls(shd: XmlEl, d: Decls): void {
  const fill = hex(shd.attrs['w:fill']);
  if (!fill) return;

  d['--h'] = fill;
  // Text with no colour of its own turns white on a dark fill, as it does in Word.
  if (luminance(fill) < 0.2) d['--od'] = '1';
}

/** Paragraph formatting (`w:pPr`) as CSS. */
export function paraDecls(pPr: XmlEl | null | undefined): Decls {
  const d: Decls = {};
  if (!pPr) return d;

  for (const c of pPr.children) {
    const a = c.attrs;

    switch (c.name) {
      case 'w:jc':
        d['text-align'] = ALIGN[a['w:val'] ?? ''] ?? 'left';
        break;
      case 'w:spacing': {
        const before = num(a['w:before']);
        const after = num(a['w:after']);
        const line = num(a['w:line']);
        const rule = a['w:lineRule'];

        if (a['w:beforeAutospacing'] === '1' || a['w:beforeAutospacing'] === 'true') d['margin-top'] = '1em';
        else if (before !== null) d['margin-top'] = `${twipsToPt(before)}pt`;

        if (a['w:afterAutospacing'] === '1' || a['w:afterAutospacing'] === 'true') d['margin-bottom'] = '1em';
        else if (after !== null) d['margin-bottom'] = `${twipsToPt(after)}pt`;

        if (line !== null) {
          if (!rule || rule === 'auto') d['line-height'] = String(round((line / 240) * LINE, 3));
          else if (rule === 'exact') d['line-height'] = `${twipsToPt(line)}pt`;
          else d['line-height'] = 'normal';
        }
        break;
      }
      case 'w:ind': {
        const left = num(a['w:left'] ?? a['w:start']);
        const right = num(a['w:right'] ?? a['w:end']);
        const hanging = num(a['w:hanging']);
        const firstLine = num(a['w:firstLine']);

        if (left !== null) d['margin-left'] = `${twipsToPt(left)}pt`;
        if (right !== null) d['margin-right'] = `${twipsToPt(right)}pt`;
        if (hanging !== null) d['text-indent'] = `${-twipsToPt(hanging)}pt`;
        else if (firstLine !== null) d['text-indent'] = `${twipsToPt(firstLine)}pt`;
        break;
      }
      case 'w:shd':
        shadeDecls(c, d);
        break;
      case 'w:pBdr':
        borderDecls(c, d);
        d['padding'] = '1pt 4pt';
        break;
      case 'w:bidi':
        if (isOn(c)) d.direction = 'rtl';
        break;
      case 'w:pageBreakBefore':
        if (isOn(c)) d['--pbb'] = '1';
        break;
    }
  }

  return d;
}

const VALIGN: Record<string, string> = { top: 'top', center: 'middle', bottom: 'bottom' };

/** Cell formatting (`w:tcPr`) as CSS. */
export function cellDecls(tcPr: XmlEl | null | undefined): Decls {
  const d: Decls = {};
  if (!tcPr) return d;

  for (const c of tcPr.children) {
    switch (c.name) {
      case 'w:shd':
        shadeDecls(c, d);
        break;
      case 'w:tcBorders':
        borderDecls(c, d);
        break;
      case 'w:vAlign':
        if (VALIGN[c.attrs['w:val'] ?? '']) d['vertical-align'] = VALIGN[c.attrs['w:val']];
        break;
    }
  }

  return d;
}

const hasBorder = (d: Decls) => Object.keys(d).some((key) => key.startsWith('border-') && d[key] !== 'none');

/**
 * How page.css shows a colour on a dark page: lightness turned over between the paper and the ink,
 * hue kept, and saturated colours lifted a little so that a dark blue heading stays readable.
 */
export const darkMap = (variable: string) =>
  `oklch(from var(${variable}) calc(var(--pl) + (1 - l) * (var(--il) - var(--pl)) + c * 0.9) c h)`;

/**
 * How page.css shows a fill on a tinted page: laid on the paper as ink is, each channel multiplied
 * by the paper's (--pr, --pg, --pb), so that a white cell is the paper's colour and not a patch.
 */
export const tintMap = (variable: string) =>
  `rgb(from var(${variable}) calc(r * var(--pr)) calc(g * var(--pg)) calc(b * var(--pb)))`;

/**
 * A stylesheet rule for these declarations, with the dark and the tinted page's rules after it
 * where colours are involved. `scope` selects the page, `parts` what the rule is for inside it.
 */
export function ruleCss(scope: string, parts: string[], d: Decls): string {
  const within = (page: string) => parts.map((part) => `${page} ${part}`).join(',');
  let body = '';
  const dark: string[] = [];
  let tint = '';

  for (const [key, value] of Object.entries(d)) {
    if (key === '--od' || key === '--pbb') continue;
    body += `${key}:${value};`;
  }

  if (d['--c']) {
    body += 'color:var(--c);';
    dark.push(`color:${darkMap('--c')}`);
  } else if (d['--od']) {
    body += 'color:var(--on-dark-fill);';
  }

  if (d['--h']) {
    body += 'background-color:var(--h);';
    dark.push(`background-color:${darkMap('--h')}`);
    tint = `background-color:${tintMap('--h')}`;
  }

  if (hasBorder(d)) {
    body += d['--bc'] ? 'border-color:var(--bc);' : 'border-color:var(--page-ink);';
    if (d['--bc']) dark.push(`border-color:${darkMap('--bc')}`);
  }

  if (!body) return '';

  return (
    `${within(scope)}{${body}}\n` +
    (dark.length ? `${within(`${scope}[data-mode="dark"]`)}{${dark.join(';')}}\n` : '') +
    (tint ? `${within(`${scope}[data-mode="tint"]`)}{${tint}}\n` : '')
  );
}

/**
 * The same declarations for one element: a style attribute, plus the classes page.css keys its
 * colour rules on (c text, h fill, bd / bdc border, od text on a dark fill, pbb page break before).
 */
export function inlineCss(d: Decls): { style: string; classes: string[] } {
  let style = '';
  const classes: string[] = [];

  for (const [key, value] of Object.entries(d)) {
    if (key === '--od' || key === '--pbb') continue;
    style += `${key}:${value};`;
  }

  if (d['--c']) classes.push('c');
  else if (d['--od']) classes.push('od');
  if (d['--h']) classes.push('h');
  if (hasBorder(d)) classes.push(d['--bc'] ? 'bdc' : 'bd');
  if (d['--pbb']) classes.push('pbb');

  return { style, classes };
}
