// What is drawn on each page around its text: the header in the top margin, the footer in the
// bottom margin, and the strip of desk between one sheet and the next.
//
// None of it is in the editor's document. It is a layer over the `.page` element, laid out from
// what pages.ts measured: page k's top edge is k × (page height + gap) from the page element's
// top. Each header and footer is its part (src/docx/headers.ts) with its page-number fields
// filled in for that page. A double click on one opens it in an editor of its own, in place;
// leaving it (a click elsewhere, or Escape) writes the part back if anything changed.
//
// The footer's bottom edge stands at the footer distance (`w:pgMar/@w:footer`) from the page's
// bottom edge, as in Word, and it grows upwards. A footer taller than the bottom margin leaves
// room for itself: the body and its footnote area end above it (`footerClearance`).

import { DOMSerializer, type Node as PMNode } from 'prosemirror-model';
import type { EditorView } from 'prosemirror-view';
import { footerRoom } from './footer-room';
import { type HfKind, type PageInfo, type Section, evenAndOddHeaders, fillFields, loadPart, numberPages, partFor, savePart, sectionsOf } from '../docx/headers';
import type { DocContext } from '../docx/import';
import { PAGE_GAP } from './pages';
import { schema } from './schema';
import { notesViewOf } from '../notes/view';
import { createEditor } from './view';

/** How far the strip of desk reaches past the page's edges, to cover its shadow. */
const BAND_OVERHANG = 22;

interface Editing {
  view: EditorView;
  path: string;
  box: HTMLElement;
  start: PMNode;
  leave: (event: Event) => void;
}

export class PageFurniture {
  private readonly layer = document.createElement('div');
  /** The section each page starts in, as last measured. */
  private pageSections: number[] = [0];
  /** The footnotes at the foot of each page, by id (src/notes/view.ts). */
  private pageNotes: string[][] = [];
  private pages: PageInfo[] = [];
  private sections: Section[] = [];
  private evenOdd = false;
  /** Headers and footers drawn already, by part and the numbers shown in them. */
  private readonly drawn = new Map<string, HTMLElement>();
  private editing: Editing | null = null;
  /** Footer heights, by part, as measured at the body's width; measured again with each layout. */
  private readonly footerHeights = new Map<string, number>();
  /** Called after a header or footer was changed and written back into the package. */
  onEdited: () => void = () => {};

  constructor(
    private readonly main: EditorView,
    private readonly ctx: DocContext,
    private readonly pageEl: HTMLElement,
  ) {
    this.layer.className = 'page-furniture';

    // The desk takes a press outside the text to put the cursor back into it; not this one.
    this.layer.addEventListener('mousedown', (event) => {
      if (this.editing?.box.contains(event.target as Node)) event.stopPropagation();
    });

    this.layer.addEventListener('dblclick', (event) => {
      const box = (event.target as HTMLElement).closest<HTMLElement>('.hf');
      if (!box || box.classList.contains('editing')) return;

      event.preventDefault();
      this.edit(box);
    });
  }

  /** The pages as last drawn: their numbers and sections. */
  get pageInfo(): readonly PageInfo[] {
    return this.pages;
  }

  /** Draws every page's header and footer, and the desk between the pages. */
  draw(pageSections: number[], pageNotes: string[][] = this.pageNotes): void {
    this.pageSections = pageSections;
    this.pageNotes = pageNotes;
    // Redrawing would take away the editor in use; it is drawn when that is left.
    if (this.editing) return;

    this.sections = sectionsOf(this.ctx, this.main.state.doc);
    this.evenOdd = evenAndOddHeaders(this.ctx);
    this.pages = numberPages(pageSections, this.sections);

    const page = this.ctx.page;
    const pitch = page.height + PAGE_GAP;
    const out: HTMLElement[] = [];

    this.pages.forEach((_info, k) => {
      if (k > 0) {
        const band = document.createElement('div');
        band.className = 'page-gap-band';
        band.style.top = `${k * pitch - PAGE_GAP}px`;
        band.style.left = `${-BAND_OVERHANG}px`;
        band.style.width = `${page.width + BAND_OVERHANG * 2}px`;
        band.style.height = `${PAGE_GAP}px`;
        out.push(band);
      }

      out.push(...this.sheetBoxes(k, k * pitch));
    });

    this.layer.replaceChildren(...out);
    if (this.layer.parentElement !== this.pageEl) this.pageEl.append(this.layer);
  }

  clear(): void {
    this.finish();
    this.layer.replaceChildren();
    this.layer.remove();
  }

  destroy(): void {
    this.clear();
  }

  /** The header and footer of page `k`, placed for a sheet whose top edge is at `top`. */
  sheetBoxes(k: number, top = 0): HTMLElement[] {
    const boxes = (['header', 'footer'] as const).map((kind) => this.box(kind, k, top)).filter((el): el is HTMLElement => !!el);
    const foot = this.footArea(k, top);
    return foot ? [...boxes, foot] : boxes;
  }

  /** Page `k`'s footnotes, under a short line at the foot of its body. */
  private footArea(k: number, top: number): HTMLElement | null {
    const ids = this.pageNotes[k];
    const notes = notesViewOf(this.main);
    if (!ids?.length || !notes) return null;

    const page = this.ctx.page;
    const el = document.createElement('div');
    const sep = document.createElement('div');

    el.className = 'foot-area notes-area';
    el.contentEditable = 'false';
    el.style.left = `${page.left}px`;
    el.style.width = `${Math.max(20, page.width - page.left - page.right)}px`;
    el.style.top = `${top + page.height - page.bottom - this.clearanceOf(k, this.pages)}px`;
    sep.className = 'foot-sep';
    el.append(sep, ...notes.footBoxes(ids));
    notes.wire(el);

    return el;
  }

  /**
   * How far the body of the last page in `pageSections` has to end above its bottom margin to
   * keep clear of a footer taller than the margin. pages.ts asks this as it starts each page.
   */
  footerClearance(pageSections: readonly number[]): number {
    if (this.editing || !pageSections.length) return 0;
    // The first page of a new measure: the sections may have changed since the last.
    if (pageSections.length === 1 || !this.sections.length) {
      this.footerHeights.clear();
      this.sections = sectionsOf(this.ctx, this.main.state.doc);
      this.evenOdd = evenAndOddHeaders(this.ctx);
    }
    return this.clearanceOf(pageSections.length - 1, numberPages(pageSections, this.sections));
  }

  private clearanceOf(k: number, pages: readonly PageInfo[]): number {
    const info = pages[k];
    const path = info ? partFor('footer', info, this.sections, this.evenOdd) : null;
    if (!info || !path) return 0;

    return footerRoom(this.ctx.page.bottom, this.sectionOf(info).footerDistance, this.footerHeight(path, info));
  }

  /** A footer's height, measured once per part at the body's width. */
  private footerHeight(path: string, info: PageInfo): number {
    let height = this.footerHeights.get(path);
    if (height !== undefined) return height;

    const content = this.content(path, info);
    if (!content) return 0;

    const page = this.ctx.page;
    const probe = document.createElement('div');
    const parent = this.layer.parentElement ?? this.pageEl;

    probe.className = 'hf hf-footer';
    probe.style.visibility = 'hidden';
    probe.style.width = `${Math.max(20, page.width - page.left - page.right)}px`;
    probe.append(content);
    parent.append(probe);
    // In the page's own pixels: the page's zoom is taken out.
    height = probe.getBoundingClientRect().height / (parseFloat(getComputedStyle(this.pageEl).zoom) || 1);
    probe.remove();

    this.footerHeights.set(path, height);
    return height;
  }

  private sectionOf(info: PageInfo): Section {
    return this.sections[Math.min(info.section, this.sections.length - 1)];
  }

  private box(kind: HfKind, k: number, top: number): HTMLElement | null {
    const info = this.pages[k];
    const path = info ? partFor(kind, info, this.sections, this.evenOdd) : null;
    if (!info || !path) return null;

    const content = this.content(path, info);
    if (!content) return null;

    const page = this.ctx.page;
    const section = this.sectionOf(info);
    const el = document.createElement('div');

    el.className = `hf hf-${kind}`;
    el.title = kind === 'header' ? 'Double-click to edit the header' : 'Double-click to edit the footer';
    el.dataset.page = String(k);
    el.dataset.path = path;
    el.style.left = `${page.left}px`;
    el.style.width = `${Math.max(20, page.width - page.left - page.right)}px`;
    el.style.top = `${kind === 'header' ? top + section.headerDistance : top + page.height - section.footerDistance}px`;
    el.append(content);

    return el;
  }

  /** A part as shown on one page: its fields filled in. */
  private filled(path: string, info: PageInfo): PMNode | null {
    const part = loadPart(this.ctx, path);
    return part ? fillFields(part.doc, { page: info, numPages: this.pages.length }, this.sectionOf(info).fmt) : null;
  }

  private content(path: string, info: PageInfo): HTMLElement | null {
    const key = `${path}|${info.label}|${info.sectionPages}|${this.pages.length}`;
    let el = this.drawn.get(key);

    if (!el) {
      const doc = this.filled(path, info);
      if (!doc) return null;

      el = document.createElement('div');
      el.className = 'ProseMirror hf-content';
      el.append(DOMSerializer.fromSchema(schema).serializeFragment(doc.content));
      this.drawn.set(key, el);
    }

    return el.cloneNode(true) as HTMLElement;
  }

  // ---- Editing ------------------------------------------------------------------------------

  private edit(box: HTMLElement): void {
    this.finish();

    const path = box.dataset.path ?? '';
    const info = this.pages[Number(box.dataset.page)];
    const doc = info ? this.filled(path, info) : null;
    if (!doc) return;

    box.replaceChildren();
    box.classList.add('editing');
    this.pageEl.classList.add('hf-editing');

    const view = createEditor({
      ctx: this.ctx,
      doc,
      mount: box,
      onChange: () => {},
      onOpenLink: () => {},
      onEditChart: () => {},
      onSuggestion: () => {},
      nested: true,
    });
    view.dom.classList.add('hf-content');

    // Leaving: a press anywhere outside it, or Escape.
    const leave = (event: Event) => {
      const inside = box.contains(event.target as Node);
      if (event instanceof KeyboardEvent ? event.key === 'Escape' && inside : !inside) this.finish();
    };

    document.addEventListener('mousedown', leave, true);
    document.addEventListener('keydown', leave, true);

    this.editing = { view, path, box, start: view.state.doc, leave };
    view.focus();
  }

  /** Leaves the header or footer being edited, writing it back if it changed. */
  finish(): void {
    const editing = this.editing;
    if (!editing) return;

    this.editing = null;
    document.removeEventListener('mousedown', editing.leave, true);
    document.removeEventListener('keydown', editing.leave, true);

    const doc = editing.view.state.doc;
    editing.view.destroy();
    this.pageEl.classList.remove('hf-editing');

    if (!doc.eq(editing.start)) {
      savePart(this.ctx, editing.path, doc);
      this.drawn.clear();
      this.footerHeights.clear();
      this.onEdited();
    }

    if (this.layer.isConnected) this.draw(this.pageSections);
  }
}
