// ---- Patterns -----------------------------------------------------------------------------------

type Token =
  | { kind: 'word'; options: RegExp[]; not: boolean }
  | { kind: 'any' }
  | { kind: 'gap'; max: number };

interface Compiled {
  start: boolean;
  tokens: Token[];
}

const wordRegex = (text: string) =>
  new RegExp(`^${text.toLowerCase().replace(/[.+?^${}()[\]\\]/g, '\\$&').replace(/\*/g, '[\\p{L}\\p{N}\\-]*')}$`, 'u');

/** A pattern line as tokens, or a sentence saying what is wrong with it. */
export function compilePattern(line: string): Compiled | string {
  const parts = line.trim().split(/\s+/).filter(Boolean);
  const start = parts[0] === '^';
  if (start) parts.shift();

  if (!parts.length) return 'The pattern is empty.';

  const tokens: Token[] = [];

  for (const part of parts) {
    const gap = /^(?:\.\.\.|…)(\d*)$/.exec(part);

    if (gap) {
      if (!tokens.length || tokens[tokens.length - 1].kind === 'gap') return 'A gap (...) needs a word before and after it.';
      tokens.push({ kind: 'gap', max: gap[1] ? Math.min(30, Number(gap[1])) : 8 });
    } else if (part === '@') {
      tokens.push({ kind: 'any' });
    } else {
      const not = part.startsWith('!');
      const options = part.replace(/^!/, '').split('|').filter(Boolean);

      if (!options.length || options.some((o) => !/[\p{L}\p{N}]/u.test(o))) return `“${part}” is not a word pattern.`;
      tokens.push({ kind: 'word', options: options.map(wordRegex), not });
    }
  }

  if (tokens[tokens.length - 1].kind === 'gap') return 'A gap (...) needs a word before and after it.';
  return { start, tokens };
}

/** Why a rule's pattern cannot be used, or null when it can. */
export function patternProblem(pattern: string): string | null {
  const lines = pattern.split('\n').filter((l) => l.trim());
  if (!lines.length) return 'The pattern is empty.';

  for (const line of lines) {
    const compiled = compilePattern(line);
    if (typeof compiled === 'string') return compiled;
  }

  return null;
}

interface SentenceWord {
  word: string;
  from: number;
  to: number;
  sentence: number;
  first: boolean;
}

const WORD = /[\p{L}\p{N}]+(?:[-'’][\p{L}\p{N}]+)*/gu;

/** The words of a paragraph, each with the sentence it is in. A sentence ends at . ! ? or : before a capital. */
export function sentenceWords(text: string): SentenceWord[] {
  const out: SentenceWord[] = [];
  let sentence = 0;
  let last = 0;

  for (const m of text.matchAll(WORD)) {
    const between = text.slice(last, m.index);
    const ends = out.length > 0 && /[.!?]["'”»)]*\s/.test(between) && /^\p{Lu}/u.test(m[0]) && !/\b\p{L}\.\s*$/u.test(text.slice(Math.max(0, last - 2), m.index));

    if (ends) sentence++;
    out.push({ word: m[0], from: m.index, to: m.index + m[0].length, sentence, first: !out.length || ends });
    last = m.index + m[0].length;
  }

  return out;
}

const fits = (token: Token, word: string) => {
  if (token.kind === 'any') return true;
  if (token.kind !== 'word') return false;

  const lower = word.toLowerCase();
  const hit = token.options.some((r) => r.test(lower));
  return token.not ? !hit : hit;
};

/** Where a compiled pattern matches at word `i`: the index of its last word, or -1. */
function matchAt(words: SentenceWord[], i: number, tokens: Token[], t: number, sentence: number): number {
  if (t === tokens.length) return i - 1;
  if (i >= words.length || words[i].sentence !== sentence) return -1;

  const token = tokens[t];

  if (token.kind === 'gap') {
    for (let skip = 0; skip <= token.max; skip++) {
      if (i + skip >= words.length || words[i + skip].sentence !== sentence) break;

      const end = matchAt(words, i + skip, tokens, t + 1, sentence);
      if (end >= 0) return end;
    }
    return -1;
  }

  return fits(token, words[i].word) ? matchAt(words, i + 1, tokens, t + 1, sentence) : -1;
}

export interface StyleHit {
  rule: StyleRule;
  para: number;
  from: number;
  to: number;
  text: string;
  /** Whether the pattern had a gap: then the hit cannot be replaced as one stretch. */
  gapped: boolean;
}

/** Every place in the paragraphs where one of the rules matches, in reading order. */
export function findStyleHits(paragraphs: string[], rules: StyleRule[]): StyleHit[] {
  const compiled = rules.map((rule) => ({
    rule,
    lines: rule.pattern
      .split('\n')
      .filter((l) => l.trim())
      .map(compilePattern)
      .filter((c): c is Compiled => typeof c !== 'string'),
  }));
  const hits: StyleHit[] = [];

  paragraphs.forEach((text, para) => {
    const words = sentenceWords(text);

    for (const { rule, lines } of compiled) {
      let after = -1;

      for (let i = 0; i < words.length; i++) {
        if (i <= after) continue;

        for (const line of lines) {
          if (line.start && !words[i].first) continue;

          const end = matchAt(words, i, line.tokens, 0, words[i].sentence);

          if (end >= 0) {
            const from = words[i].from;
            const to = words[end].to;

            hits.push({ rule, para, from, to, text: text.slice(from, to), gapped: line.tokens.some((t) => t.kind === 'gap') });
            after = end;
            break;
          }
        }
      }
    }
  });

  return hits.sort((a, b) => a.para - b.para || a.from - b.from);
}

/** The hits as review findings, with a fix where the rule has a replacement and the hit no gap. */
export function styleFindings(paragraphs: string[], rules: StyleRule[]): Finding[] {
  return findStyleHits(paragraphs, rules).map((hit) => {
    const spot: Spot = { para: hit.para, from: hit.from, to: hit.to, text: hit.text };
    let fix: Finding['fix'];

    if (hit.rule.replace !== undefined && !hit.gapped) {
      // An empty replacement takes the space after it too, and gives the next word a capital
      // when the phrase began the sentence.
      const text = paragraphs[hit.para];
      const to = hit.rule.replace === '' ? hit.to + (/^[ ,]*/.exec(text.slice(hit.to))?.[0].length ?? 0) : hit.to;
      const insert = matchCase(hit.text, hit.rule.replace);

      if (hit.rule.replace === '' && /^\p{Lu}/u.test(hit.text)) {
        fix = [{ ...spot, to: to + 1, text: text.slice(hit.from, to + 1), insert: text.charAt(to).toUpperCase() }];
      } else {
        fix = [{ ...spot, to, text: text.slice(hit.from, to), insert }];
      }
    }

    return {
      kind: 'style',
      title: hit.rule.suggestion ? `${hit.text} → ${hit.rule.suggestion}` : hit.text,
      detail: hit.rule.explanation,
      spots: [spot],
      fix,
      rule: hit.rule.id,
    } satisfies Finding;
  });
}

const GERMAN = /^(der|die|das|und|ist|nicht|ein|eine|mit|von|zu|auf|für|sich|dass|wird|werden|auch|als|bei|oder|wie|im|den|des)$/i;
const ENGLISH = /^(the|and|is|of|to|in|that|it|for|with|as|was|are|be|this|by|on|not|or|from|which|an|have|has)$/i;

/** Whether a text is mostly German or mostly English, by its commonest words. */
export function guessLanguage(text: string): 'de' | 'en' {
  let de = 0;
  let en = 0;

  for (const m of text.slice(0, 20_000).matchAll(/\p{L}+/gu)) {
    if (GERMAN.test(m[0])) de++;
    else if (ENGLISH.test(m[0])) en++;
  }

  return de > en ? 'de' : 'en';
}

/** The rules that apply to a text in a language, without the ones switched off. */
export function activeRules(rules: StyleRule[], language: 'de' | 'en', off: ReadonlySet<string>): StyleRule[] {
  return rules.filter((r) => !off.has(r.id) && (r.language === 'any' || r.language === language));
}
