// The find and replace bar, under the toolbar.
//
// Besides finding text it finds patterns with variables, `(*)` for whatever is in brackets, and
// formats every match at once: all of each match, or only what its variables stood for.

import type { Command } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import {
  clearFind, type FindMode, type FindTarget, findState, findStep, MAX_MATCHES, replaceAll, replaceCurrent, setQuery, targetSpans, WILDCARDS,
} from '../editor/find';
import { type FormatAction, formatSpans } from '../editor/format';
import { describeFilter, type FormatFilter, fontsUsed, styleRuns } from '../editor/formatmatch';
import { type Recipe, type RecipeFormat, runRecipe } from '../editor/recipes';
import { closePopover, h, keepFocus, popover, store, stored, toast } from './dom';
import { filterEditor } from './findfilter';
import { icon } from './icons';
import { recipesMenu } from './recipesmenu';

export interface FindHost {
  tab(): { view: EditorView; ctx: DocContext } | null;
  focus(): void;
  /** The fonts the toolbar offers. */
  fonts(): string[];
  /** The colours the toolbar offers for text and for highlighting. */
  colors(): { text: string[]; highlight: string[] };
}

const MODE_KEY = 'text-studio:find-mode';
const TARGET_KEY = 'text-studio:find-target';

const MODES: { value: FindMode; label: string; title: string }[] = [
  { value: 'text', label: 'Text', title: 'Find the words as typed' },
  { value: 'pattern', label: 'Pattern', title: 'Wildcards as variables: (*) finds everything in round brackets' },
  { value: 'regex', label: 'Regex', title: 'A regular expression; its groups are the variables' },
];

const EXAMPLES: { pattern: string; meaning: string }[] = [
  { pattern: '(*)', meaning: 'everything in round brackets' },
  { pattern: '"*"', meaning: 'everything in quotation marks' },
  { pattern: '[#]', meaning: 'numbered references like [12]' },
  { pattern: 'Figure #', meaning: '“Figure 3”, “Figure 12”, …' },
  { pattern: '*:', meaning: 'the start of a line up to a colon' },
];

export class FindBar {
  readonly el = h('div', { class: 'findbar', hidden: true });

  private readonly query = h('input', { class: 'field', placeholder: 'Find', spellcheck: 'false' });
  private readonly replacement = h('input', { class: 'field', placeholder: 'Replace with', spellcheck: 'false' });
  private readonly matchCase = h('input', { type: 'checkbox' });
  private readonly modeSelect = h('select', { class: 'tool-select mode', title: 'How the search is read' });
  private readonly helpButton = h('button', { class: 'tool', title: 'How patterns work', html: '<span class="glyph">?</span>' });
  private readonly formatButton = h('button', { class: 'button', title: 'Format every match, or only its variables' }, 'Format…');
  private readonly count = h('span', { class: 'count' });
  private readonly filterButton = h('button', { class: 'button filter', title: 'Find only text with some formatting: italic, a font, a style, …' }, 'Formatting…');
  private readonly recipesButton = h('button', { class: 'button', title: 'Saved searches that format or replace every match' }, 'Recipes…');
  /** The formatting matches must have, or null for any. */
  private filter: FormatFilter | null = null;
  /** The formatting last given from the Format menu, for a recipe to save. */
  private lastFormat: { format: RecipeFormat; label: string } | null = null;
  private mode: FindMode = (MODES.find((m) => m.value === stored(MODE_KEY))?.value ?? 'text') as FindMode;
  private target: FindTarget = stored(TARGET_KEY) === 'match' ? 'match' : 'variables';

  constructor(private readonly host: FindHost) {
    const button = (title: string, content: string, action: () => void, cls = 'tool') => h('button', { class: cls, title, html: content, onclick: action });

    keepFocus(this.el);

    for (const m of MODES) this.modeSelect.append(h('option', { value: m.value, title: m.title }, m.label));
    this.modeSelect.value = this.mode;

    this.modeSelect.addEventListener('change', () => {
      this.mode = this.modeSelect.value as FindMode;
      store(MODE_KEY, this.mode);
      this.showMode();
      this.search();
      this.query.focus();
    });

    this.helpButton.addEventListener('click', () => this.help());
    this.formatButton.addEventListener('click', () => this.formatMenu());
    this.filterButton.addEventListener('click', () => this.filterMenu());
    this.recipesButton.addEventListener('click', () => this.recipes());

    this.query.addEventListener('input', () => this.search());
    this.matchCase.addEventListener('change', () => this.search());

    this.query.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        this.run(findStep(event.shiftKey ? -1 : 1));
      }
    });

    this.replacement.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        this.run(replaceCurrent(this.replacement.value));
      }
    });

    this.el.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && !event.defaultPrevented) {
        event.preventDefault();
        this.close();
      }
    });

    this.el.append(
      this.modeSelect,
      this.query,
      this.helpButton,
      this.filterButton,
      button('Previous (Shift+Enter)', icon('up'), () => this.run(findStep(-1))),
      button('Next (Enter)', icon('down'), () => this.run(findStep(1))),
      this.count,
      h('label', { class: 'check', title: 'Match upper and lower case' }, this.matchCase, 'Aa'),
      this.replacement,
      button('Replace this match', 'Replace', () => this.run(replaceCurrent(this.replacement.value)), 'button'),
      button('Replace every match', 'All', () => this.replaceEvery(), 'button'),
      this.formatButton,
      this.recipesButton,
      h('span', { class: 'spacer' }),
      button('Close (Esc)', icon('close'), () => this.close()),
    );

    this.showMode();
  }

  get isOpen(): boolean {
    return !this.el.hidden;
  }

  /** Runs a command on the document without moving the focus out of the bar. */
  private run(command: Command): boolean {
    const view = this.host.tab()?.view;
    return view ? command(view.state, view.dispatch) : false;
  }

  private search(): void {
    const ctx = this.host.tab()?.ctx;
    this.run(setQuery(this.query.value, this.matchCase.checked, this.mode, this.filter, ctx ? styleRuns(ctx.styles) : null));
  }

  // ---- Finding by formatting -------------------------------------------------------------------

  private setFilter(filter: FormatFilter | null): void {
    this.filter = filter;

    const ctx = this.host.tab()?.ctx;
    const name = (id: string) => {
      const def = ctx?.styles.byId.get(id);
      return def ? ctx!.styles.displayName(def) : id;
    };

    this.filterButton.setAttribute('aria-pressed', String(!!filter));
    this.filterButton.textContent = filter ? describeFilter(filter, name) : 'Formatting…';
    this.search();
  }

  private filterMenu(): void {
    const tab = this.host.tab();
    if (!tab) return;

    const { styles } = tab.ctx;
    const fonts = [...new Set([...fontsUsed(tab.view.state.doc), ...this.host.fonts()])];
    const choices = styles
      .choices()
      .filter((c) => !c.value.startsWith('builtin:'))
      .map((c) => ({ value: c.value === styles.defaultParagraph ? '' : c.value, label: c.label }));

    popover(this.filterButton, filterEditor(this.filter, { fonts, colors: this.host.colors(), styles: choices, onChange: (f) => this.setFilter(f) }), () => this.query.focus());
  }

  // ---- Recipes ---------------------------------------------------------------------------------

  private recipes(): void {
    popover(
      this.recipesButton,
      recipesMenu(
        {
          state: () => ({
            mode: this.mode,
            query: this.query.value,
            matchCase: this.matchCase.checked,
            filter: this.filter,
            replacement: this.replacement.value,
            target: this.target,
            lastFormat: this.lastFormat,
          }),
          run: (recipe) => this.runRecipe(recipe),
          load: (recipe) => this.load(recipe),
        },
        () => closePopover(),
      ),
      () => this.query.focus(),
    );
  }

  /** Puts a recipe's search into the bar and shows its matches. */
  load(recipe: Recipe): void {
    this.mode = recipe.mode;
    this.modeSelect.value = recipe.mode;
    this.query.value = recipe.query;
    this.matchCase.checked = recipe.matchCase;
    this.replacement.value = recipe.replace ?? '';
    this.target = recipe.target;
    this.showMode();

    this.el.hidden = false;
    this.setFilter(recipe.filter);
    this.query.focus();
  }

  /** Runs a recipe on the document in front, then shows what it looked for. */
  runRecipe(recipe: Recipe): void {
    const tab = this.host.tab();
    if (!tab) return;

    let found = { matches: 0, error: null as string | null };
    const done = runRecipe(recipe, tab.ctx, styleRuns(tab.ctx.styles), (r) => (found = r))(tab.view.state, tab.view.dispatch);

    this.load(recipe);

    if (found.error) toast(`Not a valid pattern: ${found.error}`, true);
    else if (!found.matches) toast(`“${recipe.name}” found nothing in this document.`);
    else if (done) toast(`“${recipe.name}”: ${found.matches} ${found.matches === 1 ? 'match' : 'matches'}. Ctrl+Z undoes it.`);
    else toast(`“${recipe.name}” changed nothing.`);
  }

  private showMode(): void {
    const wild = this.mode !== 'text';

    this.query.placeholder = { text: 'Find', pattern: 'Find a pattern: (*)', regex: 'Regular expression' }[this.mode];
    this.replacement.placeholder = wild ? 'Replace with ($1 = 1st variable)' : 'Replace with';
    this.replacement.title = wild ? '$1, $2, … put back what each variable matched, with its formatting; $0 the whole match' : '';
    this.helpButton.hidden = !wild;
    this.el.classList.toggle('patterns', wild);
  }

  private replaceEvery(): void {
    const count = this.matchCount();
    if (this.run(replaceAll(this.replacement.value))) toast(`Replaced ${count} ${count === 1 ? 'match' : 'matches'}. Ctrl+Z undoes it.`);
  }

  private matchCount(): number {
    const view = this.host.tab()?.view;
    return view ? findState(view.state).matches.length : 0;
  }

  // ---- Help ----------------------------------------------------------------------------------

  private help(): void {
    const use = (pattern: string) => {
      closePopover();
      this.query.value = pattern;
      this.query.focus();
      this.search();
    };

    const content =
      this.mode === 'regex'
        ? h(
            'div',
            { class: 'find-help' },
            h('div', { class: 'menu-label' }, 'Regular expressions'),
            h('p', null, 'JavaScript syntax. Each group in round brackets is a variable: \\((.*?)\\) finds bracketed text and makes its inside variable 1.'),
            h('p', null, 'In the replacement, $1, $2, … put back what each group matched; $0 is the whole match.'),
          )
        : h(
            'div',
            { class: 'find-help' },
            h('div', { class: 'menu-label' }, 'Wildcards: each one is a variable'),
            h('table', null, ...WILDCARDS.map((w) => h('tr', null, h('td', null, h('code', null, w.token)), h('td', null, w.meaning)))),
            h('div', { class: 'menu-label' }, 'Try'),
            ...EXAMPLES.map((e) =>
              h('button', { class: 'menu-item', onclick: () => use(e.pattern) }, h('code', null, e.pattern), h('span', { class: 'hint' }, e.meaning)),
            ),
            h(
              'p',
              null,
              'Format… can style only the variables: with (*), the text inside the brackets. ' +
                'Replacing (*) with $1 takes the brackets away and keeps the text and its formatting.',
            ),
          );

    popover(this.helpButton, content, () => this.query.focus());
  }

  // ---- Formatting every match ----------------------------------------------------------------

  private formatMenu(): void {
    const tab = this.host.tab();
    if (!tab) return;

    const { matches, mode } = findState(tab.view.state);

    if (!matches.length) {
      toast('Nothing found to format. Search for something first.');
      return;
    }

    const hasVariables = mode !== 'text' && matches.some((m) => m.groups.length);
    const target = (): FindTarget => (hasVariables ? this.target : 'match');

    const apply = (action: FormatAction, what: string) => {
      const view = this.host.tab()?.view;
      if (!view) return;

      const state = findState(view.state);
      const spans = targetSpans(state.matches, target());
      const done = formatSpans(spans, action)(view.state, view.dispatch);
      const n = state.matches.length;

      // Kept for a recipe, which puts the formatting on rather than toggling it.
      if (done) {
        const format: RecipeFormat = action.kind === 'style' ? { kind: 'style', value: action.value } : action.kind === 'toggle' || action.kind === 'vert' ? { ...action, on: true } : action;
        this.lastFormat = { format, label: what };
      }
      if (done) toast(`${what}: ${n} ${n === 1 ? 'match' : 'matches'}${target() === 'variables' ? ' (variables only)' : ''}. Ctrl+Z undoes it.`);
      else toast('That changed nothing.');
    };

    // Where the formatting goes.
    const targetRow = h('div', { class: 'segmented' });
    const targetButtons = (['variables', 'match'] as FindTarget[]).map((value) =>
      h(
        'button',
        {
          class: 'seg',
          'aria-pressed': String(target() === value),
          disabled: !hasVariables && value === 'variables',
          onclick: () => {
            this.target = value;
            store(TARGET_KEY, value);
            for (const b of targetButtons) b.setAttribute('aria-pressed', String(b.dataset.value === value));
          },
          'data-value': value,
        },
        value === 'variables' ? 'Only the variables' : 'The whole match',
      ),
    );

    targetRow.append(...targetButtons);

    const glyph = (cls: string, text: string) => `<span class="glyph ${cls}">${text}</span>`;
    const toggle = (title: string, html: string, action: FormatAction) => h('button', { class: 'tool', title, html, onclick: () => apply(action, title) });

    const toggles = h(
      'div',
      { class: 'find-format-row' },
      toggle('Bold', glyph('b', 'B'), { kind: 'toggle', mark: 'bold' }),
      toggle('Italic', glyph('i', 'I'), { kind: 'toggle', mark: 'italic' }),
      toggle('Underline', glyph('u', 'U'), { kind: 'toggle', mark: 'underline' }),
      toggle('Strikethrough', glyph('s', 'S'), { kind: 'toggle', mark: 'strike' }),
      toggle('Subscript', glyph('', 'x<small>2</small>'), { kind: 'vert', value: 'subscript' }),
      toggle('Superscript', glyph('', 'x<small style="vertical-align:super">2</small>'), { kind: 'vert', value: 'superscript' }),
      h('button', { class: 'tool', title: 'Clear formatting', html: icon('clear'), onclick: () => apply({ kind: 'clear' }, 'Cleared formatting') }),
    );

    // Font and size.
    const font = h('select', { class: 'tool-select font', title: 'Font' }, h('option', { value: '' }, 'Font…'), ...this.host.fonts().map((f) => h('option', { value: f }, f)));
    font.addEventListener('change', () => font.value && apply({ kind: 'set', mark: 'fontFamily', attrs: { name: font.value } }, `Font ${font.value}`));

    const size = h('input', { class: 'tool-input size', title: 'Font size, in points', placeholder: 'Size', list: 'font-sizes', inputmode: 'decimal' });
    const applySize = () => {
      const pt = parseFloat(size.value.replace(',', '.'));
      if (pt >= 1 && pt <= 1638) apply({ kind: 'set', mark: 'fontSize', attrs: { size: Math.round(pt * 2) } }, `Size ${pt} pt`);
    };
    size.addEventListener('change', applySize);
    size.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        applySize();
      }
    });

    // Colours.
    const { text: textColors, highlight: highlightColors } = this.host.colors();
    const swatches = (mark: 'color' | 'highlight', colors: string[], none: string) =>
      h(
        'div',
        { class: 'swatches' },
        h('button', { class: 'swatch none', title: none, onclick: () => apply({ kind: 'set', mark, attrs: null }, none) }),
        ...colors.map((value) =>
          h('button', { class: 'swatch', title: value, style: `background:${value}`, onclick: () => apply({ kind: 'set', mark, attrs: { value } }, mark === 'color' ? 'Text colour' : 'Highlight') }),
        ),
      );

    // Paragraph style, for the paragraphs the matches are in.
    const style = h('select', { class: 'tool-select style', title: 'Give the paragraphs the matches are in this style' }, h('option', { value: '' }, 'Paragraph style…'));
    for (const choice of tab.ctx.styles.choices()) style.append(h('option', { value: choice.value }, choice.label));
    style.addEventListener('change', () => {
      const ctx = this.host.tab()?.ctx;
      if (ctx && style.value) apply({ kind: 'style', ctx, value: style.value }, `Style ${style.selectedOptions[0]?.textContent ?? ''}`);
    });

    popover(
      this.formatButton,
      h(
        'div',
        { class: 'find-format' },
        h('div', { class: 'menu-label' }, `Format ${matches.length >= MAX_MATCHES ? `the first ${MAX_MATCHES}` : matches.length} ${matches.length === 1 ? 'match' : 'matches'}`),
        hasVariables ? targetRow : h('p', { class: 'note' }, mode === 'text' ? 'Search in Pattern mode, (*) say, to format only part of each match.' : 'This pattern has no variables; the whole match is formatted.'),
        toggles,
        h('div', { class: 'find-format-row' }, font, size),
        h('div', { class: 'menu-label' }, 'Text colour'),
        swatches('color', textColors.slice(0, 20), 'Automatic'),
        h('div', { class: 'menu-label' }, 'Highlight'),
        swatches('highlight', highlightColors, 'No highlight'),
        h('div', { class: 'menu-label' }, 'Paragraphs'),
        style,
      ),
    );
  }

  // ---- Opening and closing -------------------------------------------------------------------

  open(): void {
    const view = this.host.tab()?.view;

    // A word or phrase that is selected is what is looked for; a pattern is left as it is.
    if (view && !view.state.selection.empty && this.mode === 'text') {
      const { from, to } = view.state.selection;
      const selected = view.state.doc.textBetween(from, to, ' ');

      if (selected && selected.length < 200 && !selected.includes('\n')) this.query.value = selected;
    }

    this.el.hidden = false;
    this.query.focus();
    this.query.select();
    this.search();
  }

  close(): void {
    if (!this.isOpen) return;

    this.el.hidden = true;
    closePopover();
    this.run(clearFind);
    this.host.focus();
  }

  /** Another document came to the front: look for the same thing in it. */
  sync(): void {
    if (this.isOpen) this.search();
  }

  /** Shows how many matches there are and which one the view is on. */
  refresh(): void {
    if (!this.isOpen) return;

    const view = this.host.tab()?.view;
    const { matches, current, query, error } = view ? findState(view.state) : { matches: [], current: -1, query: '', error: null };
    const many = matches.length >= MAX_MATCHES ? '+' : '';

    this.count.classList.toggle('bad', !!error);
    this.count.title = error ?? '';
    this.count.textContent = !query && !this.filter ? '' : error ? 'Not a valid pattern' : matches.length ? `${current + 1} of ${matches.length}${many}` : 'No matches';
    this.formatButton.disabled = !matches.length;
  }
}
