// Sections and their columns.
//
// The document is a flat list of blocks (see the note on `doc` in src/editor/schema.ts): a
// paragraph whose `sectPr` is set ends a section, and the body's last section takes the doc's
// `sectPr` attribute, or `ctx.sectPr` while that is null. `sectionRanges` turns that into each
// section's extent, properties and columns.
//
// Why not a section node around the blocks: every part of the editor that walks the blocks
// (find, outline, notes, track changes, fields, the importer and the exporter, pagination) works
// on them as children of the doc, and a section break that a person deletes or types around
// would have to be kept in step with a node boundary. With ranges, a section is just where the
// `sectPr` paragraphs say it is, the .docx is read and written as before, and the columns are
// a matter of drawing (src/columns/view.ts).
//
// `w:cols` as Word writes it: `w:num` columns, `w:space` between them (twips), `w:sep` for a
// line between them, and with `w:equalWidth="0"` a `w:col` (`w:w`, `w:space`) for each column.

import type { Node as PMNode } from 'prosemirror-model';
import { twipsToPx } from '../docx/props';
import { child, childrenNamed, parseFragment, type XmlEl } from '../docx/xml';

export interface Cols {
  count: number;
  /** Between equal columns, in twips. */
  space: number;
  equal: boolean;
  /** For columns of their own widths: each one's width and the space after it, in twips. */
  widths: { w: number; space: number }[];
  /** A line between the columns. */
  sep: boolean;
}

export const ONE_COLUMN: Cols = { count: 1, space: 720, equal: true, widths: [], sep: false };

export interface SectionRange {
  index: number;
  /** The positions of its first block and just after its last, in the doc. */
  from: number;
  to: number;
  /** Its `w:sectPr`, as source. */
  sectPr: string | null;
  cols: Cols;
  /** How it starts: nextPage, continuous, evenPage, oddPage, nextColumn. */
  type: string;
}

const on = (value: string | undefined) => value === undefined || !(value === '0' || value === 'false' || value === 'off');

function sectPrEl(source: string | null | undefined): XmlEl | null {
  return parseFragment(source)?.children.find((c) => c.name === 'w:sectPr') ?? null;
}

/** A section's columns, from its `w:sectPr`. */
export function readCols(sectPr: string | null | undefined): Cols {
  const cols = child(sectPrEl(sectPr), 'w:cols');
  if (!cols) return ONE_COLUMN;

  const num = Math.max(1, Math.min(45, Math.round(Number(cols.attrs['w:num'] ?? 1)) || 1));
  const spaceAttr = Number(cols.attrs['w:space']);
  const space = Number.isFinite(spaceAttr) && spaceAttr >= 0 ? spaceAttr : 720;
  const widths = childrenNamed(cols, 'w:col')
    .map((c) => ({ w: Number(c.attrs['w:w']) || 0, space: Number(c.attrs['w:space']) || 0 }))
    .filter((c) => c.w > 0);
  const equal = cols.attrs['w:equalWidth'] === undefined ? widths.length === 0 : on(cols.attrs['w:equalWidth']);
  const sep = cols.attrs['w:sep'] !== undefined && on(cols.attrs['w:sep']);

  if (!equal && widths.length) return { count: widths.length, space, equal: false, widths, sep };
  return { count: num, space, equal: true, widths: [], sep };
}

/** How a section starts (`w:type`). */
export function sectionType(sectPr: string | null | undefined): string {
  return child(sectPrEl(sectPr), 'w:type')?.attrs['w:val'] ?? 'nextPage';
}

/** Each column's left edge and width in CSS pixels, in a body this wide. */
export function columnBoxes(cols: Cols, bodyWidth: number): { x: number; width: number }[] {
  if (cols.count <= 1) return [{ x: 0, width: bodyWidth }];

  if (!cols.equal && cols.widths.length) {
    const total = cols.widths.reduce((sum, c, i) => sum + c.w + (i < cols.widths.length - 1 ? c.space : 0), 0);
    // The widths are the section's own; the page drawn may be another section's size.
    const scale = total > 0 ? bodyWidth / twipsToPx(total) : 1;
    let x = 0;

    return cols.widths.map((c) => {
      const box = { x, width: twipsToPx(c.w) * scale };
      x += (c.w + c.space) * (scale / 15);
      return box;
    });
  }

  const space = Math.min(twipsToPx(cols.space), bodyWidth / (cols.count * 2));
  const width = (bodyWidth - space * (cols.count - 1)) / cols.count;
  return Array.from({ length: cols.count }, (_, i) => ({ x: i * (width + space), width }));
}

/** Whether a block ends a section: a paragraph with section properties, or a wrapper around one. */
export function endingSectPr(node: PMNode): string | null {
  if (node.type.name === 'paragraph') return node.attrs.sectPr ?? null;
  if (node.type.name !== 'block_wrap') return null;

  let found: string | null = null;
  node.descendants((n) => {
    if (n.type.name === 'paragraph' && n.attrs.sectPr) found = n.attrs.sectPr;
    return n.type.name !== 'paragraph';
  });
  return found;
}

/** The document's sections, in order; the last is the body's own. */
export function sectionRanges(doc: PMNode, bodySectPr: string | null): SectionRange[] {
  const out: SectionRange[] = [];
  const add = (from: number, to: number, sectPr: string | null) =>
    out.push({ index: out.length, from, to, sectPr, cols: readCols(sectPr), type: sectionType(sectPr) });
  let from = 0;

  doc.forEach((node, offset) => {
    const sectPr = endingSectPr(node);
    if (!sectPr) return;

    add(from, offset + node.nodeSize, sectPr);
    from = offset + node.nodeSize;
  });

  add(from, doc.content.size, doc.attrs.sectPr ?? bodySectPr);
  return out;
}

/** The section a position is in. */
export function sectionAt(ranges: readonly SectionRange[], pos: number): SectionRange {
  return ranges.find((r) => pos < r.to) ?? ranges[ranges.length - 1];
}

// ---- Writing --------------------------------------------------------------------------------

/** The children of `w:sectPr` in the order the schema has them. */
const ORDER = [
  'w:headerReference', 'w:footerReference', 'w:footnotePr', 'w:endnotePr', 'w:type', 'w:pgSz', 'w:pgMar', 'w:paperSrc',
  'w:pgBorders', 'w:lnNumType', 'w:pgNumType', 'w:cols', 'w:formProt', 'w:vAlign', 'w:noEndnote', 'w:titlePg',
  'w:textDirection', 'w:bidi', 'w:rtlGutter', 'w:docGrid', 'w:printerSettings', 'w:sectPrChange',
];

/** An element of `w:sectPr` (self-closing or not), anywhere in its source. */
const elementRe = (name: string) => new RegExp(`<${name}\\b[^>]*?/>|<${name}\\b[^>]*?>[\\s\\S]*?</${name}>`);

/** `sectPr` with its `name` element replaced by `xml` (or taken out, for ''), or put in its place. */
export function putChild(sectPr: string, name: string, xml: string): string {
  let src = sectPr.trim();
  if (/^<w:sectPr\b[^>]*\/>$/.test(src)) src = `${src.slice(0, -2)}></w:sectPr>`;

  const re = elementRe(name);
  if (re.test(src)) return src.replace(re, xml);
  if (!xml) return src;

  for (const later of ORDER.slice(ORDER.indexOf(name) + 1)) {
    const at = src.search(new RegExp(`<${later}\\b`));
    if (at >= 0) return src.slice(0, at) + xml + src.slice(at);
  }

  const end = src.lastIndexOf('</w:sectPr>');
  return src.slice(0, end) + xml + src.slice(end);
}

export function colsXml(cols: Cols): string {
  if (cols.count <= 1) return `<w:cols w:space="${cols.space}"/>`;

  const sep = cols.sep ? ' w:sep="1"' : '';
  if (cols.equal || !cols.widths.length) return `<w:cols w:num="${cols.count}"${sep} w:space="${cols.space}"/>`;

  const each = cols.widths.map((c, i) => (i < cols.widths.length - 1 ? `<w:col w:w="${c.w}" w:space="${c.space}"/>` : `<w:col w:w="${c.w}"/>`));
  return `<w:cols w:num="${cols.widths.length}"${sep} w:space="${cols.space}" w:equalWidth="0">${each.join('')}</w:cols>`;
}

/** A section's properties with these columns. */
export function withCols(sectPr: string, cols: Cols): string {
  return putChild(sectPr, 'w:cols', colsXml(cols));
}

/** A section's properties with this start (`w:type`); nextPage, the default, is written as no `w:type`. */
export function withType(sectPr: string, type: string): string {
  return putChild(sectPr, 'w:type', type === 'nextPage' ? '' : `<w:type w:val="${type}"/>`);
}

/**
 * Columns of their own widths for a body this wide (twips), as Word's Left and Right presets
 * make them: the narrow one a little under half the wide one.
 */
export function presetCols(preset: 'one' | 'two' | 'three' | 'left' | 'right', bodyTwips: number, sep = false, space = 720): Cols {
  switch (preset) {
    case 'one':
      return { ...ONE_COLUMN, space };
    case 'two':
    case 'three':
      return { count: preset === 'two' ? 2 : 3, space, equal: true, widths: [], sep };
    default: {
      const narrow = Math.round((bodyTwips - space) * 0.34);
      const wide = Math.round(bodyTwips - space - narrow);
      const widths = preset === 'left' ? [{ w: narrow, space }, { w: wide, space: 0 }] : [{ w: wide, space }, { w: narrow, space: 0 }];
      return { count: 2, space, equal: false, widths, sep };
    }
  }
}
