// RIS and CSL-JSON, the formats Zotero, Mendeley, EndNote and most library catalogues export,
// and choosing the reader for a file by its name and content.

import { bibtexToSources } from './bibtex';
import type { Name, Source } from './model';

// ---- RIS --------------------------------------------------------------------------------------------------

const RIS_TYPES: Record<string, string> = {
  JOUR: 'JournalArticle', JFULL: 'JournalArticle', MGZN: 'ArticleInAPeriodical', NEWS: 'ArticleInAPeriodical',
  BOOK: 'Book', EBOOK: 'Book', EDBOOK: 'Book', CHAP: 'BookSection', ECHAP: 'BookSection',
  CONF: 'ConferenceProceedings', CPAPER: 'ConferenceProceedings', RPRT: 'Report', THES: 'Report',
  ELEC: 'InternetSite', WEB: 'InternetSite', BLOG: 'InternetSite',
};

function risName(text: string): Name {
  const [last, rest = ''] = text.split(/\s*,\s*/, 2);
  if (!text.includes(',')) return { corporate: text.trim() };
  const [first, ...middle] = rest.split(/\s+/).filter(Boolean);
  const name: Name = { last };
  if (first) name.first = first;
  if (middle.length) name.middle = middle.join(' ');
  return name;
}

export function risToSources(text: string): Source[] {
  const out: Source[] = [];
  let tags: [string, string][] = [];

  const finish = () => {
    if (tags.length) out.push(risSource(tags));
    tags = [];
  };

  for (const line of text.split(/\r?\n/)) {
    const m = /^([A-Z][A-Z0-9])  -\s?(.*)$/.exec(line);
    if (!m) {
      // A value carried on to the next line.
      if (tags.length && line.trim()) tags[tags.length - 1][1] += ` ${line.trim()}`;
      continue;
    }
    if (m[1] === 'TY') finish();
    if (m[1] === 'ER') finish();
    else tags.push([m[1], m[2].trim()]);
  }
  finish();
  return out;
}

function risSource(tags: [string, string][]): Source {
  const all = (...names: string[]) => tags.filter(([t]) => names.includes(t)).map(([, v]) => v).filter(Boolean);
  const one = (...names: string[]) => all(...names)[0] ?? '';
  const ty = one('TY');
  const type = RIS_TYPES[ty] ?? 'Misc';
  const fields: Record<string, string> = {};
  const set = (word: string, value: string) => {
    if (value) fields[word] = value;
  };

  const date = one('PY', 'Y1', 'DA');
  const parts = date.split(/[/-]/);
  set('Title', one('TI', 'T1', 'CT'));
  set('Year', /\d{4}/.exec(parts[0] ?? '')?.[0] ?? '');
  set('Month', parts[1] ? String(Number(parts[1]) || '') : '');
  set('Day', parts[2] ? String(Number(parts[2]) || '') : '');

  const secondary = one('T2', 'BT');
  if (type === 'JournalArticle' || type === 'ArticleInAPeriodical') set('JournalName', one('JO', 'JF', 'JA', 'J2') || secondary);
  if (type === 'BookSection') set('BookTitle', secondary);
  if (type === 'ConferenceProceedings') set('ConferenceName', secondary || one('C3'));
  if (type === 'InternetSite') set('InternetSiteTitle', secondary);
  if (ty === 'THES') {
    set('ThesisType', one('M3') || 'Thesis');
    set('Institution', one('PB'));
  } else set('Publisher', one('PB'));

  set('Volume', one('VL'));
  set('Issue', one('IS'));
  const sp = one('SP');
  const ep = one('EP');
  set('Pages', sp && ep ? `${sp}–${ep}` : sp);
  set('City', one('CY'));
  set('Edition', one('ET'));
  set('DOI', one('DO'));
  set('URL', one('UR', 'L2'));
  if (type === 'Report') set('StandardNumber', one('SN', 'M1'));

  const people: Record<string, Name[]> = {};
  const authors = all('AU', 'A1');
  const editors = all('A2', 'ED');
  if (authors.length) people.Author = authors.map(risName);
  if (editors.length && type !== 'JournalArticle') people.Editor = editors.map(risName);

  return { tag: one('ID'), type, fields, people, extra: [] };
}

// ---- CSL-JSON ----------------------------------------------------------------------------------------------

const CSL_TYPES: Record<string, string> = {
  'article-journal': 'JournalArticle', 'article-magazine': 'ArticleInAPeriodical', 'article-newspaper': 'ArticleInAPeriodical',
  book: 'Book', chapter: 'BookSection', 'paper-conference': 'ConferenceProceedings', report: 'Report', thesis: 'Report',
  webpage: 'InternetSite', 'post-weblog': 'InternetSite', post: 'InternetSite',
};

interface CslName {
  family?: string;
  given?: string;
  literal?: string;
  'non-dropping-particle'?: string;
}

type CslDate = { 'date-parts'?: (number | string)[][]; raw?: string; literal?: string } | undefined;

function cslNames(list: unknown): Name[] {
  if (!Array.isArray(list)) return [];
  return (list as CslName[]).map((n): Name => {
    if (n.literal || !n.family) return { corporate: (n.literal ?? n.given ?? '').trim() };
    const [first, ...middle] = (n.given ?? '').split(/\s+/).filter(Boolean);
    const name: Name = { last: [n['non-dropping-particle'], n.family].filter(Boolean).join(' ') };
    if (first) name.first = first;
    if (middle.length) name.middle = middle.join(' ');
    return name;
  });
}

function cslDate(date: CslDate): string[] {
  const parts = date?.['date-parts']?.[0];
  if (parts?.length) return parts.map(String);
  const m = /(\d{4})(?:-(\d{1,2}))?(?:-(\d{1,2}))?/.exec(date?.raw ?? date?.literal ?? '');
  return m ? [m[1], m[2], m[3]].filter(Boolean).map((v) => String(Number(v))) : [];
}

export function cslToSource(item: Record<string, unknown>): Source {
  const str = (key: string) => (typeof item[key] === 'string' || typeof item[key] === 'number' ? String(item[key]).trim() : '');
  const type = CSL_TYPES[str('type')] ?? 'Misc';
  const fields: Record<string, string> = {};
  const set = (word: string, value: string) => {
    if (value) fields[word] = value;
  };

  const [year, month, day] = cslDate(item.issued as CslDate);
  set('Title', str('title'));
  set('ShortTitle', str('title-short') || str('shortTitle'));
  set('Year', year ?? '');
  set('Month', month ?? '');
  set('Day', day ?? '');

  const container = str('container-title');
  if (type === 'JournalArticle' || type === 'ArticleInAPeriodical') set('JournalName', container);
  if (type === 'BookSection') set('BookTitle', container);
  if (type === 'ConferenceProceedings') set('ConferenceName', container || str('event') || str('event-title'));
  if (type === 'InternetSite') set('InternetSiteTitle', container);

  if (str('type') === 'thesis') {
    set('ThesisType', str('genre') || 'Thesis');
    set('Institution', str('publisher'));
  } else set('Publisher', str('publisher'));
  if (str('type') === 'report') {
    set('ReportType', str('genre'));
    set('StandardNumber', str('number'));
  }

  set('Volume', str('volume'));
  set('Issue', str('issue'));
  set('Pages', str('page').replace(/\s*[-–]+\s*/g, '–'));
  set('Edition', str('edition'));
  set('City', str('publisher-place'));
  set('DOI', str('DOI'));
  set('URL', str('URL'));

  const [ay, am, ad] = cslDate(item.accessed as CslDate);
  if (type === 'InternetSite') {
    set('YearAccessed', ay ?? '');
    set('MonthAccessed', am ?? '');
    set('DayAccessed', ad ?? '');
  }

  const people: Record<string, Name[]> = {};
  const authors = cslNames(item.author);
  const editors = cslNames(item.editor);
  if (authors.length) people.Author = authors;
  if (editors.length) people.Editor = editors;

  return { tag: str('citation-key') || '', type, fields, people, extra: [] };
}

export function cslJsonToSources(text: string): Source[] {
  const data = JSON.parse(text) as unknown;
  const list = Array.isArray(data) ? data : Array.isArray((data as { items?: unknown[] })?.items) ? (data as { items: unknown[] }).items : [data];
  return list.filter((x): x is Record<string, unknown> => !!x && typeof x === 'object').map(cslToSource);
}

// ---- Any file ----------------------------------------------------------------------------------------------

/** Sources from a .bib, .ris or CSL-JSON file, chosen by the name and, failing that, the content. */
export function sourcesFromFile(name: string, text: string): Source[] {
  const ext = /\.([a-z]+)$/i.exec(name)?.[1].toLowerCase() ?? '';
  const body = text.replace(/^﻿/, '');

  if (ext === 'bib' || ext === 'bibtex') return bibtexToSources(body);
  if (ext === 'ris') return risToSources(body);
  if (ext === 'json' || ext === 'csljson') return cslJsonToSources(body);

  const start = body.trimStart();
  if (start.startsWith('[') || start.startsWith('{')) return cslJsonToSources(body);
  if (/^TY {2}- /m.test(body)) return risToSources(body);
  return bibtexToSources(body);
}
