// Footnotes and endnotes on screen.
//
// The plugin numbers every reference in the text (a node decoration gives it `data-n`, which the
// stylesheet shows) and adds the notes areas as widgets: one after the last block holding the
// footnotes, which the continuous view shows and Pages view hides (there they are drawn at the
// foot of each page by furniture.ts, from `footBoxes`), and the endnotes, after the last block or
// after each section's last paragraph when `w:endnotePr` puts them at the end of sections.
//
// A note is shown as its content, drawn once and kept; a click in it opens it in an editor of its
// own, in place, as headers and footers are. Leaving that editor (a click elsewhere, Escape) puts
// the content back into the store, which marks the document changed. A click on a reference jumps
// to its note; a click on a note's number jumps back to the reference.

import { keymap } from 'prosemirror-keymap';
import { DOMSerializer, type Node as PMNode } from 'prosemirror-model';
import { type EditorState, Plugin, PluginKey, TextSelection } from 'prosemirror-state';
import { Decoration, DecorationSet, type EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { schema } from '../editor/schema';
import '../styles/notes.css';
import { insertNote, splitDuplicateRefs } from './commands';
import { type NoteKind, type NoteRef, type NoteStore, notesOf, numberRefs, refOf, refsIn, referencedIds } from './model';

const N = schema.nodes;

/** Opens a note's content in an editor of its own (createEditor, handed in to keep imports one way). */
export type MakeEditor = (options: { ctx: DocContext; doc: PMNode; mount: HTMLElement }) => EditorView;

interface NotesState {
  refs: NoteRef[];
  numbers: string[];
  /** `${kind}:${id}` → the number shown. */
  byNote: Map<string, string>;
  /** For numbering that starts again on each page: the page each reference was laid out on. */
  pages: ReadonlyMap<number, number>;
}

export const notesKey = new PluginKey<NotesState>('notes');

const noteKey = (kind: NoteKind, id: string) => `${kind}:${id}`;

function compute(ctx: DocContext, doc: PMNode, pages: ReadonlyMap<number, number>): NotesState {
  const store = notesOf(ctx);
  const refs = refsIn(doc);
  const sectPrs: (string | null)[] = [];

  doc.forEach((node) => {
    if (node.type === N.paragraph && node.attrs.sectPr) sectPrs.push(node.attrs.sectPr);
  });
  sectPrs.push(doc.attrs.sectPr ?? ctx.sectPr);

  const numbers = numberRefs(refs, (kind, section) => store.sectionProps(kind, sectPrs[section] ?? null), (ref) => pages.get(ref.pos) ?? 0);
  const byNote = new Map<string, string>();
  refs.forEach((ref, i) => byNote.set(noteKey(ref.kind, ref.id), numbers[i]));

  return { refs, numbers, byNote, pages };
}

const views = new WeakMap<EditorView, NotesView>();

/** The notes shown with a document's editor, for furniture.ts and pages.ts. */
export function notesViewOf(view: EditorView): NotesView | null {
  return views.get(view) ?? null;
}

export function notesPlugin(ctx: DocContext, makeEditor: MakeEditor): Plugin<NotesState> {
  // Made the first time it is needed: the notes areas are drawn before the plugin's view exists.
  const ensure = (view: EditorView): NotesView => {
    let nv = views.get(view);
    if (!nv) views.set(view, (nv = new NotesView(view, ctx, makeEditor)));
    return nv;
  };

  return new Plugin<NotesState>({
    key: notesKey,
    state: {
      init: (_config, state) => {
        const store = notesOf(ctx);
        for (const kind of ['footnote', 'endnote'] as const) store.loadedRefs[kind] ??= referencedIds(state.doc, kind);
        return compute(ctx, state.doc, new Map());
      },
      apply: (tr, old, _oldState, state) => {
        const pages = tr.getMeta(notesKey) as ReadonlyMap<number, number> | undefined;
        if (!tr.docChanged && !pages) return old;
        return compute(ctx, state.doc, pages ?? (tr.docChanged ? new Map() : old.pages));
      },
    },
    view: (view) => {
      const nv = ensure(view);
      queueMicrotask(() => nv.update());
      return { update: () => nv.update(), destroy: () => nv.destroy() };
    },
    appendTransaction: (trs, _old, state) => (trs.some((tr) => tr.docChanged) ? splitDuplicateRefs(state, ctx) : null),
    props: {
      decorations(state) {
        return decorationsFor(ctx, state, ensure);
      },
      handleClickOn(view, _pos, node) {
        const ref = refOf(node);
        if (!ref) return false;

        notesViewOf(view)?.goToNote(ref.kind, ref.id);
        return true;
      },
    },
  });
}

function decorationsFor(ctx: DocContext, state: EditorState, ensure: (view: EditorView) => NotesView): DecorationSet {
  const s = notesKey.getState(state);
  if (!s?.refs.length) return DecorationSet.empty;

  const decos: Decoration[] = s.refs.map((ref, i) => Decoration.node(ref.pos, ref.pos + 1, { 'data-n': s.numbers[i], class: 'note-ref' }));
  const end = state.doc.content.size;
  const widget = (pos: number, group: string, side: number) =>
    Decoration.widget(pos, (view) => ensure(view).area(group), { key: `notes-${group}`, side, stopEvent: () => true, ignoreSelection: true });

  if (s.refs.some((r) => r.kind === 'footnote')) decos.push(widget(end, 'foot', 1));

  const store = notesOf(ctx);
  const endnotes = s.refs.filter((r) => r.kind === 'endnote');

  if (endnotes.length) {
    if (store.props.endnote.pos === 'sectEnd') {
      const ends: number[] = [];
      state.doc.forEach((node, pos) => {
        if (node.type === N.paragraph && node.attrs.sectPr) ends.push(pos + node.nodeSize);
      });
      ends.push(end);

      for (const section of new Set(endnotes.map((r) => r.section))) {
        decos.push(widget(ends[Math.min(section, ends.length - 1)], `end-${section}`, 2));
      }
    } else {
      decos.push(widget(end, 'end', 2));
    }
  }

  return DecorationSet.create(state.doc, decos);
}

interface Editing {
  view: EditorView;
  kind: NoteKind;
  id: string;
  leave: (event: Event) => void;
}

/** What one editor shows of its notes, and the note being edited. */
export class NotesView {
  private readonly store: NoteStore;
  private readonly areas = new Map<string, HTMLElement>();
  /** Notes drawn already, by note and the store's version. */
  private readonly drawn = new Map<string, { version: number; el: HTMLElement }>();
  private readonly measure = document.createElement('div');
  private editing: Editing | null = null;
  private shown = '';
  private readonly unlisten: () => void;
  /** Called when the notes look different (one edited, made, opened or left): the pages need laying out again. */
  onLayout: () => void = () => {};
  /** A note just made, opened once it has been laid out. */
  private pending: { kind: NoteKind; id: string } | null = null;

  constructor(
    private readonly main: EditorView,
    private readonly ctx: DocContext,
    private readonly makeEditor: MakeEditor,
  ) {
    this.store = notesOf(ctx);
    this.measure.className = 'notes-measure';
    this.unlisten = this.store.onChange(() => {
      this.shown = '';
      queueMicrotask(() => this.update());
    });
  }

  private get state(): NotesState | undefined {
    return notesKey.getState(this.main.state);
  }

  /** The element of a notes area: 'foot', 'end' or `end-${section}`. */
  area(group: string): HTMLElement {
    let el = this.areas.get(group);

    if (!el) {
      el = document.createElement('div');
      el.className = group === 'foot' ? 'notes-area notes-foot' : 'notes-area notes-end';
      el.contentEditable = 'false';
      el.dataset.group = group;
      this.listen(el);
      this.areas.set(group, el);
      this.shown = '';
    }

    return el;
  }

  update(): void {
    if (this.main.isDestroyed) return;

    const s = this.state;
    if (!s) return;

    const key = `${this.store.version}|${s.numbers.join(',')}|${s.refs.map((r) => r.kind[0] + r.id + ':' + r.section).join(',')}|${[...this.areas.keys()].join(',')}`;
    if (key === this.shown) return;
    this.shown = key;

    for (const [group, el] of this.areas) {
      if (this.editing && el.contains(this.editing.view.dom)) continue;

      const refs = s.refs.filter((r) => (group === 'foot' ? r.kind === 'footnote' : r.kind === 'endnote' && (group === 'end' || group === `end-${r.section}`)));
      const boxes = refs.map((r) => this.box(r.kind, r.id));
      const title = document.createElement('div');

      title.className = 'notes-title';
      title.textContent = group === 'foot' ? 'Footnotes' : 'Endnotes';
      el.replaceChildren(...(boxes.length ? [title, ...boxes] : []));
    }
  }

  /** A note as shown: its number, which leads back to the reference, and its content. */
  box(kind: NoteKind, id: string): HTMLElement {
    const note = this.store.get(kind, id);
    const number = this.state?.byNote.get(noteKey(kind, id)) ?? '';
    const box = document.createElement('div');

    box.className = 'note';
    box.dataset.kind = kind;
    box.dataset.id = id;

    const num = document.createElement('span');
    num.className = 'note-num';
    num.textContent = number;
    num.title = 'Go to the reference in the text';
    box.append(num);

    if (!note) {
      const missing = document.createElement('div');
      missing.className = 'note-body note-missing';
      missing.textContent = 'This note is missing from the file.';
      box.append(missing);
      return box;
    }

    const k = noteKey(kind, id);
    let drawn = this.drawn.get(k);

    if (!drawn || drawn.version !== this.store.version) {
      const el = document.createElement('div');
      el.className = 'ProseMirror note-body';
      el.title = 'Click to edit the note';
      el.append(DOMSerializer.fromSchema(schema).serializeFragment(this.store.docOf(note).content));
      drawn = { version: this.store.version, el };
      this.drawn.set(k, drawn);
    }

    box.append(drawn.el.cloneNode(true));
    return box;
  }

  private listen(el: HTMLElement): void {
    // The desk takes a press outside the text to put the cursor back into it; not this one.
    el.addEventListener('mousedown', (event) => {
      const target = event.target as HTMLElement;
      const box = target.closest<HTMLElement>('.note');
      if (!box) return;

      event.stopPropagation();
      if (this.editing && box.contains(this.editing.view.dom)) return;

      event.preventDefault();
      const kind = box.dataset.kind as NoteKind;
      const id = box.dataset.id ?? '';

      if (target.closest('.note-num')) this.goToRef(kind, id);
      else this.edit(box, { left: event.clientX, top: event.clientY });
    });
  }

  /** Footnote boxes for the foot of one page (Pages view), wired up to be edited there. */
  footBoxes(ids: readonly string[]): HTMLElement[] {
    return ids.map((id) => {
      const editing = this.editing;
      if (editing?.kind === 'footnote' && editing.id === id) {
        // The note being edited moves into the new area; moving it takes its focus away.
        if (editing.view.hasFocus()) queueMicrotask(() => this.editing === editing && editing.view.focus());
        return editing.view.dom.closest<HTMLElement>('.note') ?? this.box('footnote', id);
      }
      return this.box('footnote', id);
    });
  }

  /** Wires up a footnote area drawn elsewhere (furniture.ts). */
  wire(el: HTMLElement): void {
    this.listen(el);
  }

  /**
   * The footnotes the text refers to, in order: where each reference is laid out (from the
   * editor's top, without page gaps) and how tall its note is at `width`. For pages.ts.
   */
  footnotes(toY: (clientY: number) => number, width: number, zoom: number): { y: number; height: number; id: string; pos: number }[] {
    const s = this.state;
    if (!s) return [];

    const refs = s.refs.filter((r) => r.kind === 'footnote');
    if (!refs.length) return [];

    const host = this.main.dom.parentElement ?? document.body;
    this.measure.style.width = `${width}px`;
    if (this.measure.parentElement !== host) host.append(this.measure);

    const boxes = refs.map((r) => this.box('footnote', r.id));
    this.measure.replaceChildren(...boxes);

    const out = refs.map((r, i) => {
      const dom = this.main.nodeDOM(r.pos);
      const rect = dom instanceof HTMLElement ? dom.getBoundingClientRect() : null;
      return { y: rect ? toY(rect.top) : 0, height: boxes[i].getBoundingClientRect().height / zoom, id: r.id, pos: r.pos };
    });

    this.measure.replaceChildren();
    return out;
  }

  /** After a layout: the page each footnote reference is on, for numbering by page. */
  pagesMeasured(pageOf: ReadonlyMap<number, number>): void {
    const s = this.state;
    if (!s) return;

    const store = this.store;
    const byPage = (['footnote', 'endnote'] as const).some((kind) => store.props[kind].restart === 'eachPage' || /w:numRestart w:val="eachPage"/.test(this.ctx.sectPr ?? ''));
    if (!byPage) return;

    const same = s.refs.every((r) => (s.pages.get(r.pos) ?? 0) === (pageOf.get(r.pos) ?? 0));
    if (!same) this.main.dispatch(this.main.state.tr.setMeta(notesKey, pageOf).setMeta('addToHistory', false));
  }

  /** Clears what the last layout put on the notes areas (pages.ts pushes notes onto the next page with a margin). */
  resetLayout(): void {
    for (const el of this.areas.values()) for (const box of el.querySelectorAll<HTMLElement>('.note, .notes-title')) box.style.marginTop = '';
  }

  // ---- Moving between reference and note ------------------------------------------------------

  goToNote(kind: NoteKind, id: string): void {
    const root = this.main.dom.closest('.page') ?? document;
    // The one shown: in Pages view the footnotes after the text are hidden, the page's are drawn.
    const boxes = [...root.querySelectorAll<HTMLElement>(`.note[data-kind="${kind}"][data-id="${CSS.escape(id)}"]`)];
    const box = boxes.find((b) => b.getClientRects().length > 0) ?? boxes[0];

    if (!box) return;
    box.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    this.edit(box, null);
  }

  goToRef(kind: NoteKind, id: string): void {
    this.finish();

    const ref = this.state?.refs.find((r) => r.kind === kind && r.id === id);
    if (!ref) return;

    const view = this.main;
    view.dispatch(view.state.tr.setSelection(TextSelection.create(view.state.doc, ref.pos + 1)).scrollIntoView());
    view.focus();
  }

  // ---- Editing ------------------------------------------------------------------------------

  private edit(box: HTMLElement, at: { left: number; top: number } | null): void {
    const kind = box.dataset.kind as NoteKind;
    const id = box.dataset.id ?? '';
    const note = this.store.get(kind, id);
    if (!note) return;

    this.finish();

    const body = box.querySelector('.note-body');
    const mount = document.createElement('div');
    mount.className = 'note-editing';
    if (body) body.replaceWith(mount);
    else box.append(mount);

    const view = this.makeEditor({ ctx: this.ctx, doc: this.store.docOf(note), mount });
    view.dom.classList.add('note-body');

    const leave = (event: Event) => {
      const inside = mount.contains(event.target as Node);
      if (event instanceof KeyboardEvent ? event.key === 'Escape' && inside : !inside) this.finish();
    };

    document.addEventListener('mousedown', leave, true);
    document.addEventListener('keydown', leave, true);
    this.editing = { view, kind, id, leave };

    const hit = at ? view.posAtCoords(at) : null;
    const pos = hit?.pos ?? view.state.doc.content.size - 1;
    view.dispatch(view.state.tr.setSelection(TextSelection.near(view.state.doc.resolve(pos), hit ? 1 : -1)));
    view.focus();
  }

  /** Leaves the note being edited, putting its content back into the store if it changed. */
  finish(): void {
    const editing = this.editing;
    if (!editing) return;

    this.editing = null;
    document.removeEventListener('mousedown', editing.leave, true);
    document.removeEventListener('keydown', editing.leave, true);

    const doc = editing.view.state.doc;
    const note = this.store.get(editing.kind, editing.id);
    editing.view.destroy();

    this.shown = '';
    if (note && !doc.eq(this.store.docOf(note))) this.store.setDoc(note, doc);
    else this.update();
    this.onLayout();
  }

  /** Makes a note at the cursor and opens it to be written. */
  insert(kind: NoteKind): void {
    const { tr, note } = insertNote(this.main.state, this.ctx, kind);
    this.main.dispatch(tr);
    this.update();

    // In Pages view a footnote is drawn at the foot of its page once the pages are laid out.
    if (kind === 'footnote' && this.main.dom.closest('.page')?.classList.contains('paged')) {
      this.pending = { kind, id: note.id };
      this.onLayout();
    } else {
      this.goToNote(kind, note.id);
    }
  }

  /** The pages were laid out and drawn: a note just made can be opened now. */
  laidOut(): void {
    const pending = this.pending;
    this.pending = null;
    if (pending) requestAnimationFrame(() => this.goToNote(pending.kind, pending.id));
  }

  destroy(): void {
    this.finish();
    this.unlisten();
    this.measure.remove();
  }
}

/** The notes plugin and its keys, for the document's own editor. */
export function notesPlugins(ctx: DocContext, makeEditor: MakeEditor): Plugin[] {
  return [notesPlugin(ctx, makeEditor), keymap(noteKeys())];
}

/** Ctrl+Alt+F and Ctrl+Alt+D, as in Word. */
export function noteKeys(): Record<string, (state: EditorState, dispatch?: unknown, view?: EditorView) => boolean> {
  const make = (kind: NoteKind) => (_state: EditorState, dispatch?: unknown, view?: EditorView) => {
    const nv = view ? notesViewOf(view) : null;
    // Not in a note, a header or a footer.
    if (!nv || view?.dom.closest('.note, .hf')) return false;
    if (dispatch) nv.insert(kind);
    return true;
  };

  return { 'Mod-Alt-f': make('footnote'), 'Mod-Alt-d': make('endnote') };
}
