// The References menu: captions, cross-references, the table of contents, and updating fields.

import type { Command } from 'prosemirror-state';
import type { EditorView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import {
  CAPTION_LABELS, type RefTarget, type RefWhat, captionTargets, findToc, headingTargets, insertCaption, insertCrossReference, insertToc,
} from '../fields/insert';
import { pageMapper, runFieldUpdate } from '../fields/plugin';
import { closePopover, h, popover } from './dom';
import { citationMenuItems } from '../cite/ui';

export interface ReferencesHost {
  tab(): { ctx: DocContext; view: EditorView } | null;
  run(command: Command): void;
  focus(): void;
}

export const REFERENCES_ICON =
  '<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round">' +
  '<path d="M3 2.5h7l3 3v8H3z"/><path d="M5.5 7h5M5.5 9.5h5M5.5 12h3"/><path d="M10 2.5v3h3"/></svg>';

/** A dialog with a form in it; resolves with true for OK and false for Cancel or Escape. */
export function formDialog(title: string, body: HTMLElement, okLabel: string): Promise<boolean> {
  return new Promise((resolve) => {
    const done = (ok: boolean) => {
      document.removeEventListener('keydown', onKey, true);
      backdrop.remove();
      resolve(ok);
    };

    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        done(false);
      } else if (event.key === 'Enter' && !(event.target instanceof HTMLSelectElement && event.target.size > 1)) {
        event.preventDefault();
        done(true);
      }
    };

    const backdrop = h(
      'div',
      { class: 'dialog-backdrop' },
      h(
        'div',
        { class: 'dialog field-dialog', role: 'dialog' },
        h('h2', null, title),
        body,
        h(
          'div',
          { class: 'buttons' },
          h('button', { class: 'button', onclick: () => done(false) }, 'Cancel'),
          h('button', { class: 'button primary', onclick: () => done(true) }, okLabel),
        ),
      ),
    );

    closePopover();
    document.addEventListener('keydown', onKey, true);
    document.body.append(backdrop);
    body.querySelector<HTMLElement>('input, select')?.focus();
  });
}

const row = (label: string, control: HTMLElement) => h('label', { class: 'field-row' }, h('span', null, label), control);

function option(value: string, label: string): HTMLOptionElement {
  return h('option', { value }, label);
}

/** The caption labels in a document, Word's three first. */
function labelsIn(view: EditorView): string[] {
  const found = captionTargets(view.state.doc).map((target) => target.label);
  return [...new Set([...CAPTION_LABELS, ...found])];
}

async function captionDialog(host: ReferencesHost): Promise<void> {
  const tab = host.tab();
  if (!tab) return;

  const labels = labelsIn(tab.view);
  const list = h('datalist', { id: 'caption-labels' }, ...labels.map((label) => option(label, label)));
  const label = h('input', { class: 'tool-input', list: 'caption-labels', value: 'Figure' });
  const text = h('input', { class: 'tool-input' });
  const where = h('select', { class: 'tool-select' }, option('below', 'Below the selected item'), option('above', 'Above the selected item'));
  const body = h('div', null, row('Label', label), list, row('Caption', text), row('Position', where));

  if (!(await formDialog('Insert caption', body, 'Insert'))) return host.focus();
  host.run(insertCaption(tab.ctx, label.value, text.value, where.value === 'above'));
}

async function crossReferenceDialog(host: ReferencesHost): Promise<void> {
  const tab = host.tab();
  if (!tab) return;

  const { view, ctx } = tab;
  const captions = captionTargets(view.state.doc);
  const headings = headingTargets(view.state.doc, ctx);
  const labels = labelsIn(view);
  const type = h('select', { class: 'tool-select' }, ...labels.map((label) => option(`label:${label}`, label)), option('heading', 'Heading'));
  const what = h('select', { class: 'tool-select' });
  const items = h('select', { class: 'field-list', size: 8 });
  let targets: RefTarget[] = [];

  const fill = () => {
    const isHeading = type.value === 'heading';
    const label = type.value.slice('label:'.length);

    what.replaceChildren(
      ...(isHeading
        ? [option('text', 'Heading text'), option('page', 'Page number')]
        : [option('labelNumber', 'Label and number'), option('number', 'Number only'), option('text', 'Entire caption'), option('page', 'Page number')]),
    );

    targets = isHeading ? headings : captions.filter((caption) => caption.label.toLowerCase() === label.toLowerCase());
    items.replaceChildren(
      ...targets.map((target, i) => option(String(i), target.kind === 'heading' ? `${' '.repeat(target.level)}${target.text}` : target.text)),
    );
    if (targets.length) items.selectedIndex = 0;
  };

  type.addEventListener('change', fill);
  items.addEventListener('dblclick', () => (document.querySelector('.field-dialog .button.primary') as HTMLButtonElement | null)?.click());

  // The first kind there is something of.
  const firstLabel = labels.find((label) => captions.some((caption) => caption.label.toLowerCase() === label.toLowerCase()));
  type.value = firstLabel ? `label:${firstLabel}` : 'heading';
  fill();

  const body = h('div', null, row('Reference type', type), row('Insert reference to', what), row('For which item', items));
  if (!(await formDialog('Cross-reference', body, 'Insert'))) return host.focus();

  const target = targets[items.selectedIndex];
  if (!target) return host.focus();

  host.run(insertCrossReference(ctx, target, what.value as RefWhat, what.value === 'page' ? pageMapper(view, ctx) : null));
}

/** Opens the References menu under its toolbar button. */
export function referencesMenu(anchor: HTMLElement, host: ReferencesHost): void {
  const tab = host.tab();
  if (!tab) return;

  const item = (label: string, action: () => void) =>
    h(
      'button',
      {
        class: 'menu-item',
        onclick: () => {
          closePopover();
          action();
        },
      },
      label,
    );

  const hasToc = !!findToc(tab.view.state.doc);
  const content = h(
    'div',
    null,
    item('Insert caption…', () => void captionDialog(host)),
    item('Cross-reference…', () => void crossReferenceDialog(host)),
    item(hasToc ? 'Update table of contents' : 'Insert table of contents', () => host.run(insertToc(tab.ctx, pageMapper(tab.view, tab.ctx)))),
    h('div', { class: 'menu-sep' }),
    ...citationMenuItems(host, item),
    h('div', { class: 'menu-sep' }),
    item('Update fields (F9)', () => {
      runFieldUpdate(tab.view, tab.ctx, false);
      host.focus();
    }),
    item('Update all fields (Shift+F9)', () => {
      runFieldUpdate(tab.view, tab.ctx, true);
      host.focus();
    }),
  );

  popover(anchor, content);
}
