// Recovery copies and AutoSave. While a document has unsaved changes a copy of it is written to
// the recovery folder (electron/recovery.cjs) every minute or so, and a few seconds after typing
// stops; a clean save or close takes the copy away. On start, copies an earlier run left behind
// are offered back. AutoSave, when switched on, saves a document that has a file of its own to
// that file once typing stops.
//
// What to do is worked out by the plain functions at the top, so that it can be tested without a
// window; the class below only keeps the timers and talks to the main process.

import type { RecoveryEntry } from '../desktop';

export type RecoveryChoice = 'restore' | 'original' | 'discard' | 'later';

/** Seconds between recovery copies while changes keep coming, unless set otherwise. */
export const DEFAULT_INTERVAL = 60;
/** Seconds after the last change before a copy is written, or AutoSave saves. */
export const IDLE_DELAY = 4;

/** The interval setting as stored: whole seconds, at least 10, or the default. */
export function intervalFrom(stored: string | null): number {
  const n = Math.round(Number(stored));
  return Number.isFinite(n) && n >= 10 ? Math.min(n, 3600) : DEFAULT_INTERVAL;
}

/** Whether a document needs a new recovery copy: it has unsaved changes the last copy has not. */
export function needsCopy(doc: { dirty: boolean; changes: number; copied: number }): boolean {
  return doc.dirty && doc.changes !== doc.copied;
}

/** Whether AutoSave should save a document now. */
export function needsAutoSave(on: boolean, doc: { dirty: boolean; path: string | null }): boolean {
  return on && doc.dirty && doc.path !== null;
}

/**
 * The copies to offer, newest first, one per document: of two copies of the same file only the
 * newer is offered, and the older goes in `stale` to be thrown away.
 */
export function recoveryPlan(entries: RecoveryEntry[]): { offer: RecoveryEntry[]; stale: RecoveryEntry[] } {
  const sorted = [...entries].sort((a, b) => b.time - a.time);
  const seen = new Set<string>();
  const offer: RecoveryEntry[] = [];
  const stale: RecoveryEntry[] = [];

  for (const entry of sorted) {
    const id = entry.path ? entry.path.toLowerCase() : `key:${entry.key}`;

    if (seen.has(id)) stale.push(entry);
    else {
      seen.add(id);
      offer.push(entry);
    }
  }

  return { offer, stale };
}

/** The buttons for one copy: "Open original" only for a document that has a file. */
export function choicesFor(entry: RecoveryEntry): { label: string; value: RecoveryChoice; primary?: boolean }[] {
  return [
    { label: 'Discard', value: 'discard' },
    ...(entry.path ? [{ label: 'Open original', value: 'original' as const }] : []),
    { label: 'Restore', value: 'restore', primary: true },
  ];
}

export interface RecoveryOutcome {
  /** What to open: the copy, the file as it is on disk, or nothing. */
  open: 'copy' | 'original' | null;
  /** The copy stays (until the restored document is saved or closed), or goes now. */
  keepCopy: boolean;
  /** The opened document counts as having unsaved changes. */
  modified: boolean;
}

export function outcomeOf(choice: RecoveryChoice): RecoveryOutcome {
  switch (choice) {
    case 'restore':
      return { open: 'copy', keepCopy: true, modified: true };
    case 'original':
      return { open: 'original', keepCopy: false, modified: false };
    case 'discard':
      return { open: null, keepCopy: false, modified: false };
    case 'later':
      return { open: null, keepCopy: true, modified: false };
  }
}

/** The question asked about one copy. */
export function recoveryMessage(entry: RecoveryEntry, now = Date.now()): { title: string; message: string } {
  const minutes = Math.max(0, Math.round((now - entry.time) / 60_000));
  const when =
    minutes < 1 ? 'less than a minute ago' : minutes < 60 ? `${minutes} minute${minutes === 1 ? '' : 's'} ago` : new Date(entry.time).toLocaleString('en-GB', { dateStyle: 'medium', timeStyle: 'short' });

  return {
    title: `Recover “${entry.name}”?`,
    message:
      `Text Studio closed without saving the latest changes to this document. A recovery copy was kept ${when}. ` +
      (entry.path ? `Restore it to go on from there (saving writes to ${entry.path}), open the file as it was last saved, or discard the copy.` : 'Restore it to go on from there, or discard the copy.'),
  };
}

// ---- Keeping the copies -------------------------------------------------------------------------

/** One open document, as far as recovery and AutoSave need to know it. */
export interface KeptDoc {
  readonly dirty: boolean;
  readonly path: string | null;
  readonly name: string;
}

export interface RecoveryHost<T extends KeptDoc> {
  docs(): T[];
  /** The document as a .docx, as it would be saved. */
  bytes(doc: T): Uint8Array;
  /** AutoSave: saves a document to its own file, quietly. */
  save(doc: T): Promise<boolean>;
  write?(key: string, info: { path: string | null; name: string }, bytes: Uint8Array): Promise<boolean>;
  remove?(key: string): Promise<void>;
}

let counter = 0;
const newKey = () => `${Date.now().toString(36)}-${(++counter).toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

export class RecoveryKeeper<T extends KeptDoc> {
  private readonly keys = new WeakMap<T, string>();
  private readonly changes = new WeakMap<T, number>();
  private readonly copied = new WeakMap<T, number>();
  /** Documents that have a copy on disk now. */
  private readonly held = new Set<T>();
  private idleTimer: ReturnType<typeof setTimeout> | undefined;
  private intervalTimer: ReturnType<typeof setInterval> | undefined;
  private writing = false;

  constructor(
    private readonly host: RecoveryHost<T>,
    interval: number,
    public autoSave: boolean,
  ) {
    this.setInterval(interval);
  }

  setInterval(seconds: number): void {
    clearInterval(this.intervalTimer);
    this.intervalTimer = setInterval(() => void this.flush(), seconds * 1000);
  }

  keyOf(doc: T): string {
    let key = this.keys.get(doc);
    if (!key) this.keys.set(doc, (key = newKey()));
    return key;
  }

  /** A restored document goes on under its old copy's key, so the copy stays until it is saved. */
  adopt(doc: T, key: string): void {
    this.keys.set(doc, key);
    this.held.add(doc);
  }

  /** The document changed. */
  touched(doc: T): void {
    this.changes.set(doc, (this.changes.get(doc) ?? 0) + 1);
    clearTimeout(this.idleTimer);
    this.idleTimer = setTimeout(() => void this.idle(), IDLE_DELAY * 1000);
  }

  /** Stops the timers. */
  stop(): void {
    clearTimeout(this.idleTimer);
    clearInterval(this.intervalTimer);
  }

  /** The document was saved, or closed: its copy is no longer needed. */
  settled(doc: T): void {
    if (doc.dirty && this.docsHas(doc)) return;

    this.copied.set(doc, this.changes.get(doc) ?? 0);
    if (this.held.delete(doc)) void this.host.remove?.(this.keyOf(doc));
  }

  private docsHas(doc: T): boolean {
    return this.host.docs().includes(doc);
  }

  /** Typing stopped: AutoSave saves what it may, and the rest gets a copy. */
  private async idle(): Promise<void> {
    for (const doc of this.host.docs()) {
      if (needsAutoSave(this.autoSave, doc)) await this.host.save(doc);
    }

    await this.flush();
  }

  /** Writes a copy of every document with changes the last copy does not have. */
  async flush(): Promise<void> {
    if (this.writing || !this.host.write) return;
    this.writing = true;

    try {
      for (const doc of this.host.docs()) {
        const changes = this.changes.get(doc) ?? 0;

        if (!needsCopy({ dirty: doc.dirty, changes, copied: this.copied.get(doc) ?? -1 })) continue;

        let bytes: Uint8Array;
        try {
          bytes = this.host.bytes(doc);
        } catch (error) {
          console.warn('recovery copy not made', error);
          continue;
        }

        if (await this.host.write(this.keyOf(doc), { path: doc.path, name: doc.name }, bytes)) {
          this.copied.set(doc, changes);
          this.held.add(doc);
        }
      }
    } finally {
      this.writing = false;
    }
  }
}
