// BibTeX (.bib): entries, `@string` macros, values in braces, quotes or bare, joined with `#`,
// LaTeX accents and commands turned into the characters they stand for, and author lists.

import { type Name, type Source } from './model';

const MONTHS: Record<string, string> = {
  jan: '1', feb: '2', mar: '3', apr: '4', may: '5', jun: '6', jul: '7', aug: '8', sep: '9', oct: '10', nov: '11', dec: '12',
};

export interface BibEntry {
  type: string;
  key: string;
  fields: Record<string, string>;
}

/** Reads the entries of a .bib file. Values are as written, LaTeX and all; braces stay. */
export function parseBibtex(text: string): BibEntry[] {
  const macros: Record<string, string> = { ...MONTHS };
  const entries: BibEntry[] = [];
  let i = 0;

  const skipSpace = () => {
    while (i < text.length && /\s/.test(text[i])) i++;
  };

  const ident = () => {
    const start = i;
    while (i < text.length && /[^\s,={}()"#%]/.test(text[i])) i++;
    return text.slice(start, i);
  };

  /** A balanced group starting at the open brace; returns what is inside. */
  const braced = () => {
    let depth = 0;
    const start = i + 1;
    for (; i < text.length; i++) {
      if (text[i] === '\\') {
        i++;
        continue;
      }
      if (text[i] === '{') depth++;
      else if (text[i] === '}' && --depth === 0) return text.slice(start, i++);
    }
    return text.slice(start);
  };

  const quotedValue = () => {
    let depth = 0;
    const start = ++i;
    for (; i < text.length; i++) {
      if (text[i] === '\\') {
        i++;
        continue;
      }
      if (text[i] === '{') depth++;
      else if (text[i] === '}') depth--;
      else if (text[i] === '"' && depth === 0) return text.slice(start, i++);
    }
    return text.slice(start);
  };

  const value = () => {
    let out = '';
    for (;;) {
      skipSpace();
      if (text[i] === '{') out += braced();
      else if (text[i] === '"') out += quotedValue();
      else {
        const word = ident();
        out += /^\d+$/.test(word) ? word : (macros[word.toLowerCase()] ?? word);
      }
      skipSpace();
      if (text[i] !== '#') return out;
      i++;
    }
  };

  while (i < text.length) {
    const at = text.indexOf('@', i);
    if (at < 0) break;
    i = at + 1;
    const type = ident().toLowerCase();
    skipSpace();
    const open = text[i];
    if (open !== '{' && open !== '(') continue;
    const close = open === '{' ? '}' : ')';
    i++;

    if (type === 'comment') {
      i--;
      if (open === '{') braced();
      continue;
    }
    if (type === 'preamble') {
      value();
      continue;
    }

    if (type === 'string') {
      skipSpace();
      const name = ident().toLowerCase();
      skipSpace();
      if (text[i] === '=') {
        i++;
        macros[name] = value();
      }
      skipSpace();
      if (text[i] === close) i++;
      continue;
    }

    skipSpace();
    const keyStart = i;
    while (i < text.length && text[i] !== ',' && text[i] !== close && !/\s/.test(text[i])) i++;
    const key = text.slice(keyStart, i);
    const fields: Record<string, string> = {};

    for (;;) {
      skipSpace();
      if (text[i] === ',') i++;
      skipSpace();
      if (i >= text.length || text[i] === close) {
        i++;
        break;
      }
      const name = ident().toLowerCase();
      skipSpace();
      if (!name || text[i] !== '=') {
        // Something unreadable: on to the next entry.
        while (i < text.length && text[i] !== '@') i++;
        break;
      }
      i++;
      fields[name] = value();
    }

    entries.push({ type, key, fields });
  }

  return entries;
}

// ---- LaTeX to text ------------------------------------------------------------------------------------

const ACCENTS: Record<string, string> = {
  '"': '̈', "'": '́', '`': '̀', '^': '̂', '~': '̃', '=': '̄', '.': '̇',
  c: '̧', v: '̌', H: '̋', u: '̆', k: '̨', r: '̊', d: '̣', b: '̱',
};

const SYMBOLS: Record<string, string> = {
  ss: 'ß', o: 'ø', O: 'Ø', ae: 'æ', AE: 'Æ', oe: 'œ', OE: 'Œ', aa: 'å', AA: 'Å', l: 'ł', L: 'Ł', i: 'ı', j: 'ȷ',
  dh: 'ð', DH: 'Ð', th: 'þ', TH: 'Þ', ng: 'ŋ', NG: 'Ŋ', S: '§', P: '¶', copyright: '©', textregistered: '®',
  textendash: '–', textemdash: '—', dots: '…', ldots: '…', textquoteright: '’', textquoteleft: '‘', LaTeX: 'LaTeX', TeX: 'TeX',
};

/** LaTeX as plain text: `{\"u}ber` → `über`, `\&` → `&`, `--` → `–`, braces dropped. */
export function latexToText(input: string): string {
  let s = input;

  // Accents: \"u, \"{u}, {\"u}, \'{\i}, \c{c}, \v s
  s = s.replace(/\\(["'`^~=.])\s*(?:\{\s*(\\?[A-Za-z]?)\s*\}|(\\[ij](?![A-Za-z])|[A-Za-z]))/g, (_m, accent: string, inBraces: string | undefined, bare: string | undefined) => {
    const letter = (inBraces ?? bare ?? '').replace(/^\\([ij])$/, '$1');
    return (letter + ACCENTS[accent]).normalize('NFC');
  });
  s = s.replace(/\\([cvHukrdb])(?:\s*\{\s*(\\?[A-Za-z])\s*\}|\s+([A-Za-z]))/g, (_m, accent: string, a: string | undefined, b: string | undefined) => {
    const letter = (a ?? b ?? '').replace(/^\\([ij])$/, '$1');
    return (letter + ACCENTS[accent]).normalize('NFC');
  });

  // Commands that are characters, then escaped characters.
  s = s.replace(/\\([A-Za-z]+)(?![A-Za-z])\s?(?:\{\})?/g, (m, name: string) => SYMBOLS[name] ?? m);
  s = s.replace(/\\([&%$#_{}])/g, '$1');

  // Formatting commands keep their argument: \emph{x}, \textit{x}, \url{x}, ...
  for (let k = 0; k < 4; k++) s = s.replace(/\\[A-Za-z]+\*?\s*\{([^{}]*)\}/g, '$1');
  s = s.replace(/\\[A-Za-z]+\*?/g, '');

  s = s.replace(/---/g, '—').replace(/--/g, '–').replace(/``|''/g, '"').replace(/~/g, ' ');
  s = s.replace(/[{}]/g, '');
  return s.replace(/\s+/g, ' ').trim();
}

// ---- Names ----------------------------------------------------------------------------------------------

/** Splits on a word at brace depth 0. */
function splitTop(text: string, separator: RegExp): string[] {
  const parts: string[] = [];
  let depth = 0;
  let start = 0;

  for (let i = 0; i < text.length; i++) {
    if (text[i] === '{') depth++;
    else if (text[i] === '}') depth--;
    else if (depth === 0) {
      const m = separator.exec(text.slice(i));
      if (m && m.index === 0) {
        parts.push(text.slice(start, i));
        i += m[0].length - 1;
        start = i + 1;
      }
    }
  }
  parts.push(text.slice(start));
  return parts.map((p) => p.trim()).filter(Boolean);
}

/** A BibTeX name list: "Smith, John and {World Health Organization} and Jane van Doe". */
export function bibtexNames(text: string): Name[] {
  return splitTop(text.replace(/\s+/g, ' '), /^\s+and\s+/i).map((raw): Name => {
    if (/^\{[^{}]*(\{[^{}]*\}[^{}]*)*\}$/.test(raw) && !raw.slice(1, -1).includes(',')) return { corporate: latexToText(raw) };

    const parts = splitTop(raw, /^,/);
    if (parts.length >= 2) {
      // "von Last, First" or "von Last, Jr, First"
      const given = latexToText(parts[parts.length - 1]).split(' ').filter(Boolean);
      return tidy({ last: latexToText(parts[0]), first: given[0], middle: given.slice(1).join(' ') });
    }

    const words = splitTop(raw, /^\s+/);
    if (words.length === 1) return { last: latexToText(words[0]) };
    // "First von Last": the last name starts at the first lower-case word, or is the last word.
    let at = words.findIndex((w, i) => i > 0 && i < words.length - 1 && /^[a-z]/.test(w));
    if (at < 0) at = words.length - 1;
    const given = words.slice(0, at).map(latexToText);
    return tidy({ last: words.slice(at).map(latexToText).join(' '), first: given[0], middle: given.slice(1).join(' ') });
  });
}

function tidy(name: Name): Name {
  const out: Name = {};
  for (const key of ['last', 'first', 'middle', 'corporate'] as const) if (name[key]) out[key] = name[key];
  return out;
}

// ---- To sources -------------------------------------------------------------------------------------------

const THESES: Record<string, string> = { phdthesis: 'Doctoral dissertation', mastersthesis: "Master's thesis", thesis: 'Thesis' };

export function bibtexToSources(text: string): Source[] {
  return parseBibtex(text).map((entry) => {
    const f = (name: string) => (entry.fields[name] !== undefined ? latexToText(entry.fields[name]) : '');
    const fields: Record<string, string> = {};
    const set = (word: string, value: string) => {
      if (value) fields[word] = value;
    };

    let type = 'Misc';
    switch (entry.type) {
      case 'article':
        type = 'JournalArticle';
        set('JournalName', f('journal') || f('journaltitle'));
        break;
      case 'book':
      case 'booklet':
      case 'manual':
        type = 'Book';
        break;
      case 'inbook':
      case 'incollection':
        type = 'BookSection';
        set('BookTitle', f('booktitle'));
        break;
      case 'inproceedings':
      case 'conference':
      case 'proceedings':
        type = 'ConferenceProceedings';
        set('ConferenceName', f('booktitle') || f('eventtitle'));
        break;
      case 'techreport':
      case 'report':
        type = 'Report';
        set('ReportType', f('type'));
        set('StandardNumber', f('number'));
        break;
      case 'phdthesis':
      case 'mastersthesis':
      case 'thesis':
        type = 'Report';
        set('ThesisType', f('type') || THESES[entry.type]);
        set('Institution', f('school') || f('institution'));
        break;
      case 'online':
      case 'electronic':
      case 'webpage':
      case 'www':
        type = 'InternetSite';
        set('InternetSiteTitle', f('organization'));
        break;
    }

    const date = f('date');
    set('Title', f('title'));
    set('Year', f('year') || (/^\d{4}/.exec(date)?.[0] ?? ''));
    set('Month', f('month') || (/^\d{4}-(\d{2})/.exec(date)?.[1].replace(/^0/, '') ?? ''));
    set('Volume', f('volume'));
    if (type !== 'Report') set('Issue', f('number') || f('issue'));
    set('Pages', f('pages').replace(/\s*[-–]+\s*/g, '–'));
    set('Edition', f('edition'));
    set('Publisher', f('publisher') || (type === 'Report' && !fields.ThesisType ? f('institution') : ''));
    set('City', f('address') || f('location'));
    set('DOI', f('doi'));
    set('URL', f('url'));
    set('Comments', f('note'));
    set('ShortTitle', f('shorttitle'));

    const people: Record<string, Name[]> = {};
    if (entry.fields.author) people.Author = bibtexNames(entry.fields.author);
    if (entry.fields.editor) people.Editor = bibtexNames(entry.fields.editor);
    if (!people.Author && f('organization') && type !== 'InternetSite') people.Author = [{ corporate: f('organization') }];

    return { tag: entry.key.replace(/[^\w:.-]/g, ''), type, fields, people, extra: [] };
  });
}
