// Who is reviewing: the name new comments and tracked changes are signed with. It is a setting of
// its own; until it is set, the name of the user logged in to the computer (asked of the desktop
// program), and in a browser a plain "Author".

const AUTHOR_KEY = 'text-studio:author';

let systemName = '';

function read(): string | null {
  try {
    return localStorage.getItem(AUTHOR_KEY);
  } catch {
    return null;
  }
}

/** The name new comments and changes carry. */
export function authorName(): string {
  return read()?.trim() || systemName || 'Author';
}

/** The name as set by the user; empty when it falls back to the computer's user name. */
export function authorSetting(): string {
  return read() ?? '';
}

export function setAuthorName(name: string): void {
  try {
    if (name.trim()) localStorage.setItem(AUTHOR_KEY, name.trim());
    else localStorage.removeItem(AUTHOR_KEY);
  } catch {
    // Storage switched off: the name lasts until the window closes.
    systemName = name.trim() || systemName;
  }
}

/** What the computer calls its user, used while no name has been set. */
export function setSystemAuthor(name: string): void {
  systemName = name.trim();
}

/** Two or three letters for a name, the way Word abbreviates commenters. */
export function initialsOf(name: string): string {
  const words = name.split(/[\s._-]+/).filter(Boolean);
  if (!words.length) return '';
  return (words.length === 1 ? words[0].slice(0, 2) : words.slice(0, 3).map((w) => w[0]).join('')).toUpperCase();
}

/** Now, the way Word dates its revisions: to the second, in UTC. */
export function revisionDate(now = new Date()): string {
  return `${now.toISOString().slice(0, 19)}Z`;
}
