// The hidden `opaque` nodes that hold Word's markers between runs: comment ranges, bookmarks, move
// ranges. Review edits them as source: a marker is added to one, or taken out of it.

import type { Node as PMNode } from 'prosemirror-model';
import type { Transaction } from 'prosemirror-state';
import { schema } from '../editor/schema';

const N = schema.nodes;

/** A hidden marker node holding this source. */
export function hiddenNode(raw: string): PMNode {
  return N.opaque.create({ raw, kind: 'para', look: 'hidden' });
}

export const isHidden = (node: PMNode): boolean => node.type === N.opaque && node.attrs.kind === 'para' && node.attrs.look === 'hidden';

/**
 * Rewrites the source of every hidden marker node in the document; one left with nothing in it
 * goes. Returns whether anything changed.
 */
export function editHidden(tr: Transaction, edit: (raw: string, pos: number) => string): boolean {
  const edits: { pos: number; node: PMNode; raw: string }[] = [];

  tr.doc.descendants((node, pos) => {
    if (node.isTextblock && !node.childCount) return false;
    if (!isHidden(node)) return !node.isInline;

    const raw = edit(node.attrs.raw, pos);
    if (raw !== node.attrs.raw) edits.push({ pos, node, raw });
    return false;
  });

  // From the end, so the positions still hold.
  for (const { pos, node, raw } of edits.reverse()) {
    if (raw.trim()) tr.setNodeMarkup(pos, null, { ...node.attrs, raw }, node.marks);
    else tr.delete(pos, pos + node.nodeSize);
  }

  return edits.length > 0;
}

/** A self-closing element `<name .../>` whose `w:id` is this. */
export function elementWithId(name: string, id: string): RegExp {
  return new RegExp(`<${name}\\b[^>]*?\\bw:id="${id.replace(/[^\w-]/g, '')}"[^>]*?/>`, 'g');
}

/** A whole run holding the comment reference with this id. */
export function referenceRun(id: string): RegExp {
  return new RegExp(`<w:r\\b[^>]*>(?:(?!</w:r>)[\\s\\S])*?<w:commentReference\\b[^>]*?\\bw:id="${id.replace(/[^\w-]/g, '')}"[^>]*?/>(?:(?!</w:r>)[\\s\\S])*?</w:r>`, 'g');
}
