// Fields as the editor finds them in its document.
//
// The importer keeps Word's field codes as hidden `opaque` nodes (a `w:fldChar` begin, the
// `w:instrText`, a separate, an end) and the result between separate and end as ordinary text and
// paragraphs. A simple field (`w:fldSimple`) is a `wrap` mark around its result. Nothing here
// changes how a field is stored: `scanFields` reads them out of the document as it is, with the
// positions of their results, so an updater can replace a result and leave the codes as they came.
//
// One hidden node may hold several codes (a bookmark, then a field's begin, say), because the
// importer merges neighbouring hidden runs. Each code is an event with the node's position and
// its index inside the node.

import type { Mark, Node as PMNode } from 'prosemirror-model';
import { decodeEntities, parseFragment } from '../docx/xml';
import { schema } from '../editor/schema';

const N = schema.nodes;

export type EventKind = 'begin' | 'instr' | 'separate' | 'end' | 'bmStart' | 'bmEnd';

export interface FieldEvent {
  kind: EventKind;
  /** The position of the node the code is in. */
  pos: number;
  /** Its index among the codes in that node. */
  index: number;
  node: PMNode;
  text?: string;
  name?: string;
  id?: string;
}

export interface Field {
  /** The instruction as written, trimmed: `SEQ Figure \* ARABIC`. */
  instr: string;
  /** Its first word in capitals: SEQ, REF, TOC, ... */
  type: string;
  /** Where the field starts and ends: the begin code's node, and just after the end code's node. */
  from: number;
  to: number;
  /** The result: what is between the separate code and the end code. Empty when there is no separate. */
  resultFrom: number;
  resultTo: number;
  begin: FieldEvent | null;
  separate: FieldEvent | null;
  end: FieldEvent | null;
  /** For a `w:fldSimple`: the mark that stands for it. */
  simple: Mark | null;
  /** The field this one is in (inside its instruction or its result), if any. */
  parent: Field | null;
}

export interface Bookmark {
  name: string;
  id: string;
  /** Where the bookmark starts and ends, as the positions of the nodes its codes are in. */
  from: number;
  to: number;
}

export interface FieldScan {
  fields: Field[];
  bookmarks: Map<string, Bookmark>;
  /** The highest annotation id (`w:id`) in the document, for new bookmarks. */
  maxId: number;
}

const EVENT_RE =
  /<w:fldChar\b([^>]*?)\/?>|<w:instrText\b[^>]*?(?:\/>|>([\s\S]*?)<\/w:instrText>)|<w:bookmarkStart\b([^>]*?)\/?>|<w:bookmarkEnd\b([^>]*?)\/?>/g;
const attr = (attrs: string, name: string) => new RegExp(`\\b${name}="([^"]*)"`).exec(attrs)?.[1];

const eventCache = new Map<string, Omit<FieldEvent, 'pos' | 'node'>[]>();

/** The codes in one piece of kept XML, in order. */
export function eventsIn(raw: string): Omit<FieldEvent, 'pos' | 'node'>[] {
  let found = eventCache.get(raw);
  if (found) return found;

  found = [];

  if (/<w:(fldChar|instrText|bookmark)/.test(raw)) {
    for (const match of raw.matchAll(EVENT_RE)) {
      const index = found.length;

      if (match[1] !== undefined) {
        const type = attr(match[1], 'w:fldCharType');
        if (type === 'begin' || type === 'separate' || type === 'end') found.push({ kind: type, index });
      } else if (match[0].startsWith('<w:instrText')) {
        found.push({ kind: 'instr', index, text: decodeEntities(match[2] ?? '') });
      } else if (match[3] !== undefined) {
        found.push({ kind: 'bmStart', index, name: decodeEntities(attr(match[3], 'w:name') ?? ''), id: attr(match[3], 'w:id') ?? '' });
      } else if (match[4] !== undefined) {
        found.push({ kind: 'bmEnd', index, id: attr(match[4], 'w:id') ?? '' });
      }
    }
  }

  if (eventCache.size > 4000) eventCache.clear();
  eventCache.set(raw, found);
  return found;
}

const scanCache = new WeakMap<PMNode, FieldScan>();

function fieldType(instr: string): string {
  return (/^\s*([^\s\\]+)/.exec(instr)?.[1] ?? '').toUpperCase();
}

const isSimple = (mark: Mark) => mark.type === schema.marks.wrap && String(mark.attrs.open).startsWith('<w:fldSimple');

/** Every field and bookmark in a document. Cached per document. */
export function scanFields(doc: PMNode): FieldScan {
  const cached = scanCache.get(doc);
  if (cached) return cached;

  const fields: Field[] = [];
  const bookmarks = new Map<string, Bookmark>();
  const openBookmarks = new Map<string, { name: string; from: number }>();
  const stack: { begin: FieldEvent; instr: string; separate: FieldEvent | null; field: Field }[] = [];
  let maxId = 0;
  let simple: { mark: Mark; from: number; to: number } | null = null;

  const closeSimple = () => {
    if (!simple) return;

    const instr = decodeEntities(/\bw:instr="([^"]*)"/.exec(simple.mark.attrs.open)?.[1] ?? '').trim();
    fields.push({
      instr, type: fieldType(instr), from: simple.from, to: simple.to, resultFrom: simple.from, resultTo: simple.to,
      begin: null, separate: null, end: null, simple: simple.mark, parent: stack.length ? stack[stack.length - 1].field : null,
    });
    simple = null;
  };

  const ids = (text: string) => {
    for (const match of text.matchAll(/\bw:id="(\d+)"/g)) maxId = Math.max(maxId, Number(match[1]));
  };

  doc.descendants((node, pos) => {
    if (!node.isInline) {
      if (node.type === N.opaque_block) ids(node.attrs.raw);
      if (node.type !== N.opaque_block) return true;
    }

    const mark = node.marks.find(isSimple) ?? null;

    if (simple && (!mark || !mark.eq(simple.mark))) closeSimple();
    if (mark) {
      if (simple) simple.to = pos + node.nodeSize;
      else simple = { mark, from: pos, to: pos + node.nodeSize };
    }

    for (const m of node.marks) if (m.attrs.tag || m.attrs.open) ids(String(m.attrs.tag ?? m.attrs.open));
    if (node.type !== N.opaque && node.type !== N.opaque_block) return false;

    const raw: string = node.attrs.raw;
    ids(raw);

    for (const e of eventsIn(raw)) {
      const event: FieldEvent = { ...e, pos, node };

      switch (event.kind) {
        case 'begin': {
          const field: Field = {
            instr: '', type: '', from: pos, to: pos, resultFrom: pos, resultTo: pos,
            begin: event, separate: null, end: null, simple: null, parent: stack.length ? stack[stack.length - 1].field : null,
          };
          stack.push({ begin: event, instr: '', separate: null, field });
          break;
        }
        case 'instr': {
          const top = stack[stack.length - 1];
          if (top && !top.separate) top.instr += event.text ?? '';
          break;
        }
        case 'separate': {
          const top = stack[stack.length - 1];
          if (top && !top.separate) top.separate = event;
          break;
        }
        case 'end': {
          const top = stack.pop();
          if (!top) break;

          const field = top.field;
          field.instr = top.instr.trim();
          field.type = fieldType(field.instr);
          field.separate = top.separate;
          field.end = event;
          field.to = pos + node.nodeSize;
          field.resultFrom = top.separate ? (top.separate.pos === pos ? pos : top.separate.pos + top.separate.node.nodeSize) : pos;
          field.resultTo = pos;
          fields.push(field);
          break;
        }
        case 'bmStart':
          if (event.id !== undefined && event.name) openBookmarks.set(event.id, { name: event.name, from: pos });
          break;
        case 'bmEnd': {
          const open = event.id !== undefined ? openBookmarks.get(event.id) : undefined;

          if (open) {
            openBookmarks.delete(event.id!);
            bookmarks.set(open.name, { name: open.name, id: event.id!, from: open.from, to: pos });
          }
          break;
        }
      }
    }

    return false;
  });

  closeSimple();
  fields.sort((a, b) => a.from - b.from || b.to - a.to);

  const scan = { fields, bookmarks, maxId };
  scanCache.set(doc, scan);
  return scan;
}

// ---- Instructions ------------------------------------------------------------------------------

export interface Instruction {
  type: string;
  /** Arguments that are not switches, in order; quotes taken off. */
  args: string[];
  /** Switches by their letter or sign (`*`, `o`, `h`), with their argument or true. */
  switches: Map<string, string | true>;
  /** Every `\*` switch: a field can have a number format and MERGEFORMAT both. */
  formats: string[];
}

/**
 * Reads an instruction. `withArgs` lists the switches that take an argument (`\*`, `\#` and `\@`
 * always do); any other switch is a flag.
 */
export function parseInstr(instr: string, withArgs = ''): Instruction {
  const tokens: string[] = [];
  const re = /"((?:[^"\\]|\\.)*)"|(\\\S)|([^\s"]+)/g;
  const quoted = new Set<number>();

  for (const match of instr.matchAll(re)) {
    if (match[1] !== undefined) {
      quoted.add(tokens.length);
      tokens.push(match[1].replace(/\\(.)/g, '$1'));
    } else {
      tokens.push(match[2] ?? match[3]);
    }
  }

  const type = (tokens.shift() ?? '').toUpperCase();
  const args: string[] = [];
  const switches = new Map<string, string | true>();
  const formats: string[] = [];
  const takes = new Set(['*', '#', '@', ...withArgs]);

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    const isSwitch = !quoted.has(i + 1) && /^\\\S$/.test(token);

    if (!isSwitch) {
      args.push(token);
      continue;
    }

    const letter = token[1];
    const key = letter === '*' || letter === '#' || letter === '@' ? letter : letter.toLowerCase();
    const next = tokens[i + 1];

    if (takes.has(key) && next !== undefined && (quoted.has(i + 1) || !/^\\\S$/.test(next))) {
      switches.set(key, next);
      if (key === '*') formats.push(next);
      i++;
    } else {
      switches.set(key, true);
    }
  }

  return { type, args, switches, formats };
}

// ---- Reading the document ------------------------------------------------------------------------

/** The text of a range, without field codes and other hidden things. */
export function visibleText(doc: PMNode, from: number, to: number): string {
  return doc.textBetween(Math.max(0, from), Math.min(doc.content.size, to), ' ', '');
}

/** Whether a node shows nothing: a field code, a bookmark, a comment anchor. */
export const isHidden = (node: PMNode | null | undefined): boolean =>
  !!node && node.type === N.opaque && node.attrs.look === 'hidden';

/** The innermost field around a position. */
export function fieldAt(doc: PMNode, pos: number): Field | null {
  let best: Field | null = null;

  for (const field of scanFields(doc).fields) {
    if (field.from <= pos && pos <= field.to && (!best || field.to - field.from < best.to - best.from)) best = field;
  }

  return best;
}

/** Splits kept XML into the part up to and including the element the n-th code is in, and the rest. */
export function splitRawAfter(raw: string, eventIndex: number): [string, string] | null {
  const holder = parseFragment(raw);
  if (!holder) return null;

  let count = 0;

  for (const el of holder.children) {
    const source = holder.src.slice(el.start, el.end);
    count += eventsIn(source).length;

    if (count > eventIndex) {
      const cut = el.end - 3; // parseFragment wraps the source in <x>...</x>
      return [raw.slice(0, cut), raw.slice(cut)];
    }
  }

  return null;
}
