// Writing the editor's document back into its .docx.
//
// The package the document was read from is never changed: each save starts from a copy of it and
// replaces the main part, plus whatever the edit needed on top (new pictures, links, lists and
// styles). Every other part goes out byte for byte as it came in.
//
// Inside the main part, source kept on nodes is written back as it is, properties the editor
// manages are written fresh, and both are put into the order the schema asks for.

import type { Mark, Node as PMNode, Fragment } from 'prosemirror-model';
import { TableMap } from 'prosemirror-tables';
import { chartXml } from '../chart/chartxml';
import { type ChartSpec, parseSpec } from '../chart/model';
import { workbookBytes } from '../chart/workbook';
import { ommlForPart } from '../math/node';
import { WRAPPERS, schema } from '../editor/schema';
import type { DocContext } from './import';
import { type DocxPackage, IMAGE_TYPES, REL_TYPE, type Rel, addContentTypes, addRels, dirOf, parseDataUrl, parseRels, relKind, relsPathFor, resolveTarget } from './package';
import { PPR_LAST, PPR_ORDER, RPR_LAST, RPR_ORDER, TCPR_LAST, TCPR_ORDER, highlightName, pxToEmu, pxToTwips, twipsToPx } from './props';
import { childrenNamed, escAttr, escText, orderProps, parseXml, splitElements } from './xml';
import { writeComments } from '../review/comments';
import { partWriters } from './part-writers';
import { shapeXml } from '../shapes/io';

const N = schema.nodes;

const R_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';
const WP_NS = 'http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing';
const A_NS = 'http://schemas.openxmlformats.org/drawingml/2006/main';
const PIC_NS = 'http://schemas.openxmlformats.org/drawingml/2006/picture';
const CHART_NS = 'http://schemas.openxmlformats.org/drawingml/2006/chart';
const WML = 'application/vnd.openxmlformats-officedocument.wordprocessingml';
const CHART_TYPE = 'application/vnd.openxmlformats-officedocument.drawingml.chart+xml';
const XLSX_TYPE = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

const EXT_OF_MIME: Record<string, string> = { 'image/png': 'png', 'image/jpeg': 'jpeg', 'image/gif': 'gif', 'image/bmp': 'bmp' };

/** A field's markers and code text, wherever they sit in kept source. */
const FIELD_TOKEN =
  /<w:fldChar\b[^>]*?w:fldCharType="(begin|separate|end)"[^>]*?(?:\/>|>[\s\S]*?<\/w:fldChar>)|<w:(instrText|delInstrText)\b[^>]*?(?:\/>|>[\s\S]*?<\/w:\2>)/g;

/** An element as source, with some attributes set (or, with null, removed). */
function withAttrs(source: string, changes: Record<string, string | null>): string {
  const el = parseXml(source);
  const attrs: Record<string, string> = { ...el.attrs };

  for (const [name, value] of Object.entries(changes)) {
    if (value === null) delete attrs[name];
    else attrs[name] = value;
  }

  const open = `<${el.name}${Object.entries(attrs).map(([name, value]) => ` ${name}="${escAttr(value)}"`).join('')}`;

  return el.innerStart === el.end ? `${open}/>` : `${open}>${source.slice(el.innerStart, el.innerEnd)}</${el.name}>`;
}

class Exporter {
  private readonly pkg;
  private readonly newRels: Rel[] = [];
  private readonly usedRelIds: Set<string>;
  private relCounter = 1;
  private readonly linkRels = new Map<string, string>();
  private readonly imageRels = new Map<string, string>();
  private readonly defaults = new Map<string, string>();
  private readonly overrides = new Map<string, string>();
  private readonly rPrCache = new WeakMap<readonly Mark[], string>();
  private readonly wrapperCache = new WeakMap<readonly Mark[], Mark[]>();
  private mediaCounter = 1;
  private chartCounter = 1;
  /** Chart parts that a chart in the document still shows as they are, and ones written afresh. */
  private readonly chartsKept = new Set<string>();
  private readonly chartsRewritten = new Set<string>();
  private drawingId: number;
  private fieldDepth = 0;

  constructor(private readonly ctx: DocContext) {
    this.pkg = ctx.pkg.clone();
    this.usedRelIds = new Set(ctx.rels.map((rel) => rel.id));
    this.drawingId = ctx.maxDrawingId;
  }

  run(doc: PMNode): Uint8Array {
    const { ctx, pkg } = this;

    // A copied chart shares its part with the original. The part can only be rewritten for a
    // changed chart if no unchanged one still shows it.
    doc.descendants((node) => {
      if (node.type === N.chart && node.attrs.part && node.attrs.spec === node.attrs.orig) this.chartsKept.add(node.attrs.part);
    });

    let body = this.blocks(doc.content);

    // A field whose end was deleted would swallow whatever follows it. Close it where the text ends.
    if (this.fieldDepth > 0) {
      const closers = '<w:r><w:fldChar w:fldCharType="end"/></w:r>'.repeat(this.fieldDepth);
      const at = body.lastIndexOf('</w:p>');
      body = at >= 0 ? body.slice(0, at) + closers + body.slice(at) : `${body}<w:p>${closers}</w:p>`;
    }

    pkg.setText(ctx.docPath, ctx.head + body + (doc.attrs.sectPr ?? ctx.sectPr ?? '') + ctx.tail);

    const numbering = ctx.numbering.exportXml(ctx.numberingPath ? ctx.pkg.text(ctx.numberingPath) : null);

    if (numbering) {
      pkg.setText(ctx.numberingPath ?? this.newPart('numbering.xml', 'numbering', `${WML}.numbering+xml`), numbering);
    }

    ctx.styles.useEdits(doc.attrs.styleEdits);
    const styles = ctx.styles.exportXml(ctx.stylesPath ? ctx.pkg.text(ctx.stylesPath) : null);

    if (styles) {
      pkg.setText(ctx.stylesPath ?? this.newPart('styles.xml', 'styles', `${WML}.styles+xml`), styles);
    }

    writeComments(ctx, doc, { pkg, relId: () => this.relId(), rels: this.newRels, overrides: this.overrides, docPath: ctx.docPath });

    if (this.newRels.length) {
      const relsPath = relsPathFor(ctx.docPath);
      pkg.setText(relsPath, addRels(pkg.text(relsPath), this.newRels));
    }

    if (this.defaults.size || this.overrides.size) {
      pkg.setText('[Content_Types].xml', addContentTypes(pkg.text('[Content_Types].xml') ?? '', this.defaults, this.overrides));
    }

    for (const write of partWriters) write(ctx, pkg, doc);

    return pkg.toBytes();
  }

  /**
   * A header or footer part with new content (src/docx/headers.ts). New pictures and links get
   * relationships of the part's own; the package with the part written is returned.
   */
  part(path: string, head: string, doc: PMNode, tail: string): DocxPackage {
    const relsPath = relsPathFor(path);
    for (const rel of parseRels(this.pkg.text(relsPath))) this.usedRelIds.add(rel.id);

    let body = this.blocks(doc.content);

    if (this.fieldDepth > 0) {
      const closers = '<w:r><w:fldChar w:fldCharType="end"/></w:r>'.repeat(this.fieldDepth);
      const at = body.lastIndexOf('</w:p>');
      body = at >= 0 ? body.slice(0, at) + closers + body.slice(at) : `${body}<w:p>${closers}</w:p>`;
    }

    this.pkg.setText(path, head + body + tail);
    if (this.newRels.length) this.pkg.setText(relsPath, addRels(this.pkg.text(relsPath), this.newRels));
    if (this.defaults.size) this.pkg.setText('[Content_Types].xml', addContentTypes(this.pkg.text('[Content_Types].xml') ?? '', this.defaults, new Map()));

    return this.pkg;
  }

  // ---- Package bookkeeping -----------------------------------------------------------------

  private relId(): string {
    let id: string;

    do {
      id = `rId${this.relCounter++}`;
    } while (this.usedRelIds.has(id));

    this.usedRelIds.add(id);
    return id;
  }

  /** A part the document did not have before, beside the main part; returns its path. */
  private newPart(name: string, kind: string, contentType: string): string {
    const path = dirOf(this.ctx.docPath) + name;

    this.newRels.push({ id: this.relId(), type: `${REL_TYPE}/${kind}`, target: name, external: false });
    this.overrides.set(path, contentType);

    return path;
  }

  private linkRel(href: string): string {
    let id = this.linkRels.get(href);

    if (!id) {
      id = this.relId();
      this.linkRels.set(href, id);
      this.newRels.push({ id, type: `${REL_TYPE}/hyperlink`, target: href, external: true });
    }

    return id;
  }

  /** Puts a new picture into the package, once however often it is used, and returns its relationship. */
  private imageRel(src: string): string | null {
    const known = this.imageRels.get(src);
    if (known) return known;

    const data = parseDataUrl(src);
    const ext = data ? EXT_OF_MIME[data.mime] : undefined;
    if (!data || !ext) return null;

    const dir = `${dirOf(this.ctx.docPath)}media/`;
    let name: string;

    do {
      name = `image${this.mediaCounter++}.${ext}`;
    } while (this.pkg.has(dir + name));

    const id = this.relId();

    this.pkg.set(dir + name, data.bytes);
    this.defaults.set(ext, IMAGE_TYPES[ext]);
    this.newRels.push({ id, type: `${REL_TYPE}/image`, target: `media/${name}`, external: false });
    this.imageRels.set(src, id);

    return id;
  }

  // ---- Blocks ------------------------------------------------------------------------------

  private blocks(content: Fragment): string {
    let out = '';
    let last: PMNode | null = null;

    content.forEach((node) => {
      out += this.block(node);
      if (node.type !== N.opaque_block || !node.attrs.hidden) last = node;
    });

    // Word wants a paragraph after a table, at the end of a cell and of the document alike.
    if (!last || (last as PMNode).type === N.table) out += '<w:p/>';

    return out;
  }

  private block(node: PMNode): string {
    switch (node.type) {
      case N.paragraph: {
        const inside = this.pPr(node.attrs) + this.inline(node);
        return inside ? `<w:p>${inside}</w:p>` : '<w:p/>';
      }
      case N.table:
        return this.table(node);
      case N.block_wrap:
        return node.attrs.open + this.blocks(node.content) + node.attrs.close;
      case N.opaque_block:
        return this.fixFields(node.attrs.raw);
      default:
        return '';
    }
  }

  private pPr(a: PMNode['attrs']): string {
    const entries: [string, string][] = [];

    if (a.styleId) entries.push(['w:pStyle', `<w:pStyle w:val="${escAttr(a.styleId)}"/>`]);
    if (a.numId !== null) entries.push(['w:numPr', `<w:numPr><w:ilvl w:val="${a.ilvl}"/><w:numId w:val="${a.numId}"/></w:numPr>`]);
    if (a.align) entries.push(['w:jc', `<w:jc w:val="${escAttr(a.align)}"/>`]);

    const kept = splitElements(a.ppr);

    if (a.indent !== null) {
      const ind = kept.find(([name]) => name === 'w:ind');
      entries.push(['w:ind', ind ? withAttrs(ind[1], { 'w:left': String(a.indent), 'w:start': null }) : `<w:ind w:left="${a.indent}"/>`]);
    }

    for (const entry of kept) {
      if (entry[0] !== 'w:pStyle' && entry[0] !== 'w:jc') entries.push(entry);
    }

    if (a.sectPr) entries.push(['w:sectPr', a.sectPr]);

    const inside = orderProps(entries, PPR_ORDER, PPR_LAST);
    return inside ? `<w:pPr>${inside}</w:pPr>` : '';
  }

  // ---- Tables ------------------------------------------------------------------------------

  private table(node: PMNode): string {
    const a = node.attrs;
    const map = TableMap.get(node);
    const { width, height } = map;
    const sound = !map.problems?.length && width > 0;

    // The width of each column, from whichever cell says it.
    const widths: (number | null)[] = new Array(width).fill(null);

    if (sound) {
      for (let r = 0; r < height; r++) {
        for (let c = 0; c < width; c++) {
          const pos = map.map[r * width + c];
          if (c > 0 && map.map[r * width + c - 1] === pos) continue;

          const colwidth = node.nodeAt(pos)?.attrs.colwidth as number[] | null;
          colwidth?.forEach((w, i) => {
            if (c + i < width && w > 0) widths[c + i] = w;
          });
        }
      }
    }

    const original = a.grid ? childrenNamed(parseXml(a.grid), 'w:gridCol').map((col) => Math.round(twipsToPx(Number(col.attrs['w:w'] ?? 0)))) : [];
    const known = sound && widths.every((w) => w !== null);
    const unchanged = original.length === width && (!known || widths.every((w, i) => w === original[i]));
    let grid: string;
    let twips: number[] | null = null;

    if (unchanged) {
      // Nothing moved: the grid and the cells' own widths go back as they were.
      grid = a.grid;
    } else {
      const text = this.ctx.page.width - this.ctx.page.left - this.ctx.page.right;
      twips = (known ? (widths as number[]) : new Array<number>(Math.max(1, width)).fill(text / Math.max(1, width))).map(pxToTwips);
      grid = `<w:tblGrid>${twips.map((w) => `<w:gridCol w:w="${w}"/>`).join('')}</w:tblGrid>`;
    }

    const tblPr =
      a.tblPr ??
      `<w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblBorders>${['top', 'left', 'bottom', 'right', 'insideH', 'insideV']
        .map((side) => `<w:${side} w:val="single" w:sz="4" w:space="0" w:color="auto"/>`)
        .join('')}</w:tblBorders></w:tblPr>`;

    let rows = '';

    for (let r = 0; r < node.childCount; r++) {
      const row = node.child(r);
      let cells = '';

      if (sound) {
        for (let c = 0; c < width; ) {
          const pos = map.map[r * width + c];
          const cell = node.nodeAt(pos)!;
          let span = 1;

          while (c + span < width && map.map[r * width + c + span] === pos) span++;

          const tcW = twips ? twips.slice(c, c + span).reduce((sum, w) => sum + w, 0) : null;
          const fromAbove = r > 0 && map.map[(r - 1) * width + c] === pos;

          cells += this.cell(cell, span, fromAbove ? 'continue' : cell.attrs.rowspan > 1 ? 'restart' : null, tcW);
          c += span;
        }
      } else {
        // A table whose rows do not add up: written cell by cell, without the merged cells' fillers.
        row.forEach((cell) => {
          cells += this.cell(cell, cell.attrs.colspan, cell.attrs.rowspan > 1 ? 'restart' : null, null);
        });
      }

      rows += `<w:tr>${row.attrs.trPr ?? ''}${cells}</w:tr>`;
    }

    return `<w:tbl>${tblPr}${grid}${rows}</w:tbl>`;
  }

  private cell(cell: PMNode, span: number, vMerge: 'restart' | 'continue' | null, tcW: number | null): string {
    const entries: [string, string][] = [];

    if (tcW !== null) entries.push(['w:tcW', `<w:tcW w:w="${tcW}" w:type="dxa"/>`]);
    if (span > 1) entries.push(['w:gridSpan', `<w:gridSpan w:val="${span}"/>`]);
    if (vMerge) entries.push(['w:vMerge', vMerge === 'restart' ? '<w:vMerge w:val="restart"/>' : '<w:vMerge/>']);

    for (const entry of splitElements(cell.attrs.tcPr)) {
      if (entry[0] !== 'w:gridSpan' && entry[0] !== 'w:vMerge' && entry[0] !== 'w:hMerge') entries.push(entry);
    }

    const inside = orderProps(entries, TCPR_ORDER, TCPR_LAST);

    // The cells a merged cell covers in the rows below exist in the file, empty.
    return `<w:tc>${inside ? `<w:tcPr>${inside}</w:tcPr>` : ''}${vMerge === 'continue' ? '<w:p/>' : this.blocks(cell.content)}</w:tc>`;
  }

  // ---- Inline content ----------------------------------------------------------------------

  private wrappersOf(node: PMNode): Mark[] {
    let wrappers = this.wrapperCache.get(node.marks);

    if (!wrappers) {
      wrappers = node.marks.filter((mark) => WRAPPERS.has(mark.type.name)).sort((x, y) => x.attrs.depth - y.attrs.depth);
      this.wrapperCache.set(node.marks, wrappers);
    }

    return wrappers;
  }

  private inline(parent: PMNode): string {
    const kids: PMNode[] = [];
    parent.forEach((kid) => kids.push(kid));

    return this.inlineRange(kids, 0, kids.length, 0);
  }

  /** Neighbours that share a wrapper mark go inside one element for it, nested level by level. */
  private inlineRange(kids: PMNode[], from: number, to: number, level: number): string {
    let out = '';
    let i = from;

    while (i < to) {
      const wrapper = this.wrappersOf(kids[i])[level];

      if (!wrapper) {
        out += this.inlineNode(kids[i]);
        i++;
        continue;
      }

      let j = i + 1;
      while (j < to && this.wrappersOf(kids[j])[level]?.eq(wrapper)) j++;

      const [open, close] = this.wrapperTags(wrapper);
      out += open + this.inlineRange(kids, i, j, level + 1) + close;
      i = j;
    }

    return out;
  }

  private wrapperTags(mark: Mark): [string, string] {
    const a = mark.attrs;

    switch (mark.type.name) {
      case 'link': {
        // A link from the file goes back as it was unless it now points somewhere else.
        if (a.tag && (a.rid === null || a.href === a.orig)) return [a.tag, '</w:hyperlink>'];

        if (a.href.startsWith('#')) return [`<w:hyperlink w:anchor="${escAttr(a.href.slice(1))}" w:history="1">`, '</w:hyperlink>'];

        return [`<w:hyperlink xmlns:r="${R_NS}" r:id="${this.linkRel(a.href)}" w:history="1">`, '</w:hyperlink>'];
      }
      case 'track':
        return [a.tag, `</w:${a.kind}>`];
      default:
        return [a.open, a.close];
    }
  }

  private inlineNode(node: PMNode): string {
    const rPr = this.rPr(node.marks);

    switch (node.type) {
      case N.text:
        return `<w:r>${rPr}${this.text(node.text ?? '', node.marks)}</w:r>`;
      case N.hard_break:
        return `<w:r>${rPr}${node.attrs.raw ?? '<w:br/>'}</w:r>`;
      case N.page_break:
        return `<w:r>${rPr}<w:br w:type="${node.attrs.column ? 'column' : 'page'}"/></w:r>`;
      case N.image:
        return `<w:r>${rPr}${this.drawing(node)}</w:r>`;
      case N.chart:
        return `<w:r>${rPr}${this.chart(node)}</w:r>`;
      case N.shape:
        return `<w:r>${rPr}${shapeXml(node, (doc) => this.blocks(doc.content), () => ++this.drawingId)}</w:r>`;
      case N.math:
        return ommlForPart(node.attrs.raw, this.ctx.head);
      case N.opaque:
        return node.attrs.kind === 'para' ? this.fixFields(node.attrs.raw) : `<w:r>${rPr}${this.fixFields(node.attrs.raw)}</w:r>`;
      default:
        return '';
    }
  }

  private text(text: string, marks: readonly Mark[]): string {
    // Text inside a tracked deletion has an element of its own.
    const deleted = marks.some((mark) => mark.type.name === 'track' && (mark.attrs.kind === 'del' || mark.attrs.kind === 'moveFrom'));
    const tag = deleted ? 'w:delText' : 'w:t';

    return text
      .split(/(\t|\n)/)
      .map((part) => (part === '\t' ? '<w:tab/>' : part === '\n' ? '<w:br/>' : part ? `<${tag} xml:space="preserve">${escText(part)}</${tag}>` : ''))
      .join('');
  }

  private rPr(marks: readonly Mark[]): string {
    if (!marks.length) return '';

    let xml = this.rPrCache.get(marks);
    if (xml !== undefined) return xml;

    const entries: [string, string][] = [];
    const toggle = (name: string, on: boolean) => entries.push([name, on ? `<${name}/>` : `<${name} w:val="0"/>`]);

    for (const mark of marks) {
      const a = mark.attrs;

      switch (mark.type.name) {
        case 'bold':
          toggle('w:b', a.on);
          toggle('w:bCs', a.on);
          break;
        case 'italic':
          toggle('w:i', a.on);
          toggle('w:iCs', a.on);
          break;
        case 'strike':
          toggle('w:strike', a.on);
          break;
        case 'underline':
          entries.push(['w:u', a.raw ?? `<w:u w:val="${escAttr(a.kind)}"/>`]);
          break;
        case 'color':
          entries.push(['w:color', a.raw ?? `<w:color w:val="${a.value === 'auto' ? 'auto' : a.value.slice(1)}"/>`]);
          break;
        case 'highlight': {
          if (a.raw) {
            entries.push(...splitElements(a.raw));
          } else {
            // Word's highlighter has sixteen colours; any other fill is written as shading.
            const name = highlightName(a.value);
            entries.push(name ? ['w:highlight', `<w:highlight w:val="${name}"/>`] : ['w:shd', `<w:shd w:val="clear" w:color="auto" w:fill="${a.value.slice(1)}"/>`]);
          }
          break;
        }
        case 'fontSize':
          if (a.raw) entries.push(...splitElements(a.raw));
          else entries.push(['w:sz', `<w:sz w:val="${a.size}"/>`], ['w:szCs', `<w:szCs w:val="${a.size}"/>`]);
          break;
        case 'fontFamily': {
          const name = escAttr(a.name);
          entries.push(['w:rFonts', a.raw ?? `<w:rFonts w:ascii="${name}" w:hAnsi="${name}" w:cs="${name}"/>`]);
          break;
        }
        case 'vert':
          entries.push(['w:vertAlign', a.raw ?? `<w:vertAlign w:val="${a.value}"/>`]);
          break;
        case 'charStyle':
          entries.push(['w:rStyle', `<w:rStyle w:val="${escAttr(a.id)}"/>`]);
          break;
        case 'rawRPr':
          entries.push(...splitElements(a.xml));
          break;
      }
    }

    const inside = orderProps(entries, RPR_ORDER, RPR_LAST);
    xml = inside ? `<w:rPr>${inside}</w:rPr>` : '';
    this.rPrCache.set(marks, xml);

    return xml;
  }

  /**
   * Field markers in kept source, checked against the ones seen so far. An end or a separator
   * with no beginning before it is left out; the beginnings without an end are counted for `run`.
   */
  private fixFields(source: string): string {
    if (source.indexOf('w:fldChar') < 0 && source.indexOf('nstrText') < 0) return source;

    return source.replace(FIELD_TOKEN, (whole: string, type: string | undefined) => {
      if (type === 'begin') {
        this.fieldDepth++;
        return whole;
      }

      if (this.fieldDepth === 0) return '';
      if (type === 'end') this.fieldDepth--;

      return whole;
    });
  }

  /** A drawing kept from the file, at the size it has now. */
  private sized(a: PMNode['attrs']): string {
    if (a.w === a.ow && a.h === a.oh) return a.raw;

    // Resized: the two places a picture's size is written, and nothing else.
    const size = `$1${pxToEmu(a.w)}$2${pxToEmu(a.h)}$3`;
    const sized = /(<wp:extent\b[^>]*?\bcx=")\d+("[^>]*?\bcy=")\d+(")/;
    const stretched = /(<a:ext\b[^>]*?\bcx=")\d+("[^>]*?\bcy=")\d+(")/;

    return (a.raw as string).replace(sized, size).replace(stretched, size);
  }

  private chart(node: PMNode): string {
    const a = node.attrs;
    const spec = parseSpec(a.spec);

    if (a.raw && a.part) {
      if (!spec || a.spec === a.orig) return this.sized(a);

      // Changed: its part is written again where it is, and the drawing that points at it stays.
      if (!this.chartsKept.has(a.part) && !this.chartsRewritten.has(a.part) && this.pkg.has(a.part)) {
        this.chartsRewritten.add(a.part);
        this.rewriteChart(a.part, spec);

        return this.sized(a);
      }
    }

    if (!spec) return '';

    // A new chart: a chart part, the workbook it draws from, and a drawing that points at the part.
    const dir = dirOf(this.ctx.docPath);
    let n = this.chartCounter;

    while (this.pkg.has(`${dir}charts/chart${n}.xml`) || this.pkg.has(`${dir}embeddings/Microsoft_Excel_Worksheet${n}.xlsx`)) n++;

    this.chartCounter = n + 1;

    const part = `${dir}charts/chart${n}.xml`;
    const rid = this.relId();
    const id = ++this.drawingId;

    this.pkg.setText(part, chartXml(spec, 'rId1'));
    this.pkg.setText(relsPathFor(part), addRels(null, [{ id: 'rId1', type: `${REL_TYPE}/package`, target: `../embeddings/Microsoft_Excel_Worksheet${n}.xlsx`, external: false }]));
    this.pkg.set(`${dir}embeddings/Microsoft_Excel_Worksheet${n}.xlsx`, workbookBytes(spec.cells));
    this.overrides.set(part, CHART_TYPE);
    this.defaults.set('xlsx', XLSX_TYPE);
    this.newRels.push({ id: rid, type: `${REL_TYPE}/chart`, target: `charts/chart${n}.xml`, external: false });

    return (
      `<w:drawing><wp:inline xmlns:wp="${WP_NS}" distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${pxToEmu(a.w)}" cy="${pxToEmu(a.h)}"/>` +
      `<wp:effectExtent l="0" t="0" r="0" b="0"/><wp:docPr id="${id}" name="Chart ${id}"${spec.title.trim() ? ` descr="${escAttr(spec.title.trim())}"` : ''}/>` +
      `<wp:cNvGraphicFramePr/><a:graphic xmlns:a="${A_NS}"><a:graphicData uri="${CHART_NS}">` +
      `<c:chart xmlns:c="${CHART_NS}" xmlns:r="${R_NS}" r:id="${rid}"/></a:graphicData></a:graphic></wp:inline></w:drawing>`
    );
  }

  /** Writes a changed chart over the part it was read from, and its sheet over that part's workbook. */
  private rewriteChart(part: string, spec: ChartSpec): void {
    const relsPath = relsPathFor(part);
    const rels = parseRels(this.pkg.text(relsPath));
    let book = rels.find((rel) => relKind(rel) === 'package' && !rel.external && /\.xlsx$/i.test(rel.target));

    if (!book) {
      // No workbook, or one in a format this does not write: the chart gets one of its own.
      const dir = dirOf(this.ctx.docPath);
      const used = new Set(rels.map((rel) => rel.id));
      let n = this.chartCounter;
      let id = 1;

      while (this.pkg.has(`${dir}embeddings/Microsoft_Excel_Worksheet${n}.xlsx`)) n++;
      while (used.has(`rId${id}`)) id++;

      this.chartCounter = n + 1;
      book = { id: `rId${id}`, type: `${REL_TYPE}/package`, target: `/${dir}embeddings/Microsoft_Excel_Worksheet${n}.xlsx`, external: false };
      this.pkg.setText(relsPath, addRels(this.pkg.text(relsPath), [book]));
      this.defaults.set('xlsx', XLSX_TYPE);
    }

    this.pkg.set(resolveTarget(part, book.target), workbookBytes(spec.cells));
    this.pkg.setText(part, chartXml(spec, book.id));
  }

  private drawing(node: PMNode): string {
    const a = node.attrs;

    if (a.raw) return this.sized(a);

    const rid = this.imageRel(a.src);
    if (!rid) return '';

    const id = ++this.drawingId;
    const cx = pxToEmu(a.w);
    const cy = pxToEmu(a.h);
    const name = escAttr(a.alt || `Picture ${id}`);

    return (
      `<w:drawing><wp:inline xmlns:wp="${WP_NS}" distT="0" distB="0" distL="0" distR="0"><wp:extent cx="${cx}" cy="${cy}"/>` +
      `<wp:effectExtent l="0" t="0" r="0" b="0"/><wp:docPr id="${id}" name="Picture ${id}" descr="${name}"/>` +
      `<wp:cNvGraphicFramePr><a:graphicFrameLocks xmlns:a="${A_NS}" noChangeAspect="1"/></wp:cNvGraphicFramePr>` +
      `<a:graphic xmlns:a="${A_NS}"><a:graphicData uri="${PIC_NS}"><pic:pic xmlns:pic="${PIC_NS}">` +
      `<pic:nvPicPr><pic:cNvPr id="${id}" name="Picture ${id}"/><pic:cNvPicPr/></pic:nvPicPr>` +
      `<pic:blipFill><a:blip xmlns:r="${R_NS}" r:embed="${rid}"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill>` +
      `<pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr>` +
      `</pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing>`
    );
  }
}

/** The document as a .docx file. `ctx.pkg` is left as it was, so this can be called again and again. */
export function exportDocx(ctx: DocContext, doc: PMNode): Uint8Array {
  return new Exporter(ctx).run(doc);
}

/** A header or footer part written with `doc` as its content, in a copy of `ctx.pkg` (src/docx/headers.ts). */
export function exportPart(ctx: DocContext, path: string, head: string, doc: PMNode, tail: string): DocxPackage {
  return new Exporter(ctx).part(path, head, doc, tail);
}
