// Reading a .docx into the editor's document.
//
// The rule throughout: nothing is thrown away because the editor does not know it. Formatting it
// has no control for stays on the node as source; elements it cannot show become `opaque` nodes
// holding their source; whole parts it never opens (headers, footnotes, comments, settings) stay
// in the package as bytes. What is dropped on purpose is listed in the README: spelling marks,
// Word's cached page-break positions and per-paragraph revision ids.

import { Fragment, Mark, type Node as PMNode } from 'prosemirror-model';
import { accentColors, readChart } from '../chart/chartxml';
import { type ChartSpec, dataOf, sameData, specJson } from '../chart/model';
import { readWorkbook } from '../chart/workbook';
import { shapeNode } from '../shapes/io';
import { type ThemeColors, themeColors } from '../shapes/model';
import { nextKey, schema } from '../editor/schema';
import { Numbering } from './numbering';
import { DRAWABLE, DocxPackage, IMAGE_TYPES, NotDocxError, type Rel, parseRels, relKind, relsPathFor, resolveTarget, toBase64 } from './package';
import { HIGHLIGHTS, type Theme, emuToPx, fontOf, hex, isOn, parseTheme, twipsToPx } from './props';
import { Styles } from './styles';
import { type XmlEl, child, childrenNamed, descendants, hasDescendant, inner, openTag, parseXml, raw, val } from './xml';

export interface PageGeometry {
  /** In CSS pixels, at 96 to the inch. */
  width: number;
  height: number;
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/** Everything about an open document that is not its text: the package and what was read from it. */
export interface DocContext {
  /** Unique per opened document; says which document copied content came from. */
  key: string;
  pkg: DocxPackage;
  docPath: string;
  rels: Rel[];
  styles: Styles;
  stylesPath: string | null;
  numbering: Numbering;
  numberingPath: string | null;
  theme: Theme;
  /** The theme's six accent colours, for charts that name none of their own. */
  accents: string[];
  /** document.xml before and after the body's content, as source. */
  head: string;
  tail: string;
  /** The last section's properties: page size, margins, header and footer references. */
  sectPr: string | null;
  page: PageGeometry;
  /** The highest drawing id in the document, so new pictures get ids no other has. */
  maxDrawingId: number;
}

const N = schema.nodes;
const M = schema.marks;

/** Run content that shows nothing where it stands. A run made only of these is kept whole. */
const HIDDEN_IN_RUN = new Set([
  'w:fldChar', 'w:instrText', 'w:delInstrText', 'w:commentReference', 'w:annotationRef', 'w:footnoteRef',
  'w:endnoteRef', 'w:separator', 'w:continuationSeparator', 'w:lastRenderedPageBreak',
]);

/** Drawings that are more than one picture: shapes, text boxes, charts, diagrams. */
const NOT_A_PICTURE = new Set(['wps:wsp', 'wpg:wgp', 'wpc:wpc', 'c:chart', 'dgm:relIds']);

const TRACKED = new Set(['w:ins', 'w:del', 'w:moveFrom', 'w:moveTo']);
const WRAPPING = new Set(['w:fldSimple', 'w:smartTag', 'w:customXml', 'w:dir', 'w:bdo']);

const A4 = { width: 11906, height: 16838, margin: 1440 };

let documentCounter = 0;

function pageOf(sectPr: XmlEl | null): PageGeometry {
  const size = child(sectPr, 'w:pgSz');
  const margins = child(sectPr, 'w:pgMar');
  const twips = (el: XmlEl | null, name: string, fallback: number) => {
    const n = Number(el?.attrs[name]);
    return Number.isFinite(n) && n > 0 ? n : fallback;
  };

  return {
    width: Math.round(twipsToPx(twips(size, 'w:w', A4.width))),
    height: Math.round(twipsToPx(twips(size, 'w:h', A4.height))),
    top: Math.round(twipsToPx(twips(margins, 'w:top', A4.margin))),
    right: Math.round(twipsToPx(twips(margins, 'w:right', A4.margin))),
    bottom: Math.round(twipsToPx(twips(margins, 'w:bottom', A4.margin))),
    left: Math.round(twipsToPx(twips(margins, 'w:left', A4.margin))),
  };
}

const rawOf = (el: XmlEl | null): string => (el ? raw(el) : '');

class Importer {
  private readonly relById = new Map<string, Rel>();
  private readonly mediaCache = new Map<string, { src: string; alt: string }>();
  private readonly markCache = new Map<string, readonly Mark[]>();
  /** The theme's colours, for shapes that name them (src/shapes/). */
  shapeColors: ThemeColors | undefined;

  constructor(
    private readonly pkg: DocxPackage,
    private readonly docPath: string,
    rels: Rel[],
    private readonly styles: Styles,
    private readonly theme: Theme,
    private readonly accents: string[],
  ) {
    for (const rel of rels) this.relById.set(rel.id, rel);
  }

  // ---- Blocks ------------------------------------------------------------------------------

  blocks(children: XmlEl[]): PMNode[] {
    const out: PMNode[] = [];

    const opaque = (el: XmlEl, hidden: boolean, label = '') => {
      const last = out[out.length - 1];

      // Neighbouring hidden pieces become one node: one thing for the cursor to step over, not five.
      if (hidden && last?.type === N.opaque_block && last.attrs.hidden) {
        out[out.length - 1] = N.opaque_block.create({ ...last.attrs, raw: last.attrs.raw + raw(el) });
      } else {
        out.push(N.opaque_block.create({ raw: raw(el), hidden, label }));
      }
    };

    for (const el of children) {
      switch (el.name) {
        case 'w:p':
          out.push(this.paragraph(el));
          break;

        case 'w:tbl': {
          const table = this.table(el);
          if (table) out.push(table);
          else opaque(el, false, 'Table (kept as it is)');
          break;
        }

        case 'w:sdt': {
          const content = child(el, 'w:sdtContent');
          const inside = content ? this.blocks(content.children) : [];

          if (inside.length) {
            out.push(
              N.block_wrap.create(
                { open: openTag(el) + rawOf(child(el, 'w:sdtPr')) + rawOf(child(el, 'w:sdtEndPr')) + openTag(content!), close: '</w:sdtContent></w:sdt>' },
                inside,
              ),
            );
          } else {
            opaque(el, true);
          }
          break;
        }

        case 'w:customXml': {
          const pr = child(el, 'w:customXmlPr');
          const inside = this.blocks(el.children.filter((c) => c !== pr));

          if (inside.length) out.push(N.block_wrap.create({ open: openTag(el) + rawOf(pr), close: '</w:customXml>' }, inside));
          else opaque(el, true);
          break;
        }

        case 'w:proofErr':
        case 'w:tcPr':
          break;

        case 'w:altChunk':
          opaque(el, false, 'Embedded document (kept as it is)');
          break;

        default:
          opaque(el, true);
      }
    }

    return out;
  }

  private paragraph(p: XmlEl): PMNode {
    const pPr = child(p, 'w:pPr');
    const attrs: Record<string, unknown> = {};
    let ppr = '';

    for (const c of pPr?.children ?? []) {
      switch (c.name) {
        case 'w:pStyle':
          attrs.styleId = c.attrs['w:val'] ?? null;
          break;
        case 'w:jc':
          attrs.align = c.attrs['w:val'] ?? null;
          break;
        case 'w:numPr': {
          const numId = val(c, 'w:numId');

          if (numId === null) {
            ppr += raw(c);
          } else {
            attrs.numId = Number(numId);
            attrs.ilvl = Number(val(c, 'w:ilvl') ?? 0);
          }
          break;
        }
        case 'w:sectPr':
          attrs.sectPr = raw(c);
          break;
        default:
          ppr += raw(c);
      }
    }

    if (ppr) attrs.ppr = ppr;

    const out: PMNode[] = [];
    this.inline(p.children, [], out);

    return N.paragraph.create(attrs, Fragment.fromArray(out));
  }

  // ---- Tables ------------------------------------------------------------------------------

  private table(tbl: XmlEl): PMNode | null {
    const tblPr = child(tbl, 'w:tblPr');
    const grid = child(tbl, 'w:tblGrid');
    const widths = childrenNamed(grid, 'w:gridCol').map((col) => Math.round(twipsToPx(Number(col.attrs['w:w'] ?? 0))));

    // A content control around rows or cells is opened up; its rows and cells are what matters.
    const unwrap = (parent: XmlEl, name: string): XmlEl[] =>
      parent.children.flatMap((c) => (c.name === name ? [c] : c.name === 'w:sdt' ? unwrap(child(c, 'w:sdtContent') ?? c, name) : []));

    interface Cell {
      attrs: { colspan: number; rowspan: number; colwidth: number[] | null; tcPr: string | null };
      content: PMNode[];
    }

    /** For each column, the cell above that is still merging downwards into it. */
    const merging: (Cell | null)[] = [];
    const rows: { tr: XmlEl; cells: Cell[] }[] = [];

    for (const tr of unwrap(tbl, 'w:tr')) {
      const cells: Cell[] = [];
      let col = 0;

      for (const tc of unwrap(tr, 'w:tc')) {
        const tcPr = child(tc, 'w:tcPr');
        const span = Math.max(1, Number(val(tcPr, 'w:gridSpan') ?? 1));
        const vMerge = child(tcPr, 'w:vMerge');
        const restart = vMerge?.attrs['w:val'] === 'restart';
        const above = merging[col];

        // A cell that continues a vertical merge has no content of its own: the cell above grows.
        if (vMerge && !restart && above) {
          above.attrs.rowspan++;
          col += span;
          continue;
        }

        const own = widths.slice(col, col + span);
        const content = this.blocks(tc.children);
        const cell: Cell = {
          attrs: {
            colspan: span,
            rowspan: 1,
            colwidth: own.length === span && own.every((w) => w > 0) ? own : null,
            tcPr: tcPr ? inner(tcPr) || null : null,
          },
          content: content.length ? content : [N.paragraph.create()],
        };

        cells.push(cell);
        for (let k = col; k < col + span; k++) merging[k] = restart ? cell : null;
        col += span;
      }

      rows.push({ tr, cells });
    }

    if (!rows.length) return null;

    // Built only now: a cell's rowspan is not known until the rows below it have been read.
    const built = rows.map(({ tr, cells }) =>
      N.table_row.create(
        { trPr: rawOf(child(tr, 'w:tblPrEx')) + rawOf(child(tr, 'w:trPr')) || null },
        cells.map((cell) => N.table_cell.create(cell.attrs, cell.content)),
      ),
    );

    return N.table.create(
      {
        tblPr: tblPr ? raw(tblPr) : null,
        grid: grid ? raw(grid) : null,
        tstyle: val(tblPr, 'w:tblStyle'),
        borders: this.styles.tableHasBorders(tblPr),
      },
      built,
    );
  }

  // ---- Inline content ----------------------------------------------------------------------

  private pushHidden(out: PMNode[], source: string, marks: readonly Mark[]): void {
    const last = out[out.length - 1];

    if (last?.type === N.opaque && last.attrs.kind === 'para' && last.attrs.look === 'hidden' && Mark.sameSet(last.marks, marks)) {
      out[out.length - 1] = N.opaque.create({ ...last.attrs, raw: last.attrs.raw + source }, null, marks);
    } else {
      out.push(N.opaque.create({ raw: source, kind: 'para', look: 'hidden' }, null, marks));
    }
  }

  /** Content wrapped in an element that becomes a mark. With nothing to mark, the element is kept whole. */
  private wrapped(el: XmlEl, kids: XmlEl[], mark: Mark, wrap: readonly Mark[], out: PMNode[]): void {
    const before = out.length;

    this.inline(kids, [...wrap, mark], out);

    if (out.length === before) {
      this.pushHidden(out, raw(el), wrap);
    }
  }

  private inline(children: XmlEl[], wrap: readonly Mark[], out: PMNode[]): void {
    for (const el of children) {
      const name = el.name;

      if (name === 'w:r') {
        this.run(el, wrap, out);
      } else if (name === 'w:pPr' || name === 'w:proofErr') {
        continue;
      } else if (name === 'w:hyperlink') {
        const rid = el.attrs['r:id'] ?? null;
        const anchor = el.attrs['w:anchor'];
        const target = rid ? (this.relById.get(rid)?.target ?? '') : '';
        const href = target || (anchor ? `#${anchor}` : '');

        this.wrapped(el, el.children, M.link.create({ href, tag: openTag(el), rid, orig: href, depth: wrap.length, k: nextKey() }), wrap, out);
      } else if (TRACKED.has(name)) {
        this.wrapped(el, el.children, M.track.create({ kind: name.slice(2), tag: openTag(el), depth: wrap.length, k: nextKey() }), wrap, out);
      } else if (name === 'w:sdt') {
        const content = child(el, 'w:sdtContent');
        const open = openTag(el) + rawOf(child(el, 'w:sdtPr')) + rawOf(child(el, 'w:sdtEndPr')) + (content ? openTag(content) : '');

        if (content && content.innerStart !== content.end) {
          this.wrapped(el, content.children, M.wrap.create({ open, close: '</w:sdtContent></w:sdt>', depth: wrap.length, k: nextKey() }), wrap, out);
        } else {
          this.pushHidden(out, raw(el), wrap);
        }
      } else if (WRAPPING.has(name) && el.innerStart !== el.end) {
        const pr = el.children.find((c) => c.name === `${name}Pr`) ?? null;

        this.wrapped(
          el,
          el.children.filter((c) => c !== pr),
          M.wrap.create({ open: openTag(el) + rawOf(pr), close: `</${name}>`, depth: wrap.length, k: nextKey() }),
          wrap,
          out,
        );
      } else if (name === 'm:oMath' || name === 'm:oMathPara') {
        out.push(N.math.create({ raw: raw(el), display: name === 'm:oMathPara' }, null, wrap));
      } else {
        // Bookmarks, comment ranges and the like: nothing to see, but they have to stay in place.
        this.pushHidden(out, raw(el), wrap);
      }
    }
  }

  private marksFor(rPr: XmlEl | null, wrap: readonly Mark[]): readonly Mark[] {
    let format: readonly Mark[] = Mark.none;

    if (rPr) {
      const key = raw(rPr);
      const cached = this.markCache.get(key);

      if (cached) {
        format = cached;
      } else {
        format = this.formatMarks(rPr);
        this.markCache.set(key, format);
      }
    }

    return wrap.length ? wrap.reduce((set, mark) => mark.addToSet(set), format) : format;
  }

  /** A run's properties as marks. What has no mark of its own is kept together in `rawRPr`. */
  private formatMarks(rPr: XmlEl): readonly Mark[] {
    const kids = rPr.children;
    const has = (name: string) => kids.some((c) => c.name === name);
    const highlighted = kids.some((c) => c.name === 'w:highlight' && HIGHLIGHTS[c.attrs['w:val'] ?? '']);
    const marks: Mark[] = [];
    let rest = '';

    for (const c of kids) {
      const v = c.attrs['w:val'];

      switch (c.name) {
        case 'w:b':
          marks.push(M.bold.create({ on: isOn(c) }));
          break;
        case 'w:i':
          marks.push(M.italic.create({ on: isOn(c) }));
          break;
        case 'w:strike':
          marks.push(M.strike.create({ on: isOn(c) }));
          break;
        // The complex-script twins are written again from the mark, unless they stand alone.
        case 'w:bCs':
          if (!has('w:b')) rest += raw(c);
          break;
        case 'w:iCs':
          if (!has('w:i')) rest += raw(c);
          break;
        case 'w:szCs':
          if (!has('w:sz')) rest += raw(c);
          break;
        case 'w:u':
          marks.push(M.underline.create({ kind: v ?? 'single', raw: raw(c) }));
          break;
        case 'w:color': {
          const color = hex(v);
          if (color || v === 'auto') marks.push(M.color.create({ value: color ?? 'auto', raw: raw(c) }));
          else rest += raw(c);
          break;
        }
        case 'w:highlight':
          if (HIGHLIGHTS[v ?? '']) marks.push(M.highlight.create({ value: HIGHLIGHTS[v!], raw: raw(c) }));
          else rest += raw(c);
          break;
        case 'w:shd': {
          const fill = hex(c.attrs['w:fill']);
          if (fill && !highlighted) marks.push(M.highlight.create({ value: fill, raw: raw(c) }));
          else rest += raw(c);
          break;
        }
        case 'w:sz': {
          const size = Number(v);
          if (size > 0) marks.push(M.fontSize.create({ size, raw: raw(c) + rawOf(child(rPr, 'w:szCs')) }));
          else rest += raw(c);
          break;
        }
        case 'w:rFonts': {
          const name = fontOf(c, this.theme);
          if (name) marks.push(M.fontFamily.create({ name, raw: raw(c) }));
          else rest += raw(c);
          break;
        }
        case 'w:vertAlign':
          if (v === 'superscript' || v === 'subscript') marks.push(M.vert.create({ value: v, raw: raw(c) }));
          else rest += raw(c);
          break;
        case 'w:rStyle':
          if (v) marks.push(M.charStyle.create({ id: v }));
          break;
        default:
          rest += raw(c);
      }
    }

    if (rest) marks.push(M.rawRPr.create({ xml: rest }));

    return marks.reduce<readonly Mark[]>((set, mark) => mark.addToSet(set), Mark.none);
  }

  private run(r: XmlEl, wrap: readonly Mark[], out: PMNode[]): void {
    const rPr = child(r, 'w:rPr');
    const kids = r.children.filter((c) => c !== rPr);

    if (kids.every((c) => HIDDEN_IN_RUN.has(c.name))) {
      // Field codes and the like. The run goes back whole, formatting and all.
      if (kids.some((c) => c.name !== 'w:lastRenderedPageBreak')) this.pushHidden(out, raw(r), wrap);
      return;
    }

    const marks = this.marksFor(rPr, wrap);
    let text = '';

    const flush = () => {
      if (text) {
        out.push(schema.text(text, marks));
        text = '';
      }
    };

    for (const c of kids) {
      switch (c.name) {
        case 'w:t':
        case 'w:delText':
          text += c.text;
          break;
        case 'w:tab':
          text += '\t';
          break;
        case 'w:noBreakHyphen':
          text += '‑';
          break;
        case 'w:softHyphen':
          text += '­';
          break;
        case 'w:lastRenderedPageBreak':
          break;
        case 'w:br': {
          const type = c.attrs['w:type'];
          flush();

          if (type === 'page' || type === 'column') out.push(N.page_break.create({ column: type === 'column' }, null, marks));
          else out.push(N.hard_break.create({ raw: Object.keys(c.attrs).length ? raw(c) : null }, null, marks));
          break;
        }
        case 'w:cr':
          flush();
          out.push(N.hard_break.create({ raw: raw(c) }, null, marks));
          break;
        case 'w:drawing':
          flush();
          out.push(this.drawing(c, marks));
          break;
        case 'w:footnoteReference':
          flush();
          out.push(N.opaque.create({ raw: raw(c), kind: 'run', look: 'footnote', label: 'Footnote (kept as it is)' }, null, marks));
          break;
        case 'w:endnoteReference':
          flush();
          out.push(N.opaque.create({ raw: raw(c), kind: 'run', look: 'endnote', label: 'Endnote (kept as it is)' }, null, marks));
          break;
        case 'w:pict':
        case 'w:object':
        case 'mc:AlternateContent': {
          flush();
          const shape = c.name !== 'w:object' ? shapeNode(c, this.shapeColors, (kids) => this.blocks(kids), marks) : null;
          if (shape) {
            out.push(shape);
            break;
          }
          out.push(N.opaque.create({ raw: raw(c), kind: 'run', look: 'object', label: 'Drawing or embedded object (kept as it is)' }, null, marks));
          break;
        }
        case 'w:sym':
          flush();
          out.push(N.opaque.create({ raw: raw(c), kind: 'run', look: 'sym', label: 'Symbol (kept as it is)' }, null, marks));
          break;
        default:
          flush();
          out.push(N.opaque.create({ raw: raw(c), kind: 'run', look: 'hidden' }, null, marks));
      }
    }

    flush();
  }

  private media(rid: string | undefined): { src: string; alt: string } {
    const rel = rid ? this.relById.get(rid) : undefined;

    if (!rel || rel.external) return { src: '', alt: 'Linked picture' };

    const part = resolveTarget(this.docPath, rel.target);
    let found = this.mediaCache.get(part);

    if (!found) {
      const bytes = this.pkg.get(part);
      const ext = part.slice(part.lastIndexOf('.') + 1).toLowerCase();

      found =
        bytes && DRAWABLE.has(ext)
          ? { src: `data:${IMAGE_TYPES[ext]};base64,${toBase64(bytes)}`, alt: '' }
          : { src: '', alt: bytes ? `${ext.toUpperCase()} picture` : 'Missing picture' };

      this.mediaCache.set(part, found);
    }

    return found;
  }

  private drawing(el: XmlEl, marks: readonly Mark[]): PMNode {
    const blip = descendants(el, 'a:blip')[0];
    const extent = descendants(el, 'wp:extent')[0];
    const rid = blip?.attrs['r:embed'] ?? blip?.attrs['r:link'];

    if (blip && extent && rid && descendants(el, 'pic:pic').length === 1 && !hasDescendant(el, NOT_A_PICTURE)) {
      const w = Math.max(1, Math.round(emuToPx(Number(extent.attrs.cx) || 0)));
      const h = Math.max(1, Math.round(emuToPx(Number(extent.attrs.cy) || 0)));
      const media = this.media(rid);
      const described = descendants(el, 'wp:docPr')[0]?.attrs.descr ?? '';

      return N.image.create({ src: media.src, w, h, raw: raw(el), ow: w, oh: h, alt: media.alt || described }, null, marks);
    }

    const chartRef = descendants(el, 'c:chart')[0];

    if (chartRef && extent && descendants(el, 'a:graphicData').length === 1) {
      const chart = this.chart(el, chartRef.attrs['r:id'], extent, marks);
      if (chart) return chart;
    }

    const shape = shapeNode(el, this.shapeColors, (kids) => this.blocks(kids), marks);
    if (shape) return shape;

    return N.opaque.create({ raw: raw(el), kind: 'run', look: 'object', label: 'Drawing (kept as it is)' }, null, marks);
  }

  /** A chart of a kind the editor draws, or null for one that stays a placeholder. */
  private chart(el: XmlEl, rid: string | undefined, extent: XmlEl, marks: readonly Mark[]): PMNode | null {
    const rel = rid ? this.relById.get(rid) : undefined;
    if (!rel || rel.external) return null;

    const part = resolveTarget(this.docPath, rel.target);
    const xml = this.pkg.text(part);
    let spec: ChartSpec | null = null;

    try {
      spec = xml ? readChart(parseXml(xml), this.accents) : null;
    } catch {
      // A chart part that is not sound XML: Word may still make something of it, so it is kept.
    }

    if (!spec) return null;

    // The chart part has the numbers; the workbook beside it has the formulas they came from. Its
    // cells are taken if they are laid out as the editor's own sheet is and give the same chart.
    const book = parseRels(this.pkg.text(relsPathFor(part))).find((r) => relKind(r) === 'package' && !r.external);
    const bytes = book ? this.pkg.get(resolveTarget(part, book.target)) : null;
    const cells = bytes ? readWorkbook(bytes) : null;

    if (cells && sameData(dataOf({ ...spec, cells }), dataOf(spec))) spec = { ...spec, cells };

    const json = specJson(spec);
    const w = Math.max(1, Math.round(emuToPx(Number(extent.attrs.cx) || 0)));
    const h = Math.max(1, Math.round(emuToPx(Number(extent.attrs.cy) || 0)));

    return N.chart.create({ spec: json, orig: json, w, h, ow: w, oh: h, raw: raw(el), part }, null, marks);
  }
}

export interface Imported {
  ctx: DocContext;
  doc: PMNode;
}

export function importDocx(bytes: Uint8Array): Imported {
  const pkg = DocxPackage.open(bytes);

  // The main part is wherever the package's own relationships say it is.
  const main = parseRels(pkg.text('_rels/.rels')).find((rel) => relKind(rel) === 'officeDocument');
  const docPath = main ? resolveTarget('', main.target) : 'word/document.xml';
  const source = pkg.text(docPath);

  if (!source) {
    throw new NotDocxError('This file has no document in it. It may be a template or another Office format saved as .docx.');
  }

  const root = parseXml(source);
  const body = child(root, 'w:body');

  if (root.name !== 'w:document' || !body) {
    throw new NotDocxError('This document is laid out in a way the editor cannot read yet.');
  }

  const rels = parseRels(pkg.text(relsPathFor(docPath)));
  const partOf = (kind: string) => {
    const rel = rels.find((r) => relKind(r) === kind && !r.external);
    return rel ? resolveTarget(docPath, rel.target) : null;
  };

  const themePath = partOf('theme');
  const themeXml = themePath ? pkg.text(themePath) : null;
  const themeRoot = themeXml ? parseXml(themeXml) : null;
  const theme = parseTheme(themeRoot);
  const accents = accentColors(themeRoot);

  const stylesPath = partOf('styles');
  const styles = Styles.parse(stylesPath ? pkg.text(stylesPath) : null, theme);

  const numberingPath = partOf('numbering');
  const numbering = Numbering.parse(numberingPath ? pkg.text(numberingPath) : null);
  numbering.resolveLinks(styles);

  const kids = body.children.slice();
  const last = kids[kids.length - 1];
  const sectPr = last?.name === 'w:sectPr' ? (kids.pop() as XmlEl) : null;

  const importer = new Importer(pkg, docPath, rels, styles, theme, accents);
  importer.shapeColors = themeColors(themeRoot);
  const blocks = importer.blocks(kids);

  if (!blocks.some((block) => block.type !== N.opaque_block)) {
    blocks.push(N.paragraph.create());
  }

  const selfClosing = body.innerStart === body.end;
  let maxDrawingId = 0;

  for (const match of source.matchAll(/<wp:docPr\b[^>]*?\bid="(\d+)"/g)) {
    maxDrawingId = Math.max(maxDrawingId, Number(match[1]));
  }

  const ctx: DocContext = {
    key: `doc${++documentCounter}`,
    pkg,
    docPath,
    rels,
    styles,
    stylesPath,
    numbering,
    numberingPath,
    theme,
    accents,
    head: selfClosing ? `${source.slice(0, body.start)}<w:body>` : source.slice(0, body.innerStart),
    tail: selfClosing ? `</w:body>${source.slice(body.end)}` : source.slice(body.innerEnd),
    sectPr: sectPr ? raw(sectPr) : null,
    page: pageOf(sectPr),
    maxDrawingId,
  };

  return { ctx, doc: N.doc.create(null, blocks) };
}

/**
 * A header or footer part, read the way the body is, with its own relationships
 * (src/docx/headers.ts). `head` and `tail` are its source around the blocks.
 */
export function importPart(ctx: DocContext, path: string): { doc: PMNode; head: string; tail: string } | null {
  const source = ctx.pkg.text(path);
  if (!source) return null;

  const root = parseXml(source);
  const importer = new Importer(ctx.pkg, path, parseRels(ctx.pkg.text(relsPathFor(path))), ctx.styles, ctx.theme, ctx.accents);
  const blocks = importer.blocks(root.children);

  if (!blocks.some((block) => block.type !== N.opaque_block)) blocks.push(N.paragraph.create());

  const selfClosing = root.innerStart === root.end;
  const open = source.slice(root.start, root.innerStart);

  return {
    doc: N.doc.create(null, blocks),
    head: selfClosing ? `${source.slice(0, root.start)}${open.replace(/\s*\/>$/, '>')}` : source.slice(0, root.innerStart),
    tail: selfClosing ? `</${root.name}>${source.slice(root.end)}` : source.slice(root.innerEnd),
  };
}

/**
 * Body content kept in another part, a footnote or an endnote say (src/notes/), read the way the
 * body is, with that part's relationships.
 */
export function importBlocks(ctx: DocContext, path: string, children: XmlEl[]): PMNode[] {
  const importer = new Importer(ctx.pkg, path, parseRels(ctx.pkg.text(relsPathFor(path))), ctx.styles, ctx.theme, ctx.accents);
  return importer.blocks(children);
}
