// ---- Unicode's mathematical alphabets ----------------------------------------------------------

/** Where each alphabet's capital A, small a and digit zero start; null where it has none. */
const ALPHABETS: Record<string, [number, number, number | null]> = {
  bold: [0x1d400, 0x1d41a, 0x1d7ce],
  italic: [0x1d434, 0x1d44e, null],
  'bold-italic': [0x1d468, 0x1d482, null],
  script: [0x1d49c, 0x1d4b6, null],
  'bold-script': [0x1d4d0, 0x1d4ea, null],
  fraktur: [0x1d504, 0x1d51e, null],
  'bold-fraktur': [0x1d56c, 0x1d586, null],
  'double-struck': [0x1d538, 0x1d552, 0x1d7d8],
  'sans-serif': [0x1d5a0, 0x1d5ba, 0x1d7e2],
  'bold-sans-serif': [0x1d5d4, 0x1d5ee, 0x1d7ec],
  'sans-serif-italic': [0x1d608, 0x1d622, null],
  'sans-serif-bold-italic': [0x1d63c, 0x1d656, null],
  monospace: [0x1d670, 0x1d68a, 0x1d7f6],
};

/** Letters that were in Unicode before the alphabets were, and sit outside them. */
const HOLES: Record<string, Record<string, string>> = {
  italic: { h: 'ℎ' },
  script: { B: 'ℬ', E: 'ℰ', F: 'ℱ', H: 'ℋ', I: 'ℐ', L: 'ℒ', M: 'ℳ', R: 'ℛ', e: 'ℯ', g: 'ℊ', o: 'ℴ' },
  fraktur: { C: 'ℭ', H: 'ℌ', I: 'ℑ', R: 'ℜ', Z: 'ℨ' },
  'double-struck': { C: 'ℂ', H: 'ℍ', N: 'ℕ', P: 'ℙ', Q: 'ℚ', R: 'ℝ', Z: 'ℤ' },
};

const GREEK_BOLD: [number, number] = [0x1d6a8, 0x1d6c2];

/** The alphabet a run's script and style select, or null for the ordinary letters. */
export function alphabetOf(scr: string | null, sty: string | null): string | null {
  const bold = sty === 'b' || sty === 'bi';
  const italic = sty === 'bi' || sty === 'i';

  switch (scr) {
    case 'script': return bold ? 'bold-script' : 'script';
    case 'fraktur': return bold ? 'bold-fraktur' : 'fraktur';
    case 'double-struck': return 'double-struck';
    case 'sans-serif': return bold ? (italic ? 'sans-serif-bold-italic' : 'bold-sans-serif') : italic ? 'sans-serif-italic' : 'sans-serif';
    case 'monospace': return 'monospace';
    default: return sty === 'b' ? 'bold' : sty === 'bi' ? 'bold-italic' : null;
  }
}

/** Text in one of the mathematical alphabets: letters and digits change, everything else stays. */
export function styled(text: string, alphabet: string | null): string {
  const base = alphabet ? ALPHABETS[alphabet] : null;
  if (!base || !alphabet) return text;

  let out = '';

  for (const ch of text) {
    const code = ch.codePointAt(0)!;
    const hole = HOLES[alphabet]?.[ch];

    if (hole) out += hole;
    else if (code >= 65 && code <= 90) out += String.fromCodePoint(base[0] + code - 65);
    else if (code >= 97 && code <= 122) out += String.fromCodePoint(base[1] + code - 97);
    else if (code >= 48 && code <= 57 && base[2] !== null) out += String.fromCodePoint(base[2] + code - 48);
    else if (alphabet === 'bold' && code >= 0x391 && code <= 0x3a9) out += String.fromCodePoint(GREEK_BOLD[0] + code - 0x391);
    else if (alphabet === 'bold' && code >= 0x3b1 && code <= 0x3c9) out += String.fromCodePoint(GREEK_BOLD[1] + code - 0x3b1);
    else out += ch;
  }

  return out;
}
