// The toolbar's Equation button: a new inline or display equation, or the selected one edited.

import type { EditorView } from 'prosemirror-view';
import { closePopover, h, popover } from '../ui/dom';
import { editEquation, insertEquation, selectedEquation } from './plugin';

export const EQUATION_ICON =
  '<svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round">' +
  '<path d="M1.5 9l1.5-1 2 5 3-10.5h6.5M9 7.5l4 5M13 7.5l-4 5"/></svg>';

export function equationMenu(anchor: HTMLElement, host: { tab(): { view: EditorView } | null }): void {
  const tab = host.tab();
  if (!tab) return;

  const { view } = tab;
  const selected = selectedEquation(view.state);
  const item = (label: string, action: () => void) => h('button', { class: 'menu-item', onclick: () => (closePopover(), action()) }, label);

  popover(
    anchor,
    h(
      'div',
      null,
      selected ? item('Edit equation…', () => void editEquation(view, selected.pos)) : null,
      item('Inline equation… (Alt+=)', () => void insertEquation(view, false)),
      item('Display equation…', () => void insertEquation(view, true)),
    ),
  );
}
