// Tab stops: `w:tabs` read from a paragraph and its style chain, and where a tab character ends.
//
// Positions are in twips from the start of the text column (the page margin, or a cell's inside
// edge), as Word measures them, whatever the paragraph's own indent. Everything here is plain
// arithmetic, so the editor's view plugin (editor/tabs.ts) only has to measure the text.

import type { Styles } from './styles';
import type { XmlEl } from './xml';
import { childrenNamed, child, parseFragment } from './xml';
import type { DocxPackage, Rel } from './package';
import { relKind, resolveTarget } from './package';

export type TabAlign = 'left' | 'center' | 'right' | 'decimal' | 'bar';
export type TabLeader = 'none' | 'dot' | 'hyphen' | 'underscore' | 'heavy' | 'middleDot';

export interface TabStop {
  /** Twips from the start of the text column. */
  pos: number;
  align: TabAlign;
  leader: TabLeader;
}

/** Word's default when settings.xml names none: half an inch. */
export const DEFAULT_TAB_INTERVAL = 720;

const ALIGNS: Record<string, TabAlign> = {
  left: 'left', start: 'left', center: 'center', right: 'right', end: 'right', decimal: 'decimal', bar: 'bar', num: 'left',
};

const LEADERS = new Set<string>(['dot', 'hyphen', 'underscore', 'heavy', 'middleDot']);

/**
 * Applies one `w:tabs` element to the stops inherited so far: a `clear` takes away the stop at its
 * position, anything else adds one or replaces the one at the same position.
 */
export function applyTabs(inherited: readonly TabStop[], tabs: XmlEl | null): TabStop[] {
  const stops = inherited.slice();
  if (!tabs) return stops;

  for (const tab of childrenNamed(tabs, 'w:tab')) {
    const pos = Math.round(Number(tab.attrs['w:pos']));
    const kind = tab.attrs['w:val'] ?? 'left';
    if (!Number.isFinite(pos)) continue;

    const at = stops.findIndex((stop) => stop.pos === pos);
    if (at >= 0) stops.splice(at, 1);
    if (kind === 'clear') continue;

    const leader = tab.attrs['w:leader'] ?? 'none';
    stops.push({ pos, align: ALIGNS[kind] ?? 'left', leader: LEADERS.has(leader) ? (leader as TabLeader) : 'none' });
  }

  return stops.sort((a, b) => a.pos - b.pos);
}

/** The stops a paragraph has: its style chain's, then its own `w:pPr` (as the source the editor keeps). */
export function paragraphTabs(styles: Styles, styleId: string | null, ppr: string | null): TabStop[] {
  let stops: TabStop[] = applyTabs([], child(styles.docPPr, 'w:tabs'));

  for (const def of styles.chain(styleId ?? styles.defaultParagraph)) {
    stops = applyTabs(stops, child(def.pPr, 'w:tabs'));
  }

  const own = parseFragment(ppr);
  return applyTabs(stops, own ? (own.children.find((el) => el.name === 'w:tabs') ?? null) : null);
}

/** `w:defaultTabStop` from settings.xml, in twips. */
export function defaultTabInterval(pkg: DocxPackage, docPath: string, rels: Rel[]): number {
  const rel = rels.find((r) => relKind(r) === 'settings' && !r.external);
  const xml = rel ? pkg.text(resolveTarget(docPath, rel.target)) : null;
  const found = xml ? /<w:defaultTabStop\b[^>]*\bw:val="(\d+)"/.exec(xml) : null;
  const value = found ? Number(found[1]) : 0;

  return value > 0 ? value : DEFAULT_TAB_INTERVAL;
}

export interface TabRun {
  /** Where the tab character starts: px from the start of the text column. */
  x: number;
  /** The width of the text after the tab, up to the next tab or the end of the line. */
  follow: number;
  /** The width of that text up to its decimal separator; `follow` if it has none. */
  beforeDecimal: number;
}

export interface TabPlacement {
  /** How wide the tab character is drawn, in px. */
  width: number;
  leader: TabLeader;
  align: TabAlign;
}

/**
 * Where a tab ends. Stops are in px here (twips / 15). The next stop past `x` that is not a bar
 * takes the tab; past the last one, the next multiple of the default interval does. `implicit` is
 * the hanging indent, which Word treats as a left stop of its own.
 */
export function placeTab(stops: readonly TabStop[], intervalPx: number, run: TabRun, implicit: number | null = null): TabPlacement {
  const usable = stops.filter((stop) => stop.align !== 'bar').map((stop) => ({ ...stop, px: stop.pos / 15 }));

  if (implicit !== null && implicit > 0 && !usable.some((stop) => Math.abs(stop.px - implicit) < 0.5)) {
    usable.push({ pos: implicit * 15, px: implicit, align: 'left', leader: 'none' });
    usable.sort((a, b) => a.px - b.px);
  }

  const epsilon = 0.5;
  const stop = usable.find((s) => s.px > run.x + epsilon);

  if (!stop) {
    const step = intervalPx > 0 ? intervalPx : DEFAULT_TAB_INTERVAL / 15;
    const next = (Math.floor((run.x + epsilon) / step) + 1) * step;
    return { width: Math.max(0, next - run.x), leader: 'none', align: 'left' };
  }

  let width = stop.px - run.x;

  if (stop.align === 'right') width -= run.follow;
  else if (stop.align === 'center') width -= run.follow / 2;
  else if (stop.align === 'decimal') width -= run.beforeDecimal;

  return { width: Math.max(0, width), leader: stop.leader, align: stop.align };
}
