// CITATION and BIBLIOGRAPHY as field types (see the top of fields/update.ts), and the commands
// that insert them and bring them up to date when the sources or the style change.

import type { Mark, Node as PMNode } from 'prosemirror-model';
import type { Command, EditorState, Transaction } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import { escAttr } from '../docx/xml';
import { schema } from '../editor/schema';
import { fieldCodes, fieldNodes } from '../fields/build';
import { type Field, scanFields } from '../fields/model';
import { type UpdateEnv, registerField, updateFields } from '../fields/update';
import { type Citation, citationInstr, parseCitation } from './instr';
import type { Source } from './model';
import { findSource, library } from './store';
import type { NoteForm } from './chicago-notes';
import { formatNote } from './chicago-notes';
import { type CiteItem, type Cited, type Run, LIST_TITLES, citedContext, formatCitation, formatEntry, sortSources } from './styles';

const N = schema.nodes;
const M = schema.marks;

export const CITE_TYPES = ['CITATION', 'BIBLIOGRAPHY'];

export const NO_SOURCES = 'There are no sources in the current document.';

/** Citations kept in footnotes (Chicago notes and bibliography), filled in by src/cite/note-cite.ts. */
export const noteHooks: {
  /** While a note's citations are rendered: the form each item of `field` takes; null outside notes. */
  form: ((field: Field, doc: PMNode) => ((item: CiteItem) => NoteForm) | null) | null;
  /** The tags cited in the footnotes of the text `doc`. */
  tags: ((ctx: DocContext, doc: PMNode) => string[]) | null;
  render: ((ctx: DocContext, doc: PMNode) => boolean) | null;
  insert: ((ctx: DocContext, citation: Citation) => Command) | null;
} = { form: null, tags: null, render: null, insert: null };

interface CiteState {
  cited: Source[];
  context: Cited;
}

/** The sources the document cites, in the order it first cites them. Worked out once per update. */
function citeState(env: { doc: PMNode; ctx: DocContext; memo?: Map<string, unknown> }): CiteState {
  const cached = env.memo?.get('cite') as CiteState | undefined;
  if (cached) return cached;

  const cited: Source[] = [];
  for (const field of scanFields(env.doc).fields) {
    if (field.type !== 'CITATION') continue;
    for (const part of parseCitation(field.instr).parts) {
      const source = findSource(env.ctx, part.tag);
      if (source && !cited.includes(source)) cited.push(source);
    }
  }

  for (const tag of noteHooks.tags?.(env.ctx, env.doc) ?? []) {
    const source = findSource(env.ctx, tag);
    if (source && !cited.includes(source)) cited.push(source);
  }

  const state = { cited, context: citedContext(cited) };
  env.memo?.set('cite', state);
  return state;
}

/** Runs as text nodes: italic runs get the italic mark, the others lose it. */
export function runNodes(runs: Run[], base: readonly Mark[]): PMNode[] {
  const plain = M.italic.removeFromSet(base);
  return runs.filter((r) => r.text).map((r) => schema.text(r.text, r.italic ? M.italic.create().addToSet(plain) : plain));
}

/** The formatting a field's result has now: of its first text, or of its codes. */
function baseMarks(doc: PMNode, field: Field): readonly Mark[] {
  let marks: readonly Mark[] | null = null;
  doc.nodesBetween(field.resultFrom, field.resultTo, (node) => {
    if (marks) return false;
    if (node.isText) marks = node.marks;
    return !node.isInline;
  });
  return marks ?? (field.separate?.node ?? field.begin?.node)?.marks ?? [];
}

function citationUpdate(field: Field, env: UpdateEnv) {
  const citation = parseCitation(field.instr);
  const items = citation.parts.map((part) => ({ ...part, source: findSource(env.ctx, part.tag) }));

  // Sources the document does not have: the result Word last showed stays.
  if (!items.length || items.every((item) => !item.source)) return null;

  const { context } = citeState(env);
  const form = noteHooks.form?.(field, env.doc);
  const runs = form ? formatNote(items, form) : formatCitation(library(env.ctx).style, items, context);
  return { inline: runNodes(runs, baseMarks(env.doc, field)) };
}

/** The style bibliography entries take, added the way Word defines it when the document has none. */
export function bibliographyStyle(ctx: DocContext): string {
  const existing = ctx.styles.byName('Bibliography');
  if (existing) return existing.id;

  const normal = ctx.styles.defaultParagraph;
  return ctx.styles.addDefinition(
    'Bibliography',
    (id) =>
      `<w:style w:type="paragraph" w:styleId="${escAttr(id)}"><w:name w:val="Bibliography"/>` +
      (normal ? `<w:basedOn w:val="${escAttr(normal)}"/><w:next w:val="${escAttr(normal)}"/>` : '') +
      '<w:uiPriority w:val="37"/><w:unhideWhenUsed/><w:pPr><w:ind w:left="720" w:hanging="720"/></w:pPr></w:style>',
  );
}

/** A hanging indent of half an inch on every entry, as Word's styles write their lists. */
const ENTRY_PPR = '<w:ind w:left="720" w:hanging="720"/>';

/** The bibliography's paragraphs, for the sources a document cites. */
export function bibliographyBlocks(doc: PMNode, ctx: DocContext, memo?: Map<string, unknown>): PMNode[] {
  const { cited, context } = citeState({ doc, ctx, memo });
  const styleId = bibliographyStyle(ctx);
  const style = library(ctx).style;

  if (!cited.length) return [N.paragraph.create({ styleId }, schema.text(NO_SOURCES))];

  return sortSources(style, cited).map((source) => N.paragraph.create({ styleId, ppr: ENTRY_PPR }, runNodes(formatEntry(style, source, context), [])));
}

registerField('CITATION', { phase: 1, live: true, onSave: false, update: citationUpdate });
registerField('BIBLIOGRAPHY', {
  phase: 1,
  live: true,
  onSave: false,
  update: (_field, env) => ({ blocks: bibliographyBlocks(env.doc, env.ctx, env.memo) }),
});

// ---- Commands --------------------------------------------------------------------------------------------

/** Re-renders every citation and bibliography: after the sources or the style changed. */
export function refreshCitations(ctx: DocContext): Command {
  return (state: EditorState, dispatch?: (tr: Transaction) => void) => {
    const tr = state.tr;
    const changed = updateFields(tr, ctx, { types: CITE_TYPES });
    const notes = dispatch ? (noteHooks.render?.(ctx, state.doc) ?? false) : false;
    if (changed && dispatch) dispatch(tr);
    return changed || notes;
  };
}

/** Inserts a citation at the cursor, in place of the selection. */
export function insertCitation(ctx: DocContext, citation: Citation): Command {
  // Chicago notes and bibliography cites in a footnote.
  if (library(ctx).style === 'chicago-nb' && noteHooks.insert) return noteHooks.insert(ctx, citation);

  return (state, dispatch) => {
    if (!citation.parts.length) return false;
    if (!dispatch) return true;

    const { from, to } = state.selection;
    const marks = (state.storedMarks ?? state.selection.$from.marks()).filter((m) => m.type !== M.link);
    const tr = state.tr.replaceWith(from, to, fieldNodes(citationInstr(citation), ' ', marks));
    updateFields(tr, ctx, { types: CITE_TYPES });
    dispatch(tr.scrollIntoView());
    return true;
  };
}

/** Replaces a citation's instruction (after the citation dialog edited it). */
export function editCitation(ctx: DocContext, field: Field, citation: Citation): Command {
  return (state, dispatch) => {
    if (!field.begin || !field.end || field.simple) return false;
    if (!dispatch) return true;

    // The field is made afresh, with the formatting and content control its result had.
    const marks = baseMarks(state.doc, field).filter((m) => m.type !== M.link);
    const tr = state.tr.replaceWith(field.from, field.to, fieldNodes(citationInstr(citation), ' ', marks));
    updateFields(tr, ctx, { types: CITE_TYPES });
    dispatch(tr);
    return true;
  };
}

/** The citation the cursor is in, if it is in one. */
export function citationAt(state: EditorState): Field | null {
  const pos = state.selection.from;
  return scanFields(state.doc).fields.find((f) => f.type === 'CITATION' && pos >= f.from && pos <= f.to) ?? null;
}

export function findBibliography(doc: PMNode): Field | null {
  return scanFields(doc).fields.find((field) => field.type === 'BIBLIOGRAPHY') ?? null;
}

/**
 * Inserts a bibliography: a heading in the style's words ("References", "Works Cited") and the
 * BIBLIOGRAPHY field, before the paragraph the cursor is in (in place of it, if it is empty).
 * With one in the document already, updates that one.
 */
export function insertBibliography(ctx: DocContext): Command {
  return (state, dispatch) => {
    if (!dispatch) return true;

    const tr = state.tr;
    const existing = findBibliography(state.doc);
    if (existing) {
      updateFields(tr, ctx, { types: CITE_TYPES });
      dispatch(tr.scrollIntoView());
      return true;
    }

    const { $from } = state.selection;
    const block = $from.depth ? $from.node(1) : null;
    const at = $from.depth ? $from.before(1) : state.selection.from;
    const replace = block && block.type === N.paragraph && block.content.size === 0 && !block.attrs.sectPr;
    const headingId = ctx.styles.ensureBuiltin('heading 1');
    const heading = N.paragraph.create({ styleId: headingId }, schema.text(LIST_TITLES[library(ctx).style]));
    const [begin, end] = fieldCodes('BIBLIOGRAPHY \\l 1033');
    const styleId = bibliographyStyle(ctx);

    tr.replaceWith(at, replace ? at + block!.nodeSize : at, [heading, N.paragraph.create({ styleId }, [begin, end])]);
    updateFields(tr, ctx, { types: CITE_TYPES });
    dispatch(tr.scrollIntoView());
    return true;
  };
}
