// The document as the editor holds it.
//
// It follows Word's model rather than HTML's: a list item is a paragraph with a list id and a
// level, a heading is a paragraph with a style, and character formatting is a set of marks that
// map one to one onto run properties.
//
// Wherever a node or mark came from a file, it keeps the XML it was read from (`ppr`, `tcPr`,
// `raw`, `tag`, ...). The editor shows what it understands of that XML and changes only the parts
// it manages; export.ts writes the rest back as it came. Things it cannot show at all are
// `opaque` nodes: placeholders that carry their XML through an edit untouched.

import { type DOMOutputSpec, type MarkSpec, type NodeSpec, type Node as PMNode, Schema } from 'prosemirror-model';
import { chartSvg } from '../chart/draw';
import { parseSpec } from '../chart/model';
import { type Decls, DEFAULT_THEME, alignCss, cellDecls, fontFamilyCss, inlineCss, paraDecls, runDecls, twipsToPt, underlineDecls } from '../docx/props';
import { parseFragment } from '../docx/xml';
import { shapeSvg } from '../shapes/geometry';
import { mathNodeSpec } from '../math/node';

let keyCounter = 0;

/** A number no other wrapper mark has, so two links side by side stay two links. */
export const nextKey = (): number => ++keyCounter;

const declCache = new Map<string, Decls>();

function cached(kind: string, source: string | null, make: () => Decls): Decls {
  if (!source) return {};

  const key = kind + source;
  let d = declCache.get(key);

  if (!d) {
    d = make();
    if (declCache.size > 4000) declCache.clear();
    declCache.set(key, d);
  }

  return d;
}

/** A paragraph's own formatting (the insides of its `w:pPr`) as CSS declarations. */
export const pprDecls = (ppr: string | null): Decls => cached('p', ppr, () => paraDecls(parseFragment(ppr)));
const tcprDecls = (tcPr: string | null): Decls => cached('c', tcPr, () => cellDecls(parseFragment(tcPr)));
const rprDecls = (xml: string | null): Decls => cached('r', xml, () => runDecls(parseFragment(xml), DEFAULT_THEME));

function withCss(attrs: Record<string, string>, d: Decls, extraClass = ''): Record<string, string> {
  const { style, classes } = inlineCss(d);
  const all = extraClass ? [extraClass, ...classes] : classes;

  if (style) attrs.style = style;
  if (all.length) attrs.class = all.join(' ');

  return attrs;
}

// ---- Reading pasted HTML -------------------------------------------------------------------

function alignFromDom(dom: HTMLElement): string | null {
  const align = dom.style.textAlign || dom.getAttribute('align') || '';

  return align === 'center' || align === 'right' ? align : align === 'justify' ? 'both' : null;
}

/** "li:bullet:1" for an item in a nested bullet list: the list's kind and how deep it is. */
function listHint(li: Element): string {
  let depth = -1;
  let kind = 'bullet';

  for (let at: Element | null = li.parentElement; at; at = at.parentElement) {
    if (at.tagName === 'UL' || at.tagName === 'OL') {
      if (depth < 0) kind = at.tagName === 'OL' ? 'number' : 'bullet';
      depth++;
    }
  }

  return `li:${kind}:${Math.max(0, Math.min(8, depth))}`;
}

/** rgb(1, 2, 3) or #abc as #RRGGBB; null for anything else, and for black, which is the default. */
export function cssColorToHex(value: string): string | null {
  let hexValue: string | null = null;
  const rgb = /^rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)(?:[\s,/]+([\d.]+%?))?\s*\)$/.exec(value.trim());

  if (rgb) {
    if (rgb[4] !== undefined && parseFloat(rgb[4]) === 0) return null;
    hexValue = `#${[rgb[1], rgb[2], rgb[3]].map((part) => Math.min(255, Number(part)).toString(16).padStart(2, '0')).join('')}`;
  } else if (/^#[0-9a-f]{6}$/i.test(value.trim())) {
    hexValue = value.trim();
  } else if (/^#[0-9a-f]{3}$/i.test(value.trim())) {
    hexValue = `#${[...value.trim().slice(1)].map((c) => c + c).join('')}`;
  }

  return hexValue ? hexValue.toUpperCase() : null;
}

function cellFromDom(dom: HTMLElement) {
  const widths = dom.getAttribute('data-colwidth');
  const colspan = Number(dom.getAttribute('colspan') || 1);
  const colwidth = widths && /^\d+(,\d+)*$/.test(widths) ? widths.split(',').map(Number) : null;

  return {
    colspan,
    rowspan: Number(dom.getAttribute('rowspan') || 1),
    colwidth: colwidth && colwidth.length === colspan ? colwidth : null,
  };
}

// ---- Nodes ---------------------------------------------------------------------------------

function paragraphDom(node: PMNode): DOMOutputSpec {
  const a = node.attrs;
  const d = { ...pprDecls(a.ppr) };

  if (a.align) d['text-align'] = alignCss(a.align);
  if (a.indent !== null) d['margin-left'] = `${twipsToPt(a.indent)}pt`;

  const attrs = withCss({ 'data-style': a.styleId ?? '' }, d);
  if (a.sectPr) attrs['data-sect'] = '1';

  return ['p', attrs, 0];
}

function cellDom(tag: string) {
  return (node: PMNode): DOMOutputSpec => {
    const a = node.attrs;
    const attrs: Record<string, string> = {};

    if (a.colspan !== 1) attrs.colspan = String(a.colspan);
    if (a.rowspan !== 1) attrs.rowspan = String(a.rowspan);
    if (a.colwidth) attrs['data-colwidth'] = a.colwidth.join(',');

    return [tag, withCss(attrs, tcprDecls(a.tcPr)), 0];
  };
}

const cellAttrs = {
  colspan: { default: 1 },
  rowspan: { default: 1 },
  colwidth: { default: null },
  /** The insides of the cell's `w:tcPr`, as source. */
  tcPr: { default: null },
};

const nodes: Record<string, NodeSpec> = {
  // Sections. The document stays a flat list of blocks: a paragraph whose `sectPr` is set ends
  // a section (as `w:sectPr` in its `w:pPr` does in Word), and the body's last section has its
  // properties in the doc's own `sectPr`, or, while that is null, in `ctx.sectPr` as read.
  // There is no section node, so a walk over the blocks (`doc.descendants`, `doc.forEach`) sees
  // them as before; src/columns/model.ts `sectionRanges` gives each section's extent and
  // properties (columns among them) when they are wanted. A section's properties are kept as
  // source, so a section nobody changed is written back byte for byte.
  doc: {
    content: 'block+',
    attrs: {
      /** The body's last `w:sectPr`, as source, once changed in the editor (an undoable step); null for `ctx.sectPr`. */
      sectPr: { default: null },
      /** The style editor's changes (StyleEdits in docx/styles.ts), so they undo like any other. */
      styleEdits: { default: null },
    },
  },

  paragraph: {
    content: 'inline*',
    group: 'block',
    attrs: {
      styleId: { default: null },
      /** `w:jc`: left, center, right, both, ... or null for whatever the style says. */
      align: { default: null },
      /** The list this paragraph is an item of. 0 switches off a list its style brings. */
      numId: { default: null },
      ilvl: { default: 0 },
      /** A left indent set here, in twips, over the one in `ppr`. */
      indent: { default: null },
      /** The rest of the paragraph's `w:pPr`, as source. */
      ppr: { default: null },
      /** A section break that ends with this paragraph, as source. */
      sectPr: { default: null },
      /** Set on pasted HTML only (h1, li:bullet:0, ...), then turned into a style or a list. */
      hint: { default: null },
    },
    parseDOM: [
      {
        tag: 'p',
        getAttrs: (dom) => {
          const li = dom.parentElement?.tagName === 'LI' && !dom.previousElementSibling ? dom.parentElement : null;
          return { align: alignFromDom(dom), hint: li ? listHint(li) : null };
        },
      },
      ...[1, 2, 3, 4, 5, 6].map((level) => ({ tag: `h${level}`, attrs: { hint: `h${level}` } })),
      { tag: 'li', getAttrs: (dom) => (dom.querySelector(':scope > p, :scope > div') ? false : { hint: listHint(dom) }) },
      { tag: 'pre', preserveWhitespace: 'full' as const },
    ],
    toDOM: paragraphDom,
  },

  table: {
    content: 'table_row+',
    tableRole: 'table',
    isolating: true,
    group: 'block',
    attrs: {
      /** The table's `w:tblPr` and `w:tblGrid` elements, as source. */
      tblPr: { default: null },
      grid: { default: null },
      /** For the screen: the table style's id, and whether the table draws its grid. */
      tstyle: { default: null },
      borders: { default: true },
    },
    parseDOM: [{ tag: 'table' }],
    toDOM: (node) => ['table', { 'data-tstyle': node.attrs.tstyle ?? '', class: node.attrs.borders ? 'grid' : 'nogrid' }, ['tbody', 0]],
  },

  table_row: {
    content: '(table_cell | table_header)*',
    tableRole: 'row',
    /** What comes before the row's cells (`w:tblPrEx`, `w:trPr`), as source. */
    attrs: { trPr: { default: null } },
    parseDOM: [{ tag: 'tr' }],
    toDOM: () => ['tr', 0],
  },

  table_cell: {
    content: 'block+',
    attrs: cellAttrs,
    tableRole: 'cell',
    isolating: true,
    parseDOM: [{ tag: 'td', getAttrs: cellFromDom }],
    toDOM: cellDom('td'),
  },

  // Word has no separate header cell; this exists because the table tools expect the role.
  table_header: {
    content: 'block+',
    attrs: cellAttrs,
    tableRole: 'header_cell',
    isolating: true,
    parseDOM: [{ tag: 'th', getAttrs: cellFromDom }],
    toDOM: cellDom('th'),
  },

  /** A wrapper the editor keeps around blocks without knowing what it is for: a content control, say. */
  block_wrap: {
    content: 'block+',
    group: 'block',
    attrs: { open: { default: '' }, close: { default: '' } },
    toDOM: () => ['div', { class: 'block-wrap' }, 0],
  },

  /** Block-level XML kept as it came. Hidden when it has nothing to show (a bookmark's end, say). */
  opaque_block: {
    group: 'block',
    atom: true,
    selectable: true,
    attrs: { raw: { default: '' }, hidden: { default: true }, label: { default: '' } },
    toDOM: (node) => ['div', { class: node.attrs.hidden ? 'opaque-block hidden' : 'opaque-block', contenteditable: 'false' }, node.attrs.label],
  },

  text: { group: 'inline' },

  hard_break: {
    inline: true,
    group: 'inline',
    selectable: false,
    attrs: { raw: { default: null } },
    parseDOM: [{ tag: 'br' }],
    toDOM: () => ['br'],
  },

  page_break: {
    inline: true,
    group: 'inline',
    atom: true,
    attrs: { column: { default: false } },
    toDOM: (node) => ['span', { class: 'page-break', contenteditable: 'false', 'data-label': node.attrs.column ? 'Column break' : 'Page break' }],
  },

  image: {
    inline: true,
    group: 'inline',
    atom: true,
    draggable: true,
    attrs: {
      /** A data: URL, or '' for a format the editor cannot draw. */
      src: { default: '' },
      w: { default: 100 },
      h: { default: 100 },
      /** The `w:drawing` the picture was read from, and the size it had there. */
      raw: { default: null },
      ow: { default: null },
      oh: { default: null },
      alt: { default: '' },
    },
    parseDOM: [
      {
        tag: 'img[src]',
        getAttrs: (dom) => {
          const src = dom.getAttribute('src') ?? '';
          if (!src.startsWith('data:image/')) return false;

          const image = dom as HTMLImageElement;
          return { src, w: image.width || image.naturalWidth || 200, h: image.height || image.naturalHeight || 150, alt: image.alt };
        },
      },
    ],
    toDOM: (node) => {
      const { src, w, h, alt } = node.attrs;

      return src
        ? ['img', { src, width: String(w), height: String(h), alt }]
        : ['span', { class: 'image-missing', style: `width:${w}px;height:${h}px`, contenteditable: 'false' }, alt || 'Picture'];
    },
  },

  /** A chart: its kind, title and sheet as text (chart/model.ts), drawn by the editor itself. */
  chart: {
    inline: true,
    group: 'inline',
    atom: true,
    draggable: true,
    attrs: {
      spec: { default: '' },
      w: { default: 528 },
      h: { default: 307 },
      /**
       * From a file: the `w:drawing` the chart was read from, the chart part it points at, and
       * the size and the chart it had there. Export writes a chart afresh only if it differs.
       */
      raw: { default: null },
      part: { default: null },
      ow: { default: null },
      oh: { default: null },
      orig: { default: null },
    },
    // For the clipboard; on the page a chart is shown by its node view (view.ts).
    toDOM: (node) => {
      const spec = parseSpec(node.attrs.spec);
      const dom = document.createElement('span');

      dom.className = 'chart';
      if (spec) dom.innerHTML = chartSvg(spec, node.attrs.w, node.attrs.h);

      return dom;
    },
  },

  /** An equation (OMML), drawn as MathML: math/node.ts. */
  math: mathNodeSpec,

  /**
   * A shape or text box (src/shapes/). `spec` is what it looks like, as JSON (shapes/model.ts);
   * `text` its text box's content as an editor document in JSON, null if it has none. From a file:
   * the XML it came from and the spec it had there; export patches in only what changed.
   */
  shape: {
    inline: true,
    group: 'inline',
    atom: true,
    draggable: true,
    attrs: { raw: { default: null }, spec: { default: '' }, orig: { default: null }, text: { default: null }, edited: { default: false } },
    // For the clipboard; on the page a shape is shown by its node view (shapes/view.ts).
    toDOM: (node) => {
      const dom = document.createElement('span');
      dom.className = 'shape';
      try {
        dom.innerHTML = shapeSvg(JSON.parse(node.attrs.spec));
      } catch {
        // A spec that does not read: an empty box.
      }
      return dom;
    },
  },

  /**
   * Inline XML kept as it came. `kind` says where it goes back: 'run' inside a run of its own,
   * with the formatting its marks give; 'para' straight into the paragraph.
   */
  opaque: {
    inline: true,
    group: 'inline',
    atom: true,
    attrs: { raw: { default: '' }, kind: { default: 'run' }, look: { default: 'hidden' }, label: { default: '' } },
    toDOM: (node) => ['span', { class: `opaque opaque-${node.attrs.look}`, title: node.attrs.label, contenteditable: 'false' }],
  },
};

// ---- Marks ---------------------------------------------------------------------------------
// Listed from the outside in: a link wraps a font, which wraps a colour, which wraps an underline.
// The colour sits outside underline and strike so that their line takes the text's colour.

const toggle = (tagName: string, cssProperty: string, offValue: string, parse: MarkSpec['parseDOM']): MarkSpec => ({
  /** False for a run that switches off what its style switches on. */
  attrs: { on: { default: true } },
  parseDOM: parse,
  toDOM: (mark) => (mark.attrs.on ? [tagName, 0] : ['span', { style: `${cssProperty}:${offValue}` }, 0]),
});

const wrapperAttrs = { depth: { default: 0 }, k: { default: 0 } };

const marks: Record<string, MarkSpec> = {
  link: {
    attrs: {
      href: { default: '' },
      /** From a file: the `w:hyperlink` opening tag, its relationship id, and where that pointed. */
      tag: { default: null },
      rid: { default: null },
      orig: { default: null },
      ...wrapperAttrs,
    },
    inclusive: false,
    parseDOM: [{ tag: 'a[href]', getAttrs: (dom) => ({ href: dom.getAttribute('href') ?? '', k: nextKey() }) }],
    toDOM: (mark) => ['a', { href: mark.attrs.href, title: mark.attrs.href, class: 'link' }, 0],
  },

  /** A tracked change: shown, and kept, but not yet something the editor records or resolves. */
  track: {
    attrs: { kind: { default: 'ins' }, tag: { default: '' }, ...wrapperAttrs },
    inclusive: false,
    excludes: '',
    toDOM: (mark) => [mark.attrs.kind === 'del' || mark.attrs.kind === 'moveFrom' ? 'del' : 'ins', { class: 'track' }, 0],
  },

  /** Any other element that wraps runs (an inline content control, a simple field), kept as source. */
  wrap: {
    attrs: { open: { default: '' }, close: { default: '' }, ...wrapperAttrs },
    inclusive: false,
    excludes: '',
    toDOM: () => ['span', { class: 'wrap' }, 0],
  },

  charStyle: {
    attrs: { id: { default: '' } },
    toDOM: (mark) => ['span', { 'data-cs': mark.attrs.id }, 0],
  },

  fontFamily: {
    attrs: { name: { default: '' }, raw: { default: null } },
    toDOM: (mark) => ['span', { style: `font-family:${fontFamilyCss(mark.attrs.name)}` }, 0],
  },

  fontSize: {
    /** In half points, as the file has it. */
    attrs: { size: { default: 22 }, raw: { default: null } },
    toDOM: (mark) => ['span', { style: `font-size:${mark.attrs.size / 2}pt` }, 0],
  },

  color: {
    /** #RRGGBB, or 'auto' for a run that asks for the default colour over its style's. */
    attrs: { value: { default: 'auto' }, raw: { default: null } },
    parseDOM: [
      {
        style: 'color',
        getAttrs: (value) => {
          const color = cssColorToHex(value);
          return color && color !== '#000000' ? { value: color } : false;
        },
      },
    ],
    toDOM: (mark) =>
      mark.attrs.value === 'auto' ? ['span', { style: 'color:var(--page-ink)' }, 0] : ['span', { class: 'c', style: `--c:${mark.attrs.value}` }, 0],
  },

  highlight: {
    attrs: { value: { default: '#FFFF00' }, raw: { default: null } },
    parseDOM: [
      {
        style: 'background-color',
        getAttrs: (value) => {
          const color = cssColorToHex(value);
          return color && color !== '#FFFFFF' ? { value: color } : false;
        },
      },
    ],
    toDOM: (mark) => ['span', { class: 'h', style: `--h:${mark.attrs.value}` }, 0],
  },

  bold: toggle('strong', 'font-weight', 'normal', [
    { tag: 'strong' },
    { tag: 'b', getAttrs: (dom) => dom.style.fontWeight !== 'normal' && null },
    { style: 'font-weight', getAttrs: (value) => /^(bold(er)?|[5-9]\d{2,})$/.test(value) && null },
  ]),

  italic: toggle('em', 'font-style', 'normal', [
    { tag: 'em' },
    { tag: 'i', getAttrs: (dom) => dom.style.fontStyle !== 'normal' && null },
    { style: 'font-style=italic' },
  ]),

  underline: {
    /** `w:u`'s value: single, double, dotted, wave, ... or none. */
    attrs: { kind: { default: 'single' }, raw: { default: null } },
    parseDOM: [{ tag: 'u' }, { style: 'text-decoration', getAttrs: (value) => value.includes('underline') && null }],
    toDOM: (mark) => {
      const { style } = inlineCss(underlineDecls(mark.attrs.kind));
      return ['span', { class: 'u', style }, 0];
    },
  },

  strike: toggle('s', 'text-decoration-line', 'none', [
    { tag: 's' },
    { tag: 'strike' },
    { style: 'text-decoration', getAttrs: (value) => value.includes('line-through') && null },
  ]),

  vert: {
    attrs: { value: { default: 'superscript' }, raw: { default: null } },
    parseDOM: [
      { tag: 'sup', attrs: { value: 'superscript' } },
      { tag: 'sub', attrs: { value: 'subscript' } },
    ],
    toDOM: (mark) => [mark.attrs.value === 'subscript' ? 'sub' : 'sup', 0],
  },

  /** Run properties the editor has no control for (small caps, language, ...), as source. */
  rawRPr: {
    attrs: { xml: { default: '' } },
    toDOM: (mark) => ['span', withCss({}, rprDecls(mark.attrs.xml)), 0],
  },
};

export const schema = new Schema({ nodes, marks });

/** The marks that stand for an element around runs, not for a property of them. */
export const WRAPPERS = new Set(['link', 'track', 'wrap']);

/** The marks the "clear formatting" command removes. */
export const FORMATTING = ['fontFamily', 'fontSize', 'color', 'highlight', 'bold', 'italic', 'underline', 'strike', 'vert', 'rawRPr', 'charStyle'];
