// Footnotes and endnotes: what the document has of them, outside the text.
//
// A note's reference stays in the text as the `opaque` node the importer makes of a
// `w:footnoteReference` / `w:endnoteReference` run (look 'footnote' / 'endnote'); its content lives
// in footnotes.xml or endnotes.xml. This store reads those parts once per document, keeps each
// note's source as it was, and its content as an editor document once it has been opened. A note
// is written back from its source unless it was edited (src/notes/io.ts).
//
// Numbering follows `w:footnotePr` / `w:endnotePr`: the document-wide ones in settings.xml, and a
// section's own in its `w:sectPr`, which win for that section.

import type { Node as PMNode } from 'prosemirror-model';
import { type DocContext, importBlocks } from '../docx/import';
import { REL_TYPE, resolveTarget } from '../docx/package';
import { type XmlEl, child, parseFragment, parseXml, raw, val } from '../docx/xml';
import { schema } from '../editor/schema';

const N = schema.nodes;
const M = schema.marks;

export type NoteKind = 'footnote' | 'endnote';
export const KINDS: readonly NoteKind[] = ['footnote', 'endnote'];

export const NOTE_REL: Record<NoteKind, string> = { footnote: `${REL_TYPE}/footnotes`, endnote: `${REL_TYPE}/endnotes` };
export const NOTE_CONTENT_TYPE: Record<NoteKind, string> = {
  footnote: 'application/vnd.openxmlformats-officedocument.wordprocessingml.footnotes+xml',
  endnote: 'application/vnd.openxmlformats-officedocument.wordprocessingml.endnotes+xml',
};

export interface Note {
  kind: NoteKind;
  id: string;
  /** `w:type`: separator, continuationSeparator, continuationNotice; null for a note of the text. */
  type: string | null;
  /** The `w:footnote` / `w:endnote` element as the file had it; null for a note made here. */
  raw: string | null;
  /** The content as an editor document, once read or written. */
  doc: PMNode | null;
  edited: boolean;
}

export interface NotePart {
  /** The part's path; null while the document has no such part. */
  path: string | null;
  /** The part's source around its notes. */
  head: string;
  tail: string;
  notes: Map<string, Note>;
}

/** `w:footnotePr` / `w:endnotePr`. */
export interface NoteProps {
  fmt: string;
  start: number;
  restart: 'continuous' | 'eachSect' | 'eachPage';
  /** footnotes: pageBottom, beneathText; endnotes: docEnd, sectEnd. */
  pos: string;
}

export const DEFAULT_PROPS: Record<NoteKind, NoteProps> = {
  footnote: { fmt: 'decimal', start: 1, restart: 'continuous', pos: 'pageBottom' },
  endnote: { fmt: 'lowerRoman', start: 1, restart: 'continuous', pos: 'docEnd' },
};

/** Note properties from a `w:footnotePr` / `w:endnotePr` element over `base`. */
export function readProps(el: XmlEl | null, base: NoteProps): NoteProps {
  if (!el) return base;

  const restart = val(el, 'w:numRestart');
  const start = val(el, 'w:numStart');

  return {
    fmt: val(el, 'w:numFmt') ?? base.fmt,
    start: start !== null && Number.isFinite(Number(start)) ? Number(start) : base.start,
    restart: restart === 'eachSect' || restart === 'eachPage' || restart === 'continuous' ? restart : base.restart,
    pos: val(el, 'w:pos') ?? base.pos,
  };
}

/** A section's note properties: its `w:sectPr` source over the document's. */
export function sectionProps(kind: NoteKind, sectPr: string | null, doc: NoteProps): NoteProps {
  const sect = parseFragment(sectPr)?.children.find((c) => c.name === 'w:sectPr') ?? null;
  return readProps(child(sect, `w:${kind}Pr`), doc);
}

// ---- Number formats --------------------------------------------------------------------------

function roman(n: number): string {
  const table: [number, string][] = [[1000, 'm'], [900, 'cm'], [500, 'd'], [400, 'cd'], [100, 'c'], [90, 'xc'], [50, 'l'], [40, 'xl'], [10, 'x'], [9, 'ix'], [5, 'v'], [4, 'iv'], [1, 'i']];
  let out = '';
  for (const [value, digits] of table) {
    while (n >= value) {
      out += digits;
      n -= value;
    }
  }
  return out;
}

/** a, b, ... z, aa, bb, ...: Word's letter numbering. */
function letters(n: number): string {
  const letter = String.fromCharCode(97 + ((n - 1) % 26));
  return letter.repeat(Math.floor((n - 1) / 26) + 1);
}

const SYMBOLS = ['*', '†', '‡', '§'];

/** A note number as `w:numFmt` says to write it. */
export function formatNumber(n: number, fmt: string): string {
  if (n < 1 && fmt !== 'decimal') return String(n);

  switch (fmt) {
    case 'lowerRoman':
      return roman(n);
    case 'upperRoman':
      return roman(n).toUpperCase();
    case 'lowerLetter':
      return letters(n);
    case 'upperLetter':
      return letters(n).toUpperCase();
    case 'chicago':
      return SYMBOLS[(n - 1) % 4].repeat(Math.floor((n - 1) / 4) + 1);
    case 'decimalZero':
      return n < 10 ? `0${n}` : String(n);
    case 'decimalEnclosedCircle':
      return n >= 1 && n <= 20 ? String.fromCharCode(0x2460 + n - 1) : String(n);
    default:
      return String(n);
  }
}

// ---- References in the text ------------------------------------------------------------------

export interface NoteRef {
  kind: NoteKind;
  id: string;
  /** Where the reference node is. */
  pos: number;
  /** The section it is in, counted from 0. */
  section: number;
  /** `w:customMarkFollows`: the text after it is the mark, and it takes no number. */
  custom: boolean;
}

const REF_RE = /^<w:(footnote|endnote)Reference\b[^>]*?\bw:id="(-?\d+)"/;

/** The note a node refers to, if it is a note reference. */
export function refOf(node: PMNode): { kind: NoteKind; id: string; custom: boolean } | null {
  if (node.type !== N.opaque || (node.attrs.look !== 'footnote' && node.attrs.look !== 'endnote')) return null;

  const m = REF_RE.exec(node.attrs.raw);
  if (!m) return null;

  return { kind: m[1] as NoteKind, id: m[2], custom: /w:customMarkFollows="(?:1|true|on)"/.test(node.attrs.raw) };
}

/** Every note reference in the text, in order. */
export function refsIn(doc: PMNode): NoteRef[] {
  const out: NoteRef[] = [];
  let section = 0;

  doc.descendants((node, pos) => {
    const ref = refOf(node);
    if (ref) out.push({ ...ref, pos, section });
    if (node.type === N.paragraph && node.attrs.sectPr) section++;
    return true;
  });

  return out;
}

/** Note ids referenced anywhere in the text, kept-as-is source included (a table or text box). */
export function referencedIds(doc: PMNode, kind: NoteKind): Set<string> {
  const ids = new Set<string>();
  const re = new RegExp(`<w:${kind}Reference\\b[^>]*?\\bw:id="(-?\\d+)"`, 'g');

  doc.descendants((node) => {
    const source = node.attrs?.raw;
    if (typeof source === 'string' && source.includes(`${kind}Reference`)) {
      for (const m of source.matchAll(re)) ids.add(m[1]);
    }
    return true;
  });

  return ids;
}

/**
 * The number each reference shows, in order. `props` gives a section's properties; `pageOf` the
 * page a reference was laid out on, for numbering that starts again on each page.
 */
export function numberRefs(refs: readonly NoteRef[], props: (kind: NoteKind, section: number) => NoteProps, pageOf: (ref: NoteRef) => number = () => 0): string[] {
  const counters: Record<NoteKind, { n: number; section: number; page: number } | null> = { footnote: null, endnote: null };

  return refs.map((ref) => {
    if (ref.custom) return '';

    const p = props(ref.kind, ref.section);
    const page = pageOf(ref);
    let c = counters[ref.kind];

    if (!c || (p.restart === 'eachSect' && c.section !== ref.section) || (p.restart === 'eachPage' && c.page !== page)) {
      c = { n: p.start, section: ref.section, page };
    } else {
      c = { n: c.n + 1, section: ref.section, page };
    }

    counters[ref.kind] = c;
    return formatNumber(c.n, p.fmt);
  });
}

// ---- The store ------------------------------------------------------------------------------

export class NoteStore {
  readonly parts: Record<NoteKind, NotePart>;
  /** The document-wide properties from settings.xml. */
  readonly props: Record<NoteKind, NoteProps>;
  /** The notes the text referred to when it was opened; null until the editor has looked. */
  loadedRefs: Record<NoteKind, Set<string> | null> = { footnote: null, endnote: null };
  /** Goes up with every change, so what is drawn of the notes knows to draw again. */
  version = 0;
  private readonly listeners = new Set<() => void>();

  constructor(private readonly ctx: DocContext) {
    this.parts = { footnote: this.readPart('footnote'), endnote: this.readPart('endnote') };

    const settingsRel = ctx.rels.find((rel) => rel.type === `${REL_TYPE}/settings`);
    let settings: XmlEl | null = null;

    try {
      const source = settingsRel ? ctx.pkg.text(resolveTarget(ctx.docPath, settingsRel.target)) : null;
      settings = source ? parseXml(source) : null;
    } catch {
      settings = null;
    }

    this.props = {
      footnote: readProps(child(settings, 'w:footnotePr'), DEFAULT_PROPS.footnote),
      endnote: readProps(child(settings, 'w:endnotePr'), DEFAULT_PROPS.endnote),
    };
  }

  private readPart(kind: NoteKind): NotePart {
    const empty: NotePart = { path: null, head: '', tail: '', notes: new Map() };
    const rel = this.ctx.rels.find((r) => r.type === NOTE_REL[kind] && !r.external);
    if (!rel) return empty;

    const path = resolveTarget(this.ctx.docPath, rel.target);
    const source = this.ctx.pkg.text(path);
    if (!source) return { ...empty, path };

    let root: XmlEl;
    try {
      root = parseXml(source);
    } catch {
      return { ...empty, path };
    }

    const notes = new Map<string, Note>();

    for (const el of root.children) {
      if (el.name !== `w:${kind}`) continue;
      const id = el.attrs['w:id'] ?? '';
      notes.set(id, { kind, id, type: el.attrs['w:type'] ?? null, raw: raw(el), doc: null, edited: false });
    }

    return { path, head: source.slice(0, root.innerStart), tail: source.slice(root.innerEnd), notes };
  }

  get(kind: NoteKind, id: string): Note | undefined {
    return this.parts[kind].notes.get(id);
  }

  /** A note's content as an editor document, read from its source the first time. */
  docOf(note: Note): PMNode {
    if (!note.doc) {
      let blocks: PMNode[] = [];

      try {
        const el = note.raw ? parseXml(note.raw) : null;
        blocks = el && this.parts[note.kind].path ? importBlocks(this.ctx, this.parts[note.kind].path as string, el.children) : [];
      } catch {
        blocks = [];
      }

      if (!blocks.some((b) => b.type === N.paragraph || b.type === N.table)) blocks.push(N.paragraph.create());
      note.doc = N.doc.create(null, blocks);
    }

    return note.doc;
  }

  setDoc(note: Note, doc: PMNode): void {
    if (note.doc && note.doc.eq(doc)) return;

    note.doc = doc;
    note.edited = true;
    this.changed();
  }

  /** A new, empty note of the text; returns its id. */
  create(kind: NoteKind): Note {
    const notes = this.parts[kind].notes;
    let max = 0;
    for (const id of notes.keys()) max = Math.max(max, Number(id) || 0);

    const id = String(max + 1);
    const note: Note = { kind, id, type: null, raw: null, doc: emptyNoteDoc(this.ctx, kind), edited: true };

    notes.set(id, note);
    this.changed();
    return note;
  }

  /** The properties numbering a section's notes. */
  sectionProps(kind: NoteKind, sectPr: string | null): NoteProps {
    return sectionProps(kind, sectPr, this.props[kind]);
  }

  onChange(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  changed(): void {
    this.version++;
    for (const listener of this.listeners) listener();
  }
}

const stores = new WeakMap<DocContext, NoteStore>();

/** The notes of an open document, read the first time they are asked for. */
export function notesOf(ctx: DocContext): NoteStore {
  let store = stores.get(ctx);
  if (!store) stores.set(ctx, (store = new NoteStore(ctx)));
  return store;
}

/** The notes of a document, if anything has asked for them yet. */
export function peekNotes(ctx: DocContext): NoteStore | null {
  return stores.get(ctx) ?? null;
}

/** Called whenever a note's content changed or a note was made: unsaved work. */
export function onNotesChanged(ctx: DocContext, listener: () => void): () => void {
  return notesOf(ctx).onChange(listener);
}

// ---- Styles for new notes ----------------------------------------------------------------------

const STYLE_NAMES: Record<NoteKind, { text: string; ref: string; textId: string; refId: string }> = {
  footnote: { text: 'footnote text', ref: 'footnote reference', textId: 'FootnoteText', refId: 'FootnoteReference' },
  endnote: { text: 'endnote text', ref: 'endnote reference', textId: 'EndnoteText', refId: 'EndnoteReference' },
};

/** The paragraph style of a note's text and the character style of its number, added when missing. */
export function noteStyles(ctx: DocContext, kind: NoteKind): { text: string; ref: string } {
  const names = STYLE_NAMES[kind];
  const styles = ctx.styles;
  const normal = styles.byName('Normal')?.id;
  const font = styles.byName('Default Paragraph Font', 'character')?.id;

  const text =
    styles.byName(names.text)?.id ??
    styles.addDefinition(
      names.textId,
      (id) =>
        `<w:style w:type="paragraph" w:styleId="${id}"><w:name w:val="${names.text}"/>${normal ? `<w:basedOn w:val="${normal}"/>` : ''}` +
        `<w:uiPriority w:val="99"/><w:semiHidden/><w:unhideWhenUsed/><w:pPr><w:spacing w:after="0" w:line="240" w:lineRule="auto"/></w:pPr>` +
        `<w:rPr><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr></w:style>`,
    );

  const ref =
    styles.byName(names.ref, 'character')?.id ??
    styles.addDefinition(
      names.refId,
      (id) =>
        `<w:style w:type="character" w:styleId="${id}"><w:name w:val="${names.ref}"/>${font ? `<w:basedOn w:val="${font}"/>` : ''}` +
        `<w:uiPriority w:val="99"/><w:semiHidden/><w:unhideWhenUsed/><w:rPr><w:vertAlign w:val="superscript"/></w:rPr></w:style>`,
    );

  return { text, ref };
}

/** A new note's content: one paragraph in the note text style, starting with the note's number mark. */
export function emptyNoteDoc(ctx: DocContext, kind: NoteKind, content: PMNode[] = []): PMNode {
  const { text, ref } = noteStyles(ctx, kind);
  const mark = N.opaque.create({ raw: `<w:${kind}Ref/>`, kind: 'run', look: 'hidden' }, null, [M.charStyle.create({ id: ref })]);

  return N.doc.create(null, [N.paragraph.create({ styleId: text }, [mark, schema.text(' '), ...content])]);
}

/** A reference to a note, as the text holds it. */
export function refNode(ctx: DocContext, kind: NoteKind, id: string): PMNode {
  const { ref } = noteStyles(ctx, kind);
  return N.opaque.create(
    { raw: `<w:${kind}Reference w:id="${id}"/>`, kind: 'run', look: kind, label: kind === 'footnote' ? 'Footnote' : 'Endnote' },
    null,
    [M.charStyle.create({ id: ref })],
  );
}

/** Where a note part is, for a document that has none yet. */
export function notePartPath(ctx: DocContext, kind: NoteKind): string {
  const dir = ctx.docPath.includes('/') ? ctx.docPath.slice(0, ctx.docPath.lastIndexOf('/') + 1) : '';
  return `${dir}${kind}s.xml`;
}
