// The document as GitHub-flavoured Markdown.
//
// Pictures, charts and shapes become files in a "<name>_files" folder beside the .md file (charts
// and shapes as SVG); equations become $…$ and $$…$$ LaTeX; footnotes and endnotes [^f1] and
// [^e1] with their text at the end; page breaks a --- rule. Tables become pipe tables: Markdown
// has no merged cells, so a merged cell's text goes in its first cell, and a comment says so.

import type { Node as PMNode } from 'prosemirror-model';
import { TableMap } from 'prosemirror-tables';
import { ommlToLinear } from '../math/linear';
import {
  FileNames, type Grouped, type ListItem, Lists, N, Notes, type SideFile, type Source, chartSvgOf, childrenOf, groupBlocks, headings, isDeleted, markOn,
  nestList, noteBlocks, pictureOf, shapeSvgOf, shapeText, splitAtBreaks, svgFile,
} from './common';

/** Characters that mean something to Markdown wherever they stand, `$` for math among them. */
const SPECIAL = /[\\`*_{}[\]<>|~$]/g;

/** Text as Markdown shows it literally. */
export function escapeMarkdown(text: string): string {
  return text
    .replace(SPECIAL, '\\$&')
    .replace(/&(?=#?[A-Za-z0-9]+;)/g, '&amp;')
    .replace(/\t/g, ' ');
}

/**
 * What would start a block if it began a line (a heading's #, a quote's >, a list's - + or
 * "1.", a setext underline's =), escaped; leading spaces, which could make a code block, dropped.
 */
function escapeLineStarts(text: string): string {
  return text
    .split('\n')
    .map((line) => line.replace(/^[ \t]+/, '').replace(/^([#>+=-])/, '\\$1').replace(/^(\d+)([.)])/, '$1\\$2'))
    .join('\n');
}

/** A link's address as Markdown takes it: in <…> when it has spaces or brackets. */
function destination(href: string): string {
  return /[\s()<>]/.test(href) ? `<${href.replace(/</g, '%3C').replace(/>/g, '%3E')}>` : href;
}

interface Inline {
  /** In a table cell, where a line break has to be <br>. */
  cell: boolean;
}

/** The markup a mark opens and closes with, outermost first. */
interface MdMark {
  key: string;
  open: string;
  close: string;
}

function mdMarks(node: PMNode): MdMark[] {
  const out: MdMark[] = [];
  const link = node.marks.find((m) => m.type.name === 'link' && m.attrs.href);

  if (link) out.push({ key: `link:${link.attrs.href}`, open: '[', close: `](${destination(link.attrs.href)})` });
  if (markOn(node.marks, 'bold')) out.push({ key: 'b', open: '**', close: '**' });
  if (markOn(node.marks, 'italic')) out.push({ key: 'i', open: '*', close: '*' });
  if (markOn(node.marks, 'strike')) out.push({ key: 's', open: '~~', close: '~~' });

  const vert = node.marks.find((m) => m.type.name === 'vert');
  if (vert) out.push(vert.attrs.value === 'subscript' ? { key: 'sub', open: '<sub>', close: '</sub>' } : { key: 'sup', open: '<sup>', close: '</sup>' });

  return out;
}

class MarkdownWriter {
  readonly files: SideFile[] = [];
  private readonly names = new FileNames();
  private readonly dir: string;
  private readonly level: (node: PMNode) => number;
  private readonly notes: Notes;
  /** Blocks to put after the paragraph being written: the text of its text boxes. */
  private pending: string[] = [];

  constructor(private readonly src: Source) {
    this.dir = `${src.name}_files`;
    this.level = headings(src.ctx);
    this.notes = new Notes(src.ctx, src.doc);
  }

  write(): string {
    const body = this.blocks(childrenOf(this.src.doc), new Lists(this.src.ctx), true);
    const notes = this.notes.ordered.map((note) => {
      const blocks = this.blocks(noteBlocks(note), new Lists(this.src.ctx), false);
      const text = blocks.join('\n\n').replace(/\n/g, '\n    ');
      return `[^${note.key}]: ${text}`;
    });

    return [...body, ...notes].join('\n\n').replace(/\n{3,}/g, '\n\n').trim() + '\n';
  }

  // ---- Blocks ----------------------------------------------------------------------------------

  /** Blocks as Markdown blocks, to be joined with blank lines. */
  private blocks(nodes: readonly PMNode[], lists: Lists, top: boolean): string[] {
    const out: string[] = [];

    for (const group of groupBlocks(nodes, lists) as Generator<Grouped>) {
      if (group.run) {
        out.push(this.list(group.run));
      } else if (group.node.type === N.paragraph) {
        out.push(...this.paragraph(group.node, top));
      } else if (group.node.type === N.table) {
        out.push(this.table(group.node));
      } else if (group.node.type === N.block_wrap) {
        out.push(...this.blocks(childrenOf(group.node), lists, top));
      }

      out.push(...this.pending);
      this.pending = [];
    }

    return out.filter((block) => block.trim() !== '');
  }

  private paragraph(node: PMNode, top: boolean): string[] {
    const out: string[] = [];
    const level = this.level(node);

    for (const part of splitAtBreaks(node)) {
      if (part.pageBefore) out.push('---');

      // An equation on a line of its own is a $$ block between the paragraph's text before and after it.
      let line: PMNode[] = [];
      const flush = () => {
        const text = escapeLineStarts(this.inline(line, { cell: false })).trim();
        if (text) out.push(level ? `${'#'.repeat(Math.min(6, level))} ${text.replace(/\\?\n/g, ' ')}` : text);
        line = [];
      };

      for (const child of part.nodes) {
        if (top && child.type === N.math && child.attrs.display && !isDeleted(child.marks)) {
          flush();
          out.push(`$$\n${ommlToLinear(child.attrs.raw).text}\n$$`);
        } else {
          line.push(child);
        }
      }
      flush();
    }

    return out;
  }

  private list(run: { node: PMNode; item: ListItem }[]): string {
    const lines: string[] = [];
    const indents: string[] = [];

    nestList(
      run,
      {
        // Two lists one after the other would read as one: a comment keeps them apart.
        openList: () => {
          if (!indents.length && lines.length) lines.push('', '<!-- -->', '');
        },
        closeList: () => {},
        openItem: () => {},
        closeItem: () => indents.pop(),
      },
      (node, item) => {
        const marker = item.bullet ? '-' : `${item.n}.`;
        const prefix = indents.join('');
        const text = escapeLineStarts(this.inline(childrenOf(node), { cell: false }).trim()) || '&nbsp;';
        const hang = ' '.repeat(marker.length + 1);
        const [first, ...rest] = text.split('\n');

        lines.push(`${prefix}${marker} ${first}`, ...rest.map((line) => `${prefix}${hang}${line}`));
        indents.push(hang);
      },
    );

    return lines.join('\n');
  }

  private table(table: PMNode): string {
    const map = TableMap.get(table);
    const grid: string[][] = [];
    let merged = false;

    for (let row = 0; row < map.height; row++) {
      const cells: string[] = [];

      for (let col = 0; col < map.width; col++) {
        const offset = map.map[row * map.width + col];
        const rect = map.findCell(offset);

        if (rect.left !== col || rect.top !== row) {
          merged = true;
          cells.push('');
          continue;
        }

        const cell = table.nodeAt(offset)!;
        cells.push(this.cellText(cell));
      }

      grid.push(cells);
    }

    if (!grid.length || !map.width) return '';

    const line = (cells: string[]) => `| ${cells.map((c) => c || ' ').join(' | ')} |`;
    const rows = [line(grid[0]), line(grid[0].map(() => '---')), ...grid.slice(1).map(line)];
    const note = merged ? '<!-- Merged cells were split: each merged cell\'s text is in its first cell. -->\n' : '';

    return note + rows.join('\n');
  }

  /** A cell's content on one line: its paragraphs separated by <br>, list items with their markers. */
  private cellText(cell: PMNode): string {
    const parts: string[] = [];
    const lists = new Lists(this.src.ctx);

    const walk = (nodes: readonly PMNode[]) => {
      for (const group of groupBlocks(nodes, lists) as Generator<Grouped>) {
        const items = group.run ?? [{ node: group.node, item: null as ListItem | null }];

        for (const { node, item } of items) {
          if (node.type === N.paragraph) {
            const text = this.inline(childrenOf(node), { cell: true }).trim();
            const marker = item ? `${item.bullet ? '•' : escapeMarkdown(item.text)} ` : '';
            if (text) parts.push(marker + text);
          } else if (node.type === N.table) {
            node.forEach((row) => row.forEach((c) => walk(childrenOf(c))));
          } else if (node.type === N.block_wrap) {
            walk(childrenOf(node));
          }
        }
      }
    };

    walk(childrenOf(cell));
    return parts.join('<br>').replace(/\n/g, ' ');
  }

  // ---- Inline content ---------------------------------------------------------------------------

  private inline(nodes: readonly PMNode[], options: Inline): string {
    let buf = '';
    let open: MdMark[] = [];

    /** Closes the marks from `keep` on, with the whitespace before the close moved after it. */
    const closeTo = (keep: number) => {
      if (open.length <= keep) return;

      const space = /\s*$/.exec(buf)![0];
      buf = buf.slice(0, buf.length - space.length);
      for (let i = open.length - 1; i >= keep; i--) buf += open[i].close;
      buf += space;
      open = open.slice(0, keep);
    };

    const write = (marks: MdMark[], text: string) => {
      let same = 0;
      while (same < open.length && same < marks.length && open[same].key === marks[same].key) same++;
      closeTo(same);

      if (marks.length > same) {
        // The whitespace before an opening goes outside it, or the emphasis would not count.
        const space = /^\s*/.exec(text)![0];
        buf += space;
        text = text.slice(space.length);
        for (let i = same; i < marks.length; i++) buf += marks[i].open;
        open = marks;
      }

      buf += text;
    };

    for (const node of nodes) {
      if (isDeleted(node.marks)) continue;

      if (node.isText) {
        const text = node.text ?? '';
        // Whitespace alone neither opens nor closes anything.
        if (!text.trim()) buf += text.replace(/\t/g, ' ');
        else write(mdMarks(node), escapeMarkdown(text));
        continue;
      }

      const atom = this.atom(node, options);
      if (atom) write(mdMarks(node), atom);
    }

    closeTo(0);
    return buf;
  }

  /** Something that is not text: a picture, a chart, an equation, a note's number. */
  private atom(node: PMNode, options: Inline): string {
    switch (node.type) {
      case N.hard_break:
        return options.cell ? '<br>' : '\\\n';
      case N.image: {
        const picture = pictureOf(node);
        const alt = escapeMarkdown(node.attrs.alt || 'Picture');
        return picture ? `![${alt}](${this.file('image', picture.ext, picture.bytes, picture.mime)})` : alt;
      }
      case N.chart: {
        const svg = chartSvgOf(node);
        return svg ? `![Chart](${this.file('chart', 'svg', svgFile(svg), 'image/svg+xml')})` : '';
      }
      case N.shape: {
        const svg = shapeSvgOf(node);
        const text = shapeText(node);
        if (text) this.pending.push(...this.blocks(childrenOf(text), new Lists(this.src.ctx), false));
        return svg ? `![Shape](${this.file('shape', 'svg', svgFile(svg), 'image/svg+xml')})` : '';
      }
      case N.math: {
        const tex = ommlToLinear(node.attrs.raw).text;
        return node.attrs.display ? `$$${tex}$$` : `$${tex}$`;
      }
      case N.opaque: {
        const note = this.notes.of(node);
        return note ? `[^${note.key}]` : '';
      }
      default:
        return '';
    }
  }

  /** Puts a file in the side folder and gives the address the Markdown links it by. */
  private file(stem: string, ext: string, bytes: Uint8Array, mime: string): string {
    const name = this.names.next(stem, ext);
    this.files.push({ name, bytes, mime });
    return `${encodeURIComponent(this.dir)}/${name}`;
  }
}

/** The document as Markdown, and the files its pictures are in, for "<name>_files". */
export function toMarkdown(src: Source): { text: string; files: SideFile[] } {
  const writer = new MarkdownWriter(src);
  const text = writer.write();
  return { text, files: writer.files };
}
