// Formatting many stretches of text at once: every match of a search, or only its variables.
// All of it is one step to undo.

import type { Attrs, MarkType, Node as PMNode } from 'prosemirror-model';
import type { Command } from 'prosemirror-state';
import type { DocContext } from '../docx/import';
import type { Span } from './find';
import { listKey } from './lists';
import { FORMATTING, schema } from './schema';

const M = schema.marks;

export type FormatAction =
  // `on` puts the formatting on, or takes it off, whatever the text has now; without it, it is toggled.
  | { kind: 'toggle'; mark: 'bold' | 'italic' | 'underline' | 'strike'; on?: boolean }
  | { kind: 'vert'; value: 'superscript' | 'subscript'; on?: boolean }
  | { kind: 'set'; mark: 'fontFamily' | 'fontSize' | 'color' | 'highlight'; attrs: Attrs | null }
  | { kind: 'clear' }
  | { kind: 'style'; ctx: DocContext; value: string };

const TOGGLE_ATTRS: Record<string, Attrs> = {
  bold: { on: true },
  italic: { on: true },
  strike: { on: true },
  underline: { kind: 'single' },
};

/** Whether every piece of text in a stretch has a mark switched on (with this value, if given). */
function allHave(doc: PMNode, span: Span, type: MarkType, value?: string): boolean {
  let all = true;

  doc.nodesBetween(span.from, span.to, (node) => {
    if (!all) return false;

    if (node.isText) {
      const mark = type.isInSet(node.marks);
      if (!mark || mark.attrs.on === false || (value !== undefined && mark.attrs.value !== value)) all = false;
    }

    return true;
  });

  return all;
}

/** The paragraphs the stretches are in, each once. */
function paragraphsOf(doc: PMNode, spans: readonly Span[]): { node: PMNode; pos: number }[] {
  const found = new Map<number, PMNode>();

  for (const span of spans) {
    doc.nodesBetween(span.from, span.to, (node, pos) => {
      if (node.type !== schema.nodes.paragraph) return true;
      found.set(pos, node);
      return false;
    });
  }

  return [...found].map(([pos, node]) => ({ node, pos }));
}

/**
 * Formats every stretch. A toggle (bold, italic, …) is taken off where all of them have it, and put
 * on all of them otherwise, as the toolbar does with a selection.
 */
export function formatSpans(spans: readonly Span[], action: FormatAction): Command {
  return (state, dispatch) => {
    const live = spans.filter((s) => s.to > s.from);
    if (!live.length) return false;
    if (!dispatch) return true;

    const tr = state.tr;
    const doc = state.doc;

    switch (action.kind) {
      case 'toggle': {
        const type = M[action.mark];
        const off = action.on === undefined ? live.every((s) => allHave(doc, s, type)) : !action.on;

        for (const s of live) {
          if (off) tr.removeMark(s.from, s.to, type);
          else tr.addMark(s.from, s.to, type.create(TOGGLE_ATTRS[action.mark]));
        }
        break;
      }

      case 'vert': {
        const off = action.on === undefined ? live.every((s) => allHave(doc, s, M.vert, action.value)) : !action.on;

        for (const s of live) {
          if (off) tr.removeMark(s.from, s.to, M.vert);
          else tr.addMark(s.from, s.to, M.vert.create({ value: action.value }));
        }
        break;
      }

      case 'set': {
        const type = M[action.mark];

        for (const s of live) {
          if (action.attrs) tr.addMark(s.from, s.to, type.create(action.attrs));
          else tr.removeMark(s.from, s.to, type);
        }
        break;
      }

      case 'clear':
        for (const s of live) {
          for (const name of FORMATTING) tr.removeMark(s.from, s.to, M[name]);
        }
        break;

      case 'style': {
        const { ctx, value } = action;
        const id = value.startsWith('builtin:') ? ctx.styles.ensureBuiltin(value.slice(8)) : value;
        if (!id && value) return false;

        // The default style is written as no style at all, as Word does.
        const styleId = !id || id === ctx.styles.defaultParagraph ? null : id;

        for (const { node, pos } of paragraphsOf(doc, live)) {
          if (node.attrs.styleId !== styleId) tr.setNodeMarkup(pos, null, { ...node.attrs, styleId });
        }

        tr.setMeta(listKey, true);
        break;
      }
    }

    if (!tr.docChanged) return false;

    dispatch(tr);
    return true;
  };
}
