// On start: the recovery copies an earlier run left behind, offered back one document at a time.

import { type OpenedFile, desktop } from '../desktop';
import { ask } from '../ui/dom';
import { type RecoveryOutcome, choicesFor, outcomeOf, recoveryMessage, recoveryPlan } from './recovery';

/**
 * Asks about each copy and does what was chosen. `open` puts a document up: `file` is the copy
 * (with its document's own path) or the original, `outcome` says whether it counts as modified.
 */
export async function offerRecoveries(open: (file: OpenedFile, key: string, outcome: RecoveryOutcome) => void): Promise<void> {
  if (!desktop.recoveryList || !desktop.recoveryRead || !desktop.recoveryRemove) return;

  const { offer, stale } = recoveryPlan(await desktop.recoveryList());

  for (const entry of stale) await desktop.recoveryRemove(entry.key);

  for (const entry of offer) {
    const { title, message } = recoveryMessage(entry);
    const outcome = outcomeOf(await ask(title, message, choicesFor(entry), 'later'));

    if (outcome.open === 'copy') {
      const file = await desktop.recoveryRead(entry.key);
      if (file) open({ ...file, name: entry.path ? file.name : entry.name }, entry.key, outcome);
    } else if (outcome.open === 'original') {
      const file = await desktop.recoveryOpenOriginal?.(entry.key);
      if (file) open(file, entry.key, outcome);
    }

    if (!outcome.keepCopy) await desktop.recoveryRemove(entry.key);
  }
}
