// A shape on the page: drawn, placed, moved, resized, and its text box edited.
//
// A shape in line with the text is a box in the line. A floating one is placed from its anchor
// (model.ts) roughly as Word places it: its offset is taken from the paragraph, the column, the
// margin or the page, whichever it names. With square wrapping it floats to the side it is nearer,
// so the text goes round it; with none it lies over or behind the text. Exact Word-like wrapping
// is not attempted.
//
// A text box's content is shown as the document's own text is. A click in it opens an editor of
// its own there (as notes and headers do); every change in it is written back to the node, so the
// main editor's undo takes it back.

import { DOMSerializer, type Node as PMNode } from 'prosemirror-model';
import { NodeSelection, TextSelection } from 'prosemirror-state';
import type { EditorView, NodeView } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { schema } from '../editor/schema';
import '../styles/shapes.css';
import { shapeSvg } from './geometry';
import { parseShapeSpec, textDoc, textJson } from './io';
import type { Anchor, ShapeSpec } from './model';

export type MakeShapeEditor = (options: { ctx: DocContext; doc: PMNode; mount: HTMLElement; onDocChange: (doc: PMNode) => void }) => EditorView;

const HANDLES = ['nw', 'n', 'ne', 'e', 'se', 's', 'sw', 'w'] as const;
type Handle = (typeof HANDLES)[number];

const zoomOf = (el: Element): number => {
  const page = el.closest<HTMLElement>('.page');
  return Number(page ? getComputedStyle(page).zoom : 1) || 1;
};

/** Where a floating shape's frames are, in unzoomed px from the anchor's own place. */
interface Frames {
  /** Left edge of the page, the margin (and column), and the anchor itself. */
  page: number;
  margin: number;
  marginRight: number;
  pageRight: number;
  /** Top of the page, the margin, the paragraph, and the line. */
  pageTop: number;
  marginTop: number;
  marginBottom: number;
  pageBottom: number;
  para: number;
  line: number;
}

export class ShapeView implements NodeView {
  readonly dom: HTMLElement;
  private readonly box: HTMLElement;
  private readonly art: HTMLElement;
  private readonly textArea: HTMLElement | null = null;
  private spec: ShapeSpec;
  private editor: EditorView | null = null;
  /** The text the open editor last wrote to the node, so its own change does not redraw it. */
  private written: string | null = null;
  private frames: Frames | null = null;
  private layoutQueued = false;

  constructor(
    private node: PMNode,
    private readonly view: EditorView,
    private readonly getPos: () => number | undefined,
    private readonly ctx: DocContext,
    private readonly makeEditor: MakeShapeEditor,
  ) {
    this.spec = parseShapeSpec(node.attrs.spec) ?? { geom: 'rect', adj: {}, w: 100, h: 100, fill: null, line: '#000000', lw: 1, dash: 'solid', head: 'none', tail: 'none', rot: 0, flipH: false, flipV: false, anchor: null, text: false, inset: [0, 0, 0, 0], valign: 't' };

    this.dom = document.createElement('span');
    this.dom.className = 'shape';
    this.dom.contentEditable = 'false';

    this.box = document.createElement('span');
    this.box.className = 'shape-box';
    this.art = document.createElement('span');
    this.art.className = 'shape-art';
    this.box.append(this.art);

    if (this.node.attrs.text !== null && this.spec.text) {
      this.textArea = document.createElement('div');
      this.textArea.className = 'shape-text';
      this.textArea.title = 'Click to edit the text';
      this.textArea.addEventListener('mousedown', this.openText);
      this.box.append(this.textArea);
    }

    for (const h of HANDLES) {
      const el = document.createElement('span');
      el.className = `shape-handle shape-handle-${h}`;
      el.dataset.handle = h;
      el.addEventListener('pointerdown', (e) => this.startResize(e, h));
      this.box.append(el);
    }

    this.box.addEventListener('pointerdown', this.startMove);
    this.dom.append(this.box);
    this.render(true);
  }

  // ---- Drawing ---------------------------------------------------------------------------

  private render(withText: boolean): void {
    const s = this.spec;
    const a = s.anchor;

    this.dom.dataset.place = !a ? 'inline' : a.wrap === 'none' ? (a.behind ? 'behind' : 'front') : a.wrap;
    this.box.style.width = `${s.w}px`;
    this.box.style.height = `${s.h}px`;
    this.box.style.transform = s.rot ? `rotate(${s.rot}deg)` : '';
    this.art.innerHTML = shapeSvg(s);

    if (s.geom === 'group') this.drawPartTexts();

    if (this.textArea) {
      const [l, t, r, b] = s.inset;
      Object.assign(this.textArea.style, { left: `${l}px`, top: `${t}px`, right: `${r}px`, bottom: `${b}px` });
      this.textArea.dataset.valign = s.valign;
      if (withText && !this.editor) this.drawText();
    }

    if (a) this.queueLayout();
    else this.dom.style.cssText = '';
  }

  private drawText(): void {
    const doc = textDoc(this.node.attrs.text);
    if (!this.textArea || !doc) return;

    const body = document.createElement('div');
    body.className = 'ProseMirror shape-text-body';
    body.append(DOMSerializer.fromSchema(schema).serializeFragment(doc.content));
    this.textArea.replaceChildren(body);
  }

  /** A group's members' texts, as plain lines over each member. */
  private drawPartTexts(): void {
    for (const el of this.box.querySelectorAll('.shape-part-text')) el.remove();

    for (const part of this.spec.parts ?? []) {
      if (!part.lines.some((l) => l.trim())) continue;

      const el = document.createElement('span');
      el.className = 'shape-part-text';
      el.dataset.valign = part.valign;
      Object.assign(el.style, { left: `${part.x + part.inset[0]}px`, top: `${part.y + part.inset[1]}px`, width: `${Math.max(1, part.w - part.inset[0] - part.inset[2])}px`, height: `${Math.max(1, part.h - part.inset[1] - part.inset[3])}px` });
      for (const line of part.lines) {
        const p = document.createElement('span');
        p.textContent = line || ' ';
        el.append(p);
      }
      this.art.append(el);
    }
  }

  // ---- Placing a floating shape -----------------------------------------------------------

  private queueLayout(): void {
    if (this.layoutQueued) return;
    this.layoutQueued = true;
    requestAnimationFrame(() => {
      this.layoutQueued = false;
      this.layout();
    });
  }

  /** The frames a floating shape is placed in, measured from where its anchor is on the page. */
  private measure(): Frames | null {
    const page = this.dom.closest<HTMLElement>('.page');
    if (!page || !this.dom.isConnected) return null;

    const zoom = zoomOf(this.dom);
    const here = this.dom.getBoundingClientRect();
    const pageRect = page.getBoundingClientRect();
    const para = this.dom.closest('p, h1, h2, h3, h4, h5, h6, li, div.block-wrap') ?? this.dom.parentElement;
    const paraTop = para?.getBoundingClientRect().top ?? here.top;
    const g = this.ctx.page;

    // The page this anchor is on starts below the last page gap above it (src/editor/pages.ts).
    let contentTop = pageRect.top + g.top * zoom;
    for (const gap of this.view.dom.querySelectorAll('.page-gap')) {
      const r = gap.getBoundingClientRect();
      if (r.height > 0 && r.bottom <= here.top + 1 && r.bottom > contentTop) contentTop = r.bottom;
    }

    const x = (v: number) => (v - here.left) / zoom;
    const y = (v: number) => (v - here.top) / zoom;
    const pageTop = y(contentTop) - g.top;

    return {
      page: x(pageRect.left),
      margin: x(pageRect.left) + g.left,
      marginRight: x(pageRect.left) + g.width - g.right,
      pageRight: x(pageRect.left) + g.width,
      pageTop,
      marginTop: pageTop + g.top,
      marginBottom: pageTop + g.height - g.bottom,
      pageBottom: pageTop + g.height,
      para: y(paraTop),
      line: 0,
    };
  }

  /** Where the shape's box goes, in px from the anchor's place, and its offset as it would be written. */
  private place(a: Anchor, f: Frames): { left: number; top: number } {
    const s = this.spec;
    const [h0, h1] =
      a.relH === 'page' ? [f.page, f.pageRight]
      : a.relH === 'character' ? [0, 0]
      : a.relH === 'leftMargin' ? [f.page, f.margin]
      : a.relH === 'rightMargin' ? [f.marginRight, f.pageRight]
      : [f.margin, f.marginRight];
    const [v0, v1] =
      a.relV === 'page' ? [f.pageTop, f.pageBottom]
      : a.relV === 'margin' || a.relV === 'topMargin' ? [f.marginTop, f.marginBottom]
      : a.relV === 'line' ? [f.line, f.line]
      : [f.para, f.para];

    const along = (align: string | null, offset: number, lo: number, hi: number, size: number) =>
      align === 'center' ? (lo + hi - size) / 2
      : align === 'right' || align === 'bottom' || align === 'outside' ? hi - size
      : align === 'left' || align === 'top' || align === 'inside' ? lo
      : lo + offset;

    return { left: along(a.alignH, a.x, h0, h1, s.w), top: along(a.alignV, a.y, v0, v1, s.h) };
  }

  private layout(): void {
    const a = this.spec.anchor;
    if (!a) return;

    const f = this.measure();
    if (!f) return;
    this.frames = f;

    const { left, top } = this.place(a, f);
    const s = this.spec;

    if (a.wrap === 'none') {
      this.dom.style.cssText = '';
      this.box.style.left = `${left}px`;
      this.box.style.top = `${top}px`;
      return;
    }

    // Square (and top-and-bottom) wrapping: the box floats to the nearer side of the column, held
    // down from the line by its offset, so the text runs round it.
    this.box.style.left = '';
    this.box.style.top = '';
    const right = left + s.w / 2 > (f.margin + f.marginRight) / 2 && a.wrap !== 'topBottom';
    const down = Math.max(0, top);
    this.dom.style.cssText =
      `float:${right ? 'right' : 'left'};width:${a.wrap === 'topBottom' ? '100%' : `${s.w}px`};height:${s.h + down}px;` +
      `padding-top:${down}px;` +
      (right ? `margin-right:${Math.max(0, f.marginRight - (left + s.w))}px;` : `margin-left:${a.wrap === 'topBottom' ? 0 : Math.max(0, left - f.margin)}px;`) +
      (a.wrap === 'topBottom' ? `padding-left:${Math.max(0, left - f.margin)}px;` : '');
  }

  // ---- The text box ------------------------------------------------------------------------

  private readonly openText = (event: MouseEvent): void => {
    if (this.editor || !this.textArea || !this.view.editable) return;

    const doc = textDoc(this.node.attrs.text);
    if (!doc) return;

    event.stopPropagation();
    const mount = document.createElement('div');
    mount.className = 'shape-text-mount';
    this.textArea.replaceChildren(mount);
    this.dom.classList.add('editing');

    const editor = this.makeEditor({
      ctx: this.ctx,
      doc,
      mount,
      onDocChange: (next) => {
        const pos = this.getPos();
        if (pos === undefined) return;
        this.written = textJson(next);
        this.view.dispatch(this.view.state.tr.setNodeMarkup(pos, null, { ...this.node.attrs, text: this.written, edited: true }).setMeta('shapeText', true));
      },
    });
    this.editor = editor;
    editor.dom.classList.add('shape-text-body');

    const leave = (e: Event) => {
      const inside = this.textArea?.contains(e.target as Node);
      if (e instanceof KeyboardEvent ? e.key === 'Escape' && inside : !inside) {
        document.removeEventListener('mousedown', leave, true);
        document.removeEventListener('keydown', leave, true);
        this.closeText();
      }
    };
    document.addEventListener('mousedown', leave, true);
    document.addEventListener('keydown', leave, true);

    // The caret goes where the click was; the browser is kept from putting focus elsewhere.
    event.preventDefault();
    editor.focus();
    const at = editor.posAtCoords({ left: event.clientX, top: event.clientY });
    const $pos = editor.state.doc.resolve(at ? at.pos : editor.state.doc.content.size);
    editor.dispatch(editor.state.tr.setSelection(TextSelection.near($pos, at ? 1 : -1)));
  };

  private closeText(): void {
    if (!this.editor) return;

    this.editor.destroy();
    this.editor = null;
    this.written = null;
    this.dom.classList.remove('editing');
    this.drawText();
  }

  // ---- Moving and resizing ----------------------------------------------------------------

  private commit(spec: ShapeSpec): void {
    const pos = this.getPos();
    if (pos === undefined) return;
    this.view.dispatch(this.view.state.tr.setNodeMarkup(pos, null, { ...this.node.attrs, spec: JSON.stringify(spec) }));
  }

  private select(): void {
    const pos = this.getPos();
    if (pos !== undefined) this.view.dispatch(this.view.state.tr.setSelection(NodeSelection.create(this.view.state.doc, pos)));
  }

  /** The anchor with its offsets made plain numbers, from where the shape is drawn now. */
  private offsets(a: Anchor): Anchor {
    const f = this.frames ?? this.measure();
    if (!f || (!a.alignH && !a.alignV)) return { ...a };

    const { left, top } = this.place(a, f);
    const { left: l0, top: t0 } = this.place({ ...a, alignH: null, alignV: null, x: 0, y: 0 }, f);
    return { ...a, x: a.alignH ? left - l0 : a.x, y: a.alignV ? top - t0 : a.y, alignH: null, alignV: null };
  }

  private readonly startMove = (event: PointerEvent): void => {
    const target = event.target as HTMLElement;
    if (event.button !== 0 || target.closest('.shape-handle') || (this.textArea?.contains(target) && this.spec.text)) return;

    const a = this.spec.anchor;
    if (!a || !this.view.editable) {
      // In line with the text: selected as a picture is, and dragged by the editor itself.
      return;
    }

    event.preventDefault();
    const zoom = zoomOf(this.dom);
    const sx = event.clientX;
    const sy = event.clientY;
    const start = this.offsets(a);
    let moved = false;
    let dx = 0;
    let dy = 0;

    const move = (e: PointerEvent) => {
      dx = (e.clientX - sx) / zoom;
      dy = (e.clientY - sy) / zoom;
      if (!moved && Math.hypot(dx, dy) < 3) return;
      moved = true;
      this.box.style.translate = `${dx}px ${dy}px`;
    };

    const up = () => {
      window.removeEventListener('pointermove', move);
      this.box.style.translate = '';
      if (moved) this.commit({ ...this.spec, anchor: { ...start, x: Math.round(start.x + dx), y: Math.round(start.y + dy) } });
      this.select();
    };

    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up, { once: true });
  };

  private startResize(event: PointerEvent, handle: Handle): void {
    if (event.button !== 0 || !this.view.editable) return;
    event.preventDefault();
    event.stopPropagation();

    const zoom = zoomOf(this.dom);
    const { w, h } = this.spec;
    const sx = event.clientX;
    const sy = event.clientY;
    const keepRatio = event.shiftKey || (!this.spec.anchor && handle.length === 2);
    let next = { w, h, dx: 0, dy: 0 };

    const move = (e: PointerEvent) => {
      let mx = (e.clientX - sx) / zoom;
      let my = (e.clientY - sy) / zoom;
      if (!handle.includes('e') && !handle.includes('w')) mx = 0;
      if (!handle.includes('n') && !handle.includes('s')) my = 0;

      let nw = Math.max(4, handle.includes('w') ? w - mx : w + mx);
      let nh = Math.max(4, handle.includes('n') ? h - my : h + my);
      if (keepRatio && handle.length === 2) nh = Math.max(4, (nw * h) / w);
      nw = Math.round(nw);
      nh = Math.round(nh);
      next = { w: nw, h: nh, dx: handle.includes('w') ? w - nw : 0, dy: handle.includes('n') ? h - nh : 0 };

      this.box.style.width = `${nw}px`;
      this.box.style.height = `${nh}px`;
      this.box.style.translate = `${next.dx}px ${next.dy}px`;
    };

    const up = () => {
      window.removeEventListener('pointermove', move);
      this.box.style.translate = '';
      if (next.w === w && next.h === h) return this.render(false);

      const a = this.spec.anchor;
      const anchor = a && (next.dx || next.dy) ? this.offsets(a) : a;
      if (anchor && a && (next.dx || next.dy)) {
        anchor.x = Math.round(anchor.x + next.dx);
        anchor.y = Math.round(anchor.y + next.dy);
      }
      this.commit({ ...this.spec, w: next.w, h: next.h, anchor });
    };

    window.addEventListener('pointermove', move);
    window.addEventListener('pointerup', up, { once: true });
  }

  // ---- NodeView ---------------------------------------------------------------------------

  update(node: PMNode): boolean {
    if (node.type !== this.node.type || (node.attrs.text === null) !== (this.node.attrs.text === null)) return false;

    const old = this.node;
    this.node = node;

    if (node.attrs.spec !== old.attrs.spec) this.spec = parseShapeSpec(node.attrs.spec) ?? this.spec;

    const ownText = this.editor && node.attrs.text === this.written;
    if (this.editor && !ownText) this.closeText();

    this.render(!ownText && node.attrs.text !== old.attrs.text);
    if (node.attrs.spec === old.attrs.spec && this.spec.anchor) this.queueLayout();
    return true;
  }

  selectNode(): void {
    this.dom.classList.add('selected');
  }

  deselectNode(): void {
    this.dom.classList.remove('selected');
  }

  stopEvent(event: Event): boolean {
    const target = event.target as HTMLElement | null;
    if (!target) return false;
    if (target.closest('.shape-handle') || (this.editor && this.textArea?.contains(target))) return true;
    if (this.textArea?.contains(target) && event.type === 'mousedown') return true;
    // A floating shape is moved here, not dragged into the text.
    return !!this.spec.anchor && (event.type === 'mousedown' || event.type === 'dragstart' || event.type.startsWith('pointer'));
  }

  ignoreMutation(): boolean {
    return true;
  }

  destroy(): void {
    this.editor?.destroy();
  }
}

