// Review in the editor: commented text highlighted, the comment the cursor is in marked, and the
// recording of tracked changes.

import type { Node as PMNode } from 'prosemirror-model';
import { type EditorState, Plugin, PluginKey } from 'prosemirror-state';
import { Decoration, DecorationSet } from 'prosemirror-view';
import type { DocContext } from '../docx/import';
import { type Anchor, type CommentStore, anchorsIn, commentsOf, rangeOf } from './comments';
import { trackPlugin } from './track';

export interface ReviewState {
  anchors: Map<string, Anchor>;
  /** The comment picked in the pane, or the one the cursor is in. */
  active: string | null;
  decorations: DecorationSet;
}

export const reviewKey = new PluginKey<ReviewState>('review');

function decorate(ctx: DocContext, doc: PMNode, anchors: Map<string, Anchor>, active: string | null): DecorationSet {
  const store = commentsOf(ctx);
  const decos: Decoration[] = [];

  for (const comment of store.comments) {
    const anchor = anchors.get(comment.id);
    if (!anchor || comment.parentId) continue;

    const { from, to } = rangeOf(anchor);
    if (to <= from) continue;

    const cls = `comment-range${comment.done ? ' resolved' : ''}${comment.id === active ? ' active' : ''}`;
    decos.push(Decoration.inline(from, to, { class: cls, 'data-comment': comment.id }));
  }

  return DecorationSet.create(doc, decos);
}

/** The innermost comment around a position. */
export function commentAt(state: EditorState, store: CommentStore, pos: number): string | null {
  const anchors = reviewKey.getState(state)?.anchors;
  if (!anchors) return null;

  let best: string | null = null;
  let size = Infinity;

  for (const [id, anchor] of anchors) {
    const comment = store.byId(id);
    if (!comment || comment.parentId) continue;
    const { from, to } = rangeOf(anchor);
    if (from <= pos && pos <= to && to - from < size) {
      best = id;
      size = to - from;
    }
  }

  return best;
}

function commentPlugin(ctx: DocContext): Plugin<ReviewState> {
  return new Plugin<ReviewState>({
    key: reviewKey,
    state: {
      init: (_config, state) => {
        const anchors = anchorsIn(state.doc);
        return { anchors, active: null, decorations: decorate(ctx, state.doc, anchors, null) };
      },
      apply(tr, value) {
        const meta = tr.getMeta(reviewKey) as { active?: string | null } | undefined;
        // A comment picked in the pane stays picked until the cursor moves on its own.
        const active = meta && 'active' in meta ? (meta.active ?? null) : tr.selectionSet ? null : value.active;
        const commentsChanged = tr.getMeta('review') === 'comments';

        if (!tr.docChanged && active === value.active && !commentsChanged) return value;

        const anchors = tr.docChanged ? anchorsIn(tr.doc) : value.anchors;
        return { anchors, active, decorations: decorate(ctx, tr.doc, anchors, active) };
      },
    },
    props: {
      decorations: (state) => reviewKey.getState(state)?.decorations ?? null,
    },
  });
}

/** The plugins review adds to an editor. */
export function reviewPlugins(ctx: DocContext): Plugin[] {
  return [commentPlugin(ctx), trackPlugin(ctx)];
}
